#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

#define MLX91219_SENSITIVITY 0.040f
#define MLX91219_SUPPLY_V 5.0f
#define MLX91219_ZERO_CURRENT_OFFSET 2.5f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115_conversion(int handle) {
    char reg = ADS1115_REG_CONVERSION;
    char buf[2];
    if (i2cWriteI2CBlockData(handle, reg, buf, 0) < 0) {
        return -1;
    }
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

static int write_ads1115_config(int handle, uint16_t config) {
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteI2CBlockData(handle, buf[0], buf + 1, 2) < 0) {
        return -1;
    }
    return 0;
}

static int read_current(int handle, float *current) {
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_GND |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    if (write_ads1115_config(handle, config) < 0) {
        return -1;
    }

    gpioDelay(10000);

    int16_t raw = read_ads1115_conversion(handle);
    if (raw < 0) {
        return -1;
    }

    float voltage = (raw * 4.096f) / 32768.0f;
    *current = (voltage - MLX91219_ZERO_CURRENT_OFFSET) / MLX91219_SENSITIVITY;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        float current;
        if (read_current(i2c_handle, &current) == 0) {
            printf("Current: %.4f A\n", current);
        } else {
            fprintf(stderr, "Error reading current from ADS1115\n");
        }
        gpioDelay(500000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

