#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x8000  /* Operational status: single-shot, start */
#define ADS1115_CONFIG_MUX_AIN0 0x4000  /* AIN0 single-ended */
#define ADS1115_CONFIG_PGA_4_096V 0x0200  /* Gain ±4.096V */
#define ADS1115_CONFIG_MODE_SINGLE 0x0100  /* Single-shot */
#define ADS1115_CONFIG_DR_128SPS 0x0080  /* 128 SPS */
#define ADS1115_CONFIG_CQUE_NONE 0x0003  /* Disable comparator */
#define ADC_MAX_COUNT 32767  /* 16-bit signed, single-ended 0-3.3V maps to 0-32767 */
#define ADC_VREF 3.3
#define TEMP_MIN 20.0
#define TEMP_MAX 80.0
#define TEMP_THRESHOLD 60.0
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_US 100000
#define BUZZER_DURATION_US 2000000
#define LOG_FILE "fire_log.txt"

static volatile sig_atomic_t running = 1;
static volatile uint32_t last_flame_tick = 0;
static FILE *log_file = NULL;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed for bus %d addr 0x%02X (handle=%d).\n",
                I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_log(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        return -1;
    }
    return 0;
}

static int read_ads1115(int16_t *raw_out) {
    uint16_t config = ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
    char cfg_buf[3];
    cfg_buf[0] = ADS1115_REG_CONFIG;
    cfg_buf[1] = (config >> 8) & 0xFF;
    cfg_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, cfg_buf, 3) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed (config).\n");
        return -1;
    }

    /* Wait for conversion: 128 SPS -> ~8 ms; give 10 ms margin */
    gpioDelay(10000);

    char reg_buf[1] = { ADS1115_REG_CONVERSION };
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed (select reg).\n");
        return -1;
    }

    char data_buf[2];
    if (i2cReadDevice(i2c_handle, data_buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice failed (conversion).\n");
        return -1;
    }

    *raw_out = (int16_t)((data_buf[0] << 8) | (data_buf[1] & 0xFF));
    return 0;
}

static float adc_to_temperature(int16_t raw) {
    if (raw < 0) raw = 0;
    if (raw > ADC_MAX_COUNT) raw = ADC_MAX_COUNT;
    float voltage = (float)raw * ADC_VREF / (float)ADC_MAX_COUNT;
    float temp = TEMP_MIN + (voltage - 0.0) * (TEMP_MAX - TEMP_MIN) / (ADC_VREF - 0.0);
    return temp;
}

static void flame_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    uint32_t now = tick;
    uint32_t elapsed = now - last_flame_tick;
    if (elapsed >= DEBOUNCE_MS * 1000) {
        last_flame_tick = now;
        printf("Flame detected!\n");
    }
}

static void log_event(const char *msg) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(log_file);
}

static void activate_buzzer(void) {
    gpioWrite(BUZZER_GPIO, 1);
    gpioDelay(BUZZER_DURATION_US);
    gpioWrite(BUZZER_GPIO, 0);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }
    if (init_log() != 0) {
        cleanup();
        return 1;
    }

    if (gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, flame_isr, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed for GPIO %d.\n", FLAME_SENSOR_GPIO);
        cleanup();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw;
        if (read_ads1115(&raw) == 0) {
            float temp = adc_to_temperature(raw);
            int flame = (gpioRead(FLAME_SENSOR_GPIO) == 0);  /* LOW = flame */

            if (flame && temp > TEMP_THRESHOLD) {
                log_event("Flame and high temperature detected!");
                activate_buzzer();
            } else if (flame) {
                log_event("Flame detected!");
            } else if (temp > TEMP_THRESHOLD) {
                char msg[64];
                snprintf(msg, sizeof(msg), "High temperature: %.2f C", temp);
                log_event(msg);
            }
        } else {
            log_event("Error reading temperature sensor.");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

