/*
 * MLX91219 Current Sensor Monitor with MCP3008 ADC and Fan Control
 * Board: Raspberry Pi 5
 * SPI:  spidev0.0 (GPIO8 = CE0, GPIO10 = MISO, GPIO11 = MOSI, GPIO12 = SCLK)
 * ADC:  MCP3008 single-ended CH0, VREF = 3.3 V
 * Fan:  GPIO18 (active-high)
 *
 * Build: gcc -O2 -Wall -Wextra -o current_monitor current_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE          0

#define FAN_GPIO_LINE     18
#define GPIO_CHIP_NAME    "gpiochip4"   /* Pi 5 default; falls back to chip 0 */

#define DEFAULT_SENSITIVITY 100.0f     /* mV/A */
#define DEFAULT_THRESHOLD   5.0f        /* Amperes */
#define DEFAULT_LOG_FILE    "current_log.txt"
#define DEFAULT_SAMPLE_US   1000000     /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd   = -1;
static struct gpiod_chip  *g_chip   = NULL;
static struct gpiod_line  *g_fan_line = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_fan_line) {
        gpiod_line_set_value(g_fan_line, 0);
        gpiod_line_release(g_fan_line);
        g_fan_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        /* Fallback: try opening by number (chip 0 on Pi 5) */
        g_chip = gpiod_chip_open_by_number(0);
    }
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        return -1;
    }

    g_fan_line = gpiod_chip_get_line(g_chip, FAN_GPIO_LINE);
    if (!g_fan_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                FAN_GPIO_LINE, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(g_fan_line, "current_monitor", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = 0x80 | (channel << 4)  (single-ended + channel select)
     *   tx[2] = 0x00  (don't-care, clocks out low 2 bits)
     * Result: 10-bit value = ((rx[1] & 0x03) << 8) | rx[2]
     */
    uint8_t tx[3] = { 0x01, (uint8_t)(0x80 | (channel << 4)), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
static float adc_to_current(int adc_value, float sensitivity_mv_per_a)
{
    float voltage = (float)adc_value * 3.3f / 1024.0f;
    return voltage / (sensitivity_mv_per_a / 1000.0f);
}

/* ------------------------------------------------------------------ */
static void log_reading(float current, float threshold, int fan_on)
{
    FILE *fp = fopen(DEFAULT_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", DEFAULT_LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Current: %.2f A, Threshold: %.2f A, Fan: %s\n",
                ts, current, threshold, fan_on ? "ON" : "OFF");
    } else {
        fprintf(fp, "Current: %.2f A, Threshold: %.2f A, Fan: %s\n",
                current, threshold, fan_on ? "ON" : "OFF");
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    float sensitivity = DEFAULT_SENSITIVITY;
    float threshold   = DEFAULT_THRESHOLD;
    int   sample_us   = DEFAULT_SAMPLE_US;

    int opt;
    while ((opt = getopt(argc, argv, "s:t:")) != -1) {
        switch (opt) {
        case 's':
            sensitivity = (float)atof(optarg);
            if (sensitivity <= 0.0f) {
                fprintf(stderr, "Sensitivity must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        case 't':
            threshold = (float)atof(optarg);
            if (threshold <= 0.0f) {
                fprintf(stderr, "Threshold must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s [-s sensitivity_mV/A] [-t thresholdA]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Sensitivity: %.2f mV/A, Threshold: %.2f A\n",
           sensitivity, threshold);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; retrying in 1 s\n");
            usleep(sample_us);
            continue;
        }

        /* Sensor-absent / bus error detection: all-zero or all-ones */
        if (adc == 0 || adc == 1023) {
            fprintf(stderr, "Warning: ADC at rail (%d) - sensor may be absent or bus error\n", adc);
        }

        float current = adc_to_current(adc, sensitivity);
        int fan_on = (current > threshold) ? 1 : 0;

        if (gpiod_line_set_value(g_fan_line, fan_on) < 0) {
            fprintf(stderr, "gpiod_line_set_value: %s\n", strerror(errno));
        }

        log_reading(current, threshold, fan_on);
