#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5

/* Calibration parameters for the MICS-4514 CO element.
 * These are example values; replace with actual calibration data from the sensor datasheet. */
#define CO_A 0.001
#define CO_B 0.5
#define CO_C 100.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read a 16-bit big-endian value from the ADC register at reg_addr. */
static int read_adc_register(int handle, uint8_t reg_addr, uint16_t *value) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, reg_addr, buf, 2);
    if (result != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* Convert raw ADC value to CO concentration in PPM using a logarithmic curve. */
static float convert_to_ppm(uint16_t raw_value) {
    if (raw_value == 0) {
        return 0.0f;
    }
    float resistance = (float)raw_value;
    float ppm = CO_A * powf(resistance, CO_B) + CO_C;
    return ppm;
}

/* Log the timestamped CO concentration to the log file. */
static int log_co_concentration(float ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f PPM\n", timestamp, ppm) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("CO sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t raw_value = 0;
        if (read_adc_register(i2c_handle, 0x00, &raw_value) != 0) {
            fprintf(stderr, "Error reading ADC register (sensor absent or bus error)\n");
        } else {
            float ppm = convert_to_ppm(raw_value);
            if (log_co_concentration(ppm) != 0) {
                fprintf(stderr, "Error logging CO concentration\n");
            }
        }

        /* Sleep in 1-second increments to allow prompt signal handling. */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

