        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_DOWN);

