#define I2C_BUS 1
#define I2C_ADDR 0x28
#define CO_THRESHOLD 25.0
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define READ_INTERVAL 5

static int i2c_handle = -1;
static FILE *log_file = NULL;
static FILE *alert_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float co_ppm;
    float no2_ppm;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    char buffer[4];
    int result = i2cReadDevice(i2c_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    unsigned int ox_raw = ((unsigned int)buffer[0] << 8) | (unsigned char)buffer[1];
    unsigned int red_raw = ((unsigned int)buffer[2] << 8) | (unsigned char)buffer[3];

    data->co_ppm = (float)ox_raw / 100.0;
    data->no2_ppm = (float)red_raw / 100.0;

    return 0;
}

static float calculate_co_ppm(const sensor_data_t *data) {
    return data->co_ppm;
}

static void log_co_level(float co_ppm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, CO: %.2f PPM\n", timestamp, co_ppm);
    fflush(log_file);
}

static void check_co_threshold(float co_ppm) {
    if (co_ppm > CO_THRESHOLD) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(alert_file, "%s, CO: %.2f PPM - Alert: Threshold exceeded!\n", timestamp, co_ppm);
        fflush(alert_file);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (alert_file != NULL) {
        fclose(alert_file);
        alert_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    if (initialize_i2c() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    alert_file = fopen(ALERT_FILE, "a");
    if (alert_file == NULL) {
        perror("Failed to open alert log file");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            float co_ppm = calculate_co_ppm(&sensor_data);
            log_co_level(co_ppm);
            check_co_threshold(co_ppm);
        } else {
            fprintf(stderr, "Sensor read failed, retrying in %d seconds...\n", READ_INTERVAL);
        }

        sleep(READ_INTERVAL);
    }

    cleanup();
    return 0;
}

