#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49
#define ADC_REG 0x00
#define SAMPLE_INTERVAL_US 100000
#define SENSITIVITY -38.0
#define REFERENCE_PRESSURE 20.0e-6
#define ERROR_VALUE -999.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mic_raw(int handle, int *raw_out) {
    char reg = (char)ADC_REG;
    char buf[2];
    int rc = i2cWriteDevice(handle, &reg, 1);
    if (rc < 0) return -1;
    rc = i2cReadDevice(handle, buf, 2);
    if (rc < 0) return -1;
    *raw_out = (buf[0] << 8) | buf[1];
    return 0;
}

static double calculate_spl(int raw) {
    double voltage = (double)raw * 0.0001;
    double pressure = voltage / (10.0 * pow(10.0, SENSITIVITY / 20.0));
    return 20.0 * log10(pressure / REFERENCE_PRESSURE);
}

static void log_data(double spl1, double spl2) {
    FILE *fp = fopen("audio_log.txt", "a");
    if (!fp) {
        perror("fopen audio_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f, %.2f\n", ts, spl1, spl2);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int h1 = i2cOpen(I2C_BUS, MIC1_ADDR, 0);
    if (h1 < 0) {
        fprintf(stderr, "Failed to open I2C for mic1 (addr 0x%02X): %d\n", MIC1_ADDR, h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int h2 = i2cOpen(I2C_BUS, MIC2_ADDR, 0);
    if (h2 < 0) {
        fprintf(stderr, "Failed to open I2C for mic2 (addr 0x%02X): %d\n", MIC2_ADDR, h2);
        i2cClose(h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Acoustic leak detection started. Press Ctrl+C to stop.\n");

    while (running) {
        int raw1 = 0, raw2 = 0;
        int ok1 = read_mic_raw(h1, &raw1);
        int ok2 = read_mic_raw(h2, &raw2);

        double spl1 = ERROR_VALUE, spl2 = ERROR_VALUE;
        if (ok1 == 0) spl1 = calculate_spl(raw1);
        if (ok2 == 0) spl2 = calculate_spl(raw2);

        log_data(spl1, spl2);

        if (ok1 != 0) fprintf(stderr, "Warning: mic1 read failed\n");
        if (ok2 != 0) fprintf(stderr, "Warning: mic2 read failed\n");

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(h1);
    i2cClose(h2);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

