#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL_1 0
#define SPI_CHANNEL_2 1
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 27
#define THRESHOLD 0.7
#define NUM_SAMPLES 100
#define SAMPLE_INTERVAL_US 1000 // 1 ms
#define LED_ON_DURATION_US 500000 // 500 ms
#define ADC_VREF 3.3

// Global variables
int spi_handle_1 = -1;
int spi_handle_2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_spi();
int read_adc(int spi_handle, int channel);
double calculate_rms(int *samples, int num_samples);
void control_led(int state);
void log_data(double mic1_rms, double mic2_rms);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Initialize SPI interface
int initialize_spi() {
    int handle = spiOpen(SPI_CHANNEL_1, SPI_SPEED, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel 1: %d\n", handle);
        return -1;
    }
    spi_handle_1 = handle;

    handle = spiOpen(SPI_CHANNEL_2, SPI_SPEED, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel 2: %d\n", handle);
        spiClose(spi_handle_1);
        spi_handle_1 = -1;
        return -1;
    }
    spi_handle_2 = handle;

    return 0;
}

// Read ADC value from MCP3008
int read_adc(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command: start bit (1), single-ended mode (1), channel select (3 bits)
    unsigned char tx_buf[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx_buf[3] = {0, 0, 0};

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Calculate RMS value of a set of samples
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double normalized = (double)samples[i] / ADC_VREF;
        sum_of_squares += normalized * normalized;
    }
    return sqrt(sum_of_squares / num_samples);
}

// Control the LED
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Log data to CSV file
void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file);
}

// Cleanup resources
void cleanup() {
    if (spi_handle_1 >= 0) {
        spiClose(spi_handle_1);
        spi_handle_1 = -1;
    }
    if (spi_handle_2 >= 0) {
        spiClose(spi_handle_2);
        spi_handle_2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int mic1_samples[NUM_SAMPLES];
        int mic2_samples[NUM_SAMPLES];

        // Sample microphone 1
        for (int i = 0; i < NUM_SAMPLES; i++) {
            mic1_samples[i] = read_adc(spi_handle_1, 0);
            if (mic1_samples[i] < 0) {
                fprintf(stderr, "Error reading ADC channel 1\n");
                program_running = 0;
                break;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        // Sample microphone 2
        for (int i = 0; i < NUM_SAMPLES; i++) {
            mic2_samples[i] = read_adc(spi_handle_2, 0);
            if (mic2_samples[i] < 0) {
                fprintf(stderr, "Error reading ADC channel 2\n");
                program_running = 0;
                break;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        if (!program_running) break;

        // Calculate RMS values
        double mic1_rms = calculate_rms(mic1_samples, NUM_SAMPLES);
        double mic2_rms = calculate_rms(mic2_samples, NUM_SAMPLES);

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Check threshold and control LED
        if (mic1_rms > THRESHOLD || mic2_rms > THRESHOLD) {
            control_led(1);
            gpioDelay(LED_ON_DURATION_US);
            control_led(0);
        }
    }

    // Cleanup
    cleanup();
    return 0;
}

