#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define LED_GPIO 17
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define OVERCURRENT_THRESHOLD 50.0f
#define VREF 5.0f
#define MLX91204_VMIN 0.5f
#define MLX91204_VMAX 4.5f
#define MLX91204_IMAX 100.0f

// ADS1115 Config: Single-shot, A0 single-ended, +/-4.096V, 128 SPS, Disable comparator
#define ADS1115_CONFIG_BASE 0x8000  // OS bit
#define ADS1115_CONFIG_MUX_A0 0x4000
#define ADS1115_CONFIG_PGA_4096 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

// Global variables
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static float current_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

// Function prototypes
static int read_ads1115(int handle, int16_t *raw_value);
static float convert_to_current(int16_t raw_value);
static void add_to_buffer(float current);
static float calculate_average(void);
static void check_overcurrent(float average_current);
static void signal_handler(int signal);
static void cleanup(void);

// Signal handler for graceful shutdown
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup resources
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

// Read raw 16-bit value from ADS1115 conversion register
static int read_ads1115(int handle, int16_t *raw_value) {
    char reg = ADS1115_REG_CONVERSION;
    char buf[2];
    int result;

    // Write pointer to conversion register
    result = i2cWriteDevice(handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 config register: %d\n", result);
        return -1;
    }

    // Read 2 bytes (big-endian)
    result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register: %d\n", result);
        return -1;
    }

    *raw_value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Convert raw ADC value to current (A)
static float convert_to_current(int16_t raw_value) {
    // ADS1115 PGA = +/-4.096V, 16-bit signed
    // 16-bit signed range: -32768 to 32767
    // 4.096V / 32768 = 0.000125V per LSB
    float voltage = (float)raw_value * 0.000125f;

    // Clamp to sensor valid range
    if (voltage < MLX91204_VMIN) voltage = MLX91204_VMIN;
    if (voltage > MLX91204_VMAX) voltage = MLX91204_VMAX;

    // Ratiometric conversion: 0.5V -> 0A, 4.5V -> 100A
    float current = ((voltage - MLX91204_VMIN) / (MLX91204_VMAX - MLX91204_VMIN)) * MLX91204_IMAX;
    return current;
}

// Add current reading to circular buffer
static void add_to_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Calculate average current from buffer
static float calculate_average(void) {
    if (buffer_count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) {
        sum += current_buffer[i];
    }
    return sum / (float)buffer_count;
}

// Check for overcurrent condition
static void check_overcurrent(float average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
        printf("Overcurrent detected! Average current: %.2f A\n", average_current);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (running) {
        int16_t raw_value = 0;
        if (read_ads1115(i2c_handle, &raw_value) != 0) {
            fprintf(stderr, "Error reading ADS1115, retrying...\n");
            gpioDelay(1000000); // 1 second delay before retry
            continue;
        }

        float current = convert_to_current(raw_value);
        add_to_buffer(current);
        float average_current = calculate_average();
        check_overcurrent(average_current);

        printf("Current: %.2f A, Average: %.2f A\n", current, average_current);

        gpioDelay(1000000 / SAMPLE_RATE_HZ); // Delay for 10Hz sampling
    }

    // Cleanup
    cleanup();
    return 0;
}

