#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TCS34725_I2C_ADDR 0x29
#define TCS34725_ID_REG   0x12
#define TCS34725_ENABLE   0x00
#define TCS34725_ATIME    0x01
#define TCS34725_CONTROL  0x0F
#define TCS34725_CDATAL   0x14
#define TCS34725_RDATAL   0x16
#define TCS34725_GDATAL   0x18
#define TCS34725_BDATAL   0x1A

#define TCS34725_ID_VALUE 0x44
#define I2C_BUS 1
#define LOG_FILE "color_log.csv"
#define MAX_CONSECUTIVE_ERRORS 3
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t g_running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_word(int handle, uint8_t reg) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
    }
    return rc;
}

static int init_tcs34725(int handle) {
    int id = i2c_read_word(handle, TCS34725_ID_REG);
    if (id < 0) {
        fprintf(stderr, "Failed to read ID register\n");
        return -1;
    }
    if ((id & 0x00FF) != TCS34725_ID_VALUE) {
        fprintf(stderr, "Unexpected ID: 0x%02X (expected 0x%02X)\n", id & 0x00FF, TCS34725_ID_VALUE);
        return -1;
    }

    if (i2c_write_byte(handle, TCS34725_ATIME, 0xFF) < 0) return -1;
    if (i2c_write_byte(handle, TCS34725_CONTROL, 0x01) < 0) return -1;
    if (i2c_write_byte(handle, TCS34725_ENABLE, 0x01) < 0) return -1;
    gpioDelay(3000);
    if (i2c_write_byte(handle, TCS34725_ENABLE, 0x03) < 0) return -1;
    gpioDelay(3000);
    return 0;
}

static int read_color_data(int handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int c = i2c_read_word(handle, TCS34725_CDATAL);
    int r = i2c_read_word(handle, TCS34725_RDATAL);
    int g = i2c_read_word(handle, TCS34725_GDATAL);
    int b = i2c_read_word(handle, TCS34725_BDATAL);
    if (c < 0 || r < 0 || g < 0 || b < 0) return -1;
    *clear = (uint16_t)c;
    *red   = (uint16_t)r;
    *green = (uint16_t)g;
    *blue  = (uint16_t)b;
    return 0;
}

static void log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            clear, red, green, blue);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, TCS34725_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_tcs34725(i2c_handle) != 0) {
        fprintf(stderr, "TCS34725 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
        fflush(log_file);
    }

    int consecutive_errors = 0;

    while (g_running) {
        uint16_t clear, red, green, blue;
        if (read_color_data(i2c_handle, &clear, &red, &green, &blue) == 0) {
            consecutive_errors = 0;
            log_data(log_file, clear, red, green, blue);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error reading color data (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Max consecutive errors reached, exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2c_write_byte(i2c_handle, TCS34725_ENABLE, 0x00);
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

