#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MLX90817_ADDR  0x40
#define PRESSURE_REG   0x00
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1.0
#define MAX_READ_ERRORS 10

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int open_log_file(void)
{
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    /* Write header only if file is empty */
    long pos = ftell(g_log_file);
    if (pos == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
            perror("fprintf(header)");
            fclose(g_log_file);
            g_log_file = NULL;
            return -1;
        }
        if (fflush(g_log_file) != 0) {
            perror("fflush(header)");
            fclose(g_log_file);
            g_log_file = NULL;
            return -1;
        }
    }
    return 0;
}

static int read_pressure(int handle, float *pressure_kPa)
{
    int raw = i2cReadWordData(handle, PRESSURE_REG);
    if (raw < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: pigpio error %d\n",
                PRESSURE_REG, raw);
        return -1;
    }

    uint16_t raw_u = (uint16_t)raw;
    *pressure_kPa = ((float)raw_u / 65535.0f) * 500.0f;
    return 0;
}

static int log_data(FILE *fp, float pressure_kPa)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        perror("gmtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, pressure_kPa) < 0) {
        perror("fprintf(data)");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush(data)");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: pigpio error %d\n",
                I2C_BUS, MLX90817_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (open_log_file() != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    int consecutive_errors = 0;

    while (g_running) {
        float pressure;
        if (read_pressure(g_i2c_handle, &pressure) == 0) {
            consecutive_errors = 0;
            if (log_data(g_log_file, pressure) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Pressure read failed (%d/%d)\n",
                    consecutive_errors, MAX_READ_ERRORS);
            if (consecutive_errors >= MAX_READ_ERRORS) {
                fprintf(stderr, "Too many consecutive I2C errors; aborting.\n");
                break;
            }
        }

        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

