#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0f
#define ADC_VREF 5.0f
#define ADC_MAX 32767.0f
#define ADC_GAIN_2_3 0x0200
#define ADC_MODE_SINGLE 0x0100
#define ADC_DR_128 0x0080
#define ADC_MUX_AIN0 0x4000
#define ADC_MUX_AIN1 0x5000
#define ADC_CONFIG (ADC_MODE_SINGLE | ADC_GAIN_2_3 | ADC_DR_128 | ADC_MUX_AIN0)
#define ADC_CONFIG_TEMP (ADC_MODE_SINGLE | ADC_GAIN_2_3 | ADC_DR_128 | ADC_MUX_AIN1)
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_config(int handle, uint16_t config) {
    char buf[3];
    buf[0] = 0x01;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    return i2cWriteDevice(handle, buf, 3);
}

static int read_adc(int handle, int16_t *value) {
    char reg = 0x00;
    char buf[2];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(handle, &reg, 1) != 0) {
            fprintf(stderr, "I2C write error (reg select): %s\n", pigpio_error(0));
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (i2cReadDevice(handle, buf, 2) != 2) {
            fprintf(stderr, "I2C read error (data): %s\n", pigpio_error(0));
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        *value = (int16_t)((buf[0] << 8) | buf[1]);
        return 0;
    }
    return -1;
}

static int read_pressure(int handle, float *pressure) {
    int16_t raw;
    if (read_adc(handle, &raw) != 0) return -1;
    *pressure = (raw / ADC_MAX) * ADC_VREF;
    *pressure = (*pressure / ADC_VREF) * 400.0f;
    return 0;
}

static int read_temperature(int handle, float *temperature) {
    int16_t raw;
    if (read_adc(handle, &raw) != 0) return -1;
    *temperature = (raw / ADC_MAX) * ADC_VREF;
    *temperature = (*temperature / ADC_VREF) * 100.0f;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, ADS1115_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        if (write_config(i2c_handle, ADC_CONFIG) != 0) {
            fprintf(stderr, "Failed to write pressure config\n");
            gpioDelay(1000000);
            continue;
        }
        gpioDelay(10000);

        float pressure = 0.0f;
        if (read_pressure(i2c_handle, &pressure) != 0) {
            fprintf(stderr, "Pressure read failed\n");
            gpioWrite(LED_GPIO, 0);
            gpioDelay(1000000);
            continue;
        }

        if (write_config(i2c_handle, ADC_CONFIG_TEMP) != 0) {
            fprintf(stderr, "Failed to write temperature config\n");
            gpioDelay(1000000);
            continue;
        }
        gpioDelay(10000);

        float temperature = 0.0f;
        if (read_temperature(i2c_handle, &temperature) != 0) {
            fprintf(stderr, "Temperature read failed\n");
            gpioWrite(LED_GPIO, 0);
            gpioDelay(1000000);
            continue;
        }

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(1000000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

