#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Configuration */
#define SPI_CHANNEL    0          /* MCP3008 on SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* SPI mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define OVERCURRENT_THRESHOLD 10.0 /* Amperes */
#define MOTOR_SHUTDOWN_PIN 27     /* GPIO27 */
#define SAMPLE_INTERVAL_US 100000 /* 100 ms */
#define LOG_FILE_NAME  "current_log.txt"

/* MLX91209 parameters (example values) */
#define SENSOR_SENSITIVITY 0.066   /* 66 mV/A */
#define SENSOR_ZERO_CURRENT_V 1.65 /* Vcc/2 = 3.3V / 2 */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7)                             */
/* Returns 0-1023 on success, -1 on error                              */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI protocol: 3-byte transfer
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   Byte 2: 0x00  (clock out remaining bits)
     * Response: bits 9-8 in rx[1] lower 2 bits, bits 7-0 in rx[2]
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value to current (A)                                    */
/* ------------------------------------------------------------------ */
static double adc_to_current(int adc_value)
{
    double voltage = (double)adc_value * 3.3 / 1024.0;
    double current = (voltage - SENSOR_ZERO_CURRENT_V) / SENSOR_SENSITIVITY;
    return current;
}

/* ------------------------------------------------------------------ */
/* Log a reading with timestamp                                        */
/* ------------------------------------------------------------------ */
static void log_reading(double current)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[64];

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s, Current: %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file\n");
    }
}

/* ------------------------------------------------------------------ */
/* Log an overcurrent event                                            */
/* ------------------------------------------------------------------ */
static void log_overcurrent_event(void)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[64];

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s, OVERCURRENT: Motor shutdown triggered!\n", timestamp) < 0) {
        fprintf(stderr, "Failed to write overcurrent event\n");
        return;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush overcurrent event\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure motor shutdown pin is LOW before terminating */
    if (gpioInitialise() >= 0) {
        gpioWrite(MOTOR_SHUTDOWN_PIN, 0);
        gpioTerminate();
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI bus for MCP3008 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure motor shutdown pin as output, initially LOW */
    if (gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR_SHUTDOWN_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0);

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Motor current monitor started. Logging to %s\n", LOG_FILE_NAME);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (program_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double current = adc_to_current(adc_value);

        log_reading(current);

        if (current > OVERCURRENT_THRESHOLD) {
            printf("OVERCURRENT: %.2f A > %.2f A\n", current, OVERCURRENT_THRESHOLD);
            if (gpioWrite(MOTOR_SHUTDOWN_PIN, 1) != 0) {
                fprintf(stderr, "Failed to assert motor shutdown pin\n");
            }
            log_overcurrent_event();
            break; /* Exit loop after shutdown */
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

