#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000  /* 1 MHz */
#define SPI_FLAGS      0        /* mode 0, active-low CE0 */
#define ADC_CHANNEL    0        /* MCP3008 single-ended channel 0 */
#define LOG_FILE       "methane_log.txt"
#define PPM_MAX        5000.0f
#define PPM_THRESHOLD  1000.0f
#define SAMPLE_US      1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success and stores the 10-bit ADC value in *out;
 * returns -1 on SPI transfer failure.
 */
static int read_mcp3008(int handle, int channel, uint16_t *out)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer, mode 0):
     *   tx[0] = 0x01                       start bit
     *   tx[1] = (0x80 | (channel << 4))    SGL/DIFF=1, D2 D1 D0 = channel
     *   tx[2] = 0x00                       dummy (clocks out low 2 bits)
     * Result: ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)(0x80 | (channel << 4)), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    *out = ((uint16_t)(rx[1] & 0x03) << 8) | (uint16_t)(rx[2] & 0xFF);
    return 0;
}

static float adc_to_ppm(uint16_t adc)
{
    return ((float)adc / 1023.0f) * PPM_MAX;
}

static void log_reading(FILE *fp, float ppm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s, %.2f PPM\n", ts, ppm) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s for append\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Methane monitoring started. Logging to %s. Press Ctrl+C to exit.\n",
           LOG_FILE);

    while (g_running) {
        uint16_t adc = 0;
        if (read_mcp3008(g_spi_handle, ADC_CHANNEL, &adc) != 0) {
            fprintf(stderr, "ADC read failed; continuing\n");
        } else {
            float ppm = adc_to_ppm(adc);
            log_reading(fp, ppm);

            if (ppm > PPM_THRESHOLD) {
                fprintf(stderr,
                        "\033[1;31mALARM: Methane leak detected! %.2f PPM\033[0m\n",
                        ppm);
            }
        }

        /* Sleep 1 s; pigpio's gpioDelay is interruptible by signals */
        gpioDelay(SAMPLE_US);
    }

    /* --- cleanup --- */
    printf("\nShutting down...\n");
    if (fp != NULL) {
        fclose(fp);
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

