#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADS1115 I2C address (ADDR pin tied to GND) */
#define ADS1115_ADDR 0x48

/* ADS1115 registers */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config register bit fields */
#define ADS1115_CFG_OS_BEGIN   0x8000  /* Operational status / single-shot start */
#define ADS1115_CFG_MUX_AIN0  0x4000  /* AIN0 vs GND */
#define ADS1115_CFG_PGA_4_096V 0x0200 /* +/-4.096V range */
#define ADS1115_CFG_MODE_SS   0x0100  /* Single-shot mode */
#define ADS1115_CFG_DR_128    0x0080  /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE 0x0003  /* Disable comparator */

/* MLX90830 transfer function (example values) */
#define MLX90830_OFFSET_V 0.5f
#define MLX90830_SENSITIVITY_V_PER_KPA 0.1f
#define MLX90830_MIN_PRESSURE_KPA 0.0f
#define MLX90830_MAX_PRESSURE_KPA 100.0f
#define ADS1115_VREF 4.096f
#define ADC_MAX_COUNT 32767.0f  /* 16-bit signed, positive range */

#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_adc_raw(void) {
    char config[3];
    char conv[2];
    int16_t raw;

    /* Write config: single-shot, AIN0, +/-4.096V, 128 SPS, comparator off */
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0 |
                 ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_SS |
                 ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE) & 0xFF;
    config[2] = ((ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0 |
                  ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_SS |
                  ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE) >> 8) & 0xFF;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing ADS1115 config: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    /* Read conversion register (2 bytes, big-endian) */
    if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERSION, conv, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion: %s\n", strerror(errno));
        return -1;
    }

    raw = (int16_t)((conv[0] << 8) | conv[1]);
    return raw;
}

static float convert_to_pressure(int16_t raw) {
    float voltage = ((float)raw / ADC_MAX_COUNT) * ADS1115_VREF;
    float pressure = (voltage - MLX90830_OFFSET_V) / MLX90830_SENSITIVITY_V_PER_KPA;
    return pressure;
}

static int log_pressure(float pressure) {
    FILE *fp;
    time_t t;
    struct tm tm_info;
    char timestamp[32];

    t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    fprintf(fp, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADS1115 address */
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for graceful shutdown */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not set SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not set SIGTERM handler: %s\n", strerror(errno));
    }

    printf("MLX90830 pressure logger started. Logging to '%s'. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (running) {
        int16_t raw = read_adc_raw();
        if (raw < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float pressure = convert_to_pressure(raw);

        if (pressure < MLX90830_MIN_PRESSURE_KPA ||
            pressure > MLX90830_MAX_PRESSURE_KPA) {
            fprintf(stderr, "Pressure out of range: %.2f kPa (raw=%d)\n",
                    pressure, raw);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (log_pressure(pressure) != 0) {
            fprintf(stderr, "Error logging pressure data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean up */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

