#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_FLAGS 0

#define ADC_CHANNEL_X 0
#define ADC_CHANNEL_Y 1
#define ADC_CHANNEL_Z 2

#define VREF 3.3
#define ADC_MAX 1023.0
#define SENSITIVITY 0.3
#define ZERO_G_OFFSET 1.65
#define IMPACT_THRESHOLD 2.0
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

#define LOG_FILE "impact_log.txt"
#define CS_PIN 8

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    gpioWrite(CS_PIN, 0);
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    gpioWrite(CS_PIN, 1);

    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_voltage(int adc_value) {
    return (adc_value / ADC_MAX) * VREF;
}

static double voltage_to_g(double voltage) {
    return (voltage - ZERO_G_OFFSET) / SENSITIVITY;
}

static double calculate_magnitude(double x, double y, double z) {
    return sqrt(x * x + y * y + z * z);
}

static void log_data(double x, double y, double z, double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fflush(log_file);
}

static void log_impact(double x, double y, double z, double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,IMPACT DETECTED,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL335 impact detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int x_adc = read_adc(ADC_CHANNEL_X);
        int y_adc = read_adc(ADC_CHANNEL_Y);
        int z_adc = read_adc(ADC_CHANNEL_Z);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (x_adc > 1023 || y_adc > 1023 || z_adc > 1023) {
            fprintf(stderr, "ADC value out of range (X=%d, Y=%d, Z=%d)\n", x_adc, y_adc, z_adc);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double x_voltage = adc_to_voltage(x_adc);
        double y_voltage = adc_to_voltage(y_adc);
        double z_voltage = adc_to_voltage(z_adc);

        double x_g = voltage_to_g(x_voltage);
        double y_g = voltage_to_g(y_voltage);
        double z_g = voltage_to_g(z_voltage);

        double magnitude = calculate_magnitude(x_g, y_g, z_g);

        log_data(x_g, y_g, z_g, magnitude);

        if (magnitude > IMPACT_THRESHOLD) {
            log_impact(x_g, y_g, z_g, magnitude);
            printf("Impact detected! Magnitude: %.3f g\n", magnitude);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

