#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1172_ADDR 0x49
#define LOG_FILE "biometric_log.csv"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */

/* Si1172 command register (0xC0) */
#define SI1172_CMD_REG 0xC0
/* Si1172 data register (0xC1) holds the first byte of the FIFO payload */
#define SI1172_DATA_REG 0xC1

/* Command values */
#define SI1172_CMD_RESET 0x01
#define SI1172_CMD_START 0x02
#define SI1172_CMD_READ_FIFO 0x03

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    return i2cWriteDevice(handle, buf, 2);
}

static int i2c_read_bytes(int handle, uint8_t reg, char *buf, uint32_t count)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0)
        return -1;
    return i2cReadDevice(handle, buf, count);
}

/* ------------------------------------------------------------------ */
/* Si1172 initialization                                               */
/* ------------------------------------------------------------------ */
static int si1172_init(int handle)
{
    /* Issue a soft reset */
    if (i2c_write_byte(handle, SI1172_CMD_REG, SI1172_CMD_RESET) != 0) {
        fprintf(stderr, "Error: Si1172 reset write failed.\n");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms settle */

    /* Start continuous measurement mode */
    if (i2c_write_byte(handle, SI1172_CMD_REG, SI1172_CMD_START) != 0) {
        fprintf(stderr, "Error: Si1172 start measurement failed.\n");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms for first conversion */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one 16-bit sample from the Si1172 FIFO                          */
/* ------------------------------------------------------------------ */
static int si1172_read_sample(int handle, uint16_t *ir_value, uint16_t *red_value)
{
    char buf[2];
    int ret;

    /* Trigger a FIFO read */
    if (i2c_write_byte(handle, SI1172_CMD_REG, SI1172_CMD_READ_FIFO) != 0)
        return -1;

    /* Read 2 bytes: IR ADC (MSB) then RED ADC (LSB) */
    ret = i2c_read_bytes(handle, SI1172_DATA_REG, buf, 2);
    if (ret != 2)
        return -1;

    *ir_value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *red_value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one data row                                                    */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t ir_value, uint16_t red_value,
                     int error_flag)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%d\n", timestamp, ir_value, red_value, error_flag);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t ir_value = 0, red_value = 0;
    int error_flag = 0;

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to Si1172 */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). "
                        "Sensor may be absent or bus unavailable.\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si1172_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: Si1172 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,HR_bpm,SpO2_percent,Error_Flag\n");
        fflush(g_log_file);
    }

    printf("Si1172 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        if (si1172_read_sample(g_i2c_handle, &ir_value, &red_value) == 0) {
            error_flag = 0;
            log_data(g_log_file, ir_value, red_value, error_flag);
        } else {
            error_flag = 1;
            log_data(g_log_file, 0, 0, error_flag);
            fprintf(stderr, "Warning: I2C read error (flag=%d).\n", error_flag);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

