    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t ir_value = 0, red_value = 0;
    int error_flag = 0;

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to Si1172 */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). "
                        "Sensor may be absent or bus unavailable.\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si1172_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: Si1172 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,HR_bpm,SpO2_percent,Error_Flag\n");
        fflush(g_log_file);
    }

    printf("Si1172 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        if (si1172_read_sample(g_i2c_handle, &ir_value, &red_value) == 0) {
            error_flag = 0;
            log_data(g_log_file, ir_value, red_value, error_flag);
        } else {
            error_flag = 1;
            log_data(g_log_file, 0, 0, error_flag);
            fprintf(stderr, "Warning: I2C read error (flag=%d).\n", error_flag);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

