#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define VREF 3.3
#define MAX_FLOW_RATE 5.0
#define ADC_MAX_VALUE 1023.0
#define LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, baud %d).\n", SPI_CHANNEL, SPI_BAUD);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        spiClose(spi_handle);
        spi_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d.\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed.\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double convert_to_flow_rate(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1.0;
    }

    if (adc_value == 0) {
        fprintf(stderr, "Warning: Sensor absent or disconnected (ADC reads 0).\n");
        return -1.0;
    }

    if (adc_value >= (int)ADC_MAX_VALUE) {
        fprintf(stderr, "Warning: ADC saturated (sensor may be disconnected or at max flow).\n");
        return -1.0;
    }

    return ((double)adc_value / ADC_MAX_VALUE) * MAX_FLOW_RATE;
}

static void log_flow_rate(double flow_rate) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s.%06ld,%.2f\n", timestamp, ts.tv_nsec / 1000, flow_rate);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize() != 0) {
        return 1;
    }

    printf("Oxygen concentrator flow monitoring started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value.\n");
        } else {
            double flow_rate = convert_to_flow_rate(adc_value);
            if (flow_rate >= 0.0 && flow_rate <= MAX_FLOW_RATE) {
                log_flow_rate(flow_rate);
            } else {
                fprintf(stderr, "Error: Flow rate out of range: %.2f L/min\n", flow_rate);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

