#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define BUZZER_GPIO 18
#define FLAME_THRESHOLD 1.0f
#define TEMP_OFFSET 25.0f
#define TEMP_SCALE 0.001f
#define ADC_MAX 1023
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *buzzer_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ambient_temp(float *temp) {
    FILE *fp = fopen("ambient_temp.txt", "r");
    if (!fp) {
        fprintf(stderr, "Error: cannot open ambient_temp.txt: %s\n", strerror(errno));
        return -1;
    }
    if (fscanf(fp, "%f", temp) != 1) {
        fprintf(stderr, "Error: invalid data in ambient_temp.txt\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int read_mcp3008(int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static void log_data(int adc_value, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n",
            timestamp, adc_value, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file);
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        perror("fopen flame_log.txt");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        fclose(log_file);
        return 1;
    }

    unsigned char mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        cleanup();
        return 1;
    }
    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        cleanup();
        return 1;
    }
    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return 1;
    }
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(buzzer_line, "flame_buzzer", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature = 0.0f;
        if (read_ambient_temp(&temperature) != 0) {
            fprintf(stderr, "Warning: using default temperature 25.0°C\n");
            temperature = 25.0f;
        }

        int adc_value = 0;
        int retries = 0;
        int read_ok = 0;
        while (retries < MAX_RETRIES && !read_ok) {
            if (read_mcp3008(0, &adc_value) == 0) {
                read_ok = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    usleep(10000);
                }
            }
        }
        if (!read_ok) {
            fprintf(stderr, "Error: failed to read ADC after %d retries\n", MAX_RETRIES);
            gpiod_line_set_value(buzzer_line, 0);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float voltage = (float)adc_value / (float)ADC_MAX * 3.3f;
        float compensated_voltage = voltage + (temperature - TEMP_OFFSET) * TEMP_SCALE;
        int flame_detected = (compensated_voltage > FLAME_THRESHOLD) ? 1 : 0;

        log_data(adc_value, voltage, compensated_voltage, temperature, flame_detected);

        if (flame_detected) {
            gpiod_line_set_value(buzzer_line, 1);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

