    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        cleanup();
        return 1;
    }
    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return 1;
    }
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(buzzer_line, "flame_buzzer", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature = 0.0f;
        if (read_ambient_temp(&temperature) != 0) {
            fprintf(stderr, "Warning: using default temperature 25.0°C\n");
            temperature = 25.0f;
        }

        int adc_value = 0;
        int retries = 0;
        int read_ok = 0;
        while (retries < MAX_RETRIES && !read_ok) {
            if (read_mcp3008(0, &adc_value) == 0) {
                read_ok = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    usleep(10000);
                }
            }
        }
        if (!read_ok) {
            fprintf(stderr, "Error: failed to read ADC after %d retries\n", MAX_RETRIES);
            gpiod_line_set_value(buzzer_line, 0);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float voltage = (float)adc_value / (float)ADC_MAX * 3.3f;
        float compensated_voltage = voltage + (temperature - TEMP_OFFSET) * TEMP_SCALE;
        int flame_detected = (compensated_voltage > FLAME_THRESHOLD) ? 1 : 0;

        log_data(adc_value, voltage, compensated_voltage, temperature, flame_detected);

        if (flame_detected) {
            gpiod_line_set_value(buzzer_line, 1);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

