#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_GPIO 17
#define WATER_LEVEL_THRESHOLD_HIGH 75
#define WATER_LEVEL_THRESHOLD_LOW 70
#define JSON_FILE "water_levels.json"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds in microseconds */

static volatile sig_atomic_t program_running = 1;
static int spi_handle = -1;
static FILE *json_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     * Byte 0: 0x01 (start bit)
     * Byte 1: (0x08 | channel) << 4  -> 0x80|channel<<4 (single-ended + channel)
     * Byte 2: 0x00 (padding)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    /* 10-bit result: lower 2 bits of rx[1] + 8 bits of rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static float calculate_water_level(int adc_value) {
    return ((float)adc_value / 1023.0f) * 100.0f;
}

static void log_water_level(float water_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(json_file, "  {\"timestamp\": \"%s\", \"water_level\": %.2f}\n", timestamp, water_level);
    fflush(json_file);
}

static void control_led(float water_level) {
    static int led_state = 0;
    if (water_level > WATER_LEVEL_THRESHOLD_HIGH && led_state == 0) {
        gpioWrite(LED_GPIO, 1);
        led_state = 1;
    } else if (water_level < WATER_LEVEL_THRESHOLD_LOW && led_state == 1) {
        gpioWrite(LED_GPIO, 0);
        led_state = 0;
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    if (json_file != NULL) {
        fprintf(json_file, "]\n");
        fclose(json_file);
        json_file = NULL;
    }
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 (CE0) at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (pigpio error %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO as output and ensure it starts OFF */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Open JSON file in append mode; write a JSON array start if empty */
    json_file = fopen(JSON_FILE, "a");
    if (json_file == NULL) {
        fprintf(stderr, "Error: Could not open JSON file %s\n", JSON_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write JSON array start if file is empty */
    fseek(json_file, 0, SEEK_END);
    if (ftell(json_file) == 0) {
        fprintf(json_file, "[\n");
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            float water_level = calculate_water_level(adc_value);
            log_water_level(water_level);
            control_led(water_level);
            printf("Water Level: %.2f%%\n", water_level);
        }

        /* Sleep in small increments so signals are handled promptly */
        for (int i = 0; i < 50 && program_running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

