#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_RAW 300
#define DEFAULT_MAX_RAW 700
#define DEFAULT_THRESHOLD 30
#define DEFAULT_LOGGING_FREQUENCY 60
#define DEFAULT_RECIPIENT_EMAIL "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG_FILE "/etc/msmtp.conf"

static int spi_channel = DEFAULT_SPI_CHANNEL;
static int adc_channel = DEFAULT_ADC_CHANNEL;
static int min_raw = DEFAULT_MIN_RAW;
static int max_raw = DEFAULT_MAX_MAX;
static int threshold = DEFAULT_THRESHOLD;
static int logging_frequency = DEFAULT_LOGGING_FREQUENCY;
static char *recipient_email = DEFAULT_RECIPIENT_EMAIL;
static char *msmtp_config_file = DEFAULT_MSMTP_CONFIG_FILE;
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    if (spiXfer(handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture(int raw_value, int min_raw, int max_raw) {
    if (raw_value < min_raw) raw_value = min_raw;
    if (raw_value > max_raw) raw_value = max_raw;
    return 100.0f * (float)(raw_value - min_raw) / (float)(max_raw - min_raw);
}

static void log_data(float moisture, const char *filename) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open %s for writing\n", filename);
        return;
    }
    fprintf(fp, "%s, %.2f\n", timestamp, moisture);
    fclose(fp);
}

static void send_email_alert(float moisture, const char *recipient, const char *config_file) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    char body[256];
    snprintf(body, sizeof(body),
             "Subject: Plant Moisture Alert\n\n"
             "Plant moisture level is below threshold!\n"
             "Timestamp: %s\n"
             "Moisture: %.2f%%\n", timestamp, moisture);
    char command[512];
    snprintf(command, sizeof(command),
             "echo '%s' | msmtp -t -f root@localhost --config-file=%s %s",
             body, config_file, recipient);
    FILE *fp = popen(command, "r");
    if (!fp) {
        fprintf(stderr, "Error: Could not execute email command\n");
        return;
    }
