#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended CH0 */
#define LOG_FILE       "soil_moisture.log"
#define DEFAULT_SAMPLE_INTERVAL 1 /* seconds */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the MCP3008 (single-ended, channel 0-7)        */
/* Returns 0-1023 on success, -1 on SPI error.                         */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out low 2 bits)
     * Result: rx[1] bits 1:0 are the high 2 bits, rx[2] is the low 8 bits.
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert raw ADC value to moisture percentage                       */
/* 0 = bone dry, 1023 = fully submerged (clamped to [0, 100]).         */
/* ------------------------------------------------------------------ */
static int calculate_moisture_percentage(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    int pct = (int)(((float)adc_value / 1023.0f) * 100.0f);
    if (pct < 0)   pct = 0;
    if (pct > 100) pct = 100;
    return pct;
}

/* ------------------------------------------------------------------ */
/* Log one sample with an ISO-8601 timestamp                          */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int adc_value, int moisture_pct)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, ADC: %4d, Moisture: %3d%%\n", ts, adc_value, moisture_pct);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int sample_interval = DEFAULT_SAMPLE_INTERVAL;

    if (argc > 1) {
        sample_interval = atoi(argv[1]);
        if (sample_interval <= 0) {
            fprintf(stderr, "Invalid sample interval '%s'; using default %d s\n",
                    argv[1], DEFAULT_SAMPLE_INTERVAL);
            sample_interval = DEFAULT_SAMPLE_INTERVAL;
        }
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open SPI ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Soil moisture monitoring started.\n");
    printf("  SPI channel : %d\n", SPI_CHANNEL);
    printf("  SPI speed   : %d Hz\n", SPI_SPEED);
    printf("  ADC channel : %d\n", ADC_CHANNEL);
    printf("  Log file    : %s\n", LOG_FILE);
    printf("  Sample      : every %d s\n", sample_interval);
    printf("Press Ctrl-C to exit.\n");

    /* ---- main loop ---- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Warning: SPI read error — sample skipped\n");
        } else {
            int moisture_pct = calculate_moisture_percentage(adc_value);
            log_data(g_log_file, adc_value, moisture_pct);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < (sample_interval * 10) && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

