#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define ADC_MAX 1023.0
#define MIN_VOLTAGE 0.5
#define MAX_VOLTAGE 4.5
#define MIN_PRESSURE 10.0
#define MAX_PRESSURE 150.0
#define SAMPLE_INTERVAL 1.0
#define SENSOR_TIMEOUT_SEC 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_voltage(int adc_value) {
    return ((float)adc_value / ADC_MAX) * VREF;
}

static float voltage_to_pressure(float voltage) {
    if (voltage < MIN_VOLTAGE) voltage = MIN_VOLTAGE;
    if (voltage > MAX_VOLTAGE) voltage = MAX_VOLTAGE;
    return MIN_PRESSURE + ((voltage - MIN_VOLTAGE) / (MAX_VOLTAGE - MIN_VOLTAGE)) * (MAX_PRESSURE - MIN_PRESSURE);
}

static void log_reading(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    printf("%s - Pressure: %.2f kPa\n", timestamp, pressure);
    fflush(stdout);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("MLX90823 Pressure Sensor Reader started. Press Ctrl+C to exit.\n");

    time_t last_change_time = time(NULL);
    int consecutive_errors = 0;

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            consecutive_errors++;
            if (consecutive_errors > 10) {
                fprintf(stderr, "Error: Too many consecutive SPI read failures\n");
                break;
            }
            time_sleep(SAMPLE_INTERVAL);
            continue;
        }
        consecutive_errors = 0;

        float voltage = adc_to_voltage(adc_value);
        float pressure = voltage_to_pressure(voltage);

        time_t current_time = time(NULL);
        if (current_time - last_change_time > SENSOR_TIMEOUT_SEC) {
            if (voltage <= 0.01 || voltage >= VREF - 0.01) {
                fprintf(stderr, "Warning: Sensor absent or disconnected (voltage stuck at %.2fV)\n", voltage);
            }
            last_change_time = current_time;
        }

        log_reading(pressure);
        time_sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

