#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 17
#define MOISTURE_LOW_THRESHOLD 300
#define MOISTURE_HIGH_THRESHOLD 600
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_US 5000000

#define SPI_READ_ERROR -1

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

typedef struct {
    LogEntry entries[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int spi_handle = -1;
static CircularBuffer log_buffer;
static volatile sig_atomic_t running = 1;

static void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void add_to_circular_buffer(CircularBuffer *cb, time_t ts, int moisture, int pump_state) {
    cb->entries[cb->head].timestamp = ts;
    cb->entries[cb->head].moisture_level = moisture;
    cb->entries[cb->head].pump_state = pump_state;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static void print_circular_buffer(const CircularBuffer *cb) {
    printf("\n--- Log Buffer (%d entries) ---\n", cb->count);
    for (int i = 0; i < cb->count; i++) {
        int idx = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts_str[32];
        struct tm *tm_info = localtime(&cb->entries[idx].timestamp);
        strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("[%s] Moisture: %d, Pump: %s\n",
               ts_str, cb->entries[idx].moisture_level,
               cb->entries[idx].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return SPI_READ_ERROR;

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) return SPI_READ_ERROR;

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) < 0) {
        fprintf(stderr, "Error: Failed to write GPIO %d\n", PUMP_GPIO);
    }
}

static void timer_callback(void *user_data) {
    (void)user_data;
    time_t now = time(NULL);
    int moisture = read_mcp3008(0);

    if (moisture == SPI_READ_ERROR) {
        fprintf(stderr, "Error: SPI read failed at %ld\n", (long)now);
        add_to_circular_buffer(&log_buffer, now, -1, -1);
        print_circular_buffer(&log_buffer);
        return;
    }

    int pump_state = -1;
    if (moisture < MOISTURE_LOW_THRESHOLD && !gpioRead(PUMP_GPIO)) {
        control_pump(1);
        pump_state = 1;
    } else if (moisture > MOISTURE_HIGH_THRESHOLD && gpioRead(PUMP_GPIO)) {
        control_pump(0);
        pump_state = 0;
    }

    add_to_circular_buffer(&log_buffer, now, moisture, pump_state);
    print_circular_buffer(&log_buffer);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, speed %d)\n",
                SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PUMP_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    init_circular_buffer(&log_buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, timer_callback, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set timer\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    gpioWrite(PUMP_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

