#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_STATUS_2 0x01
#define REG_INTR_ENABLE_1 0x02
#define REG_FIFO_WR_PTR 0x04
#define REG_OVF_COUNTER 0x05
#define REG_FIFO_RD_PTR 0x06
#define REG_FIFO_DATA 0x07
#define REG_MODE_CONFIG 0x06
#define REG_SPO2_CONFIG 0x08
#define REG_LED1_PA 0x09
#define REG_LED2_PA 0x0A
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15

#define SAMPLE_INTERVAL_US 1000000
#define LOG_THRESHOLD_SPO2 95.0f
#define LOG_THRESHOLD_HR 100.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    return i2cWriteDevice(handle, buf, 2);
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) return -1;
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) return -1;
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int i2c_read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int init_max30102(int handle) {
    uint8_t part_id = 0;
    if (i2c_read_reg(handle, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: Failed to read Part ID register.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Error: Unexpected Part ID 0x%02X (expected 0x%02X). Sensor not present?\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (i2c_write_reg(handle, REG_MODE_CONFIG, 0x40) != 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg(handle, REG_INTR_ENABLE_1, 0x00) != 0) return -1;
    if (i2c_write_reg(handle, REG_FIFO_WR_PTR, 0x00) != 0) return -1;
    if (i2c_write_reg(handle, REG_OVF_COUNTER, 0x00) != 0) return -1;
    if (i2c_write_reg(handle, REG_FIFO_RD_PTR, 0x00) != 0) return -1;
    if (i2c_write_reg(handle, REG_FIFO_DATA, 0x00) != 0) return -1;
    if (i2c_write_reg(handle, REG_MODE_CONFIG, 0x03) != 0) return -1;
    if (i2c_write_reg(handle, REG_SPO2_CONFIG, 0x27) != 0) return -1;
    if (i2c_write_reg(handle, REG_LED1_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(handle, REG_LED2_PA, 0x24) != 0) return -1;

    return 0;
}

static int read_fifo_data(int handle, uint32_t *red, uint32_t *ir) {
    uint8_t buf[6];
    if (i2c_read_burst(handle, REG_FIFO_DATA, buf, 6) != 0) return -1;
    *red = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    *ir = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | buf[5];
    return 0;
}

static float calculate_spo2(uint32_t *red, uint32_t *ir, int num_samples) {
    if (num_samples < 2) return -1.0f;
    float sum_red = 0.0f, sum_ir = 0.0f;
    for (int i = 0; i < num_samples; i++) {
        sum_red += red[i];
        sum_ir += ir[i];
    }
    if (sum_red == 0.0f || sum_ir == 0.0f) return -1.0f;
    float ratio = sum_ir / sum_red;
    float target = 0.96f;
    float diff = ratio - target;
    if (diff < 0.0f) diff = -diff;
    return 110.0f - (10.0f * diff);
}

static int calculate_hr(uint32_t *ir, int num_samples) {
    if (num_samples < 2) return -1;
    int peaks = 0;
    for (int i = 1; i < num_samples - 1; i++) {
        if (ir[i] > ir[i - 1] && ir[i] > ir[i + 1]) peaks++;
    }
    if (peaks == 0) return -1;
    return (peaks * 60) / num_samples;
}

static void log_event(float spo2, int hr) {
    FILE *fp = fopen("health_log.txt", "a");
    if (!fp) {
        perror("Error opening health_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    fprintf(fp, "%s, SpO2: %.2f%%, HR: %d BPM\n", timestamp, spo2, hr);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at bus %d, addr 0x%02X.\n", I2C_BUS, MAX30102_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_max30102(i2c_handle) != 0) {
        fprintf(stderr, "Error: MAX30102 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint32_t red_buf[100], ir_buf[100];
    int idx = 0;

    while (running) {
        uint32_t red, ir;
        if (read_fifo_data(i2c_handle, &red, &ir) != 0) {
            fprintf(stderr, "Error: Failed to read FIFO data.\n");
            gpioDelay(100000);
            continue;
        }

        red_buf[idx] = red;
        ir_buf[idx] = ir;
        idx++;

        if (idx >= 100) {
            idx = 0;
            float spo2 = calculate_spo2(red_buf, ir_buf, 100);
            int hr = calculate_hr(ir_buf, 100);

            if (spo2 > 0.0f && hr > 0) {
                if (spo2 < LOG_THRESHOLD_SPO2 || hr > LOG_THRESHOLD_HR) {
                    log_event(spo2, hr);
                }
            } else {
                fprintf(stderr, "Warning: Invalid sensor data (SpO2: %.2f, HR: %d).\n", spo2, hr);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

