#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_LO_THRESH 0x02
#define ADS1115_REG_HI_THRESH 0x03

#define RELAY_LINE     17
#define REED_LINE      27

#define BASELINE_SAMPLES 10
#define BASELINE_DELAY_MS 50
#define POLL_DELAY_MS 200
#define RELAY_PULSE_MS 3000
#define LOG_FILE "/var/log/door_events.log"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *reed_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = {reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF)};
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    uint16_t lo, hi;
    if (i2c_write_reg16(fd, ADS1115_REG_LO_THRESH, 0x0000) < 0) return -1;
    if (i2c_write_reg16(fd, ADS1115_REG_HI_THRESH, 0xFFFF) < 0) return -1;
    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, 0x8083) < 0) return -1;
    usleep(10000);
    if (i2c_read_reg16(fd, ADS1115_REG_LO_THRESH, &lo) < 0) return -1;
    if (i2c_read_reg16(fd, ADS1115_REG_HI_THRESH, &hi) < 0) return -1;
    if (lo != 0x0000 || hi != 0xFFFF) return -1;
    return 0;
}

static int ads1115_read(int fd, int16_t *raw) {
    uint16_t val;
    if (i2c_read_reg16(fd, ADS1115_REG_CONV, &val) < 0) return -1;
    *raw = (int16_t)val;
    return 0;
}

static int read_distance(int fd, int16_t *raw) {
    if (ads1115_read(fd, raw) < 0) return -1;
    return 0;
}

static int read_reed(void) {
    int v = gpiod_line_get_value(reed_line);
    if (v < 0) return -1;
    return (v == 0) ? 1 : 0;
}

static void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen log"); return; }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[64];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, event);
    fclose(fp);
}

static void cleanup(void) {
    if (relay_line) gpiod_line_set_value(relay_line, 0);
    if (relay_line) gpiod_line_release(relay_line);
    if (reed_line) gpiod_line_release(reed_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) { perror("open i2c"); return 1; }
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE"); cleanup(); return 1;
    }
    if (ads1115_init(i2c_fd) < 0) {
        fprintf(stderr, "ADS1115 init failed\n");
        cleanup(); return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) { perror("gpiod_chip_open"); cleanup(); return 1; }
    relay_line = gpiod_chip_get_line(chip, RELAY_LINE);
    reed_line = gpiod_chip_get_line(chip, REED_LINE);
    if (!relay_line || !reed_line) {
        perror("gpiod_chip_get_line"); cleanup(); return 1;
    }
    if (gpiod_line_request_output(relay_line, "door_lock", 0) < 0) {
        perror("gpiod_line_request_output relay"); cleanup(); return 1;
    }
    if (gpiod_line_request_input(reed_line, "door_reed") < 0) {
        perror("gpiod_line_request_input reed"); cleanup(); return 1;
    }

    int16_t samples[BASELINE_SAMPLES];
    int ok = 0;
    for (int i = 0; i < BASELINE_SAMPLES; i++) {
