    if (i2c_fd < 0) { perror("open i2c"); return 1; }
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE"); cleanup(); return 1;
    }
    if (ads1115_init(i2c_fd) < 0) {
        fprintf(stderr, "ADS1115 init failed\n");
        cleanup(); return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) { perror("gpiod_chip_open"); cleanup(); return 1; }
    relay_line = gpiod_chip_get_line(chip, RELAY_LINE);
    reed_line = gpiod_chip_get_line(chip, REED_LINE);
    if (!relay_line || !reed_line) {
        perror("gpiod_chip_get_line"); cleanup(); return 1;
    }
    if (gpiod_line_request_output(relay_line, "door_lock", 0) < 0) {
        perror("gpiod_line_request_output relay"); cleanup(); return 1;
    }
    if (gpiod_line_request_input(reed_line, "door_reed") < 0) {
        perror("gpiod_line_request_input reed"); cleanup(); return 1;
    }

    int16_t samples[BASELINE_SAMPLES];
    int ok = 0;
    for (int i = 0; i < BASELINE_SAMPLES; i++) {
        if (read_distance(i2c_fd, &samples[i]) == 0) ok++;
        usleep(BASELINE_DELAY_MS * 1000);
    }
    if (ok == 0) {
        fprintf(stderr, "No valid baseline samples\n");
        cleanup(); return 1;
    }
    int32_t sum = 0;
    for (int i = 0; i < BASELINE_SAMPLES; i++) sum += samples[i];
    int32_t avg = sum / ok;
    int threshold = (int)(avg * 0.8);
    printf("Baseline average: %d, threshold: %d\n", avg, threshold);

    while (running) {
        int16_t raw;
        if (read_distance(i2c_fd, &raw) < 0) {
            log_event("I2C read error");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }
        if (raw < threshold) {
            printf("Proximity detected (raw=%d)\n", raw);
            log_event("Proximity detected");
            if (gpiod_line_set_value(relay_line, 1) < 0) {
                log_event("Failed to energize relay");
            } else {
                usleep(RELAY_PULSE_MS * 1000);
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    log_event("Failed to de-energize relay");
                } else {
                    log_event("Relay de-energized");
                }
            }
            int reed = read_reed();
            if (reed < 0) log_event("Failed to read reed sensor");
            else if (reed) log_event("Door opened");
            else log_event("Door not opened");
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    cleanup();
