#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CE 8
#define ADC_CHANNEL 0
#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_DURATION 10
#define DEFAULT_INTERVAL 60
#define MAX_SPI_RETRIES 3
#define DRY_RAW 200
#define WET_RAW 800

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void log_message(const char *message) {
    FILE *fp = fopen("irrigation.log", "a");
    if (!fp) {
        perror("fopen irrigation.log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n", attempt + 1, MAX_SPI_RETRIES, ret);
        gpioDelay(10000);
    }
    return -1;
}

static float calculate_moisture(int adc_value) {
    if (adc_value < 0) return -1.0f;
    float pct = ((float)(adc_value - DRY_RAW) / (float)(WET_RAW - DRY_RAW)) * 100.0f;
    if (pct < 0.0f) pct = 0.0f;
    if (pct > 100.0f) pct = 100.0f;
    return pct;
}

static void control_pump(int state) {
