#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define PCF8591_ADDR 0x48
#define I2C_BUS "/dev/i2c-1"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

/* Control byte: single-ended mode, channel 0, analog output disabled */
#define PCF8591_CTRL_AIN0 0x00

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *value)
{
    uint8_t buf;
    ssize_t n = read(fd, &buf, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    *value = buf;
    return 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the PCF8591 slave address */
    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus address 0x%02X: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Configure PCF8591: single-ended mode, channel 0, analog output off */
    if (i2c_write_byte(fd, PCF8591_CTRL_AIN0) < 0) {
        goto cleanup;
    }

    /* First conversion is stale; discard it */
    uint8_t dummy;
    if (i2c_read_byte(fd, &dummy) < 0) {
        goto cleanup;
    }

    printf("PCF8591 AIN0 monitoring started. Press Ctrl-C to exit.\n");

    while (g_running) {
        uint8_t value;
        if (i2c_read_byte(fd, &value) < 0) {
            goto cleanup;
        }
        printf("AIN0: %u\n", value);
        usleep(SAMPLE_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

