#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define GPIO_MOTOR     27
#define BUFFER_SIZE    10
#define SAMPLE_HZ      1
#define VREF           3.3f
#define V_ZERO         2.5f
#define SENSITIVITY    0.0014f  /* 1.4 mV/Gauss */
#define THRESHOLD_GAUSS 500.0f
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x8083  /* AIN0 single-ended, +/-4.096V, 128 SPS, single-shot */

typedef struct {
    float gauss[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cb_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value) {
    cb->gauss[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->gauss[i];
    return sum / (float)cb->count;
}

static int16_t ads1115_read_raw(int handle) {
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_BASE >> 8) & 0xFF;
    config[2] = ADS1115_CONFIG_BASE & 0xFF;

    if (i2cWriteDevice(handle, config, 3) < 0) return -1;

    /* Wait for conversion (~8 ms at 128 SPS) */
    gpioDelay(10000);

    char reg = ADS1115_REG_CONV;
    if (i2cWriteDevice(handle, &reg, 1) < 0) return -1;

    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;

    return (int16_t)((buf[0] << 8) | buf[1]);
}

static float voltage_to_gauss(float voltage) {
    return (voltage - V_ZERO) / SENSITIVITY;
}

static void motor_shutdown(int gpio_pin) {
    if (gpioWrite(gpio_pin, 1) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d HIGH", gpio_pin);
    } else {
        syslog(LOG_INFO, "Motor shutdown signal activated (GPIO %d HIGH)", gpio_pin);
    }
}

static void motor_reset(int gpio_pin) {
    if (gpioWrite(gpio_pin, 0) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d LOW", gpio_pin);
    } else {
        syslog(LOG_INFO, "Motor shutdown signal deactivated (GPIO %d LOW)", gpio_pin);
    }
}

int main(void) {
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
