#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION 10
#define READ_INTERVAL 60
#define LOG_FILE "watering_events.txt"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

static void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) < 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", PUMP_GPIO);
    }
}

static void log_event(const char *event, int moisture) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - %s - Moisture: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, event, moisture);
    } else {
        fprintf(fp, "<timestamp error> - %s - Moisture: %d\n", event, moisture);
    }
    fclose(fp);
}

static void cleanup(void) {
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_pump(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            fprintf(stderr, "Sensor read error; deactivating pump and exiting.\n");
            control_pump(0);
            cleanup();
            return EXIT_FAILURE;
        }

        printf("Moisture level: %d\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold; activating pump.\n");
            control_pump(1);
            log_event("Pump activated", moisture);

            for (int i = 0; i < WATERING_DURATION && running; i++) {
                sleep(1);
            }

            control_pump(0);
            log_event("Pump deactivated", moisture);
        }

        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

