#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <getopt.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_SENSITIVITY 0.001f
#define ADS1115_VREF 4.096f
#define ADS1115_MAX_COUNT 32767.0f
#define SAMPLE_INTERVAL_US 100000
#define BLINK_DURATION_US 1000000
#define BLINK_CYCLE_US 50000

static volatile sig_atomic_t running = 1;
static float threshold = 100.0f;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (i2cWriteDevice(handle, buf, 3) < 0) {
        fprintf(stderr, "I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteDevice(handle, (char *)&reg, 1) < 0) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int ads1115_read_adc(int handle, int16_t *raw) {
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) < 0) {
        return -1;
    }
    gpioDelay(10000);
    uint16_t cfg;
    for (int i = 0; i < 10; i++) {
        if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg) < 0) {
            return -1;
        }
        if (cfg & ADS1115_CONFIG_OS_SINGLE) {
            break;
        }
        gpioDelay(10000);
    }
    uint16_t conv;
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &conv) < 0) {
        return -1;
    }
    *raw = (int16_t)conv;
    return 0;
}

static float calculate_field(int16_t raw) {
    float voltage = (raw / ADS1115_MAX_COUNT) * ADS1115_VREF;
    return voltage / ADS1115_SENSITIVITY;
}

static void blink_led(int gpio, int duration_us) {
    int on_time = duration_us / 2;
    int off_time = duration_us / 2;
    for (int i = 0; i < 20 && running; i++) {
        gpioWrite(gpio, 1);
        gpioDelay(on_time);
        gpioWrite(gpio, 0);
        gpioDelay(off_time);
    }
}

int main(int argc, char *argv[]) {
    int i2c_handle = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = (float)atof(optarg);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Threshold must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, ADS1115_ADDR, i2c_handle);
        goto cleanup_gpio;
    }

    printf("Monitoring SS49E via ADS1115 (I2C bus %d, addr 0x%02X, AIN0)...\n",
           I2C_BUS, ADS1115_ADDR);
    printf("Threshold: %.2f Gauss\n", threshold);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw;
        if (ads1115_read_adc(i2c_handle, &raw) < 0) {
            fprintf(stderr, "ADC read error; retrying in 1 s\n");
            gpioDelay(1000000);
            continue;
        }

        float field = calculate_field(raw);
        printf("Magnetic Field: %.2f Gauss\n", field);

        if (field > threshold) {
            printf("Threshold exceeded! Blinking LED.\n");
            blink_led(LED_GPIO, BLINK_DURATION_US);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup_i2c:
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
cleanup_gpio:
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    return ret;
}

