#define RELAY_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MOISTURE_THRESHOLD 30.0
#define MOISTURE_HYSTERESIS 35.0
#define MQTT_TOPIC "soil_moisture"
#define MQTT_PUMP_TOPIC "pump_control"
#define MQTT_CLIENT_ID "soil_monitor"
#define MQTT_BROKER "localhost"
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t running = 1;
static MQTTClient mqtt_client;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed on channel %d", channel);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1.0f;
    }
    return 100.0f - ((float)adc_value / 1023.0f) * 100.0f;
}

static int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO %d", RELAY_GPIO);
        return -1;
    }
    return 0;
}

static void publish_moisture(float moisture) {
    char payload[32];
