    return (adc_value / 1023.0f) * VREF;
}

static int log_data(const float voltages[NUM_CHANNELS]) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, voltages[0], voltages[1], voltages[2]) < 0) {
        fprintf(stderr, "Error writing to %s\n", LOG_FILE);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Logging MCP3008 channels 0-2 to %s every %d seconds. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (running) {
        float voltages[NUM_CHANNELS];
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int adc = 0;
            if (read_mcp3008(i, &adc) != 0) {
                fprintf(stderr, "Error reading channel %d\n", i);
                error = 1;
                break;
            }
            voltages[i] = adc_to_voltage(adc);
        }

        if (!error) {
            if (log_data(voltages) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    printf("\nShutting down...\n");

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

