            int duty_cycle = (noise_level - NOISE_THRESHOLD) * PWM_RANGE / (1023 - NOISE_THRESHOLD);
            if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
            if (duty_cycle < 0) duty_cycle = 0;

            gpioPWM(MOTOR1_GPIO, duty_cycle);
            gpioPWM(MOTOR2_GPIO, duty_cycle);
            log_event(noise_level);
        } else {
            gpioPWM(MOTOR1_GPIO, 0);
            gpioPWM(MOTOR2_GPIO, 0);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

