#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES2 0x11
#define BH1750_CONV_TIME_MS 180
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define CSV_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL_SEC 5
#define ADC_CHANNEL 0

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int fd, float *lux) {
    unsigned char cmd = BH1750_CONT_HIGH_RES2;
    if (write(fd, &cmd, 1) != 1) {
        return -1;
    }
    usleep(BH1750_CONV_TIME_MS * 1000);
    unsigned char buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    unsigned int raw = (buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_db(int adc_value) {
    if (adc_value < 0) return -100.0f;
    return 20.0f * log10f((float)adc_value + 1.0f);
}

static void log_data(FILE *fp, float sound_db, float light_lux, int error_code) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, sound_db, light_lux, error_code);
    fflush(fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C device");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        close(i2c_fd);
        return 1;
    }
    unsigned int speed = SPI_SPEED_HZ;
    unsigned char bits = 8;
    unsigned char mode = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI config");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(CSV_FILE, "a");
    if (!log_file) {
        perror("fopen CSV");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float sound_db = -100.0f;
        float light_lux = -1.0f;
        int error_code = 0;

        int adc = read_mcp3008(spi_fd, ADC_CHANNEL);
        if (adc < 0) {
            error_code = 1;
        } else {
            sound_db = adc_to_db(adc);
        }

        if (read_bh1750(i2c_fd, &light_lux) < 0) {
            error_code = 2;
        }

        log_data(log_file, sound_db, light_lux, error_code);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (log_file) fclose(log_file);
    if (spi_fd >= 0) close(spi_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

