#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30.0
#define SAMPLE_INTERVAL 60
#define MAX_RETRIES 3
#define ADC_CHANNEL 0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0f;
    }
    return 100.0f - ((float)adc_value / 1023.0f) * 100.0f;
}

static void control_pump(int on) {
    if (gpioWrite(PUMP_GPIO, on ? 1 : 0) != 0) {
        fprintf(stderr, "Failed to write GPIO%d\n", PUMP_GPIO);
    }
}

static void log_data(float moisture) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Moisture: %.2f%%\n", ts, moisture);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", PUMP_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_pump(0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc = -1;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            adc = read_mcp3008(ADC_CHANNEL);
            if (adc >= 0) break;
            fprintf(stderr, "ADC read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1) gpioDelay(100000);
        }

        if (adc < 0) {
            fprintf(stderr, "ADC read failed after %d retries, skipping cycle\n", MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL * 1000000);
            continue;
        }

        float moisture = adc_to_moisture(adc);
        if (moisture < 0.0f) {
            fprintf(stderr, "Invalid moisture conversion, skipping cycle\n");
            gpioDelay(SAMPLE_INTERVAL * 1000000);
            continue;
        }

        log_data(moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            control_pump(1);
            printf("Moisture below threshold (%.2f%% < %.2f%%), pump ON\n", moisture, MOISTURE_THRESHOLD);
        } else {
            control_pump(0);
            printf("Moisture above threshold, pump OFF\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            gpioDelay(1000000);
        }
    }

    control_pump(0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

