        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calculate_average(int s1, int s2, int s3) {
    int valid = 0, sum = 0;
    if (s1 >= 0) { sum += s1; valid++; }
    if (s2 >= 0) { sum += s2; valid++; }
    if (s3 >= 0) { sum += s3; valid++; }
    if (valid == 0) return -1;
    return sum / valid;
}

static int map_moisture_to_valve(int moisture) {
    if (moisture < 0) moisture = 0;
    if (moisture > 1023) moisture = 1023;
