    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);
    gpioPWM(PWM_PIN, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Irrigation controller started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = read_mcp3008(SOIL_SENSOR_1);
        int s2 = read_mcp3008(SOIL_SENSOR_2);
        int s3 = read_mcp3008(SOIL_SENSOR_3);

        int avg = calculate_average(s1, s2, s3);
        int valve = 0;
        if (avg >= 0) {
            valve = map_moisture_to_valve(avg);
            gpioPWM(PWM_PIN, valve);
        }

        log_data(s1, s2, s3, avg, valve);
        sleep(SAMPLE_INTERVAL);
    }

    gpioPWM(PWM_PIN, 0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    printf("Irrigation controller stopped.\n");
    return 0;
}

