#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <math.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_DEVICE "/dev/spidev0.0"
#define PWM_EXPORT_PATH "/sys/class/pwm/pwmchip0/export"
#define PWM_UNEXPORT_PATH "/sys/class/pwm/pwmchip0/unexport"
#define PWM_PERIOD_PATH "/sys/class/pwm/pwmchip0/pwm0/period"
#define PWM_DUTY_CYCLE_PATH "/sys/class/pwm/pwmchip0/pwm0/duty_cycle"
#define PWM_ENABLE_PATH "/sys/class/pwm/pwmchip0/pwm0/enable"
#define CONFIG_FILE "theremin_config.txt"

#define MAX_DISTANCE 400.0
#define MIN_DISTANCE 20.0
#define MIN_FREQUENCY 220.0
#define MAX_FREQUENCY 880.0
#define PWM_PERIOD_NS 1000000
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_DELAY 0
#define TRIG_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define SAMPLE_DELAY_US 50000

volatile sig_atomic_t program_running = 1;
FILE *config_file = NULL;
struct gpiod_chip *chip = NULL;
struct gpiod_line *trig_line = NULL;
struct gpiod_line *echo_line = NULL;
int spi_fd = -1;

typedef struct {
    float min_distance;
    float max_distance;
    float min_frequency;
    float max_frequency;
} CalibrationData;

CalibrationData calibration_data = {MIN_DISTANCE, MAX_DISTANCE, MIN_FREQUENCY, MAX_FREQUENCY};

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int write_to_file(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open file");
        return -1;
    }
    if (write(fd, value, strlen(value)) < 0) {
        perror("Failed to write to file");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int read_from_file(const char *path, char *buffer, size_t size) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open file");
        return -1;
    }
    ssize_t bytes_read = read(fd, buffer, size - 1);
    if (bytes_read < 0) {
        perror("Failed to read from file");
        close(fd);
        return -1;
    }
    buffer[bytes_read] = '\0';
    close(fd);
    return 0;
}

int init_pwm() {
    if (write_to_file(PWM_EXPORT_PATH, "0") < 0) {
        return -1;
    }
    usleep(100000);
    char period_str[32];
    snprintf(period_str, sizeof(period_str), "%d", PWM_PERIOD_NS);
    if (write_to_file(PWM_PERIOD_PATH, period_str) < 0) {
        return -1;
    }
    if (write_to_file(PWM_ENABLE_PATH, "1") < 0) {
        return -1;
    }
    return 0;
}

void cleanup_pwm() {
    if (write_to_file(PWM_ENABLE_PATH, "0") < 0) {
        fprintf(stderr, "Warning: Failed to disable PWM\n");
    }
    if (write_to_file(PWM_UNEXPORT_PATH, "0") < 0) {
        fprintf(stderr, "Warning: Failed to unexport PWM\n");
    }
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    int bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
