#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define MCP3008_CHANNEL 0
#define LOG_FILE "alcohol_log.txt"
#define PPM_THRESHOLD_HIGH 50.0
#define PPM_THRESHOLD_LOW 20.0
#define SAMPLE_INTERVAL_SEC 1
#define MAX_SPI_RETRIES 3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned char bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int init_gpio_cs(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, 8);  // GPIO8 = SPI0 CE0
    if (!cs_line) {
        fprintf(stderr, "Error getting GPIO line 8: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line 8 as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        cs_line = NULL;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((channel << 4) | 0x80), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            fprintf(stderr, "Error pulling CS low: %s\n", strerror(errno));
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);

        if (gpiod_line_set_value(cs_line, 1) < 0) {
            fprintf(stderr, "Error pulling CS high: %s\n", strerror(errno));
        }

        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n", attempt + 1, MAX_SPI_RETRIES, strerror(errno));
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        return adc_value;
    }

    fprintf(stderr, "Failed to read MCP3008 after %d attempts\n", MAX_SPI_RETRIES);
    return -1;
}

static double adc_to_ppm(int adc_value) {
    return (adc_value * 0.5) - 10.0;
}

static const char *classify_ppm(double ppm) {
    if (ppm > PPM_THRESHOLD_HIGH) {
        return "Alcohol detected! Limit exceeded.";
    } else if (ppm < PPM_THRESHOLD_LOW) {
        return "Sobriety confirmed.";
    } else {
        return "Alcohol level within acceptable range.";
    }
}

static void log_reading(double ppm, const char *classification) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Error getting UTC time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file) {
        fprintf(log_file, "%s, %.2f, %s\n", timestamp, ppm, classification);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open\n");
    }
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_spi() < 0) {
        return 1;
    }

    if (init_gpio_cs() < 0) {
        close(spi_fd);
        spi_fd = -1;
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);

        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
        } else {
            double ppm = adc_to_ppm(adc_value);

            if (adc_value == 0 || adc_value == 1023) {
                fprintf(stderr, "Warning: ADC reading at rail (%d). Sensor may be absent or disconnected.\n", adc_value);
            }

            const char *classification = classify_ppm(ppm);
            log_reading(ppm, classification);
            printf("ADC: %d, PPM: %.2f, Classification: %s\n", adc_value, ppm, classification);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

