#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor 1 GPIO pins
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2 GPIO pins
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Potentiometer ADC channels
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Speed mapping parameters
#define MIN_SPEED 50
#define MAX_SPEED 255
#define SPEED_FACTOR 1.0

// Acceleration/deceleration time (seconds)
#define ACCEL_TIME 2.0
#define PAUSE_TIME 5.0

// Global variables for cleanup
static int spi_handle = -1;
static volatile int running = 1;

// Function prototypes
int read_potentiometer(int channel);
int map_speed(int pot_value);
void motor_forward(int motor_number, int speed);
void motor_backward(int motor_number, int speed);
void motor_stop(int motor_number);
void accelerate_motor(int motor_number, int speed, double time);
void decelerate_motor(int motor_number, int speed, double time);
void reverse_directions(void);
void cleanup(void);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup function to release resources
void cleanup(void) {
    // Stop motors
    motor_stop(1);
    motor_stop(2);

    // Close SPI
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    // Terminate pigpio
    gpioTerminate();
}

// Function to read the value from the potentiometer via MCP3008 ADC
int read_potentiometer(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format (3 bytes):
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Don't care (0x00)
    unsigned char tx_buf[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx_buf[3] = {0};

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed for channel %d (returned %d)\n", channel, result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to map the potentiometer value to a motor speed
int map_speed(int pot_value) {
    if (pot_value < 0) pot_value = 0;
    if (pot_value > 1023) pot_value = 1023;

    // Logarithmic mapping for finer control at lower speeds
    double speed_factor = 1.0 + (double)pot_value / 1023.0 * (SPEED_FACTOR - 1.0);
    int speed = MIN_SPEED + (int)((MAX_SPEED - MIN_SPEED) * speed_factor);

    if (speed < MIN_SPEED) speed = MIN_SPEED;
    if (speed > MAX_SPEED) speed = MAX_SPEED;

    return speed;
}

// Function to move a motor forward
void motor_forward(int motor_number, int speed) {
    if (motor_number == 1) {
        gpioWrite(MOTOR1_DIRECTION, 1);
        gpioPWM(MOTOR1_ENABLE, speed);
    } else if (motor_number == 2) {
        gpioWrite(MOTOR2_DIRECTION, 1);
        gpioPWM(MOTOR2_ENABLE, speed);
    } else {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor_number);
    }
}

// Function to move a motor backward
void motor_backward(int motor_number, int speed) {
    if (motor_number == 1) {
        gpioWrite(MOTOR1_DIRECTION, 0);
        gpioPWM(MOTOR1_ENABLE, speed);
    } else if (motor_number == 2) {
        gpioWrite(MOTOR2_DIRECTION, 0);
        gpioPWM(MOTOR2_ENABLE, speed);
    } else {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor_number);
    }
}

// Function to stop a motor
void motor_stop(int motor_number) {
    if (motor_number == 1) {
        gpioPWM(MOTOR1_ENABLE, 0);
    } else if (motor_number == 2) {
        gpioPWM(MOTOR2_ENABLE, 0);
    } else {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor_number);
    }
}

// Function to accelerate a motor to a target speed over a given time
void accelerate_motor(int motor_number, int speed, double time) {
    double start_time = time_time();
    double elapsed = 0.0;
    int current_speed = MIN_SPEED;

    while (elapsed < time && running) {
        double dt = time_time() - start_time;
        current_speed = MIN_SPEED + (int)((MAX_SPEED - MIN_SPEED) * (dt / time));
        if (current_speed > speed) current_speed = speed;

        if (motor_number == 1) {
            gpioPWM(MOTOR1_ENABLE, current_speed);
        } else if (motor_number == 2) {
            gpioPWM(MOTOR2_ENABLE, current_speed);
        }

        gpioDelay(10000); // 10ms delay for smooth acceleration
        elapsed = time_time() - start_time;
    }
}

// Function to decelerate a motor to a target speed over a given time
void decelerate_motor(int motor_number, int speed, double time) {
    double start_time = time_time();
    double elapsed = 0.0;
    int current_speed = MAX_SPEED;

    while (elapsed < time && running) {
        double dt = time_time() - start_time;
        current_speed = MAX_SPEED - (int)((MAX_SPEED - MIN_SPEED) * (dt / time));
        if (current_speed < speed) current_speed = speed;

        if (motor_number == 1) {
            gpioPWM(MOTOR1_ENABLE, current_speed);
        } else if (motor_number == 2) {
            gpioPWM(MOTOR2_ENABLE, current_speed);
        }

        gpioDelay(10000); // 10ms delay for smooth deceleration
        elapsed = time_time() - start_time;
    }
}

// Function to reverse the direction of both motors
void reverse_directions(void) {
    gpioWrite(MOTOR1_DIRECTION, 0);
    gpioWrite(MOTOR2_DIRECTION, 1);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (running) {
        // Read potentiometer values
        int pot1_value = read_potentiometer(POT1_CHANNEL);
        int pot2_value = read_potentiometer(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Failed to read potentiometer values\n");
            gpioDelay(100000); // 100ms delay before retry
            continue;
        }

        // Map potentiometer values to motor speeds
        int speed1 = map_speed(pot1_value);
        int speed2 = map_speed(pot2_value);

        // Accelerate motors forward
        motor_forward(1, speed1);
        motor_forward(2, speed2);
        accelerate_motor(1, speed1, ACCEL_TIME);
        accelerate_motor(2, speed2, ACCEL_TIME);

        // Hold speed for 2 seconds
        gpioDelay(2000000); // 2 seconds

        // Decelerate motors
        decelerate_motor(1, speed1, ACCEL_TIME);
        decelerate_motor(2, speed2, ACCEL_TIME);

        // Stop motors
        motor_stop(1);
        motor_stop(2);

        // Pause for 5 seconds
        gpioDelay(PAUSE_TIME * 1000000); // 5 seconds

        // Reverse directions
        reverse_directions();

        // Accelerate motors backward
        motor_backward(1, speed1);
        motor_backward(2, speed2);
        accelerate_motor(1, speed1, ACCEL_TIME);
        accelerate_motor(2, speed2, ACCEL_TIME);

        // Hold speed for 2 seconds
        gpioDelay(2000000); // 2 seconds

        // Decelerate motors
        decelerate_motor(1, speed1, ACCEL_TIME);
        decelerate_motor(2, speed2, ACCEL_TIME);

        // Stop motors
        motor_stop(1);
        motor_stop(2);

        // Pause for 5 seconds
        gpioDelay(PAUSE_TIME * 1000000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

