#define DEBOUNCE_US 10000
#define CALIBRATION_SAMPLES 500
#define CALIBRATION_DURATION_US 5000000
#define THRESHOLD_PERCENT 10

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calibrate_ambient(void) {
    long sum = 0;
    int valid_samples = 0;

    printf("Calibrating ambient noise for %d samples...\n", CALIBRATION_SAMPLES);

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int val = read_adc(ADC_CHANNEL);
        if (val >= 0) {
            sum += val;
            valid_samples++;
        } else {
            fprintf(stderr, "Error reading ADC during calibration (sample %d)\n", i);
        }
        gpioDelay(1000);
