#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0
#define ADC_CHANNEL     0
#define SAMPLE_RATE_HZ  1000
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_RATE_HZ)
#define LOG_FILE        "audio_log.txt"
#define GPIO_CHIP_NAME  "gpiochip0"
#define CS_LINE_OFFSET  8  /* GPIO8 = CE0 on RPi Zero W */

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;
static struct gpiod_line_request *g_cs_req = NULL;
static struct gpiod_chip *g_chip = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int setup_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int setup_spi(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int setup_gpio_cs(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(g_chip, CS_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    struct gpiod_line_request_config config = {
        .consumer = "mcp3008-cs",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .flags = 0,
    };
    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    g_cs_req = gpiod_line_request_current(line);
    if (!g_cs_req) {
        perror("gpiod_line_request_current");
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    /* Ensure CS is high before we start */
    if (gpiod_line_request_set_value(g_cs_req, GPIOD_LINE_VALUE_ACTIVE) < 0) {
        perror("gpiod_line_request_set_value");
        gpiod_line_release(g_cs_req);
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        g_cs_req = NULL;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0,
    };

    /* Manually drive CS low */
    if (gpiod_line_request_set_value(g_cs_req, GPIOD_LINE_VALUE_INACTIVE) < 0) {
        perror("gpiod_line_request_set_value (low)");
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        gpiod_line_request_set_value(g_cs_req, GPIOD_LINE_VALUE_ACTIVE);
        return -1;
    }

    /* Manually drive CS high */
    if (gpiod_line_request_set_value(g_cs_req, GPIOD_LINE_VALUE_ACTIVE) < 0) {
        perror("gpiod_line_request_set_value (high)");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_audio_sample(FILE *fp, long timestamp_ns, int adc_value)
{
    if (fprintf(fp, "%ld|%d\n", timestamp_ns, adc_value) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_cs_req) {
        gpiod_line_request_release(g_cs_req);
        g_cs_req = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

int main(void)
{
    if (setup_signal_handlers() < 0) {
        return EXIT_FAILURE;
    }

    if (setup_spi() < 0) {
        return EXIT_FAILURE;
    }

    if (setup_gpio_cs() < 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "w");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    struct timespec next_sample;
    clock_gettime(CLOCK_MONOTONIC_RAW, &next_sample);

    while (g_running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC_RAW, &now);

        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; continuing\n");
            next_sample.tv_nsec += SAMPLE_PERIOD_NS;
            if (next_sample.tv_nsec >= 1000000000L) {
                next_sample.tv_nsec -= 1000000000L;
                next_sample.tv_sec++;
            }
            nanosleep(&next_sample, NULL);
            continue;
        }

        long timestamp_ns = (long)now.tv_sec * 1000000000L + now.tv_nsec;

        if (log_audio_sample(g_log_fp, timestamp_ns, adc_value) < 0) {
            fprintf(stderr, "Logging failed; aborting\n");
            break;
        }

        next_sample.tv_nsec += SAMPLE_PERIOD_NS;
        if (next_sample.tv_nsec >= 1000000000L) {
            next_sample.tv_nsec -= 1000000000L;
            next_sample.tv_sec++;
        }
        nanosleep(&next_sample, NULL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

