    while (!terminate) {
        // Read ADC values from MCP3008
        int adc_x = read_mcp3008(0);
        int adc_y = read_mcp3008(1);
        int adc_z = read_mcp3008(2);

        if (adc_x < 0 || adc_y < 0 || adc_z < 0) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            break;
        }

        // Convert ADC values to voltages
        float voltage_x = adc_to_voltage(adc_x);
        float voltage_y = adc_to_voltage(adc_y);
        float voltage_z = adc_to_voltage(adc_z);

        // Convert voltages to acceleration (g)
        float acceleration_x = voltage_to_acceleration(voltage_x);
        float acceleration_y = voltage_to_acceleration(voltage_y);
        float acceleration_z = voltage_to_acceleration(voltage_z);

        // Apply Kalman filter
        kalman_filter_update(&kalman_x, acceleration_x);
        kalman_filter_update(&kalman_y, acceleration_y);
        kalman_filter_update(&kalman_z, acceleration_z);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", kalman_x.angle, kalman_y.angle, kalman_z.angle);

        // Delay for 100ms (10 Hz)
        gpioDelay(100000); // 100ms in microseconds
    }

    // Clean up resources
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("\nProgram terminated gracefully.\n");
    return 0;
}

