#include <errno.h>
#include <gpiod.h>

#define GPIO4 4
#define GPIO17 17
#define GPIO27 27
#define VCC 3.3
#define V_QUIESCENT (VCC / 2.0)
#define SENSITIVITY 0.025
#define MIN_FIELD -100.0
#define MAX_FIELD 100.0
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(FILE *fp, float s1, float s2, float s3) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, s1, s2, s3) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line4 = NULL, *line17 = NULL, *line27 = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line4 = gpiod_chip_get_line(chip, GPIO4);
    line17 = gpiod_chip_get_line(chip, GPIO17);
    line27 = gpiod_chip_get_line(chip, GPIO27);
    if (!line4 || !line17 || !line27) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line4, "drv5055va") < 0 ||
        gpiod_line_request_input(line17, "drv5055va") < 0 ||
        gpiod_line_request_input(line27, "drv5055va") < 0) {
        fprintf(stderr, "Failed to request GPIO lines as input: %s\n", strerror(errno));
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Logging DRV5055VA sensor data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        int v4 = gpiod_line_get_value(line4);
        int v17 = gpiod_line_get_value(line17);
        int v27 = gpiod_line_get_value(line27);

        if (v4 < 0 || v17 < 0 || v27 < 0) {
            fprintf(stderr, "Error reading GPIO values: %s\n", strerror(errno));
            goto sleep_and_continue;
        }

        float s1 = (v4 == 1) ? (VCC - V_QUIESCENT) : 0.0;
        float s2 = (v17 == 1) ? (VCC - V_QUIESCENT) : 0.0;
        float s3 = (v27 == 1) ? (VCC - V_QUIESCENT) : 0.0;

        float f1 = s1 / SENSITIVITY;
        float f2 = s2 / SENSITIVITY;
        float f3 = s3 / SENSITIVITY;

        if (f1 < MIN_FIELD || f1 > MAX_FIELD) {
            fprintf(stderr, "Warning: Sensor 1 field %.3f mT out of range\n", f1);
        }
        if (f2 < MIN_FIELD || f2 > MAX_FIELD) {
            fprintf(stderr, "Warning: Sensor 2 field %.3f mT out of range\n", f2);
        }
        if (f3 < MIN_FIELD || f3 > MAX_FIELD) {
            fprintf(stderr, "Warning: Sensor 3 field %.3f mT out of range\n", f3);
        }

        if (log_data(fp, f1, f2, f3) != 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

    sleep_and_continue:
        struct timespec ts = {0, SAMPLE_INTERVAL_MS * 1000000L};
        nanosleep(&ts, NULL);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (line4) gpiod_line_release(line4);
    if (line17) gpiod_line_release(line17);
    if (line27) gpiod_line_release(line27);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

