#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define PUMP_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MOISTURE_THRESHOLD 30.0
#define LOG_FILE "watering.log"
#define CHECK_INTERVAL 60

static volatile int running = 1;
static int spi_handle = -1;

void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "[%s] %s\n", timestamp, message);
    fclose(fp);
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Invalid MCP3008 channel");
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        log_event("SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) return -1.0;
    return (float)adc_value / 1023.0 * 100.0;
}

void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    char msg[64];
    snprintf(msg, sizeof(msg), "Pump %s", state ? "ON" : "OFF");
    log_event(msg);
}

void cleanup() {
    control_pump(0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    log_event("Program terminated");
}

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    log_event("Program started");

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    control_pump(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        log_event("SPI open failed");
        cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            log_event("ADC read error, skipping cycle");
        } else {
            float moisture = calculate_moisture(adc);
            if (moisture < 0) {
                log_event("Invalid moisture calculation");
            } else {
                char msg[128];
                snprintf(msg, sizeof(msg), "Moisture: %.2f%% (ADC: %d)", moisture, adc);
                log_event(msg);
                if (moisture < MOISTURE_THRESHOLD) {
                    control_pump(1);
                } else {
                    control_pump(0);
                }
            }
        }
        sleep(CHECK_INTERVAL);
    }

    cleanup();
    return 0;
}

