        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)(0x80 | (channel << 4)), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int log_data(int ch0, int ch1, int ch2) {
    if (fprintf(log_file, "%d,%d,%d\n", ch0, ch1, ch2) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    log_file = fopen("sensor_data.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    if (fprintf(log_file, "timestamp,ch0,ch1,ch2\n") < 0) {
        fprintf(stderr, "Error writing CSV header: %s\n", strerror(errno));
        fclose(log_file);
        close(spi_fd);
        return 1;
    }

    while (running) {
        int ch0 = read_mcp3008(0);
        int ch1 = read_mcp3008(1);
        int ch2 = read_mcp3008(2);

        if (ch0 < 0 || ch1 < 0 || ch2 < 0) {
            fprintf(stderr, "Error reading ADC values, exiting.\n");
            break;
        }

        if (log_data(ch0, ch1, ch2) < 0) {
            break;
        }

        sleep(LOG_INTERVAL_SEC);
    }

    if (log_file) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return 0;
}

