#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER_ADDRESS "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define LED_GPIO 17
#define MAX_RECONNECT_DELAY 60
#define MAX_PAYLOAD_SIZE 512

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker.\n");
        int rc = mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic");
        }
    } else {
        log_error("MQTT connection failed");
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m;
    (void)userdata;
    if (rc == 0) {
        printf("Disconnected from MQTT broker.\n");
    } else {
        log_error("Unexpected MQTT disconnection");
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;
    if (message->payloadlen > 0 && message->payloadlen <= MAX_PAYLOAD_SIZE) {
        char *payload = (char *)message->payload;
        if (message->payloadlen >= 2 && payload[0] == '{' && payload[message->payloadlen - 1] == '}') {
            char *json_string = payload;
            cJSON *json = cJSON_Parse(json_string);
            if (json == NULL) {
                log_error("Failed to parse JSON payload");
                return;
            }
            cJSON *led_state = cJSON_GetObjectItemCaseSensitive(json, "led_state");
            if (led_state == NULL || !cJSON_IsBool(led_state)) {
                log_error("Invalid JSON payload: missing or non-boolean led_state");
                cJSON_Delete(json);
                return;
            }
            int state = led_state->valueint;
            if (gpioWrite(LED_GPIO, state) != 0) {
                log_error("Failed to write to GPIO");
            } else {
                printf("LED set to %s\n", state ? "ON" : "OFF");
            }
            cJSON_Delete(json);
        } else {
            log_error("Invalid JSON format: must be a JSON object");
        }
    } else {
        log_error("Invalid payload length");
    }
}

static int connect_mqtt(void) {
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (mosq == NULL) {
        log_error("Failed to create MQTT client");
        return -1;
    }
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);
    int rc = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (connect_mqtt() != 0) {
        gpioTerminate();
        return 1;
    }
    int reconnect_delay = 1;
    while (running) {
        int rc = mosquitto_loop_start(mosq);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to start MQTT loop");
            break;
        }
        while (running) {
            rc = mosquitto_loop(mosq, 100, 1);
            if (rc != MOSQ_ERR_SUCCESS) {
                log_error("MQTT loop error");
                break;
            }
        }
        mosquitto_loop_stop(mosq, false);
        if (!running) break;
        log_error("MQTT connection lost, attempting reconnection...");
        int delay = reconnect_delay;
        while (running && delay <= MAX_RECONNECT_DELAY) {
            sleep(delay);
            if (connect_mqtt() == 0) {
                reconnect_delay = 1;
                break;
            }
            delay *= 2;
        }
        if (delay > MAX_RECONNECT_DELAY) {
            log_error("Max reconnection delay reached, exiting");
            running = 0;
        }
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

