#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN    18
#define CHIP_NAME        "gpiochip4"
#define CONSUMER         "sound_alarm"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the sound sensor line (input) */
    sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_line) {
        perror("gpiod_chip_get_line (sound)");
        goto cleanup;
    }

    /* Get the alarm LED line (output) */
    led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (led)");
        goto cleanup;
    }

    /* Request sound sensor line as input */
    if (gpiod_line_request_input(sound_line, CONSUMER) < 0) {
        perror("gpiod_line_request_input (sound)");
        goto cleanup;
    }

    /* Request alarm LED line as output, initial value LOW */
    if (gpiod_line_request_output(led_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (led)");
        goto cleanup;
    }

    printf("Sound sensor alarm system started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_level = gpiod_line_get_value(sound_line);
        if (sound_level < 0) {
            perror("gpiod_line_get_value (sound)");
            break;
        }

        printf("Sound level: %d\n", sound_level);

        if (sound_level == 0) {
            /* Sound detected: blink LED for 1 second */
            if (gpiod_line_set_value(led_line, 1) < 0) {
                perror("gpiod_line_set_value (led on)");
                break;
            }
            sleep(1);
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value (led off)");
                break;
            }
        }

        usleep(100000); /* 100 ms delay */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure LED is off on exit */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sound_line) {
        gpiod_line_release(sound_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return ret;
}

