#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_REG 0xE0
#define BMP280_RESET_CMD 0xB6
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_PRESS_MSB_REG 0xF7
#define BMP280_TEMP_MSB_REG 0xFA
#define BMP280_CALIB_START 0x88
#define BMP280_CALIB_LEN 24
#define SEA_LEVEL_PRESSURE 101325.0
#define LOG_FILE "altitude_log.txt"
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static bmp280_calib_t cal;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(int handle) {
    uint8_t buf[BMP280_CALIB_LEN];
    if (i2cReadI2CBlockData(handle, BMP280_CALIB_START, (char *)buf, BMP280_CALIB_LEN) != BMP280_CALIB_LEN) {
        fprintf(stderr, "Error: Failed to read calibration block\n");
        return -1;
    }
    cal.dig_T1 = (uint16_t)(buf[1] << 8 | buf[0]);
    cal.dig_T2 = (int16_t)(buf[3] << 8 | buf[2]);
    cal.dig_T3 = (int16_t)(buf[5] << 8 | buf[4]);
    cal.dig_P1 = (uint16_t)(buf[7] << 8 | buf[6]);
    cal.dig_P2 = (int16_t)(buf[9] << 8 | buf[8]);
    cal.dig_P3 = (int16_t)(buf[11] << 8 | buf[10]);
    cal.dig_P4 = (int16_t)(buf[13] << 8 | buf[12]);
    cal.dig_P5 = (int16_t)(buf[15] << 8 | buf[14]);
    cal.dig_P6 = (int16_t)(buf[17] << 8 | buf[16]);
    cal.dig_P7 = (int16_t)(buf[19] << 8 | buf[18]);
    cal.dig_P8 = (int16_t)(buf[21] << 8 | buf[20]);
    cal.dig_P9 = (int16_t)(buf[23] << 8 | buf[22]);
    return 0;
}

static int32_t compensate_temperature(int32_t adc_T) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)cal.dig_T1 << 1))) * ((int32_t)cal.dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)cal.dig_T1)) * ((adc_T >> 4) - ((int32_t)cal.dig_T1))) >> 12) * ((int32_t)cal.dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P) {
    int32_t var1, var2;
    uint32_t p;
    var1 = ((int32_t)t_fine >> 1) - 64000;
    var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)cal.dig_P6);
    var2 = var2 + ((var1 * ((int32_t)cal.dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)cal.dig_P4) << 16);
    var1 = (((((var1 >> 2) * (var1 >> 2)) >> 13) * ((int32_t)cal.dig_P3)) >> 3) + ((((int32_t)cal.dig_P2) * var1) >> 1);
    var1 = (((32768 + var1)) * ((int32_t)cal.dig_P1)) >> 15;
    if (var1 == 0) return 0;
    p = (((uint32_t)(((1 << 31) - adc_P) - (var2 >> 12))) * 6250);
    p = (p << 1) / ((uint32_t)var1);
    var1 = (((int32_t)cal.dig_P9) * (int32_t)((p >> 3) * (p >> 3))) >> 13;
    var2 = (((int32_t)(p >> 2)) * ((int32_t)cal.dig_P8)) >> 13;
    p = (uint32_t)((int32_t)p + ((var1 + var2 + ((int32_t)cal.dig_P7)) >> 4));
    return p;
}

static double calculate_altitude(uint32_t pressure_pa) {
    return 44330.0 * (1.0 - pow((double)pressure_pa / SEA_LEVEL_PRESSURE, 0.1903));
}

static int read_raw_data(int handle, int32_t *raw_temp, int32_t *raw_press) {
    uint8_t buf[6];
    if (i2cReadI2CBlockData(handle, BMP280_PRESS_MSB_REG, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read raw data\n");
        return -1;
    }
    *raw_press = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | ((int32_t)buf[2] >> 4);
    *raw_temp = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | ((int32_t)buf[5] >> 4);
    return 0;
}

static int log_data(double altitude) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    if (fprintf(log_file, "%s, %.2f\n", timestamp, altitude) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", BMP280_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    int chip_id = i2cReadByteData(i2c_handle, BMP280_CHIP_ID_REG);
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X). Sensor not present.\n", chip_id, BMP280_CHIP_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, BMP280_RESET_REG, BMP280_RESET_CMD) < 0) {
        fprintf(stderr, "Error: Failed to reset BMP280\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(2000);

    if (read_calibration(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, BMP280_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write config register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, BMP280_CTRL_MEAS_REG, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write ctrl_meas register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int32_t raw_temp, raw_press;
        if (read_raw_data(i2c_handle, &raw_temp, &raw_press) == 0) {
            int32_t temp_comp = compensate_temperature(raw_temp);
            uint32_t press_comp = compensate_pressure(raw_press);
            double altitude = calculate_altitude(press_comp);
            if (log_data(altitude) != 0) {
                fprintf(stderr, "Warning: Logging failed, continuing\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, retrying next cycle\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    fprintf(stderr, "Shutting down cleanly...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

