#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define VREF 3.3
#define ADC_MAX 1023.0
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"
#define SAMPLE_INTERVAL 5

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_temperature(int adc_value) {
    float voltage = (float)adc_value / ADC_MAX * VREF;
    return voltage * 100.0f;
}

static void log_temperature(float temperature, int index, float *buffer) {
    buffer[index] = temperature;
    printf("Temperature: %.2f °C\n", temperature);
}

static int write_buffer_to_file(const float *buffer, int size, const char *filename) {
    FILE *fp = fopen(filename, "wb+");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    size_t written = fwrite(buffer, sizeof(float), size, fp);
    fclose(fp);
    if (written != (size_t)size) {
        fprintf(stderr, "Short write to %s\n", filename);
        return -1;
    }
