#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define I2C_DEVICE "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "environmental_log.txt"
#define SAMPLE_INTERVAL 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int fd) {
    unsigned char cmd = BH1750_CONT_HIGH_RES;
    if (write(fd, &cmd, 1) != 1) {
        return -1;
    }
    usleep(180000);
    unsigned char buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_data(FILE *fp, int light, int sound) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Light: %d lux, Sound: %d\n", timestamp, light, sound);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        close(i2c_fd);
        return 1;
    }
    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }
    unsigned char mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }
    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        int light = read_bh1750(i2c_fd);
        int sound = read_mcp3008(spi_fd, MCP3008_CHANNEL);

        if (light < 0) {
            fprintf(stderr, "Error reading light sensor: %s\n", strerror(errno));
        } else if (sound < 0) {
            fprintf(stderr, "Error reading sound sensor: %s\n", strerror(errno));
        } else {
            log_data(fp, light, sound);
        }

        sleep(SAMPLE_INTERVAL);
    }

    fclose(fp);
    close(spi_fd);
    close(i2c_fd);
    return 0;
}

