#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNELS 3
#define SLEEP_INTERVAL 60
#define LOG_FILE "soil_data.txt"

static int spi_handle = -1;
static FILE *log_file = NULL;

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0f;
    }
    return (1.0f - (float)adc_value / 1023.0f) * 100.0f;
}

static void log_data(float moisture1, float moisture2, float moisture3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor 1: %.2f%%, Sensor 2: %.2f%%, Sensor 3: %.2f%%\n",
            timestamp, moisture1, moisture2, moisture3);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    cleanup();
    exit(0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        int adc1 = read_mcp3008(0);
        int adc2 = read_mcp3008(1);
        int adc3 = read_mcp3008(2);

        float moisture1 = calculate_moisture(adc1);
        float moisture2 = calculate_moisture(adc2);
        float moisture3 = calculate_moisture(adc3);

        if (moisture1 < 0.0f || moisture2 < 0.0f || moisture3 < 0.0f) {
            fprintf(stderr, "Error reading sensor data, skipping log\n");
        } else {
            log_data(moisture1, moisture2, moisture3);
        }

        gpioDelay(SLEEP_INTERVAL * 1000000);
    }

    cleanup();
    return 0;
}

