#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define RELAY_ON_TIME_MS 1000
#define RELAY_OFF_DELAY_MS 1000

static const unsigned int relay_pins[NUM_RELAYS] = {17, 22, 23, 24};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS];
static volatile sig_atomic_t keep_running = 1;

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 0);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", relay_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(relay_lines[i], "relay-seq", 0) < 0) {
            fprintf(stderr, "Failed to request output on GPIO %u\n", relay_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    while (keep_running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (!keep_running) break;
            if (gpiod_line_set_value(relay_lines[i], 1) < 0) {
                perror("gpiod_line_set_value HIGH");
                cleanup();
                return EXIT_FAILURE;
            }
            usleep(RELAY_ON_TIME_MS * 1000);
            if (!keep_running) break;
            if (gpiod_line_set_value(relay_lines[i], 0) < 0) {
                perror("gpiod_line_set_value LOW");
                cleanup();
                return EXIT_FAILURE;
            }
            if (i < NUM_RELAYS - 1) {
                usleep(RELAY_OFF_DELAY_MS * 1000);
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

