#define LED_PIN 16
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SOUND_THRESHOLD 500
#define DEBOUNCE_DELAY_MS 500
#define LED_ON_DURATION_MS 500
#define SAMPLE_INTERVAL_US 10000

static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
