#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27
#define PWM_RANGE 255
#define PWM_DUTY 150
#define RAIN_THRESHOLD 5
#define MOTOR_RUN_TIME 3
#define LOG_FILE "rain_log.txt"

static volatile sig_atomic_t program_running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int convert_adc_to_rain_level(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return (int)(((float)adc_value / 1023.0f) * 10.0f);
}

static void log_rain_level(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not open\n");
        return;
    }

    if (fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file\n");
    }
}

static void control_motor(int direction) {
    if (gpioWrite(MOTOR_IN1, direction == 1 ? 1 : 0) != 0) {
        fprintf(stderr, "Error: Failed to write IN1\n");
    }
    if (gpioWrite(MOTOR_IN2, direction == 1 ? 0 : 1) != 0) {
        fprintf(stderr, "Error: Failed to write IN2\n");
    }
    if (gpioPWM(MOTOR_ENA, PWM_DUTY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM\n");
    }
}

static void stop_motor(void) {
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);
}

static void cleanup(void) {
    stop_motor();
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int rain_level;
    int motor_state = 0; /* 0 = open, 1 = closed */

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_ENA, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set motor GPIO modes\n");
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(MOTOR_ENA, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(RAIN_SENSOR_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read rain sensor\n");
            sleep(1);
            continue;
        }

        rain_level = convert_adc_to_rain_level(adc_value);
        if (rain_level < 0) {
            fprintf(stderr, "Error: Failed to convert ADC value\n");
            sleep(1);
            continue;
        }

        log_rain_level(rain_level);

        if (rain_level >= RAIN_THRESHOLD) {
            if (motor_state == 0) {
                printf("Rain detected! Closing window...\n");
                control_motor(1);
                sleep(MOTOR_RUN_TIME);
                stop_motor();
                motor_state = 1;
            }
        } else {
            if (motor_state == 1) {
                printf("Rain stopped! Opening window...\n");
                control_motor(0);
                sleep(MOTOR_RUN_TIME);
                stop_motor();
                motor_state = 0;
            }
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

