#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define DISTANCE_THRESHOLD 200.0
#define A 26.0
#define B -6.0

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_gpio_value(int pin) {
    char path[64];
    char value_str[4];
    int value;
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening GPIO %d value: %s\n", pin, strerror(errno));
        return -1;
    }

    if (fgets(value_str, sizeof(value_str), fp) == NULL) {
        fprintf(stderr, "Error reading GPIO %d value: %s\n", pin, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    value = atoi(value_str);
    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO %d value: %d\n", pin, value);
        return -1;
