#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "gpiochip0"
#define CS_LINE_OFFSET  8
#define MCP3008_CHANNEL 0
#define VREF_MV         3300
#define ADC_MAX         1023
#define DRV5055_SENS_MT 100.0f
#define DRV5055_VCC_MV  1650.0f
#define LOG_FILE        "magnetic_log.txt"
#define SAMPLE_MS       500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int read_mcp3008(int fd, struct gpiod_line *cs_line, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS: %s\n", strerror(errno));
        return -1;
    }

    if (spi_transfer(fd, tx, rx, sizeof(tx)) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS: %s\n", strerror(errno));
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | rx[2];
    return adc;
}

static float calculate_magnetic_field(int adc_value) {
    int vout_mv = (adc_value * VREF_MV) / ADC_MAX;
    int field_mt = (vout_mv - (int)DRV5055_VCC_MV) / (int)DRV5055_SENS_MT;
    return (float)field_mt;
}

static void log_data(FILE *fp, float magnetic_field) {
    time_t now = time(NULL);
    if (fprintf(fp, "%ld,%.2f\n", (long)now, magnetic_field) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    printf("Starting magnetic field logging. Press Ctrl+C to stop.\n");

    while (g_running) {
        int adc_value = read_mcp3008(spi_fd, cs_line, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, skipping sample.\n");
        } else {
            float magnetic_field = calculate_magnetic_field(adc_value);
            log_data(log_fp, magnetic_field);
            printf("Magnetic Field: %.2f mT\n", magnetic_field);
        }
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nExiting gracefully.\n");
    fclose(log_fp);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    return 0;
}

