#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Configuration */
#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 channel 0 (single-ended) */
#define VREF           5.0        /* MCP3008 VDD = 5 V */
#define ADC_MAX        1023       /* 10-bit ADC */
#define VZERO          2.5        /* MLX91211 output at 0 A (VDD/2) */
#define VFULL          5.0        /* MLX91211 output at +50 A (VDD) */
#define IFULL          50.0       /* Full-scale current (+50 A) */
#define LOG_FILE       "current_log.txt"
#define SAMPLE_US      100000     /* 100 ms between samples */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7)                             */
/* Returns 0-1023 on success, -1 on SPI error                          */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI command: start bit, single-ended + channel, then don't-care */
    unsigned char tx[3] = {
        0x01,                       /* start bit */
        (unsigned char)(0x80 | (channel << 4)), /* single-ended + channel */
        0x00                        /* clock out remaining bits */
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert raw ADC code to current (A)                                 */
/* ------------------------------------------------------------------ */
static double adc_to_current(int adc_value)
{
    double voltage = ((double)adc_value / (double)ADC_MAX) * VREF;
    double current = (voltage - VZERO) * (IFULL / (VFULL - VZERO));
    return current;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped current reading to the log file                */
/* ------------------------------------------------------------------ */
static void log_current(double current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return;
    }
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 (CE0) at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Current monitoring started. Logging to '%s'. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* Main sampling loop */
    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            /* SPI error — skip this sample, keep running */
            gpioDelay(SAMPLE_US);
            continue;
        }

        double current = adc_to_current(adc_value);

        /* Sanity-check voltage range */
        double voltage = ((double)adc_value / (double)ADC_MAX) * VREF;
        if (voltage < 0.0 || voltage > VREF) {
            fprintf(stderr, "Warning: voltage %.2f V out of range [0, %.1f V]; skipping\n",
                    voltage, VREF);
            gpioDelay(SAMPLE_US);
            continue;
        }

        log_current(current);
        gpioDelay(SAMPLE_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

