#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_MS 2
#define POLL_INTERVAL_S 1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(struct gpiod_line *line) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
            return -1;
        }
        if (val == 0) low_count++;
        if (i < DEBOUNCE_SAMPLES - 1) usleep(DEBOUNCE_DELAY_MS * 1000);
    }
    return (low_count > DEBOUNCE_SAMPLES / 2) ? 0 : 1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line (sensor1)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line (sensor2)");
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "b5w_sensor1") < 0) {
        perror("gpiod_line_request_input (sensor1)");
        goto cleanup;
    }
    if (gpiod_line_request_input(line2, "b5w_sensor2") < 0) {
        perror("gpiod_line_request_input (sensor2)");
        goto cleanup;
    }

    printf("Monitoring Omron B5W-DB01 sensors on GPIO%d and GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR1_PIN, SENSOR2_PIN);

    while (running) {
        int s1 = read_sensor(line1);
        int s2 = read_sensor(line2);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error; exiting.\n");
            goto cleanup;
        }

        printf("Sensor 1: %d, Sensor 2: %d\n", s1, s2);
        if (s1 == 0 && s2 == 0) {
            printf("ALERT: Both sensors detect object\n");
        }
        fflush(stdout);
        sleep(POLL_INTERVAL_S);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

