#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define DEBOUNCE_DELAY_MS 200
#define POLL_INTERVAL_US 50000
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define IMAGE_DIR "/home/pi/security_cam"
#define LOG_FILE "/var/log/security_cam.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        syslog(LOG_ERR, "Path '%s' exists but is not a directory", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        syslog(LOG_ERR, "mkdir('%s') failed: %m", path);
        return -1;
    }
    return 0;
}

static int capture_image(void) {
    char filename[256];
    char command[512];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        syslog(LOG_ERR, "localtime() failed");
        return -1;
    }

    if (strftime(filename, sizeof(filename), IMAGE_DIR "/%Y%m%d_%H%M%S.jpg", timeinfo) == 0) {
        syslog(LOG_ERR, "strftime() failed to format filename");
        return -1;
    }

    if (ensure_directory(IMAGE_DIR) != 0) {
        syslog(LOG_ERR, "Failed to ensure image directory: %s", IMAGE_DIR);
        return -1;
    }

    snprintf(command, sizeof(command),
             "libcamera-still -o %s --width %d --height %d --nopreview --timeout 1000",
             filename, IMAGE_WIDTH, IMAGE_HEIGHT);

    syslog(LOG_INFO, "Capturing image: %s", filename);

    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %m");
        return -1;
    }

    if (pid == 0) {
        execvp("libcamera-still", (char *[]){ "libcamera-still", "-o", filename, "--width", "-1", "--height", "-1", "--nopreview", "--timeout", "1000", NULL });
        syslog(LOG_ERR, "execvp(libcamera-still) failed: %m");
        _exit(127);
    }

    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR) continue;
        syslog(LOG_ERR, "waitpid() failed: %m");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        syslog(LOG_INFO, "Image captured successfully: %s", filename);
        return 0;
    }

    syslog(LOG_ERR, "libcamera-still failed (exit status: %d)", WIFEXITED(status) ? WEXITSTATUS(status) : -1);
    return -1;
}

int main(void) {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction() failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_INPUT) failed", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Security camera system started (PIR on BCM GPIO%d)", PIR_GPIO);

    int last_state = gpioRead(PIR_GPIO);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial gpioRead(%d) failed", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead(%d) failed", PIR_GPIO);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            current_state = gpioRead(PIR_GPIO);
            if (current_state < 0) {
                syslog(LOG_ERR, "gpioRead(%d) failed during debounce", PIR_GPIO);
                continue;
            }

            if (current_state == last_state) {
                syslog(LOG_INFO, "Motion detected on BCM GPIO%d", PIR_GPIO);
                if (capture_image() != 0) {
                    syslog(LOG_ERR, "Failed to capture image");
                }
            }
            last_state = current_state;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down security camera system");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

