#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define NUM_BUFFERS 4
#define LOG_FILE "frame_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd, struct v4l2_format *fmt, struct v4l2_requestbuffers *reqbufs,
                       struct v4l2_buffer *buf, void **buffers, size_t *buffer_size) {
    *fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (*fd < 0) {
        perror("Cannot open video device");
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, fmt) < 0) {
        perror("VIDIOC_QUERYCAP failed");
        close(*fd);
        *fd = -1;
        return -1;
    }

    if (!(fmt->capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", VIDEO_DEVICE);
        close(*fd);
        *fd = -1;
        return -1;
    }

    if (!(fmt->capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", VIDEO_DEVICE);
        close(*fd);
        *fd = -1;
        return -1;
    }

    memset(buf, 0, sizeof(*buf));
    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_S_FMT, fmt) < 0) {
        perror("VIDIOC_S_FMT failed");
        close(*fd);
        *fd = -1;
        return -1;
    }

    if (fmt->fmt.pix.width < FRAME_WIDTH || fmt->fmt.pix.height < FRAME_HEIGHT) {
        fprintf(stderr, "Warning: requested resolution %dx%d not supported, using %ux%u\n",
                FRAME_WIDTH, FRAME_HEIGHT, fmt->fmt.pix.width, fmt->fmt.pix.height);
    }

    memset(reqbufs, 0, sizeof(*reqbufs));
    reqbufs->count = NUM_BUFFERS;
    reqbufs->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    reqbufs->memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, reqbufs) < 0) {
        perror("VIDIOC_REQBUFS failed");
        close(*fd);
        *fd = -1;
        return -1;
    }

    for (int i = 0; i < reqbufs->count; i++) {
        memset(buf, 0, sizeof(*buf));
        buf->index = i;
        buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf->memory = V4L2_MEMORY_MMAP;

        if (xioctl(*fd, VIDIOC_QUERYBUF, buf) < 0) {
            perror("VIDIOC_QUERYBUF failed");
            close(*fd);
            *fd = -1;
            return -1;
        }

        if (mmap(NULL, buf->length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf->m.offset) == MAP_FAILED) {
            perror("mmap failed");
            close(*fd);
            *fd = -1;
            return -1;
        }

        buffers[i] = mmap(NULL, buf->length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf->m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap failed");
            close(*fd);
            *fd = -1;
            return -1;
        }

        buffer_size[i] = buf->length;
    }

    return 0;
}

static int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON failed");
        return -1;
    }
    return 0;
}

static int capture_frame(int fd, void **buffers, size_t *buffer_size, int *index) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return 1;
        perror("select() failed");
        return -1;
    }
    if (r == 0) return 1;

    memset(buffers[*index], 0, buffer_size[*index]);

    if (xioctl(fd, VIDIOC_DQBUF, buffers[*index]) < 0) {
        perror("VIDIOC_DQBUF failed");
        return -1;
    }

    *index = (*index + 1) % NUM_BUFFERS;
    return 0;
}

static int log_timestamp(const struct timespec *ts) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen() failed");
        return -1;
    }
    fprintf(fp, "%ld.%06ld\n", ts->tv_sec, ts->tv_nsec / 1000);
    if (fclose(fp) != 0) {
        perror("fclose() failed");
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers reqbufs;
    struct v4l2_buffer buf;
    void *buffers[NUM_BUFFERS];
    size_t buffer_size[NUM_BUFFERS];
    int index = 0;
    struct timespec ts;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction() failed");
        return 1;
    }

    if (init_camera(&fd, &fmt, &reqbufs, &buf, buffers, buffer_size) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return 1;
    }

    if (start_streaming(fd) < 0) {
        fprintf(stderr, "Failed to start streaming\n");
        close(fd);
        return 1;
    }

    printf("Capturing video stream from %s... Press Ctrl+C to stop.\n", VIDEO_DEVICE);

    while (running) {
        int ret = capture_frame(fd, buffers, buffer_size, &index);
        if (ret < 0) {
            fprintf(stderr, "Error capturing frame\n");
            break;
        }
        if (ret == 1) {
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("clock_gettime() failed");
            break;
        }

        if (log_timestamp(&ts) < 0) {
            fprintf(stderr, "Error logging timestamp\n");
            break;
        }
    }

    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (buffers[i] != MAP_FAILED && buffers[i] != NULL) {
                munmap(buffers[i], buffer_size[i]);
            }
        }
        close(fd);
    }

    printf("\nExiting cleanly.\n");
    return 0;
}

