        if (xioctl(*fd, VIDIOC_QUERYBUF, buf) < 0) {
            perror("VIDIOC_QUERYBUF failed");
            close(*fd);
            *fd = -1;
            return -1;
        }

        if (mmap(NULL, buf->length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf->m.offset) == MAP_FAILED) {
            perror("mmap failed");
            close(*fd);
            *fd = -1;
            return -1;
        }

        buffers[i] = mmap(NULL, buf->length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf->m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap failed");
            close(*fd);
            *fd = -1;
            return -1;
        }

        buffer_size[i] = buf->length;
    }

    return 0;
}

static int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON failed");
        return -1;
    }
    return 0;
}

static int capture_frame(int fd, void **buffers, size_t *buffer_size, int *index) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return 1;
        perror("select() failed");
        return -1;
    }
    if (r == 0) return 1;

    memset(buffers[*index], 0, buffer_size[*index]);

    if (xioctl(fd, VIDIOC_DQBUF, buffers[*index]) < 0) {
        perror("VIDIOC_DQBUF failed");
        return -1;
    }

    *index = (*index + 1) % NUM_BUFFERS;
    return 0;
}

static int log_timestamp(const struct timespec *ts) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen() failed");
        return -1;
    }
    fprintf(fp, "%ld.%06ld\n", ts->tv_sec, ts->tv_nsec / 1000);
    if (fclose(fp) != 0) {
        perror("fclose() failed");
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers reqbufs;
    struct v4l2_buffer buf;
    void *buffers[NUM_BUFFERS];
    size_t buffer_size[NUM_BUFFERS];
    int index = 0;
    struct timespec ts;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction() failed");
        return 1;
    }

    if (init_camera(&fd, &fmt, &reqbufs, &buf, buffers, buffer_size) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return 1;
    }

    if (start_streaming(fd) < 0) {
        fprintf(stderr, "Failed to start streaming\n");
        close(fd);
        return 1;
    }

    printf("Capturing video stream from %s... Press Ctrl+C to stop.\n", VIDEO_DEVICE);

    while (running) {
        int ret = capture_frame(fd, buffers, buffer_size, &index);
        if (ret < 0) {
            fprintf(stderr, "Error capturing frame\n");
            break;
        }
        if (ret == 1) {
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("clock_gettime() failed");
            break;
        }

        if (log_timestamp(&ts) < 0) {
            fprintf(stderr, "Error logging timestamp\n");
            break;
        }
    }

    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (buffers[i] != MAP_FAILED && buffers[i] != NULL) {
                munmap(buffers[i], buffer_size[i]);
            }
        }
        close(fd);
    }

    printf("\nExiting cleanly.\n");
    return 0;
}

