typedef struct {
    unsigned int frame_index;
    unsigned int fragment_index;
    unsigned int total_fragments;
    unsigned int payload_size;
} FrameHeader;

static volatile sig_atomic_t running = 1;
static int video_fd = -1;
static int sockfd = -1;
static void *buffers[NUM_BUFFERS];
static size_t buffer_sizes[NUM_BUFFERS];
static struct v4l2_buffer buf;
static struct v4l2_requestbuffers req;
static struct sockaddr_in servaddr;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(void) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_streamparm parm;

    video_fd = open(VIDEO_DEVICE, O_RDWR);
    if (video_fd < 0) {
        perror("open video device");
        return -1;
    }

    if (xioctl(video_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(video_fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(video_fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    for (unsigned int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(video_fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            return -1;
        }
        buffer_sizes[i] = buf.length;
        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap");
            return -1;
        }
    }

    for (unsigned int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(video_fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(video_fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    return 0;
}

static int init_socket(const char *ip, int port) {
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip, &servaddr.sin_addr) <= 0) {
        perror("inet_pton");
        return -1;
    }
    return 0;
}

static int send_frame(const unsigned char *frame, unsigned int frame_index, unsigned int total_fragments) {
    unsigned int num_fragments = (FRAME_SIZE + MAX_DGRAM_SIZE - 1) / MAX_DGRAM_SIZE;
    if (num_fragments == 0) num_fragments = 1;

    for (unsigned int frag = 0; frag < num_fragments; frag++) {
        unsigned int start = frag * MAX_DGRAM_SIZE;
        unsigned int end = (frag + 1) * MAX_DGRAM_SIZE;
        if (end > FRAME_SIZE) end = FRAME_SIZE;
        unsigned int payload_size = end - start;

        FrameHeader header;
        header.frame_index = frame_index;
        header.fragment_index = frag;
        header.total_fragments = total_fragments;
        header.payload_size = payload_size;

        unsigned char *dgram = malloc(MAX_DGRAM_SIZE);
        if (!dgram) {
            perror("malloc");
            return -1;
        }

        memcpy(dgram, &header, sizeof(FrameHeader));
        memcpy(dgram + sizeof(FrameHeader), frame + start, payload_size);

        if (sendto(sockfd, dgram, sizeof(FrameHeader) + payload_size, 0,
                   (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
            perror("sendto");
            free(dgram);
            return -1;
        }
        free(dgram);
    }
    return 0;
}

static void cleanup(void) {
