    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_camera() < 0) {
        cleanup();
        return 1;
    }

    if (init_socket(server_ip, server_port) < 0) {
        cleanup();
        return 1;
    }

    unsigned int frame_index = 0;
    unsigned int total_fragments = (FRAME_SIZE + MAX_DGRAM_SIZE - 1) / MAX_DGRAM_SIZE;
    if (total_fragments == 0) total_fragments = 1;

    while (running) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (xioctl(video_fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) continue;
            perror("VIDIOC_DQBUF");
            break;
        }

        unsigned char *frame = (unsigned char *)buffers[buf.index];
        if (send_frame(frame, frame_index, total_fragments) < 0) {
            break;
        }

        if (xioctl(video_fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            break;
        }

        frame_index++;
    }

    cleanup();
    return 0;
}

