#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define PAN_PIN      4
#define TILT_PIN     5
#define TILT_UP_PIN  6
#define TILT_DOWN_PIN 7
#define PAN_LEFT_PIN 8
#define PAN_RIGHT_PIN 9

#define MIN_DUTY 25
#define MAX_DUTY 125
#define DUTY_RANGE (MAX_DUTY - MIN_DUTY)
#define STEP 5
#define PWM_PERIOD_US 20000
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo(struct gpiod_line *line, int duty) {
    if (duty < MIN_DUTY) duty = MIN_DUTY;
    if (duty > MAX_DUTY) duty = MAX_DUTY;

    int on_us = (duty * PWM_PERIOD_US) / 1000;
    int off_us = PWM_PERIOD_US - on_us;

    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(on_us);
    if (gpiod_line_set_value(line, 0) < 0) return -1;
    usleep(off_us);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pan_line = NULL, *tilt_line = NULL;
    struct gpiod_line *tilt_up = NULL, *tilt_down = NULL;
    struct gpiod_line *pan_left = NULL, *pan_right = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    pan_line = gpiod_chip_get_line(chip, PAN_PIN);
    tilt_line = gpiod_chip_get_line(chip, TILT_PIN);
    tilt_up = gpiod_chip_get_line(chip, TILT_UP_PIN);
    tilt_down = gpiod_chip_get_line(chip, TILT_DOWN_PIN);
    pan_left = gpiod_chip_get_line(chip, PAN_LEFT_PIN);
    pan_right = gpiod_chip_get_line(chip, PAN_RIGHT_PIN);

    if (!pan_line || !tilt_line || !tilt_up || !tilt_down ||
        !pan_left || !pan_right) {
        fprintf(stderr, "Failed to get one or more GPIO lines\n");
        goto cleanup;
    }

    if (gpiod_line_request_output(pan_line, "pan_servo", 0) < 0 ||
        gpiod_line_request_output(tilt_line, "tilt_servo", 0) < 0) {
        fprintf(stderr, "Failed to request servo output lines\n");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(tilt_up, "tilt_up", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_request_input_flags(tilt_down, "tilt_down", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_request_input_flags(pan_left, "pan_left", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_request_input_flags(pan_right, "pan_right", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request button input lines\n");
        goto cleanup;
    }

    int pan_duty = 75;
    int tilt_duty = 75;

    if (set_servo(pan_line, pan_duty) < 0 || set_servo(tilt_line, tilt_duty) < 0) {
        fprintf(stderr, "Failed to initialize servos\n");
        goto cleanup;
    }

    printf("Pan-tilt control started. Press Ctrl+C to exit.\n");

    while (running) {
        int tilt_up_val = gpiod_line_get_value(tilt_up);
        int tilt_down_val = gpiod_line_get_value(tilt_down);
        int pan_left_val = gpiod_line_get_value(pan_left);
        int pan_right_val = gpiod_line_get_value(pan_right);

        if (tilt_up_val == 0) {
            tilt_duty += STEP;
            if (tilt_duty > MAX_DUTY) tilt_duty = MAX_DUTY;
            if (set_servo(tilt_line, tilt_duty) < 0) {
                fprintf(stderr, "Error setting tilt servo\n");
            }
        }
        if (tilt_down_val == 0) {
            tilt_duty -= STEP;
            if (tilt_duty < MIN_DUTY) tilt_duty = MIN_DUTY;
            if (set_servo(tilt_line, tilt_duty) < 0) {
                fprintf(stderr, "Error setting tilt servo\n");
            }
        }
        if (pan_left_val == 0) {
            pan_duty += STEP;
            if (pan_duty > MAX_DUTY) pan_duty = MAX_DUTY;
            if (set_servo(pan_line, pan_duty) < 0) {
                fprintf(stderr, "Error setting pan servo\n");
            }
        }
        if (pan_right_val == 0) {
            pan_duty -= STEP;
            if (pan_duty < MIN_DUTY) pan_duty = MIN_DUTY;
            if (set_servo(pan_line, pan_duty) < 0) {
                fprintf(stderr, "Error setting pan servo\n");
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (pan_line) gpiod_line_release(pan_line);
    if (tilt_line) gpiod_line_release(tilt_line);
    if (tilt_up) gpiod_line_release(tilt_up);
    if (tilt_down) gpiod_line_release(tilt_down);
    if (pan_left) gpiod_line_release(pan_left);
    if (pan_right) gpiod_line_release(pan_right);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

