#include <sys/select.h>
#include <linux/videodev2.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <jpeglib.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define JPEG_QUALITY 75
#define BLUR_RADIUS 2
#define NUM_BUFFERS 4

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    void *start;
    size_t length;
} buffer_t;

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd, buffer_t **buffers, unsigned int *n_buffers) {
    *fd = open(DEVICE_NAME, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(*fd); *fd = -1; return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(*fd); *fd = -1; return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(*fd); *fd = -1; return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        close(*fd); *fd = -1; return -1;
    }
    if (fmt.fmt.pix.width != WIDTH || fmt.fmt.pix.height != HEIGHT) {
        fprintf(stderr, "Warning: device set format to %ux%u\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height);
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        close(*fd); *fd = -1; return -1;
    }
    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(*fd); *fd = -1; return -1;
    }

    *n_buffers = req.count;
    buffers = malloc(*n_buffers * sizeof(buffer_t));
    if (!buffers) {
        fprintf(stderr, "malloc failed: %s\n", strerror(errno));
        close(*fd); *fd = -1; return -1;
    }
    memset(buffers, 0, *n_buffers * sizeof(buffer_t));

    for (unsigned int i = 0; i < *n_buffers; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QUERYBUF[%u] failed: %s\n", i, strerror(errno));
            free(buffers); *fd = -1; return -1;
        }
        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            fprintf(stderr, "mmap[%u] failed: %s\n", i, strerror(errno));
            free(buffers); *fd = -1; return -1;
        }
    }
    return 0;
}

static int start_stream(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int stop_stream(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_frame(int fd, buffer_t *buffers, unsigned int n_buffers, unsigned char **yuyv_data, size_t *yuyv_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    struct timeval tv;
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "select failed: %s\n", strerror(errno));
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        return -1;
    }

    *yuyv_data = buffers[buf.index].start;
    *yuyv_size = buf.bytesused;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void convert_yuyv_to_rgb(unsigned char *yuyv, int w, int h, unsigned char *rgb) {
    for (int i = 0; i < w * h; i++) {
        int y1 = yuyv[0];
        int u = yuyv[1];
        int v = yuyv[2];
        int y2 = yuyv[3];
        int y3 = yuyv[4];
        int y4 = yuyv[5];
        int u2 = yuyv[6];
        int v2 = yuyv[7];

        int r1 = y1 + 1.402 * (v - 128);
        int g1 = y1 - 0.34414 * (u - 128) - 0.71414 * (v - 128);
        int b1 = y1 + 1.772 * (u - 128);
        if (r1 < 0) r1 = 0; if (r1 > 255) r1 = 255;
        if (g1 < 0) g1 = 0; if (g1 > 255) g1 = 255;
        if (b1 < 0) b1 = 0; if (b1 > 255) b1 = 255;

        int r2 = y2 + 1.402 * (v - 128);
        int g2 = y2 - 0.34414 * (u - 128) - 0.71414 * (v - 128);
        int b2 = y2 + 1.772 * (u - 128);
        if (r2 < 0) r2 = 0; if (r2 > 255) r2 = 255;
        if (g2 < 0) g2 = 0; if (g2 > 255) g2 = 255;
        if (b2 < 0) b2 = 0; if (b2 > 255) b2 = 255;

        int r3 = y3 + 1.402 * (v2 - 128);
        int g3 = y3 - 0.34414 * (u2 - 128) - 0.71414 * (v2 - 128);
        int b3 = y3 + 1.772 * (u2 - 128);
        if (r3 < 0) r3 = 0; if (r3 > 255) r3 = 255;
        if (g3 < 0) g3 = 0; if (g3 > 255) g3 = 255;
        if (b3 < 0) b3 = 0; if (b3 > 255) b3 = 255;

        int r4 = y4 + 1.402 * (v2 - 128);
        int g4 = y4 - 0.34414 * (u2 - 128) - 0.71414 * (v2 - 128);
        int b4 = y4 + 1.772 * (u2 - 128);
        if (r4 < 0) r4 = 0; if (r4 > 255) r4 = 255;
        if (g4 < 0) g4 = 0; if (g4 > 255) g4 = 255;
        if (b4 < 0) b4 = 0; if (b4 > 255) b4 = 255;

        rgb[0] = (unsigned char)r1; rgb[1] = (unsigned char)g1; rgb[2] = (unsigned char)b1;
        rgb[3] = (unsigned char)r2; rgb[4] = (unsigned char)g2; rgb[5] = (unsigned char)b2;
        rgb[6] = (unsigned char)r3; rgb[7] = (unsigned char)g3; rgb[8] = (unsigned char)b3;
        rgb[9] = (unsigned char)r4; rgb[10] = (unsigned char)g4; rgb[11] = (unsigned char)b4;
        yuyv += 8;
        rgb += 12;
    }
}

static void apply_box_blur(unsigned char *rgb, int w, int h) {
    int kernel_size = 2 * BLUR_RADIUS + 1;
    int kernel_radius = BLUR_RADIUS;
    int kernel_sum = kernel_size * kernel_size;
    int *r = malloc(kernel_sum * sizeof(int));
    int *g = malloc(kernel_sum * sizeof(int));
    int *b = malloc(kernel_sum * sizeof(int));
    if (!r || !g || !b) {
        fprintf(stderr, "malloc failed: %s\n", strerror(errno));
        free(r); free(g); free(b);
        return;
    }

    for (int i = 0; i < kernel_sum; i++) r[i] = g[i] = b[i] = 0;

    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            int r_val = rgb[2 * (x + y * w)];
            int g_val = rgb[2 * (x + y * w) + 1];
            int b_val = rgb[2 * (x + y * w) + 2];
            r[(x - kernel_radius + kernel_size - 1 + kernel_size) % kernel_size] = r_val;
            g[(x - kernel_radius + kernel_size - 1 + kernel_size) % kernel_size] = g_val;
            b[(x - kernel_radius + kernel_size - 1 + kernel_size) % kernel_size] = b_val;
        }
        for (int x = 0; x < w; x++) {
            int r_val = rgb[2 * (x + y * w)];
            int g_val = rgb[2 * (x + y * w) + 1];
            int b_val = rgb[2 * (x + y * w) + 2];
            for (int i = 0; i < kernel_size; i++) {
                r[i] = r_val;
                g[i] = g_val;
                b[i] = b_val;
            }
            for (int i = 0; i < kernel_size; i++) {
                r_val += r[i];
                g_val += g[i];
                b_val += b[i];
            }
            r_val /= kernel_sum;
            g_val /= kernel_sum;
            b_val /= kernel_sum;
            rgb[2 * (x + y * w)] = (unsigned char)r_val;
            rgb[2 * (x + y * w) + 1] = (unsigned char)g_val;
            rgb[2 * (x + y * w) + 2] = (unsigned char)b_val;
        }
    }
    free(r); free(g); free(b);
}

static int save_jpeg(const unsigned char *rgb, int w, int h, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_mem_dest(&cinfo, &rgb, &h * w * 3);
    cinfo.image_width = w;
    cinfo.image_height = h;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;
    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);
    JSAMPROW row_pointer[1];
    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = (JSAMPROW)(rgb + cinfo.next_scanline * w * 3);
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }
    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = -1;
    buffer_t *buffers = NULL;
    unsigned int n_buffers = 0;
    unsigned char *yuyv_data = NULL;
    size_t yuyv_size = 0;
    unsigned char *rgb_data = NULL;
    int ret = 1;

    if (init_camera(&fd, &buffers, &n_buffers) < 0) goto cleanup;
    if (start_stream(fd) < 0) goto cleanup;
    if (capture_frame(fd, buffers, n_buffers, &yuyv_data, &yuyv_size) < 0) goto cleanup;
    rgb_data = malloc(WIDTH * HEIGHT * 3);
    if (!rgb_data) {
        fprintf(stderr, "malloc failed: %s\n", strerror(errno));
        goto cleanup;
    }
    convert_yuyv_to_rgb(yuyv_data, WIDTH, HEIGHT, rgb_data);
    apply_box_blur(rgb_data, WIDTH, HEIGHT);

    time_t rawtime;
    struct tm *timeinfo;
    char filename[256];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);
    if (save_jpeg(rgb_data, WIDTH, HEIGHT, filename) < 0) {
        fprintf(stderr, "Failed to save JPEG\n");
        goto cleanup;
    }
    printf("Saved blurred image to %s\n", filename);
    ret = 0;

cleanup:
    if (fd != -1) {
        stop_stream(fd);
        for (unsigned int i = 0; i < n_buffers; i++) {
            if (buffers[i].start && buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
        close(fd);
    }
    free(rgb_data);
    return ret;
}

