    int *g = malloc(kernel_sum * sizeof(int));
    int *b = malloc(kernel_sum * sizeof(int));
    if (!r || !g || !b) {
        fprintf(stderr, "malloc failed: %s\n", strerror(errno));
        free(r); free(g); free(b);
        return;
    }

    for (int i = 0; i < kernel_sum; i++) r[i] = g[i] = b[i] = 0;

    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            int r_val = rgb[2 * (x + y * w)];
            int g_val = rgb[2 * (x + y * w) + 1];
            int b_val = rgb[2 * (x + y * w) + 2];
            r[(x - kernel_radius + kernel_size - 1 + kernel_size) % kernel_size] = r_val;
            g[(x - kernel_radius + kernel_size - 1 + kernel_size) % kernel_size] = g_val;
            b[(x - kernel_radius + kernel_size - 1 + kernel_size) % kernel_size] = b_val;
        }
        for (int x = 0; x < w; x++) {
            int r_val = rgb[2 * (x + y * w)];
            int g_val = rgb[2 * (x + y * w) + 1];
            int b_val = rgb[2 * (x + y * w) + 2];
            for (int i = 0; i < kernel_size; i++) {
                r[i] = r_val;
                g[i] = g_val;
                b[i] = b_val;
            }
            for (int i = 0; i < kernel_size; i++) {
                r_val += r[i];
                g_val += g[i];
                b_val += b[i];
            }
            r_val /= kernel_sum;
            g_val /= kernel_sum;
            b_val /= kernel_sum;
            rgb[2 * (x + y * w)] = (unsigned char)r_val;
            rgb[2 * (x + y * w) + 1] = (unsigned char)g_val;
            rgb[2 * (x + y * w) + 2] = (unsigned char)b_val;
        }
    }
    free(r); free(g); free(b);
}

static int save_jpeg(const unsigned char *rgb, int w, int h, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_mem_dest(&cinfo, &rgb, &h * w * 3);
    cinfo.image_width = w;
    cinfo.image_height = h;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;
    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);
    JSAMPROW row_pointer[1];
    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = (JSAMPROW)(rgb + cinfo.next_scanline * w * 3);
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }
    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = -1;
    buffer_t *buffers = NULL;
    unsigned int n_buffers = 0;
    unsigned char *yuyv_data = NULL;
    size_t yuyv_size = 0;
    unsigned char *rgb_data = NULL;
    int ret = 1;

    if (init_camera(&fd, &buffers, &n_buffers) < 0) goto cleanup;
    if (start_stream(fd) < 0) goto cleanup;
    if (capture_frame(fd, buffers, n_buffers, &yuyv_data, &yuyv_size) < 0) goto cleanup;
    rgb_data = malloc(WIDTH * HEIGHT * 3);
    if (!rgb_data) {
        fprintf(stderr, "malloc failed: %s\n", strerror(errno));
        goto cleanup;
    }
    convert_yuyv_to_rgb(yuyv_data, WIDTH, HEIGHT, rgb_data);
    apply_box_blur(rgb_data, WIDTH, HEIGHT);

    time_t rawtime;
    struct tm *timeinfo;
    char filename[256];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);
    if (save_jpeg(rgb_data, WIDTH, HEIGHT, filename) < 0) {
        fprintf(stderr, "Failed to save JPEG\n");
        goto cleanup;
    }
    printf("Saved blurred image to %s\n", filename);
    ret = 0;

cleanup:
    if (fd != -1) {
        stop_stream(fd);
        for (unsigned int i = 0; i < n_buffers; i++) {
            if (buffers[i].start && buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
        close(fd);
    }
    free(rgb_data);
    return ret;
}

