#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static void print_frame_size(const struct v4l2_frmsize_discrete *fs) {
    printf("  %ux%u\n", fs->width, fs->height);
}

static void print_frame_interval(const struct v4l2_frmival_stepwise *fi) {
    if (fi->type == V4L2_FRMIVAL_TYPE_DISCRETE) {
        printf("  %u/%u fps\n", fi->denominator, fi->numerator);
    } else if (fi->type == V4L2_FRMIVAL_TYPE_STEPWISE) {
        printf("  %u-%u fps\n", fi->min.denominator / fi->min.numerator,
               fi->max.denominator / fi->max.numerator);
    } else {
        printf("  unknown frame rate\n");
    }
}

int main(void) {
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_ENUM_FRAMESIZES)) {
        printf("Camera does not support frame-size enumeration.\n");
    } else {
        struct v4l2_frmsizeenum fse;
        memset(&fse, 0, sizeof(fse));
        fse.pixel_format = V4L2_PIX_FMT_MJPEG;
        int found = 0;
        for (int i = 0; i < 100; i++) {
            fse.index = i;
            if (xioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fse) == -1) {
                if (errno == EINVAL) break;
                fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES failed: %s\n", strerror(errno));
                break;
            }
            if (fse.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
                printf("Supported resolutions:\n");
                print_frame_size(&fse.discrete);
                found = 1;
            }
        }
        if (!found) {
            printf("  (none found)\n");
        }
    }

    if (!(cap.capabilities & V4L2_CAP_ENUM_FRAMEINTERVALS)) {
        printf("Camera does not support frame-interval enumeration.\n");
    } else {
        struct v4l2_frmivalenum fi;
        memset(&fi, 0, sizeof(fi));
        fi.pixel_format = V4L2_PIX_FMT_MJPEG;
        int found = 0;
        for (int i = 0; i < 100; i++) {
            fi.index = i;
            if (xioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fi) == -1) {
                if (errno == EINVAL) break;
                fprintf(stderr, "VIDIOC_ENUM_FRAMEINTERVALS failed: %s\n", strerror(errno));
                break;
            }
            if (fi.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
                printf("Supported frame rates:\n");
                print_frame_interval(&fi.discrete);
                found = 1;
            }
        }
        if (!found) {
            printf("  (none found)\n");
        }
    }

    if (cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) {
        struct v4l2_control ctrl;
        memset(&ctrl, 0, sizeof(ctrl));
        ctrl.id = V4L2_CID_FOCUS_AUTO;
        if (xioctl(fd, VIDIOC_QUERYCTRL, &ctrl) == -1) {
            if (errno == EINVAL) {
                printf("Autofocus: not supported\n");
            } else {
                fprintf(stderr, "VIDIOC_QUERYCTRL (autofocus) failed: %s\n", strerror(errno));
            }
        } else {
            printf("Autofocus: %s\n", ctrl.value ? "supported" : "not supported");
        }
    }

    close(fd);
    return EXIT_SUCCESS;
}

