#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_CENTER_PULSE_WIDTH 1500
#define SERVO_STEP 10
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse(int pin, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: pulse width %d out of range [%d, %d]\n",
                pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return -1;
    }
    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(UP_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pan_pos = SERVO_CENTER_PULSE_WIDTH;
    int tilt_pos = SERVO_CENTER_PULSE_WIDTH;

    if (set_servo_pulse(PAN_SERVO_PIN, pan_pos) != 0 ||
        set_servo_pulse(TILT_SERVO_PIN, tilt_pos) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pan-tilt control started.\n");
    printf("  Pan servo : GPIO%d (center %d us)\n", PAN_SERVO_PIN, SERVO_CENTER_PULSE_WIDTH);
    printf("  Tilt servo: GPIO%d (center %d us)\n", TILT_SERVO_PIN, SERVO_CENTER_PULSE_WIDTH);
    printf("  UP : GPIO%d\n  DOWN : GPIO%d\n  LEFT : GPIO%d\n  RIGHT : GPIO%d\n",
           UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int up    = (gpioRead(UP_BUTTON_PIN) == 0);
        int down  = (gpioRead(DOWN_BUTTON_PIN) == 0);
        int left  = (gpioRead(LEFT_BUTTON_PIN) == 0);
        int right = (gpioRead(RIGHT_BUTTON_PIN) == 0);

        if (up) {
            if (pan_pos + SERVO_STEP <= SERVO_MAX_PULSE_WIDTH) {
                pan_pos += SERVO_STEP;
            }
        } else if (down) {
            if (pan_pos - SERVO_STEP >= SERVO_MIN_PULSE_WIDTH) {
                pan_pos -= SERVO_STEP;
            }
        }

        if (left) {
            if (tilt_pos + SERVO_STEP <= SERVO_MAX_PULSE_WIDTH) {
                tilt_pos += SERVO_STEP;
            }
        } else if (right) {
            if (tilt_pos - SERVO_STEP >= SERVO_MIN_PULSE_WIDTH) {
                tilt_pos -= SERVO_STEP;
            }
        }

        if (set_servo_pulse(PAN_SERVO_PIN, pan_pos) != 0 ||
            set_servo_pulse(TILT_SERVO_PIN, tilt_pos) != 0) {
            break;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

