#define CAPTURE_QUALITY 85
#define CAPTURE_DIR "motion_captures"
#define SERVER_URL "http://<server_ip>:<server_port>/upload"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_capture_dir(void) {
    struct stat st;
    if (stat(CAPTURE_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", CAPTURE_DIR);
        return -1;
    }
    if (mkdir(CAPTURE_DIR, 0755) != 0) {
        if (errno != EEXIST) {
            fprintf(stderr, "Error creating directory '%s': %s\n", CAPTURE_DIR, strerror(errno));
            return -1;
        }
        fprintf(stderr, "Warning: directory '%s' already exists\n", CAPTURE_DIR);
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
        "libcamera-still -o %s/%s -w %d -h %d -q %d --nopreview 2>/dev/null",
        CAPTURE_DIR, filename, CAPTURE_WIDTH, CAPTURE_HEIGHT, CAPTURE_QUALITY);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: command buffer too small\n");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error: system() failed: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: libcamera-still failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

static int send_data(const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: curl_easy_init() failed\n");
        return -1;
    }
    char json[512];
    int ret = snprintf(json, sizeof(json),
        "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion_status\":%d,\"gpio_pin\":%d}",
        filename, timestamp, motion_status, gpio_pin);
    if (ret < 0 || (size_t)ret >= sizeof(json)) {
        fprintf(stderr, "Error: JSON buffer too small\n");
        curl_easy_cleanup(curl);
        return -1;
    }
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Error: curl_slist_append() failed\n");
        curl_easy_cleanup(curl);
        return -1;
    }
    curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);
    CURLcode res = curl_easy_perform(curl);
    int result = 0;
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        result = -1;
    }
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return result;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }
    const char *server_ip = argv[1];
    const char *server_port = argv[2];
    snprintf(SERVER_URL, sizeof(SERVER_URL), "http://%s:%s/upload", server_ip, server_port);
    if (ensure_capture_dir() != 0) return EXIT_FAILURE;
    if (curl_global_init(CURL_GLOBAL_DEFAULT) != 0) {
        fprintf(stderr, "Error: curl_global_init() failed\n");
        return EXIT_FAILURE;
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        curl_global_cleanup();
        return EXIT_FAILURE;
    }
    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction() failed: %s\n", strerror(errno));
        gpioTerminate();
        curl_global_cleanup();
        return EXIT_FAILURE;
    }
    printf("Motion detection started on GPIO%d. Press Ctrl+C to exit.\n", PIR_GPIO);
    while (running) {
        int motion = gpioRead(PIR_GPIO);
        if (motion < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed\n", PIR_GPIO);
            break;
        }
        if (motion) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[32];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
            char filename[128];
            snprintf(filename, sizeof(filename), "%s/%s_%ld.jpg", CAPTURE_DIR, timestamp, (long)time(NULL));
            printf("Motion detected on GPIO%d at %s. Capturing image...\n", PIR_GPIO, timestamp);
            if (capture_image(filename) == 0) {
                printf("Image captured: %s\n", filename);
                if (send_data(filename, timestamp, 1, PIR_GPIO) == 0) {
                    printf("Data sent to server.\n");
                } else {
                    fprintf(stderr, "Error: Failed to send data to server.\n");
                }
            } else {
                fprintf(stderr, "Error: Failed to capture image.\n");
            }
            for (int i = 0; i < DEBOUNCE_DELAY_S * 10 && running; i++) {
                gpioDelay(POLL_INTERVAL_US);
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }
    printf("\nShutting down...\n");
    gpioTerminate();
    curl_global_cleanup();
    return EXIT_SUCCESS;
