#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <gpiod.h>

#define PIR_GPIO_LINE		17
#define GPIO_CHIP_NAME		"gpiochip0"
#define IMAGE_DIR			"/home/pi/images"
#define LOG_FILE			"/home/pi/motion_capture.log"
#define DEBOUNCE_MS		50
#define CAPTURE_TIMEOUT_MS	2000
#define POLL_TIMEOUT_MS		100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
	(void)sig;
	program_running = 0;
}

static void log_event(const char *message)
{
	FILE *fp = fopen(LOG_FILE, "a");
	if (!fp) {
		fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
		return;
	}
	time_t t = time(NULL);
	struct tm tm;
	if (localtime_r(&t, &tm)) {
		fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
			tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
			tm.tm_hour, tm.tm_min, tm.tm_sec, message);
	}
	fclose(fp);
}

static int capture_image(void)
{
	time_t t = time(NULL);
	struct tm tm;
	if (!localtime_r(&t, &tm)) {
		fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
		return -1;
	}

	char filename[256];
	char command[512];

	snprintf(filename, sizeof(filename), "%s/%04d%02d%02d_%02d%02d%02d_%03d.jpg",
		 IMAGE_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
		 tm.tm_hour, tm.tm_min, tm.tm_sec, (tm.tm_sec * 1000) % 1000);

	snprintf(command, sizeof(command),
		"libcamera-still -o '%s' --width 640 --height 480 -q 85 --timeout %d --nopreview",
		filename, CAPTURE_TIMEOUT_MS);

	int ret = system(command);
	if (ret == -1) {
		fprintf(stderr, "system() failed: %s\n", strerror(errno));
		return -1;
	}
	if (!WIFEXITED(ret) || WEXITSTATUS(ret) != 0) {
		fprintf(stderr, "libcamera-still failed (status=%d)\n", ret);
		return -1;
	}
	return 0;
}

int main(void)
{
	struct sigaction sa;
	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = signal_handler;
	sigemptyset(&sa.sa_mask);
	sa.sa_flags = 0;
	if (sigaction(SIGINT, &sa, NULL) == -1) {
		fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
		return 1;
	}
	if (sigaction(SIGTERM, &sa, NULL) == -1) {
		fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
		return 1;
	}

	struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
	if (!chip) {
		fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
		return 1;
	}

	struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
	if (!pir_line) {
		fprintf(stderr, "Failed to get GPIO line %d: %s\n", PIR_GPIO_LINE, strerror(errno));
		gpiod_chip_close(chip);
		return 1;
	}

	if (gpiod_line_request_falling_edge_events(pir_line, "motion_capture") < 0) {
		fprintf(stderr, "Failed to request falling-edge events on GPIO %d: %s\n",
			PIR_GPIO_LINE, strerror(errno));
		gpiod_chip_close(chip);
		return 1;
	}

	log_event("Motion capture service started.");

	struct timespec last_event = {0, 0};

	while (program_running) {
		struct timespec ts = {0, POLL_TIMEOUT_MS * 1000000L};
		int ret = gpiod_line_event_wait(pir_line, &ts);
		if (ret < 0) {
			if (errno == EINTR) continue;
			fprintf(stderr, "gpiod_line_event_wait error: %s\n", strerror(errno));
			break;
		}
		if (ret == 0) continue;

		struct gpiod_line_event event;
		if (gpiod_line_event_read(pir_line, &event) < 0) {
			fprintf(stderr, "gpiod_line_event_read error: %s\n", strerror(errno));
			continue;
		}

		struct timespec now = event.ts;
		long elapsed_ms = (now.tv_sec - last_event.tv_sec) * 1000L +
			(now.tv_nsec - last_event.tv_nsec) / 1000000L;
		if (elapsed_ms < DEBOUNCE_MS) continue;
		last_event = now;

		if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
			log_event("Motion detected!");
			if (capture_image() == 0) {
				log_event("Image captured successfully.");
			} else {
				log_event("Failed to capture image.");
			}
		}
	}

	log_event("Motion capture service stopped.");
	gpiod_line_release(pir_line);
	gpiod_chip_close(chip);
	return 0;
}

