#define OUTPUT_FILE "cropped.yuv"
#define TIMEOUT_SEC 2

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r < 0 && errno == EINTR);
    return r;
}

static int open_device(const char *name) {
    int fd = open(name, O_RDWR);
    if (fd < 0) {
        perror("open device");
        return -1;
    }
    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(fd);
        return -1;
    }
    return fd;
}

static int set_format(int fd, int w, int h, unsigned int pixfmt) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = w;
    fmt.fmt.pix.height = h;
    fmt.fmt.pix.pixelformat = pixfmt;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return -1;
    }
    if (fmt.fmt.pix.width != w || fmt.fmt.pix.height != h) {
        fprintf(stderr, "Warning: driver adjusted format to %dx%d\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height);
    }
    if (fmt.fmt.pix.pixelformat != pixfmt) {
        fprintf(stderr, "Warning: driver adjusted pixel format\n");
        return -1;
    }
    return 0;
}

static int set_crop(int fd, int x, int y, int w, int h) {
    struct v4l2_crop crop;
    memset(&crop, 0, sizeof(crop));
    crop.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    crop.c = (struct v4l2_rect){.left = x, .top = y, .width = w, .height = h};
    if (xioctl(fd, VIDIOC_S_CROP, &crop) < 0) {
        perror("VIDIOC_S_CROP");
        return -1;
    }
    if (crop.c.width != w || crop.c.height != h) {
        fprintf(stderr, "Warning: crop adjusted to %dx%d\n",
                crop.c.width, crop.c.height);
    }
    return 0;
}

static int init_mmap(int fd, struct v4l2_buffer *buf, void **mem, size_t *size) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }
    memset(buf, 0, sizeof(*buf));
    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;
    buf->index = 0;
    if (xioctl(fd, VIDIOC_QUERYBUF, buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        return -1;
    }
    *size = buf->length;
    *mem = mmap(NULL, buf->length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf->m.offset);
    if (*mem == MAP_FAILED) {
        perror("mmap");
        *mem = NULL;
        return -1;
    }
    return 0;
}

static int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    return 0;
}

static int dequeue_frame(int fd, struct v4l2_buffer *buf) {
    if (xioctl(fd, VIDIOC_DQBUF, buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }
    return 0;
}

static int queue_frame(int fd, struct v4l2_buffer *buf) {
    if (xioctl(fd, VIDIOC_QBUF, buf) < 0) {
        perror("VIDIOC_QBUF");
        return -1;
    }
    return 0;
}

static void stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("VIDIOC_STREAMOFF");
    }
}

static void uninit_mmap(void *mem, size_t size) {
    if (mem != NULL && mem != MAP_FAILED) {
        munmap(mem, size);
    }
}

static int save_cropped_frame(const unsigned char *src, int src_w, int src_h,
                              int crop_x, int crop_y, int crop_w, int crop_h,
                              const char *filename) {
    size_t total = (size_t)crop_w * crop_h * 2;
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen output");
        return -1;
    }
    for (int y = 0; y < crop_h; y++) {
        for (int x = 0; x < crop_w; x++) {
            int src_x = crop_x + x;
            int src_y = crop_y + y;
            if (src_x + 1 < src_w && src_y + 1 < src_h) {
                size_t offset = (size_t)(src_y * src_w * 2 + src_x * 2);
                unsigned char y0 = src[offset];
                unsigned char u  = src[offset + 1];
                unsigned char y1 = src[offset + 2];
                unsigned char v  = src[offset + 3];
                if (fwrite(&y0, 1, 1, fp) != 1) { perror("fwrite y0"); return -1; }
                if (fwrite(&u, 1, 1, fp) != 1) { perror("fwrite u"); return -1; }
                if (fwrite(&y1, 1, 1, fp) != 1) { perror("fwrite y1"); return -1; }
                if (fwrite(&v, 1, 1, fp) != 1) { perror("fwrite v"); return -1; }
            }
        }
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) { perror("sigaction SIGINT"); return EXIT_FAILURE; }
    if (sigaction(SIGTERM, &sa, NULL) < 0) { perror("sigaction SIGTERM"); return EXIT_FAILURE; }

    int fd = open_device(DEVICE_NAME);
    if (fd < 0) return EXIT_FAILURE;

    if (set_format(fd, WIDTH, HEIGHT, V4L2_PIX_FMT_YUYV) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (set_crop(fd, CROP_X, CROP_Y, CROP_WIDTH, CROP_HEIGHT) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    void *mem = NULL;
    size_t size = 0;
    if (init_mmap(fd, &buf, &mem, &size) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (start_streaming(fd) < 0) {
        uninit_mmap(mem, size);
        close(fd);
        return EXIT_FAILURE;
    }

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = TIMEOUT_SEC;
    tv.tv_usec = 0;

    int ret = select(fd + 1, &fds, NULL, NULL, &tv);
    if (ret < 0) {
        if (errno == EINTR) {
            fprintf(stderr, "select interrupted by signal\n");
        } else {
            perror("select");
        }
        stop_streaming(fd);
        uninit_mmap(mem, size);
        close(fd);
        return EXIT_FAILURE;
    }
    if (ret == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        stop_streaming(fd);
        uninit_mmap(mem, size);
        close(fd);
        return EXIT_FAILURE;
    }

    if (dequeue_frame(fd, &buf) < 0) {
        stop_streaming(fd);
        uninit_mmap(mem, size);
        close(fd);
        return EXIT_FAILURE;
    }

    if (buf.width != WIDTH || buf.height != HEIGHT ||
        buf.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Unexpected frame: %dx%d, 0x%08x\n",
                buf.width, buf.height, buf.pixelformat);
        queue_frame(fd, &buf);
        stop_streaming(fd);
        uninit_mmap(mem, size);
        close(fd);
        return EXIT_FAILURE;
    }

    if (save_cropped_frame((unsigned char *)mem, buf.width, buf.height,
                           CROP_X, CROP_Y, CROP_WIDTH, CROP_HEIGHT,
                           OUTPUT_FILE) < 0) {
        queue_frame(fd, &buf);
        stop_streaming(fd);
        uninit_mmap(mem, size);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Cropped frame saved to %s (%dx%d YUYV)\n", OUTPUT_FILE, CROP_WIDTH, CROP_HEIGHT);

    queue_frame(fd, &buf);
    stop_streaming(fd);
    uninit_mmap(mem, size);
    close(fd);
    return EXIT_SUCCESS;
}

