#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_GPIO 17
#define TILT_GPIO 18
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define NEUTRAL_ANGLE 90
#define STEP_SIZE 5
#define DELAY_MS 100

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int angle_to_pulse(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d].\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    return SERVO_MIN_PULSE + (angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE)) / MAX_ANGLE;
}

int set_servo_angle(int gpio, int angle) {
    int pulse = angle_to_pulse(angle);
    if (pulse < 0) return -1;
    if (gpioServo(gpio, pulse) != 0) {
        fprintf(stderr, "Error: Failed to set servo on GPIO %d to pulse %d.\n", gpio, pulse);
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    signal(SIGINT, handle_signal);

    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    printf("Pan-Tilt Camera Mount Control\n");
    printf("Arrow keys: up/down/left/right\n");
    printf("Press Ctrl+C or 'q' to exit.\n");
    printf("Initial position: pan=%d, tilt=%d\n", pan_angle, tilt_angle);

    while (keep_running) {
        char input;
        printf("> ");
        fflush(stdout);
        if (scanf(" %c", &input) != 1) {
            break;
        }

        if (input == 'q' || input == 'Q' || !keep_running) {
            break;
        }

        switch (input) {
            case 'w':
            case 'W':
                tilt_angle += STEP_SIZE;
                if (tilt_angle > MAX_ANGLE) tilt_angle = MAX_ANGLE;
                break;
            case 's':
            case 'S':
                tilt_angle -= STEP_SIZE;
                if (tilt_angle < MIN_ANGLE) tilt_angle = MIN_ANGLE;
                break;
            case 'a':
            case 'A':
                pan_angle -= STEP_SIZE;
                if (pan_angle < MIN_ANGLE) pan_angle = MIN_ANGLE;
                break;
            case 'd':
            case 'D':
                pan_angle += STEP_SIZE;
                if (pan_angle > MAX_ANGLE) pan_angle = MAX_ANGLE;
                break;
            default:
                printf("Invalid input. Use arrow keys (w/s/a/d).\n");
                continue;
        }

        if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
            fprintf(stderr, "Failed to update pan servo.\n");
        }
        if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
            fprintf(stderr, "Failed to update tilt servo.\n");
        }

        printf("Pan=%d, Tilt=%d\n", pan_angle, tilt_angle);
        gpioDelay(DELAY_MS * 1000);
    }

    printf("\nShutting down: setting servos to neutral...\n");
    set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE);
    set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE);
    gpioTerminate();
    printf("Done.\n");
    return 0;
}

