#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void lcd_strobe(int data) {
    if (i2c_handle < 0) return;
    char buf[2] = { (char)(data | ENABLE | LCD_BACKLIGHT), (char)(data & ~ENABLE | LCD_BACKLIGHT) };
    i2cWriteDevice(i2c_handle, buf, 2);
    gpioDelay(1000);
}

static void lcd_byte(int bits, int mode) {
    if (i2c_handle < 0) return;
    char buf[4] = {0};
    buf[0] = 0x01;
    buf[1] = (char)(bits & 0xF0) | mode | LCD_BACKLIGHT;
    buf[2] = (char)(((bits << 4) & 0xF0) | mode | LCD_BACKLIGHT);
    buf[3] = (char)(((bits << 8) & 0xF0) | mode | LCD_BACKLIGHT);
    i2cWriteDevice(i2c_handle, buf, 4);
    gpioDelay(100);
}

static void lcd_string(const char *s) {
    if (i2c_handle < 0) return;
    while (*s) {
        lcd_byte((uint8_t)*s++, LCD_CHR);
    }
}

static void lcd_clear(void) {
    if (i2c_handle < 0) return;
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(2000);
}

static void lcd_set_cursor(int col, int row) {
    if (i2c_handle < 0) return;
    int row_offsets[] = {0x00, 0x40, 0x14, 0x54};
    if (row < 0 || row > 3) row = 0;
    lcd_byte(0x80 | (col + row_offsets[row]), LCD_CMD);
}

static void lcd_print(const char *s) {
    lcd_string(s);
}

static void lcd_update_display(float flow_rate, float total_volume) {
    char line1[LCD_WIDTH + 1];
    char line2[LCD_WIDTH + 1];
    snprintf(line1, sizeof(line1), "Flow: %.2f LPM", flow_rate);
    snprintf(line2, sizeof(line2), "Vol: %.2f L", total_volume);
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print(line1);
    lcd_set_cursor(0, 1);
    lcd_print(line2);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        lcd_clear();
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Warning: Failed to open I2C device at 0x%02X. LCD updates will be skipped.\n", LCD_I2C_ADDR);
    } else {
        lcd_byte(0x33, LCD_CMD);
        lcd_byte(0x32, LCD_CMD);
        lcd_byte(0x28, LCD_CMD);
        lcd_byte(0x0C, LCD_CMD);
        lcd_byte(0x06, LCD_CMD);
        lcd_clear();
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint32_t last_tick = gpioTick();
    uint32_t last_log_tick = gpioTick();
    uint32_t last_lcd_tick = gpioTick();
    int last_state = gpioRead(FLOW_SENSOR_GPIO);
    if (last_state < 0) {
        fprintf(stderr, "Error: Failed to read initial GPIO state.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    float total_volume = 0.0f;
    float last_volume = 0.0f;
    int pulse_count = 0;

    while (running) {
        int current_state = gpioRead(FLOW_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "Error: Failed to read GPIO %d.\n", FLOW_SENSOR_GPIO);
            break;
        }

        if (current_state != last_state) {
            uint32_t now = gpioTick();
            uint32_t elapsed = now - last_tick;
            if (elapsed > 0) {
                pulse_count++;
            }
            last_tick = now;
            last_state = current_state;
        }

        uint32_t now = gpioTick();
        if (now - last_log_tick >= 1000000) {
            float current_volume = (float)pulse_count / PULSES_PER_LITER;
            float flow_rate = current_volume - last_volume;
            last_volume = current_volume;
            total_volume += flow_rate;
            printf("Flow Rate: %.2f LPM, Total Volume: %.2f L\n", flow_rate, total_volume);
            fflush(stdout);
            last_log_tick = now;
        }

        if (now - last_lcd_tick >= 10000000) {
            float current_volume = (float)pulse_count / PULSES_PER_LITER;
            float flow_rate = current_volume - last_volume;
            last_volume = current_volume;
            total_volume += flow_rate;
            lcd_update_display(flow_rate, total_volume);
            last_lcd_tick = now;
        }

        gpioDelay(10000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

