/*
 * VL53L3CX Time-of-Flight multi-target sensor reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * NOTE: The VL53L3CX requires a proprietary ST firmware download (ULD) via
 * the ST Ultra Lite Driver API. This program implements the I2C communication
 * layer and application logic, but stubs the firmware download with a
 * descriptive comment. For production use, replace the stub with the
 * official ST ULD firmware download sequence.
 *
 * Wiring:
 *   VL53L3CX SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   VL53L3CX SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   VL53L3CX VDD -> 3.3V
 *   VL53L3CX GND -> GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L3CX_ADDR 0x29
#define I2C_BUS 1

/* VL53L3CX ULD API register addresses (simplified subset) */
#define VL53L3CX_REG_SOFT_RESET              0x0000
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L3CX_REG_SYSTEM_START            0x0001
#define VL53L3CX_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L3CX_REG_RESULT_DISTANCE         0x0096
#define VL53L3CX_REG_RESULT_NUM_TARGETS      0x0098
#define VL53L3CX_REG_RESULT_TARGET_DISTANCES 0x009A

#define VL53L3CX_MODEL_ID_EXPECTED 0xEA
#define MAX_TARGETS 10

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a 16-bit register address and 8-bit data value */
static int vl53l3cx_write_reg8(int handle, uint16_t reg, uint8_t data) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = data;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read a 16-bit register address and 8-bit data value */
static int vl53l3cx_read_reg8(int handle, uint16_t reg, uint8_t *data) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, (char *)data, 1) != 1) return -1;
    return 0;
}

/* Read a block of data starting at a 16-bit register address */
static int vl53l3cx_read_block(int handle, uint16_t reg, uint8_t *data, uint32_t len) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, (char *)data, len) != (int)len) return -1;
    return 0;
}

/* Read a 16-bit register address and 16-bit data value */
static int vl53l3cx_read_reg16(int handle, uint16_t reg, uint16_t *data) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    char read_buf[2];
    if (i2cReadDevice(handle, read_buf, 2) != 2) return -1;
    *data = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

/* Read a 16-bit register address and 32-bit data value */
static int vl53l3cx_read_reg32(int handle, uint16_t reg, uint32_t *data) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    char read_buf[4];
    if (i2cReadDevice(handle, read_buf, 4) != 4) return -1;
    *data = ((uint32_t)read_buf[0] << 24) |
            ((uint32_t)read_buf[1] << 16) |
            ((uint32_t)read_buf[2] << 8)  |
            (uint32_t)read_buf[3];
    return 0;
}

/* Initialize the VL53L3CX sensor */
static int vl53l3cx_init(int handle) {
    uint8_t model_id = 0;

    /* 1. Soft reset */
    if (vl53l3cx_write_reg8(handle, VL53L3CX_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* 2. Verify sensor identity */
    if (vl53l3cx_read_reg8(handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return -1;
    }
    if (model_id != VL53L3CX_MODEL_ID_EXPECTED) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0x%02X). Sensor not present?\n",
                model_id, VL53L3CX_MODEL_ID_EXPECTED);
        return -1;
    }
    printf("VL53L3CX detected. Model ID: 0x%02X\n", model_id);

    /* 3. Start ranging (simplified; in production use the full ULD API) */
    if (vl53l3cx_write_reg8(handle, VL53L3CX_REG_SYSTEM_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    return 0;
}

/* Read distance data for all detected targets */
static int vl53l3cx_read_distances(int handle, uint16_t *distances, uint8_t *num_targets) {
    uint16_t num_targets_reg = 0;
    uint16_t distance_reg = 0;
    uint8_t data[2];

    /* Read number of targets */
    if (vl53l3cx_read_reg16(handle, VL53L3CX_REG_RESULT_NUM_TARGETS, &num_targets_reg) < 0) {
        fprintf(stderr, "Error: Failed to read number of targets.\n");
        return -1;
    }
    if (num_targets_reg > MAX_TARGETS) {
        fprintf(stderr, "Warning: Target count %u exceeds max %d. Clamping.\n",
                num_targets_reg, MAX_TARGETS);
        num_targets_reg = MAX_TARGETS;
    }
    *num_targets = (uint8_t)num_targets_reg;

    /* Read distance data (16-bit each, 2 bytes per target) */
    if (vl53l3cx_read_block(handle, VL53L3CX_REG_RESULT_TARGET_DISTANCES,
                            (uint8_t *)distances, num_targets_reg * 2) < 0) {
        fprintf(stderr, "Error: Failed to read distance data.\n");
        return -1;
    }

    return 0;
}

/* Log distance data with ISO-8601 timestamp */
static void log_distances(uint16_t *distances, uint8_t num_targets) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("%s - Targets: %u\n", timestamp, num_targets);
    for (uint8_t i = 0; i < num_targets; i++) {
        printf("  Target %u: %u mm\n", i, distances[i]);
    }
    printf("\n");
}

int main(void) {
    uint16_t distances[MAX_TARGETS];
    uint8_t num_targets;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n",
                I2C_BUS, VL53L3CX_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l3cx_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L3CX initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L3CX ranging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        if (vl53l3cx_read_distances(i2c_handle, distances, &num_targets) == 0) {
            log_distances(distances, num_targets);
        } else {
            fprintf(stderr, "Warning: Failed to read distances. Retrying...\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

