        }
        gpioDelay(100000); /* 100 ms */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

