static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, pigpio_error(rc));
    }
    return rc;
}

static int si1145_init(int handle)
{
    int part_id = i2c_read_byte(handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x45).\n", part_id);
        return -1;
    }

    /* Reset the device */
    if (i2c_write_byte(handle, REG_COMMAND, CMD_RESET) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    /* Write HW_KEY to enable proper operation */
    if (i2c_write_byte(handle, REG_HW_KEY, 0x17) < 0)
        return -1;

    /* Clear any stale IRQ */
    if (i2c_write_byte(handle, REG_IRQ_STATUS, 0x0F) < 0)
        return -1;

    /* Set measurement rates to 0 (manual mode) */
    if (i2c_write_byte(handle, REG_MEAS_RATE0, 0x00) < 0)
        return -1;
    if (i2c_write_byte(handle, REG_MEAS_RATE1, 0x00) < 0)
        return -1;

    /* Enable PS and ALS interrupts */
    if (i2c_write_byte(handle, REG_IRQ_ENABLE, 0x0F) < 0)
        return -1;

    return 0;
}

static int si1145_read_proximity(int handle, uint16_t *prox)
{
    if (i2c_write_byte(handle, REG_COMMAND, CMD_PS_FORCE) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    int lo = i2c_read_byte(handle, REG_PS1_DATA0);
    int hi = i2c_read_byte(handle, REG_PS1_DATA1);
    if (lo < 0 || hi < 0)
        return -1;

    *prox = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int si1145_read_ambient_light(int handle, uint16_t *light)
{
    if (i2c_write_byte(handle, REG_COMMAND, CMD_ALS_FORCE) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    int lo = i2c_read_byte(handle, REG_ALS_VIS_DATA0);
    int hi = i2c_read_byte(handle, REG_ALS_VIS_DATA1);
    if (lo < 0 || hi < 0)
        return -1;

    *light = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Proximity: %u, Ambient Light: %u\n", ts, proximity, ambient_light);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si1145_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Si1145 initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1145 initialized. Logging to %s every 500 ms. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        uint16_t proximity = 0, ambient_light = 0;

        if (si1145_read_proximity(g_i2c_handle, &proximity) != 0) {
            fprintf(stderr, "Proximity read error — continuing.\n");
        } else if (si1145_read_ambient_light(g_i2c_handle, &ambient_light) != 0) {
            fprintf(stderr, "Ambient light read error — continuing.\n");
        } else {
            log_data(g_log_file, proximity, ambient_light);
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

