#define REG_PART_ID      0x00
#define REG_HW_KEY       0x07
#define REG_MEAS_RATE0   0x08
#define REG_MEAS_RATE1   0x09
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_PS1_DATA0    0x18
#define REG_PS1_DATA1    0x19
#define REG_CH_LIST      0x4F
#define REG_COMMAND      0x30

#define CMD_ALS_FORCE    0x06
#define CMD_PS_FORCE     0x07

#define EXPECTED_PART_ID 0x45

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X val=0x%02X rc=%d\n", reg, val, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int read_word(uint8_t reg_low, uint16_t *out) {
    uint8_t lo, hi;
    if (read_reg(reg_low, &lo) < 0) return -1;
    if (read_reg(reg_low + 1, &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int init_si1145(void) {
    uint8_t part_id;
    if (read_reg(REG_PART_ID, &part_id) < 0) return -1;
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1145 detected (PART_ID=0x%02X)\n", part_id);

    if (write_reg(REG_HW_KEY, 0x17) < 0) return -1;
    if (write_reg(REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (write_reg(REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (write_reg(REG_CH_LIST, 0x01) < 0) return -1;
    return 0;
}

static int read_si1145(uint16_t *prox, uint16_t *als) {
    if (write_reg(REG_COMMAND, CMD_ALS_FORCE) < 0) return -1;
    if (write_reg(REG_COMMAND, CMD_PS_FORCE) < 0) return -1;

    gpioDelay(10000);

    if (read_word(REG_PS1_DATA0, prox) < 0) return -1;
    if (read_word(REG_ALS_VIS_DATA0, als) < 0) return -1;
    return 0;
}

static void log_data(uint16_t prox, uint16_t als) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%u,%u\n", ts, prox, als);
    fflush(log_file);
}

