    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1145() < 0) {
        fprintf(stderr, "Si1145 init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_data.log", "a");
    if (!log_file) {
        perror("fopen");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Logging to biometric_data.log (Ctrl+C to stop)\n");

    while (!terminate) {
        uint16_t prox, als;
        if (read_si1145(&prox, &als) == 0) {
            log_data(prox, als);
        } else {
            fprintf(stderr, "Read error; continuing\n");
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

