    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file);
}

static int trigger_pulse(struct gpiod_line *trigger) {
    if (gpiod_line_set_value(trigger, 1) < 0) {
        return -1;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        return -1;
    }
    return 0;
}

static long long elapsed_us(const struct timespec *start, const struct timespec *end) {
    return (long long)(end->tv_sec - start->tv_sec) * 1000000LL +
           (end->tv_nsec - start->tv_nsec) / 1000LL;
}

