static void log_message(FILE *log_file, const char *message) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void log_distance(FILE *log_file, double distance) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file);
}

static int trigger_pulse(struct gpiod_line *trigger) {
    if (gpiod_line_set_value(trigger, 1) < 0) {
        return -1;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        return -1;
    }
    return 0;
}

