    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t red, green, blue;
    uint8_t proximity;

    while (running) {
        if (read_apds9960_data(i2c_handle, &red, &green, &blue, &proximity) == 0) {
            if (proximity > PROXIMITY_THRESHOLD) {
                log_data(log_file, red, green, blue, proximity);
            }
        } else {
            fprintf(stderr, "I2C read error, re-initializing sensor...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            usleep(100000);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to reopen I2C bus: %d\n", i2c_handle);
                break;
            }
            if (initialize_apds9960(i2c_handle) < 0) {
                fprintf(stderr, "Sensor re-initialization failed\n");
                break;
            }
        }
        usleep(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

