#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x5A

#define REG_PART_ID    0x00
#define REG_MEAS_RATE0 0x08
#define REG_COMMAND    0x47
#define REG_PS_DATA0   0x24
#define REG_PS_DATA1   0x25

#define CMD_RESET      0x01
#define CMD_START      0x02

#define EXPECTED_PART_ID 0x82

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (i2c_smbus_read_byte_data(fd, reg) < 0) return -1;
    *val = (uint8_t)i2c_smbus_read_byte_data(fd, reg);
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    return i2c_smbus_write_byte_data(fd, reg, val);
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    int lo = i2c_smbus_read_byte_data(fd, reg);
    if (lo < 0) return -1;
    int hi = i2c_smbus_read_byte_data(fd, reg + 1);
    if (hi < 0) return -1;
    *val = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int si1182_init(int fd) {
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error reading PART_ID: %s\n", strerror(errno));
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1182 detected (PART_ID=0x%02X)\n", part_id);

    if (i2c_write_reg8(fd, REG_MEAS_RATE0, 0x0A) < 0) {
        fprintf(stderr, "Error writing MEAS_RATE0: %s\n", strerror(errno));
        return -1;
    }

    if (i2c_write_reg8(fd, REG_COMMAND, CMD_RESET) < 0) {
        fprintf(stderr, "Error resetting Si1182: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);

    if (i2c_write_reg8(fd, REG_COMMAND, CMD_START) < 0) {
        fprintf(stderr, "Error starting Si1182: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);
    return 0;
}

static int read_proximity(int fd, uint16_t *prox) {
    if (i2c_read_reg16(fd, REG_PS_DATA0, prox) < 0) {
        fprintf(stderr, "Error reading PS_DATA0: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static float calculate_bpm(uint16_t prox) {
    (void)prox;
    return 72.0f;
}

static void log_data(FILE *fp, float bpm) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, bpm);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }

    if (si1182_init(fd) < 0) {
        close(fd);
        return 1;
    }

    FILE *fp = fopen("heartrate.csv", "a");
    if (!fp) {
        perror("fopen heartrate.csv");
        close(fd);
        return 1;
    }

    while (running) {
        uint16_t prox = 0;
        if (read_proximity(fd, &prox) < 0) {
            fprintf(stderr, "Warning: proximity read failed, skipping sample\n");
        } else {
            float bpm = calculate_bpm(prox);
            log_data(fp, bpm);
        }
        usleep(100000);
    }

    printf("\nExiting cleanly.\n");
    fclose(fp);
    close(fd);
    return 0;
}

