#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define TRIGGER_PIN 17

#define REG_SYSRANGE_START 0x00
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS 0x14
#define REG_SYSTEM_INTERRUPT_CLEAR 0x0B

#define MEASURE_TIMEOUT_MS 100
#define POLL_DELAY_US 1000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write failed at reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "I2C write (reg select) failed at 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "I2C read failed at reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int verify_sensor(int handle) {
    uint8_t id = 0;
    if (i2c_read_bytes(handle, 0x010F, &id, 1) != 0) return -1;
    if (id != 0xEA) {
        fprintf(stderr, "Sensor not found (ID=0x%02X, expected 0xEA)\n", id);
        return -1;
    }
    return 0;
}

static int read_distance(int handle, uint16_t *distance_mm) {
    if (i2c_write_byte(handle, REG_SYSRANGE_START, 0x01) != 0) return -1;

    uint8_t status = 0;
    int elapsed = 0;
    while (elapsed < MEASURE_TIMEOUT_MS) {
        if (i2c_read_bytes(handle, REG_RESULT_INTERRUPT_STATUS, &status, 1) != 0) return -1;
        if (status & 0x01) break;
        gpioDelay(POLL_DELAY_US);
        elapsed++;
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "Measurement timeout\n");
        return -1;
    }

    uint8_t data[14];
    if (i2c_read_bytes(handle, REG_RESULT_RANGE_STATUS, data, 14) != 0) return -1;

    *distance_mm = ((uint16_t)data[10] << 8) | data[11];

    if (i2c_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) return -1;

    return 0;
}

static void log_distance(FILE *fp, uint16_t distance) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%u\n", timestamp, distance);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", VL53L0X_ADDR);
        gpioTerminate();
        return 1;
    }

    if (verify_sensor(i2c_handle) != 0) {
        fprintf(stderr, "VL53L0X sensor not detected\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP);

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("VL53L0X distance logger started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(TRIGGER_PIN) == 0) {
            gpioDelay(20000);
            if (!running) break;
            uint16_t distance = 0;
            if (read_distance(i2c_handle, &distance) == 0) {
                log_distance(log_file, distance);
                printf("Distance: %u mm\n", distance);
            } else {
                fprintf(stderr, "Failed to read distance\n");
            }
        }
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

