#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define CH101_ADDR     0x45
#define TRIGGER_REG    0x00
#define DISTANCE_REG   0x02
#define SAMPLE_US      200000   /* 200 ms */
#define TRIGGER_US     50000    /* 50 ms  */
#define LOG_FILE       "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int trigger_sensor(int handle)
{
    char buf[2] = { TRIGGER_REG, 0x01 };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error: failed to write trigger register\n");
        return -1;
    }
    gpioDelay(TRIGGER_US);
    return 0;
}

static int read_distance(int handle, int *distance_mm)
{
    char reg = DISTANCE_REG;
    char data[2] = {0, 0};

    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to set distance register pointer\n");
        return -1;
    }
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read distance data\n");
        return -1;
    }
    *distance_mm = (data[0] << 8) | data[1];
    return 0;
}

