#define ICU20201_REG_DISTANCE 0x0010
#define ICU20201_REG_STATUS 0x0012
#define ICU20201_REG_CONFIG 0x0014

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    if (i2cWriteDevice(handle, buf, 4) != 0) {
        return -1;
    }
    return 0;
}

static int read_distance(int handle, float *distance) {
    uint16_t dist_raw;
    if (i2c_read_reg16(handle, ICU20201_REG_DISTANCE, &dist_raw) != 0) {
        return -1;
    }
    *distance = (float)dist_raw / 10.0f;
    return 0;
}

static int log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

