        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("ICU-20201 detected (Product ID: 0x%04X). Starting distance monitoring...\n", product_id);

    while (running) {
        float distance;
        if (read_distance(i2c_handle, &distance) != 0) {
            fprintf(stderr, "Error reading distance from sensor. Retrying in 100 ms...\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Warning: Failed to log distance.\n");
            }
            control_led(LED_GPIO, (distance < DISTANCE_THRESHOLD) ? 1 : 0);
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    control_led(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

