#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define WHO_AM_I_REG 0x00
#define EXPECTED_WHO_AM_I 0x01
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100
#define LOG_FILE "tof_log.txt"
#define POLL_DELAY_US 50000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int initialize_sensor(int handle) {
    uint8_t who_am_i = 0;
    if (read_register(handle, WHO_AM_I_REG, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != EXPECTED_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, EXPECTED_WHO_AM_I);
        return -1;
    }
    printf("ICU-20201 detected (WHO_AM_I = 0x%02X).\n", who_am_i);
    return 0;
}

static int read_distance(int handle, uint16_t *distance_mm) {
    uint8_t buf[2];
    int rc = i2cReadI2CBlockData(handle, 0x02, (char *)buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C block read error: %d\n", rc);
        return -1;
    }
    *distance_mm = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static void log_data(uint16_t distance, int threshold) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %u mm, Threshold: %d mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance, threshold);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;

    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold. Using default: %d mm\n", DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting distance monitoring (threshold: %d mm). Press Ctrl+C to exit.\n", threshold);

    while (running) {
        uint16_t distance = 0;
        if (read_distance(i2c_handle, &distance) == 0) {
            log_data(distance, threshold);
            if (distance < threshold) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
            gpioWrite(LED_GPIO, 0);
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

