        fprintf(stderr, "I2C read short: got %zd, expected %zu\n", n, len);
        return -1;
    }
    return 0;
}

static int read_distance(int fd, int *distance_out) {
    uint8_t cmd[4] = {0x50, 0x0A, 0x00, 0x01};
    uint8_t resp[15];

    if (i2c_write_cmd(fd, cmd, sizeof(cmd)) != 0) {
        return -1;
    }

    usleep(SAMPLE_DELAY_MS * 1000);

    if (i2c_read_resp(fd, resp, sizeof(resp)) != 0) {
        return -1;
    }

    if (resp[0] != 0x50) {
        fprintf(stderr, "Invalid response header: 0x%02X\n", resp[0]);
        return -1;
    }

    uint16_t dist = ((uint16_t)resp[11] << 8) | resp[12];
    *distance_out = (int)dist;
    return 0;
}

static int log_intrusion(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return -1;
        }
    }

    if (fprintf(log_fp, "%s - Intrusion detected! Average distance: %d mm\n", timestamp, distance) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, B5L_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", B5L_I2C_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("B5L-LD50-07050 intrusion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int total_distance = 0;
        int valid_samples = 0;

        for (int i = 0; i < NUM_SAMPLES; i++) {
            int distance;
            if (read_distance(i2c_fd, &distance) == 0) {
                total_distance += distance;
                valid_samples++;
            } else {
                fprintf(stderr, "Sample %d failed\n", i + 1);
            }
            usleep(SAMPLE_DELAY_MS * 1000);
        }

        if (valid_samples > 0) {
            int avg_distance = total_distance / valid_samples;
            if (avg_distance < DISTANCE_THRESHOLD) {
                if (log_intrusion(avg_distance) != 0) {
                    fprintf(stderr, "Logging failed\n");
                }
            }
        } else {
            fprintf(stderr, "No valid samples in this cycle\n");
        }

        usleep(CYCLE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

