                I2C_BUS, VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_vl53l0x(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int distance = read_distance(g_i2c_handle);
        if (distance >= 0) {
            print_timestamp();
            printf(" Distance: %d mm\n", distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: failed to read distance\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

