#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI1182_ADDR    0x39
#define REG_CONFIG     0x18
#define REG_IRQ_STATUS 0x25
#define REG_PROX_LSB   0x2A
#define REG_PROX_MSB   0x2B
#define CONFIG_PROX_EN 0x01
#define POLL_DELAY_US  500000
#define MAX_RETRIES    10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0)
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    return rc;
}

static int read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0)
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
    return rc;
}

static int read_proximity(int handle, uint16_t *prox)
{
    int lsb = read_reg(handle, REG_PROX_LSB);
    if (lsb < 0)
        return -1;
    int msb = read_reg(handle, REG_PROX_MSB);
    if (msb < 0)
        return -1;
    *prox = (uint16_t)((msb << 8) | lsb);
    return 0;
}

static int init_sensor(int handle)
{
    if (write_reg(handle, REG_CONFIG, CONFIG_PROX_EN) < 0)
        return -1;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, SI1182_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed (check wiring / sensor present)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1182 proximity sensor reading started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int ready = -1;
        for (int i = 0; i < MAX_RETRIES && g_running; i++) {
            ready = read_reg(g_i2c_handle, REG_IRQ_STATUS);
            if (ready >= 0 && (ready & 0x01))
                break;
            gpioDelay(10000);
        }

        if (!g_running)
            break;

        if (ready < 0) {
            fprintf(stderr, "IRQ status read error — bus error or sensor absent\n");
        } else if (!(ready & 0x01)) {
            printf("Data not ready (IRQ=0x%02X)\n", ready);
        } else {
            uint16_t prox;
            if (read_proximity(g_i2c_handle, &prox) == 0) {
                printf("Proximity: %u\n", prox);
            } else {
                fprintf(stderr, "Proximity read error\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

