#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define OPT3101_I2C_ADDR 0x44
#define I2C_BUS 1
#define POLL_INTERVAL_US 500000

/* OPT3101 Register Map */
#define REG_RESULT_DISTANCE 0x00
#define REG_RESULT_AMBIENT  0x02
#define REG_ERROR_FLAGS     0x04
#define REG_CONFIG          0x06
#define REG_INT_STATUS      0x08
#define REG_INT_CLEAR       0x0A
#define REG_SYSTEM_CTRL     0x0C
#define REG_SYSTEM_STATUS   0x0E
#define REG_SYSTEM_RESET    0x10
#define REG_SYSTEM_ID       0x12

/* Configuration Register (0x06) */
#define CFG_ENABLE          0x01
#define CFG_AUTO_RESET      0x02
#define CFG_AUTO_CLEAR      0x04
#define CFG_AUTO_CONFIG     0x08
#define CFG_AUTO_START      0x10
#define CFG_AUTO_STOP       0x20
#define CFG_AUTO_RESET_EN   0x40
#define CFG_AUTO_RESET_CLR  0x80

/* System Control Register (0x0C) */
#define SYS_CTRL_RESET      0x01
#define SYS_CTRL_START      0x02

/* System Status Register (0x0E) */
#define SYS_STATUS_BUSY     0x01
#define SYS_STATUS_ERROR    0x02

/* Error Flags Register (0x04) */
#define ERR_FLAG_DATA_READY 0x01
#define ERR_FLAG_AMBIENT    0x02
#define ERR_FLAG_RANGE      0x04
#define ERR_FLAG_CONFIG     0x08
#define ERR_FLAG_SYSTEM     0x10

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "Error reading block from reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int init_opt3101(void) {
    uint8_t id = 0;
    if (read_reg(REG_SYSTEM_ID, &id) < 0) {
        fprintf(stderr, "Sensor not responding at address 0x%02X\n", OPT3101_I2C_ADDR);
        return -1;
    }
    printf("OPT3101 ID: 0x%02X\n", id);

    /* Software reset */
    if (write_reg(REG_SYSTEM_RESET, 0x01) < 0) return -1;
    gpioDelay(10000); /* 10 ms */

    /* Clear any pending interrupts */
    if (write_reg(REG_INT_CLEAR, 0xFF) < 0) return -1;

    /* Configure register: enable auto-reset, auto-clear, auto-config, auto-start */
    uint8_t cfg = CFG_AUTO_RESET | CFG_AUTO_CLEAR | CFG_AUTO_CONFIG | CFG_AUTO_START;
    if (write_reg(REG_CONFIG, cfg) < 0) return -1;

    /* Start measurement */
    if (write_reg(REG_SYSTEM_CTRL, SYS_CTRL_START) < 0) return -1;

    gpioDelay(100000); /* 100 ms for first measurement */
    return 0;
}

static int read_sensor_data(uint16_t *distance, uint16_t *ambient, uint8_t *error_flags) {
    uint8_t buf[4];
    if (read_block(REG_RESULT_DISTANCE, buf, 4) < 0) return -1;

    *distance = (uint16_t)((buf[0] << 8) | buf[1]);
    *ambient  = (uint16_t)((buf[2] << 8) | buf[3]);
    *error_flags = buf[3];

    return 0;
}

static void log_data(uint16_t distance, uint16_t ambient, uint8_t error_flags) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Distance: %u mm, Ambient: %u lux, Error Flags: 0x%02X\n",
           timestamp, distance, ambient, error_flags);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3101_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, OPT3101_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_opt3101() < 0) {
        fprintf(stderr, "OPT3101 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("OPT3101 sensor logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t distance = 0, ambient = 0;
        uint8_t error_flags = 0;

        if (read_sensor_data(&distance, &ambient, &error_flags) == 0) {
            log_data(distance, ambient, error_flags);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

