#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define TIMEOUT_US  200000   /* 200 ms timeout for echo edges */
#define MAX_PULSE_US 38000   /* ~12 m round-trip limit for HC-SR04 */
#define SAMPLE_PERIOD_US 1000000 /* 1 second between readings */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance in centimetres using the HC-SR04.
 * Returns -1.0 on timeout or invalid pulse.
 */
static float read_distance(void) {
    /* Send 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1.0f;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Error: echo rising-edge timeout\n");
            return -1.0f;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - echo_start) > TIMEOUT_US) {
            fprintf(stderr, "Error: echo falling-edge timeout\n");
            return -1.0f;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_us = echo_end - echo_start;
    if (pulse_us == 0 || pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "Error: invalid pulse duration %u us\n", pulse_us);
        return -1.0f;
    }

    /* Distance = (pulse_us * 0.0343) / 2  (cm) */
    return (float)pulse_us * 0.0343f / 2.0f;
}

static void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
    fflush(stdout);
}

int main(void) {
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize trigger low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle */
    gpioDelay(500000); /* 500 ms */

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");
    printf("Note: HC-SR04 operates at 5V; use a 1 kOhm resistor in series on the echo line.\n");
    printf("      The Pi GPIO is only 3.3V tolerant.\n");

    while (running) {
        float distance = read_distance();
        if (distance >= 0.0f) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Warning: reading failed, will retry next cycle\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

