#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define UART_PORT "/dev/serial0"
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 1.0f
#define RANGE_RESOLUTION 0.0486f
#define NUM_RANGE_BINS 64
#define DATA_FRAME_SIZE (8 + (NUM_RANGE_BINS * 2))
#define LOG_FILE "intrusion_log.csv"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B115200);
    cfsetispeed(&tty, B115200);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (n == 0) return -1;
        total += (size_t)n;
    }
    return 0;
}

static int read_data_frame(int fd, uint8_t *frame) {
    uint8_t magic[8] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    if (memcmp(frame, magic, 8) != 0) {
        fprintf(stderr, "Invalid magic word\n");
        return -1;
    }

    if (read_exact(fd, frame + 8, DATA_FRAME_SIZE - 8) != 0) {
        fprintf(stderr, "Error reading data frame\n");
        return -1;
    }
    return 0;
}

static int process_range_data(const uint8_t *frame, float *range_profile) {
    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        uint16_t raw = (uint16_t)frame[8 + i * 2] | ((uint16_t)frame[8 + i * 2 + 1] << 8);
        range_profile[i] = (float)raw * RANGE_RESOLUTION;
    }
    return 0;
}

static int detect_intrusion(const float *range_profile, float threshold) {
    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        if (range_profile[i] <= threshold) {
            return 1;
        }
    }
    return 0;
}

static void log_intrusion(FILE *fp, float distance) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.3f\n", timestamp, distance);
    fflush(fp);
}

static void cleanup(void) {
    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_PORT);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    uint8_t frame[DATA_FRAME_SIZE];
    float range_profile[NUM_RANGE_BINS];

    while (running) {
        if (read_exact(uart_fd, frame, DATA_FRAME_SIZE) != 0) {
            fprintf(stderr, "UART read error or sensor absent\n");
            break;
        }

        if (process_range_data(frame, range_profile) != 0) {
            fprintf(stderr, "Range data processing error\n");
            continue;
        }

        if (detect_intrusion(range_profile, DISTANCE_THRESHOLD)) {
            gpioWrite(GPIO_LED, 1);
            float min_distance = 100.0f;
            for (int i = 0; i < NUM_RANGE_BINS; i++) {
                if (range_profile[i] < min_distance) {
                    min_distance = range_profile[i];
                }
            }
            log_intrusion(log_fp, min_distance);
            gpioDelay(2000000);
            gpioWrite(GPIO_LED, 0);
        }
    }

    cleanup();
    return 0;
}

