#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x69
#define DIST_REG_HIGH  0x31
#define DIST_REG_LOW   0x32
#define GPIO_PIN       17
#define DIST_THRESHOLD 10.0f
#define LOG_FILE       "distance_log.txt"
#define SAMPLE_US      100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_distance(int handle, float *distance)
{
    int hi, lo;

    hi = i2cReadByteData(handle, DIST_REG_HIGH);
    if (hi < 0) {
        fprintf(stderr, "I2C read error (high byte reg 0x31): %d\n", hi);
        return -1;
    }

    lo = i2cReadByteData(handle, DIST_REG_LOW);
    if (lo < 0) {
        fprintf(stderr, "I2C read error (low byte reg 0x32): %d\n", lo);
        return -1;
    }

    uint16_t raw = ((uint16_t)hi << 8) | (uint16_t)lo;
    *distance = (float)raw / 10.0f;
    return 0;
}

static int log_distance(float distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance);
    fclose(fp);
    return 0;
}

static void trigger_alert(float distance)
{
    if (distance < DIST_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1);
        gpioDelay(200000);  /* 200 ms */
        gpioWrite(GPIO_PIN, 0);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", GPIO_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_PIN, 0);

    printf("ICU-20201 distance monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance;

        if (read_distance(g_i2c_handle, &distance) != 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Logging failed.\n");
            }
            trigger_alert(distance);
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(GPIO_PIN, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

