#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L1X_ADDR             0x29
#define VL53L1X_REG_MODEL_ID     0x010F
#define VL53L1X_REG_SYSRANGE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x078
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x014
#define VL53L1X_REG_SYSTEM_MODE_START 0x007
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x0014
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG 0x0089
#define VL53L1X_REG_RESULT_INT_STATUS 0x013
#define VL53L1X_MODEL_ID         0xEA
#define I2C_BUS                 1
#define LOG_FILE                "distance_log.csv"
#define POLL_TIMEOUT_MS         100
#define LOOP_DELAY_MS           100
#define STOP_THRESHOLD_MM       300
#define APPROACH_THRESHOLD_MM   600
#define SLOW_THRESHOLD_MM       1200

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *value)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, (char *)value, 1) != 1)
        return -1;
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0)
        return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;
    if (i2c_read_reg8(handle, VL53L1X_REG_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: failed to read model ID register.\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, VL53L1X_MODEL_ID);
        return -1;
    }

    if (i2c_write_reg8(handle, VL53L1X_REG_SYSRANGE_START, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write SYSRANGE_START.\n");
        return -1;
    }
    gpioDelay(2000);

    if (i2c_write_reg8(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start ranging.\n");
        return -1;
    }

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    int elapsed = 0;

    while (elapsed < POLL_TIMEOUT_MS) {
        if (i2c_read_reg8(handle, VL53L1X_REG_RESULT_INT_STATUS, &status) < 0) {
            fprintf(stderr, "Error: failed to read interrupt status.\n");
            return -1;
        }
        if (status & 0x01)
            break;
        gpioDelay(1000);
        elapsed++;
    }
    if (elapsed >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "Error: timeout waiting for data-ready.\n");
        return -1;
    }

    uint16_t range = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range) < 0) {
        fprintf(stderr, "Error: failed to read range status.\n");
        return -1;
    }

    if (i2c_write_reg8(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error: failed to clear interrupt.\n");
        return -1;
    }

    *distance_mm = range;
    return 0;
}

static void log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%u\n", timestamp, distance_mm);
    fflush(fp);
}

static void print_guidance(uint16_t distance_mm)
{
    if (distance_mm < STOP_THRESHOLD_MM)
        printf("STOP\n");
    else if (distance_mm < APPROACH_THRESHOLD_MM)
        printf("APPROACH\n");
    else if (distance_mm < SLOW_THRESHOLD_MM)
        printf("SLOW\n");
    else
        printf("CLEAR\n");
    fflush(stdout);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,distance_mm\n");
        fflush(g_log_file);
    }

    printf("Parking assistance system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance = 0;
        if (vl53l1x_read_distance(g_i2c_handle, &distance) < 0) {
            fprintf(stderr, "Warning: sensor read failed, retrying...\n");
            gpioDelay(LOOP_DELAY_MS * 1000);
            continue;
        }
        log_distance(g_log_file, distance);
        print_guidance(distance);
        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

