#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x45
#define LED_GPIO       18
#define SAMPLE_US      100000   /* 100 ms between samples */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000    /* 10 ms between retries */
#define MIN_DISTANCE_MM 50.0f
#define MAX_DISTANCE_MM 500.0f
#define MIN_FREQ_HZ     1.0f
#define MAX_FREQ_HZ     10.0f

/* CH201 register addresses (16-bit, big-endian on the wire) */
#define REG_PRODUCT_ID  0x0000
#define REG_DISTANCE   0x0010
#define REG_STATUS     0x0012
#define REG_CONFIG     0x0014

#define EXPECTED_ID    0x2010

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address, then a 16-bit value (big-endian). */
static int i2c_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read N bytes starting at a 16-bit register address. */
static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *data, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) != 0)
        return -1;
    return i2cReadDevice(handle, (char *)data, len);
}

static int read_register(int handle, uint16_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (i2c_read_reg16(handle, reg, buf, 2) != 2)
        return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int write_register(int handle, uint16_t reg, uint16_t value)
{
    return i2c_write_reg16(handle, reg, value);
}

static int init_sensor(int handle)
{
    uint16_t product_id = 0;
    if (read_register(handle, REG_PRODUCT_ID, &product_id) != 0) {
        fprintf(stderr, "Error: failed to read product ID (sensor absent or bus error).\n");
        return -1;
    }
    if (product_id != EXPECTED_ID) {
        fprintf(stderr, "Error: unexpected product ID 0x%04X (expected 0x%04X).\n",
                product_id, EXPECTED_ID);
        return -1;
    }
    printf("CH201 detected (product ID 0x%04X).\n", product_id);

    /* Standby -> start measurement. */
    if (write_register(handle, REG_CONFIG, 0x0001) != 0) {
        fprintf(stderr, "Error: failed to write config register.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */
    return 0;
}

static int read_distance(int handle, float *distance_mm)
{
    uint16_t raw = 0;
    int attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (read_register(handle, REG_DISTANCE, &raw) == 0)
            break;
        fprintf(stderr, "Warning: I2C read failed (attempt %d/%d).\n",
                attempt + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
    }
    if (attempt == MAX_RETRIES) {
        fprintf(stderr, "Error: distance read failed after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    /* CH201 distance is a 16-bit value in mm; bit 15 is valid flag. */
    if (raw & 0x8000) {
        *distance_mm = (float)(raw & 0x7FFF);
        return 0;
    }
    fprintf(stderr, "Warning: distance register indicates no valid data (raw=0x%04X).\n", raw);
    return -1;
}

static void map_distance_to_frequency(float distance, float *frequency)
{
    if (distance < MIN_DISTANCE_MM)
        distance = MIN_DISTANCE_MM;
    if (distance > MAX_DISTANCE_MM)
        distance = MAX_DISTANCE_MM;
    *frequency = MAX_FREQ_HZ -
                 ((distance - MIN_DISTANCE_MM) /
                  (MAX_DISTANCE_MM - MIN_DISTANCE_MM)) *
                 (MAX_FREQ_HZ - MIN_FREQ_HZ);
}

static void blink_led(int gpio, float frequency_hz)
{
    static int led_state = 0;
    static uint32_t last_tick = 0;
    uint32_t now = gpioTick();

    if (last_tick == 0)
        last_tick = now;

    if (frequency_hz > 0.0f) {
        uint32_t half_period_us = 500000 / (uint32_t)frequency_hz;
        if (now - last_tick >= half_period_us) {
            led_state = !led_state;
            gpioWrite(gpio, led_state);
            last_tick = now;
        }
    } else {
        /* Force off if frequency is clamped out of range. */
        gpioWrite(gpio, 0);
    }
}

static void log_data(float distance, float frequency)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Distance: %.2f mm, Frequency: %.2f Hz\n",
           timestamp, distance, frequency);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: sensor initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    printf("Starting distance measurement. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = 0.0f;
        if (read_distance(g_i2c_handle, &distance) != 0) {
            fprintf(stderr, "Error: distance read failed; continuing.\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float frequency = 0.0f;
        map_distance_to_frequency(distance, &frequency);

        blink_led(LED_GPIO, frequency);
        log_data(distance, frequency);

        gpioDelay(SAMPLE_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

