#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x28
#define TRIGGER_CMD 0x01
#define MEAS_DELAY_US 10000
#define READ_DELAY_US 10000
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3
#define LOG_FILE "distance_log.csv"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_measurement(int handle) {
    char cmd = TRIGGER_CMD;
    int rc = i2cWriteDevice(handle, &cmd, 1);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed (rc=%d)\n", rc);
        return -1;
    }
    return 0;
}

static int read_distance(int handle, uint16_t *distance_cm) {
    char buf[2];
    int rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 2)\n", rc);
        return -1;
    }
    *distance_cm = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int log_distance(const char *filename, uint16_t distance_cm) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%u\n", timestamp, distance_cm);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d) - sensor may be absent at 0x%02X\n", i2c_handle, MLX75030_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX75030 distance logger started. Logging to %s\n", LOG_FILE);

    while (running) {
        int retries = 0;
        int success = 0;
        uint16_t distance_cm = 0;

        while (retries < MAX_RETRIES && !success && running) {
            if (trigger_measurement(i2c_handle) == 0) {
                gpioDelay(MEAS_DELAY_US);
                if (read_distance(i2c_handle, &distance_cm) == 0) {
                    success = 1;
                } else {
                    retries++;
                    if (retries < MAX_RETRIES) {
                        fprintf(stderr, "Warning: read failed, retry %d/%d\n", retries, MAX_RETRIES);
                        gpioDelay(10000);
                    }
                }
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "Warning: trigger failed, retry %d/%d\n", retries, MAX_RETRIES);
                    gpioDelay(10000);
                }
            }
        }

        if (success) {
            if (log_distance(LOG_FILE, distance_cm) != 0) {
                fprintf(stderr, "Warning: failed to log distance\n");
            } else {
                printf("Distance: %u cm\n", distance_cm);
            }
        } else {
            fprintf(stderr, "Error: failed to read distance after %d retries\n", MAX_RETRIES);
        }

        if (running) {
            gpioDelay(SAMPLE_INTERVAL_US);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

