#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x49
#define MEAS_TRIGGER   0x04
#define MEAS_STATUS    0x06
#define DIST_HIGH      0x08
#define DIST_LOW       0x09
#define LOG_FILE       "distance_log.csv"
#define SAMPLE_MS      500
#define MEAS_TIMEOUT_MS 50

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, val, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write address 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read from 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int ch101_trigger_and_wait(int fd)
{
    if (i2c_write_reg8(fd, MEAS_TRIGGER, 0x01) < 0)
        return -1;

    for (int i = 0; i < MEAS_TIMEOUT_MS; i++) {
        uint8_t status;
        if (i2c_read_reg8(fd, MEAS_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            return 0;
        usleep(1000);
    }
    fprintf(stderr, "CH-101 measurement timeout\n");
    return -1;
}

static int ch101_read_distance(int fd, uint16_t *distance_mm)
{
    if (ch101_trigger_and_wait(fd) < 0)
        return -1;

    uint8_t high, low;
    if (i2c_read_reg8(fd, DIST_HIGH, &high) < 0)
        return -1;
    if (i2c_read_reg8(fd, DIST_LOW, &low) < 0)
        return -1;

    *distance_mm = ((uint16_t)high << 8) | (uint16_t)low;
    return 0;
}

static void log_data(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%u\n", ts, distance_mm);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                CH101_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    fprintf(g_log, "# timestamp,distance_mm\n");
    fflush(g_log);

    while (g_running) {
        uint16_t dist;
        if (ch101_read_distance(g_i2c_fd, &dist) == 0) {
            log_data(g_log, dist);
        } else {
            fprintf(stderr, "Sensor read failed; skipping sample\n");
        }
        usleep(SAMPLE_MS * 1000);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_log) {
        fflush(g_log);
        fclose(g_log);
        g_log = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

