#define VL53L5CX_ADDR 0x29
#define I2C_BUS "/dev/i2c-1"
#define NUM_ZONES 64
#define POLL_INTERVAL_MS 500

static volatile sig_atomic_t running = 1;
static int g_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *value) {
    uint8_t cmd[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "I2C write (reg select) for 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_vl53l5cx(int fd) {
    if (i2c_write_reg8(fd, 0x0000, 0x01) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, 0x001E, 0x01) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, 0x001F, 0x01) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, 0x0020, 0x01) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, 0x0021, 0x01) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, 0x0022, 0x01) < 0) return -1;
    usleep(10000);
