#define MLX75030_ADDR 0x4C
#define READ_DISTANCE_REG 0x00
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_distance(uint16_t *distance) {
    char buf[2];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cReadI2CBlockData(i2c_handle, READ_DISTANCE_REG, buf, 2);
        if (result == 2) {
            *distance = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "I2C read error (attempt %d/%d): %d\n", attempt + 1, MAX_RETRIES, result);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

static void log_distance(uint16_t distance) {
    struct timespec ts;
    struct tm tm_info;
    char time_str[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("%s.%03ld Distance: %u mm\n", time_str, ts.tv_nsec / 1000000, distance);
    fflush(stdout);
}

int main(void) {
    uint16_t distance;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", MLX75030_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX75030 ToF sensor reader started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

