#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100
#define I2C_BUS 1
#define POLL_DELAY_US 500000

/* VL53L1X register addresses */
#define REG_SOFT_RESET              0x0001
#define REG_I2C_SLAVE__DEVICE_ADDRESS 0x0001
#define REG_SYSTEM__MODE_START      0x0007
#define REG_RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_write16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int vl53l1x_read16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    char data_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, data_buf, 2) != 2) return -1;
    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    /* Soft reset */
    if (vl53l1x_write16(handle, REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (vl53l1x_write16(handle, REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(1000);

    /* Set I2C slave address (already 0x29, but confirm) */
    if (vl53l1x_write16(handle, REG_I2C_SLAVE__DEVICE_ADDRESS, VL53L1X_ADDR) < 0) return -1;

    /* Start continuous ranging mode */
    if (vl53l1x_write16(handle, REG_SYSTEM__MODE_START, 0x01) < 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int read_distance(int handle, uint16_t *distance) {
    return vl53l1x_read16(handle, REG_RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM, distance);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error initializing VL53L1X sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int buzzer_active = 0;

    while (running) {
        uint16_t distance = 0;
        if (read_distance(i2c_handle, &distance) < 0) {
            fprintf(stderr, "Error reading distance from sensor\n");
            if (vl53l1x_init(i2c_handle) < 0) {
                fprintf(stderr, "Re-initialization failed, retrying next cycle\n");
            }
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (distance < DISTANCE_THRESHOLD) {
            if (!buzzer_active) {
                gpioWrite(BUZZER_GPIO, 1);
                buzzer_active = 1;
            }
        } else {
            if (buzzer_active) {
                gpioWrite(BUZZER_GPIO, 0);
                buzzer_active = 0;
            }
        }

        printf("Distance: %u mm\n", distance);
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

