        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        log_error("Failed to set trigger pin mode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        log_error("Failed to set echo pin mode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        log_error("Failed to set servo pin mode");
        gpioTerminate();
        return 1;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    while (running) {
        float distance = measure_distance();
        if (distance < 0) {
            log_error("Sensor timeout or read error");
        } else {
            int angle = map_distance_to_angle(distance);
            if (set_servo_angle(angle) < 0) {
                log_error("Failed to set servo angle");
            }
