#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <stdint.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   400.0
#define DISTANCE_THRESHOLD 30.0
#define TIMEOUT_US     30000
#define POLL_DELAY_US  100000

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick   = 0;
static volatile int      echo_state = 0;   /* 0=idle, 1=rising seen, 2=falling seen */
static volatile int      echo_error = 0;
static volatile int      running    = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        start_tick = tick;
        echo_state = 1;
    } else if (level == 0 && echo_state == 1) {
        end_tick = tick;
        echo_state = 2;
    }
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

static double calculate_distance(uint32_t start, uint32_t end)
{
    uint32_t diff = end - start;  /* pigpio ticks are 32-bit; subtraction wraps correctly */
    return (double)diff * SPEED_OF_SOUND / 2000000.0;
}

static void cleanup(void)
{
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register echo alert.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_state = 0;
        echo_error = 0;

        trigger_sensor();

        uint32_t elapsed = 0;
        while (running && echo_state != 2 && elapsed < TIMEOUT_US) {
            gpioDelay(100);
            elapsed += 100;
        }

        if (echo_state != 2) {
            echo_error = 1;
            fprintf(stderr, "Warning: echo timeout - sensor absent or not responding.\n");
        } else {
            double distance = calculate_distance(start_tick, end_tick);

            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                echo_error = 1;
                fprintf(stderr, "Warning: invalid distance reading (%.2f cm).\n", distance);
            } else {
                printf("Distance: %.2f cm\n", distance);
            }
        }

        if (echo_error == 0) {
            gpioWrite(BUZZER_PIN, distance < DISTANCE_THRESHOLD ? 1 : 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

