#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 200
#define I2C_BUS 1
#define LOG_FILE "gate_log.txt"
#define MQTT_CLIENT_ID "gate_controller"
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883

#define VL53L1X_REG_SOFT_RESET 0x0003
#define VL53L1X_REG_SYSTEM_START 0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static MQTTClient mqtt_client;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int vl53l1x_write16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

int vl53l1x_read16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int vl53l1x_init(int handle) {
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_START, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_START, 0x01) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

int vl53l1x_read_distance(int handle) {
    uint16_t status, distance;
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0) return -1;
    if (status & 0x01) {
        if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_DISTANCE, &distance) < 0) return -1;
        return (int)distance;
    }
    return -1;
}

void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec, event);
    fflush(log_file);
}

void control_servo(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse = (int)(500 + (angle * 2000 / 180));
    gpioServo(SERVO_PIN, pulse);
}

void mqtt_message_arrived(void *context, char *topicName, int topicLen, MQTTClient_message *message) {
    (void)context;
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(topicName, "gate/force_open") == 0) {
            control_servo(90);
            log_event("Gate opened remotely.");
        } else if (strcmp(topicName, "gate/force_close") == 0) {
            control_servo(0);
            log_event("Gate closed remotely.");
        } else if (strcmp(topicName, "gate/status_request") == 0) {
            char status[100];
            snprintf(status, sizeof(status), "Gate status: %s", (gpioServo(SERVO_PIN, 0) == 0) ? "closed" : "open");
            MQTTClient_message pubmsg = MQTTClient_message_initializer;
            pubmsg.payload = status;
            pubmsg.payloadlen = strlen(status);
            pubmsg.qos = 1;
            pubmsg.retained = 0;
            MQTTClient_deliveryToken token;
            MQTTClient_publishMessage(mqtt_client, "gate/status", &pubmsg, &token);
        }
    }
    MQTTClient_freeMessage(&message);
    MQTTClient_free(topicName);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X init failed\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO set mode failed\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    control_servo(0);

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    MQTTClient_create(&mqtt_client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (MQTTClient_connect(mqtt_client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT connect failed\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    MQTTClient_setCallbacks(mqtt_client, NULL, NULL, mqtt_message_arrived, NULL);
    MQTTClient_subscribe(mqtt_client, "gate/#", 1);

    while (running) {
        int distance = vl53l1x_read_distance(i2c_handle);
        if (distance >= 0) {
            if (distance < DISTANCE_THRESHOLD) {
                if (gpioServo(SERVO_PIN, 90) == 0) {
                    log_event("Object detected, gate opening.");
                }
            } else {
                if (gpioServo(SERVO_PIN, 0) == 0) {
                    log_event("Path clear, gate closing.");
                }
            }
        } else {
            fprintf(stderr, "I2C read error\n");
            log_event("I2C read error");
        }
        gpioDelay(100000);
    }

    control_servo(0);
    MQTTClient_unsubscribe(mqtt_client, "gate/#");
    MQTTClient_disconnect(mqtt_client, 1000);
    MQTTClient_destroy(&mqtt_client);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

