#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <stdint.h>

#define TRIG_PIN 23
#define ECHO_PIN 24

#define TRIG_PULSE_US 10
#define ECHO_TIMEOUT_US 60000
#define MIN_PULSE_US 100
#define MAX_PULSE_US 30000
#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define SAMPLE_INTERVAL_US 200000

static volatile uint32_t g_rising_tick = 0;
static volatile uint32_t g_falling_tick = 0;
static volatile int g_echo_received = 0;
static volatile int g_echo_pending = 0;
static FILE *g_log_file = NULL;
static volatile sig_atomic_t g_running = 1;

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_rising_tick = tick;
        g_echo_pending = 1;
    } else if (level == 0 && g_echo_pending) {
        g_falling_tick = tick;
        g_echo_received = 1;
        g_echo_pending = 0;
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIG_PIN %d as output.\n", TRIG_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN %d.\n", ECHO_PIN);
    }

    if (gpioWrite(TRIG_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise TRIG_PIN %d to LOW.\n", TRIG_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert callback on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void trigger_sensor(void)
{
    if (gpioWrite(TRIG_PIN, 1) != 0) {
        fprintf(stderr, "Warning: failed to set TRIG_PIN HIGH.\n");
        return;
    }
    gpioDelay(TRIG_PULSE_US);
    if (gpioWrite(TRIG_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to set TRIG_PIN LOW.\n");
    }
}

static double calculate_distance(uint32_t pulse_duration_us)
{
    return (double)pulse_duration_us * SPEED_OF_SOUND_CM_PER_US / 2.0;
}

static void log_distance(double distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);

    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s Distance: %.2f cm\n", timestamp, distance);
        fflush(g_log_file);
    }
}

static void log_warning(const char *message)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(stderr, "%s WARNING: %s\n", timestamp, message);

    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s WARNING: %s\n", timestamp, message);
        fflush(g_log_file);
    }
}

int main(void)
{
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log_file = fopen("distance_log.txt", "a");
    if (g_log_file == NULL) {
        perror("Error opening distance_log.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");
    printf("Note: ECHO output is 5V; use a voltage divider or logic-level converter.\n");

    while (g_running) {
        memset(&g_rising_tick, 0, sizeof(g_rising_tick));
        memset(&g_falling_tick, 0, sizeof(g_falling_tick));
        g_echo_received = 0;
        g_echo_pending = 0;

        trigger_sensor();

        uint32_t start_wait = gpioTick();
        while (!g_echo_received && g_running) {
            if ((gpioTick() - start_wait) > ECHO_TIMEOUT_US) {
                break;
            }
            gpioDelay(100);
        }

        if (!g_echo_received) {
            log_warning("Timeout: no echo received within 60 ms");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        uint32_t pulse_duration;
        if (g_falling_tick >= g_rising_tick) {
            pulse_duration = g_falling_tick - g_rising_tick;
        } else {
