#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_OPEN_PIN 18
#define GATE_CLOSE_PIN 19
#define DISTANCE_THRESHOLD_MM 200
#define POLL_INTERVAL_US 500000
#define LOG_FILE "gate_events.log"

/* VL53L1X 16-bit register addresses */
#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_MODE 0x0001
#define VL53L1X_REG_RANGE_CONFIG 0x0002
#define VL53L1X_REG_INTERMEASUREMENT 0x0003
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(log_file, "%s: %s\n", ts, event);
    fflush(log_file);
}

static int vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteI2CBlockData(handle, buf[0], &buf[1], 2);
}

static int vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteI2CBlockData(handle, reg_buf[0], &reg_buf[1], 1) < 0) return -1;
    return i2cReadI2CBlockData(handle, reg_buf[0], (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(1000);
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_INTERMEASUREMENT, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE, 0x01) < 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm) {
    uint8_t status_buf[2];
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, status_buf, 2) < 0) return -1;
    uint16_t status = ((uint16_t)status_buf[0] << 8) | status_buf[1];
    if ((status & 0x01) == 0) return 1; /* no new data ready */
    uint8_t dist_buf[2];
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) return -1;
    *distance_mm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

static void control_gate(int open) {
    if (gpioWrite(GATE_OPEN_PIN, open ? 1 : 0) < 0) {
        log_event("ERROR: Failed to write GATE_OPEN_PIN");
        return;
    }
    if (gpioWrite(GATE_CLOSE_PIN, open ? 0 : 1) < 0) {
        log_event("ERROR: Failed to write GATE_CLOSE_PIN");
        return;
    }
    if (open) {
        log_event("Gate opened");
    } else {
        log_event("Gate closed");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);
    gpioSetMode(GATE_OPEN_PIN, PI_INPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_INPUT);
    gpioTerminate();
    if (log_file) {
        log_event("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        log_event("ERROR: i2cOpen failed");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X init failed\n");
        log_event("ERROR: VL53L1X init failed");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT);
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);

    log_event("Program started");

    while (running) {
        uint16_t distance = 0;
        int rc = vl53l1x_read_distance(i2c_handle, &distance);
        if (rc == 0) {
            if (distance < DISTANCE_THRESHOLD_MM) {
                control_gate(1);
            } else {
                control_gate(0);
            }
        } else if (rc == 1) {
            /* No new data ready yet */
        } else {
            log_event("ERROR: VL53L1X read failed");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

