#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define TRIGGER_PIN 24
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18

#define DISTANCE_THRESHOLD_LOW 100   /* mm (10 cm) */
#define DISTANCE_THRESHOLD_HIGH 300  /* mm (30 cm) */

#define REG_SOFT_RESET 0x0000
#define REG_SYSTEM_START 0x0000
#define REG_DATA_READY 0x0089
#define REG_DISTANCE_MSB 0x0096
#define REG_DISTANCE_LSB 0x0097

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error: soft reset write failed\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    if (i2c_write_reg16(handle, REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Error: start measurement write failed\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t ready = 0;
    int timeout = 100; /* 100 * 10 ms = 1 s max */

    while (timeout-- > 0) {
        if (i2c_read_reg16(handle, REG_DATA_READY, &ready, 1) != 1) {
            fprintf(stderr, "Error: data ready read failed\n");
            return -1;
        }
        if (ready & 0x01) break;
        gpioDelay(10000); /* 10 ms */
    }
    if (timeout < 0) {
        fprintf(stderr, "Error: data ready timeout\n");
        return -1;
    }

    uint8_t dist_buf[2];
    if (i2c_read_reg16(handle, REG_DISTANCE_MSB, dist_buf, 2) != 2) {
        fprintf(stderr, "Error: distance read failed\n");
        return -1;
    }
    *distance = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

static void motor_forward(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 1);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    printf("Motor: FORWARD\n");
}

static void motor_backward(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
