#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define MPR121_ADDR 0x5A
#define I2C_BUS "/dev/i2c-1"

#define GPIO_CHIP "gpiochip0"
#define LED1_PIN 17
#define LED2_PIN 18
#define LED3_PIN 27
#define LED4_PIN 22

#define REG_TOUCHSTATUS_L 0x00
#define REG_TOUCHSTATUS_H 0x01
#define REG_ELECONFIG0 0x5E
#define REG_SOFTRESET 0x80
#define REG_MHDR 0x2B
#define REG_NHDR 0x2C
#define REG_NCLR 0x2D
#define REG_FDLR 0x2E
#define REG_AUTO_CONFIG0 0x5A
#define REG_AUTO_CONFIG1 0x5B
#define REG_AUTO_CONFIG2 0x5C
#define REG_AUTO_CONFIG3 0x5D
#define REG_USL 0x7B
#define REG_LSL 0x7D
#define REG_TL 0x7E
#define REG_CL 0x7F

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_lines[4] = {NULL, NULL, NULL, NULL};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, msg);
    fflush(log_file);
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        log_message("I2C write error");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        log_message("I2C write (reg select) error");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        log_message("I2C read error");
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    if (i2c_write_reg8(fd, REG_SOFTRESET, 0x63) < 0) return -1;
    usleep(10000);

    uint8_t whoami;
    if (i2c_read_reg8(fd, REG_ELECONFIG0, &whoami) < 0) return -1;
    if (whoami != 0x00) {
        log_message("MPR121 not responding after reset");
        return -1;
    }

    if (i2c_write_reg8(fd, REG_ELECONFIG0, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, REG_NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, REG_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg8(fd, REG_FDLR, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_AUTO_CONFIG0, 0x0B) < 0) return -1;
    if (i2c_write_reg8(fd, REG_AUTO_CONFIG1, 0xC8) < 0) return -1;
    if (i2c_write_reg8(fd, REG_AUTO_CONFIG2, 0x82) < 0) return -1;
    if (i2c_write_reg8(fd, REG_AUTO_CONFIG3, 0xB4) < 0) return -1;
    if (i2c_write_reg8(fd, REG_USL, 0xC8) < 0) return -1;
    if (i2c_write_reg8(fd, REG_LSL, 0x82) < 0) return -1;
    if (i2c_write_reg8(fd, REG_TL, 0xB4) < 0) return -1;
    if (i2c_write_reg8(fd, REG_CL, 0x00) < 0) return -1;

    if (i2c_write_reg8(fd, REG_ELECONFIG0, 0x0C) < 0) return -1;
    usleep(10000);
    return 0;
}

static void set_led_pattern(int pattern) {
    int vals[4] = {0, 0, 0, 0};
    switch (pattern) {
        case 0: vals[0] = 1; vals[1] = 0; vals[2] = 0; vals[3] = 0; break;
        case 1: vals[0] = 0; vals[1] = 1; vals[2] = 0; vals[3] = 0; break;
        case 2: vals[0] = 1; vals[1] = 1; vals[2] = 0; vals[3] = 0; break;
        case 3: vals[0] = 0; vals[1] = 0; vals[2] = 1; vals[3] = 0; break;
        case 4: vals[0] = 1; vals[1] = 0; vals[2] = 1; vals[3] = 0; break;
        case 5: vals[0] = 0; vals[1] = 1; vals[2] = 1; vals[3] = 0; break;
        case 6: vals[0] = 1; vals[1] = 1; vals[2] = 1; vals[3] = 0; break;
        case 7: vals[0] = 0; vals[1] = 0; vals[2] = 0; vals[3] = 1; break;
        case 8: vals[0] = 1; vals[1] = 0; vals[2] = 0; vals[3] = 1; break;
        case 9: vals[0] = 0; vals[1] = 1; vals[2] = 0; vals[3] = 1; break;
        case 10: vals[0] = 1; vals[1] = 1; vals[2] = 0; vals[3] = 1; break;
        case 11: vals[0] = 0; vals[1] = 0; vals[2] = 1; vals[3] = 1; break;
        case 12: vals[0] = 1; vals[1] = 0; vals[2] = 1; vals[3] = 1; break;
        case 13: vals[0] = 0; vals[1] = 1; vals[2] = 1; vals[3] = 1; break;
        case 14: vals[0] = 1; vals[1] = 1; vals[2] = 1; vals[3] = 1; break;
        default: vals[0] = 0; vals[1] = 0; vals[2] = 0; vals[3] = 0; break;
    }
    gpiod_line_set_value(led_lines[0], vals[0]);
    gpiod_line_set_value(led_lines[1], vals[1]);
    gpiod_line_set_value(led_lines[2], vals[2]);
    gpiod_line_set_value(led_lines[3], vals[3]);
}

static void cleanup(void) {
    if (log_file) { fclose(log_file); log_file = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) { gpiod_line_set_value(led_lines[i], 0); gpiod_line_release(led_lines[i]); led_lines[i] = NULL; }
    }
    if (chip) { gpiod_chip_close(chip); chip = NULL; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen("installation.log", "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_message("Failed to open I2C bus");
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        log_message("Failed to set I2C slave address");
        cleanup();
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        log_message("MPR121 initialization failed");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        log_message("Failed to open GPIO chip");
        cleanup();
        return 1;
    }

    int pins[4] = {LED1_PIN, LED2_PIN, LED3_PIN, LED4_PIN};
    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!led_lines[i]) {
            log_message("Failed to get GPIO line");
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "mpr121_led", 0) < 0) {
            log_message("Failed to request GPIO line as output");
            cleanup();
            return 1;
        }
    }

    log_message("Installation started");

    while (running) {
        uint8_t lo, hi;
        if (i2c_read_reg8(i2c_fd, REG_TOUCHSTATUS_L, &lo) < 0 ||
            i2c_read_reg8(i2c_fd, REG_TOUCHSTATUS_H, &hi) < 0) {
            log_message("Error reading touch status");
            usleep(50000);
            continue;
        }

        uint16_t touch_status = ((uint16_t)hi << 8) | lo;
        int active = 0;
        for (int i = 0; i < 12; i++) {
            if (touch_status & (1 << i)) {
                active = 1;
                int pattern = i % 16;
                set_led_pattern(pattern);
                char msg[128];
                snprintf(msg, sizeof(msg), "Electrode %d touched, LED pattern %d", i, pattern);
                log_message(msg);
            }
        }
        if (!active) {
            set_led_pattern(0);
            log_message("No electrode touched");
        }
        usleep(50000);
    }

    log_message("Installation stopped");
    cleanup();
    return 0;
}

