        case 7: vals[0] = 0; vals[1] = 0; vals[2] = 0; vals[3] = 1; break;
        case 8: vals[0] = 1; vals[1] = 0; vals[2] = 0; vals[3] = 1; break;
        case 9: vals[0] = 0; vals[1] = 1; vals[2] = 0; vals[3] = 1; break;
        case 10: vals[0] = 1; vals[1] = 1; vals[2] = 0; vals[3] = 1; break;
        case 11: vals[0] = 0; vals[1] = 0; vals[2] = 1; vals[3] = 1; break;
        case 12: vals[0] = 1; vals[1] = 0; vals[2] = 1; vals[3] = 1; break;
        case 13: vals[0] = 0; vals[1] = 1; vals[2] = 1; vals[3] = 1; break;
        case 14: vals[0] = 1; vals[1] = 1; vals[2] = 1; vals[3] = 1; break;
        default: vals[0] = 0; vals[1] = 0; vals[2] = 0; vals[3] = 0; break;
    }
    gpiod_line_set_value(led_lines[0], vals[0]);
    gpiod_line_set_value(led_lines[1], vals[1]);
    gpiod_line_set_value(led_lines[2], vals[2]);
    gpiod_line_set_value(led_lines[3], vals[3]);
}

static void cleanup(void) {
    if (log_file) { fclose(log_file); log_file = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) { gpiod_line_set_value(led_lines[i], 0); gpiod_line_release(led_lines[i]); led_lines[i] = NULL; }
    }
    if (chip) { gpiod_chip_close(chip); chip = NULL; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen("installation.log", "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_message("Failed to open I2C bus");
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        log_message("Failed to set I2C slave address");
        cleanup();
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        log_message("MPR121 initialization failed");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        log_message("Failed to open GPIO chip");
        cleanup();
        return 1;
    }

    int pins[4] = {LED1_PIN, LED2_PIN, LED3_PIN, LED4_PIN};
    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!led_lines[i]) {
            log_message("Failed to get GPIO line");
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "mpr121_led", 0) < 0) {
            log_message("Failed to request GPIO line as output");
            cleanup();
            return 1;
        }
    }

    log_message("Installation started");

    while (running) {
        uint8_t lo, hi;
        if (i2c_read_reg8(i2c_fd, REG_TOUCHSTATUS_L, &lo) < 0 ||
            i2c_read_reg8(i2c_fd, REG_TOUCHSTATUS_H, &hi) < 0) {
            log_message("Error reading touch status");
            usleep(50000);
            continue;
        }

        uint16_t touch_status = ((uint16_t)hi << 8) | lo;
        int active = 0;
        for (int i = 0; i < 12; i++) {
            if (touch_status & (1 << i)) {
                active = 1;
                int pattern = i % 16;
                set_led_pattern(pattern);
                char msg[128];
                snprintf(msg, sizeof(msg), "Electrode %d touched, LED pattern %d", i, pattern);
                log_message(msg);
            }
        }
        if (!active) {
            set_led_pattern(0);
            log_message("No electrode touched");
        }
        usleep(50000);
    }

    log_message("Installation stopped");
    cleanup();
    return 0;
}

