#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define LED_GPIO 27
#define LOG_FILE "proximity.log"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_SOFTRESET 0x80
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n", reg, value, pigpio_error(rc));
    }
    return rc;
}

static int mpr121_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, pigpio_error(rc));
    }
    return rc;
}

static int mpr121_init(int handle) {
    if (mpr121_write_reg(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write_reg(handle, MPR121_ELECTRODE_CONFIG, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDLT, 0x00) < 0) return -1;

    if (mpr121_write_reg(handle, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_CONFIG2, 0x20) < 0) return -1;

    if (mpr121_write_reg(handle, MPR121_E0TTH, 0x0A) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_E0RTH, 0x05) < 0) return -1;

    if (mpr121_write_reg(handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int mpr121_read_touch_status(int handle) {
    int low = mpr121_read_reg(handle, MPR121_TOUCHSTATUS_L);
    if (low < 0) return -1;
    int high = mpr121_read_reg(handle, MPR121_TOUCHSTATUS_H);
    if (high < 0) return -1;
    return (high << 8) | low;
}

static void log_proximity_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Proximity detected on electrode 0\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    int id = mpr121_read_reg(i2c_handle, MPR121_ELECTRODE_CONFIG);
    if (id < 0) {
        fprintf(stderr, "MPR121 not detected on I2C bus 1 at 0x%02X\n", MPR121_ADDR);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int status = mpr121_read_touch_status(i2c_handle);
        if (status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        if (status & 0x01) {
            printf("Proximity detected!\n");
            gpioWrite(LED_GPIO, 1);
            log_proximity_event();
            gpioDelay(1000000);
            gpioWrite(LED_GPIO, 0);
        }
        gpioDelay(50000);
    }

    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

