#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TIMEOUT_US  30000
#define MIN_CM      2.0f
#define MAX_CM      400.0f
#define SPEED_CM_US 0.0343f

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trig_line = NULL;
static struct gpiod_line *echo_line = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (trig_line) {
        gpiod_line_release(trig_line);
        trig_line = NULL;
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
        echo_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(trig_line, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void trigger_pulse(void) {
    gpiod_line_set_value(trig_line, 0);
    usleep(5);
    gpiod_line_set_value(trig_line, 1);
    usleep(10);
    gpiod_line_set_value(trig_line, 0);
}

static long long elapsed_us(const struct timespec *start, const struct timespec *end) {
    return (long long)(end->tv_sec - start->tv_sec) * 1000000LL +
           (end->tv_nsec - start->tv_nsec) / 1000LL;
}

static int wait_for_rising(struct timespec *timeout) {
    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    t1 = t0;
    t1.tv_sec += TIMEOUT_US / 1000000;
    t1.tv_nsec += (TIMEOUT_US % 1000000) * 1000;

    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &t1);
        if (elapsed_us(&t0, &t1) >= TIMEOUT_US) {
            return -1;
        }
    }
    return 0;
}

static int wait_for_falling(struct timespec *timeout) {
    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    t1 = t0;
    t1.tv_sec += TIMEOUT_US / 1000000;
    t1.tv_nsec += (TIMEOUT_US % 1000000) * 1000;

    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &t1);
        if (elapsed_us(&t0, &t1) >= TIMEOUT_US) {
            return -1;
        }
    }
    return 0;
}

static float measure_distance(void) {
    struct timespec t_start, t_echo_start, t_echo_end;

    trigger_pulse();

    if (wait_for_rising(&t_start) < 0) {
        return -1.0f;
    }

    if (wait_for_falling(&t_echo_start) < 0) {
        return -1.0f;
    }

    if (wait_for_rising(&t_echo_end) < 0) {
        return -1.0f;
    }

    long long pulse_us = elapsed_us(&t_echo_start, &t_echo_end);
    float distance = (pulse_us * SPEED_CM_US) / 2.0f;

    if (distance < MIN_CM || distance > MAX_CM) {
        return -1.0f;
    }

    return distance;
}

static void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (distance < 0.0f) {
        fprintf(log_fp, "%s,ERROR: Sensor timeout or out of range\n", timestamp);
    } else {
        fprintf(log_fp, "%s,%.2f\n", timestamp, distance);
    }
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        float distance = measure_distance();
        log_distance(distance);
        sleep(1);
    }

    cleanup();
    return 0;
}

