#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TRIGGER_PULSE_US 10
#define SAMPLE_INTERVAL_S 1.0
#define MIN_PULSE_US 58
#define MAX_PULSE_US 25000
#define SPEED_OF_SOUND_CM_S 34300.0
#define TIMEOUT_US 30000

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile int      g_echo_state = 0;   /* 0=idle, 1=rising seen, 2=done */
static volatile int      g_pulse_us   = 0;
static FILE             *g_log_fp     = NULL;
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * pigpio ISR callback for the ECHO pin.
 *  level  0 = falling edge, 1 = rising edge
 *  tick   is the 32-bit microsecond counter (wraps every ~71.6 min)
 */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_start_tick = tick;
        g_echo_state = 1;
    } else if (level == 0 && g_echo_state == 1) {
        /* Falling edge: echo pulse ends */
        g_end_tick = tick;
        g_pulse_us = (uint32_t)(g_end_tick - g_start_tick);
        g_echo_state = 2;
    }
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double calculate_distance_cm(uint32_t pulse_us)
{
    return (double)pulse_us * SPEED_OF_SOUND_CM_S / 2.0e6;
}

static void log_distance(double distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s, Distance: %.2f cm\n", timestamp, distance_cm);
    fflush(g_log_fp);
}

int main(void)
{
    int rc;

    /* --- Initialize pigpio --- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", rc);
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    /* --- Register ISR on ECHO pin --- */
    rc = gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL);
    if (rc < 0) {
        fprintf(stderr, "Error: cannot register ISR on ECHO_PIN %d (code %d).\n", ECHO_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("HC-SR04 distance logger started. TRIG=GPIO%d, ECHO=GPIO%d, log=%s\n",
           TRIGGER_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        g_echo_state = 0;
        g_pulse_us   = 0;

        trigger_sensor();

        /* Wait for echo with a timeout */
        uint32_t wait_start = gpioTick();
        while (g_running && g_echo_state != 2) {
            if ((uint32_t)(gpioTick() - wait_start) > TIMEOUT_US) {
                fprintf(stderr, "Warning: echo timeout (no echo received this cycle).\n");
                break;
            }
            gpioDelay(100);  /* 100 us poll */
        }

        if (g_echo_state == 2 && g_pulse_us > 0) {
            if (g_pulse_us >= MIN_PULSE_US && g_pulse_us <= MAX_PULSE_US) {
                double dist_cm = calculate_distance_cm(g_pulse_us);
                log_distance(dist_cm);
                printf("Distance: %.2f cm (pulse %u us)\n", dist_cm, g_pulse_us);
            } else {
                fprintf(stderr, "Warning: pulse width %u us out of range, skipping.\n",
                        g_pulse_us);
            }
        }

        /* Sleep for the sample interval (interruptible by signals) */
        struct timespec ts;
        ts.tv_sec  = (time_t)SAMPLE_INTERVAL_S;
        ts.tv_nsec = (long)(SAMPLE_INTERVAL_S * 1e9) % 1000000000L;
        nanosleep(&ts, NULL);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioWrite(TRIGGER_PIN, 0);

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

