#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define TRIGGER_PIN    27

#define REG_SYSRANGE_START  0x0020
#define REG_RESULT_RANGE_STATUS 0x0016
#define REG_RESULT_DISTANCE  0x0014
#define REG_SYSTEM_MODE      0x0018
#define REG_SYSTEM_INTERMEASUREMENT 0x0019

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int vl53l1x_write_reg(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int vl53l1x_read_reg(int handle, uint16_t reg, uint8_t *value)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, (char *)value, 1) != 1)
        return -1;
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance, uint8_t *status)
{
    uint8_t dist_low, dist_high, status_byte;

    if (vl53l1x_read_reg(handle, REG_RESULT_DISTANCE, &dist_low) < 0)
        return -1;
    if (vl53l1x_read_reg(handle, REG_RESULT_DISTANCE + 1, &dist_high) < 0)
        return -1;
    if (vl53l1x_read_reg(handle, REG_RESULT_RANGE_STATUS, &status_byte) < 0)
        return -1;

    *distance = (uint16_t)((dist_high << 8) | dist_low);
    *status   = status_byte;
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    closelog();
}

int main(void)
{
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install signal handlers: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(TRIGGER_PIN, 1);

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device on bus %d at addr 0x%02X: %d",
               I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    if (vl53l1x_write_reg(g_i2c_handle, REG_SYSTEM_MODE, 0x00) < 0 ||
        vl53l1x_write_reg(g_i2c_handle, REG_SYSTEM_INTERMEASUREMENT, 0x00) < 0 ||
        vl53l1x_write_reg(g_i2c_handle, REG_SYSRANGE_START, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to initialise VL53L1X sensor");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "VL53L1X sensor initialised successfully");

    while (g_running) {
        uint16_t distance;
        uint8_t  status;

        if (vl53l1x_read_distance(g_i2c_handle, &distance, &status) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

            if (status == 0x00)
                syslog(LOG_INFO, "%s - Distance: %u mm, Status: OK", ts, distance);
            else
                syslog(LOG_ERR, "%s - Distance: %u mm, Status: 0x%02X", ts, distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read distance from VL53L1X sensor");
        }

        gpioDelay(100000);
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    cleanup();
    return EXIT_SUCCESS;
}

