#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define GATE_GPIO      24
#define DISTANCE_THRESHOLD_CM 20
#define POLL_DELAY_US  100000  /* 100 ms */
#define LOG_FILE       "gate_log.txt"

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define REG_MODEL_ID          0x010F
#define REG_SYSRANGE_START    0x0015
#define REG_RANGE_CONFIG      0x0021
#define REG_RESULT_DISTANCE   0x0089

#define EXPECTED_MODEL_ID     0xEA

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* Write one byte to a 16-bit VL53L1X register */
static int vl53l1x_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write failed at reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

/* Read one byte from a 16-bit VL53L1X register */
static int vl53l1x_read_reg8(int handle, uint16_t reg, uint8_t *value)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) failed at reg 0x%04X\n", reg);
        return -1;
    }
    char data;
    if (i2cReadDevice(handle, &data, 1) != 1) {
        fprintf(stderr, "I2C read failed at reg 0x%04X\n", reg);
        return -1;
    }
    *value = (uint8_t)data;
    return 0;
}

/* Read a 16-bit big-endian value from two consecutive 16-bit registers */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    uint8_t lo, hi;
    if (vl53l1x_read_reg8(handle, reg, &hi) != 0)
        return -1;
    if (vl53l1x_read_reg8(handle, reg + 1, &lo) != 0)
        return -1;
    *value = ((uint16_t)hi << 8) | lo;
    return 0;
}

static int init_sensor(int handle)
{
    uint8_t model_id;
    if (vl53l1x_read_reg8(handle, REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID 0x%02X (expected 0x%02X)\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L1X detected (model ID 0x%02X)\n", model_id);

    /* Set ranging mode to short (0x00) */
    if (vl53l1x_write_reg8(handle, REG_RANGE_CONFIG, 0x00) != 0)
        return -1;

    /* Start ranging */
    if (vl53l1x_write_reg8(handle, REG_SYSRANGE_START, 0x01) != 0)
        return -1;

    return 0;
}

static int read_distance_cm(int handle, int *distance_cm)
{
    uint16_t raw;
    if (vl53l1x_read_reg16(handle, REG_RESULT_DISTANCE, &raw) != 0)
        return -1;
    *distance_cm = (int)(raw / 10);  /* convert mm to cm */
    return 0;
}

static void log_event(const char *msg)
{
    if (!log_file)
        return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", ts, msg);
    fflush(log_file);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0);  /* gate closed at startup */

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_event("System started: gate closed, sensor initialised");

    int gate_open = 0;
    int consecutive_errors = 0;

    while (!terminate) {
        int distance_cm;
        if (read_distance_cm(i2c_handle, &distance_cm) == 0) {
            consecutive_errors = 0;
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %d cm", distance_cm);
            log_event(msg);

            if (distance_cm < DISTANCE_THRESHOLD_CM && !gate_open) {
                gpioWrite(GATE_GPIO, 1);
                gate_open = 1;
                log_event("Gate opened");
            } else if (distance_cm >= DISTANCE_THRESHOLD_CM && gate_open) {
                gpioWrite(GATE_GPIO, 0);
                gate_open = 0;
                log_event("Gate closed");
            }
        } else {
            consecutive_errors++;
            char msg[128];
            snprintf(msg, sizeof(msg), "Read error (consecutive: %d)", consecutive_errors);
            log_event(msg);
            if (consecutive_errors >= 10) {
                log_event("Too many consecutive errors, aborting");
                break;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    gpioWrite(GATE_GPIO, 0);
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    if (log_file)
        fclose(log_file);
    gpioTerminate();
    return 0;
}

