#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000
#define SERVO_MIN_US     500
#define SERVO_MAX_US     2500
#define SERVO_DEFAULT_DEG 90
#define SERVO_RANGE_DEG  180
#define SAMPLE_COUNT     5
#define LOOP_DELAY_US    100000

static volatile sig_atomic_t running = 1;
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick   = 0;
static volatile int      echo_done  = 0;
static volatile int      echo_seen  = 0;

static double distance_history[SAMPLE_COUNT];
static int    history_index = 0;
static int    history_filled = 0;
static double current_distance = -1.0;

static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        start_tick = tick;
        echo_seen  = 0;
    } else if (level == 0) {
        end_tick   = tick;
        echo_seen  = 1;
    }
}

static double calculate_distance(uint32_t pulse_us) {
    if (pulse_us == 0 || pulse_us > ECHO_TIMEOUT_US) return -1.0;
    return (double)pulse_us * 0.0343 / 2.0;
}

static double moving_average(double new_value) {
    distance_history[history_index] = new_value;
    history_index = (history_index + 1) % SAMPLE_COUNT;
    if (history_filled < SAMPLE_COUNT) history_filled++;
    double sum = 0.0;
    for (int i = 0; i < history_filled; i++) sum += distance_history[i];
    return sum / history_filled;
}

static double map_distance_to_angle(double distance) {
    if (distance < 2.0) distance = 2.0;
    if (distance > 400.0) distance = 400.0;
    double log_dist = log10(distance);
    double log_max  = log10(400.0);
    double log_min  = log10(2.0);
    double norm     = (log_dist - log_min) / (log_max - log_min);
    return norm * SERVO_RANGE_DEG;
}

static int set_servo_angle(double angle) {
    if (angle < 0.0) angle = 0.0;
    if (angle > 180.0) angle = 180.0;
    int pulse_us = (int)(SERVO_MIN_US +
        (angle / 180.0) * (SERVO_MAX_US - SERVO_MIN_US));
    return gpioServo(SERVO_PIN, pulse_us);
}

static int log_data(double distance, double angle) {
    if (log_file == NULL) return -1;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            distance, angle);
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        gpioTerminate();
        return 1;
    }

    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set echo alert\n");
        gpioTerminate();
        return 1;
    }

    for (int i = 0; i < SAMPLE_COUNT; i++) distance_history[i] = 0.0;

    log_file = fopen("distance_log.csv", "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "Timestamp,Distance_cm,Servo_Angle_deg\n");
    fflush(log_file);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t t0 = gpioTick();
        echo_done = 0;

        while (!echo_done && (gpioTick() - t0) < ECHO_TIMEOUT_US) {
            gpioDelay(100);
        }

        if (echo_seen) {
            uint32_t pulse_us = end_tick - start_tick;
            if (pulse_us > ECHO_TIMEOUT_US) {
                current_distance = -1.0;
            } else {
                current_distance = calculate_distance(pulse_us);
            }
        } else {
            current_distance = -1.0;
        }

        double avg_dist = moving_average(current_distance);

        if (avg_dist < 0.0) {
            avg_dist = 0.0;
        }

        double angle = map_distance_to_angle(avg_dist);
        if (set_servo_angle(angle) < 0) {
            fprintf(stderr, "Failed to set servo angle\n");
        }

        log_data(avg_dist, angle);
        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    return 0;
}

