#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

#define SI1102_ADDR 0x60
#define PROX_REG_HIGH 0x08
#define PROX_REG_LOW 0x09
#define GPIO_PIN 27
#define DEFAULT_THRESHOLD 1000
#define LOG_FILE "proximity.log"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static int threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t running = 1;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int proximity_data_ready = 0;
static volatile int proximity_value = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", address, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_proximity(int *proximity) {
    int high = i2cReadByteData(i2c_handle, PROX_REG_HIGH);
    if (high < 0) {
        fprintf(stderr, "Error reading proximity high byte: %d\n", high);
        return -1;
    }
    int low = i2cReadByteData(i2c_handle, PROX_REG_LOW);
    if (low < 0) {
        fprintf(stderr, "Error reading proximity low byte: %d\n", low);
        return -1;
    }
    *proximity = (high << 8) | low;
    return 0;
}

static void log_proximity(int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        fprintf(log_file, "%s, %d, %s\n", timestamp, proximity, (proximity <= threshold) ? "SAFE" : "ALERT");
        fflush(log_file);
    }
    pthread_mutex_unlock(&log_mutex);
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    int prox;
    if (read_proximity(&prox) == 0) {
        proximity_value = prox;
        proximity_data_ready = 1;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_handle = i2cOpen(1, strtol(optarg, NULL, 0), 0);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
                    return 1;
                }
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c(SI1102_ADDR) != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", GPIO_PIN);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error setting pull-down on GPIO %d\n", GPIO_PIN);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(GPIO_PIN, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler on GPIO %d\n", GPIO_PIN);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Proximity sensor monitoring started. Threshold: %d\n", threshold);

    while (running) {
        if (proximity_data_ready) {
            log_proximity(proximity_value);
            proximity_data_ready = 0;
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

