#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SPEAKER_PIN 18

#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000
#define MIN_DISTANCE  2.0
#define MAX_DISTANCE  200.0
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  200000
#define LOOP_DELAY_US    10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        return -1;
    }
    if (gpioSetMode(SPEAKER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set speaker pin mode\n");
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low\n");
        return -1;
    }

    return 0;
}

static double measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0;
    }

    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() >= timeout_tick) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() >= timeout_tick) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    double distance = (double)pulse_width / 58.0;
    return distance;
}

static int set_frequency(double distance) {
    double frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) *
                       (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);

    if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
    if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;

    int pwm_range = 255;
    int pwm_dutycycle = 128;

    if (gpioSetPWMfrequency(SPEAKER_PIN, (int)frequency) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        return -1;
    }
    if (gpioSetPWMrange(SPEAKER_PIN, pwm_range) < 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        return -1;
    }
    if (gpioPWM(SPEAKER_PIN, pwm_dutycycle) < 0) {
        fprintf(stderr, "Error: failed to start PWM\n");
        return -1;
    }

    printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (initialize_gpio() < 0) {
        return 1;
    }

    double previous_frequency = MIN_FREQUENCY;

    while (running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Warning: distance measurement failed, keeping previous frequency\n");
        } else {
            if (set_frequency(distance) < 0) {
                fprintf(stderr, "Warning: failed to set frequency\n");
            }
            previous_frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) *
                                 (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioPWM(SPEAKER_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return 0;
}

