#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define SPEED_OF_SOUND 29.1f
#define MIN_DISTANCE 2.0f
#define MAX_DISTANCE 400.0f
#define TIMEOUT_US 50000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioWrite(TRIGGER_PIN, 0);
    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static float measure_distance(void) {
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin low timeout\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin high timeout\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    float distance = (float)pulse_width / 2.0f / SPEED_OF_SOUND;
    return distance;
}

static void print_distance(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        printf("Invalid reading\n");
    } else {
        printf("Distance: %.2f cm\n", distance);
        if (distance < 10.0f) {
            printf("Too close!\n");
        }
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    while (running) {
        trigger_sensor();
        float distance = measure_distance();
        if (distance >= 0.0f) {
            print_distance(distance);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

