#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define CS_PIN 8

#define REG_TRIGGER 0x00
#define REG_RANGE 0x02
#define REG_MEAS_MODE 0x01
#define REG_DIST_LOW 0x0C
#define REG_DIST_HIGH 0x0D

#define LOG_FILE "distance_log.csv"

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg | 0x80), (char)value };
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write error: reg=0x%02X, val=0x%02X\n", reg, value);
        return -1;
    }
    return 0;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg & 0x7F), 0x00 };
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read error: reg=0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int read_distance(uint16_t *distance) {
    uint8_t low, high;
    if (spi_read_register(REG_DIST_LOW, &low) != 0) return -1;
    if (spi_read_register(REG_DIST_HIGH, &high) != 0) return -1;
    *distance = ((uint16_t)high << 8) | low;
    return 0;
}

static int log_distance(uint16_t distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(log_file, "%s,%u\n", ts, distance) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (spi_write_register(REG_MEAS_MODE, 0x01) != 0 ||
        spi_write_register(REG_RANGE, 0x00) != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        if (spi_write_register(REG_TRIGGER, 0x01) != 0) {
            fprintf(stderr, "Trigger write failed\n");
            gpioDelay(100000);
            continue;
        }
        gpioDelay(100000);

        uint16_t distance;
        if (read_distance(&distance) != 0) {
            fprintf(stderr, "Distance read failed\n");
        } else {
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
        }
    }

    cleanup();
    return 0;
}

