#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_I2C_ADDR 0x60
#define I2C_BUS "/dev/i2c-1"
#define CSV_FILE "proximity_log.csv"
#define ALS_VIS_REG_LOW 0x22
#define ALS_VIS_REG_HIGH 0x23
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_si1175(int fd) {
    /* Minimal initialization: enable ALS visible channel (register 0x03 bit 0 = 1) */
    if (i2c_write_byte(fd, 0x03, 0x01) < 0) {
        fprintf(stderr, "Failed to enable ALS visible channel\n");
        return -1;
    }
    return 0;
}

static int read_als_visible(int fd, uint16_t *als_visible) {
    uint8_t low, high;
    if (i2c_read_byte(fd, ALS_VIS_REG_LOW, &low) < 0) return -1;
    if (i2c_read_byte(fd, ALS_VIS_REG_HIGH, &high) < 0) return -1;
    *als_visible = ((uint16_t)high << 8) | low;
    return 0;
}

static int log_data(FILE *fp, uint16_t als_visible) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%u\n", timestamp, als_visible) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1175_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1175_I2C_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_si1175(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1175 initialization failed (sensor may be absent or bus error)\n");
        cleanup();
        return 1;
    }

    g_log_fp = fopen(CSV_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", CSV_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    /* Write header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,als_visible\n");
        fflush(g_log_fp);
    }

    printf("Si1175 ALS logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t als_visible = 0;
        if (read_als_visible(g_i2c_fd, &als_visible) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
        } else {
            if (log_data(g_log_fp, als_visible) < 0) {
                fprintf(stderr, "Logging error, continuing...\n");
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return 0;
}

