#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1120_ADDR        0x60
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_RESET   0x30
#define SI1120_REG_ALS_L   0x22
#define SI1120_REG_ALS_H   0x23
#define SI1120_REG_PS1_L   0x18
#define SI1120_REG_PS1_H   0x19
#define SI1120_PART_ID     0x41
#define I2C_BUS            1
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES        3
#define RETRY_DELAY_US     10000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0)
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): pigpio error %d\n",
                reg, value, rc);
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0)
        fprintf(stderr, "I2C read failed (reg 0x%02X): pigpio error %d\n", reg, rc);
    return rc;
}

static int init_si1120(int handle)
{
    if (i2c_write_byte(handle, SI1120_REG_RESET, 0x01) < 0)
        return -1;

    gpioDelay(10000);

    int part_id = i2c_read_byte(handle, SI1120_REG_PART_ID);
    if (part_id < 0)
        return -1;

    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Unexpected part ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1120_PART_ID);
        return -1;
    }

    printf("Si1120 detected (part ID 0x%02X). Starting measurements...\n", part_id);
    return 0;
}

static int read_si1120_data(int handle, uint16_t *als, uint16_t *ps1)
{
    int als_l = i2c_read_byte(handle, SI1120_REG_ALS_L);
    int als_h = i2c_read_byte(handle, SI1120_REG_ALS_H);
    int ps1_l = i2c_read_byte(handle, SI1120_REG_PS1_L);
    int ps1_h = i2c_read_byte(handle, SI1120_REG_PS1_H);

    if (als_l < 0 || als_h < 0 || ps1_l < 0 || ps1_h < 0)
        return -1;

    *als = (uint16_t)((als_h << 8) | als_l);
    *ps1 = (uint16_t)((ps1_h << 8) | ps1_l);
    return 0;
}

static int log_data(FILE *fp, uint16_t als, uint16_t ps1)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s, ALS: %u, PS1: %u\n", timestamp, als, ps1) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: pigpio error %d\n",
                I2C_BUS, SI1120_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1120(g_i2c_handle) != 0) {
        fprintf(stderr, "Si1120 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("si1120_log.txt", "a");
    if (g_log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging to si1120_log.txt. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t als = 0, ps1 = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_si1120_data(g_i2c_handle, &als, &ps1) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(RETRY_DELAY_US);
        }

        if (ok) {
            if (log_data(g_log_file, als, ps1) != 0)
                fprintf(stderr, "Logging failed for this sample\n");
        } else {
            fprintf(stderr, "Failed to read Si1120 data after %d attempts\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

