#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SI1145_ADDR 0x60
#define I2C_BUS 1
#define LOG_FILE "proximity_log.txt"
#define MAX_RETRIES 3

/* Si1145 register addresses */
#define REG_PART_ID      0x00
#define REG_HW_KEY       0x07
#define REG_MEAS_RATE    0x06
#define REG_IRQ_ENABLE   0x0F
#define REG_IRQ_MODE1    0x10
#define REG_IRQ_MODE2    0x11
#define REG_ALS_VIS_ADC_COUNTER 0x21
#define REG_ALS_VIS_ADC_GAIN    0x24
#define REG_PS_ADC_COUNTER      0x22
#define REG_PS_LED21            0x0C
#define REG_PS_LED3             0x0F
#define REG_PS_ADC_MISC         0x11
#define REG_PS_ADC_GAIN         0x0D
#define REG_COMMAND             0x80
#define REG_PS1_DATA0           0x16
#define REG_PS1_DATA1           0x17

#define CMD_PS_FORCE 0x03

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, value, rc);
    }
    return rc;
}

static int read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
    }
    return rc;
}

static int init_si1145(int handle) {
    /* Mandatory hardware key */
    if (write_reg(handle, REG_HW_KEY, 0x03) < 0) return -1;
    gpioDelay(10000); /* 10 ms */

    /* Measurement rate: 2 ms */
    if (write_reg(handle, REG_MEAS_RATE, 0x02) < 0) return -1;
    gpioDelay(10000);

    /* No interrupt */
    if (write_reg(handle, REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (write_reg(handle, REG_IRQ_MODE1, 0x00) < 0) return -1;
    if (write_reg(handle, REG_IRQ_MODE2, 0x00) < 0) return -1;

    /* ALS visible ADC counter: 16-bit */
    if (write_reg(handle, REG_ALS_VIS_ADC_COUNTER, 0x0B) < 0) return -1;
    /* ALS visible ADC gain: 0x00 */
    if (write_reg(handle, REG_ALS_VIS_ADC_GAIN, 0x00) < 0) return -1;

    /* PS ADC counter: 16-bit, 1/15 gain */
    if (write_reg(handle, REG_PS_ADC_COUNTER, 0x49) < 0) return -1;
    /* PS LED21: 180 mA */
    if (write_reg(handle, REG_PS_LED21, 0x03) < 0) return -1;
    /* PS LED3: 180 mA */
    if (write_reg(handle, REG_PS_LED3, 0x0F) < 0) return -1;
    /* PS ADC misc: small IR */
    if (write_reg(handle, REG_PS_ADC_MISC, 0x03) < 0) return -1;
    /* PS ADC gain: 7.7x */
    if (write_reg(handle, REG_PS_ADC_GAIN, 0x07) < 0) return -1;

    /* Force a single proximity measurement */
    if (write_reg(handle, REG_COMMAND, CMD_PS_FORCE) < 0) return -1;
    gpioDelay(10000); /* 10 ms for conversion */

    return 0;
}

static int read_proximity(int handle) {
    int low = read_reg(handle, REG_PS1_DATA0);
    if (low < 0) return -1;
    int high = read_reg(handle, REG_PS1_DATA1);
    if (high < 0) return -1;
    return (high << 8) | low;
}

static void log_data(FILE *fp, int proximity) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %d\n", timestamp, proximity);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, ERROR: %s\n", timestamp, msg);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1145(i2c_handle) != 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Si1145 proximity logger started. Press Ctrl+C to stop.\n");

    while (running) {
        int proximity = read_proximity(i2c_handle);
        if (proximity >= 0) {
            log_data(log_file, proximity);
        } else {
            fprintf(stderr, "Failed to read proximity data\n");
            log_error(log_file, "Failed to read proximity data");
            int retries = 0;
            while (running && retries < MAX_RETRIES) {
                gpioDelay(1000000); /* 1 s */
                proximity = read_proximity(i2c_handle);
                if (proximity >= 0) {
                    log_data(log_file, proximity);
                    break;
                }
                retries++;
            }
            if (proximity < 0) {
                fprintf(stderr, "Max retries reached, exiting\n");
                break;
            }
        }
        gpioDelay(1000000); /* 1 s */
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

