    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1145(i2c_handle) != 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Si1145 proximity logger started. Press Ctrl+C to stop.\n");

    while (running) {
        int proximity = read_proximity(i2c_handle);
        if (proximity >= 0) {
            log_data(log_file, proximity);
        } else {
            fprintf(stderr, "Failed to read proximity data\n");
            log_error(log_file, "Failed to read proximity data");
            int retries = 0;
            while (running && retries < MAX_RETRIES) {
                gpioDelay(1000000); /* 1 s */
                proximity = read_proximity(i2c_handle);
                if (proximity >= 0) {
                    log_data(log_file, proximity);
                    break;
                }
                retries++;
            }
            if (proximity < 0) {
                fprintf(stderr, "Max retries reached, exiting\n");
                break;
            }
        }
        gpioDelay(1000000); /* 1 s */
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

