#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define DISTANCE_THRESHOLD_CM    20.0
#define TRIGGER_PULSE_US         10
#define LOOP_DELAY_US            1000000  /* 1 second */

/* Shared state between the interrupt handler and the main thread */
static volatile uint32_t g_rise_tick = 0;
static volatile uint32_t g_fall_tick = 0;
static volatile int      g_echo_state = 0;  /* 0 = idle, 1 = rising edge seen, 2 = falling edge seen */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (SIGINT / SIGTERM)            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Interrupt callback for the echo pin (rising / falling edges)       */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_rise_tick  = tick;
        g_echo_state = 1;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_fall_tick  = tick;
        g_echo_state = 2;
    }
    /* level == 2 (timeout) is ignored here */
}

/* ------------------------------------------------------------------ */
/* Send a 10 us trigger pulse to the HC-SR04                           */
/* ------------------------------------------------------------------ */
static int trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 1) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 0) failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Measure distance in cm using the recorded echo pulse               */
/* Returns -1.0 on timeout or error                                    */
/* ------------------------------------------------------------------ */
static double measure_distance(void)
{
    g_echo_state = 0;
    g_rise_tick  = 0;
    g_fall_tick  = 0;

    if (trigger_sensor() < 0) {
        return -1.0;
    }

    /* Wait for the falling edge (echo pulse ends) */
    uint32_t start = gpioTick();
    while (g_echo_state != 2) {
        if ((gpioTick() - start) > 50000) {  /* 50 ms timeout */
            return -1.0;
        }
        gpioDelay(100);  /* yield CPU */
    }

    uint32_t rise  = g_rise_tick;
    uint32_t fall  = g_fall_tick;

    /* Handle 32-bit tick wrap-around */
    uint32_t diff = fall - rise;  /* pigpio ticks are uint32_t; subtraction wraps correctly */

    double distance = (double)diff * SPEED_OF_SOUND_CM_PER_US / 2.0;
    return distance;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper: terminate pigpio                                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER_PIN, PI_OUTPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO_PIN, PI_INPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER_PIN, PI_OUTPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 0) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(BUZZER_PIN, 0) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register alert callback for echo pin (rising + falling edges) */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(ECHO_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("Trigger: GPIO%d, Echo: GPIO%d, Buzzer: GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Threshold: %.1f cm. Press Ctrl+C to exit.\n\n", DISTANCE_THRESHOLD_CM);

    /* Main measurement loop */
    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Warning: measurement timeout or error\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (distance < DISTANCE_THRESHOLD_CM) {
                if (gpioWrite(BUZZER_PIN, 1) < 0) {
                    fprintf(stderr, "Error: gpioWrite(BUZZER_PIN, 1) failed\n");
                }
            } else {
                if (gpioWrite(BUZZER_PIN, 0) < 0) {
                    fprintf(stderr, "Error: gpioWrite(BUZZER_PIN, 0) failed\n");
                }
            }
        }

        /* Sleep 1 second (interruptible by signals) */
        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

