#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define MAX_DISTANCE 200.0
#define MIN_DISTANCE 20.0

#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

float measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;
    int timeout = 0;

    while (gpioRead(ECHO_PIN) == 0) {
        if (timeout++ > 100000) return -1.0;
        gpioDelay(1);
    }
    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (timeout++ > 100000) return -1.0;
        gpioDelay(1);
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0;

    if (distance > MAX_DISTANCE || distance < MIN_DISTANCE) {
        return -1.0;
    }
    return distance;
}

void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse_width = SERVO_MIN_PULSE + (angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE)) / 180;
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000000);

    signal(SIGINT, signal_handler);

    while (program_running) {
        float distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Error measuring distance. Retrying...\n");
            gpioDelay(100000);
            continue;
        }

        int angle = 180 - (int)((distance - 20.0) / (200.0 - 20.0) * 160.0);
        if (angle < 0) angle = 0;
        if (angle > 180) angle = 180;

        set_servo_angle(angle);
        printf("Distance: %.2f cm, Servo Angle: %d degrees\n", distance, angle);
        gpioDelay(100000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return 0;
}

