#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 200
#define DISTANCE_HYSTERESIS 250
#define SERVO_MIN_PULSE 1000
#define SERVO_MAX_PULSE 2000
#define LOG_FILE "gate_log.txt"

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_RESULT_DISTANCE 0x0096
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0089
#define VL53L1X_REG_RANGE_START 0x0000
#define VL53L1X_REG_TIMING_BUDGET 0x0001

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int init_vl53l1x(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error: Failed to read model ID\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }

    if (i2c_write_reg16(handle, VL53L1X_REG_TIMING_BUDGET, 0x0000) != 0) {
        fprintf(stderr, "Error: Failed to set timing budget\n");
        return -1;
    }

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x0001) != 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }

    return 0;
}

static int read_distance(int handle) {
    uint8_t status = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status, 1) != 1) {
        fprintf(stderr, "Error: Failed to read interrupt status\n");
        return -1;
    }
    if ((status & 0x01) == 0) return -1;

    uint8_t dist_buf[2] = {0};
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read distance\n");
        return -1;
    }

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Warning: Failed to clear interrupt\n");
    }

    return (dist_buf[0] << 8) | dist_buf[1];
