#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_ANGLE       0
#define MAX_ANGLE       180
#define MIN_PULSE_US    500
#define MAX_PULSE_US    2500
#define ECHO_TIMEOUT_US 50000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US   100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static float measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger is low before starting */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5);

    /* 10 us trigger pulse */
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);

    /* Wait for echo rising edge (timeout) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_duration = end_tick - start_tick;
    float distance = (float)pulse_duration * 0.0343f / 2.0f;
    return distance;
}

static int map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    float angle = (distance - MIN_DISTANCE_CM) *
                  (float)(MAX_ANGLE - MIN_ANGLE) /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM) +
                  (float)MIN_ANGLE;

    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return (int)angle;
}

static int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;

    int pulse_width = MIN_PULSE_US +
                      (int)((float)(angle - MIN_ANGLE) *
                            (MAX_PULSE_US - MIN_PULSE_US) /
                            (float)(MAX_ANGLE - MIN_ANGLE));

    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for angle %d\n", angle);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: setMode trigger failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: setMode echo failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: setMode servo failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000);

    /* Register signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction failed\n");
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();
        if (distance < 0.0f) {
            fprintf(stderr, "Error: distance measurement failed\n");
        } else {
            int angle = map_distance_to_angle(distance);
            if (set_servo_angle(angle) == 0) {
                printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
            }
        }
        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nParking Assist System stopped.\n");
    return EXIT_SUCCESS;
}

