#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define REG_TEMP 0x01
#define REG_HUM 0x02
#define REG_CONFIG 0x03
#define CONFIG_NO_HEATER 0x00
#define CONVERSION_DELAY_US 10000
#define SAMPLE_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_config(void) {
    if (i2cWriteByteData(i2c_handle, REG_CONFIG, CONFIG_NO_HEATER) < 0) {
        fprintf(stderr, "Error: failed to write CONFIG register\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_register(uint8_t reg, uint16_t *value) {
    int raw = i2cReadWordData(i2c_handle, reg);
    if (raw < 0) {
        fprintf(stderr, "Error: I2C read failed for register 0x%02X (pigpio error %d)\n", reg, raw);
        return -1;
    }
    *value = (uint16_t)raw;
    return 0;
}

static int read_sensor(float *temperature, float *humidity) {
    uint16_t raw_temp, raw_hum;

    if (read_register(REG_TEMP, &raw_temp) < 0) return -1;
    if (read_register(REG_HUM, &raw_hum) < 0) return -1;

    *temperature = (175.72f * (float)raw_temp) / 65536.0f - 46.85f;
    *humidity = (125.0f * (float)raw_hum) / 65536.0f - 6.0f;

    if (*humidity < 0.0f) *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (pigpio error %d)\n",
                I2C_BUS, SI7005_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_config() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        float temperature, humidity;

        if (read_sensor(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error: sensor read failed, attempting I2C recovery...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: failed to re-open I2C bus (pigpio error %d)\n", i2c_handle);
                break;
            }
            if (write_config() < 0) {
                fprintf(stderr, "Error: config write failed after recovery\n");
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

