#define MPU6050_WHO_AM_I_VAL 0x68

/* Sample rate divider: 7 -> 1 kHz / (1 + 7) = 125 Hz */
#define SMPLRT_DIV_VAL 7

/* ±2 g range -> 0x00, ±250 deg/s -> 0x00 */
#define ACCEL_CONFIG_VAL 0x00
#define GYRO_CONFIG_VAL  0x00

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Read interval in microseconds (100 ms) */
#define READ_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to an MPU-6050 register; return 0 on success, -1 on error */
/* ------------------------------------------------------------------ */
static int mpu_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a byte from an MPU-6050 register; return 0 on success, -1 on error */
/* ------------------------------------------------------------------ */
static int mpu_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the MPU-6050: verify identity, reset, configure ranges  */
/* ------------------------------------------------------------------ */
static int mpu6050_init(void)
{
    uint8_t who_am_i = 0;

    /* Verify sensor identity */
    if (mpu_read_reg(MPU6050_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: Cannot read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). "
                        "Sensor not present or wrong device.\n",
                who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }
    printf("MPU-6050 detected (WHO_AM_I = 0x%02X).\n", who_am_i);

    /* Reset the device (clear SLEEP bit) */
    if (mpu_write_reg(MPU6050_PWR_MGMT_1, 0x80) != 0) {
        fprintf(stderr, "Error: Could not reset MPU-6050.\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle after reset */

    /* Clear SLEEP bit to wake up the device */
    if (mpu_write_reg(MPU6050_PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050.\n");
        return -1;
