    gpioDelay(10000); /* 10 ms for oscillator to stabilise */

    /* Configure sample rate divider */
    if (mpu_write_reg(MPU6050_SMPLRT_DIV, SMPLRT_DIV_VAL) != 0) {
        fprintf(stderr, "Error: Could not set sample rate divider.\n");
        return -1;
    }

    /* Configure accelerometer range (+/- 2 g) */
    if (mpu_write_reg(MPU6050_ACCEL_CONFIG, ACCEL_CONFIG_VAL) != 0) {
        fprintf(stderr, "Error: Could not set accelerometer range.\n");
        return -1;
    }

    /* Configure gyroscope range (+/- 250 deg/s) */
    if (mpu_write_reg(MPU6050_GYRO_CONFIG, GYRO_CONFIG_VAL) != 0) {
        fprintf(stderr, "Error: Could not set gyroscope range.\n");
        return -1;
    }

