    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the MPU-6050 default address */
    g_i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise the sensor */
    if (mpu6050_init() != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting data acquisition (100 ms interval). Press Ctrl+C to stop.\n");

    /* Main acquisition loop */
    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (mpu6050_read_data(&ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d  Y=%6d  Z=%6d  |  Gyro: X=%6d  Y=%6d  Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
