#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REP 0xFD
#define I2C_BUS 1
#define READ_INTERVAL_SEC 5
#define MEASURE_DELAY_US 10000  /* 10 ms */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* CRC-8 as used by Sensirion SHT40: poly 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_sht40(int handle, float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_HIGH_REP;
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write measurement command to SHT40\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6 bytes from SHT40\n");
        return -1;
    }

    /* Validate CRC for temperature (bytes 0-1, CRC byte 2) */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                crc8(buf, 2), buf[2]);
        return -1;
    }

    /* Validate CRC for humidity (bytes 3-4, CRC byte 5) */
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                crc8(buf + 3, 2), buf[5]);
        return -1;
    }

    uint16_t raw_t = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t raw_h = (uint16_t)((buf[3] << 8) | buf[4]);

    *temperature = -45.0f + (175.0f * (float)raw_t / 65535.0f);
    *humidity   = -6.0f  + (125.0f * (float)raw_h / 65535.0f);

    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X\n",
                I2C_BUS, SHT40_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float temperature, humidity;

    while (running) {
        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
            printf("%s - Temperature: %.2f C, Humidity: %.2f %%\n",
                   ts, temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error: sensor read failed, re-opening I2C bus\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(1000000);  /* 1 s back-off before retry */
            i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: failed to re-open I2C bus\n");
                break;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

