    *humidity   = -6.0f  + (125.0f * (float)raw_h / 65535.0f);

    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X\n",
                I2C_BUS, SHT40_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float temperature, humidity;

    while (running) {
        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
            printf("%s - Temperature: %.2f C, Humidity: %.2f %%\n",
                   ts, temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error: sensor read failed, re-opening I2C bus\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(1000000);  /* 1 s back-off before retry */
            i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: failed to re-open I2C bus\n");
                break;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

