#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_fp = NULL;
static FILE *err_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    if (!err_fp) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(err_fp, "%s: %s\n", ts, msg);
    fflush(err_fp);
}

static int read_temperature(float *temp_c) {
    char cmd[2] = {0x36, 0x08};
    char buf[9];
    int rc;

    rc = i2cWriteDevice(i2c_handle, cmd, 2);
    if (rc < 0) {
        log_error("I2C write failed (sensor absent or bus error)");
        return -1;
    }

    gpioDelay(20000); /* 20 ms conversion time */

    rc = i2cReadDevice(i2c_handle, buf, 9);
    if (rc < 0) {
        log_error("I2C read failed (bus error)");
        return -1;
    }
    if (rc != 9) {
        log_error("I2C read short read");
        return -1;
    }

    int16_t raw = (buf[0] << 8) | buf[1];
    *temp_c = (float)raw / 100.0f;
    return 0;
}

static void log_temperature(float temp_c) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_fp, "%s, %.2f\n", ts, temp_c);
    fflush(log_fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_fp) { fclose(log_fp); log_fp = NULL; }
    if (err_fp) { fclose(err_fp); err_fp = NULL; }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", STS30_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!err_fp) {
        perror("Failed to open error log file");
        cleanup();
        return 1;
    }

    printf("STS30-DIS temperature logger started. Press Ctrl+C to exit.\n");

    while (running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            log_temperature(temp);
            printf("Temperature: %.2f C\n", temp);
        } else {
            log_error("Failed to read temperature");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

