#define SDP31_ADDR 0x28
#define TRIGGER_MEASUREMENT 0x2196
#define LOG_FILE "airflow.log"
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int trigger_measurement(int handle) {
    uint8_t cmd[2] = {0x21, 0x96};
    int rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed (trigger): %d\n", rc);
        return -1;
    }
    gpioDelay(1000);
    return 0;
}

static int read_measurement(int handle, float *pressure, float *temperature) {
    uint8_t buf[6];
    int rc = i2cReadDevice(handle, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: i2cReadDevice failed (got %d bytes)\n", rc);
        return -1;
    }
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    int16_t raw_temperature = (buf[3] << 8) | buf[4];
    *pressure = (float)raw_pressure / 60.0f;
    *temperature = (float)raw_temperature / 200.0f;
    return 0;
}

static int log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        fprintf(stderr, "Error: fprintf to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush failed\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: fopen log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float pressure, temperature;
    int retry_count;

    while (running) {
        retry_count = 0;
        int success = 0;
        while (retry_count < MAX_RETRIES && !success && running) {
            if (trigger_measurement(i2c_handle) == 0) {
                if (read_measurement(i2c_handle, &pressure, &temperature) == 0) {
                    success = 1;
                } else {
                    retry_count++;
                    if (retry_count < MAX_RETRIES) {
                        gpioDelay(100000 * (1 << retry_count));
                    }
                }
            } else {
                retry_count++;
                if (retry_count < MAX_RETRIES) {
                    gpioDelay(100000 * (1 << retry_count));
                }
            }
        }

        if (success) {
            if (log_data(log_file, pressure, temperature) != 0) {
                fprintf(stderr, "Warning: log_data failed\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor after %d retries\n", MAX_RETRIES);
        }

        if (running) {
            gpioDelay(SAMPLE_INTERVAL_US);
        }
    }

    cleanup();
    return 0;
}

