#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7015_ADDR    0x40
#define CMD_TEMP       0xF3
#define CMD_HUMID      0xF5
#define LOG_FILE       "sensor_data.txt"
#define SAMPLE_US      5000000  /* 5 seconds */
#define MEAS_TIMEOUT_US 20000   /* 20 ms max for one measurement */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single command byte to the Si7015 (No Hold Master mode). */
static int si7015_write_cmd(int handle, uint8_t cmd)
{
    if (i2cWriteByte(handle, cmd) < 0) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n",
                cmd, pigpio_error(i2cWriteByte(handle, cmd)));
        return -1;
    }
    return 0;
}

/* Read `len` bytes from the Si7015 (No Hold Master mode). */
static int si7015_read_bytes(int handle, uint8_t *buf, int len)
{
    int n = i2cReadDevice(handle, (char *)buf, len);
    if (n != len) {
        fprintf(stderr, "I2C read failed (expected %d, got %d): %s\n",
                len, n, pigpio_error(n));
        return -1;
    }
    return 0;
}

/* Trigger a measurement and wait for completion, then read 2 bytes. */
static int si7015_read_measurement(int handle, uint8_t cmd,
                                   uint16_t *raw)
{
    if (si7015_write_cmd(handle, cmd) < 0)
        return -1;

    /* Poll until the sensor is ready (or timeout). */
    uint8_t buf[2];
    int waited = 0;
    while (waited < MEAS_TIMEOUT_US) {
        if (si7015_read_bytes(handle, buf, 2) == 0) {
            *raw = ((uint16_t)buf[0] << 8) | buf[1];
            return 0;
        }
        gpioDelay(1000);          /* 1 ms */
        waited += 1000;
    }

    fprintf(stderr, "Measurement timeout (cmd 0x%02X)\n", cmd);
    return -1;
}

static float convert_temperature(uint16_t raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw)
{
    float rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

static void log_data(float temp, float rh)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%RH\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temp, rh);
    } else {
        fprintf(fp, "Timestamp error, Temperature: %.2f C, Humidity: %.2f %%RH\n", temp, rh);
    }

    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return 1;
    }

    printf("Si7015 sensor logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t raw_t = 0, raw_h = 0;

        if (si7015_read_measurement(g_i2c_handle, CMD_TEMP, &raw_t) < 0) {
            fprintf(stderr, "Temperature read failed; retrying next cycle.\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (si7015_read_measurement(g_i2c_handle, CMD_HUMID, &raw_h) < 0) {
            fprintf(stderr, "Humidity read failed; retrying next cycle.\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float temp = convert_temperature(raw_t);
        float rh   = convert_humidity(raw_h);

        log_data(temp, rh);
        printf("Temperature: %.2f C, Humidity: %.2f %%RH\n", temp, rh);

        gpioDelay(SAMPLE_US);
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

