#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x25
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x2F
#define SCALE_FACTOR_PRESSURE 240.0f
#define SCALE_FACTOR_TEMPERATURE 200.0f
#define OFFSET_TEMPERATURE -45.0f
#define LOG_FILE "airflow_data.txt"
#define MEASUREMENT_DELAY_MS 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb) {
    uint8_t buf[2] = {msb, lsb};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sdp800(int fd, float *pressure, float *temperature) {
    uint8_t data[6];
    if (i2c_write_cmd(fd, MEASURE_CMD_MSB, MEASURE_CMD_LSB) < 0)
        return -1;
    usleep(MEASUREMENT_DELAY_MS * 1000);
    if (i2c_read_bytes(fd, data, 6) < 0)
        return -1;
    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temperature = (int16_t)((data[3] << 8) | data[4]);
    *pressure = (float)raw_pressure / SCALE_FACTOR_PRESSURE;
    *temperature = (float)raw_temperature / SCALE_FACTOR_TEMPERATURE + OFFSET_TEMPERATURE;
    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_fp);
}

