#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD  2.0
#define MEAS_DELAY_US  10000
#define MAX_RETRIES    3
#define TEMP_HIGH      28.0
#define TEMP_LOW       27.0

#define CMD_TEMP_HOLD  0xE3
#define CMD_HUM_HOLD   0xE5

typedef struct {
    time_t timestamp;
    float  temperature;
    float  humidity;
} SensorData;

static SensorData circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, float *temperature, float *humidity) {
    uint8_t cmd;
    uint8_t data[2];
    int retries = 0;

    cmd = CMD_TEMP_HOLD;
    if (i2cWriteByte(handle, cmd) < 0) {
        fprintf(stderr, "Error: failed to write temperature command (0x%02X)\n", cmd);
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);
    if (i2cReadDevice(handle, (char *)data, 2) != 2) {
        fprintf(stderr, "Error: failed to read temperature data\n");
        return -1;
    }
    uint16_t raw_temp = ((uint16_t)data[0] << 8) | data[1];
    *temperature = (175.72f * raw_temp / 65536.0f) - 46.85f;

    cmd = CMD_HUM_HOLD;
    if (i2cWriteByte(handle, cmd) < 0) {
        fprintf(stderr, "Error: failed to write humidity command (0x%02X)\n", cmd);
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);
    if (i2cReadDevice(handle, (char *)data, 2) != 2) {
        fprintf(stderr, "Error: failed to read humidity data\n");
        return -1;
    }
    uint16_t raw_hum = ((uint16_t)data[0] << 8) | data[1];
    *humidity = (125.0f * raw_hum / 65536.0f) - 6.0f;

    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;
    return 0;
}

static void add_to_buffer(time_t ts, float temp, float hum) {
    circular_buffer[buffer_index].timestamp  = ts;
    circular_buffer[buffer_index].temperature = temp;
    circular_buffer[buffer_index].humidity    = hum;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    int start = (buffer_count < BUFFER_SIZE) ? 0 : buffer_index;
    printf("\n--- Sensor Data Log (%d entries) ---\n", buffer_count);
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm_info = localtime(&circular_buffer[idx].timestamp);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("[%s] Temp: %.2f C, Hum: %.2f %%\n",
               ts, circular_buffer[idx].temperature, circular_buffer[idx].humidity);
    }
    printf("--- End of Log ---\n");
}

static void control_fan(float temperature) {
    static int fan_on = 0;
    if (temperature > TEMP_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON  (Temp: %.2f C)\n", temperature);
        } else {
            fprintf(stderr, "Error: failed to turn fan ON\n");
        }
    } else if (temperature < TEMP_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (Temp: %.2f C)\n", temperature);
        } else {
            fprintf(stderr, "Error: failed to turn fan OFF\n");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X (handle=%d)\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    printf("Si7021 monitoring started (I2C bus %d, addr 0x%02X, fan GPIO%d)\n",
           I2C_BUS, I2C_ADDR, FAN_GPIO);
    printf("Sampling every %.1f s. Press Ctrl+C to exit.\n", SAMPLE_PERIOD);

    while (running) {
        float temperature = 0.0f, humidity = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_sensor_data(i2c_handle, &temperature, &humidity) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Warning: I2C read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            gpioDelay(100000);
        }

        if (!ok) {
            fprintf(stderr, "Error: sensor read failed after %d attempts — sensor may be absent\n", MAX_RETRIES);
            gpioWrite(FAN_GPIO, 0);
            gpioDelay(500000);
            continue;
        }

        time_t now = time(NULL);
        add_to_buffer(now, temperature, humidity);
        control_fan(temperature);

        if (buffer_count >= BUFFER_SIZE) {
            print_buffer();
            buffer_count = 0;
        }

        for (int i = 0; i < 5 && running; i++) {
            time_sleep(SAMPLE_PERIOD / 5.0);
        }
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

