#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define SCD40_CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define SCD40_CMD_READ_MEASUREMENT 0xEC05
#define SCD40_CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define SCD40_CMD_GET_DATA_READY_STATUS 0xE4B8
#define SCD40_MEASUREMENT_INTERVAL_MS 5000
#define SCD40_FIRST_READ_DELAY_MS 1000
#define SCD40_READ_DELAY_MS 5000
#define SCD40_STOP_DELAY_MS 1000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int send_command(uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to send command 0x%04X\n", command);
        return -1;
    }
    return 0;
}

static int read_data(uint16_t *co2, uint16_t *temperature, uint16_t *humidity) {
    uint8_t buf[9];
    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from SCD40\n");
        return -1;
    }
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: CRC check failed for CO2 word\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: CRC check failed for temperature word\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: CRC check failed for humidity word\n");
        return -1;
    }
    *co2 = (buf[0] << 8) | buf[1];
    *temperature = (buf[3] << 8) | buf[4];
    *humidity = (buf[6] << 8) | buf[7];
    return 0;
}

static int is_data_ready(void) {
    if (send_command(SCD40_CMD_GET_DATA_READY_STATUS) != 0) {
        return -1;
    }
    gpioDelay(2000);
    uint8_t buf[3];
    if (i2cReadDevice(i2c_handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: Failed to read data-ready status\n");
        return -1;
    }
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: CRC check failed for data-ready status\n");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

static void log_data(uint16_t co2, uint16_t temperature, uint16_t humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%u,%.2f,%.2f\n", timestamp, co2,
            -45.0f + 175.0f * (float)temperature / 65535.0f,
            100.0f * (float)humidity / 65535.0f);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(SCD40_CMD_STOP_PERIODIC_MEASUREMENT);
        gpioDelay(SCD40_STOP_DELAY_MS * 1000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d\n",
                SCD40_I2C_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (send_command(SCD40_CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement\n");
        cleanup();
        return 1;
    }
    gpioDelay(SCD40_FIRST_READ_DELAY_MS * 1000);
    signal(SIGINT, signal_handler);
    while (!terminate) {
        int ready = is_data_ready();
        if (ready < 0) {
            fprintf(stderr, "Error: Failed to check data-ready status\n");
            gpioDelay(SCD40_MEASUREMENT_INTERVAL_MS * 1000);
            continue;
        }
        if (ready == 1) {
            uint16_t co2, temperature, humidity;
            if (read_data(&co2, &temperature, &humidity) == 0) {
                log_data(co2, temperature, humidity);
            } else {
                fprintf(stderr, "Error: Failed to read measurement data\n");
            }
        }
        gpioDelay(SCD40_READ_DELAY_MS * 1000);
    }
    cleanup();
    return 0;
}

