    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%u,%.2f,%.2f\n", timestamp, co2,
            -45.0f + 175.0f * (float)temperature / 65535.0f,
            100.0f * (float)humidity / 65535.0f);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(SCD40_CMD_STOP_PERIODIC_MEASUREMENT);
        gpioDelay(SCD40_STOP_DELAY_MS * 1000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d\n",
                SCD40_I2C_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (send_command(SCD40_CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement\n");
        cleanup();
        return 1;
    }
    gpioDelay(SCD40_FIRST_READ_DELAY_MS * 1000);
    signal(SIGINT, signal_handler);
    while (!terminate) {
        int ready = is_data_ready();
