#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define LED_GPIO 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20
#define MEASUREMENT_INTERVAL 5
#define MAX_RETRIES 3

#define CMD_START_PERIODIC 0x21B1
#define CMD_STOP_PERIODIC 0x3F86
#define CMD_DATA_READY 0xE4B8
#define CMD_READ_MEASUREMENT 0xEC05

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
    time_t timestamp;
} sensor_data_t;

typedef struct {
    sensor_data_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t co2_buffer;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int read_data_ready(uint8_t *ready) {
    if (send_command(CMD_DATA_READY) != 0) return -1;
    gpioDelay(2000);
    uint8_t buf[3];
    if (i2cReadDevice(i2c_handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: I2C read failed for data-ready status\n");
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on data-ready status\n");
        return -1;
    }
    *ready = buf[0] & 0x01;
    return 0;
}

static int read_measurement(sensor_data_t *data) {
    if (send_command(CMD_READ_MEASUREMENT) != 0) return -1;
    gpioDelay(2000);
    uint8_t buf[9];
    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: I2C read failed for measurement data\n");
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on CO2 word\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: CRC mismatch on temperature word\n");
        return -1;
    }
    if (crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "Error: CRC mismatch on humidity word\n");
        return -1;
    }
    data->co2 = (uint16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (float)((buf[3] << 8) | buf[4]) / 100.0f;
    data->humidity = (float)((buf[6] << 8) | buf[7]) / 100.0f;
    data->timestamp = time(NULL);
    return 0;
}

static void buffer_add(circular_buffer_t *buf, sensor_data_t data) {
    buf->buffer[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static void buffer_print(const circular_buffer_t *buf) {
    printf("\n--- Circular Buffer Contents ---\n");
    int start = (buf->count == BUFFER_SIZE) ? buf->head : 0;
    for (int i = 0; i < buf->count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm_info = localtime(&buf->buffer[idx].timestamp);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("[%s] CO2: %u ppm, Temp: %.2f C, Hum: %.2f %%\n",
               ts, buf->buffer[idx].co2, buf->buffer[idx].temperature, buf->buffer[idx].humidity);
    }
    printf("--- End of Buffer ---\n");
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(CMD_STOP_PERIODIC);
        gpioDelay(2000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (addr 0x%02X): %d\n", SCD40_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    memset(&co2_buffer, 0, sizeof(co2_buffer));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (send_command(CMD_START_PERIODIC) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement\n");
        cleanup();
        return 1;
    }
    gpioDelay(2000);

    printf("SCD40 monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint8_t ready = 0;
        int retries = 0;
        while (!ready && retries < MAX_RETRIES && !terminate) {
            if (read_data_ready(&ready) != 0) {
                fprintf(stderr, "Warning: Data-ready poll failed, retrying...\n");
                gpioDelay(100000);
                continue;
            }
            gpioDelay(100000);
            retries++;
        }

        if (terminate) break;

        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "Warning: Data-ready timeout, skipping cycle\n");
            gpioDelay(MEASUREMENT_INTERVAL * 1000000);
            continue;
        }

        sensor_data_t data;
        if (read_measurement(&data) != 0) {
            fprintf(stderr, "Warning: Measurement read failed, skipping cycle\n");
            gpioDelay(MEASUREMENT_INTERVAL * 1000000);
            continue;
        }

        buffer_add(&co2_buffer, data);
        printf("[%ld] CO2: %u ppm, Temp: %.2f C, Hum: %.2f %%\n",
               (long)data.timestamp, data.co2, data.temperature, data.humidity);

        if (data.co2 > CO2_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        buffer_print(&co2_buffer);

        gpioDelay(MEASUREMENT_INTERVAL * 1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

