#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define TIMEOUT_US 50000
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
    if (log_file) {
        fprintf(log_file, "%s,ERROR,%s\n", ts, msg);
        fflush(log_file);
    }
}

static void log_temperature(double temp) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%.2f\n", ts, temp);
    fflush(log_file);
}

/*
 * Measure high-pulse width (TH) and total cycle width (TL) via busy-wait polling.
 * Returns 0 on success, -1 on timeout, -2 on division-by-zero.
 */
static int measure_pulse_widths(unsigned int *th, unsigned int *tl) {
    int level = gpioRead(GPIO_PIN);
    if (level < 0) {
        log_error("gpioRead failed");
        return -1;
    }

    uint32_t start_tick = gpioTick();
    uint32_t timeout_start = start_tick;

    /* Wait for falling edge (end of high pulse) */
    while (running) {
        level = gpioRead(GPIO_PIN);
        if (level < 0) {
            log_error("gpioRead failed during high-pulse measurement");
            return -1;
        }
        if (level == 0) break;
        if ((int32_t)(gpioTick() - timeout_start) > TIMEOUT_US) {
            log_error("Timeout waiting for high-pulse end");
            return -1;
        }
    }
    if (!running) return -1;

    *th = gpioTick() - start_tick;

    /* Wait for rising edge (start of next cycle) */
    level = gpioRead(GPIO_PIN);
    if (level < 0) {
        log_error("gpioRead failed during low-pulse measurement");
        return -1;
    }

    uint32_t cycle_start = gpioTick();
    while (running) {
        level = gpioRead(GPIO_PIN);
        if (level < 0) {
            log_error("gpioRead failed during low-pulse measurement");
            return -1;
        }
        if (level == 1) break;
        if ((int32_t)(gpioTick() - cycle_start) > TIMEOUT_US) {
            log_error("Timeout waiting for cycle start");
            return -1;
        }
    }
    if (!running) return -1;

    *tl = gpioTick() - cycle_start;

    if (*tl == 0) {
        log_error("Division by zero: total cycle width is zero");
        return -2;
    }
    return 0;
}

static double calculate_temperature(unsigned int th, unsigned int tl) {
    return 4215.0 - (2143.0 * (double)th / (double)tl);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMP05 temperature logger started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_PIN);

    int consecutive_errors = 0;

    while (running) {
        unsigned int th = 0, tl = 0;
        int rc = measure_pulse_widths(&th, &tl);

        if (rc == 0) {
            double temp = calculate_temperature(th, tl);
            if (temp >= -40.0 && temp <= 150.0) {
                log_temperature(temp);
                consecutive_errors = 0;
                printf("Temperature: %.2f C\n", temp);
            } else {
                log_error("Temperature out of valid range");
                consecutive_errors++;
                if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                    log_error("SENSOR MALFUNCTION");
                    consecutive_errors = 0;
                }
            }
        } else {
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_error("SENSOR MALFUNCTION");
                consecutive_errors = 0;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

