#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD_HIGH_REP 0x24
#define MEASURE_CMD_ARG 0x00
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 1000
#define MEASUREMENT_DELAY_MS 15
#define LOG_INTERVAL_S 5
#define LOG_FILE "environmental_data.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} SensorData;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int read_sht35(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD_HIGH_REP, MEASURE_CMD_ARG};
    uint8_t buf[6];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d)\n", retries + 1);
            retries++;
            if (retries < RETRY_COUNT) gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_MS * 1000);

        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d)\n", retries + 1);
            retries++;
            if (retries < RETRY_COUNT) gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d)\n", retries + 1);
            retries++;
            if (retries < RETRY_COUNT) gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d)\n", retries + 1);
            retries++;
            if (retries < RETRY_COUNT) gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        uint16_t temp_raw = (buf[0] << 8) | buf[1];
        uint16_t hum_raw = (buf[3] << 8) | buf[4];

        *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
        *humidity = 100.0f * (float)hum_raw / 65535.0f;

        return 0;
    }

    fprintf(stderr, "SHT35 read failed after %d retries\n", RETRY_COUNT);
    return -1;
}

