            simulate_offset(&temperature, &humidity, time(NULL));
            log_data(log_file, temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; logging NaN values\n");
            log_data(log_file, NAN, NAN);
        }

        for (int i = 0; i < LOG_INTERVAL_S && !terminate; i++) {
            gpioDelay(1000000);
        }
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

