#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP810_ADDR 0x25
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x2F
#define CONVERSION_TIME_MS 45
#define LOG_INTERVAL_MS 1000
#define LOG_FILE "airflow.csv"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb) {
    uint8_t buf[2] = {msb, lsb};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        return -1;
    }
    return 0;
}

static int read_sdp810(int fd, float *pressure, float *temperature) {
    uint8_t data[9];
    int16_t raw_pressure, raw_temperature;
    uint16_t scale_factor;

    if (i2c_write_cmd(fd, MEASURE_CMD_MSB, MEASURE_CMD_LSB) < 0) {
        return -1;
    }

    usleep(CONVERSION_TIME_MS * 1000);

    if (i2c_read_data(fd, data, 9) < 0) {
        return -1;
    }

    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "CRC error on pressure data\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "CRC error on temperature data\n");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "CRC error on scale factor\n");
        return -1;
    }

    raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    raw_temperature = (int16_t)((data[3] << 8) | data[4]);
    scale_factor = (uint16_t)((data[6] << 8) | data[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

static int log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    float pressure, temperature;

    while (running) {
        if (read_sdp810(i2c_fd, &pressure, &temperature) == 0) {
            if (log_data(log_fp, pressure, temperature) < 0) {
                fprintf(stderr, "Failed to write to log file\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(LOG_INTERVAL_MS * 1000);
    }

    if (log_fp) {
        fclose(log_fp);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

