    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    float pressure, temperature;

    while (running) {
        if (read_sdp810(i2c_fd, &pressure, &temperature) == 0) {
            if (log_data(log_fp, pressure, temperature) < 0) {
                fprintf(stderr, "Failed to write to log file\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(LOG_INTERVAL_MS * 1000);
    }

    if (log_fp) {
        fclose(log_fp);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

