}

static int reset_sensor(int fd) {
    if (i2c_write_cmd(fd, CMD_RESET) < 0) return -1;
    usleep(15000);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (reset_sensor(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor reset failed; continuing anyway.\n");
    }

    printf("Greenhouse monitoring started. Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        int ok = 1;

        if (read_humidity(g_i2c_fd, &humidity) < 0) {
            fprintf(stderr, "Humidity read failed; resetting sensor.\n");
            ok = 0;
        }

        if (ok && read_temperature(g_i2c_fd, &temperature) < 0) {
            fprintf(stderr, "Temperature read failed; resetting sensor.\n");
            ok = 0;
        }

        if (ok) {
            if (log_data(LOG_FILE, temperature, humidity) < 0) {
                fprintf(stderr, "Logging failed.\n");
            } else {
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            }
        } else {
            if (reset_sensor(g_i2c_fd) < 0) {
                fprintf(stderr, "Sensor reset failed after error.\n");
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

