    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting HVAC airflow monitoring. Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (!terminate) {
        if (read_sdp810(i2c_handle, &pressure, &temperature) == 0) {
            if (log_data(log_file, pressure, temperature) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }
