#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_US 100000
#define FLOW_MIN_SLPM 0.0f
#define FLOW_MAX_SLPM 10.0f
#define FLOW_MIN_COUNTS 1638
#define FLOW_MAX_COUNTS 14745
#define LOG_FILE "flow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint16_t *raw_data) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }
    uint16_t word = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *raw_data = word >> 2;
    return 0;
}

static float calculate_flow_rate(uint16_t raw_data) {
    float flow_rate = (float)(raw_data - FLOW_MIN_COUNTS) *
                      (FLOW_MAX_SLPM - FLOW_MIN_SLPM) /
                      (float)(FLOW_MAX_COUNTS - FLOW_MIN_COUNTS) +
                      FLOW_MIN_SLPM;
    if (flow_rate < FLOW_MIN_SLPM) flow_rate = FLOW_MIN_SLPM;
    if (flow_rate > FLOW_MAX_SLPM) flow_rate = FLOW_MAX_SLPM;
    return flow_rate;
}

static void control_fan(float flow_rate) {
    float duty_cycle = (flow_rate / FLOW_MAX_SLPM) * 100.0f;
    if (duty_cycle < 0.0f) duty_cycle = 0.0f;
    if (duty_cycle > 100.0f) duty_cycle = 100.0f;
    int pwm_value = (int)(duty_cycle * PWM_RANGE / 100.0f);
    gpioPWM(FAN_GPIO, pwm_value);
}

static void log_data(FILE *fp, float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, flow_rate);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        i2cClose(i2c_handle);
        gpioTerminate();
