#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_US 100000
#define FLOW_MIN_SLPM 0.0f
#define FLOW_MAX_SLPM 10.0f
#define FLOW_MIN_COUNTS 1638
#define FLOW_MAX_COUNTS 14745
#define LOG_FILE "flow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint16_t *raw_data) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }
    uint16_t word = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *raw_data = word >> 2;
    return 0;
}

static float calculate_flow_rate(uint16_t raw_data) {
    float flow_rate = (float)(raw_data - FLOW_MIN_COUNTS) *
                      (FLOW_MAX_SLPM - FLOW_MIN_SLPM) /
                      (float)(FLOW_MAX_COUNTS - FLOW_MIN_COUNTS) +
                      FLOW_MIN_SLPM;
    if (flow_rate < FLOW_MIN_SLPM) flow_rate = FLOW_MIN_SLPM;
    if (flow_rate > FLOW_MAX_SLPM) flow_rate = FLOW_MAX_SLPM;
    return flow_rate;
}

static void control_fan(float flow_rate) {
    float duty_cycle = (flow_rate / FLOW_MAX_SLPM) * 100.0f;
    if (duty_cycle < 0.0f) duty_cycle = 0.0f;
    if (duty_cycle > 100.0f) duty_cycle = 100.0f;
    int pwm_value = (int)(duty_cycle * PWM_RANGE / 100.0f);
