#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LPS33HW_ADDR 0x5D
#define WHO_AM_I     0x0F
#define WHO_AM_I_VAL 0xB1
#define CTRL_REG1    0x10
#define CTRL_REG1_VAL 0xB0
#define PRESS_OUT_XL 0x28
#define TEMP_OUT_L   0x2B

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "%s, ERROR: %s\n", ts, msg);
    if (log_file) {
        fprintf(log_file, "%s, ERROR: %s\n", ts, msg);
        fflush(log_file);
    }
}

static int read_reg8(int h, uint8_t reg, uint8_t *val) {
    int r = i2cReadByteData(h, reg);
    if (r < 0) return -1;
    *val = (uint8_t)r;
    return 0;
}

static int write_reg8(int h, uint8_t reg, uint8_t val) {
    return i2cWriteByteData(h, reg, val);
}

static int read_pressure(int h, float *pressure) {
    uint8_t xl, l, h;
    if (read_reg8(h, PRESS_OUT_XL, &xl) < 0) return -1;
    if (read_reg8(h, PRESS_OUT_L, &l)  < 0) return -1;
    if (read_reg8(h, PRESS_OUT_H, &h)  < 0) return -1;
    int32_t raw = (int32_t)((uint32_t)h << 16 | (uint32_t)l << 8 | xl);
    if (raw & 0x800000) raw |= 0xFF000000;
    *pressure = (float)raw / 4096.0f;
    return 0;
}

static int read_temperature(int h, float *temperature) {
    uint8_t l, h;
    if (read_reg8(h, TEMP_OUT_L, &l) < 0) return -1;
    if (read_reg8(h, TEMP_OUT_H, &h) < 0) return -1;
    int16_t raw = (int16_t)((uint16_t)h << 8 | l);
    *temperature = 42.5f + (float)raw / 480.0f;
    return 0;
}

static int init_sensor(int h) {
    uint8_t id;
    if (read_reg8(h, WHO_AM_I, &id) < 0) {
        log_error("Failed to read WHO_AM_I");
        return -1;
    }
    if (id != WHO_AM_I_VAL) {
        char msg[64];
        snprintf(msg, sizeof(msg), "WHO_AM_I mismatch: 0x%02X (expected 0x%02X)", id, WHO_AM_I_VAL);
        log_error(msg);
        return -1;
    }
    if (write_reg8(h, CTRL_REG1, CTRL_REG1_VAL) < 0) {
        log_error("Failed to write CTRL_REG1");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X\n", LPS33HW_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle) < 0) {
        cleanup();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        perror("Failed to open environmental_data.txt");
        cleanup();
        return 1;
    }

    while (running) {
        float pressure, temperature;
        int p_ok = read_pressure(i2c_handle, &pressure);
        int t_ok = read_temperature(i2c_handle, &temperature);

        if (p_ok == 0 && t_ok == 0) {
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", ts, pressure, temperature);
            fflush(log_file);
        } else {
            log_error("Sensor read failure");
        }

        gpioDelay(1000000);
    }

    cleanup();
    return 0;
}

