#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define SAMPLE_PERIOD  1.0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read temperature from STLM75; returns 0 on success, -1 on error. */
static int read_temperature(float *temperature)
{
    int raw = i2cReadWordData(g_i2c_handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "I2C read error: %d\n", raw);
        return -1;
    }

    /* pigpio returns bytes in little-endian order; swap to get the
     * STLM75 two's-complement value. */
    uint16_t swapped = ((uint16_t)(raw & 0xFF) << 8) |
                       ((uint16_t)((raw >> 8) & 0xFF));

    /* STLM75: 9-bit two's-complement, low 7 bits always 0. */
    int16_t temp_raw = (int16_t)swapped;
    temp_raw >>= 7;          /* arithmetic shift preserves sign */
    *temperature = (float)temp_raw / 2.0f;
    return 0;
}

static void update_buffer(float temperature, float buffer[], int *index, int size)
{
    buffer[*index] = temperature;
    *index = (*index + 1) % size;
}

static float calculate_average(const float buffer[], int size)
{
    float sum = 0.0f;
    for (int i = 0; i < size; i++)
        sum += buffer[i];
    return sum / (float)size;
}

static void control_led(float average_temperature)
{
    if (average_temperature > TEMP_THRESHOLD)
        gpioWrite(LED_GPIO, 1);
    else
        gpioWrite(LED_GPIO, 0);
}

int main(void)
{
    float temperature_buffer[BUFFER_SIZE] = {0.0f};
    int buffer_index = 0;
    float average_temperature = 0.0f;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    while (g_running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            update_buffer(temperature, temperature_buffer, &buffer_index, BUFFER_SIZE);
            average_temperature = calculate_average(temperature_buffer, BUFFER_SIZE);
            control_led(average_temperature);
            printf("Temperature: %.2f C, Average: %.2f C\n",
                   temperature, average_temperature);
        } else {
            fprintf(stderr, "Skipping sample due to read error\n");
        }
        time_sleep(SAMPLE_PERIOD);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

