            printf("Temperature: %.2f C, Average: %.2f C\n",
                   temperature, average_temperature);
        } else {
            fprintf(stderr, "Skipping sample due to read error\n");
        }
        time_sleep(SAMPLE_PERIOD);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

