#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD30_I2C_ADDR 0x61
#define SCD30_CMD_START_CONT_MEAS 0x0010
#define SCD30_CMD_STOP_CONT_MEAS  0x0104
#define SCD30_CMD_GET_DATA_READY  0x0202
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_SET_MEAS_INTERVAL 0x4600
#define SCD30_MEAS_INTERVAL_SEC 2
#define SCD30_DATA_READY_TIMEOUT_MS 1000
#define SCD30_DATA_READY_POLL_MS 100
#define SCD30_READ_LEN 18
#define SCD30_CRC_POLY 0x31
#define SCD30_CRC_INIT 0xFF

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t scd30_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = SCD30_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ SCD30_CRC_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int scd30_write_cmd(int handle, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int scd30_write_cmd_with_arg(int handle, uint16_t cmd, uint16_t arg) {
    uint8_t buf[5];
    buf[0] = (uint8_t)(cmd >> 8);
    buf[1] = (uint8_t)(cmd & 0xFF);
    buf[2] = (uint8_t)(arg >> 8);
    buf[3] = (uint8_t)(arg & 0xFF);
    buf[4] = scd30_crc8(&buf[2], 2);
    if (i2cWriteDevice(handle, (char *)buf, 5) != 0) {
        fprintf(stderr, "Error: I2C write failed for command 0x%04X with arg 0x%04X\n", cmd, arg);
        return -1;
    }
    return 0;
}

static int scd30_data_ready(int handle) {
    if (scd30_write_cmd(handle, SCD30_CMD_GET_DATA_READY) != 0)
        return -1;
    gpioDelay(2000);
    uint8_t buf[3];
    if (i2cReadDevice(handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: I2C read failed for data-ready check\n");
        return -1;
    }
    if (scd30_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on data-ready response\n");
        return -1;
    }
    uint16_t ready = ((uint16_t)buf[0] << 8) | buf[1];
    return (ready == 1) ? 1 : 0;
}

static int scd30_read_measurement(int handle, uint16_t *co2, float *temp, float *rh) {
    if (scd30_write_cmd(handle, SCD30_CMD_READ_MEASUREMENT) != 0)
        return -1;
    gpioDelay(2000);
    uint8_t buf[SCD30_READ_LEN];
    if (i2cReadDevice(handle, (char *)buf, SCD30_READ_LEN) != SCD30_READ_LEN) {
        fprintf(stderr, "Error: I2C read failed for measurement data\n");
        return -1;
    }
    for (int i = 0; i < 3; i++) {
        if (scd30_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "Error: CRC mismatch on measurement value %d\n", i);
            return -1;
        }
    }
    uint16_t co2_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t temp_raw = ((uint16_t)buf[3] << 8) | buf[4];
    uint16_t rh_raw = ((uint16_t)buf[6] << 8) | buf[7];
    *co2 = co2_raw;
    *temp = (float)temp_raw / 100.0f;
    *rh = (float)rh_raw / 100.0f;
    return 0;
}

static void log_data(FILE *fp, uint16_t co2, float temp, float rh) {
    time_t t = time(NULL);
    struct tm tm_utc;
    gmtime_r(&t, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(fp, "%s,%u,%.2f,%.2f\n", ts, co2, temp, rh);
    fflush(fp);
}

static void control_ventilation(uint16_t co2) {
    if (co2 >= 1200) {
        printf("Ventilation: HIGH\n");
    } else if (co2 >= 800) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: OFF\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        scd30_write_cmd(i2c_handle, SCD30_CMD_STOP_CONT_MEAS);
        gpioDelay(2000000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 0;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 0;
    }

    i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at 0x%02X\n", SCD30_I2C_ADDR);
        gpioTerminate();
        return 0;
    }

    if (scd30_write_cmd_with_arg(i2c_handle, SCD30_CMD_SET_MEAS_INTERVAL, SCD30_MEAS_INTERVAL_SEC) != 0) {
        fprintf(stderr, "Error: Failed to set measurement interval\n");
        cleanup();
        return 0;
    }
    if (scd30_write_cmd_with_arg(i2c_handle, SCD30_CMD_START_CONT_MEAS, 0) != 0) {
        fprintf(stderr, "Error: Failed to start continuous measurement\n");
        cleanup();
        return 0;
    }

    log_file = fopen("air_quality.log", "a");
    if (!log_file) {
        perror("Error: Failed to open log file");
        cleanup();
        return 0;
    }

    printf("SCD30 monitoring started. Logging to air_quality.log\n");

    while (!terminate) {
        int ready = scd30_data_ready(i2c_handle);
        if (ready < 0) {
            fprintf(stderr, "Warning: Data-ready poll failed, retrying...\n");
            gpioDelay(1000000);
            continue;
        }
        if (ready == 0) {
            gpioDelay(SCD30_MEAS_INTERVAL_SEC * 1000000);
            continue;
        }

        uint16_t co2;
        float temp, rh;
        if (scd30_read_measurement(i2c_handle, &co2, &temp, &rh) != 0) {
            fprintf(stderr, "Warning: Measurement read failed, retrying...\n");
            gpioDelay(1000000);
            continue;
        }

        log_data(log_file, co2, temp, rh);
        control_ventilation(co2);

        gpioDelay(SCD30_MEAS_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

