#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SDP32_ADDR 0x21
#define I2C_BUS 1
#define DEFAULT_INTERVAL_MS 1000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int sdp32_start_continuous(void) {
    uint8_t cmd[2] = {0x36, 0x2F};
    int rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: failed to send continuous-measurement command (rc=%d)\n", rc);
        return -1;
    }
    return 0;
}

static int sdp32_read_measurement(float *pressure_pa, float *temperature_c) {
    uint8_t buf[9];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (rc != 9) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected 9)\n", rc);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Error: invalid scale factor (0)\n");
        return -1;
    }

    *pressure_pa = (float)raw_pressure / (float)scale_factor;
    *temperature_c = (float)raw_temperature / 200.0f;
    return 0;
}

static void log_data(float pressure_pa, float temperature_c) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("%s - Pressure: %.2f Pa, Temperature: %.2f C\n", ts, pressure_pa, temperature_c);
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    int interval_ms = DEFAULT_INTERVAL_MS;

    if (argc > 1) {
        interval_ms = atoi(argv[1]);
        if (interval_ms <= 0) {
            fprintf(stderr, "Warning: invalid interval '%s', using default %d ms\n", argv[1], DEFAULT_INTERVAL_MS);
            interval_ms = DEFAULT_INTERVAL_MS;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at bus %d addr 0x%02X (rc=%d)\n", I2C_BUS, SDP32_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (sdp32_start_continuous() != 0) {
        fprintf(stderr, "Error: sensor not responding at 0x%02X - check wiring\n", SDP32_ADDR);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float pressure_pa, temperature_c;
    int consecutive_errors = 0;

    while (!terminate) {
        if (sdp32_read_measurement(&pressure_pa, &temperature_c) == 0) {
            log_data(pressure_pa, temperature_c);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Warning: read failed (%d consecutive)\n", consecutive_errors);
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Error: max consecutive failures reached, aborting\n");
                break;
            }
        }
        gpioDelay(interval_ms * 1000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

