    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("%s - Pressure: %.2f Pa, Temperature: %.2f C\n", ts, pressure_pa, temperature_c);
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    int interval_ms = DEFAULT_INTERVAL_MS;

    if (argc > 1) {
        interval_ms = atoi(argv[1]);
        if (interval_ms <= 0) {
            fprintf(stderr, "Warning: invalid interval '%s', using default %d ms\n", argv[1], DEFAULT_INTERVAL_MS);
            interval_ms = DEFAULT_INTERVAL_MS;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at bus %d addr 0x%02X (rc=%d)\n", I2C_BUS, SDP32_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (sdp32_start_continuous() != 0) {
        fprintf(stderr, "Error: sensor not responding at 0x%02X - check wiring\n", SDP32_ADDR);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float pressure_pa, temperature_c;
    int consecutive_errors = 0;

    while (!terminate) {
        if (sdp32_read_measurement(&pressure_pa, &temperature_c) == 0) {
            log_data(pressure_pa, temperature_c);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Warning: read failed (%d consecutive)\n", consecutive_errors);
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Error: max consecutive failures reached, aborting\n");
                break;
            }
        }
        gpioDelay(interval_ms * 1000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

