#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90833_ADDR 0x60
#define READ_INTERVAL_US 500000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_pressure_raw(int handle, int16_t *raw_out) {
    char buf[2];
    int rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cReadDevice(handle, buf, 2);
        if (rc == 2) {
            *raw_out = (int16_t)((buf[0] << 8) | buf[1]);
            return 0;
        }
        fprintf(stderr, "I2C read attempt %d failed (rc=%d)\n", attempt + 1, rc);
        gpioDelay(10000);
    }
    return -1;
}

static int convert_to_pressure(int16_t raw, float *pressure_out) {
    /* MLX90833: 16-bit signed raw -> pressure in Pa (example linear mapping) */
    *pressure_out = (float)raw * 10.0f;
    return 0;
}

static void log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("[%s] Pressure: %.2f Pa\n", ts, pressure);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X (rc=%d)\n",
                I2C_BUS, MLX90833_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90833 pressure sensor reader started (I2C bus %d, addr 0x%02X)\n",
           I2C_BUS, MLX90833_ADDR);
    fflush(stdout);

    while (running) {
        int16_t raw;
        if (read_pressure_raw(i2c_handle, &raw) == 0) {
            float pressure;
            if (convert_to_pressure(raw, &pressure) == 0) {
                log_pressure(pressure);
            } else {
                fprintf(stderr, "Conversion error\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed after %d retries\n", MAX_RETRIES);
        }
        gpioDelay(READ_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

