#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ICP10101_ADDR  0x63
#define CMD_READ_OTP   0x50
#define CMD_MEASURE    0x40
#define MEASURE_DELAY  7000   /* microseconds */
#define SAMPLE_PERIOD  5      /* seconds */

/* Calibration coefficients */
static uint16_t scale_factor_lut = 0;
static uint16_t scale_factor_h   = 0;
static uint16_t scale_factor_p   = 0;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    if (i2cWriteByte(handle, cmd) < 0) {
        fprintf(stderr, "Error: i2cWriteByte(0x%02X) failed\n", cmd);
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int count)
{
    int n = i2cReadDevice(handle, (char *)buf, count);
    if (n != count) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected %d)\n", n, count);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* OTP calibration read                                                */
/* ------------------------------------------------------------------ */
static int read_calibration(int handle)
{
    uint8_t otp[8];

    if (i2c_write_cmd(handle, CMD_READ_OTP) < 0)
        return -1;

    gpioDelay(1000); /* 1 ms settle */

    if (i2c_read_bytes(handle, otp, sizeof(otp)) < 0)
        return -1;

    /* Check for sensor-absent / bus error (0xFF on all bytes) */
    for (int i = 0; i < (int)sizeof(otp); i++) {
        if (otp[i] != 0xFF) {
            scale_factor_lut = (uint16_t)((otp[0] << 8) | otp[1]);
            scale_factor_h   = (uint16_t)((otp[2] << 8) | otp[3]);
            scale_factor_p   = (uint16_t)((otp[4] << 8) | otp[5]);
            return 0;
        }
    }

    fprintf(stderr, "Error: OTP read returned all 0xFF (sensor absent?)\n");
    return -1;
}

/* ------------------------------------------------------------------ */
/* High-precision measurement                                          */
/* ------------------------------------------------------------------ */
static int read_measurement(int handle, float *temperature, float *pressure)
{
    uint8_t data[6];

    if (i2c_write_cmd(handle, CMD_MEASURE) < 0)
        return -1;

    gpioDelay(MEASURE_DELAY);

    if (i2c_read_bytes(handle, data, sizeof(data)) < 0)
        return -1;

    /* Check for sensor-absent / bus error (0xFF on all bytes) */
    for (int i = 0; i < (int)sizeof(data); i++) {
        if (data[i] != 0xFF) {
            uint16_t raw_t = (uint16_t)((data[0] << 8) | data[1]);
            uint32_t raw_p = (uint32_t)((data[2] << 24) |
                                        (data[3] << 16) |
                                        (data[4] << 8)  |
                                        data[5]);

            /* Datasheet compensation formulas */
            float t = (float)raw_t / 65536.0f;
            float p = (float)raw_p / 4294967295.0f;

            *temperature = t * 100.0f;          /* degrees C */
            *pressure    = p * scale_factor_p;   /* Pascals   */
            return 0;
        }
    }

    fprintf(stderr, "Error: measurement read returned all 0xFF (sensor absent?)\n");
    return -1;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    char ts[32];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ICP10101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ICP10101_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_calibration(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: failed to read calibration coefficients\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ICP-10101 sensor initialised. Sampling every %d s. Press Ctrl+C to stop.\n",
           SAMPLE_PERIOD);

    while (g_running) {
        float temperature, pressure;

        if (read_measurement(g_i2c_handle, &temperature, &pressure) == 0) {
            get_timestamp(ts, sizeof(ts));
            printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n",
                   ts, temperature, pressure);
            fflush(stdout);
        } else {
            get_timestamp(ts, sizeof(ts));
            fprintf(stderr, "%s - Error: failed to read sensor data\n", ts);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

