#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define LOG_FILE       "pressure_log.txt"
#define MEASURE_CMD    0x362F
#define MEASURE_DELAY  45000  /* microseconds */
#define CRC_POLY       0x31
#define CRC_INIT       0xFF

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        perror("i2c write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        perror("i2c read failed");
        return -1;
    }
    return 0;
}

static int read_sdp800(int fd, float *pressure, float *temperature) {
    if (i2c_write_cmd(fd, MEASURE_CMD) < 0)
        return -1;

    usleep(MEASURE_DELAY);

    uint8_t data[9];
    if (i2c_read_bytes(fd, data, sizeof(data)) < 0)
        return -1;

    /* Validate CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&data[i * 3], 2) != data[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temp     = (int16_t)((data[3] << 8) | data[4]);

    *pressure    = (float)raw_pressure / 60.0f;
    *temperature = (float)raw_temp     / 200.0f;
    return 0;
}

static void log_data(float pressure, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log failed");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                pressure, temperature);
    } else {
        fprintf(fp, "timestamp_error,%.2f,%.2f\n", pressure, temperature);
    }

    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        perror("open " I2C_BUS " failed");
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("ioctl I2C_SLAVE failed");
        close(g_fd);
        return EXIT_FAILURE;
    }

    printf("SDP800 HVAC monitor started. Logging to %s\n", LOG_FILE);

    while (g_running) {
        float pressure, temperature;
        if (read_sdp800(g_fd, &pressure, &temperature) == 0) {
            log_data(pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                   pressure, temperature);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        sleep(1);
    }

    printf("\nShutting down cleanly.\n");
    if (g_fd >= 0)
        close(g_fd);
    return EXIT_SUCCESS;
}

