#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MLX90821_ADDR  0x40
#define PRESSURE_REG   0x00
#define SCALE_FACTOR   0.01f
#define MIN_PRESSURE   200.0f
#define MAX_PRESSURE   250.0f
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_US      1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, MLX90821_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure)
{
    char buf[2];
    int  bytes;

    bytes = i2cReadI2CBlockData(g_i2c_handle, PRESSURE_REG, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "I2C read failed (got %d bytes, expected 2)\n", bytes);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *pressure = (float)raw * SCALE_FACTOR;
    return 0;
}

static void log_pressure(float pressure)
{
    time_t     t;
    struct tm  tm_utc;
    char       ts[32];

    time(&t);
    gmtime_r(&t, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    if (fprintf(g_log_file, "%s,%.2f\n", ts, pressure) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return;
    }
    fflush(g_log_file);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    long pos = ftell(g_log_file);
    if (pos == 0) {
        fprintf(g_log_file, "timestamp,pressure_kPa\n");
        fflush(g_log_file);
    }

    while (g_running) {
        float pressure;

        if (read_pressure(&pressure) == 0) {
            printf("Pressure: %.2f kPa\n", pressure);
            if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
                fprintf(stderr, "WARNING: Pressure %.2f kPa out of safe range [%.1f, %.1f]\n",
                        pressure, MIN_PRESSURE, MAX_PRESSURE);
            }
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Retrying I2C connection...\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

