#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE (1024 * 1024)
#define SAMPLE_INTERVAL_US 5000000
#define MEASUREMENT_DELAY_US 40000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
            timestamp, temperature, humidity);

    if (ftell(fp) > MAX_LOG_SIZE) {
        fclose(fp);
        fp = fopen(LOG_FILE, "w");
        if (!fp) {
            perror("fopen (truncate)");
            return -1;
        }
        fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                timestamp, temperature, humidity);
    } else {
        fclose(fp);
    }

    return 0;
}

static int read_hih6130(int handle, float *temperature, float *humidity) {
    unsigned char data[4];
    int result;

    result = i2cWriteByte(handle, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    result = i2cReadDevice(handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    if (data[0] & 0x01) {
        fprintf(stderr, "Sensor status bit indicates error\n");
        return -1;
    }

    unsigned int raw_humidity = ((unsigned int)data[0] << 8) | data[1];
    unsigned int raw_temperature = ((unsigned int)data[2] << 8) | data[3];

    *humidity = (float)raw_humidity * 100.0 / 16383.0;
    *temperature = (float)raw_temperature * 165.0 / 16383.0 - 40.0;

    return 0;
}

int main(void) {
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        if (read_hih6130(i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

