#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENT_GPIO 4
#define TICK_US 3
#define SYNC_TICKS 56
#define NIBBLE_TICKS_MIN 12
#define NIBBLE_TICKS_MAX 271
#define NIBBLES 5
#define TIMEOUT_US 1000000
#define LOG_FILE "pressure_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "%s, ERROR: %s\n", ts, msg);
}

static void log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        log_error("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(fp, "%s, Pressure: %.2f Pa\n", ts, pressure);
    fclose(fp);
}

static int wait_for_level(int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(SENT_GPIO) != level) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int read_nibble(uint8_t *nibble) {
    if (wait_for_level(1, TIMEOUT_US) < 0) return -1;
    uint32_t high_start = gpioTick();
    if (wait_for_level(0, TIMEOUT_US) < 0) return -1;
    uint32_t high_us = gpioTick() - high_start;
    uint32_t ticks = high_us / TICK_US;
    if (ticks < NIBBLE_TICKS_MIN || ticks > NIBBLE_TICKS_MAX) return -2;
    *nibble = (uint8_t)(ticks - NIBBLE_TICKS_MIN);
    return 0;
}

static int read_sent(uint16_t *raw) {
    if (wait_for_level(0, TIMEOUT_US) < 0) return -1;
    if (wait_for_level(1, TIMEOUT_US) < 0) return -1;
    uint8_t nibbles[NIBBLES];
    for (int i = 0; i < NIBBLES; i++) {
        int rc = read_nibble(&nibbles[i]);
        if (rc < 0) return rc;
    }
    uint8_t checksum = (nibbles[0] + nibbles[1] + nibbles[2] + nibbles[3]) & 0x0F;
    if (checksum != nibbles[4]) return -3;
    *raw = ((uint16_t)nibbles[1] << 8) | ((uint16_t)nibbles[2] << 4) | nibbles[3];
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(SENT_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP);

    float scale = 0.5f;
    float offset = 0.0f;

    while (running) {
        uint16_t raw = 0;
        int rc = read_sent(&raw);
        if (rc == 0) {
            float pressure = (float)raw * scale + offset;
            log_pressure(pressure);
        } else if (rc == -1) {
            log_error("Sensor absent (timeout)");
        } else if (rc == -2) {
            log_error("Bus error: invalid nibble width");
        } else if (rc == -3) {
            log_error("Bus error: checksum mismatch");
        }
        gpioDelay(100000);
    }

    gpioTerminate();
    return 0;
}

