#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEV_ID_REG 0x01
#define EXPECTED_DEV_ID 0x0117
#define LOG_FILE "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature register: %d\n", result);
        return -1;
    }
    int16_t raw = (int16_t)((buf[1] << 8) | buf[0]);
    *temperature = (float)raw * 0.0078125f;
    return 0;
}

static int log_temperature(FILE *fp, float temperature) {
    uint32_t timestamp = (uint32_t)time(NULL);
    if (fwrite(&timestamp, sizeof(timestamp), 1, fp) != 1) {
        fprintf(stderr, "Error writing timestamp: %s\n", strerror(errno));
        return -1;
    }
    if (fwrite(&temperature, sizeof(temperature), 1, fp) != 1) {
        fprintf(stderr, "Error writing temperature: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    char dev_id_buf[2];
    int dev_id_result = i2cReadI2CBlockData(i2c_handle, DEV_ID_REG, dev_id_buf, 2);
    if (dev_id_result != 2) {
        fprintf(stderr, "Error reading device ID: %d\n", dev_id_result);
        cleanup();
        return 1;
    }
    uint16_t dev_id = (uint16_t)((dev_id_buf[1] << 8) | dev_id_buf[0]);
    if (dev_id != EXPECTED_DEV_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%04X (expected 0x%04X)\n", dev_id, EXPECTED_DEV_ID);
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Greenhouse temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            if (log_temperature(log_file, temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            } else {
                printf("Temperature: %.2f °C\n", temperature);
            }
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

