#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define TMP117_ADDR    0x48
#define TEMP_REG       0x00
#define TEMP_LSB       0.0078125f
#define BUFFER_SIZE    100
#define LOG_FILE       "temperature_log.dat"
#define SAMPLE_PERIOD  5

typedef struct {
    float temperature;
    time_t timestamp;
} TemperatureReading;

static TemperatureReading temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: i2cReadI2CBlockData returned %d\n", result);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (float)raw * TEMP_LSB;
    return 0;
}

static void add_reading(float temperature) {
    time_t now = time(NULL);
    temperature_buffer[buffer_index].temperature = temperature;
    temperature_buffer[buffer_index].timestamp = now;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static int save_buffer_to_file(const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }
    size_t written = fwrite(temperature_buffer, sizeof(TemperatureReading), buffer_count, fp);
    if (written != (size_t)buffer_count) {
        fprintf(stderr, "Error writing to file: wrote %zu of %d entries\n", written, buffer_count);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("Error closing file");
        return -1;
    }
    return 0;
}

static int load_buffer_from_file(const char *filename) {
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) {
        fprintf(stderr, "Warning: could not open log file for reading; buffer is empty\n");
        return 0;
    }
    size_t read = fread(temperature_buffer, sizeof(TemperatureReading), BUFFER_SIZE, fp);
    if (read > 0) {
        buffer_count = (int)read;
        printf("Loaded %d temperature readings from log file\n", buffer_count);
    } else {
        fprintf(stderr, "Warning: file read returned %zu entries; buffer is empty\n", read);
    }
    if (fclose(fp) != 0) {
        perror("Error closing file");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d addr 0x%02X: %d\n", I2C_BUS, TMP117_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (load_buffer_from_file(LOG_FILE) != 0) {
        fprintf(stderr, "Failed to load log file; continuing with empty buffer\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting temperature logging (TMP117 @ 0x%02X, every %d s). Press Ctrl+C to stop.\n", TMP117_ADDR, SAMPLE_PERIOD);

    while (program_running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            add_reading(temperature);
            printf("Temperature: %.4f C\n", temperature);
            if (save_buffer_to_file(LOG_FILE) != 0) {
                fprintf(stderr, "Warning: failed to persist buffer to disk\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature; will retry next cycle\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    if (save_buffer_to_file(LOG_FILE) != 0) {
        fprintf(stderr, "Warning: failed to persist final buffer to disk\n");
    }
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

