#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define LOG_FILE "dht11_readings.txt"
#define SAMPLE_INTERVAL_US 2000000  /* 2 seconds */
#define MAX_TIMINGS 85
#define DHT11_START_LOW_US 18000
#define DHT11_START_HIGH_US 40
#define DHT11_RESP_LOW_US 80
#define DHT11_RESP_HIGH_US 80
#define DHT11_BIT_LOW_US 50
#define DHT11_BIT_THRESHOLD_US 50
#define DHT11_TIMEOUT_US 200

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    if (!log_fp) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_fp, "%s ERROR: %s\n", ts, msg);
    fflush(log_fp);
}

static void log_reading(float temp, float hum) {
    if (!log_fp) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_fp, "%s Temperature: %.1f C, Humidity: %.1f %%\n", ts, temp, hum);
    fflush(log_fp);
}

/*
 * Read DHT11 via bit-banged single-wire protocol.
 * Returns 0 on success, negative on error.
 */
static int read_dht11(float *temp, float *hum) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int counter = 0;
    int j = 0;

    /* --- Start signal: pull low >= 18 ms, then release --- */
    if (gpioSetMode(DHT11_GPIO, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(DHT11_GPIO, PI_LOW) < 0) return -1;
    gpioDelay(DHT11_START_LOW_US);
    if (gpioWrite(DHT11_GPIO, PI_HIGH) < 0) return -1;
    gpioDelay(DHT11_START_HIGH_US);

    /* --- Switch to input and sample response --- */
    if (gpioSetMode(DHT11_GPIO, PI_INPUT) < 0) return -1;
    gpioSetPullUpDown(DHT11_GPIO, PI_PUD_UP);

    /* Wait for sensor to pull line low (response start) */
    counter = 0;
    while (gpioRead(DHT11_GPIO) == PI_HIGH) {
        gpioDelay(1);
        if (++counter > DHT11_TIMEOUT_US) return -2; /* sensor absent */
    }
    /* Wait for response high */
    counter = 0;
    while (gpioRead(DHT11_GPIO) == PI_LOW) {
        gpioDelay(1);
        if (++counter > DHT11_TIMEOUT_US) return -3; /* sensor absent */
    }
    /* Wait for response low */
    counter = 0;
    while (gpioRead(DHT11_GPIO) == PI_HIGH) {
        gpioDelay(1);
        if (++counter > DHT11_TIMEOUT_US) return -4; /* sensor absent */
    }

    /* --- Read 40 data bits --- */
    for (j = 0; j < MAX_TIMINGS; j++) {
        counter = 0;
        while (gpioRead(DHT11_GPIO) == laststate) {
            gpioDelay(1);
            if (++counter > DHT11_TIMEOUT_US) return -5; /* stuck */
        }
        laststate = gpioRead(DHT11_GPIO);
        if (counter > DHT11_BIT_THRESHOLD_US) {
            data[j / 8] <<= 1;
            if (counter > DHT11_BIT_THRESHOLD_US + 40) {
                data[j / 8] |= 1;
            }
        }
    }

    /* --- Checksum validation --- */
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -6; /* checksum error */
    }

    /* DHT11: byte 0 = humidity integer, byte 1 = 0, byte 2 = temp integer, byte 3 = 0 */
    *hum = (float)data[0];
    *temp = (float)data[2];
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        float temp = 0.0f, hum = 0.0f;
        int rc = read_dht11(&temp, &hum);

        if (rc == 0) {
            log_reading(temp, hum);
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
        } else {
            const char *err_msg;
            switch (rc) {
                case -2: err_msg = "Sensor absent: line stuck high (start wait)"; break;
                case -3: err_msg = "Sensor absent: response low timeout"; break;
                case -4: err_msg = "Sensor absent: response high timeout"; break;
                case -5: err_msg = "Stuck line during data read"; break;
                case -6: err_msg = "Checksum error"; break;
                default: err_msg = "DHT11 read failed (unknown error)"; break;
            }
            log_error(err_msg);
            fprintf(stderr, "DHT11 read failed: %s\n", err_msg);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 20 && running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Cleanup */
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

