static int read_register16(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteI2CBlockData(handle, reg, buf, 0) < 0) {
        return -1;
    }
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

