#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define RAW_PRESSURE_REG 0x0A2C
#define RAW_TEMP_REG 0x0A2E
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_SEC 2

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

static void log_line(const char *msg) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(log_file, "%s %s\n", ts, msg);
    fflush(log_file);
}

static int read_raw_register(uint16_t reg, uint16_t *value) {
    char reg_buf[2] = { (char)((reg >> 8) & 0xFF), (char)(reg & 0xFF) };
    char data[2] = {0};

    if (i2cWriteDevice(i2c_handle, reg_buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int read_pressure(float *pressure_kPa) {
    uint16_t raw;
    if (read_raw_register(RAW_PRESSURE_REG, &raw) != 0) {
        return -1;
    }
    *pressure_kPa = (float)(raw - 0) * (800.0f - 0.0f) / (32768.0f - 0.0f);
    return 0;
}

static int read_temperature(float *temp_C) {
    uint16_t raw;
    if (read_raw_register(RAW_TEMP_REG, &raw) != 0) {
        return -1;
    }
    *temp_C = (float)raw * 0.01f - 40.0f;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n",
                I2C_BUS, MLX90824_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_line("Program started");

    while (running) {
        float pressure_kPa = 0.0f;
        float temp_C = 0.0f;
        char line[256];

        if (read_pressure(&pressure_kPa) == 0 && read_temperature(&temp_C) == 0) {
            snprintf(line, sizeof(line), "Pressure: %.2f kPa, Temperature: %.2f C", pressure_kPa, temp_C);
        } else {
            snprintf(line, sizeof(line), "Error reading sensor data");
        }

        log_line(line);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    log_line("Program stopped");
    cleanup();
    return EXIT_SUCCESS;
}

