#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS        1
#define LM75B_ADDR     0x48
#define TEMP_REG       0x00
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD  1.0
#define TEMP_THRESHOLD_HIGH  28.0
#define TEMP_THRESHOLD_LOW   26.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temp_out) {
    int raw = i2cReadWordData(handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "I2C read error: %d\n", raw);
        return -1;
    }
    /* LM75B: 9-bit signed, 0.5 °C resolution, bits D9-D1, D0 = 0 */
    int16_t signed_val = (int16_t)(raw & 0x03FF);
    if (signed_val & 0x0200) {
        signed_val |= 0xFC00; /* sign-extend to 16 bits */
    }
    *temp_out = (float)signed_val * 0.5f;
    return 0;
}

static void control_fan(float avg_temp) {
    static int fan_on = 0;
    if (avg_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON  (avg=%.2f)\n", avg_temp);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (avg_temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (avg=%.2f)\n", avg_temp);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, LM75B_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    float temp_buffer[BUFFER_SIZE];
    int   buf_index = 0;
    int   buf_count = 0;
    float sum = 0.0f;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LM75B temperature monitor started (I2C bus %d, addr 0x%02X, fan GPIO %d)\n",
           I2C_BUS, LM75B_ADDR, FAN_GPIO);

    while (running) {
        float temp;
        if (read_temperature(i2c_handle, &temp) == 0) {
            sum -= temp_buffer[buf_index];
            temp_buffer[buf_index] = temp;
            sum += temp;
            buf_index = (buf_index + 1) % BUFFER_SIZE;
            if (buf_count < BUFFER_SIZE) buf_count++;

            float avg = (buf_count > 0) ? (sum / buf_count) : 0.0f;
            printf("Temp: %.2f C  |  Avg: %.2f C  |  Fan: %s\n",
                   temp, avg, gpioRead(FAN_GPIO) ? "ON" : "OFF");
            control_fan(avg);
        } else {
            fprintf(stderr, "Temperature read failed; will retry next cycle\n");
        }

        time_sleep(SAMPLE_PERIOD);
    }

    /* Graceful shutdown */
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

