#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define LOG_FILE       "airflow.log"
#define PRESSURE_THRESHOLD 5.0f
#define SAMPLE_PERIOD_US 1000000  /* 1 second */
#define MEAS_DELAY_US   45000     /* 45 ms for first measurement */

/* SDP810 continuous measurement command (mass flow, no averaging) */
static const uint8_t CMD_CONT_MEAS[2] = {0x36, 0x2F};

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no final XOR           */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Write a 2-byte command to the SDP810                                */
/* ------------------------------------------------------------------ */
static int sdp810_write_cmd(int handle, const uint8_t *cmd, size_t len)
{
    if (i2cWriteDevice(handle, (char *)cmd, len) != 0) {
        fprintf(stderr, "[ERROR] I2C write failed (cmd %02X%02X)\n",
                cmd[0], cmd[1]);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 9 bytes from the SDP810 and validate CRCs                      */
/* ------------------------------------------------------------------ */
static int sdp810_read_measurement(int handle,
                                   float *pressure,
                                   float *temperature)
{
    uint8_t buf[9];
