#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x4A
#define TEMP_REG       0x00
#define LED_PIN        17
#define TEMP_HIGH      28.0f
#define TEMP_LOW       27.0f
#define POLL_DELAY_US  1000000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static float convert_temp(uint16_t raw)
{
    return (float)(raw >> 4) * 0.0625f;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", STTS2004_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "gpiod_chip_get_line %d failed: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led, "stts2004-led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    bool led_on = false;
    int consecutive_errors = 0;

    while (g_running) {
        uint16_t raw;
        if (i2c_read_reg16(i2c_fd, TEMP_REG, &raw) == 0) {
            consecutive_errors = 0;
            float temp = convert_temp(raw);
            printf("Temperature: %.2f C\n", temp);
            fflush(stdout);

            if (temp > TEMP_HIGH && !led_on) {
                if (gpiod_line_set_value(led, 1) < 0) {
                    fprintf(stderr, "gpiod_line_set_value high failed: %s\n", strerror(errno));
                } else {
                    led_on = true;
                    printf("LED ON\n");
                }
            } else if (temp < TEMP_LOW && led_on) {
                if (gpiod_line_set_value(led, 0) < 0) {
                    fprintf(stderr, "gpiod_line_set_value low failed: %s\n", strerror(errno));
                } else {
                    led_on = false;
                    printf("LED OFF\n");
                }
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "I2C read error (%d consecutive)\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many I2C errors, aborting.\n");
                break;
            }
        }
        usleep(POLL_DELAY_US);
    }

    if (led_on) {
        gpiod_line_set_value(led, 0);
    }
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

