#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define SAMPLE_INTERVAL 60
#define MAX_RETRIES    3
#define MEASURE_DELAY_US 20000  /* 20 ms */

/* Si7021 commands (single-byte, no register addressing) */
#define CMD_MEASURE_RH_NOHOLD  0xF5
#define CMD_MEASURE_TEMP_NOHOLD 0xF3
#define CMD_READ_PREV_TEMP     0xE0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single command byte to the Si7021 */
static int si7021_write_cmd(int handle, uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    int rc = i2cWriteDevice(handle, buf, 1);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed for cmd 0x%02X: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

/* Read N bytes from the Si7021 after a previous command */
static int si7021_read_bytes(int handle, uint8_t *buf, int len)
{
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "[ERROR] i2cReadDevice expected %d bytes, got %d\n", len, rc);
        return -1;
    }
    return 0;
}

/* Read a 16-bit raw value from the Si7021 after issuing a measurement command */
static int si7021_read_raw(int handle, uint8_t cmd, uint16_t *raw)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (si7021_write_cmd(handle, cmd) != 0) {
            gpioDelay(10000); /* 10 ms backoff */
            continue;
        }
        gpioDelay(MEASURE_DELAY_US);

        uint8_t buf[3];
        if (si7021_read_bytes(handle, buf, 3) != 0) {
            gpioDelay(10000);
            continue;
        }

        *raw = ((uint16_t)buf[0] << 8) | buf[1];
        return 0;
    }
    return -1;
}

/* Read temperature from the previous RH measurement (command 0xE0) */
static int si7021_read_temperature(int handle, float *temp_c)
{
    uint16_t raw;
    if (si7021_read_raw(handle, CMD_READ_PREV_TEMP, &raw) != 0)
        return -1;
    *temp_c = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

/* Read relative humidity (issues 0xF5, reads 3 bytes) */
static int si7021_read_humidity(int handle, float *rh)
{
    uint16_t raw;
    if (si7021_read_raw(handle, CMD_MEASURE_RH_NOHOLD, &raw) != 0)
        return -1;
    float h = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (h < 0.0f)   h = 0.0f;
    if (h > 100.0f) h = 100.0f;
    *rh = h;
    return 0;
}

/* Read temperature and humidity; returns 0 on success, -1 on failure */
static int read_sensor(int handle, float *temp_c, float *rh)
{
    if (si7021_read_humidity(handle, rh) != 0)
        return -1;
    if (si7021_read_temperature(handle, temp_c) != 0)
        return -1;
    return 0;
}

static void log_data(float temp_c, float rh)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen log");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, rh);
    } else {
        fprintf(fp, "1970-01-01T00:00:00,%.2f,%.2f\n", temp_c, rh);
    }
    fflush(fp);
    fclose(fp);

    printf("%s,%.2f,%.2f\n", ts, temp_c, rh);
}

static void log_error(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,ERROR,%s\n", ts, msg);
    } else {
        fprintf(fp, "1970-01-01T00:00:00,ERROR,%s\n", msg);
    }
    fflush(fp);
    fclose(fp);
    fprintf(stderr, "[ERROR] %s\n", msg);
}

static int init_sensor(int handle)
{
    /* Read firmware revision (command 0xFA) to confirm sensor is present */
    uint8_t buf[2];
    if (si7021_write_cmd(handle, 0xFA) != 0)
        return -1;
    gpioDelay(10000);
    if (si7021_read_bytes(handle, buf, 2) != 0)
        return -1;
    uint16_t rev = ((uint16_t)buf[0] << 8) | buf[1];
    if (rev == 0x0000 || rev == 0xFFFF) {
        fprintf(stderr, "[ERROR] Si7021 not responding or not present\n");
        return -1;
    }
    printf("Si7021 detected (firmware rev 0x%04X)\n", rev);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] Sensor initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting data logging (interval %d s)...\n", SAMPLE_INTERVAL);

    while (g_running) {
        float temp_c = 0.0f, rh = 0.0f;
        if (read_sensor(g_i2c_handle, &temp_c, &rh) == 0) {
            log_data(temp_c, rh);
        } else {
            log_error("Failed to read sensor data");
        }
        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return 0;
}

