#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HDC1080_ADDR 0x40
#define HDC1080_TEMP_REG 0x00
#define HDC1080_CONFIG_REG 0x02
#define HDC1080_CONFIG_14BIT 0x0000
#define LOG_FILE "enviro_log.txt"
#define I2C_BUS 1
#define CONVERSION_DELAY_US 20000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_hdc1080(void) {
    if (i2cWriteWordData(i2c_handle, HDC1080_CONFIG_REG, HDC1080_CONFIG_14BIT) < 0) {
        fprintf(stderr, "Error: Failed to write HDC1080 config register.\n");
        return -1;
    }
    return 0;
}

static int read_hdc1080(float *temperature, float *humidity) {
    char buf[4];
    int result;

    result = i2cWriteByte(i2c_handle, HDC1080_TEMP_REG);
    if (result < 0) {
        fprintf(stderr, "Error: Failed to set HDC1080 pointer to temperature register.\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error: Failed to read HDC1080 data (read %d bytes).\n", result);
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t raw_humidity = ((uint16_t)buf[2] << 8) | (uint8_t)buf[3];

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_humidity / 65536.0f) * 100.0f;

    return 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, HDC1080_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_hdc1080() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;

    while (!terminate) {
        if (read_hdc1080(&temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Warning: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: Failed to read sensor data.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 5, 0);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

