{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = i2c_open(I2C_BUS, STS40_ADDR);
    if (g_i2c_fd < 0)
        return 1;

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    while (g_running) {
        float temperature;
        if (sts40_read(g_i2c_fd, &temperature) == 0) {
            log_temperature(g_log_fp, temperature);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    if (g_log_fp)  fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

