#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data"
#define ERROR_LOG "/var/log/scd40_error.log"
#define SCD40_CMD_START_PERIODIC 0x21B1
#define SCD40_CMD_STOP_PERIODIC 0x3F86
#define SCD40_CMD_READ_MEASUREMENT 0xE000
#define MEASUREMENT_DELAY_US 1000000
#define LOOP_DELAY_US 5000000
#define LOG_INTERVAL_S 60

typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

static int i2c_handle = -1;
static CircularBuffer buffer;
static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;
static FILE *error_log_fp = NULL;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static void log_error(const char *message) {
    if (!error_log_fp) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
