#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEVICE    "/dev/i2c-1"
#define ICP10125_ADDR 0x63
#define GPIO_CHIP     "gpiochip4"
#define LED_PIN       17
#define PRESSURE_THRESHOLD 95000.0f
#define POLL_INTERVAL_US  1000000
#define MEAS_DELAY_US     20000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/* CRC-8 polynomial 0x31, init 0x00, no reflection, no final XOR — InvenSense spec */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write cmd 0x%04X failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed (got %zd of %zu): %s\n", n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_calibration(int fd, float *c0, float *c1, float *c00, float *c10) {
    if (i2c_write_cmd(fd, 0x6600) < 0) return -1;
    usleep(10000);

    uint8_t buf[8];
    if (i2c_read_bytes(fd, buf, 8) < 0) return -1;

    if (crc8(buf, 6) != buf[7]) {
        fprintf(stderr, "Calibration CRC mismatch\n");
        return -1;
    }

    uint32_t c0_raw = ((uint32_t)buf[0] << 24) | ((uint32_t)buf[1] << 16) |
                      ((uint32_t)buf[2] << 8)  | buf[3];
    uint32_t c1_raw = ((uint32_t)buf[4] << 24) | ((uint32_t)buf[5] << 16) |
                      ((uint32_t)buf[6] << 8)  | buf[7];

    *c0  = (float)c0_raw / 8192.0f;
    *c1  = (float)c1_raw / 8192.0f;
    *c00 = (float)c0_raw / 8192.0f;
    *c10 = (float)c1_raw / 8192.0f;
    return 0;
}

static int read_sensor(int fd, float *pressure, float *temperature) {
    if (i2c_write_cmd(fd, 0x4011) < 0) return -1;
    usleep(MEAS_DELAY_US);

    uint8_t buf[6];
    if (i2c_read_bytes(fd, buf, 6) < 0) return -1;

    if (crc8(buf, 4) != buf[5]) {
        fprintf(stderr, "Measurement CRC mismatch\n");
        return -1;
    }

    uint32_t raw_p = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    uint32_t raw_t = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | buf[5];

    *temperature = (float)raw_t / 65536.0f * 165.0f - 40.0f;

    float p = (float)raw_p / 65536.0f;
    float t = (float)raw_t / 65536.0f;
    *pressure = *c0 * 100.0f + *c1 * p * 100.0f + *c00 * t * 100.0f + *c10 * p * t * 100.0f;

    return 0;
}

int main(void) {
    struct sigaction sa = { .sa_handler = sigint_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_DEVICE);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    float c0, c1, c00, c10;
    if (read_calibration(i2c_fd, &c0, &c1, &c00, &c10) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led, "icp10125_led", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("ICP-10125 initialized. Polling every 1 s. Ctrl+C to exit.\n");

    while (running) {
        float pressure, temperature;
        if (read_sensor(i2c_fd, &pressure, &temperature) < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
        } else {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
            if (pressure < PRESSURE_THRESHOLD) {
                printf("WARNING: High altitude detected!\n");
                gpiod_line_set_value(led, 1);
                usleep(100000);
                gpiod_line_set_value(led, 0);
                usleep(100000);
            } else {
                gpiod_line_set_value(led, 1);
                usleep(500000);
                gpiod_line_set_value(led, 0);
                usleep(500000);
            }
        }
        usleep(POLL_INTERVAL_US);
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

