#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS        1
#define I2C_ADDR       0x5A
#define FAN_GPIO       18
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG  0x07
#define TEMP_SCALE     0.02f
#define TEMP_OFFSET    273.15f
#define TEMP_HIGH      30.0f
#define TEMP_LOW       28.0f
#define LOG_FILE       "temperature_log.txt"
#define READ_RETRIES   3
#define RETRY_DELAY_US 10000
#define POLL_INTERVAL  2

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_temperature(int handle, uint8_t reg, float *temp_out) {
    int raw = i2cReadWordData(handle, reg);
    if (raw < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", reg, raw);
        return -1;
    }
    int16_t signed_raw = (int16_t)raw;
    *temp_out = (float)signed_raw * TEMP_SCALE - TEMP_OFFSET;
    return 0;
}

static int log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Ambient: %.2f C, Object: %.2f C\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                ambient, object);
    }
    fclose(fp);
    return 0;
}

static void control_fan(float object_temp) {
    static int fan_on = 0;
    if (object_temp > TEMP_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON  (Object: %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (object_temp < TEMP_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (Object: %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90614 temperature monitor started. Ctrl+C to exit.\n");

    while (g_running) {
        float ambient = 0.0f, object = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < READ_RETRIES && g_running; attempt++) {
            if (read_temperature(g_i2c_handle, AMBIENT_TEMP_REG, &ambient) == 0 &&
                read_temperature(g_i2c_handle, OBJECT_TEMP_REG, &object) == 0) {
                ok = 1;
                break;
            }
            if (attempt < READ_RETRIES - 1) {
                fprintf(stderr, "Retrying I2C read (%d/%d)...\n", attempt + 1, READ_RETRIES);
                gpioDelay(RETRY_DELAY_US);
            }
        }

        if (ok) {
            printf("Ambient: %.2f C, Object: %.2f C\n", ambient, object);
            if (log_temperature(ambient, object) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
            control_fan(object);
        } else {
            fprintf(stderr, "All I2C read attempts failed; skipping cycle\n");
        }

        for (int i = 0; i < POLL_INTERVAL && g_running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

