#define HDC2010_ADDR        0x40
#define REG_TEMP_LOW        0x00
#define REG_TEMP_HIGH       0x01
#define REG_HUM_LOW         0x02
#define REG_HUM_HIGH        0x03
#define REG_MEAS_CONFIG     0x0E
#define REG_CONFIG          0x0F
#define MEAS_TRIGGER        0x01
#define CONFIG_DEFAULT      0x00
#define I2C_BUS             1
#define POLL_TIMEOUT_US     500000
#define POLL_INTERVAL_US    1000
#define MAX_RETRIES         10
#define SAMPLE_INTERVAL_S   5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int write_register(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_word(uint8_t low_reg, uint16_t *out) {
    uint8_t lo, hi;
    if (read_register(low_reg, &lo) < 0) return -1;
    if (read_register(low_reg + 1, &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int trigger_and_wait(void) {
    if (write_register(REG_MEAS_CONFIG, MEAS_TRIGGER) < 0) return -1;
    for (int i = 0; i < MAX_RETRIES; i++) {
        uint8_t cfg;
        if (read_register(REG_MEAS_CONFIG, &cfg) < 0) return -1;
        if ((cfg & 0x01) == 0) return 0;
        gpioDelay(POLL_INTERVAL_US);
    }
    fprintf(stderr, "Measurement conversion timeout\n");
    return -1;
}

static int read_hdc2010(float *temp, float *hum) {
    if (trigger_and_wait() < 0) return -1;
    uint16_t raw_t, raw_h;
    if (read_word(REG_TEMP_LOW, &raw_t) < 0) return -1;
    if (read_word(REG_HUM_LOW, &raw_h) < 0) return -1;
    *temp = ((float)raw_t / 65536.0f) * 165.0f - 40.0f;
    *hum  = ((float)raw_h / 65536.0f) * 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, HDC2010_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (write_register(REG_CONFIG, CONFIG_DEFAULT) < 0) {
        fprintf(stderr, "Failed to configure HDC2010\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float temp, hum;
        if (read_hdc2010(&temp, &hum) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }
        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

