#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x2F
#define MEASUREMENT_DELAY_US 45000
#define READ_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* CRC-8 as used by Sensirion: polynomial 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_sdp800(int handle, int16_t *pressure, int16_t *temperature) {
    uint8_t cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (trigger measurement).\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed (expected 6 bytes).\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }

    *pressure = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP800-500Pa sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t pressure, temperature;
        if (read_sdp800(i2c_handle, &pressure, &temperature) == 0) {
            printf("Pressure: %d, Temperature: %d\n", pressure, temperature);
        }
        gpioDelay(READ_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

