#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define RELAY_PIN 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;
FILE *profile_file = NULL;
int spi_fd = -1;
struct gpiod_chip *chip = NULL;
struct gpiod_line *relay_line = NULL;

typedef struct {
    float target_temp;
    time_t start_time;
} ProfilePoint;

ProfilePoint *profile = NULL;
int profile_size = 0;
int current_profile_index = 0;
float Kp = 1.0, Ki = 0.1, Kd = 0.01;
float integral = 0.0, previous_error = 0.0;
float current_time = 0.0;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to configure SPI");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    return 0;
}

int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(relay_line, "reflow-oven", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        chip = NULL;
        relay_line = NULL;
        return -1;
    }
    return 0;
}

int read_profile(void) {
    profile_file = fopen(PROFILE_FILE, "r");
    if (!profile_file) {
        perror("Failed to open profile file");
        return -1;
    }
    profile_size = 0;
    profile = malloc(sizeof(ProfilePoint) * 100);
    if (!profile) {
        perror("Failed to allocate memory for profile");
        fclose(profile_file);
        profile_file = NULL;
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), profile_file)) {
        if (profile_size >= 100) break;
