#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_DIR "/sys/bus/w1/devices/"
#define SENSOR_FILE "w1_slave"
#define LOG_FILE "greenhouse.log"
#define HEATER_GPIO 17
#define PWM_GPIO 18
#define PWM_PERIOD_NS 10000000  // 10ms = 100Hz
#define PWM_RANGE 100
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *heater_line = NULL;
static struct gpiod_line *pwm_line = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_temperature(const char *sensor_id, float *temp) {
    char path[256];
    char line[256];
    FILE *fp;
    int crc_ok = 0;

    snprintf(path, sizeof(path), "%s%s/%s", SENSOR_DIR, sensor_id, SENSOR_FILE);
    fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading first line from %s\n", path);
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (strstr(line, "YES") != NULL) {
        crc_ok = 1;
    } else {
        fprintf(stderr, "CRC check failed for sensor %s\n", sensor_id);
        return -1;
    }

    fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error re-opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading second line from %s\n", path);
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *temp_str = strstr(line, "t=");
    if (!temp_str) {
        fprintf(stderr, "Temperature data not found in %s\n", path);
        return -1;
    }

    long raw = strtol(temp_str + 2, NULL, 10);
    *temp = (float)raw / 1000.0f;
    return 0;
}

int set_heater(int state) {
    if (gpiod_line_set_value(heater_line, state) < 0) {
        fprintf(stderr, "Error setting heater GPIO %d: %s\n", HEATER_GPIO, strerror(errno));
        return -1;
    }
    return 0;
}

int set_pwm_duty(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    int period_ns = PWM_PERIOD_NS;
    int on_ns = (period_ns * duty) / PWM_RANGE;
    int off_ns = period_ns - on_ns;

    if (gpiod_line_set_value(pwm_line, 1) < 0) {
        fprintf(stderr, "Error setting PWM high: %s\n", strerror(errno));
        return -1;
    }
    usleep(on_ns / 1000);
    if (gpiod_line_set_value(pwm_line, 0) < 0) {
        fprintf(stderr, "Error setting PWM low: %s\n", strerror(errno));
        return -1;
    }
    usleep(off_ns / 1000);
    return 0;
}

void log_data(float avg_temp, float setpoint, float pid_out, int duty) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, avg_temp, setpoint, pid_out, duty);
    fflush(log_file);
}

void cleanup() {
    if (heater_line) {
        gpiod_line_set_value(heater_line, 0);
        gpiod_line_release(heater_line);
    }
    if (pwm_line) {
        gpiod_line_set_value(pwm_line, 0);
        gpiod_line_release(pwm_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

int main(int argc, char *argv[]) {
    float setpoint = 25.0f;
    float Kp = 1.0f, Ki = 0.1f, Kd = 0.01f;

    if (argc > 1) setpoint = atof(argv[1]);
    if (argc > 2) Kp = atof(argv[2]);
    if (argc > 3) Ki = atof(argv[3]);
    if (argc > 4) Kd = atof(argv[4]);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    heater_line = gpiod_chip_get_line(chip, HEATER_GPIO);
    if (!heater_line) {
        fprintf(stderr, "Error getting heater GPIO %d: %s\n", HEATER_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    pwm_line = gpiod_chip_get_line(chip, PWM_GPIO);
    if (!pwm_line) {
        fprintf(stderr, "Error getting PWM GPIO %d: %s\n", PWM_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(heater_line, "greenhouse_heater", 0) < 0) {
        fprintf(stderr, "Error requesting heater GPIO as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(pwm_line, "greenhouse_pwm", 0) < 0) {
        fprintf(stderr, "Error requesting PWM GPIO as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Greenhouse heater controller started. Setpoint: %.2f°C, Kp: %.2f, Ki: %.2f, Kd: %.2f\n", setpoint, Kp, Ki, Kd);

    char sensor_ids[256];
    int num_sensors = 0;
    DIR *d = opendir(SENSOR_DIR);
    if (d) {
        struct dirent *dir;
        while ((dir = readdir(d)) != NULL && num_sensors < 255) {
            if (strstr(dir->d_name, "28-") != NULL) {
                strncpy(sensor_ids + num_sensors, dir->d_name, 255 - num_sensors);
                num_sensors += strlen(dir->d_name) + 1;
            }
        }
        closedir(d);
    } else {
        fprintf(stderr, "Error opening sensor directory: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    sensor_ids[num_sensors - 1] = '\0';

    if (num_sensors == 0) {
        fprintf(stderr, "No DS18B20 sensors found. Exiting.\n");
        cleanup();
        return 1;
    }

    float integral = 0.0f;
    float prev_error = 0.0f;

    while (running) {
        float sum_temp = 0.0f;
        int valid = 0;

        for (int i = 0; i < num_sensors; i++) {
            float temp;
            if (read_temperature(sensor_ids + i, &temp) == 0) {
                sum_temp += temp;
                valid++;
            } else {
                fprintf(stderr, "Error reading sensor %s\n", sensor_ids + i);
            }
        }

        if (valid == 0) {
            fprintf(stderr, "No valid temperature readings. Skipping PID calculation.\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float avg_temp = sum_temp / valid;
        float error = setpoint - avg_temp;
        integral += error;
        float derivative = error - prev_error;
        float pid_output = Kp * error + Ki * integral + Kd * derivative;
        prev_error = error;

        if (pid_output < 0) pid_output = 0;
        if (pid_output > PWM_RANGE) pid_output = PWM_RANGE;

        if (set_pwm_duty((int)pid_output) < 0) {
            fprintf(stderr, "Error setting PWM duty cycle.\n");
        }

        log_data(avg_temp, setpoint, pid_output, (int)pid_output);
        printf("Avg Temp: %.2f°C, Setpoint: %.2f°C, PID Output: %.2f, PWM Duty: %d\n", avg_temp, setpoint, pid_output, (int)pid_output);

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    set_heater(0);
    set_pwm_duty(0);
    cleanup();
    return 0;
}

