#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define AHT20_ADDR 0x38
#define I2C_BUS "/dev/i2c-1"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define HUMIDITY_HIGH 60.0f
#define HUMIDITY_LOW 55.0f
#define POLL_INTERVAL_SEC 5
#define AHT20_INIT_CMD_LEN 3
#define AHT20_MEASURE_CMD_LEN 3
#define AHT20_DATA_LEN 6
#define AHT20_INIT_DELAY_MS 20
#define AHT20_MEASURE_DELAY_MS 80
#define AHT20_BUSY_MASK 0x01
#define AHT20_CALIB_MASK 0x02
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, cmd, len) == (ssize_t)len) return 0;
        fprintf(stderr, "I2C write attempt %d failed\n", attempt + 1);
        if (attempt < MAX_RETRIES - 1) usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        ssize_t n = read(fd, buf, len);
        if (n == (ssize_t)len) return 0;
        fprintf(stderr, "I2C read attempt %d failed (got %zd bytes)\n", attempt + 1, n);
        if (attempt < MAX_RETRIES - 1) usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int aht20_init(int fd) {
    uint8_t init_cmd[AHT20_INIT_CMD_LEN] = {0xBE, 0x08, 0x00};
    if (i2c_write_cmd(fd, init_cmd, AHT20_INIT_CMD_LEN) != 0) {
        fprintf(stderr, "AHT20 initialization write failed\n");
        return -1;
    }
    usleep(AHT20_INIT_DELAY_MS * 1000);
    return 0;
}

static int aht20_read_humidity(int fd, float *humidity) {
    uint8_t measure_cmd[AHT20_MEASURE_CMD_LEN] = {0xAC, 0x33, 0x00};
    if (i2c_write_cmd(fd, measure_cmd, AHT20_MEASURE_CMD_LEN) != 0) {
        fprintf(stderr, "AHT20 measurement trigger failed\n");
        return -1;
    }
    usleep(AHT20_MEASURE_DELAY_MS * 1000);

    uint8_t data[AHT20_DATA_LEN];
    if (i2c_read_data(fd, data, AHT20_DATA_LEN) != 0) {
        fprintf(stderr, "AHT20 data read failed\n");
        return -1;
    }

    if (!(data[0] & AHT20_BUSY_MASK)) {
        fprintf(stderr, "AHT20 busy (status=0x%02X)\n", data[0]);
        return -1;
    }
    if (!(data[0] & AHT20_CALIB_MASK)) {
        fprintf(stderr, "AHT20 not calibrated (status=0x%02X)\n", data[0]);
        return -1;
    }

    uint32_t raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
    *humidity = ((float)raw / 1048576.0f) * 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    if (aht20_init(i2c_fd) != 0) {
        fprintf(stderr, "AHT20 init failed; sensor may be absent\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line *relay = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!relay) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(relay, "aht20-dehumidifier", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    int relay_state = 0;

    while (running) {
        float humidity;
        if (aht20_read_humidity(i2c_fd, &humidity) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Humidity: %.2f%%\n", ts, humidity);
            fflush(stdout);

            if (humidity > HUMIDITY_HIGH && relay_state == 0) {
                if (gpiod_line_set_value(relay, 1) == 0) {
                    relay_state = 1;
                    printf("[%s] Dehumidifier ON\n", ts);
                } else {
                    perror("gpiod_line_set_value ON");
                }
            } else if (humidity < HUMIDITY_LOW && relay_state == 1) {
                if (gpiod_line_set_value(relay, 0) == 0) {
                    relay_state = 0;
                    printf("[%s] Dehumidifier OFF\n", ts);
                } else {
                    perror("gpiod_line_set_value OFF");
                }
            }
        } else {
            fprintf(stderr, "Sensor read failed after retries; continuing\n");
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(relay, 0);
    gpiod_line_release(relay);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return 0;
}

