#define HTU21D_CMD_HUMID_HOLD 0xE5
#define HTU21D_CMD_SOFT_RESET 0xFE
#define HTTP_SERVER "api.example.com"
#define HTTP_PORT 80
#define HTTP_ENDPOINT "/humidity"
#define SAMPLE_INTERVAL 60
#define MAX_RETRIES 3
#define MAX_RETRIES_DELAY 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sock_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, unsigned char byte) {
    if (write(fd, &byte, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, unsigned char *buf, int len) {
    if (read(fd, buf, len) != len) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int htu21d_reset(int fd) {
    if (i2c_write_byte(fd, HTU21D_CMD_SOFT_RESET) < 0) {
        syslog(LOG_ERR, "HTU21D soft reset failed");
        return -1;
    }
    usleep(15000);
    return 0;
}

static int htu21d_read_humidity(int fd, float *humidity) {
    unsigned char cmd = HTU21D_CMD_HUMID_HOLD;
    unsigned char data[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_byte(fd, cmd) < 0) {
            retries++;
            syslog(LOG_WARNING, "Humidity write failed, retry %d", retries);
            usleep(100000);
            continue;
        }

        usleep(20000);

        if (i2c_read_bytes(fd, data, 3) < 0) {
            retries++;
            syslog(LOG_WARNING, "Humidity read failed, retry %d", retries);
            usleep(100000);
            continue;
        }

        int humidity_raw = (data[0] << 8) | data[1];
        int humidity_crc = data[2];

        int expected_crc = 0;
        for (int i = 0; i < 2; i++) {
            expected_crc ^= (humidity_raw >> (16 - 2 - i)) & 0x01;
            for (int j = 0; j < 8; j++) {
                if (expected_crc & 0x80) {
                    expected_crc = (expected_crc << 1) ^ 0x983000UL;
                } else {
                    expected_crc <<= 1;
                }
            }
        }

        if (humidity_crc != (expected_crc & 0xFF)) {
            syslog(LOG_WARNING, "Humidity CRC mismatch: got 0x%02X, expected 0x%02X", humidity_crc, expected_crc & 0xFF);
            retries++;
            usleep(100000);
            continue;
        }

        *humidity = -6.0f + 125.0f * ((float)humidity_raw / 65536.0f);
        return 0;
    }

    syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
    return -1;
}

static int http_post_data(const char *server, int port, const char *endpoint, const char *data) {
    struct hostent *host = gethostbyname(server);
    if (!host) {
        syslog(LOG_ERR, "gethostbyname failed for %s: %s", server, hstrerror(h_errno));
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    memcpy(&addr.sin_addr, host->h_addr, host->h_length);

    sock_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (sock_fd < 0) {
        syslog(LOG_ERR, "socket failed: %s", strerror(errno));
        return -1;
    }

    if (connect(sock_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        syslog(LOG_ERR, "connect failed: %s", strerror(errno));
        close(sock_fd);
        sock_fd = -1;
        return -1;
    }

    char request[512];
    int request_len = snprintf(request, sizeof(request),
        "POST %s HTTP/1.1\r\n"
        "Host: %s\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n"
        "\r\n"
        "%s",
        endpoint, server, strlen(data), data);

    if (request_len < 0 || (size_t)request_len >= sizeof(request)) {
        syslog(LOG_ERR, "Request buffer too small");
        close(sock_fd);
        sock_fd = -1;
        return -1;
    }

    if (send(sock_fd, request, request_len, 0) < 0) {
        syslog(LOG_ERR, "send failed: %s", strerror(errno));
        close(sock_fd);
        sock_fd = -1;
        return -1;
    }

    char response[1024];
    ssize_t bytes_received = recv(sock_fd, response, sizeof(response) - 1, 0);
    if (bytes_received < 0) {
        syslog(LOG_ERR, "recv failed: %s", strerror(errno));
        close(sock_fd);
        sock_fd = -1;
        return -1;
    }

    response[bytes_received] = '\0';
