static int read_bmp280_data(int handle, float *temperature, float *pressure) {
    if (i2c_write_byte(handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) return -1;
    gpioDelay(10000);
    uint8_t buf[6];
    if (i2c_read_block(handle, BMP280_REG_PRESS_MSB, buf, 6) != 0) return -1;
    int32_t adc_P = (buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4);
    int32_t adc_T = (buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4);
    int32_t T = compensate_temperature(adc_T);
    uint32_t P = compensate_pressure(adc_P);
    *temperature = T / 100.0f;
    *pressure = P / 100.0f;
    return 0;
}

static int log_pressure_event(float pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) {
        perror("fopen pressure_log.txt");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Pressure: %.2f hPa\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    fclose(fp);
    return 0;
}

static int init_bmp280(int handle) {
    uint8_t chip_id;
    if (i2c_read_block(handle, BMP280_REG_CHIP_ID, &chip_id, 1) != 0) return -1;
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_byte(handle, BMP280_REG_RESET, BMP280_RESET_CMD) != 0) return -1;
    gpioDelay(2000);
    if (read_calibration_data(handle) != 0) return -1;
    if (i2c_write_byte(handle, BMP280_REG_CONFIG, 0x00) != 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        i2c_handle = i2cOpen(I2C_BUS, BMP280_I2C_ADDR, 0);
        if (i2c_handle >= 0) {
            if (init_bmp280(i2c_handle) == 0) break;
            i2cClose(i2c_handle);
            i2c_handle = -1;
        }
        fprintf(stderr, "I2C init attempt %d/%d failed, retrying in 1 s\n", attempt + 1, I2C_RETRIES);
        gpioDelay(1000000);
    }
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C initialisation failed after %d attempts\n", I2C_RETRIES);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float temperature, pressure;
        if (read_bmp280_data(i2c_handle, &temperature, &pressure) == 0) {
            printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temperature, pressure);
            if (pressure > PRESSURE_HIGH_THRESHOLD || pressure < PRESSURE_LOW_THRESHOLD) {
                log_pressure_event(pressure);
            }
        } else {
            fprintf(stderr, "Failed to read BMP280 data\n");
        }
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            gpioDelay(1000000);
        }
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

