/*
 * Raspberry Pi 4B Environmental Logger
 * Sensors: TMP117 (I2C 0x48), AHT20 (I2C 0x38), PIR on GPIO 17 (libgpiod)
 * Logs daily CSV files with timestamp, temperature, humidity, motion.
 * Build: gcc -o logger logger.c -lgpiod -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define AHT20_ADDR     0x38
#define PIR_GPIO_LINE  17
#define GPIO_CHIP      "gpiochip4"
#define SAMPLE_INTERVAL 1
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, len) == (ssize_t)len) return 0;
        if (errno != EINTR) {
            fprintf(stderr, "I2C write failed (attempt %d): %s\n", attempt + 1, strerror(errno));
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (read(fd, buf, len) == (ssize_t)len) return 0;
        if (errno != EINTR) {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", attempt + 1, strerror(errno));
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int tmp117_init(int fd) {
    uint8_t cmd = 0x85;
    return i2c_write(fd, &cmd, 1);
}

static int tmp117_read_temp(int fd, float *temp_c) {
    uint8_t reg = 0x00;
    if (i2c_write(fd, &reg, 1) != 0) return -1;
    usleep(10000);

    uint8_t buf[2];
    if (i2c_read(fd, buf, 2) != 0) return -1;

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp_c = raw * 0.0078125f;
    return 0;
}

static int aht20_init(int fd) {
    uint8_t init_cmd[3] = {0xBE, 0x08, 0x00};
    return i2c_write(fd, init_cmd, 3);
}

static int aht20_read(int fd, float *temp_c, float *hum) {
    uint8_t cmd[3] = {0xAC, 0x33, 0x00};
    if (i2c_write(fd, cmd, 3) != 0) return -1;
    usleep(80000);

    uint8_t buf[7];
    if (i2c_read(fd, buf, 7) != 0) return -1;

    if (buf[0] & 0x80) {
        fprintf(stderr, "AHT20 busy, retrying...\n");
        return -1;
    }

    uint32_t hum_raw = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | (buf[3] >> 4);
    uint32_t temp_raw = ((uint32_t)(buf[3] & 0x0F) << 16) | ((uint32_t)buf[4] << 8) | buf[5];

    *hum = (hum_raw / 1048576.0f) * 100.0f;
    *temp_c = (temp_raw / 1048576.0f) * 200.0f - 50.0f;
    return 0;
}

static int pir_read(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "PIR read error: %s\n", strerror(errno));
    }
    return val;
}

static void get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", tm);
}

static void log_data(const char *ts, float temp, float hum, int motion) {
    char filename[64];
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(filename, sizeof(filename), "%Y-%m-%d.log", tm);

    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, temp, hum, motion);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", PIR_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int tmp_fd = open(I2C_BUS, O_RDWR);
    if (tmp_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(tmp_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Failed to set TMP117 slave address: %s\n", strerror(errno));
    } else {
        if (tmp117_init(tmp_fd) != 0) {
            fprintf(stderr, "Warning: TMP117 init failed, continuing without it.\n");
        }
    }

    int aht_fd = open(I2C_BUS, O_RDWR);
    if (aht_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        close(tmp_fd);
        return 1;
    }

    if (ioctl(aht_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set AHT20 slave address: %s\n", strerror(errno));
    } else {
        if (aht20_init(aht_fd) != 0) {
            fprintf(stderr, "Warning: AHT20 init failed, continuing without it.\n");
        }
    }

    printf("Environmental logger started. Press Ctrl+C to exit.\n");

    while (running) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char ts[32];
        get_timestamp(ts, sizeof(ts));

        float temp = 0.0f, hum = 0.0f;
        int tmp_ok = 0, hum_ok = 0;

        if (tmp_fd >= 0 && ioctl(tmp_fd, I2C_SLAVE, TMP117_ADDR) >= 0) {
            if (tmp117_read_temp(tmp_fd, &temp) == 0) {
                tmp_ok = 1;
            } else {
                fprintf(stderr, "TMP117 read failed at %s\n", ts);
            }
        }

        if (aht_fd >= 0 && ioctl(aht_fd, I2C_SLAVE, AHT20_ADDR) >= 0) {
            if (aht20_read(aht_fd, &temp, &hum) == 0) {
                hum_ok = 1;
            } else {
                fprintf(stderr, "AHT20 read failed at %s\n", ts);
            }
        }

        int motion = pir_read(pir_line);

        if (tmp_ok || hum_ok) {
            log_data(ts, tmp_ok ? temp : 0.0f, hum_ok ? hum : 0.0f, motion);
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    if (tmp_fd >= 0) close(tmp_fd);
    if (aht_fd >= 0) close(aht_fd);
    return 0;
}

