#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define RAIN_SENSOR_GPIO 17
#define MOTOR_ENABLE_GPIO 22
#define MOTOR_IN1_GPIO 23
#define MOTOR_IN2_GPIO 24
#define POLL_INTERVAL_SEC 2
#define MOTOR_RUN_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error opening /dev/gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(gpio_fd, GPIO_GET_LINE_OFFSET, RAIN_SENSOR_GPIO) < 0) {
        fprintf(stderr, "Error: GPIO %d not available: %s\n", RAIN_SENSOR_GPIO, strerror(errno));
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(gpio_fd, GPIO_GET_LINE_OFFSET, MOTOR_ENABLE_GPIO) < 0) {
        fprintf(stderr, "Error: GPIO %d not available: %s\n", MOTOR_ENABLE_GPIO, strerror(errno));
        close(gpio_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(gpio_fd, GPIO_GET_LINE_OFFSET, MOTOR_IN1_GPIO) < 0) {
        fprintf(stderr, "Error: GPIO %d not available: %s\n", MOTOR_IN1_GPIO, strerror(errno));
        close(gpio_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(gpio_fd, GPIO_GET_LINE_OFFSET, MOTOR_IN2_GPIO) < 0) {
        fprintf(stderr, "Error: GPIO %d not available: %s\n", MOTOR_IN2_GPIO, strerror(errno));
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    struct gpio_line_request req;
    memset(&req, 0, sizeof(req));
