#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void set_led_color(uint8_t r, uint8_t g, uint8_t b)
{
    /* Common-anode LED: 0 = full on, 255 = full off.
       pigpio hardware PWM duty cycle is 0..range, so invert. */
    gpioPWM(RED_PIN,   PWM_RANGE - r);
    gpioPWM(GREEN_PIN, PWM_RANGE - g);
    gpioPWM(BULE_PIN,  PWM_RANGE - b);
}

static void turn_led_off(void)
{
    set_led_color(0, 0, 0);
}

static float calculate_cpu_load(void)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen /proc/stat");
        return 0.0f;
    }

    unsigned long long user, nice, system, idle, iowait,
                       irq, softirq, steal, guest, guest_nice;
    int rc = fscanf(fp,
                    "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                    &user, &nice, &system, &idle, &iowait,
                    &irq, &softirq, &steal, &guest, &guest_nice);
    fclose(fp);

    if (rc != 10) {
        fprintf(stderr, "Failed to parse /proc/stat\n");
        return 0.0f;
    }

    static unsigned long long prev_user = 0, prev_nice = 0,
                              prev_system = 0, prev_idle = 0,
                              prev_iowait = 0, prev_irq = 0,
                              prev_softirq = 0, prev_steal = 0,
                              prev_guest = 0, prev_guest_nice = 0;
    static int first = 1;

    if (first) {
        prev_user = user; prev_nice = nice; prev_system = system;
        prev_idle = idle; prev_iowait = iowait; prev_irq = irq;
        prev_softirq = softirq; prev_steal = steal;
        prev_guest = guest; prev_guest_nice = guest_nice;
        first = 0;
        return 0.0f;
    }

    unsigned long long cur_user = user, cur_nice = nice,
                       cur_system = system, cur_idle = idle,
                       cur_iowait = iowait, cur_irq = irq,
                       cur_softirq = softirq, cur_steal = steal,
                       cur_guest = guest, cur_guest_nice = guest_nice;

    unsigned long long prev_idle_time = prev_idle + prev_iowait;
    unsigned long long cur_idle_time = cur_idle + cur_iowait;
    unsigned long long prev_non_idle = prev_user + prev_nice +
                                       prev_system + prev_irq +
                                       prev_softirq + prev_steal +
                                       prev_guest + prev_guest_nice;
    unsigned long long cur_non_idle = cur_user + cur_nice +
                                      cur_system + cur_irq +
                                      cur_softirq + cur_steal +
                                      cur_guest + cur_guest_nice;

    unsigned long long prev_total = prev_idle_time + prev_non_idle;
    unsigned long long cur_total = cur_idle_time + cur_non_idle;

    unsigned long long prev_total_delta = prev_total - (prev_idle_time + prev_non_idle);
    unsigned long long cur_total_delta = cur_total - (cur_idle_time + cur_non_idle);

    if (prev_total_delta == 0 || cur_total_delta == 0) {
        return 0.0f;
    }

    float cpu_usage = ((float)(cur_total_delta - (cur_idle_time - prev_idle_time)) /
                       (float)cur_total_delta) * 100.0f;

    prev_user = cur_user; prev_nice = cur_nice; prev_system = cur_system;
    prev_idle = cur_idle; prev_iowait = cur_iowait; prev_irq = cur_irq;
    prev_softirq = cur_softirq; prev_steal = cur_steal;
    prev_guest = cur_guest; prev_guest_nice = cur_guest_nice;

    return cpu_usage;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BULE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BULE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    turn_led_off();

    while (g_running) {
        float cpu_load = calculate_cpu_load();

        uint8_t r = 0, g = 0, b = 0;

        if (cpu_load < 50.0f) {
            g = (uint8_t)(cpu_load * 5.0f);
        } else if (cpu_load < 100.0f) {
            r = (uint8_t)((cpu_load - 50.0f) * 5.0f);
            g = (uint8_t)((100.0f - cpu_load) * 5.0f);
        } else {
            r = PWM_RANGE;
        }

        if (r > PWM_RANGE) r = PWM_RANGE;
        if (g > PWM_RANGE) g = PWM_RANGE;
        if (b > PWM_RANGE) b = PWM_RANGE;

        set_led_color(r, g, b);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    turn_led_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

