#include <unistd.h>
#include <string.h>

#define FAN_GPIO        18
#define SPI_CHANNEL     0
#define SPI_SPEED       500000
#define SPI_FLAGS       0
#define PWM_FREQUENCY   1000
#define PWM_RANGE       255
#define BUFFER_SIZE     20
#define SAMPLE_INTERVAL 1.0

#define TEMP_LOW        25.0
#define TEMP_MID        40.0
#define TEMP_HIGH       60.0
#define DUTY_LOW        0
#define DUTY_MID        50
#define DUTY_HIGH       200
#define DUTY_MAX        255

#define MAX31855_FAULT  0x0001
#define MAX31855_OC     0x0001
#define MAX31855_SCG    0x0002
#define MAX31855_SCV    0x0004

typedef struct {
    time_t timestamp;
    float  temperature;
    int    pwm_duty;
} TemperatureReading;

static TemperatureReading temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioPWM(FAN_GPIO, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM initial off failed for GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, speed %d, flags %d)\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
        return -1;
    }
    return 0;
}

static int read_max31855(int *raw) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }
    *raw = ((uint32_t)(uint8_t)rx[0] << 24) |
           ((uint32_t)(uint8_t)rx[1] << 16) |
           ((uint32_t)(uint8_t)rx[2] <<  8) |
           ((uint32_t)(uint8_t)rx[3]);
    return 0;
}

static float extract_temperature(int raw) {
    if (raw & MAX31855_FAULT) {
        if (raw & MAX31855_OC)   fprintf(stderr, "MAX31855 fault: Open Circuit\n");
        if (raw & MAX31855_SCG)  fprintf(stderr, "MAX31855 fault: Short to GND\n");
        if (raw & MAX31855_SCV)  fprintf(stderr, "MAX31855 fault: Short to VCC\n");
        return -1000.0f;
    }
    int32_t temp_raw = (int32_t)raw >> 18;
    if (temp_raw & 0x2000) temp_raw |= 0xFFFFC000;
    return (float)temp_raw * 0.25f;
}

static int calculate_pwm_duty(float temperature) {
    if (temperature < TEMP_LOW) return DUTY_LOW;
    if (temperature < TEMP_MID) return (int)((temperature - TEMP_LOW) * (DUTY_MID - DUTY_LOW) / (TEMP_MID - TEMP_LOW) + DUTY_LOW);
    if (temperature < TEMP_HIGH) return (int)((temperature - TEMP_MID) * (DUTY_HIGH - DUTY_MID) / (TEMP_HIGH - TEMP_MID) + DUTY_MID);
    return DUTY_MAX;
}

static void update_fan_speed(int pwm_duty) {
    if (gpioPWM(FAN_GPIO, pwm_duty) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for GPIO %d\n", FAN_GPIO);
    }
}

static void log_temperature(float temperature, int pwm_duty) {
    time_t now = time(NULL);
    temperature_buffer[buffer_index].timestamp = now;
    temperature_buffer[buffer_index].temperature = temperature;
    temperature_buffer[buffer_index].pwm_duty = pwm_duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- Temperature Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm_info = localtime(&temperature_buffer[idx].timestamp);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("[%s] Temp: %.2f C, PWM: %d\n",
               ts, temperature_buffer[idx].temperature, temperature_buffer[idx].pwm_duty);
    }
    printf("--- End of Log ---\n");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() != 0) return 1;
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int raw;
        if (read_max31855(&raw) != 0) {
            fprintf(stderr, "Error: Failed to read temperature\n");
        } else {
            float temperature = extract_temperature(raw);
            if (temperature > -999.0f) {
                int pwm_duty = calculate_pwm_duty(temperature);
                update_fan_speed(pwm_duty);
                log_temperature(temperature, pwm_duty);
                printf("Temp: %.2f C, PWM: %d\n", temperature, pwm_duty);
            } else {
                fprintf(stderr, "Error: MAX31855 fault detected\n");
            }
        }
        time_sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    print_buffer();
    return 0;
}

