#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "bme280_log.csv"
#define SAMPLE_INTERVAL_SEC 5

#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7

#define BME280_CHIP_ID 0x60
#define BME280_RESET_CMD 0xB6

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int bme280_init(int fd) {
    uint8_t chip_id;
    if (i2c_read_reg8(fd, BME280_REG_ID, &chip_id) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X)\n", chip_id, BME280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, BME280_REG_RESET, BME280_RESET_CMD) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);

    if (i2c_write_reg8(fd, BME280_REG_CTRL_HUM, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, BME280_REG_CONFIG, 0xA0) < 0) return -1;
    if (i2c_write_reg8(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) return -1;

    return 0;
}

static int bme280_read_data(int fd, float *temp, float *hum, float *press) {
    uint8_t data[8];
    if (i2c_read_block(fd, BME280_REG_DATA, data, 8) < 0) {
        fprintf(stderr, "Error: Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }

    int32_t raw_press = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t raw_hum = (data[6] << 8) | data[7];

    *press = (float)raw_press / 100.0f;
    *temp = (float)raw_temp / 100.0f;
    *hum = (float)raw_hum / 1024.0f;

    return 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", tm_info);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n", BME280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bme280_init(fd) < 0) {
        fprintf(stderr, "Error: BME280 initialization failed.\n");
        close(fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,temperature_C,humidity_percent,pressure_hPa\n");
    }

    while (running) {
        float temp, hum, press;
        if (bme280_read_data(fd, &temp, &hum, &press) == 0) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, temp, hum, press);
            fflush(fp);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping log entry.\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    fclose(fp);
    close(fd);
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

