#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_ADDR_1 0x76
#define BMP280_I2C_ADDR_2 0x77
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_REG 0xE0
#define BMP280_RESET_CMD 0xB6
#define BMP280_STATUS_REG 0xF3
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_PRESS_MSB_REG 0xF7
#define BMP280_TEMP_MSB_REG 0xFA
#define BMP280_CALIB_START 0x88
#define BMP280_CALIB_LEN 24
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "weather_data.txt"
#define POLL_TIMEOUT_MS 100
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_calibration(int fd, bmp280_calib_t *cal) {
    uint8_t buf[BMP280_CALIB_LEN];
    if (i2c_read_reg(fd, BMP280_CALIB_START, buf, BMP280_CALIB_LEN) < 0) return -1;
    cal->dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    cal->dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    cal->dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    cal->dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    cal->dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int32_t g_t_fine;

static int32_t compensate_temperature(int32_t adc_T, const bmp280_calib_t *cal) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)cal->dig_T1 << 1))) * ((int32_t)cal->dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)cal->dig_T1)) * ((adc_T >> 4) - ((int32_t)cal->dig_T1))) >> 12) * ((int32_t)cal->dig_T3)) >> 14;
    g_t_fine = var1 + var2;
    return (g_t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P, const bmp280_calib_t *cal) {
    int64_t var1, var2, p;
    var1 = ((int64_t)g_t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)cal->dig_P6;
    var2 = var2 + ((var1 * (int64_t)cal->dig_P5) << 17);
    var2 = var2 + (((int64_t)cal->dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)cal->dig_P3) >> 8) + ((var1 * (int64_t)cal->dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)cal->dig_P1) >> 33;
    if (var1 == 0) return 0;
    p = 1048576 - adc_P;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)cal->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)cal->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)cal->dig_P7) << 4);
    return (uint32_t)(p >> 8);
}

static int read_raw(int fd, int32_t *raw_T, int32_t *raw_P) {
    uint8_t buf[6];
    if (i2c_read_reg(fd, BMP280_PRESS_MSB_REG, buf, 6) < 0) return -1;
    *raw_P = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | (buf[2] >> 4);
    *raw_T = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | (buf[5] >> 4);
    return 0;
}

static int wait_measurement(int fd) {
    uint8_t status;
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (i2c_read_reg(fd, BMP280_STATUS_REG, &status, 1) < 0) return -1;
        if ((status & 0x08) == 0) return 0;
        usleep(1000);
    }
    return -1;
}

static int init_bmp280(int fd, const bmp280_calib_t *cal) {
    if (i2c_write_reg(fd, BMP280_CTRL_MEAS_REG, 0x27) < 0) return -1;
    if (i2c_write_reg(fd, BMP280_CONFIG_REG, 0xA0) < 0) return -1;
    return 0;
}

static int open_i2c(int addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) { perror("open i2c"); return -1; }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) { perror("ioctl I2C_SLAVE"); close(fd); return -1; }
    return fd;
}

static void log_data(float temp, float press) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen log"); return; }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", ts, temp, press);
    fclose(fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open_i2c(BMP280_I2C_ADDR_1);
    if (fd < 0) {
        fd = open_i2c(BMP280_I2C_ADDR_2);
    }
    if (fd < 0) {
        fprintf(stderr, "No BMP280 found on I2C bus 1.\n");
        return 1;
    }

    uint8_t chip_id;
    if (i2c_read_reg(fd, BMP280_CHIP_ID_REG, &chip_id, 1) < 0) {
        fprintf(stderr, "Failed to read chip ID.\n");
        close(fd);
        return 1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Unexpected chip ID: 0x%02X (expected 0x58).\n", chip_id);
        close(fd);
        return 1;
    }

    bmp280_calib_t cal;
    if (read_calibration(fd, &cal) < 0) {
        fprintf(stderr, "Failed to read calibration data.\n");
        close(fd);
        return 1;
    }

    if (init_bmp280(fd, &cal) < 0) {
        fprintf(stderr, "Failed to initialize BMP280.\n");
        close(fd);
        return 1;
    }

    while (running) {
        if (i2c_write_reg(fd, BMP280_CTRL_MEAS_REG, 0x27) < 0) {
            fprintf(stderr, "Failed to trigger measurement.\n");
            break;
        }
        if (wait_measurement(fd) < 0) {
            fprintf(stderr, "Measurement timeout.\n");
            break;
        }
        int32_t raw_T, raw_P;
        if (read_raw(fd, &raw_T, &raw_P) < 0) {
            fprintf(stderr, "Failed to read raw data.\n");
            break;
        }
        int32_t t = compensate_temperature(raw_T, &cal);
        uint32_t p = compensate_pressure(raw_P, &cal);
        float temp = t / 100.0f;
        float press = p / 256.0f / 100.0f;
        log_data(temp, press);
        sleep(SAMPLE_INTERVAL_S);
    }

    close(fd);
    return 0;
}

