#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define LM75_ADDR      0x48
#define LM75_TEMP_REG  0x00
#define GPIO_CHIP       "gpiochip4"
#define GPIO_LINE       18
#define TEMP_THRESHOLD  28.0f
#define BUFFER_SIZE     60
#define SAMPLE_PERIOD   1

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static CircularBuffer temp_buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    if (pthread_mutex_init(&cb->mutex, NULL) != 0) {
        perror("pthread_mutex_init");
        exit(EXIT_FAILURE);
    }
}

static void buffer_add(CircularBuffer *cb, float value) {
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
    pthread_mutex_unlock(&cb->mutex);
}

static float buffer_average(const CircularBuffer *cb) {
    pthread_mutex_lock(&cb->mutex);
    if (cb->count == 0) {
        pthread_mutex_unlock(&cb->mutex);
        return 0.0f;
    }
    float sum = 0.0f;
    int start = (cb->count < BUFFER_SIZE) ? 0 : cb->head;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[(start + i) % BUFFER_SIZE];
    }
    pthread_mutex_unlock(&cb->mutex);
    return sum / (float)cb->count;
}

static int i2c_init(void) {
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        close(i2c_fd); i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp) {
    uint8_t reg = LM75_TEMP_REG;
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }
    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *temp = (float)(raw >> 5) / 256.0f;
    return 0;
}

static void cleanup(void) {
    if (led_line) { gpiod_line_release(led_line); led_line = NULL; }
    if (chip) { gpiod_chip_close(chip); chip = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
    pthread_mutex_destroy(&temp_buffer.mutex);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (i2c_init() != 0) return EXIT_FAILURE;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    led_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led_line, "lm75_monitor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    buffer_init(&temp_buffer);

    while (running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            buffer_add(&temp_buffer, temp);
            float avg = buffer_average(&temp_buffer);
            printf("Temperature: %.2f°C, Average: %.2f°C\n", temp, avg);
            if (avg > TEMP_THRESHOLD) {
                if (gpiod_line_set_value(led_line, 1) < 0) {
                    fprintf(stderr, "Error setting LED high: %s\n", strerror(errno));
                }
            } else {
                if (gpiod_line_set_value(led_line, 0) < 0) {
                    fprintf(stderr, "Error setting LED low: %s\n", strerror(errno));
                }
            }
        } else {
            fprintf(stderr, "Failed to read temperature. Re-initializing I2C...\n");
            if (i2c_init() != 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                break;
            }
        }
        sleep(SAMPLE_PERIOD);
    }

    gpiod_line_set_value(led_line, 0);
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

