#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_FLAGS 0x01  /* mode 1 (CPOL=1, CPHA=0) */
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_US 100000
#define MAX31865_CONFIG_REG 0x80
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07
#define MAX31865_FAULT_MASK 0x01
#define MAX31865_FAULT_OPEN 0x01
#define MAX31865_FAULT_OVERVOLTAGE 0x02
#define MAX31865_FAULT_UNDERTOLTAGE 0x04
#define R_REF 430.0
#define R0 100.0
#define A -0.00039083
#define B 0.000000644
#define FAULT_TEMP_THRESHOLD 80.0
#define CONFIG_FILE "config.json"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static double target_temperature = 25.0;
static double Kp = 1.0, Ki = 0.1, Kd = 0.01;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: config file not found, using defaults\n");
        return 0;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=\"\n\r");
        if (!key) continue;
        char *val = strtok(NULL, "=\"\n\r");
        if (!val) continue;
        if (strcmp(key, "target_temperature") == 0) target_temperature = atof(val);
        else if (strcmp(key, "Kp") == 0) Kp = atof(val);
        else if (strcmp(key, "Ki") == 0) Ki = atof(val);
        else if (strcmp(key, "Kd") == 0) Kd = atof(val);
    }
    fclose(fp);
    printf("Config: target=%.1f Kp=%.2f Ki=%.2f Kd=%.2f\n", target_temperature, Kp, Ki, Kd);
    return 0;
}

static int spi_write_reg(uint8_t reg, uint8_t val) {
    char tx[2] = { (char)(reg | 0x80), (char)val };
    char rx[2];
    if (spiXfer(spi_handle, tx, rx, 2) != 2) return -1;
    return 0;
}

static int spi_read_reg(uint8_t reg, uint8_t *val) {
    char tx[2] = { (char)(reg & 0x7F), 0x00 };
    char rx[2];
    if (spiXfer(spi_handle, tx, rx, 2) != 2) return -1;
    *val = (uint8_t)rx[1];
    return 0;
}

static int init_max31865(void) {
    if (spi_write_reg(MAX31865_CONFIG_REG, 0xC1) != 0) {
        fprintf(stderr, "Error: failed to write MAX31865 config\n");
        return -1;
    }
    return 0;
}

static int read_rtd_code(uint16_t *code) {
    uint8_t msb, lsb;
    if (spi_read_reg(MAX31865_RTD_MSB_REG, &msb) != 0) return -1;
    if (spi_read_reg(MAX31865_RTD_LSB_REG, &lsb) != 0) return -1;
    if (msb & MAX31865_FAULT_MASK) {
        uint8_t fault;
        if (spi_read_reg(MAX31865_FAULT_REG, &fault) != 0) return -1;
        if (fault & MAX31865_FAULT_OPEN) {
            fprintf(stderr, "MAX31865 fault: open circuit\n");
            return -2;
        }
        if (fault & MAX31865_FAULT_OVERVOLTAGE) {
            fprintf(stderr, "MAX31865 fault: overvoltage\n");
            return -2;
        }
        if (fault & MAX31865_FAULT_UNDERTOLTAGE) {
            fprintf(stderr, "MAX31865 fault: undervoltage\n");
            return -2;
        }
    }
    *code = ((uint16_t)(msb & 0x7F) << 8) | lsb;
    return 0;
}

static double rtd_code_to_resistance(uint16_t code) {
    return (R_REF * (double)code) / 32768.0;
}

static double resistance_to_temperature(double r) {
    if (r <= 0.0) return -273.15;
    double t = (r / R0 - 1.0);
    if (t >= 0.0) {
        double discriminant = A * A - 4.0 * B * t;
        if (discriminant < 0.0) return -273.15;
        double sqrt_d = sqrt(discriminant);
        return (-A + sqrt_d) / (2.0 * B);
    } else {
        double t = (r / R0 - 1.0) / (2.0 * A);
        return t;
    }
}

static double pid_control(double current_temp, double setpoint, double *integral, double *prev_error) {
    double error = setpoint - current_temp;
    *integral += error;
    double derivative = error - *prev_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *prev_error = error;
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;
    return output;
}

static void set_heater(double duty) {
    if (gpioPWM(HEATER_GPIO, (int)(duty * PWM_RANGE / 100.0)) < 0) {
        fprintf(stderr, "Warning: gpioPWM failed\n");
    }
}

static void failsafe(void) {
    fprintf(stderr, "Failsafe triggered! Shutting down heater.\n");
    set_heater(0.0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    exit(EXIT_FAILURE);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    if (read_config() != 0) {
        fprintf(stderr, "Warning: config read failed\n");
    }
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (init_max31865() != 0) {
        fprintf(stderr, "Error: MAX31865 init failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    double integral = 0.0, prev_error = 0.0;
    printf("Starting temperature control loop (target %.1f C)...\n", target_temperature);
    while (running) {
        uint16_t code;
        int rc = read_rtd_code(&code);
        if (rc == -1) {
            fprintf(stderr, "Error: SPI read failed\n");
            failsafe();
        } else if (rc == -2) {
            fprintf(stderr, "Error: MAX31865 fault detected\n");
            failsafe();
        }
        double resistance = rtd_code_to_resistance(code);
        double temperature = resistance_to_temperature(resistance);
        if (temperature > FAULT_TEMP_THRESHOLD) {
            fprintf(stderr, "Error: temperature %.2f C exceeds threshold %.2f C\n", temperature, FAULT_TEMP_THRESHOLD);
            failsafe();
        }
        double duty = pid_control(temperature, target_temperature, &integral, &prev_error);
        set_heater(duty);
        printf("Temp: %.2f C, Duty: %.2f%%\n", temperature, duty);
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    set_heater(0.0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

