    if (i2c_read_reg16(fd, 0xAC, ac2) < 0) return -1;
    if (i2c_read_reg16(fd, 0xAE, ac3) < 0) return -1;
    if (i2c_read_reg16(fd, 0xB0, (int16_t*)ac4) < 0) return -1;
    if (i2c_read_reg16(fd, 0xB2, (int16_t*)ac5) < 0) return -1;
    if (i2c_read_reg16(fd, 0xB4, (int16_t*)ac6) < 0) return -1;
    if (i2c_read_reg16(fd, 0xB6, b1) < 0) return -1;
    if (i2c_read_reg16(fd, 0xB8, b2) < 0) return -1;
    if (i2c_read_reg16(fd, 0xBA, mb) < 0) return -1;
    if (i2c_read_reg16(fd, 0xBC, mc) < 0) return -1;
    if (i2c_read_reg16(fd, 0xBE, md) < 0) return -1;
    return 0;
}

static int read_raw_temp(int fd, int32_t *ut) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    usleep(5000);
    return i2c_read_reg16(fd, BMP180_REG_MSB, (int16_t*)ut);
}

static int read_raw_pressure(int fd, int32_t *up) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, 0x34) < 0) return -1;
    usleep(5000);
    return i2c_read_reg24(fd, BMP180_REG_MSB, up);
}

static int calc_b5(int32_t ut, const int16_t *ac1, const int16_t *ac2, const int16_t *ac3, const uint16_t *ac4, const uint16_t *ac5, const uint16_t *ac6, int16_t *b1, int16_t *b2, int16_t *mb, int16_t *mc, int16_t *md) {
    int32_t x1 = ((ut - (int32_t)(*ac6)) * (int32_t)(*ac5)) >> 15;
    int32_t x2 = ((int32_t)(*mc) << 11) / (x1 + (int32_t)(*md));
    int32_t b5 = x1 + x2;
    return (int)b5;
}

static int calc_temp(int32_t ut, const int16_t *ac1, const int16_t *ac2, const int16_t *ac3, const uint16_t *ac4, const uint16_t *ac5, const uint16_t *ac6, int16_t *b1, int16_t *b2, int16_t *mb, int16_t *mc, int16_t *md) {
    int32_t b5 = calc_b5(ut, ac1, ac2, ac3, ac4, ac5, ac6, b1, b2, mb, mc, md);
    int32_t t = (b5 + 8) >> 4;
    return (int)t;
}

static int calc_pressure(int32_t up, int32_t ut, const int16_t *ac1, const int16_t *ac2, const int16_t *ac3, const uint16_t *ac4, const uint16_t *ac5, const uint16_t *ac6, int16_t *b1, int16_t *b2, int16_t *mb, int16_t *mc, int16_t *md) {
    int32_t b5 = calc_b5(ut, ac1, ac2, ac3, ac4, ac5, ac6, b1, b2, mb, mc, md);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)(*b2) * (b6 * b6) >> 12) >> 11;
    int32_t x2 = ((int32_t)(*ac2) * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((int32_t)(*ac1) * 4 + x3) << 3) / 16;
    x1 = ((int32_t)(*ac3) * b6) >> 13;
    x2 = ((int32_t)(*b1) * (b6 * b6) >> 12) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)(*ac4) * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)(up - b3)) * 50000;
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (int)p;
}

static void log_breach(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen log"); return; }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s: %s\n", ts, msg);
    fclose(fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) { perror("open i2c"); return 1; }

    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }

    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
    if (read_calibration(fd, &ac1, &ac2, &ac3, &ac4, &ac5, &ac6, &b1, &b2, &mb, &mc, &md) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(fd);
        return 1;
    }

    while (running) {
        int32_t ut, up;
        int ok = 0;
        for (int i = 0; i < MAX_RETRIES && running; i++) {
            if (read_raw_temp(fd, &ut) == 0 && read_raw_pressure(fd, &up) == 0) { ok = 1; break; }
            usleep(100000);
        }
        if (!ok) {
            fprintf(stderr, "Sensor read failed after retries\n");
            log_breach("Sensor read failed after retries");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        int temp = calc_temp(ut, &ac1, &ac2, &ac3, &ac4, &ac5, &ac6, &b1, &b2, &mb, &mc, &md);
        int press = calc_pressure(up, ut, &ac1, &ac2, &ac3, &ac4, &ac5, &ac6, &b1, &b2, &mb, &mc, &md);

        if (temp > TEMP_THRESHOLD || press < PRESSURE_THRESHOLD) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Temperature: %d, Pressure: %d", temp, press);
            log_breach(msg);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    close(fd);
    return 0;
}

