    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s: %s\n", ts, msg);
    fclose(fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) { perror("open i2c"); return 1; }

    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }

    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
    if (read_calibration(fd, &ac1, &ac2, &ac3, &ac4, &ac5, &ac6, &b1, &b2, &mb, &mc, &md) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(fd);
        return 1;
    }

    while (running) {
        int32_t ut, up;
        int ok = 0;
        for (int i = 0; i < MAX_RETRIES && running; i++) {
            if (read_raw_temp(fd, &ut) == 0 && read_raw_pressure(fd, &up) == 0) { ok = 1; break; }
            usleep(100000);
        }
        if (!ok) {
            fprintf(stderr, "Sensor read failed after retries\n");
            log_breach("Sensor read failed after retries");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        int temp = calc_temp(ut, &ac1, &ac2, &ac3, &ac4, &ac5, &ac6, &b1, &b2, &mb, &mc, &md);
