#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR          0x77
#define BMP180_REG_CONTROL   0xF4
#define BMP180_REG_MSB       0xF6
#define BMP180_REG_CAL_START 0xAA
#define BMP180_CAL_LEN       22
#define FAN_GPIO             18
#define TEMP_THRESHOLD       30.0f
#define BUFFER_SIZE          60
#define SAMPLE_PERIOD_US     500000
#define OSS                  0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* BMP180 calibration coefficients */
static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} sensor_data_t;

static sensor_data_t g_buffer[BUFFER_SIZE];
static int           g_head = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_calibration_data(void)
{
    uint8_t data[BMP180_CAL_LEN];
    if (i2cReadI2CBlockData(g_i2c_handle, BMP180_REG_CAL_START, (char *)data, BMP180_CAL_LEN) != BMP180_CAL_LEN) {
        fprintf(stderr, "Error: failed to read BMP180 calibration data\n");
        return -1;
    }

    ac1 = (int16_t)((data[0]  << 8) | data[1]);
    ac2 = (int16_t)((data[2]  << 8) | data[3]);
    ac3 = (int16_t)((data[4]  << 8) | data[5]);
    ac4 = (uint16_t)((data[6]  << 8) | data[7]);
    ac5 = (uint16_t)((data[8]  << 8) | data[9]);
    ac6 = (uint16_t)((data[10] << 8) | data[11]);
    b1  = (int16_t)((data[12] << 8) | data[13]);
    b2  = (int16_t)((data[14] << 8) | data[15]);
    mb  = (int16_t)((data[16] << 8) | data[17]);
    mc  = (int16_t)((data[18] << 8) | data[19]);
    md  = (int16_t)((data[20] << 8) | data[21]);

    if (ac1 == 0 && ac2 == 0 && ac3 == 0 && ac4 == 0 && ac5 == 0 && ac6 == 0) {
        fprintf(stderr, "Error: BMP180 calibration data is all zeros (sensor absent?)\n");
        return -1;
    }
    return 0;
}

static int read_raw_temperature(int32_t *ut)
{
    if (i2cWriteByteData(g_i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) {
        fprintf(stderr, "Error: failed to write temperature command\n");
        return -1;
    }
    gpioDelay(5000); /* 4.5 ms max conversion time */

    int msb = i2cReadByteData(g_i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(g_i2c_handle, BMP180_REG_MSB + 1);
    if (msb < 0 || lsb < 0) {
        fprintf(stderr, "Error: failed to read raw temperature\n");
        return -1;
    }
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int32_t *up)
{
    if (i2cWriteByteData(g_i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) < 0) {
        fprintf(stderr, "Error: failed to write pressure command\n");
        return -1;
    }
    gpioDelay(2000 + (3000 << OSS)); /* 2.0 + 0.3 * 2^(OSS) ms */

    int msb = i2cReadByteData(g_i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(g_i2c_handle, BMP180_REG_MSB + 1);
    int xlsb = i2cReadByteData(g_i2c_handle, BMP180_REG_MSB + 2);
    if (msb < 0 || lsb < 0 || xlsb < 0) {
        fprintf(stderr, "Error: failed to read raw pressure\n");
        return -1;
    }
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

static float calculate_temperature(int32_t ut)
{
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up, int32_t ut)
{
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    int32_t x3 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x4 = ((int32_t)ac2 * b6) >> 11;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;

    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);

    int32_t p;
    if (b7 < 0x80000000UL)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (float)p;
}

static void add_to_buffer(float temperature, float pressure)
{
    g_buffer[g_head].timestamp    = time(NULL);
    g_buffer[g_head].temperature  = temperature;
    g_buffer[g_head].pressure     = pressure;
    g_head = (g_head + 1) % BUFFER_SIZE;
}

static void control_fan(float temperature)
{
    if (temperature > TEMP_THRESHOLD) {
        if (gpioWrite(FAN_GPIO, 1) < 0)
            fprintf(stderr, "Warning: failed to set fan GPIO high\n");
    } else {
        if (gpioWrite(FAN_GPIO, 0) < 0)
            fprintf(stderr, "Warning: failed to set fan GPIO low\n");
    }
}

static void timer_callback(void *user_data)
{
    (void)user_data;

    int32_t ut, up;
    if (read_raw_temperature(&ut) != 0) {
        fprintf(stderr, "Timer: temperature read failed, skipping sample\n");
        return;
    }
    if (read_raw_pressure(&up) != 0) {
        fprintf(stderr, "Timer: pressure read failed, skipping sample\n");
        return;
    }

    float temperature = calculate_temperature(ut);
    float pressure    = calculate_pressure(up, ut);

    add_to_buffer(temperature, pressure);
    control_fan(temperature);

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[32];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", time_str, temperature, pressure);
    fflush(stdout);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus 1 at 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_calibration_data() != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_PERIOD_US, timer_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to set pigpio timer\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("BMP180 sampling started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running)
        gpioDelay(100000); /* 100 ms sleep to reduce CPU usage */

    printf("\nShutting down...\n");
    gpioSetTimerFuncEx(0, 0, NULL, NULL); /* disable timer */
    gpioWrite(FAN_GPIO, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

