#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define MAX_DUTY_CYCLE 800
#define LOG_FILE "heater_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(int handle, float *temperature) {
    char rx[4] = {0};
    int ret = spiRead(handle, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI read failed (returned %d)\n", ret);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        if (raw & 0x00000004) {
            fprintf(stderr, "MAX31855 fault: open circuit\n");
            return -2;
        }
        if (raw & 0x00000002) {
            fprintf(stderr, "MAX31855 fault: short to GND\n");
            return -2;
        }
        if (raw & 0x00000001) {
            fprintf(stderr, "MAX31855 fault: short to VCC\n");
            return -2;
        }
    }

    int16_t thermocouple_raw = (int16_t)(raw >> 18);
    *temperature = thermocouple_raw * 0.25f;
    return 0;
}

static void set_heater_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;
    gpioPWM(HEATER_GPIO, duty_cycle);
}

static void log_data(float temperature, int duty_cycle) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fflush(log_file);
}

static void cleanup(void) {
    set_heater_duty_cycle(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", HEATER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    set_heater_duty_cycle(0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float target_temperature = 25.0f;
    float kp = 1.0f, ki = 0.1f;
    float integral = 0.0f;
    float previous_error = 0.0f;

    while (running) {
        float temperature;
        int rc = read_max31855(spi_handle, &temperature);

        if (rc == 0) {
            float error = target_temperature - temperature;
            integral += error;
            if (integral > 1000.0f) integral = 1000.0f;
            if (integral < -1000.0f) integral = -1000.0f;

            float duty_cycle = (kp * error) + (ki * integral);
            if (duty_cycle < 0.0f) duty_cycle = 0.0f;
            if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;

            set_heater_duty_cycle((int)duty_cycle);
            log_data(temperature, (int)duty_cycle);
            previous_error = error;
        } else {
            set_heater_duty_cycle(0);
            log_data(0.0f, 0);
            fprintf(stderr, "Sensor read error (code %d)\n", rc);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

