            set_heater_duty_cycle((int)duty_cycle);
            log_data(temperature, (int)duty_cycle);
            previous_error = error;
        } else {
            set_heater_duty_cycle(0);
            log_data(0.0f, 0);
            fprintf(stderr, "Sensor read error (code %d)\n", rc);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

