#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define TEMP_THRESHOLD_LOW  40000
#define TEMP_THRESHOLD_HIGH 60000

#define PWM_RANGE 255

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_cpu_temp(void)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature file");
        return -1;
    }

    int temp = -1;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "fscanf failed to read temperature\n");
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "read error on temperature file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose temperature file");
        return -1;
    }

    return temp;
}

static void set_rgb(int r, int g, int b)
{
    /* Common-anode: duty 255 = off, duty 0 = fully on */
    gpioPWM(RED_PIN,   PWM_RANGE - r);
    gpioPWM(GREEN_PIN, PWM_RANGE - g);
    gpioPWM(BLUE_PIN,  PWM_RANGE - b);
}

static void cleanup(void)
{
    /* Turn off all channels (duty 255 = off for common-anode) */
    gpioPWM(RED_PIN,   PWM_RANGE);
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN,  PWM_RANGE);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) != 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int temp = read_cpu_temp();
        if (temp < 0) {
            fprintf(stderr, "Skipping update due to read error\n");
            time_sleep(0.5);
            continue;
        }

        int r, g, b;
        if (temp < TEMP_THRESHOLD_LOW) {
            r = 0; g = 0; b = PWM_RANGE;
        } else if (temp < TEMP_THRESHOLD_HIGH) {
            r = 0; g = PWM_RANGE; b = 0;
        } else {
            r = PWM_RANGE; g = 0; b = 0;
        }

        set_rgb(r, g, b);
        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temp, r, g, b);
        fflush(stdout);

        time_sleep(0.5);
    }

    cleanup();
    return EXIT_SUCCESS;
}

