#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define DHT22_TIMEOUT_US 100000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

static size_t write_cb(void *contents, size_t size, size_t nmemb, void *userp) {
    (void)contents; (void)size; (void)nmemb; (void)userp;
    return 0;
}

int read_dht22(int gpio, DHT22Data *data) {
    int data_bits[40] = {0};
    int i, j;
    uint32_t start_tick, end_tick;

    // Start signal: pull low for >=1ms, then high
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(2000); // 2ms low
    gpioWrite(gpio, 1);
    gpioDelay(30);   // 30us high

    // Switch to input
    gpioSetMode(gpio, PI_INPUT);

    // Wait for sensor response (low then high)
    start_tick = gpioTick();
    while (gpioRead(gpio) == 1) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
    }
    start_tick = gpioTick();
    while (gpioRead(gpio) == 0) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
    }
    start_tick = gpioTick();
    while (gpioRead(gpio) == 1) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
    }

    // Read 40 bits
    for (i = 0; i < 40; i++) {
        start_tick = gpioTick();
        while (gpioRead(gpio) == 0) {
            if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
        }
        end_tick = gpioTick();
        start_tick = end_tick;
        while (gpioRead(gpio) == 1) {
            if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
        }
        end_tick = gpioTick();
        if (end_tick - start_tick > 50) {
            data_bits[i] = 1;
        }
    }

    // Parse data
    int humidity_int = 0;
    int temperature_int = 0;
    for (j = 0; j < 16; j++) {
        humidity_int = (humidity_int << 1) | data_bits[j];
    }
    for (j = 0; j < 16; j++) {
        temperature_int = (temperature_int << 1) | data_bits[j + 16];
    }

    // Checksum
    int checksum = (humidity_int >> 8) + (humidity_int & 0xFF) + (temperature_int >> 8) + (temperature_int & 0xFF);
    if (checksum != data_bits[40]) {
        fprintf(stderr, "DHT22 checksum error\n");
        return -1;
    }

    data->humidity = humidity_int / 10.0f;
    data->temperature = temperature_int / 10.0f;
    return 0;
}

int post_data(float temperature, float humidity) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    char json_string[256];
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    snprintf(json_string, sizeof(json_string),
             "{\"timestamp\":\"%s\",\"temperature\":%.2f,\"humidity\":%.2f}",
             timestamp, temperature, humidity);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "curl_easy_init() failed\n");
        curl_global_cleanup();
        return -1;
    }

    headers = curl_slist_append(headers, "Content-Type: application/json");
    curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_cb);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    }

    curl_easy_cleanup(curl);
    curl_slist_free_all(headers);
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main() {
    DHT22Data dht22_data;
    int retries = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    while (!terminate) {
        if (read_dht22(DHT22_GPIO, &dht22_data) == 0) {
            if (post_data(dht22_data.temperature, dht22_data.humidity) == 0) {
                printf("Data posted successfully: Temp=%.2fC, Hum=%.2f%%\n", dht22_data.temperature, dht22_data.humidity);
            } else {
                fprintf(stderr, "Failed to post data\n");
            }
            break;
        } else {
            fprintf(stderr, "Failed to read DHT22 data (attempt %d)\n", retries + 1);
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
            gpioDelay(2000000); // 2s delay before retry
        }
    }

    gpioTerminate();
    return 0;
}

