#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE_OSS3 0xF4
#define LOG_FILE "pressure_log.txt"
#define BUTTON_GPIO 4
#define DEBOUNCE_US 200000
#define SAMPLE_INTERVAL_US 2000000
#define PRESSURE_CONV_US 26000

static volatile sig_atomic_t logging_enabled = 0;
static volatile uint32_t last_interrupt_tick = 0;
static int i2c_handle = -1;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

static int read_i2c_word(int handle, uint8_t reg, int16_t *out) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_i2c_uword(int handle, uint8_t reg, uint16_t *out) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_calibration(int handle, bmp180_cal_t *cal) {
    if (read_i2c_word(handle, BMP180_REG_CAL_AC1, &cal->ac1) < 0) return -1;
    if (read_i2c_word(handle, BMP180_REG_CAL_AC2, &cal->ac2) < 0) return -1;
    if (read_i2c_word(handle, BMP180_REG_CAL_AC3, &cal->ac3) < 0) return -1;
    if (read_i2c_uword(handle, BMP180_REG_CAL_AC4, &cal->ac4) < 0) return -1;
    if (read_i2c_uword(handle, BMP180_REG_CAL_AC5, &cal->ac5) < 0) return -1;
    if (read_i2c_uword(handle, BMP180_REG_CAL_AC6, &cal->ac6) < 0) return -1;
    if (read_i2c_word(handle, BMP180_REG_CAL_B1, &cal->b1) < 0) return -1;
    if (read_i2c_word(handle, BMP180_REG_CAL_B2, &cal->b2) < 0) return -1;
    if (read_i2c_word(handle, BMP180_REG_CAL_MB, &cal->mb) < 0) return -1;
    if (read_i2c_word(handle, BMP180_REG_CAL_MC, &cal->mc) < 0) return -1;
    if (read_i2c_word(handle, BMP180_REG_CAL_MD, &cal->md) < 0) return -1;
    if (cal->ac1 == 0 && cal->ac2 == 0 && cal->ac3 == 0) {
        fprintf(stderr, "Error: BMP180 calibration data invalid (all zeros)\n");
        return -1;
    }
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    char cmd = BMP180_CMD_TEMP;
    if (i2cWriteDevice(handle, &cmd, 1) < 0) return -1;
    gpioDelay(5000);
    char buf[2];
    if (i2cWriteByte(handle, BMP180_REG_MSB) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int oss, int32_t *up) {
    char cmd = BMP180_CMD_PRESSURE_OSS3;
    if (i2cWriteDevice(handle, &cmd, 1) < 0) return -1;
    gpioDelay(PRESSURE_CONV_US);
    char buf[3];
