#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define SERVER_URL "http://your-server.com/api/humidity"
#define READ_INTERVAL 10
#define MAX_JSON_SIZE 256

static volatile sig_atomic_t running = 1;
static char *server_url = NULL;

typedef struct {
    float humidity;
    float temperature;
    int valid;
} DHT22Data;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    syslog(LOG_INFO, "%s", msg);
}

static void log_error(const char *msg) {
    syslog(LOG_ERR, "%s", msg);
}

static int read_dht22(int gpio, DHT22Data *data) {
    int i, j;
    int laststate = PI_HIGH;
    int bits[40] = {0};
    int pulse_lengths[85] = {0};
    int count = 0;

    data->valid = 0;

    if (gpioSetMode(gpio, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(gpio, PI_LOW) < 0) return -1;
    gpioDelay(2000);
    if (gpioWrite(gpio, PI_HIGH) < 0) return -1;
    gpioDelay(30);
    if (gpioSetMode(gpio, PI_INPUT) < 0) return -1;

    for (i = 0; i < 85; i++) {
        int timeout = 0;
        while (gpioRead(gpio) == PI_HIGH) {
            if (++timeout > 100) return -1;
            gpioDelay(1);
        }
        timeout = 0;
        while (gpioRead(gpio) == PI_LOW) {
            if (++timeout > 100) return -1;
            gpioDelay(1);
        }
        pulse_lengths[i] = timeout;
    }

    for (i = 0; i < 40; i++) {
        if (pulse_lengths[1 + 2 * i] > pulse_lengths[2 + 2 * i]) {
            bits[i] = 1;
        } else {
            bits[i] = 0;
        }
    }

    int humidity = 0;
    int temp = 0;
    for (i = 0; i < 16; i++) {
        humidity |= (bits[i] << (15 - i));
    }
    for (i = 16; i < 32; i++) {
        temp |= (bits[i] << (15 - (i - 16)));
    }

    if (humidity > 100 || temp > 125 || temp < -40) {
        return -1;
    }

    data->humidity = humidity / 10.0f;
    data->temperature = temp / 10.0f;
    data->valid = 1;
    return 0;
}

static int post_humidity(const char *url, float humidity) {
    CURL *curl = NULL;
    CURLcode res;
    struct curl_slist *headers = NULL;
    char json_string[MAX_JSON_SIZE];
    int retry_count = 0;
    int result = -1;

    snprintf(json_string, sizeof(json_string), "{\"humidity\":%.1f}", humidity);

    while (retry_count < MAX_RETRIES) {
        curl = curl_easy_init();
        if (!curl) {
            log_error("curl_easy_init() failed");
            retry_count++;
            sleep(2);
            continue;
        }

        headers = curl_slist_append(headers, "Content-Type: application/json");
        if (!headers) {
            log_error("curl_slist_append() failed");
            curl_easy_cleanup(curl);
            retry_count++;
            sleep(2);
            continue;
        }

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
        curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            char errbuf[128];
            snprintf(errbuf, sizeof(errbuf), "curl_easy_perform() failed: %s", curl_easy_strerror(res));
            log_error(errbuf);
        } else {
            long http_code = 0;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
            if (http_code >= 200 && http_code < 300) {
                log_message("Humidity data posted successfully");
                result = 0;
                break;
            } else {
                char errbuf[128];
                snprintf(errbuf, sizeof(errbuf), "HTTP POST failed with code: %ld", http_code);
                log_error(errbuf);
            }
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        retry_count++;
        if (retry_count < MAX_RETRIES) {
            sleep(2);
        }
    }

    if (curl) curl_easy_cleanup(curl);
    if (headers) curl_slist_free_all(headers);
    return result;
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (server_url == NULL) {
        server_url = strdup(SERVER_URL);
        if (server_url == NULL) {
            log_error("strdup failed for default URL");
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
    }

    log_message("DHT22 monitor started");

    while (running) {
        DHT22Data dht_data;
        int retry_count = 0;
        int read_success = 0;

        while (retry_count < MAX_RETRIES && !read_success) {
            if (read_dht22(DHT22_GPIO, &dht_data) == 0) {
                read_success = 1;
            } else {
                char errbuf[128];
                snprintf(errbuf, sizeof(errbuf), "DHT22 read failed (attempt %d/%d)", retry_count + 1, MAX_RETRIES);
                log_error(errbuf);
                retry_count++;
                if (retry_count < MAX_RETRIES) {
                    sleep(2);
                }
            }
        }

        if (read_success && dht_data.valid) {
            if (post_humidity(server_url, dht_data.humidity) != 0) {
                log_error("Failed to post humidity data after retries");
            }
        } else {
            log_error("Failed to read valid DHT22 data after retries");
        }

        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    log_message("DHT22 monitor shutting down");
    gpioTerminate();
    if (server_url != NULL) {
        free(server_url);
    }
    curl_global_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

