#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define CPU_TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(CPU_TEMP_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", CPU_TEMP_PATH, strerror(errno));
        return -1;
    }

    char buffer[16];
    if (!fgets(buffer, sizeof(buffer), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", CPU_TEMP_PATH, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *endptr;
    long temp = strtol(buffer, &endptr, 10);
    if (*endptr != '\n' && *endptr != '\0') {
        fprintf(stderr, "Invalid temperature data: %s\n", buffer);
        return -1;
    }
    return (int)temp;
}

static int read_max_state(void) {
    FILE *fp = fopen(FAN_STATE_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_STATE_PATH, strerror(errno));
        return -1;
    }

    char buffer[16];
    if (!fgets(buffer, sizeof(buffer), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", FAN_STATE_PATH, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *endptr;
    long state = strtol(buffer, &endptr, 10);
    if (*endptr != '\n' && *endptr != '\0') {
        fprintf(stderr, "Invalid max_state data: %s\n", buffer);
        return -1;
    }
    return (int)state;
}

static int set_fan_state(int state) {
    FILE *fp = fopen(FAN_STATE_PATH, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n", FAN_STATE_PATH, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", FAN_STATE_PATH, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", FAN_STATE_PATH, strerror(errno));
        return -1;
    }
    return 0;
}

static int calculate_fan_speed(int cpu_temp) {
    if (cpu_temp < 45000) return 0;
    if (cpu_temp < 55000) return 1;
    if (cpu_temp < 65000) return 2;
    return 3;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int last_fan_state = -1;
    int max_state = read_max_state();
    if (max_state < 0) {
        fprintf(stderr, "Failed to read max_state. Exiting.\n");
        return 1;
    }

    log_event("Fan control service started.");

    while (program_running) {
        int cpu_temp = read_cpu_temp();
        if (cpu_temp < 0) {
            fprintf(stderr, "Failed to read CPU temperature. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int fan_speed = calculate_fan_speed(cpu_temp);

        if (fan_speed < 0 || fan_speed > max_state) {
            fprintf(stderr, "Invalid fan speed %d (max allowed: %d). Retrying.\n", fan_speed, max_state);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (fan_speed != last_fan_state) {
            if (set_fan_state(fan_speed) == 0) {
                char log_message[128];
                snprintf(log_message, sizeof(log_message), "Fan speed set to state %d (%d%%).", fan_speed, fan_speed * 25);
                log_event(log_message);
                last_fan_state = fan_speed;
            } else {
                fprintf(stderr, "Failed to set fan speed. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    if (set_fan_state(0) != 0) {
        fprintf(stderr, "Failed to stop fan during shutdown.\n");
    }
    log_event("Fan control service stopped.");
    return 0;
}

