#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define SAMPLE_INTERVAL_US 1000000
#define MAX_TEMP 100.0f
#define MIN_TEMP 0.0f

#define Kp 1.0f
#define Ki 0.1f
#define Kd 0.01f
#define TARGET_TEMP 50.0f

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

typedef struct {
    float Kp, Ki, Kd;
    float target;
    float integral;
    float previous_error;
} PIDController;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(float temp, int duty, float pid_out) {
    FILE *fp = fopen("heater_log.txt", "a");
    if (!fp) { perror("fopen log"); return; }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temp: %.2f, Duty: %d, PID: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, duty, pid_out);
    fclose(fp);
}

static void log_error(const char *msg) {
    FILE *fp = fopen("heater_log.txt", "a");
    if (!fp) { perror("fopen log"); return; }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fclose(fp);
}

static int read_max31855(float *temp, int *fault) {
    char rx[4] = {0};
    int rc = spiRead(spi_handle, rx, 4);
    if (rc != 4) {
        *fault = -1;
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);
    *fault = (raw >> 1) & 0x07;
    if (*fault & 0x01) { *temp = -999.0f; return -1; }
    if (*fault & 0x02) { *temp = -998.0f; return -1; }
    if (*fault & 0x04) { *temp = -997.0f; return -1; }
    int16_t milli = (int16_t)((raw >> 18) & 0x3FFF);
    if (milli & 0x2000) milli |= 0xC000;
    *temp = milli * 0.25f;
    return 0;
}

static int set_heater(int duty) {
    if (duty < 0) duty = 0;
    if (duty > 100) duty = 100;
    if (gpioPWM(HEATER_GPIO, duty) < 0) return -1;
    return 0;
}

static float pid_calculate(PIDController *pid, float temp) {
    float error = pid->target - temp;
    pid->integral += error;
    if (pid->integral > 100.0f) pid->integral = 100.0f;
    if (pid->integral < -100.0f) pid->integral = -100.0f;
    float derivative = error - pid->previous_error;
    float output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;
    pid->previous_error = error;
    if (output > 100.0f) output = 100.0f;
    if (output < 0.0f) output = 0.0f;
    return output;
}

static void cleanup(void) {
    gpioPWM(HEATER_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    PIDController pid = {Kp, Ki, Kd, TARGET_TEMP, 0.0f, 0.0f};
    while (running) {
        float temp = 0.0f;
        int fault = 0;
        if (read_max31855(&temp, &fault) != 0) {
            if (fault == -1) log_error("SPI read failed");
            else if (fault == 1) log_error("Thermocouple open circuit");
            else if (fault == 2) log_error("Thermocouple short to GND");
            else if (fault == 4) log_error("Thermocouple short to VCC");
            set_heater(0);
            pid.integral = 0.0f;
            pid.previous_error = 0.0f;
            gpioDelay(1000000);
            continue;
        }
        if (temp > MAX_TEMP || temp < MIN_TEMP) {
            log_error("Temperature out of range");
            set_heater(0);
            pid.integral = 0.0f;
            pid.previous_error = 0.0f;
            gpioDelay(1000000);
            continue;
        }
        float pid_out = pid_calculate(&pid, temp);
        int duty = (int)(pid_out + 0.5f);
        if (set_heater(duty) != 0) log_error("gpioPWM failed");
        log_data(temp, duty, pid_out);
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    cleanup();
    return 0;
}

