    float output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;
    pid->previous_error = error;
    if (output > 100.0f) output = 100.0f;
    if (output < 0.0f) output = 0.0f;
    return output;
}

static void cleanup(void) {
    gpioPWM(HEATER_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    PIDController pid = {Kp, Ki, Kd, TARGET_TEMP, 0.0f, 0.0f};
    while (running) {
        float temp = 0.0f;
        int fault = 0;
        if (read_max31855(&temp, &fault) != 0) {
            if (fault == -1) log_error("SPI read failed");
            else if (fault == 1) log_error("Thermocouple open circuit");
            else if (fault == 2) log_error("Thermocouple short to GND");
            else if (fault == 4) log_error("Thermocouple short to VCC");
            set_heater(0);
            pid.integral = 0.0f;
            pid.previous_error = 0.0f;
            gpioDelay(1000000);
            continue;
        }
        if (temp > MAX_TEMP || temp < MIN_TEMP) {
            log_error("Temperature out of range");
            set_heater(0);
            pid.integral = 0.0f;
            pid.previous_error = 0.0f;
            gpioDelay(1000000);
            continue;
        }
        float pid_out = pid_calculate(&pid, temp);
        int duty = (int)(pid_out + 0.5f);
        if (set_heater(duty) != 0) log_error("gpioPWM failed");
        log_data(temp, duty, pid_out);
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    cleanup();
    return 0;
}

