#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature file");
        return -1;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Failed to parse temperature\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_milli;
}

static int calculate_duty_cycle(int temp_milli) {
    if (temp_milli < 0) return 0;
    if (temp_milli <= 40000) return 0;
    if (temp_milli >= 70000) return 100;
    float frac = (float)(temp_milli - 40000) / (70000.0f - 40000.0f);
    return (int)(frac * 100.0f + 0.5f);
}

static int set_fan_speed(int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    int duty = (duty_percent * 1000000) / 100;
    if (gpioPWM(FAN_GPIO, duty) < 0) {
        fprintf(stderr, "gpioPWM failed\n");
        return -1;
    }
    return 0;
}

static int log_data(int temp_milli, int duty_percent) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    float temp_c = temp_milli / 1000.0f;
    fprintf(fp, "%s,%.2f,%d\n", timestamp, temp_c, duty_percent);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int first_log = 1;
    while (running) {
        int temp_milli = read_cpu_temp();
        if (temp_milli < 0) {
            fprintf(stderr, "Temperature read failed, retrying in %d s\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int duty_percent = calculate_duty_cycle(temp_milli);
        if (set_fan_speed(duty_percent) < 0) {
            fprintf(stderr, "Failed to set fan speed\n");
        }

        if (log_data(temp_milli, duty_percent) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        if (first_log) {
            printf("Fan control started. Logging to %s\n", LOG_FILE);
            first_log = 0;
        }

        sleep(POLL_INTERVAL_SEC);
    }

    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    printf("\nFan control stopped. Resources released.\n");
    return EXIT_SUCCESS;
}

