#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define LOG_FILE "flow_log.txt"
#define POLL_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 20000  // 20ms for first measurement

// SLF3S-1300F continuous measurement command
#define SLF3S_MEASURE_CMD 0x3608

// CRC-8 polynomial for Sensirion: x^8 + x^5 + x^4 + 1 (0x31)
#define CRC8_POLY 0x31

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

// CRC-8 calculation for Sensirion sensors
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Read flow rate from a single SLF3S-1300F sensor
// Returns 0 on success, -1 on failure
static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t cmd[2] = {(SLF3S_MEASURE_CMD >> 8) & 0xFF, SLF3S_MEASURE_CMD & 0xFF};
    uint8_t buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Send measurement command
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "Error writing to I2C handle %d (attempt %d)\n", handle, retries + 1);
            retries++;
            gpioDelay(10000); // 10ms delay before retry
            continue;
        }

        // Wait for measurement to complete
        gpioDelay(MEASUREMENT_DELAY_US);

        // Read 3 bytes: 2 data bytes + 1 CRC byte
        if (i2cReadDevice(handle, (char *)buf, 3) != 3) {
            fprintf(stderr, "Error reading from I2C handle %d (attempt %d)\n", handle, retries + 1);
            retries++;
            gpioDelay(10000);
            continue;
        }

        // Validate CRC
        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "CRC mismatch on I2C handle %d (attempt %d)\n", handle, retries + 1);
            retries++;
            gpioDelay(10000);
            continue;
        }

        // Convert raw value to flow rate (ml/min)
        int16_t raw_value = (buf[0] << 8) | buf[1];
        *flow_rate = (float)raw_value * 0.01f;
        return 0;
    }

    fprintf(stderr, "Failed to read flow rate from I2C handle %d after %d retries\n", handle, MAX_RETRIES);
    return -1;
}

// Log flow rates to file
static void log_flow_rates(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
}

// Signal handler for graceful shutdown
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connections
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting flow monitoring. Press Ctrl+C to stop.\n");

    // Main loop
    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ret1 = read_flow_rate(i2c_handle1, &flow1);
        int ret2 = read_flow_rate(i2c_handle2, &flow2);

        if (ret1 == 0 && ret2 == 0) {
            log_flow_rates(flow1, flow2);
        } else {
            fprintf(stderr, "Error reading flow rates (sensor1: %d, sensor2: %d)\n", ret1, ret2);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    // Cleanup
    printf("\nShutting down...\n");
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

