#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18
#define PULSES_PER_REVOLUTION 360
#define LOG_FILE "encoder_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(float angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Angle: %.2f\n", timestamp, angle) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_encoder(int *state) {
    int a = gpioRead(SENSOR_A_PIN);
    int b = gpioRead(SENSOR_B_PIN);

    if (a < 0 || b < 0) {
        fprintf(stderr, "Error reading encoder pins (A=%d, B=%d)\n", a, b);
        return -1;
    }

    *state = (a << 1) | b;
    return 0;
}

static int update_angle(float *angle, int state) {
    int prev_state = (int)((*angle - 1.0f) * PULSES_PER_REVOLUTION) % PULSES_PER_REVOLUTION;
    int delta = state - prev_state;

    if (delta > 180) delta -= PULSES_PER_REVOLUTION;
    if (delta < -180) delta += PULSES_PER_REVOLUTION;

    *angle += (float)delta / PULSES_PER_REVOLUTION * 360.0f;
    if (*angle < 0.0f) *angle += 360.0f;
    if (*angle >= 360.0f) *angle -= 360.0f;

    return 0;
}

