static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
