#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_INPUT_PIN 17
#define GPIO_GAIN_PIN 18
#define POLL_INTERVAL_US 10000
#define LOG_FILE "audio_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_peak_event(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s LEVEL\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *input_line = NULL;
    struct gpiod_line *gain_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    input_line = gpiod_chip_get_line(chip, GPIO_INPUT_PIN);
    if (!input_line) {
        fprintf(stderr, "Error getting input line %d: %s\n", GPIO_INPUT_PIN, strerror(errno));
        goto cleanup;
    }

    gain_line = gpiod_chip_get_line(chip, GPIO_GAIN_PIN);
    if (!gain_line) {
        fprintf(stderr, "Error getting gain line %d: %s\n", GPIO_GAIN_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(gain_line, "max9814_gain", 0) < 0) {
        fprintf(stderr, "Error requesting gain line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(input_line, "max9814_input") < 0) {
        fprintf(stderr, "Error requesting input line: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Audio peak detection started. Press Ctrl+C to exit.\n");

    int prev_value = gpiod_line_get_value(input_line);
    if (prev_value < 0) {
        fprintf(stderr, "Error reading initial input value: %s\n", strerror(errno));
        goto cleanup;
    }

    while (program_running) {
        int value = gpiod_line_get_value(input_line);
        if (value < 0) {
            fprintf(stderr, "Error reading input value: %s\n", strerror(errno));
            break;
        }

        if (value == 1 && prev_value == 0) {
            if (log_peak_event(LOG_FILE) < 0) {
                fprintf(stderr, "Error logging peak event\n");
            }
        }

        prev_value = value;
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (input_line) gpiod_line_release(input_line);
    if (gain_line) gpiod_line_release(gain_line);
    if (chip) gpiod_chip_close(chip);

    printf("Audio peak detection stopped.\n");
    return ret;
}

