#define I2C_ADDR 0x70
#define LOG_FILE "air_quality_log.csv"
#define SAMPLE_INTERVAL_SEC 5

/* MICS-VZ-89TE register map (representative) */
#define REG_TVOC_MSB 0x01
#define REG_TVOC_LSB 0x02
#define REG_ECO2_MSB 0x05
#define REG_ECO2_LSB 0x06

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint16_t *tvoc, uint16_t *eco2) {
    char buf[7];
    int rc;

    /* Read 7 bytes starting at register 0x00 */
    rc = i2cReadI2CBlockData(handle, 0x00, buf, 7);
    if (rc != 7) {
        fprintf(stderr, "I2C block read failed (rc=%d)\n", rc);
        return -1;
    }

    *tvoc = ((uint16_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    *eco2 = ((uint16_t)(uint8_t)buf[6] << 8) | (uint8_t)buf[5];
    return 0;
}

static float calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    float iaq = 100.0f - ((float)tvoc / 10.0f) - (((float)eco2 - 400.0f) / 50.0f);
    if (iaq < 0.0f) iaq = 0.0f;
    if (iaq > 100.0f) iaq = 100.0f;
    return iaq;
}

static int log_data(FILE *fp, float iaq, uint16_t tvoc, uint16_t eco2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f,%u,%u\n", timestamp, iaq, tvoc, eco2) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    uint16_t tvoc, eco2;
    float iaq;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,IAQ,TVOC_ppb,eCO2_ppm\n");
        fflush(log_file);
    }

    while (running) {
        if (read_sensor_data(i2c_handle, &tvoc, &eco2) == 0) {
            iaq = calculate_iaq(tvoc, eco2);
            if (log_data(log_file, iaq, tvoc, eco2) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle\n");
        }

        /* Sleep in 1-second increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

