#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_MS 100
#define TAMPER_THRESHOLD_S 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line, "ttp223_tamper") < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring TTP223B touch sensor on GPIO %d (chip %s)...\n",
           GPIO_LINE_OFFSET, GPIO_CHIP_NAME);
    printf("Press Ctrl+C to exit.\n");

    struct timespec last_touch = {0, 0};
    int first_touch = 1;

    while (g_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        if (val == 1) {
            if (first_touch) {
                last_touch = now;
                first_touch = 0;
            } else if (now.tv_sec - last_touch.tv_sec >= TAMPER_THRESHOLD_S) {
                printf("ALERT: Tamper detected on GPIO %d (touched for > %d s)\n",
                       GPIO_LINE_OFFSET, TAMPER_THRESHOLD_S);
                fflush(stdout);
                last_touch = now;
            }
        } else {
            first_touch = 1;
        }

        struct timespec sleep_ts = {0, POLL_INTERVAL_MS * 1000000L};
        nanosleep(&sleep_ts, NULL);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

