        fprintf(stderr, "Failed to open %s: %s\n", I2S_DEVICE, strerror(errno));
        return -1;
    }

    int format = AFMT_S16_LE;
    if (ioctl(*fd, SNDCTL_DSP_SETFMT, &format) == -1) {
        fprintf(stderr, "Failed to set audio format: %s\n", strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }

    int channels = 2;
    if (ioctl(*fd, SNDCTL_DSP_CHANNELS, &channels) == -1) {
        fprintf(stderr, "Failed to set channels: %s\n", strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }

    int rate = SAMPLE_RATE;
    if (ioctl(*fd, SNDCTL_DSP_SPEED, &rate) == -1) {
        fprintf(stderr, "Failed to set sample rate: %s\n", strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }

    return 0;
}

static int read_i2s_data(int fd, short *buffer, int num_samples) {
    size_t bytes_to_read = (size_t)num_samples * 2;
    ssize_t bytes_read = read(fd, buffer, bytes_to_read);

    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from I2S device: %s\n", strerror(errno));
        return -1;
    }

    if (bytes_read < bytes_to_read) {
        fprintf(stderr, "Incomplete read: %zd bytes read, expected %zu\n", bytes_read, bytes_to_read);
        return -1;
    }

    return 0;
}

static int write_to_file(const char *filename, const short *buffer, int num_samples) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t elements_written = fwrite(buffer, sizeof(short), num_samples, fp);
    if (elements_written != (size_t)num_samples) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int fd = -1;
    struct gpiod_chip *gpio_chip = NULL;
    struct gpiod_line *gpio_line = NULL;
    short *audio_buffer = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }

    if (init_gpio(&gpio_chip, &gpio_line) != 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        goto cleanup;
    }

    if (init_alsa(&fd) != 0) {
        fprintf(stderr, "ALSA initialization failed.\n");
        goto cleanup;
    }

    audio_buffer = (short *)malloc(BUFFER_SIZE * sizeof(short));
    if (!audio_buffer) {
        fprintf(stderr, "Failed to allocate memory for audio buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Audio capture started. Press Ctrl+C to stop.\n");

    while (running) {
        if (read_i2s_data(fd, audio_buffer, BUFFER_SIZE) != 0) {
            fprintf(stderr, "Error reading I2S data, exiting.\n");
            break;
        }

        if (write_to_file(FILE_NAME, audio_buffer, BUFFER_SIZE) != 0) {
            fprintf(stderr, "Error writing to file, exiting.\n");
            break;
        }
    }

    ret = 0;

cleanup:
    if (audio_buffer) {
        free(audio_buffer);
    }
    if (fd >= 0) {
        close(fd);
    }
    cleanup_gpio(gpio_chip, gpio_line);

    printf("Audio capture stopped.\n");
    return ret;
}

