#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define FLAME_SENSOR_GPIO 4
#define FAN_GPIO 18
#define PWM_FREQUENCY 100
#define PWM_RANGE 1000
#define POLL_INTERVAL_US 50000
#define DEBOUNCE_US 50000
#define LOG_FILE "flame_log.txt"
#define SENSOR_TIMEOUT_S 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    }
    fclose(fp);
}

static int read_flame_sensor(void) {
    int v1 = gpioRead(FLAME_SENSOR_GPIO);
    if (v1 < 0) {
        log_event("ERROR: gpioRead failed on flame sensor");
        return -1;
    }
    gpioDelay(DEBOUNCE_US);
    int v2 = gpioRead(FLAME_SENSOR_GPIO);
    if (v2 < 0) {
        log_event("ERROR: gpioRead failed on flame sensor (debounce)");
        return -1;
    }
    return (v1 == v2) ? v1 : -1;
}

static void control_fan(int flame_detected) {
    if (flame_detected) {
        static uint32_t start_tick = 0;
        static int first = 1;
        uint32_t now = gpioTick();
        if (first) {
            start_tick = now;
            first = 0;
        }
        double duration = (double)(now - start_tick) / 1000000.0;
        double duty = 0.0;
        if (duration > 0.0) {
            duty = 0.8 * (1.0 - exp(-duration / 1.0));
            if (duty > 1.0) duty = 1.0;
            if (duty < 0.0) duty = 0.0;
        }
        int pwm_value = (int)(duty * PWM_RANGE);
        if (gpioPWM(FAN_GPIO, pwm_value) < 0) {
            log_event("ERROR: gpioPWM start failed");
        }
    } else {
        if (gpioPWM(FAN_GPIO, 0) < 0) {
            log_event("ERROR: gpioPWM stop failed");
        }
    }
}

static void cleanup(void) {
    gpioPWM(FAN_GPIO, 0);
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(FAN_GPIO, PI_INPUT);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set fan GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("System started");

    int last_state = -1;
    time_t last_detection_time = 0;
    int sensor_timeout = 0;

    while (running) {
        int flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (flame_detected == 0) {
            if (last_state != 0) {
                last_detection_time = time(NULL);
                sensor_timeout = 0;
                log_event("Flame detected");
            }
            last_state = 0;
            sensor_timeout = 0;
        } else {
            if (last_state != 1) {
                if (time(NULL) - last_detection_time > SENSOR_TIMEOUT_S) {
                    log_event("Sensor timeout: no flame for 10s");
                }
            }
            last_state = 1;
            sensor_timeout++;
            if (sensor_timeout > 10) {
                log_event("Sensor timeout: flame stuck HIGH");
            }
        }

        control_fan(flame_detected);

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("System shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

