#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define TRIGGER_PIN 23
#define DATA_READY_PIN 24
#define DATA_SIZE 32768
#define LOG_FILE "radar_data.bin"

#define MAGIC_NUMBER 0x52444144
#define HEADER_SIZE 32

typedef struct {
    uint32_t magic_number;
    uint64_t timestamp;
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint32_t num_chirps;
    uint32_t num_samples;
    uint32_t frame_period_ms;
} radar_config_t;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting trigger pin mode\n");
        return -1;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting data ready pin mode\n");
        return -1;
    }
    if (gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error setting pull-up on data ready pin\n");
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error writing trigger pin\n");
        return -1;
    }
    return 0;
}

static int write_header(FILE *fp, const radar_config_t *cfg) {
    uint8_t header[HEADER_SIZE];
    memset(header, 0, HEADER_SIZE);
    header[0] = (uint8_t)(cfg->magic_number & 0xFF);
    header[1] = (uint8_t)((cfg->magic_number >> 8) & 0xFF);
    header[2] = (uint8_t)((cfg->magic_number >> 16) & 0xFF);
    header[3] = (uint8_t)((cfg->magic_number >> 24) & 0xFF);
    memcpy(&header[4], &cfg->timestamp, 8);
    memcpy(&header[12], &cfg->start_frequency, 4);
    memcpy(&header[16], &cfg->end_frequency, 4);
    memcpy(&header[20], &cfg->num_chirps, 4);
    memcpy(&header[24], &cfg->num_samples, 4);
    memcpy(&header[28], &cfg->frame_period_ms, 4);
    if (fwrite(header, 1, HEADER_SIZE, fp) != HEADER_SIZE) {
        fprintf(stderr, "Error writing header\n");
        return -1;
    }
    return 0;
}

static int log_frame(FILE *fp, const uint8_t *data, size_t size) {
    uint64_t ts;
    struct timespec spec;
    if (clock_gettime(CLOCK_REALTIME, &spec) != 0) {
        fprintf(stderr, "Error getting time\n");
        return -1;
    }
    ts = (uint64_t)spec.tv_sec * 1000ULL + (uint64_t)spec.tv_nsec / 1000000ULL;
    if (fwrite(&ts, 1, 8, fp) != 8) {
        fprintf(stderr, "Error writing timestamp\n");
        return -1;
    }
    if (fwrite(data, 1, size, fp) != size) {
        fprintf(stderr, "Error writing data\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    radar_config_t config = {
        .magic_number = MAGIC_NUMBER,
        .start_frequency = 77000000000ULL,
        .end_frequency = 79000000000ULL,
        .num_chirps = 64,
        .num_samples = 256,
        .frame_period_ms = 100
    };
    uint8_t *data_buffer = NULL;
    int frame_number = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_gpio() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (write_header(log_file, &config) != 0) {
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    data_buffer = malloc(DATA_SIZE);
    if (data_buffer == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting signal handler\n");
        free(data_buffer);
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting data acquisition...\n");

    while (running) {
        if (gpioWrite(TRIGGER_PIN, 1) < 0) {
            fprintf(stderr, "Error asserting trigger\n");
            break;
        }
        gpioDelay(1000);

        if (!running) break;

        if (gpioWrite(TRIGGER_PIN, 0) < 0) {
            fprintf(stderr, "Error de-asserting trigger\n");
            break;
        }

        int ready = 0;
        for (int i = 0; i < 100; i++) {
            if (gpioRead(DATA_READY_PIN) == 1) {
                ready = 1;
                break;
            }
            gpioDelay(1000);
        }

        if (!ready) {
            fprintf(stderr, "Timeout waiting for data ready\n");
            continue;
        }

        int ret = spiXfer(spi_handle, (char *)data_buffer, (char *)data_buffer, DATA_SIZE);
        if (ret != (int)DATA_SIZE) {
            fprintf(stderr, "SPI transfer error: %d\n", ret);
            break;
        }

        if (log_frame(log_file, data_buffer, DATA_SIZE) != 0) {
            break;
        }

        frame_number++;
        printf("Frame %d logged\n", frame_number);
    }

    printf("\nShutting down...\n");
    free(data_buffer);
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

