    ts = (uint64_t)spec.tv_sec * 1000ULL + (uint64_t)spec.tv_nsec / 1000000ULL;
    if (fwrite(&ts, 1, 8, fp) != 8) {
        fprintf(stderr, "Error writing timestamp\n");
        return -1;
    }
    if (fwrite(data, 1, size, fp) != size) {
        fprintf(stderr, "Error writing data\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    radar_config_t config = {
        .magic_number = MAGIC_NUMBER,
        .start_frequency = 77000000000ULL,
        .end_frequency = 79000000000ULL,
        .num_chirps = 64,
        .num_samples = 256,
        .frame_period_ms = 100
    };
    uint8_t *data_buffer = NULL;
    int frame_number = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_gpio() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (write_header(log_file, &config) != 0) {
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    data_buffer = malloc(DATA_SIZE);
    if (data_buffer == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting signal handler\n");
        free(data_buffer);
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting data acquisition...\n");

    while (running) {
        if (gpioWrite(TRIGGER_PIN, 1) < 0) {
            fprintf(stderr, "Error asserting trigger\n");
            break;
        }
        gpioDelay(1000);

        if (!running) break;

        if (gpioWrite(TRIGGER_PIN, 0) < 0) {
            fprintf(stderr, "Error de-asserting trigger\n");
            break;
        }

        int ready = 0;
        for (int i = 0; i < 100; i++) {
            if (gpioRead(DATA_READY_PIN) == 1) {
                ready = 1;
                break;
            }
            gpioDelay(1000);
        }

        if (!ready) {
            fprintf(stderr, "Timeout waiting for data ready\n");
            continue;
        }

        int ret = spiXfer(spi_handle, (char *)data_buffer, (char *)data_buffer, DATA_SIZE);
        if (ret != (int)DATA_SIZE) {
            fprintf(stderr, "SPI transfer error: %d\n", ret);
            break;
        }

        if (log_frame(log_file, data_buffer, DATA_SIZE) != 0) {
            break;
        }

        frame_number++;
        printf("Frame %d logged\n", frame_number);
    }

    printf("\nShutting down...\n");
    free(data_buffer);
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

