/*
 * flame_detect.c - Read SainSmart IR Flame Sensor on GPIO 17 using libgpiod v2.x
 *
 * Wiring (Raspberry Pi 3 Model B+):
 *   Sensor VCC -> 5V (Pin 2)
 *   Sensor GND -> GND (Pin 6)
 *   Sensor DOUT-> GPIO17 (Pin 11)
 *
 * The digital output is active-low: 0 = flame detected, 1 = no flame.
 *
 * Build: gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    printf("[%s] ", timestamp);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure the line as input with pull-up bias (active-low sensor) */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "Failed to allocate line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Failed to set input direction: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up bias: %s\n", strerror(errno));
        goto cleanup;
    }

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "Failed to allocate line config: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned int offsets[1] = { GPIO_LINE_OFFSET };
    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 1, settings) < 0) {
