#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 100

static const unsigned int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int ret;
    int i;

    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = NULL;
    }

    /* Register signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi Zero W) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    /* Request each line as input */
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u\n", channel_pins[i]);
            goto cleanup;
        }

        ret = gpiod_line_request_input(lines[i], "ttp226-touch");
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n",
                    channel_pins[i], strerror(-ret));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO line %u: %s\n",
                        channel_pins[i], strerror(-val));
                goto cleanup;
            }
            printf("Channel %d (GPIO %u): %d\n", i, channel_pins[i], val);
        }
        printf("---\n");
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

