{
    (void)sig;
    running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = touch_pins[i];

        if (gpioSetMode(pin, PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", pin);
            gpioTerminate();
            return -1;
        }

        if (gpioSetPullUpDown(pin, PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d.\n", pin);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

static void log_sensor_data(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    long elapsed_ms = (long)ts.tv_sec * 1000L + ts.tv_nsec / 1000000L;

    printf("[%ld ms] ", elapsed_ms);

    for (int i = 0; i < NUM_CHANNELS; i++) {
        int state = gpioRead(touch_pins[i]);
        if (state < 0) {
            fprintf(stderr, "Warning: gpioRead failed for pin %d.\n", touch_pins[i]);
            printf("CH%d=-1 ", i + 1);
        } else {
            printf("CH%d=%d ", i + 1, state);
        }
    }
    printf("\n");
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("TTP226 8-channel touch sensor monitoring started.\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        log_sensor_data();
        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

