#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", timeinfo);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", gpio_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_input_flags(lines[i], "ttp226-touch", GPIOD_LINE_REQUEST_FLAG_BIAS_DISABLE) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n", gpio_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Timestamp,Channel1,Channel2,Channel3,Channel4,Channel5,Channel6,Channel7,Channel8\n");

    while (program_running) {
        int values[NUM_CHANNELS];
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading GPIO line %u: %s\n", gpio_pins[i], strerror(errno));
                error = 1;
                break;
            }
            values[i] = val;
        }

        if (error) {
            break;
        }

        char timestamp[32];
        get_timestamp(timestamp, sizeof(timestamp));

        printf("%s,%d,%d,%d,%d,%d,%d,%d,%d\n",
               timestamp,
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

