#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_tilt_state(int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                     &timeinfo) > 0) {
            printf("[%s] Tilt Sensor: %s\n", timestamp,
                   state == 0 ? "Tilted" : "Not Tilted");
        } else {
            printf("[timestamp error] Tilt Sensor: %s\n",
                   state == 0 ? "Tilted" : "Not Tilted");
        }
    } else {
        printf("[unknown time] Tilt Sensor: %s\n",
               state == 0 ? "Tilted" : "Not Tilted");
    }
    fflush(stdout);
}

int main(void)
{
    int last_state = -1;  /* unknown initial state */

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n",
                TILT_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to enable pull-up on GPIO %d.\n",
                TILT_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    printf("Tilt sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n",
           TILT_SENSOR_GPIO);
    fflush(stdout);

    while (g_running) {
        int current_state = gpioRead(TILT_SENSOR_GPIO);

        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO %d.\n",
                    TILT_SENSOR_GPIO);
            break;
        }

        if (current_state != last_state) {
            log_tilt_state(current_state);
            last_state = current_state;
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

