#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x36
#define SENSOR2_ADDR   0x37
#define ALARM_GPIO     17
#define FLOW_THRESHOLD 0.5f
#define FLOW_SCALE     0.036f
#define I2C_CMD_REG   0x08
#define I2C_MEAS_REG  0x00
#define START_MEAS_CMD 0x3608
#define MEAS_DELAY_MS  100
#define LOOP_DELAY_MS  1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write cmd 0x%04X failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(int fd) {
    if (i2c_write_cmd(fd, START_MEAS_CMD) < 0)
        return -1;
    usleep(MEAS_DELAY_MS * 1000);
    return 0;
}

static int read_flow_rate(int fd, float *flow_out) {
    uint8_t buf[9];
    if (i2c_read_bytes(fd, I2C_MEAS_REG, buf, 9) < 0)
        return -1;

    for (int i = 0; i < 3; i++) {
        if (sensirion_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on measurement %d\n", i);
            return -1;
        }
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw * FLOW_SCALE;
    return 0;
}

static void log_flow(FILE *fp, float f1, float f2, float avg) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Sensor1: %.3f, Sensor2: %.3f, Avg: %.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, f1, f2, avg);
    fflush(fp);
}

int main(void) {
    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }
    struct gpiod_line *alarm = gpiod_chip_get_line(chip, ALARM_GPIO);
    if (!alarm) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", ALARM_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(alarm, "flow_alarm", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", ALARM_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int fd1 = open(I2C_BUS, O_RDWR);
    if (fd1 < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_line_release(alarm);
        gpiod_chip_close(chip);
        return 1;
    }
    int fd2 = open(I2C_BUS, O_RDWR);
    if (fd2 < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        close(fd1);
        gpiod_line_release(alarm);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(fd1, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SENSOR1_ADDR, strerror(errno));
        goto cleanup;
    }
    if (ioctl(fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SENSOR2_ADDR, strerror(errno));
        goto cleanup;
    }

    if (init_sensor(fd1) < 0 || init_sensor(fd2) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        goto cleanup;
    }

    FILE *log = fopen("flow_log.txt", "a");
    if (!log) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = read_flow_rate(fd1, &f1);
        int ok2 = read_flow_rate(fd2, &f2);

        if (ok1 < 0 || ok2 < 0) {
            fprintf(stderr, "Sensor read error; skipping cycle\n");
        } else {
            float avg = (f1 + f2) / 2.0f;
            log_flow(log, f1, f2, avg);
            gpiod_line_set_value(alarm, (avg < FLOW_THRESHOLD) ? 1 : 0);
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

cleanup:
    gpiod_line_set_value(alarm, 0);
    gpiod_line_release(alarm);
    gpiod_chip_close(chip);
    if (log) fclose(log);
    if (fd1 >= 0) close(fd1);
    if (fd2 >= 0) close(fd2);
    return 0;
}

