    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Sensor1: %.3f, Sensor2: %.3f, Avg: %.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, f1, f2, avg);
    fflush(fp);
}

int main(void) {
    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }
    struct gpiod_line *alarm = gpiod_chip_get_line(chip, ALARM_GPIO);
    if (!alarm) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", ALARM_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(alarm, "flow_alarm", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", ALARM_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int fd1 = open(I2C_BUS, O_RDWR);
    if (fd1 < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_line_release(alarm);
        gpiod_chip_close(chip);
        return 1;
    }
    int fd2 = open(I2C_BUS, O_RDWR);
    if (fd2 < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        close(fd1);
        gpiod_line_release(alarm);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(fd1, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SENSOR1_ADDR, strerror(errno));
        goto cleanup;
    }
    if (ioctl(fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SENSOR2_ADDR, strerror(errno));
        goto cleanup;
    }

    if (init_sensor(fd1) < 0 || init_sensor(fd2) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        goto cleanup;
    }

    FILE *log = fopen("flow_log.txt", "a");
    if (!log) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = read_flow_rate(fd1, &f1);
        int ok2 = read_flow_rate(fd2, &f2);

        if (ok1 < 0 || ok2 < 0) {
            fprintf(stderr, "Sensor read error; skipping cycle\n");
        } else {
            float avg = (f1 + f2) / 2.0f;
            log_flow(log, f1, f2, avg);
            gpiod_line_set_value(alarm, (avg < FLOW_THRESHOLD) ? 1 : 0);
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

cleanup:
    gpiod_line_set_value(alarm, 0);
    gpiod_line_release(alarm);
    gpiod_chip_close(chip);
    if (log) fclose(log);
    if (fd1 >= 0) close(fd1);
    if (fd2 >= 0) close(fd2);
    return 0;
}

