#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000  /* 50 ms */

typedef struct {
    time_t timestamp;
    int sensor_reading;
} sensor_data_t;

static sensor_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void add_to_buffer(time_t timestamp, int sensor_reading) {
    circular_buffer[buffer_index].timestamp = timestamp;
    circular_buffer[buffer_index].sensor_reading = sensor_reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void) {
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&circular_buffer[idx].timestamp);
        if (tm_info == NULL) {
            snprintf(time_str, sizeof(time_str), "INVALID_TIME");
        } else {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        }
        printf("[%d] Timestamp: %s, Sensor Reading: %d\n",
               idx, time_str, circular_buffer[idx].sensor_reading);
    }
    printf("--- End of Log ---\n\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to enable pull-up on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }

    printf("Obstacle avoidance sensor monitoring started on GPIO %d.\n", GPIO_PIN);
    printf("Press Ctrl+C to exit and print the log.\n");

    while (program_running) {
        int sensor_value = gpioRead(GPIO_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO %d\n", GPIO_PIN);
            break;
        }

        time_t current_time = time(NULL);
        if (current_time == (time_t)-1) {
            fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
            break;
        }

        if (sensor_value == 0) {
            add_to_buffer(current_time, sensor_value);
            printf("Obstacle detected! Timestamp: %ld, Sensor Reading: %d\n",
                   (long)current_time, sensor_value);
        }

        gpioDelay(POLL_DELAY_US);
    }

    print_buffer();
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

