/*
 * fan_health.c — Omron D7S vibration monitor for Raspberry Pi 5
 *
 * Wiring:
 *   D7S SDA  -> GPIO 2 (pin 3, I2C bus 1)
 *   D7S SCL  -> GPIO 3 (pin 5, I2C bus 1)
 *   D7S VDD  -> 3.3 V
 *   D7S GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o fan_health fan_health.c
 *
 * Run:
 *   ./fan_health
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- D7S constants (from Omron D7S datasheet) ---- */
#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x55          /* 7-bit I2C address */
#define D7S_REG_MODE   0x1D          /* MODE_CONTROL register */
#define D7S_REG_STATUS 0x1B          /* Operating status register */
#define D7S_REG_X_L    0x2A          /* X-axis LSB */
#define D7S_REG_X_H    0x2B
#define D7S_REG_Y_L    0x2C
#define D7S_REG_Y_H    0x2D
#define D7S_REG_Z_L    0x2E
#define D7S_REG_Z_H    0x2F
#define D7S_MODE_ACTIVE 0x10         /* bit 4: active mode */
#define D7S_STATUS_READY 0x01        /* bit 0: operating status ready */
#define D7S_SCALE_G    0.0009765625  /* g per LSB */
#define CSV_FILE       "fan_health.csv"
#define SAMPLE_PERIOD_MS 500
#define ACTIVATION_TIMEOUT_S 1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Write one byte to a D7S register. Returns 0 on success, -1 on error. */
static int d7s_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read one byte from a D7S register. Returns 0 on success, -1 on error. */
static int d7s_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* Read a 16-bit little-endian signed acceleration register pair. */
static int d7s_read_axis(int fd, uint8_t l_reg, int16_t *out)
{
    uint8_t lo, hi;
    if (d7s_read_reg(fd, l_reg, &lo) < 0)
        return -1;
    if (d7s_read_reg(fd, l_reg + 1, &hi) < 0)
        return -1;
    *out = (int16_t)((uint16_t)lo | ((uint16_t)hi << 8));
    return 0;
}

/* Open the I2C bus and claim the D7S slave address. Returns fd or -1. */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/* Activate the D7S and wait for the operating-status ready bit. */
static int d7s_activate(int fd)
{
    if (d7s_write_reg(fd, D7S_REG_MODE, D7S_MODE_ACTIVE) < 0)
        return -1;

    for (int i = 0; i < ACTIVATION_TIMEOUT_S * 10; i++) {
        uint8_t status;
        if (d7s_read_reg(fd, D7S_REG_STATUS, &status) < 0)
            return -1;
        if (status & D7S_STATUS_READY)
            return 0;
        usleep(100000); /* 100 ms */
    }
    fprintf(stderr, "D7S did not become ready within %d s\n",
            ACTIVATION_TIMEOUT_S);
    return -1;
}

/* Append a CSV row with an ISO-8601 timestamp. */
static int log_csv(FILE *fp, double x, double y, double z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush CSV failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = i2c_open(I2C_BUS, D7S_ADDR);
    if (fd < 0)
        return EXIT_FAILURE;

    if (d7s_activate(fd) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(CSV_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (fseek(fp, 0, SEEK_END) == 0) {
        long sz = ftell(fp);
        if (sz == 0)
            fprintf(fp, "timestamp,x_g,y_g,z_g\n");
    } else {
        fprintf(stderr, "fseek failed: %s\n", strerror(errno));
    }

    printf("Monitoring D7S at 0x%02X on %s. Press Ctrl+C to stop.\n",
           D7S_ADDR, I2C_BUS);

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        if (d7s_read_axis(fd, D7S_REG_X_L, &raw_x) < 0 ||
            d7s_read_axis(fd, D7S_REG_Y_L, &raw_y) < 0 ||
            d7s_read_axis(fd, D7S_REG_Z_L, &raw_z) < 0) {
            fprintf(stderr, "I2C read error — retrying next cycle\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        double x_g = raw_x * D7S_SCALE_G;
        double y_g = raw_y * D7S_SCALE_G;
        double z_g = raw_z * D7S_SCALE_G;

        if (log_csv(fp, x_g, y_g, z_g) < 0) {
            fprintf(stderr, "CSV logging failed — continuing\n");
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    if (fclose(fp) != 0)
        fprintf(stderr, "fclose CSV failed: %s\n", strerror(errno));
    if (close(fd) != 0)
        fprintf(stderr, "close I2C failed: %s\n", strerror(errno));
    return EXIT_SUCCESS;
}

