#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_THRESHOLD_SEC 2
#define POLL_INTERVAL_US 100000
#define LOG_FILE "stall_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_sensor(int gpio) {
    int val = gpioRead(gpio);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio, pigpio_error(val));
        return -1;
    }
    return val;
}

static int is_stall_confirmed(int s1, int s2) {
    if (s1 < 0 || s2 < 0) return 0;
    return (s1 == 0 && s2 == 0);
}

static int log_stall_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "Error converting time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Stall detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Conveyor belt stall detection started. Press Ctrl+C to exit.\n");

    time_t stall_start_time = 0;
    int stall_confirmed = 0;

    while (program_running) {
        int s1 = read_sensor(SENSOR_1_GPIO);
        int s2 = read_sensor(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error, exiting.\n");
            break;
        }

        if (is_stall_confirmed(s1, s2)) {
            if (!stall_confirmed) {
                stall_confirmed = 1;
                stall_start_time = time(NULL);
                if (stall_start_time == (time_t)-1) {
                    fprintf(stderr, "Error getting time for stall start\n");
                    break;
                }
                printf("Stall confirmed. Waiting for %d seconds...\n", STALL_THRESHOLD_SEC);
            } else {
                time_t now = time(NULL);
                if (now == (time_t)-1) {
                    fprintf(stderr, "Error getting time for stall check\n");
                    break;
                }
                if (difftime(now, stall_start_time) >= STALL_THRESHOLD_SEC) {
                    if (log_stall_event() == 0) {
                        printf("Stall event logged.\n");
                    } else {
                        fprintf(stderr, "Failed to log stall event.\n");
                    }
                    stall_confirmed = 0;
                }
            }
        } else {
            stall_confirmed = 0;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

