#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x0E
#define LOG_FILE       "magnetic_log.csv"
#define SAMPLE_US      100000  /* 100 ms */
#define EXPECTED_ID    0x8D

/* TMAG5170 register addresses */
#define REG_DEVICE_ID  0x00
#define REG_X_MSB      0x01
#define REG_X_LSB      0x02
#define REG_Y_MSB      0x03
#define REG_Y_LSB      0x04
#define REG_Z_MSB      0x05
#define REG_Z_LSB      0x06
#define REG_CONFIG     0x07

/* Config: continuous mode, X/Y/Z enabled, 50 mT range, 100 Hz ODR */
#define CONFIG_VAL     0x0000

/* 50 mT range => 0.0001 mT/LSB (16-bit two's complement) */
#define MT_PER_LSB     0.0001f

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_axis(int handle, uint8_t msb_reg, uint8_t lsb_reg, float *mt)
{
    uint8_t msb, lsb;
    if (read_register(handle, msb_reg, &msb) < 0) return -1;
    if (read_register(handle, lsb_reg, &lsb) < 0) return -1;

    int16_t raw = (int16_t)(((uint16_t)msb << 8) | (uint16_t)lsb);
    *mt = (float)raw * MT_PER_LSB;
    return 0;
}

static int log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.4f,%.4f,%.4f\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify device identity */
    uint8_t id;
    if (read_register(g_i2c_handle, REG_DEVICE_ID, &id) < 0) {
        fprintf(stderr, "Sensor not responding on bus %d addr 0x%02X\n",
                I2C_BUS, I2C_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }
    if (id != EXPECTED_ID) {
        fprintf(stderr, "Unexpected device ID 0x%02X (expected 0x%02X)\n",
                id, EXPECTED_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure sensor: continuous mode, X/Y/Z enabled, 50 mT range */
    if (write_register(g_i2c_handle, REG_CONFIG, (uint8_t)(CONFIG_VAL >> 8)) < 0) {
        fprintf(stderr, "Failed to write config MSB\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (write_register(g_i2c_handle, REG_CONFIG + 1, (uint8_t)(CONFIG_VAL & 0xFF)) < 0) {
        fprintf(stderr, "Failed to write config LSB\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file; write header if newly created */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen log");
        cleanup();
        return EXIT_FAILURE;
    }
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,X_mT,Y_mT,Z_mT\n");
        fflush(g_log_file);
    }

    printf("TMAG5170 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float x, y, z;

        if (read_axis(g_i2c_handle, REG_X_MSB, REG_X_LSB, &x) < 0 ||
            read_axis(g_i2c_handle, REG_Y_MSB, REG_Y_LSB, &y) < 0 ||
            read_axis(g_i2c_handle, REG_Z_MSB, REG_Z_LSB, &z) < 0) {
            fprintf(stderr, "Sensor read error; continuing\n");
        } else {
            if (log_data(g_log_file, x, y, z) < 0) {
                fprintf(stderr, "Log write error; continuing\n");
            }
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

