#include <pigpio.h>

#define SENSOR_GPIO 4          /* BCM 4, physical pin 7 */
#define LOG_FILE    "rpm_log.txt"
#define SAMPLE_SEC  1.0        /* 1-second sampling window */

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_pulse_count = 0;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and tears down cleanly */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback: count rising edges on SENSOR_GPIO            */
/* ------------------------------------------------------------------ */
static void pulse_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)tick;
    if (level == 1) {          /* rising edge */
        __sync_fetch_and_add(&g_pulse_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Write one timestamped RPM line to the log file and stdout           */
/* ------------------------------------------------------------------ */
static void log_rpm(double rpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s %.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush of log failed\n");
    }

    printf("%s %.2f\n", timestamp, rpm);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure GPIO ---- */
    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", SENSOR_GPIO);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d\n", SENSOR_GPIO);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- register alert callback ---- */
    if (gpioSetAlertFunc(SENSOR_GPIO, pulse_callback) != 0) {
        fprintf(stderr, "gpioSetAlertFunc failed for GPIO %d\n", SENSOR_GPIO);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed\n");
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR_GPIO);

    /* ---- main sampling loop ---- */
    while (g_running) {
        time_sleep(SAMPLE_SEC);

        if (!g_running) {
            break;  /* signal arrived during sleep */
        }

        int pulses = (int)__sync_fetch_and_zero(&g_pulse_count);
        double rpm = (double)pulses * 60.0;

        log_rpm(rpm);
    }

    /* ---- cleanup ---- */
    gpioSetAlertFunc(SENSOR_GPIO, NULL);   /* unregister callback */
    gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_OFF);  /* disable pull-up */
    gpioTerminate();
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    printf("RPM monitoring stopped.\n");
    return EXIT_SUCCESS;
}

