#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define SENSOR_A 17
#define SENSOR_B 27
#define LOG_FILE "rotation_log.txt"

static volatile int sensor_a_state = 0;
static volatile int sensor_b_state = 0;
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t running = 1;

static void log_rotation(const char *direction) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld - %s\n", timestamp, ts.tv_nsec / 1000000, direction);
    fflush(fp);
    fclose(fp);
}

static void sensor_a_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pthread_mutex_lock(&state_mutex);
        sensor_a_state = 1;
        pthread_mutex_unlock(&state_mutex);
    } else if (level == 0) {
        pthread_mutex_lock(&state_mutex);
        sensor_a_state = 0;
        pthread_mutex_unlock(&state_mutex);
    }
}

