#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define DEBOUNCE_US 5000
#define PULSES_PER_REV 2
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int gpio) {
    return gpioRead(gpio);
}

static void log_data(int s1, int s2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%d,%d\n", ts, s1, s2);
    fclose(fp);
}

static void calculate_rpm(int pulses, double dt) {
    if (dt > 0.0) {
        double rpm = (pulses / (double)PULSES_PER_REV) * (60.0 / dt);
        printf("RPM: %.2f\n", rpm);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistors\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int prev_s1 = -1, prev_s2 = -1;
    uint32_t last_tick = 0;
    int pulse_count = 0;
    struct timespec start, end;

    while (running) {
        int s1 = read_sensor(SENSOR1_GPIO);
        int s2 = read_sensor(SENSOR2_GPIO);

        if (s1 != prev_s1 || s2 != prev_s2) {
            if (clock_gettime(CLOCK_MONOTONIC, &start) == 0) {
                last_tick = start.tv_sec * 1000000 + start.tv_nsec / 1000;
            }

            if (s1 != prev_s1) {
                prev_s1 = s1;
            }
            if (s2 != prev_s2) {
                prev_s2 = s2;
            }

            log_data(s1, s2);
        }

        if (clock_gettime(CLOCK_MONOTONIC, &end) == 0) {
            uint32_t now = end.tv_sec * 1000000 + end.tv_nsec / 1000;
            if (now - last_tick >= DEBOUNCE_US) {
                pulse_count++;
                last_tick = now;
            }
        }

        gpioDelay(1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

