#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27
#define POLL_DELAY_US 100000  /* 100 ms */
#define TILT_THRESHOLD_S 2    /* 2 seconds */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *event_type, int sensor_pin) {
    if (!log_file) return;
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s - %s - Sensor %d\n", timestamp, event_type, sensor_pin) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    } else {
        fflush(log_file);
    }
}

static void cleanup(void) {
    if (log_file) {
        log_event("Program terminated", -1);
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure alarm is off before terminating pigpio */
    gpioWrite(ALARM_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALARM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize alarm pin LOW\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("bridge_integrity.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started", -1);

    int sensor1_tilted = 0;
    int sensor2_tilted = 0;
    uint32_t sensor1_tilt_start_tick = 0;
    uint32_t sensor2_tilt_start_tick = 0;
    int alarm_active = 0;

    while (program_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "gpioRead error (s1=%d, s2=%d)\n", s1, s2);
            break;
        }

        if (s1 == 1 && !sensor1_tilted) {
            sensor1_tilted = 1;
            sensor1_tilt_start_tick = gpioTick();
            log_event("Tilt started", SENSOR_1_PIN);
        } else if (s1 == 0 && sensor1_tilted) {
            sensor1_tilted = 0;
            log_event("Tilt ended", SENSOR_1_PIN);
        }

        if (s2 == 1 && !sensor2_tilted) {
            sensor2_tilted = 1;
            sensor2_tilt_start_tick = gpioTick();
            log_event("Tilt started", SENSOR_2_PIN);
        } else if (s2 == 0 && sensor2_tilted) {
            sensor2_tilted = 0;
            log_event("Tilt ended", SENSOR_2_PIN);
        }

        if (sensor1_tilted || sensor2_tilted) {
            uint32_t now = gpioTick();
            if (sensor1_tilted && (now - sensor1_tilt_start_tick) >= (TILT_THRESHOLD_S * 1000000)) {
                if (!alarm_active) {
                    if (gpioWrite(ALARM_PIN, 1) == 0) {
                        alarm_active = 1;
                        log_event("Alarm triggered", -1);
                    } else {
                        fprintf(stderr, "Failed to activate alarm\n");
                    }
                }
            }
            if (sensor2_tilted && (now - sensor2_tilt_start_tick) >= (TILT_THRESHOLD_S * 1000000)) {
                if (!alarm_active) {
                    if (gpioWrite(ALARM_PIN, 1) == 0) {
                        alarm_active = 1;
                        log_event("Alarm triggered", -1);
                    } else {
                        fprintf(stderr, "Failed to activate alarm\n");
                    }
                }
            }
        } else {
            if (alarm_active) {
                if (gpioWrite(ALARM_PIN, 0) == 0) {
                    alarm_active = 0;
                    log_event("Alarm deactivated", -1);
                } else {
                    fprintf(stderr, "Failed to deactivate alarm\n");
                }
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

