/*
 * Seismic vibration monitor for Raspberry Pi 3 Model B+
 * Sensor : Omron D7S-A0011 (I2C 7-bit address 0x1D)
 * Library: pigpio (I2C + GPIO)
 * Build  : gcc -O2 -Wall -o seismic seismic.c -lpigpio -lm -lrt
 * Run    : sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define I2C_ADDR           0x1D          /* D7S-A0011 default 7-bit address */
#define CTRL1_REG          0x1F          /* Control register 1 */
#define CTRL2_REG          0x20          /* Control register 2 */
#define OUT_X_L_REG        0x28          /* 6-byte block: X_L, X_H, Y_L, Y_H, Z_L, Z_H */
#define VIBRATION_THRESHOLD 500.0f       /* 16-bit signed, scaled per datasheet */
#define LED_GPIO           17
#define POLL_INTERVAL_US   100000        /* 100 ms */
#define MAX_RETRIES        3
#define LOG_FILE           "seismic_events.log"

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_sensor(void);
static int  read_acceleration(int16_t *x, int16_t *y, int16_t *z);
static float calculate_magnitude(int16_t x, int16_t y, int16_t z);
static void log_event(float magnitude);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C init ---------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- Sensor init ------------------------------- */
static int init_sensor(void)
{
    /* Verify sensor presence by reading CTRL1 (0x1F) */
    int reg = i2cReadByteData(g_i2c_handle, CTRL1_REG);
    if (reg < 0) {
        fprintf(stderr, "[ERROR] Sensor not responding at 0x%02X (I2C read failed)\n", I2C_ADDR);
        return -1;
    }

    /* Clear power-down bit (bit 0 of CTRL1) to enable continuous measurement */
    if (i2cWriteByteData(g_i2c_handle, CTRL1_REG, reg & ~0x01) < 0) {
        fprintf(stderr, "[ERROR] Failed to clear power-down bit in CTRL1\n");
        return -1;
    }

    /* Optional: configure CTRL2 (0x20) for ODR and full-scale range */
    if (i2cWriteByteData(g_i2c_handle, CTRL2_REG, 0x00) < 0) {
        fprintf(stderr, "[WARN] Failed to write CTRL2; continuing anyway\n");
    }

    return 0;
}

/* ----------------------------- Read acceleration -------------------------- */
static int read_acceleration(int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int n = i2cReadI2CBlockData(g_i2c_handle, OUT_X_L_REG, buf, 6);
        if (n == 6) {
            *x = (int16_t)((uint16_t)buf[1] << 8 | (uint8_t)buf[0]);
            *y = (int16_t)((uint16_t)buf[3] << 8 | (uint8_t)buf[2]);
            *z = (int16_t)((uint16_t)buf[5] << 8 | (uint8_t)buf[4]);
            return 0;
        }
        fprintf(stderr, "[WARN] I2C block read failed (attempt %d/%d): %d\n",
                attempt + 1, MAX_RETRIES, n);
