/*
 * flame_monitor.c — Monitor 5 Keyes KY-026 flame sensors on a Raspberry Pi 3 B+.
 *
 * Wiring (KY-026 module):
 *   Digital OUT  -> BCM GPIO 2, 3, 4, 17, 27  (physical pins 3, 5, 7, 11, 13)
 *   VCC          -> 3.3 V
 *   GND          -> GND
 *
 * The KY-026 digital output is LOW when a flame is detected, HIGH otherwise.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor   (needs /var/log write access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define LOG_FILE    "/var/log/flame_events.log"
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_S 1

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};
static const char *sensor_names[NUM_SENSORS] = {"Sensor 1", "Sensor 2", "Sensor 3", "Sensor 4", "Sensor 5"};
static struct gpiod_line *sensor_lines[NUM_SENSORS];
static struct gpiod_chip *chip = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void cleanup(void)
{
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
            sensor_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int log_event(int sensor_id, unsigned int gpio_pin)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open %s: %s", LOG_FILE, strerror(errno));
        return -1;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock failed: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_utc;
    if (!gmtime_r(&t, &tm_utc)) {
        syslog(LOG_ERR, "gmtime_r failed: %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime failed");
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %u) - Flame Detected\n",
                timestamp, sensor_id, gpio_pin) < 0) {
        syslog(LOG_ERR, "fprintf failed: %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        syslog(LOG_ERR, "fflush failed: %s", strerror(errno));
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_WARNING, "flock(UNLOCK) failed: %s", strerror(errno));
    }

    if (fclose(fp) != 0) {
        syslog(LOG_WARNING, "fclose failed: %s", strerror(errno));
    }

    return 0;
}

int main(void)
{
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
            syslog(LOG_ERR, "Failed to get GPIO line %u: %s",
                   sensor_pins[i], strerror(errno));
            cleanup();
            closelog();
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_input(sensor_lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "Failed to request GPIO %u as input: %s",
                   sensor_pins[i], strerror(errno));
            cleanup();
            closelog();
            return EXIT_FAILURE;
        }
    }

    syslog(LOG_INFO, "Flame monitor started. Monitoring %d sensors.", NUM_SENSORS);

    int prev_state[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        int v = gpiod_line_get_value(sensor_lines[i]);
        if (v < 0) {
            syslog(LOG_ERR, "Initial read failed on GPIO %u: %s",
                   sensor_pins[i], strerror(errno));
            prev_state[i] = -1;
        } else {
            prev_state[i] = v;
        }
    }

    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
