/*
 * TTP226 8-channel capacitive touch sensor reader using libgpiod v1.x.
 *
 * Wiring (Raspberry Pi 3 Model B+):
 *   TTP226 OUT0 -> BCM GPIO 5
 *   TTP226 OUT1 -> BCM GPIO 6
 *   TTP226 OUT2 -> BCM GPIO 13
 *   TTP226 OUT3 -> BCM GPIO 19
 *   TTP226 OUT4 -> BCM GPIO 26
 *   TTP226 OUT5 -> BCM GPIO 12
 *   TTP226 OUT6 -> BCM GPIO 16
 *   TTP226 OUT7 -> BCM GPIO 20
 *
 * Build: gcc -Wall -Wextra -o ttp226 ttp226.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int touch_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", &timeinfo);
        printf("[%s] ", buffer);
    } else {
        printf("[unknown-time] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int prev_states[NUM_CHANNELS];
    int ret;
    int i;

    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = NULL;
        prev_states[i] = -1;
    }

    /* Register signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default GPIO chip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: cannot open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Resolve each line individually */
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: cannot get line for BCM GPIO %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Request each line as input */
    for (i = 0; i < NUM_CHANNELS; i++) {
        ret = gpiod_line_request_input(lines[i], "ttp226-touch");
        if (ret < 0) {
            fprintf(stderr, "Error: cannot request BCM GPIO %u as input: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        int cur_states[NUM_CHANNELS];
        int changed = 0;

        /* Read all lines in a single bulk operation (libgpiod v1.x) */
        ret = gpiod_line_get_value_bulk(lines, cur_states, NUM_CHANNELS);
        if (ret < 0) {
            fprintf(stderr, "Error: bulk read failed: %s\n", strerror(errno));
            goto cleanup;
        }

        /* Detect and log state changes */
        for (i = 0; i < NUM_CHANNELS; i++) {
            if (cur_states[i] != prev_states[i]) {
                print_timestamp();
                if (cur_states[i] == 1) {
                    printf("Touch detected on sensor %d (BCM GPIO %u)\n",
                           i, touch_pins[i]);
                } else {
                    printf("Touch released on sensor %d (BCM GPIO %u)\n",
                           i, touch_pins[i]);
                }
                fflush(stdout);
                changed = 1;
            }
            prev_states[i] = cur_states[i];
        }

        if (changed) {
            usleep(POLL_INTERVAL_MS * 1000);
        }
    }

    printf("\nExiting gracefully...\n");

cleanup:
    /* Release lines and close chip */
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return (program_running == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

