#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS 0x04
#define LED_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int veml7700_write16(int handle, uint8_t reg, uint16_t val) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (char)(val & 0xFF);
    buf[2] = (char)((val >> 8) & 0xFF);
    if (i2cWriteDevice(handle, buf, 3) != 3) return -1;
    return 0;
}

static int veml7700_read16(int handle, uint8_t reg, uint16_t *val) {
    char reg_buf[1] = {reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 1) return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;
    *val = (uint16_t)((uint8_t)data[0] | ((uint8_t)data[1] << 8));
    return 0;
}

static int veml7700_init(int handle) {
    uint16_t config = 0x0000; /* ALS gain 1/8, IT 100ms */
    return veml7700_write16(handle, VEML7700_CONFIG, config);
}

static int read_lux(int handle, float *lux) {
    uint16_t raw;
    if (veml7700_read16(handle, VEML7700_ALS, &raw) != 0) return -1;
    *lux = (float)raw * 0.0576f;
    return 0;
}

static int set_led_brightness(int gpio, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    return gpioPWM(gpio, brightness);
}

static void log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Lux: %.2f, Brightness: %d, Error: %d\n",
            timestamp, lux, brightness, error_code);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n",
                VEML7700_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (veml7700_init(i2c_handle) != 0) {
        fprintf(stderr, "Failed to configure VEML7700 (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        float lux = 0.0f;
        int error_code = 0;

        if (read_lux(i2c_handle, &lux) != 0) {
            error_code = 1;
            lux = -1.0f;
        }

        int brightness;
        if (lux < 100.0f) brightness = PWM_RANGE;
        else if (lux < 500.0f) brightness = PWM_RANGE * 3 / 4;
        else if (lux < 1000.0f) brightness = PWM_RANGE * 1 / 2;
        else brightness = PWM_RANGE * 1 / 4;

        if (set_led_brightness(LED_GPIO, brightness) != 0) {
            error_code = 2;
        }

        log_data(log_file, lux, brightness, error_code);
        gpioDelay(1000000);
    }

    gpioPWM(LED_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

