int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n",
                VEML7700_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (veml7700_init(i2c_handle) != 0) {
        fprintf(stderr, "Failed to configure VEML7700 (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        float lux = 0.0f;
        int error_code = 0;

        if (read_lux(i2c_handle, &lux) != 0) {
            error_code = 1;
            lux = -1.0f;
        }

        int brightness;
        if (lux < 100.0f) brightness = PWM_RANGE;
        else if (lux < 500.0f) brightness = PWM_RANGE * 3 / 4;
        else if (lux < 1000.0f) brightness = PWM_RANGE * 1 / 2;
        else brightness = PWM_RANGE * 1 / 4;

        if (set_led_brightness(LED_GPIO, brightness) != 0) {
            error_code = 2;
        }

        log_data(log_file, lux, brightness, error_code);
        gpioDelay(1000000);
    }

    gpioPWM(LED_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

