#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 4
#define ALERT_PIN 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL_MS 500
#define ALERT_DURATION_MS 1000

static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int log_event(const char *message) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm *tstruct = localtime(&now);
    if (tstruct == NULL) {
        fprintf(stderr, "localtime() failed\n");
        return -1;
    }
    char buf[80];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (log_file == NULL) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }
    if (fprintf(log_file, "%s: %s\n", buf, message) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int trigger_alert(void) {
    if (gpioWrite(ALERT_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set ALERT_PIN HIGH\n");
        return -1;
    }
    gpioDelay(ALERT_DURATION_MS * 1000);
