#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x08
#define FLOW_CMD_MSB 0x36
#define FLOW_CMD_LSB 0x08
#define FLOW_SCALE 90.0f
#define FLOW_MIN 0.0f
#define FLOW_MAX 100.0f
#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE "cooling_log.csv"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int init_sensor(void) {
    char cmd[2] = {FLOW_CMD_MSB, FLOW_CMD_LSB};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to send start measurement command\n");
        return -1;
    }
    gpioDelay(2000);
    return 0;
}

static int read_flow(float *flow_rate, int *raw_value, int *error_flag) {
    char buf[3];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected 3)\n", bytes_read);
        *error_flag = 1;
        return -1;
    }
    if (crc8((uint8_t *)buf, 2) != (uint8_t)buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on flow data\n");
        *error_flag = 1;
        return -1;
    }
    int16_t raw = (int16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    *raw_value = (int)raw;
    *flow_rate = (float)raw / FLOW_SCALE;
    *error_flag = 0;
    return 0;
}

static const char *determine_status(float flow_rate, int raw_value, int error_flag) {
    if (error_flag) return "ERROR";
    if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) return "INVALID";
    return "OK";
}

static int log_data(float flow_rate, int raw_value, int error_flag, const char *status) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(log_file, "%s,%.2f,%d,%d,%s\n", timestamp, flow_rate, raw_value, error_flag, status) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(log_file);
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }
    printf("Coolant flow monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        float flow_rate = 0.0f;
        int raw_value = 0;
        int error_flag = 0;
        if (read_flow(&flow_rate, &raw_value, &error_flag) == 0) {
            const char *status = determine_status(flow_rate, raw_value, error_flag);
            if (log_data(flow_rate, raw_value, error_flag, status) != 0) {
                fprintf(stderr, "Error: logging failed, continuing\n");
            }
        } else {
            fprintf(stderr, "Error: sensor read failed, re-initializing I2C\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: i2cOpen failed after recovery (handle=%d)\n", i2c_handle);
            } else if (init_sensor() != 0) {
                fprintf(stderr, "Error: sensor re-init failed after recovery\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    printf("Coolant flow monitoring stopped.\n");
    return EXIT_SUCCESS;
}

