#include <string.h>
#include <errno.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_LEFT   17
#define GPIO_MIDDLE 27
#define GPIO_RIGHT  22
#define LOG_FILE    "path_log.csv"
#define POLL_MS     50

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL)
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
    else
        snprintf(buf, len, "1970-01-01T00:00:00");
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3];
    int pins[3] = { GPIO_LEFT, GPIO_MIDDLE, GPIO_RIGHT };
    FILE *log = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for GPIO%u: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "ky033-logger") < 0) {
            fprintf(stderr, "gpiod_line_request_input failed for GPIO%u: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("fopen");
        goto cleanup;
    }

    if (fprintf(log, "timestamp,left,middle,right\n") < 0) {
        perror("fprintf header");
        goto cleanup;
    }
    if (fflush(log) != 0) {
        perror("fflush header");
        goto cleanup;
    }

    printf("Logging KY-033 sensor data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        int vals[3];
        bool err = false;

        for (int i = 0; i < 3; i++) {
            vals[i] = gpiod_line_get_value(lines[i]);
            if (vals[i] < 0) {
                fprintf(stderr, "gpiod_line_get_value failed for GPIO%u: %s\n",
                        pins[i], strerror(errno));
                err = true;
                break;
            }
        }

        if (err)
            break;

        char ts[32];
        get_timestamp(ts, sizeof(ts));

        if (fprintf(log, "%s,%d,%d,%d\n", ts, vals[0], vals[1], vals[2]) < 0) {
            perror("fprintf data");
            break;
        }
        if (fflush(log) != 0) {
            perror("fflush data");
            break;
        }

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log) {
        fflush(log);
        fclose(log);
    }
    for (int i = 0; i < 3; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return ret;
}

