#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24
#define GPIO_CHIP "/dev/gpiochip4"
#define LOG_FILE "touch_log.txt"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_touch_event(int led_state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - LED state: %s\n", timestamp, led_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
        touch_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        fclose(log_file);
        log_file = NULL;
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        fprintf(stderr, "Error getting touch sensor line %d: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line %d: %s\n", LED_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(touch_line, "touch_sensor") < 0) {
        fprintf(stderr, "Error requesting rising edge events on touch line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "led_control", 0) < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Touch sensor and LED control program started. Press Ctrl+C to exit.\n");

    int led_state = 0;
    while (program_running) {
        struct timespec ts = { .tv_sec = POLL_TIMEOUT_MS / 1000, .tv_nsec = (POLL_TIMEOUT_MS % 1000) * 1000000L };
        int ret = gpiod_line_event_wait(touch_line, &ts);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error waiting for touch event: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "Error reading touch event: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            led_state = !led_state;
            if (gpiod_line_set_value(led_line, led_state) < 0) {
                fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
            }
            if (log_touch_event(led_state) != 0) {
                fprintf(stderr, "Error logging touch event\n");
            }
        }
    }

    printf("\nCleaning up and exiting...\n");
    cleanup();
    return EXIT_SUCCESS;
}

