/*
 * Flame detection safety system for Raspberry Pi 3 Model B+
 * Uses libgpiod (character-device API) instead of sysfs or wiringPi.
 *
 * Hardware:
 *   - Keyes KY-026 flame sensor  digital-out -> GPIO17 (physical pin 11)
 *   - Active buzzer               control     -> GPIO18 (physical pin 12)
 *
 * The KY-026 digital output is active-low: LOW  = flame detected,
 * HIGH = no flame.  The buzzer is active-high: HIGH = on, LOW = off.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define FLAME_SENSOR_PIN  17   /* GPIO17, physical pin 11 */
#define BUZZER_PIN        18   /* GPIO18, physical pin 12 */
#define LOG_FILE          "alert_log.txt"
#define POLL_INTERVAL_MS  500
#define BUZZER_DURATION_MS 2000
#define STEP_MS           100

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;
static struct gpiod_chip    *g_chip    = NULL;
static struct gpiod_line    *g_flame   = NULL;
static struct gpiod_line    *g_buzzer  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
    }
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *message)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        return;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (g_log_fp) {
        if (fprintf(g_log_fp, "%s: %s\n", ts, message) < 0) {
            perror("fprintf to log file");
        }
        if (fflush(g_log_fp) == EOF) {
            perror("fflush log file");
        }
    } else {
        fprintf(stderr, "[%s] %s\n", ts, message);
    }
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return -1;
    }

    g_flame = gpiod_chip_get_line(g_chip, FLAME_SENSOR_PIN);
    if (!g_flame) {
        perror("gpiod_chip_get_line(flame)");
        return -1;
    }

    g_buzzer = gpiod_chip_get_line(g_chip, BUZZER_PIN);
    if (!g_buzzer) {
        perror("gpiod_chip_get_line(buzzer)");
        return -1;
    }

    if (gpiod_line_request_input(g_flame, "flame_sensor") < 0) {
        perror("gpiod_line_request_input(flame)");
        return -1;
    }

    if (gpiod_line_request_output(g_buzzer, "buzzer", 0) < 0) {
        perror("gpiod_line_request_output(buzzer)");
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (g_buzzer) {
        (void)gpiod_line_set_value(g_buzzer, 0);
        gpiod_line_release(g_buzzer);
        g_buzzer = NULL;
    }
    if (g_flame) {
        gpiod_line_release(g_flame);
        g_flame = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Buzzer control (interruptible)                                     */
/* ------------------------------------------------------------------ */
static void buzzer_on(void)
{
    if (gpiod_line_set_value(g_buzzer, 1) < 0) {
        perror("gpiod_line_set_value(buzzer, 1)");
    }
}

static void buzzer_off(void)
{
    if (gpiod_line_set_value(g_buzzer, 0) < 0) {
        perror("gpiod_line_set_value(buzzer, 0)");
    }
}

static void interruptible_delay_ms(int ms)
{
    int remaining = ms;
    while (remaining > 0 && g_running) {
        int chunk = (remaining > STEP_MS) ? STEP_MS : remaining;
        usleep(chunk * 1000);
        remaining -= chunk;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(\"" LOG_FILE "\")");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        log_event("GPIO initialization failed");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    log_event("System started");

    int last_flame_state = gpiod_line_get_value(g_flame);
    if (last_flame_state < 0) {
        perror("gpiod_line_get_value(initial flame)");
        cleanup_gpio();
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    log_event("Monitoring flame sensor...");

    while (g_running) {
        int flame_state = gpiod_line_get_value(g_flame);
        if (flame_state < 0) {
            perror("gpiod_line_get_value(flame)");
            break;
        }

        /* Detect HIGH -> LOW transition (rising edge on the active-low
         * sensor output) and log the event. */
        if (last_flame_state == 1 && flame_state == 0) {
            log_event("Flame detected!");
            buzzer_on();
            interruptible_delay_ms(BUZZER_DURATION_MS);
            buzzer_off();
        }

        last_flame_state = flame_state;
        interruptible_delay_ms(POLL_INTERVAL_MS);
    }

    log_event("System stopped");
    cleanup_gpio();

    if (g_log_fp) {
        if (fclose(g_log_fp) == EOF) {
            perror("fclose log file");
        }
        g_log_fp = NULL;
    }

    return EXIT_SUCCESS;
}

