#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define LED_GPIO 17
#define LOG_FILE "touch_log.txt"
#define POLL_DELAY_US 10000   /* 10 ms */
#define DEBOUNCE_DELAY_US 200000 /* 200 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }

    /* Ensure LED is off at start */
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int log_touch_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: gmtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (log_file == NULL) {
        fprintf(stderr, "Error: log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s: Touch detected\n", timestamp) < 0) {
        fprintf(stderr, "Warning: failed to write to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file\n");
        return -1;
    }

    return 0;
}

static void toggle_led(void) {
    int current_state = gpioRead(LED_GPIO);
    if (current_state < 0) {
        fprintf(stderr, "Warning: gpioRead failed on LED GPIO%d\n", LED_GPIO);
        return;
    }

    if (gpioWrite(LED_GPIO, !current_state) != 0) {
        fprintf(stderr, "Warning: gpioWrite failed on LED GPIO%d\n", LED_GPIO);
    }
}

int main(void) {
    int last_touch_state = 0;
    int current_touch_state = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        current_touch_state = gpioRead(TOUCH_SENSOR_GPIO);
        if (current_touch_state < 0) {
            fprintf(stderr, "Warning: gpioRead failed on touch sensor GPIO%d\n", TOUCH_SENSOR_GPIO);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Detect rising edge: LOW -> HIGH */
        if (current_touch_state == 1 && last_touch_state == 0) {
            toggle_led();

            if (log_touch_event() != 0) {
                fprintf(stderr, "Warning: failed to log touch event\n");
            }

            gpioDelay(DEBOUNCE_DELAY_US);
        }

        last_touch_state = current_touch_state;
        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            perror("Warning: fclose failed on log file");
        }
        log_file = NULL;
    }

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

