#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define SENSOR_3_GPIO 27
#define LOG_FILE "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

/* TMAG5110A1 latch behavior:
 *   OUT is open-drain with internal pull-up.
 *   Logic LOW  -> magnet (south pole) present.
 *   Logic HIGH -> magnet removed (or no magnet).
 */

typedef struct {
    int gpio;
    const char *name;
} sensor_t;

static sensor_t sensors[] = {
    {SENSOR_1_GPIO, "SENSOR_1"},
    {SENSOR_2_GPIO, "SENSOR_2"},
    {SENSOR_3_GPIO, "SENSOR_3"}
};
static const int num_sensors = (int)(sizeof(sensors) / sizeof(sensors[0]));

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    for (int i = 0; i < num_sensors; i++) {
        if (gpioSetMode(sensors[i].gpio, PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for %s (GPIO %d).\n",
                    sensors[i].name, sensors[i].gpio);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(sensors[i].gpio, PI_PUD_UP) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for %s (GPIO %d).\n",
                    sensors[i].name, sensors[i].gpio);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_sensor(int gpio) {
    int level = gpioRead(gpio);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed for GPIO %d.\n", gpio);
        return -1;
    }
    return level;
}

static void log_event(const char *sensor_name, int level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }

    if (log_fp != NULL) {
        fprintf(log_fp, "%s - %s: %s\n", timestamp, sensor_name,
                (level == 0) ? "Magnet Present" : "Magnet Removed");
        fflush(log_fp);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

static void cleanup(void) {
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int prev_states[3] = {1, 1, 1};  /* assume no magnet present at startup */
    int first_read = 1;

    while (running) {
        for (int i = 0; i < num_sensors; i++) {
            int level = read_sensor(sensors[i].gpio);
            if (level < 0) {
                continue;
            }

            if (first_read) {
                prev_states[i] = level;
                first_read = 0;
            } else if (level != prev_states[i]) {
                log_event(sensors[i].name, level);
                prev_states[i] = level;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

