#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define LOG_FILE "heart_rate.csv"
#define SAMPLE_INTERVAL_US 1000000
#define MOVING_AVG_SIZE 5

#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_LED_CURRENT 0x07
#define REG_AVERAGING 0x08
#define REG_ENABLE 0x09
#define REG_HR_DATA 0x2A

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int initialize_sensor(int handle) {
    uint8_t part_id = 0, hw_rev = 0;

    if (read_register(handle, REG_PART_ID, &part_id) < 0) return -1;
    if (part_id != 0x02) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x02)\n", part_id);
        return -1;
    }
    if (read_register(handle, REG_HW_REV, &hw_rev) < 0) return -1;
    if (hw_rev != 0x01) {
        fprintf(stderr, "Unexpected HW_REV: 0x%02X (expected 0x01)\n", hw_rev);
        return -1;
    }

    if (write_register(handle, REG_LED_CURRENT, 0x3F) < 0) return -1;
    if (write_register(handle, REG_AVERAGING, 0x04) < 0) return -1;
    if (write_register(handle, REG_ENABLE, 0x01) < 0) return -1;

    return 0;
}

static int read_heart_rate(int handle, float *bpm) {
    int raw = i2cReadWordData(handle, REG_HR_DATA);
    if (raw < 0) {
        fprintf(stderr, "Error reading heart rate data: %d\n", raw);
        return -1;
    }
    *bpm = (float)raw * 0.5f;
    return 0;
}

static float moving_average(float new_value, float *buffer, int *index, int size) {
    buffer[*index] = new_value;
    *index = (*index + 1) % size;
    float sum = 0.0f;
    for (int i = 0; i < size; i++) sum += buffer[i];
    return sum / size;
}

static int log_data(FILE *fp, float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    float bpm_buffer[MOVING_AVG_SIZE] = {0.0f};
    int buffer_index = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Heart rate monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float bpm = 0.0f;
        if (read_heart_rate(i2c_handle, &bpm) == 0) {
            if (bpm >= 30.0f && bpm <= 220.0f) {
                float avg = moving_average(bpm, bpm_buffer, &buffer_index, MOVING_AVG_SIZE);
                if (log_data(log_file, avg) == 0) {
                    printf("BPM: %.2f\n", avg);
                }
            } else {
                fprintf(stderr, "Invalid BPM reading: %.2f\n", bpm);
            }
        } else {
            fprintf(stderr, "Failed to read heart rate data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nCleaning up...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

