/*
 * touch_counter.c — TTP226 8-channel capacitive touch -> 8-bit binary counter
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 * Run:    ./touch_counter
 *
 * TTP226 OUT1..OUT8 -> GPIO5,6,7,8,9,10,11,12 (BCM)
 * Counter display    -> GPIO17..24 (bit 0..7, LSB..MSB)
 *
 * Rising-edge detection per channel, 8-bit wrap, touch logging to
 * touch_log.txt.  Graceful shutdown on SIGINT/SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS  8
#define NUM_OUTPUTS   8
#define POLL_MS       10
#define STAB_MS       200
#define LOG_FILE      "touch_log.txt"

static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int output_pins[NUM_OUTPUTS]  = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_touch(FILE *log, int channel, int counter)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log) {
        fprintf(log, "%s, Channel: %d, Counter: %d\n", ts, channel, counter);
        fflush(log);
    }
    printf("Touch on channel %d | Counter: %d\n", channel, counter);
}

static int set_output(struct gpiod_line_request *req, int idx, int val)
{
    if (gpiod_line_request_set_value(req, output_pins[idx], val) < 0) {
        fprintf(stderr, "set_value(output %u, %d): %s\n",
                output_pins[idx], val, strerror(errno));
        return -1;
    }
    return 0;
}

static int update_display(struct gpiod_line_request *req, int counter)
{
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        if (set_output(req, i, (counter >> i) & 1) < 0)
            return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *req = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    FILE *log = NULL;
    int prev[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    memset(prev, 0, sizeof(prev));

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Warning: cannot open %s: %s — logging to stdout only\n",
                LOG_FILE, strerror(errno));
    }

    /* ---- open gpiochip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- request sensor lines as inputs ---- */
    line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        fprintf(stderr, "gpiod_line_config_new: %s\n", strerror(errno));
        goto cleanup;
    }

    settings = gpiod_line_settings_new();
    if (!settings) {
        fprintf(stderr, "gpiod_line_settings_new: %s\n", strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_config_add_line_settings(line_cfg, &sensor_pins[i], 1, settings) < 0) {
            fprintf(stderr, "add_line_settings(sensor %u): %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    req_cfg = gpiod_request_config_new();
    if (!req_cfg) {
        fprintf(stderr, "gpiod_request_config_new: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ttp226-touch");

    req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (!req) {
        fprintf(stderr, "gpiod_chip_request_lines(sensor): %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- request output lines as outputs, initial 0 ---- */
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_settings_set_output_value(settings, GPIOD_LINE_VALUE_INACTIVE);

    if (gpiod_line_config_add_line_settings(line_cfg, output_pins, NUM_OUTPUTS, settings) < 0) {
        fprintf(stderr, "add_line_settings(output): %s\n", strerror(errno));
        goto cleanup;
    }

    req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (!req) {
        fprintf(stderr, "gpiod_chip_request_lines(output): %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- stabilization delay ---- */
    usleep(STAB_MS * 1000);

    int counter = 0;

    /* ---- main loop ---- */
    while (g_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_request_get_value(req, sensor_pins[i]);
            if (val < 0) {
                fprintf(stderr, "get_value(sensor %u): %s\n",
                        sensor_pins[i], strerror(errno));
                continue;
            }

            if (val == 1 && prev[i] == 0) {
                counter = (counter + 1) & 0xFF;
                log_touch(log, i + 1, counter);
                if (update_display(req, counter) < 0) {
                    fprintf(stderr, "update_display failed\n");
                }
            }
            prev[i] = val;
        }
        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (req) {
        for (int i = 0; i < NUM_OUTPUTS; i++)
            (void)gpiod_line_request_set_value(req, output_pins[i], 0);
        gpiod_line_request_release(req);
    }
    if (req_cfg)
        gpiod_request_config_free(req_cfg);
    if (settings)
        gpiod_line_settings_free(settings);
    if (line_cfg)
        gpiod_line_config_free(line_cfg);
    if (chip)
        gpiod_chip_close(chip);
    if (log)
        fclose(log);
    return ret;
}

