#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_SENSORS 4
#define POLL_INTERVAL_US 100000
#define CSV_FILENAME "tracking_log.csv"

static const unsigned int sensor_pins[NUM_SENSORS] = {17, 18, 27, 22};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, const char *timestamp, const int values[NUM_SENSORS]) {
    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, values[0], values[1], values[2], values[3]) < 0) {
        return -1;
    }
