static struct gpiod_line *line2 = NULL;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    if (line1) {
        gpiod_line_release(line1);
        line1 = NULL;
    }
    if (line2) {
        gpiod_line_release(line2);
        line2 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int log_event(int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "localtime failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    int ret;
    int prev1 = 1, prev2 = 1;
    struct timespec last_event1 = {0, 0}, last_event2 = {0, 0};

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_LINE_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_1, strerror(errno));
        cleanup();
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_LINE_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_2, strerror(errno));
        cleanup();
        return 1;
    }

    ret = gpiod_line_request_input_flags(line1, "tilt-monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_LINE_1, strerror(errno));
        cleanup();
        return 1;
    }

    ret = gpiod_line_request_input_flags(line2, "tilt-monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_LINE_2, strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Monitoring tilt sensors on GPIO %d and %d. Press Ctrl+C to exit.\n", GPIO_LINE_1, GPIO_LINE_2);

    while (program_running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0) {
            fprintf(stderr, "Error reading line %d: %s\n", GPIO_LINE_1, strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }
        if (val2 < 0) {
            fprintf(stderr, "Error reading line %d: %s\n", GPIO_LINE_2, strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (val1 == 0 && prev1 == 1) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long diff_ms = (now.tv_sec - last_event1.tv_sec) * 1000L +
                           (now.tv_nsec - last_event1.tv_nsec) / 1000000L;
            if (diff_ms > DEBOUNCE_MS) {
                if (log_event(1) == 0) {
                    printf("Sensor 1 tilted\n");
                }
                last_event1 = now;
            }
        }
        prev1 = val1;

        if (val2 == 0 && prev2 == 1) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long diff_ms = (now.tv_sec - last_event2.tv_sec) * 1000L +
                           (now.tv_nsec - last_event2.tv_nsec) / 1000000L;
            if (diff_ms > DEBOUNCE_MS) {
                if (log_event(2) == 0) {
                    printf("Sensor 2 tilted\n");
                }
                last_event2 = now;
            }
        }
        prev2 = val2;

        usleep(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

