#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define MIC_PIN 4
#define LED_PIN 17
#define SAMPLE_PERIOD_US 125          /* ~8 kHz */
#define LED_ON_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char buf[32];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("%s.%03ld\n", buf, ts.tv_nsec / 1000000);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", MIC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise LED state on GPIO%d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring ICS-40180 on GPIO%d at ~8 kHz. Press Ctrl+C to exit.\n",
           MIC_PIN);
    fflush(stdout);

    while (running) {
        int level = gpioRead(MIC_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on GPIO%d\n", MIC_PIN);
            break;
        }

        if (level == 1) {
            print_timestamp();
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "gpioWrite failed on GPIO%d\n", LED_PIN);
                break;
            }
            gpioDelay(LED_ON_MS * 1000);
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "gpioWrite failed on GPIO%d\n", LED_PIN);
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

