#define GPIO_CHIP_NAME "gpiochip0"
#define LEFT_PIN  2
#define MIDDLE_PIN 3
#define RIGHT_PIN 4
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *middle_line = NULL;
    struct gpiod_line *right_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the three GPIO lines */
    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    middle_line = gpiod_chip_get_line(chip, MIDDLE_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);
    if (left_line == NULL || middle_line == NULL || right_line == NULL) {
        fprintf(stderr, "Error: Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request each line as input individually */
    if (gpiod_line_request_input(left_line, "tracking_sensor") < 0) {
        fprintf(stderr, "Error: Failed to request left line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(middle_line, "tracking_sensor") < 0) {
        fprintf(stderr, "Error: Failed to request middle line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(right_line, "tracking_sensor") < 0) {
        fprintf(stderr, "Error: Failed to request right line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Tracking sensor started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop */
    while (program_running) {
