 *
 * Wiring (Raspberry Pi 3 Model B+):
 *   TTP226 TP1 -> BCM GPIO 5
 *   TTP226 TP2 -> BCM GPIO 6
 *   TTP226 TP3 -> BCM GPIO 13
 *   TTP226 TP4 -> BCM GPIO 19
 *   TTP226 TP5 -> BCM GPIO 26
 *   TTP226 TP6 -> BCM GPIO 12
 *   TTP226 TP7 -> BCM GPIO 16
 *   TTP226 TP8 -> BCM GPIO 20
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ttp226 ttp226.c -lgpiod
 *
 * Run:
 *   ./ttp226
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

/* BCM GPIO numbers for the 8 TTP226 output lines */
static const unsigned int touch_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    printf("[%ld.%03ld] ", (long)ts.tv_sec, ts.tv_nsec / 1000000L);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++)
        lines[i] = NULL;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire and request each line as input */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get line for BCM GPIO %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "ttp226-touch") != 0) {
            fprintf(stderr, "Failed to request BCM GPIO %u as input: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int values[NUM_CHANNELS];
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading BCM GPIO %u: %s\n",
                        touch_pins[i], strerror(errno));
                error = 1;
                break;
            }
            values[i] = val;
        }

        if (error) {
            fprintf(stderr, "Sensor read error encountered, exiting.\n");
            break;
        }

        print_timestamp();
        printf("CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        /* Sleep for POLL_INTERVAL_MS, but wake early on signal */
        for (int ms = 0; ms < POLL_INTERVAL_MS && g_running; ms += 10)
            usleep(10000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nResources released. Exiting.\n");

    return ret;
}

