#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define PWM_FREQ  1000
#define PWM_RANGE 255
#define FADE_STEPS 50
#define FADE_MS   (5000 / FADE_STEPS)

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_led_color(uint8_t r, uint8_t g, uint8_t b) {
    int rc = 0;
    if (gpioPWM(RED_PIN,   255 - r) != 0) { syslog(LOG_ERR, "gpioPWM(RED) failed"); rc = -1; }
    if (gpioPWM(GREEN_PIN, 255 - g) != 0) { syslog(LOG_ERR, "gpioPWM(GREEN) failed"); rc = -1; }
    if (gpioPWM(BLUE_PIN,  255 - b) != 0) { syslog(LOG_ERR, "gpioPWM(BLUE) failed"); rc = -1; }
    return rc;
}

static int hsv_to_rgb(float h, float s, float v, uint8_t *r, uint8_t *g, uint8_t *b) {
    if (s <= 0.0f) {
        *r = *g = *b = (uint8_t)(v * 255.0f);
        return 0;
    }
    if (v <= 0.0f) {
        *r = *g = *b = 0;
        return 0;
    }
    h = fmodf(h, 360.0f);
    if (h < 0.0f) h += 360.0f;
    float hh = h / 60.0f;
    int   i  = (int)(hh);
    float ff = hh - (float)i;
    float p = v * (1.0f - s);
    float q = v * (1.0f - s * ff);
    float t = v * (1.0f - s * (1.0f - ff));
    switch (i) {
        case 0:  *r = v; *g = t; *b = p; break;
        case 1:  *r = q; *g = v; *b = p; break;
        case 2:  *r = p; *g = v; *b = t; break;
        case 3:  *r = p; *g = q; *b = v; break;
        case 4:  *r = t; *g = p; *b = v; break;
        default: *r = v; *g = p; *b = q; break;
    }
    *r = (uint8_t)(*r * 255.0f);
    *g = (uint8_t)(*g * 255.0f);
    *b = (uint8_t)(*b * 255.0f);
    return 0;
}

static int fade_to_hue(float target_hue) {
    float   current_h = 0.0f;
    uint8_t cr, cg, cb, tr, tg, tb;
    for (int i = 0; i < FADE_STEPS && g_running; i++) {
        float step = (float)i / (float)(FADE_STEPS - 1);
        float h = current_h + (target_hue - current_h) * step;
        hsv_to_rgb(h, 1.0f, 1.0f, &cr, &cg, &cb);
        hsv_to_rgb(target_hue, 1.0f, 1.0f, &tr, &tg, &tb);
        uint8_t dr = (uint8_t)((float)(tr - cr) * step + cr);
        uint8_t dg = (uint8_t)((float)(tg - cg) * step + cg);
        uint8_t db = (uint8_t)((float)(tb - cb) * step + cb);
        if (set_led_color(dr, dg, db) != 0) return -1;
        gpioDelay(FADE_MS * 1000);
    }
    return 0;
}

int main(void) {
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting mood lamp on GPIO17/18/27");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) != PWM_FREQ) {
        syslog(LOG_ERR, "gpioSetPWMfrequency failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) != PWM_RANGE) {
        syslog(LOG_ERR, "gpioSetPWMrange failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (set_led_color(0, 0, 0) != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    srand((unsigned)time(NULL));
    while (g_running) {
        float hue = (float)(rand() % 360000) / 1000.0f;
        if (fade_to_hue(hue) != 0) break;
    }

    set_led_color(0, 0, 0);
    gpioTerminate();
    syslog(LOG_INFO, "Mood lamp stopped");
    closelog();
    return EXIT_SUCCESS;
}

