#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29
#define TCS34725_ID    0x12
#define TCS34725_PON   0x00
#define TCS34725_AEN   0x01
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATAL 0x14
#define TCS34725_RDATAL 0x16
#define TCS34725_GDATAL 0x18
#define TCS34725_BDATAL 0x1A

#define LED_PIN        17
#define RED_THRESHOLD  200
#define POLL_MS        200

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, TCS34725_ID, &id) < 0) return -1;
    if (id != 0x44) {
        fprintf(stderr, "TCS34725 ID mismatch: got 0x%02X, expected 0x44\n", id);
        return -1;
    }
    if (i2c_write_reg8(fd, TCS34725_PON, 0x01) < 0) return -1;
    usleep(3000);
    if (i2c_write_reg8(fd, TCS34725_ATIME, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_CONTROL, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_AEN, 0x03) < 0) return -1;
    return 0;
}

static int tcs34725_read(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    if (i2c_read_reg16(fd, TCS34725_CDATAL, c) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_RDATAL, r) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_GDATAL, g) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_BDATAL, b) < 0) return -1;
    return 0;
}

static void calibrate(uint16_t r, uint16_t g, uint16_t b, uint16_t c,
                      float *cr, float *cg, float *cb, float *co) {
    *cr = (float)r / (float)c;
    *cg = (float)g / (float)c;
    *cb = (float)b / (float)c;
    *co = 1.0f;
}

static void cleanup(int fd, struct gpiod_line *led) {
    if (led) gpiod_line_set_value(led, 0);
    if (fd >= 0) {
        i2c_write_reg8(fd, TCS34725_PON, 0x00);
        close(fd);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                TCS34725_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }
    if (gpiod_line_request_output(led, "tcs34725-led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    float cr = 1.0f, cg = 1.0f, cb = 1.0f, co = 1.0f;
    while (running) {
        uint16_t r, g, b, c;
        if (tcs34725_read(fd, &r, &g, &b, &c) < 0) {
            fprintf(stderr, "Read failed; re-initializing sensor...\n");
            i2c_write_reg8(fd, TCS34725_PON, 0x00);
            usleep(3000);
            if (tcs34725_init(fd) < 0) {
                fprintf(stderr, "Re-init failed; exiting.\n");
                break;
            }
            continue;
        }
        calibrate(r, g, b, c, &cr, &cg, &cb, &co);
        float rc = r * cr, gc = g * cg, bc = b * cb, cc = c * co;
        printf("R: %6.2f  G: %6.2f  B: %6.2f  C: %6.2f\n", rc, gc, bc, cc);
        gpiod_line_set_value(led, (rc > RED_THRESHOLD) ? 1 : 0);
        usleep(POLL_MS * 1000);
    }

    cleanup(fd, led);
    gpiod_chip_close(chip);
    return 0;
}

