#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LED_GPIO 18
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define NUM_LEDS 10
#define I2C_BUS 1
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define MAX_LUX 1000.0f
#define MIN_LUX 0.0f
#define MAX_BRIGHTNESS 255
#define MIN_BRIGHTNESS 0
#define SAMPLE_INTERVAL_US 1000000
#define BH1750_CONV_TIME_US 180000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux_out) {
    char cmd = BH1750_CONT_HIGH_RES;
    char buf[2];
    int rc;

    rc = i2cWriteDevice(handle, &cmd, 1);
    if (rc < 0) {
        fprintf(stderr, "BH1750: i2cWriteDevice failed: %d\n", rc);
        return -1;
    }

    gpioDelay(BH1750_CONV_TIME_US);

    rc = i2cReadDevice(handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "BH1750: i2cReadDevice failed: %d\n", rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "BH1750: short read: %d bytes\n", rc);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int map_lux_to_brightness(float lux) {
    if (lux < MIN_LUX) lux = MIN_LUX;
    if (lux > MAX_LUX) lux = MAX_LUX;

    float norm = (lux - MIN_LUX) / (MAX_LUX - MIN_LUX);
    float log_norm = log10f(norm + 1.0f) / log10f(2.0f);
    if (log_norm < 0.0f) log_norm = 0.0f;
    if (log_norm > 1.0f) log_norm = 1.0f;

    int brightness = (int)(log_norm * (MAX_BRIGHTNESS - MIN_BRIGHTNESS) + MIN_BRIGHTNESS);
    if (brightness < 0) brightness = 0;
    if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;
    return brightness;
}

static int set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;

    int duty = (int)(((float)brightness / MAX_BRIGHTNESS) * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    if (gpioPWM(LED_GPIO, duty) < 0) {
        fprintf(stderr, "gpioPWM failed\n");
        return -1;
    }
    return 0;
}

static int update_led_strip(int brightness) {
    int duty = (int)(((float)brightness / MAX_BRIGHTNESS) * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    gpioPWM(LED_GPIO, duty);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    float lux = 0.0f;
    int brightness = 0;

    while (running) {
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success && running) {
            if (read_bh1750(i2c_handle, &lux) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "BH1750 read failed (attempt %d/%d)\n", retries, MAX_RETRIES);
                    gpioDelay(100000);
                }
            }
        }

        if (!success) {
            fprintf(stderr, "BH1750 sensor absent or unresponsive after %d retries\n", MAX_RETRIES);
            brightness = 0;
        } else {
            brightness = map_lux_to_brightness(lux);
        }

        if (set_led_brightness(brightness) < 0) {
            fprintf(stderr, "Failed to set LED brightness\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    set_led_brightness(0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

