#define BH1750_ADDR 0x23
#define BH1750_ONE_TIME_HIGH_RES 0x20
#define I2C_DEV "/dev/i2c-1"
#define SPI_DEV "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define NUM_LEDS 10
#define MIN_LUX 10.0f
#define MAX_LUX 300.0f
#define MAX_BRIGHTNESS 31

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_init(void) {
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C device");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(float *lux) {
    uint8_t cmd = BH1750_ONE_TIME_HIGH_RES;
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("BH1750 write command");
        return -1;
    }
    usleep(120000);
    uint8_t buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        perror("BH1750 read data");
        return -1;
    }
    uint16_t raw = (buf[0] << 8) | buf[1];
    *lux = raw / 1.2f;
    return 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI WR mode");
        goto fail;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI WR bits");
        goto fail;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI WR speed");
        goto fail;
    }
    return 0;
fail:
    close(spi_fd);
    spi_fd = -1;
    return -1;
}

static void apa102_send_frame(uint8_t brightness) {
    uint8_t start[4] = {0x00, 0x00, 0x00, 0xE0};
    uint8_t end[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    uint8_t led[4];
    led[0] = 0xE0 | (brightness & 0x1F);
    led[1] = 0x00;
    led[2] = 0x00;
    led[3] = 0x00;
    uint8_t tx[4 + 4 + NUM_LEDS * 4 + 4];
    memcpy(tx, start, 4);
    memcpy(tx + 4, led, 4);
    memcpy(tx + 8, end, 4);
    for (int i = 0; i < NUM_LEDS; i++) {
        memcpy(tx + 12 + i * 4, led, 4);
    }
    struct spi_ioc_transfer tr = {0};
    tr.tx_buf = (unsigned long)tx;
    tr.len = sizeof(tx);
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI send");
    }
}

static void apa102_off(void) {
    uint8_t start[4] = {0x00, 0x00, 0x00, 0xE0};
    uint8_t end[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    uint8_t tx[4 + 4 + 4];
    memcpy(tx, start, 4);
    memcpy(tx + 4, end, 4);
    memcpy(tx + 8, end, 4);
    struct spi_ioc_transfer tr = {0};
    tr.tx_buf = (unsigned long)tx;
    tr.len = sizeof(tx);
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI off");
    }
}

static int map_lux_to_brightness(float lux) {
    if (lux < MIN_LUX) lux = MIN_LUX;
    if (lux > MAX_LUX) lux = MAX_LUX;
    float ratio = (lux - MIN_LUX) / (MAX_LUX - MIN_LUX);
    return (uint8_t)(ratio * MAX_BRIGHTNESS);
}

