    struct sigaction sa = {0};
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (i2c_init() < 0) return 1;
    if (spi_init() < 0) {
        close(i2c_fd);
        return 1;
    }
    while (running) {
        float lux;
        if (bh1750_read_lux(&lux) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            usleep(100000);
            continue;
        }
        uint8_t brightness = map_lux_to_brightness(lux);
        apa102_send_frame(brightness);
        printf("Lux: %.2f, Brightness: %u\n", lux, brightness);
        usleep(100000);
    }
    apa102_off();
    if (i2c_fd >= 0) close(i2c_fd);
    if (spi_fd >= 0) close(spi_fd);
    return 0;
}

