#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_CMD_OT_HIGH_RES2 0x21
#define BH1750_CONV_TIME_MS 180
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_LEDS 10
#define FADE_DURATION_MS 500
#define LOOP_DELAY_MS 100

static int i2c_handles[2] = {-1, -1};
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux_out) {
    char cmd = BH1750_CMD_OT_HIGH_RES2;
    char buf[2];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write BH1750 command to handle %d\n", handle);
        return -1;
    }

    gpioDelay(BH1750_CONV_TIME_MS * 1000);

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: failed to read BH1750 data from handle %d\n", handle);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void set_apa102_brightness(int spi_handle, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 31) brightness = 31;

    char data[4 + NUM_LEDS * 4 + 4];
    int idx = 0;

    data[idx++] = 0xE0 | (NUM_LEDS & 0x3F);
    data[idx++] = 0x00;
    data[idx++] = 0x00;
    data[idx++] = 0x00;

    for (int i = 0; i < NUM_LEDS; i++) {
        data[idx++] = 0x00;
        data[idx++] = (char)brightness;
        data[idx++] = (char)brightness;
        data[idx++] = (char)brightness;
    }

    data[idx++] = 0xFF;
    data[idx++] = 0xFF;
    data[idx++] = 0xFF;
    data[idx++] = 0xFF;

    if (spiWrite(spi_handle, data, idx) != idx) {
        fprintf(stderr, "Error: SPI write failed\n");
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        set_apa102_brightness(spi_handle, 0);
        spiClose(spi_handle);
        spi_handle = -1;
    }
    for (int i = 0; i < 2; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
            i2c_handles[i] = -1;
        }
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_handles[0] = i2cOpen(I2C_BUS, BH1750_ADDR_LOW, 0);
    if (i2c_handles[0] < 0) {
        fprintf(stderr, "Warning: BH1750 at 0x%02X not found (handle %d)\n", BH1750_ADDR_LOW, i2c_handles[0]);
        i2c_handles[0] = -1;
    }

    i2c_handles[1] = i2cOpen(I2C_BUS, BH1750_ADDR_HIGH, 0);
    if (i2c_handles[1] < 0) {
        fprintf(stderr, "Warning: BH1750 at 0x%02X not found (handle %d)\n", BH1750_ADDR_HIGH, i2c_handles[1]);
        i2c_handles[1] = -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int current_brightness = 0;
    int target_brightness = 0;
    int fade_step = 0;
    int fade_steps = FADE_DURATION_MS / LOOP_DELAY_MS;
    if (fade_steps <= 0) fade_steps = 1;

    while (running) {
        float lux_sum = 0.0f;
        int valid_sensors = 0;

        if (i2c_handles[0] >= 0) {
            float lux;
            if (read_bh1750(i2c_handles[0], &lux) == 0) {
                lux_sum += lux;
                valid_sensors++;
            } else {
                fprintf(stderr, "Warning: sensor 0x%02X read error\n", BH1750_ADDR_LOW);
            }
        }

        if (i2c_handles[1] >= 0) {
            float lux;
            if (read_bh1750(i2c_handles[1], &lux) == 0) {
                lux_sum += lux;
                valid_sensors++;
            } else {
                fprintf(stderr, "Warning: sensor 0x%02X read error\n", BH1750_ADDR_HIGH);
            }
        }

        if (valid_sensors == 0) {
            fprintf(stderr, "Error: no valid BH1750 sensors available\n");
            break;
        }

        float avg_lux = lux_sum / valid_sensors;
        target_brightness = (int)((1.0f - avg_lux / 1000.0f) * 31.0f);
        if (target_brightness < 0) target_brightness = 0;
        if (target_brightness > 31) target_brightness = 31;

        if (target_brightness != current_brightness) {
            fade_step = (target_brightness > current_brightness) ? 1 : -1;
            fade_step = (fade_step > 0) ? fade_step : 0;
            fade_step = (fade_step < 0) ? -fade_step : 0;
        }

        if (fade_step > 0) {
            current_brightness += fade_step;
            if (current_brightness >= target_brightness) current_brightness = target_brightness;
        } else if (fade_step < 0) {
            current_brightness -= fade_step;
            if (current_brightness <= target_brightness) current_brightness = target_brightness;
        }

        set_apa102_brightness(spi_handle, current_brightness);

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

