    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_handles[0] = i2cOpen(I2C_BUS, BH1750_ADDR_LOW, 0);
    if (i2c_handles[0] < 0) {
        fprintf(stderr, "Warning: BH1750 at 0x%02X not found (handle %d)\n", BH1750_ADDR_LOW, i2c_handles[0]);
        i2c_handles[0] = -1;
    }

    i2c_handles[1] = i2cOpen(I2C_BUS, BH1750_ADDR_HIGH, 0);
    if (i2c_handles[1] < 0) {
        fprintf(stderr, "Warning: BH1750 at 0x%02X not found (handle %d)\n", BH1750_ADDR_HIGH, i2c_handles[1]);
        i2c_handles[1] = -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int current_brightness = 0;
    int target_brightness = 0;
    int fade_step = 0;
    int fade_steps = FADE_DURATION_MS / LOOP_DELAY_MS;
    if (fade_steps <= 0) fade_steps = 1;

    while (running) {
        float lux_sum = 0.0f;
        int valid_sensors = 0;

        if (i2c_handles[0] >= 0) {
            float lux;
            if (read_bh1750(i2c_handles[0], &lux) == 0) {
                lux_sum += lux;
                valid_sensors++;
            } else {
                fprintf(stderr, "Warning: sensor 0x%02X read error\n", BH1750_ADDR_LOW);
            }
        }

        if (i2c_handles[1] >= 0) {
            float lux;
            if (read_bh1750(i2c_handles[1], &lux) == 0) {
                lux_sum += lux;
                valid_sensors++;
            } else {
                fprintf(stderr, "Warning: sensor 0x%02X read error\n", BH1750_ADDR_HIGH);
            }
        }

        if (valid_sensors == 0) {
            fprintf(stderr, "Error: no valid BH1750 sensors available\n");
            break;
        }

        float avg_lux = lux_sum / valid_sensors;
        target_brightness = (int)((1.0f - avg_lux / 1000.0f) * 31.0f);
        if (target_brightness < 0) target_brightness = 0;
        if (target_brightness > 31) target_brightness = 31;

        if (target_brightness != current_brightness) {
            fade_step = (target_brightness > current_brightness) ? 1 : -1;
            fade_step = (fade_step > 0) ? fade_step : 0;
            fade_step = (fade_step < 0) ? -fade_step : 0;
        }

        if (fade_step > 0) {
            current_brightness += fade_step;
            if (current_brightness >= target_brightness) current_brightness = target_brightness;
        } else if (fade_step < 0) {
            current_brightness -= fade_step;
            if (current_brightness <= target_brightness) current_brightness = target_brightness;
        }

        set_apa102_brightness(spi_handle, current_brightness);

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

