#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <math.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_DATA_REG 0x04
#define CONFIG_VALUE 0x0000  // Integration time 100ms, gain 1/8
#define MAX_LUX 120000.0
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 18
#define NUM_LEDS 1
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c(void);
int init_gpio(void);
int read_veml7700(uint16_t *raw_lux);
float convert_to_lux(uint16_t raw_lux);
int map_lux_to_brightness(float lux);
void set_led_brightness(int brightness);
void cleanup(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

// Initialize I2C bus and sensor
int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Write configuration register
    uint8_t config_buf[3] = {VEML7700_CONFIG_REG, (CONFIG_VALUE >> 8) & 0xFF, CONFIG_VALUE & 0xFF};
    if (write(i2c_fd, config_buf, 3) != 3) {
        fprintf(stderr, "Failed to write VEML7700 config: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize GPIO for WS2812B bit-banging
int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(line, "ws2812b", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        line = NULL;
        return -1;
    }

    return 0;
}

// Read raw ALS data from VEML7700 with retries
int read_veml7700(uint16_t *raw_lux) {
    uint8_t reg = VEML7700_ALS_DATA_REG;
    uint8_t data[2];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        // Write register address
        if (write(i2c_fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write error (reg select): %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        // Read 2 bytes
        if (read(i2c_fd, data, 2) != 2) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        *raw_lux = (data[0] << 8) | data[1];
        return 0;
    }

    fprintf(stderr, "Failed to read VEML7700 after %d retries\n", RETRY_COUNT);
    return -1;
}

// Convert raw ALS value to lux
float convert_to_lux(uint16_t raw_lux) {
    // For default config: gain = 1/8, integration time = 100ms
    // lux = raw * 0.0036 * (1/gain) * (100ms/integration_time)
    // 0.0036 * 8 * (100/100) = 0.288
    return (float)raw_lux * 0.288f;
}

// Map lux to LED brightness with gamma correction
int map_lux_to_brightness(float lux) {
    if (lux < 0.0f) lux = 0.0f;
    if (lux > MAX_LUX) lux = MAX_LUX;

    float normalized = lux / MAX_LUX;
    float gamma = 1.0f / 2.2f;
    float brightness = 255.0f * powf(normalized, gamma);

    if (brightness < 0.0f) brightness = 0.0f;
    if (brightness > 255.0f) brightness = 255.0f;

    return (int)brightness;
}

// Set LED brightness via bit-banging on GPIO18
void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    // WS2812B timing: 800 kHz, 1.25 us per bit
    // We use a simplified approach: high time proportional to brightness
    // For simplicity, we toggle the pin at a high frequency and vary duty cycle
    // This is a basic implementation; for production, use a dedicated library
    int on_time_us = (brightness * 1000) / 255;  // 0-1000 us
    int off_time_us = 1000 - on_time_us;

    gpiod_line_set_value(line, 1);
    usleep(on_time_us);
    gpiod_line_set_value(line, 0);
    usleep(off_time_us);
}

// Cleanup resources
void cleanup(void) {
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    // Register signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VEML7700 ambient light sensor and WS2812B LED control started.\n");

    while (running) {
        uint16_t raw_lux;
        if (read_veml7700(&raw_lux) == 0) {
            float lux = convert_to_lux(raw_lux);
            int brightness = map_lux_to_brightness(lux);
            set_led_brightness(brightness);
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read sensor, continuing...\n");
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

