#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18
#define CONSUMER "flame_sensor"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static void self_test(struct gpiod_line *led, struct gpiod_line *buzzer) {
    log_event("Running self-test...");

    /* Blink LED twice (500 ms on, 500 ms off) */
    for (int i = 0; i < 2; i++) {
        if (gpiod_line_set_value(led, 1) < 0) {
            log_event("ERROR: failed to set LED high during self-test");
            return;
        }
        usleep(500000);
        if (gpiod_line_set_value(led, 0) < 0) {
            log_event("ERROR: failed to set LED low during self-test");
            return;
        }
        usleep(500000);
    }

    /* Read flame sensor 5 times at 100 ms intervals */
    int low_count = 0;
    for (int i = 0; i < 5; i++) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            log_event("ERROR: failed to read flame sensor during self-test");
            return;
        }
        if (val == 0) low_count++;
        usleep(100000);
    }

    if (low_count == 5) {
        log_event("ERROR: flame sensor fault (sensor reads LOW 5/5 times)");
        /* Rapid LED blink for 5 cycles */
        for (int i = 0; i < 5; i++) {
            gpiod_line_set_value(led, 1);
            usleep(100000);
            gpiod_line_set_value(led, 0);
            usleep(100000);
        }
        /* Buzzer pattern: short-short-long-short, repeated 3 times */
        for (int i = 0; i < 3; i++) {
            gpiod_line_set_value(buzzer, 1);
            usleep(200000);
            gpiod_line_set_value(buzzer, 0);
            usleep(200000);
            gpiod_line_set_value(buzzer, 1);
            usleep(600000);
            gpiod_line_set_value(buzzer, 0);
            usleep(200000);
        }
        log_event("Self-test failed. Exiting.");
        exit(1);
    }
    log_event("Self-test passed.");
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = 1;

    /* Open GPIO chip 0 (Raspberry Pi 5) */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return 1;
    }

    /* Get lines */
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!flame_line || !buzzer_line || !led_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request lines */
    if (gpiod_line_request_input(flame_line, CONSUMER) < 0) {
        perror("gpiod_line_request_input (flame)");
        goto cleanup;
    }
    if (gpiod_line_request_output(buzzer_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (buzzer)");
        goto cleanup;
    }
    if (gpiod_line_request_output(led_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (LED)");
        goto cleanup;
    }

    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    /* Self-test */
    self_test(led_line, buzzer_line);

    log_event("Flame sensor monitoring started.");

    /* Main loop */
    while (running) {
        int flame = gpiod_line_get_value(flame_line);
        if (flame < 0) {
            log_event("ERROR: failed to read flame sensor");
            usleep(500000);
            continue;
        }

        if (flame == 0) {
            /* Flame detected (active-low) */
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                log_event("ERROR: failed to activate buzzer");
            }
            if (gpiod_line_set_value(led_line, 1) < 0) {
                log_event("ERROR: failed to activate LED");
            }
            log_event("Flame detected!");

            /* Wait until flame clears */
            while (running) {
                int v = gpiod_line_get_value(flame_line);
                if (v < 0) {
                    log_event("ERROR: failed to read flame sensor");
                    break;
                }
                if (v == 1) break;
                usleep(50000);
            }

            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                log_event("ERROR: failed to deactivate buzzer");
            }
            if (gpiod_line_set_value(led_line, 0) < 0) {
                log_event("ERROR: failed to deactivate LED");
            }
            log_event("Flame gone.");
        }

        usleep(50000); /* 50 ms poll interval */
    }

    log_event("Shutting down.");
    ret = 0;

cleanup:
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (led_line) gpiod_line_release(led_line);
    if (flame_line) gpiod_line_release(flame_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

