#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define I2C_DEVICE "/dev/i2c-1"
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define BLINK_PERIOD_MS 1000
#define BLINK_DUTY_MS 500

static int i2c_fd = -1;
static int gpio_exported = 0;
static int gpio_fd = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_init(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    uint8_t cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "Failed to write BH1750 command: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    usleep(180000); // Wait for first measurement (max 180ms)
    return 0;
}

static int read_bh1750(uint16_t *raw) {
    uint8_t buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to read BH1750 data: %s\n", strerror(errno));
        return -1;
    }
    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static float convert_to_lux(uint16_t raw) {
    return (float)raw / 1.2f;
}

static void gpio_init(void) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/export");
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open GPIO export: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%d", GPIO_PIN);
    fclose(fp);
    gpio_exported = 1;
    usleep(100000);
}

static void gpio_set_value(int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", GPIO_PIN);
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open GPIO value: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%d", value);
    fclose(fp);
}

static void gpio_unexport(void) {
    if (!gpio_exported) return;
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/unexport");
    FILE *fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "%d", GPIO_PIN);
        fclose(fp);
    }
    gpio_exported = 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (i2c_init() != 0) {
        return 1;
    }

    gpio_init();

    float lux_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;
    int led_state = 0;
    int led_on = 0;
    uint32_t led_start_ms = 0;

    while (running) {
        uint16_t raw;
        if (read_bh1750(&raw) != 0) {
            fprintf(stderr, "I2C read failed, retrying next cycle...\n");
            sleep(1);
            continue;
        }

        float lux = convert_to_lux(raw);
        lux_buffer[buffer_index] = lux;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) buffer_count++;

        float sum = 0.0f;
        for (int i = 0; i < buffer_count; i++) {
            sum += lux_buffer[i];
        }
        float avg_lux = (buffer_count > 0) ? (sum / buffer_count) : 0.0f;

        float rate = 0.5f + (avg_lux / 1000.0f) * 4.5f;
        if (rate > 5.0f) rate = 5.0f;
        if (rate < 0.5f) rate = 0.5f;
        int period_us = (int)(BLINK_PERIOD_MS * 1000.0f / rate);

        uint32_t now_ms = (uint32_t)(clock() * 1000.0f / CLOCKS_PER_SEC);
        if (!led_on || (now_ms - led_start_ms) >= period_us) {
            led_state = !led_state;
            led_on = !led_on;
            if (led_on) {
                gpio_set_value(led_state);
                led_start_ms = now_ms;
            } else {
                gpio_set_value(!led_state);
                led_start_ms = now_ms;
            }
        }

        sleep(1);
    }

    gpio_unexport();
    if (i2c_fd >= 0) close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

