    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line (button)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request LED line as output, initially low */
    ret = gpiod_line_request_output(led_line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (LED)");
        goto cleanup;
    }

    /* Request button line as input with pull-up and falling-edge events */
    ret = gpiod_line_request_falling_edge_events_flags(button_line, CONSUMER,
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_request_falling_edge_events_flags (button)");
        goto cleanup;
    }

    printf("Blinking LED on BCM GPIO17 with 2-second period.\n");
    printf("Press the button on BCM GPIO18 to stop blinking.\n");
    fflush(stdout);

    while (keep_running) {
        /* Toggle LED: 1 second on, 1 second off */
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (LED on)");
            break;
