#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 5
#define DELAY_MS 750

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        gpioWrite(LED_PIN, 1);
        printf("LED ON\n");
        fflush(stdout);
        time_sleep(DELAY_MS / 1000.0);

        if (!keep_running) break;

        gpioWrite(LED_PIN, 0);
        printf("LED OFF\n");
        fflush(stdout);
        time_sleep(DELAY_MS / 1000.0);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

