#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>
#include <time.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18
#define PWM_PERIOD_NS 10000000  /* 10 ms = 100 Hz */
#define PWM_DUTY_MAX 100
#define LOOP_DELAY_MS 100

static volatile sig_atomic_t keep_running = 1;

static void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

static void sleep_ns(long ns) {
    struct timespec ts = { .tv_sec = 0, .tv_nsec = ns };
    while (clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, &ts) == EINTR && keep_running) {
        /* Retry if interrupted by signal */
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int ret = EXIT_FAILURE;

    /* Open GPIO chip 0 (Raspberry Pi 5) */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip 0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get lines */
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request lines as outputs, initial value 0 */
    if (gpiod_line_request_output(red_line, "rgb_led", 0) < 0 ||
        gpiod_line_request_output(green_line, "rgb_led", 0) < 0 ||
        gpiod_line_request_output(blue_line, "rgb_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as outputs: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Seed random number generator */
    srand(time(NULL));

    /* Set up signal handler for clean exit */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("RGB LED control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int red   = rand() % (PWM_DUTY_MAX + 1);
        int green = rand() % (PWM_DUTY_MAX + 1);
        int blue  = rand() % (PWM_DUTY_MAX + 1);

        /* Software PWM for each channel */
        for (int i = 0; i < PWM_PERIOD_NS && keep_running; i += 100) {
            int val = (i < red) ? 1 : 0;
            if (gpiod_line_set_value(red_line, val) < 0) {
                fprintf(stderr, "Failed to set red line: %s\n", strerror(errno));
                goto cleanup;
            }
            val = (i < green) ? 1 : 0;
            if (gpiod_line_set_value(green_line, val) < 0) {
                fprintf(stderr, "Failed to set green line: %s\n", strerror(errno));
                goto cleanup;
            }
            val = (i < blue) ? 1 : 0;
            if (gpiod_line_set_value(blue_line, val) < 0) {
                fprintf(stderr, "Failed to set blue line: %s\n", strerror(errno));
                goto cleanup;
            }
            sleep_ns(100);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (red_line)   gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line)  gpiod_line_release(blue_line);
    if (chip)       gpiod_chip_close(chip);

    printf("Exiting.\n");
    return ret;
}

