        int blue  = rand() % (PWM_DUTY_MAX + 1);

        /* Software PWM for each channel */
        for (int i = 0; i < PWM_PERIOD_NS && keep_running; i += 100) {
            int val = (i < red) ? 1 : 0;
            if (gpiod_line_set_value(red_line, val) < 0) {
                fprintf(stderr, "Failed to set red line: %s\n", strerror(errno));
                goto cleanup;
            }
            val = (i < green) ? 1 : 0;
            if (gpiod_line_set_value(green_line, val) < 0) {
                fprintf(stderr, "Failed to set green line: %s\n", strerror(errno));
                goto cleanup;
            }
            val = (i < blue) ? 1 : 0;
            if (gpiod_line_set_value(blue_line, val) < 0) {
                fprintf(stderr, "Failed to set blue line: %s\n", strerror(errno));
                goto cleanup;
            }
            sleep_ns(100);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (red_line)   gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line)  gpiod_line_release(blue_line);
    if (chip)       gpiod_chip_close(chip);

    printf("Exiting.\n");
    return ret;
}

