#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* LSM303DLHC accelerometer I2C address (SA0 tied to GND) */
#define LSM303_ACCEL_ADDR 0x19

/* LSM303DLHC register addresses */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_CTRL_REG4_A 0x23
#define LSM303_ACCEL_OUT_X_L_A   0x28

/* GPIO pin for impact indicator */
#define IMPACT_GPIO 17

/* Default impact threshold in G */
#define DEFAULT_IMPACT_THRESHOLD 2.0f

/* Sensitivity for +/- 2g full-scale: 16384 LSB/G */
#define ACCEL_SENSITIVITY 16384.0f

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* Function prototypes */
static int init_lsm303(void);
static int read_accel_data(int16_t *x, int16_t *y, int16_t *z);
static float calculate_g_force(int16_t x, int16_t y, int16_t z);
static void log_impact_data(int16_t x, int16_t y, int16_t z, float g_x, float g_y, float g_z);
static void signal_handler(int sig);
static void cleanup(void);

int main(int argc, char *argv[]) {
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;
    int opt;

    /* Parse command-line arguments */
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                impact_threshold = atof(optarg);
                if (impact_threshold <= 0.0f) {
                    fprintf(stderr, "Error: Impact threshold must be positive.\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_g]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO17 as output and ensure it starts LOW */
    gpioSetMode(IMPACT_GPIO, PI_OUTPUT);
    gpioWrite(IMPACT_GPIO, 0);

    /* Initialize LSM303DLHC */
    if (init_lsm303() != 0) {
        fprintf(stderr, "Error: LSM303DLHC initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Threshold: %.2f G\n", impact_threshold);

    /* Main loop */
    while (running) {
        int16_t x, y, z;

        if (read_accel_data(&x, &y, &z) == 0) {
            float g_x = (float)x / ACCEL_SENSITIVITY;
            float g_y = (float)y / ACCEL_SENSITIVITY;
            float g_z = (float)z / ACCEL_SENSITIVITY;
            float g_force = calculate_g_force(x, y, z);

            if (g_force > impact_threshold) {
                printf("Impact detected! G-force: %.2f G\n", g_force);
                log_impact_data(x, y, z, g_x, g_y, g_z);

                /* Pulse GPIO17 HIGH for 50 ms */
                gpioWrite(IMPACT_GPIO, 1);
                gpioDelay(50000); /* 50 ms in microseconds */
                gpioWrite(IMPACT_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Error: Failed to read accelerometer data.\n");
        }

        gpioDelay(100000); /* 100 ms delay (10 Hz polling) */
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* Initialize LSM303DLHC: enable all axes, 100 Hz, 2g full-scale */
static int init_lsm303(void) {
    /* CTRL_REG1_A: 0x27 = 0b00100111 -> ODR=100Hz, all axes enabled */
    if (i2cWriteByteData(i2c_handle, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1_A.\n");
        return -1;
    }

    /* CTRL_REG4_A: 0x00 = +/- 2g full-scale, high-resolution disabled */
    if (i2cWriteByteData(i2c_handle, LSM303_ACCEL_CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG4_A.\n");
        return -1;
    }

    return 0;
}

/* Read accelerometer data using multi-byte read with auto-increment */
static int read_accel_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    /* Multi-byte read starting at OUT_X_L_A with auto-increment (0x80) */
    if (i2cReadI2CBlockData(i2c_handle, LSM303_ACCEL_OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data block.\n");
        return -1;
    }

    /* LSM303DLHC accelerometer data is little-endian */
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

/* Calculate total G-force magnitude */
static float calculate_g_force(int16_t x, int16_t y, int16_t z) {
    float g_x = (float)x / ACCEL_SENSITIVITY;
    float g_y = (float)y / ACCEL_SENSITIVITY;
    float g_z = (float)z / ACCEL_SENSITIVITY;
    return sqrtf(g_x * g_x + g_y * g_y + g_z * g_z);
}

/* Log impact data to file */
static void log_impact_data(int16_t x, int16_t y, int16_t z, float g_x, float g_y, float g_z) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open impact_log.txt for writing.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, X: %d, Y: %d, Z: %d, G_X: %.2f, G_Y: %.2f, G_Z: %.2f\n",
            timestamp, x, y, z, g_x, g_y, g_z);
    fclose(fp);
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(IMPACT_GPIO, 0);
    gpioTerminate();
}

