#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* ADPD188BI I2C 7-bit address */
#define ADPD188BI_ADDR 0x39

/* ADPD188BI register addresses */
#define ADPD188BI_REG_MODE      0x0D
#define ADPD188BI_REG_ALS_LSB   0x64
#define ADPD188BI_REG_ALS_MSB   0x65
#define ADPD188BI_REG_RED_LSB   0x66
#define ADPD188BI_REG_RED_MSB   0x68
#define ADPD188BI_REG_GREEN_LSB 0x6A
#define ADPD188BI_REG_GREEN_MSB 0x6C
#define ADPD188BI_REG_BLUE_LSB  0x6E
#define ADPD188BI_REG_BLUE_MSB  0x70

/* GPIO pin for LED brightness control (hardware PWM) */
#define LED_GPIO 18

/* PWM range (0-255) */
#define PWM_RANGE 255

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 500000

/* Retry delay in microseconds */
#define RETRY_DELAY_US 100000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an ADPD188BI register                        */
/* ------------------------------------------------------------------ */
static int adpd_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from two consecutive registers    */
/* ------------------------------------------------------------------ */
static int adpd_read_16bit(int handle, uint8_t lsb_reg, uint16_t *out)
{
    int lsb = i2cReadByteData(handle, lsb_reg);
    if (lsb < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                lsb_reg, pigpio_error(lsb));
        return -1;
    }
    int msb = i2cReadByteData(handle, lsb_reg + 1);
    if (msb < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                lsb_reg + 1, pigpio_error(msb));
        return -1;
    }
    *out = (uint16_t)((msb << 8) | lsb);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ADPD188BI sensor                                     */
/* ------------------------------------------------------------------ */
static int adpd_init(int handle)
{
    /* Enter normal operation mode (MODE register = 0x01) */
    if (adpd_write_reg(handle, ADPD188BI_REG_MODE, 0x01) != 0) {
        fprintf(stderr, "Failed to set ADPD188BI to normal mode\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read ambient light (ALS) and color (RGB) values                     */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int handle, uint16_t *als, uint16_t *red,
                            uint16_t *green, uint16_t *blue)
{
    if (adpd_read_16bit(handle, ADPD188BI_REG_ALS_LSB, als) != 0)
        return -1;
    if (adpd_read_16bit(handle, ADPD188BI_REG_RED_LSB, red) != 0)
        return -1;
    if (adpd_read_16bit(handle, ADPD188BI_REG_GREEN_LSB, green) != 0)
        return -1;
    if (adpd_read_16bit(handle, ADPD188BI_REG_BLUE_LSB, blue) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Map ALS value (0-65535) to PWM duty cycle (0-255)                   */
/* ------------------------------------------------------------------ */
static int map_als_to_pwm(uint16_t als)
{
    if (als == 0)
        return 0;
    if (als >= 65535)
        return PWM_RANGE;
    return (int)(((float)als / 65535.0f) * PWM_RANGE);
}

/* ------------------------------------------------------------------ */
/* Log a timestamped reading to the CSV file                           */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t als, uint16_t red,
                     uint16_t green, uint16_t blue)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            als, red, green, blue);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Turn off LED */
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADPD188BI address */
    g_i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, ADPD188BI_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (adpd_init(g_i2c_handle) != 0) {
        fprintf(stderr, "ADPD188BI initialization failed (sensor may be absent)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO for hardware PWM */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioPWM(LED_GPIO, 0);

    /* Open CSV log file */
    g_log_file = fopen("color_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open color_log.csv for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,ambient_light,red,green,blue\n");
        fflush(g_log_file);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart lighting system started. Logging to color_log.csv\n");
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t als = 0, red = 0, green = 0, blue = 0;

        if (read_sensor_data(g_i2c_handle, &als, &red, &green, &blue) == 0) {
            int pwm = map_als_to_pwm(als);
            gpioPWM(LED_GPIO, pwm);
            log_data(g_log_file, als, red, green, blue);
        } else {
            fprintf(stderr, "Sensor read error; retrying in 100 ms\n");
            gpioPWM(LED_GPIO, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

