#define FXOS8700_CTRL_REG1  0x2A
#define FXOS8700_OUT_X_MSB  0x01

/* Expected chip ID */
#define FXOS8700_WHO_AM_I_VAL 0xC7

/* ±2g sensitivity: 4096 counts/g */
#define ACCEL_SENSITIVITY 4096.0f

/* Impact threshold: 2g in m/s² */
#define IMPACT_THRESHOLD 19.62f

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 50000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register; abort on failure               */
/* ------------------------------------------------------------------ */
static int fxos_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X val=0x%02X rc=%d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit register; abort on failure              */
/* ------------------------------------------------------------------ */
static int fxos_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X rc=%d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the FXOS8700CQ: standby -> ±2g -> active mode             */
/* ------------------------------------------------------------------ */
static int fxos_init(void)
{
    uint8_t who_am_i = 0;

    /* Verify chip identity */
    if (fxos_read_reg(FXOS8700_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error\n");
        return -1;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Place sensor in standby (clear ACTIVE bit) */
    if (fxos_write_reg(FXOS8700_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Set ±2g range (0x00) */
    if (fxos_write_reg(FXOS8700_XYZ_DATA_CFG, 0x00) != 0)
        return -1;

    /* Activate: ACTIVE bit = 1, ODR = 200 Hz (0x20) */
    if (fxos_write_reg(FXOS8700_CTRL_REG1, 0x20) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration (14-bit left-justified)                */
/* ------------------------------------------------------------------ */
static int fxos_read_accel(float *x, float *y, float *z)
{
    uint8_t buf[6];
    int16_t raw_x, raw_y, raw_z;

    /* Read 6 bytes starting at OUT_X_MSB */
    if (i2cReadI2CBlockData(g_i2c_handle, FXOS8700_OUT_X_MSB,
                            (char *)buf, 6) != 6) {
        fprintf(stderr, "I2C block read failed for acceleration data\n");
        return -1;
    }

    /* 14-bit left-justified: shift right by 2 */
    raw_x = (int16_t)((buf[0] << 8) | buf[1]) >> 2;
    raw_y = (int16_t)((buf[2] << 8) | buf[3]) >> 2;
    raw_z = (int16_t)((buf[4] << 8) | buf[5]) >> 2;

    /* Convert to m/s² using ±2g sensitivity */
    *x = (float)raw_x / ACCEL_SENSITIVITY * 9.81f;
    *y = (float)raw_y / ACCEL_SENSITIVITY * 9.81f;
    *z = (float)raw_z / ACCEL_SENSITIVITY * 9.81f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute acceleration magnitude                                     */
/* ------------------------------------------------------------------ */
static float accel_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
/* Log impact data to file                                             */
/* ------------------------------------------------------------------ */
static void log_impact(float x, float y, float z, float mag)
{
