#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define ADXL345_ADDR        0x53
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32
#define ADXL345_BW_RATE     0x2C

#define LED_GPIO            17
#define SAMPLE_PERIOD_US    100000  /* 100 ms = 10 Hz */
#define ACCEL_THRESHOLD     2.0f
#define FULL_RES_SENSITIVITY 0.0039f /* g/LSB at full resolution, ±2g */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int adxl345_write_reg(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, val);
    if (rc < 0)
        fprintf(stderr, "i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n", reg, val, rc);
    return rc;
}

static int adxl345_read_reg(uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int adxl345_read_block(uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(g_i2c_handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: %d\n", reg, len, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "i2cReadI2CBlockData short read: got %d, expected %u\n", rc, len);
        return -1;
    }
    return 0;
}

static int adxl345_init(void)
{
    uint8_t devid = 0;
    if (adxl345_read_reg(ADXL345_DEVID, &devid) < 0)
        return -1;
    if (devid != 0xE5) {
        fprintf(stderr, "ADXL345 DEVID mismatch: got 0x%02X, expected 0xE5\n", devid);
        return -1;
    }

    /* Standby first so configuration changes take effect */
    if (adxl345_write_reg(ADXL345_POWER_CTL, 0x00) < 0)
        return -1;

    /* Full resolution, ±2g range (0x0B = 0100 0011) */
    if (adxl345_write_reg(ADXL345_DATA_FORMAT, 0x0B) < 0)
        return -1;

    /* Data rate 10 Hz, normal measurement mode (0x0A = 0000 1010) */
    if (adxl345_write_reg(ADXL345_BW_RATE, 0x0A) < 0)
        return -1;

    /* Enable measurement mode */
    if (adxl345_write_reg(ADXL345_POWER_CTL, 0x08) < 0)
        return -1;

    return 0;
}

static int read_acceleration(float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (adxl345_read_block(ADXL345_DATAX0, buf, sizeof(buf)) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * FULL_RES_SENSITIVITY;
    *y = (float)raw_y * FULL_RES_SENSITIVITY;
    *z = (float)raw_z * FULL_RES_SENSITIVITY;
    return 0;
}

static void log_data(float x, float y, float z)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_file, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(g_log_file);
}

static void control_led(float x, float y, float z)
{
    int on = (fabsf(x) > ACCEL_THRESHOLD ||
              fabsf(y) > ACCEL_THRESHOLD ||
              fabsf(z) > ACCEL_THRESHOLD);
    gpioWrite(LED_GPIO, on ? 1 : 0);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioSetMode(LED_GPIO, PI_INPUT);
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=1, addr=0x%02X) failed: %d\n", ADXL345_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, OUTPUT) failed\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    g_log_file = fopen("accel_log.txt", "a");
    if (!g_log_file) {
        perror("fopen(accel_log.txt)");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "# ADXL345 log started\n");
    fflush(g_log_file);

    while (g_running) {
        float x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
            control_led(x, y, z);
        } else {
            fprintf(stderr, "Read error — skipping sample\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

