    /* Data rate 10 Hz, normal measurement mode (0x0A = 0000 1010) */
    if (adxl345_write_reg(ADXL345_BW_RATE, 0x0A) < 0)
        return -1;

    /* Enable measurement mode */
    if (adxl345_write_reg(ADXL345_POWER_CTL, 0x08) < 0)
        return -1;

    return 0;
}

static int read_acceleration(float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (adxl345_read_block(ADXL345_DATAX0, buf, sizeof(buf)) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * FULL_RES_SENSITIVITY;
    *y = (float)raw_y * FULL_RES_SENSITIVITY;
    *z = (float)raw_z * FULL_RES_SENSITIVITY;
    return 0;
}

static void log_data(float x, float y, float z)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_file, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(g_log_file);
}

static void control_led(float x, float y, float z)
{
    int on = (fabsf(x) > ACCEL_THRESHOLD ||
              fabsf(y) > ACCEL_THRESHOLD ||
              fabsf(z) > ACCEL_THRESHOLD);
    gpioWrite(LED_GPIO, on ? 1 : 0);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioSetMode(LED_GPIO, PI_INPUT);
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=1, addr=0x%02X) failed: %d\n", ADXL345_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, OUTPUT) failed\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    g_log_file = fopen("accel_log.txt", "a");
    if (!g_log_file) {
        perror("fopen(accel_log.txt)");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "# ADXL345 log started\n");
    fflush(g_log_file);

    while (g_running) {
        float x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
            control_led(x, y, z);
        } else {
            fprintf(stderr, "Read error — skipping sample\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

