#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM303DLHC I2C addresses */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* Accelerometer registers */
#define CTRL_REG1_A 0x20
#define OUT_X_L_A   0x28

/* Magnetometer registers */
#define MR_REG_M    0x02
#define OUT_X_H_M   0x03

#define I2C_BUS 1
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an I2C register; returns 0 on success, -1 on error. */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, pigpio_error(i2cWriteByteData(handle, reg, value)));
        return -1;
    }
    return 0;
}

/* Read N bytes starting at reg; returns 0 on success, -1 on error. */
static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read block failed (reg 0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "I2C short read: got %d of %u bytes (reg 0x%02X)\n",
                rc, len, reg);
        return -1;
    }
    return 0;
}

/* Initialize accelerometer: 50 Hz, all axes enabled. */
static int init_accelerometer(int handle) {
    if (i2c_write_reg(handle, CTRL_REG1_A, 0x27) < 0)
        return -1;
    return 0;
}

/* Initialize magnetometer: continuous-conversion mode. */
static int init_magnetometer(int handle) {
    if (i2c_write_reg(handle, MR_REG_M, 0x00) < 0)
        return -1;
    return 0;
}

/* Read accelerometer: 6 bytes from OUT_X_L_A with auto-increment. */
static int read_accelerometer(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(handle, OUT_X_L_A, buf, 6) < 0)
        return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* Read magnetometer: 6 bytes from OUT_X_H_M with auto-increment. */
static int read_magnetometer(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(handle, OUT_X_H_M, buf, 6) < 0)
        return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* Calculate tilt-compensated heading in degrees. */
static float calculate_heading(int16_t ax, int16_t ay, int16_t az,
                               int16_t mx, int16_t my, int16_t mz) {
    float axf = (float)ax, ayf = (float)ay, azf = (float)az;
    float mxf = (float)mx, myf = (float)my, mzf = (float)mz;

    float pitch  = atan2f(ayf, azf);
    float roll   = atan2f(-axf, azf);

    float cos_pitch = cosf(pitch);
    float sin_pitch = sinf(pitch);
    float cos_roll  = cosf(roll);
    float sin_roll  = sinf(roll);

    float mx_comp = mxf * cos_roll + mzf * sin_roll;
    float my_comp = mxf * sin_pitch * sin_roll + myf * cos_pitch - mzf * sin_pitch * cos_roll;

    float heading = atan2f(my_comp, mx_comp) * 180.0f / M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

/* Append a CSV row to the log file. */
static int log_data(FILE *fp, float heading, int16_t ax, int16_t ay, int16_t az,
                    int16_t mx, int16_t my, int16_t mz) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%d,%d,%d,%d,%d,%d\n",
            ts, heading, ax, ay, az, mx, my, mz);
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int accel_handle = i2cOpen(I2C_BUS, LSM303_ACCEL_ADDR, 0);
    if (accel_handle < 0) {
        fprintf(stderr, "Failed to open accelerometer I2C (0x%02X): %s\n",
                LSM303_ACCEL_ADDR, pigpio_error(accel_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int mag_handle = i2cOpen(I2C_BUS, LSM303_MAG_ADDR, 0);
    if (mag_handle < 0) {
        fprintf(stderr, "Failed to open magnetometer I2C (0x%02X): %s\n",
                LSM303_MAG_ADDR, pigpio_error(mag_handle));
        i2cClose(accel_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_accelerometer(accel_handle) < 0) {
        fprintf(stderr, "Accelerometer init failed (sensor absent or bus error)\n");
        goto cleanup;
    }
    if (init_magnetometer(mag_handle) < 0) {
        fprintf(stderr, "Magnetometer init failed (sensor absent or bus error)\n");
        goto cleanup;
    }

    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        perror("fopen compass_log.txt");
        goto cleanup;
    }

    /* Write CSV header if file is empty. */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Heading(deg),Accel_X(g),Accel_Y(g),Accel_Z(g),Mag_X(gauss),Mag_Y(gauss),Mag_Z(gauss)\n");
        fflush(fp);
    }

    printf("LSM303DLHC compass logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t ax, ay, az, mx, my, mz;

        if (read_accelerometer(accel_handle, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Accel read error; continuing\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        if (read_magnetometer(mag_handle, &mx, &my, &mz) < 0) {
            fprintf(stderr, "Mag read error; continuing\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float heading = calculate_heading(ax, ay, az, mx, my, mz);

        if (log_data(fp, heading, ax, ay, az, mx, my, mz) < 0) {
            fprintf(stderr, "Log write failed; aborting\n");
            break;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");

    fclose(fp);
    i2cClose(accel_handle);
    i2cClose(mag_handle);
    gpioTerminate();
    return EXIT_SUCCESS;

cleanup:
    i2cClose(accel_handle);
    i2cClose(mag_handle);
    gpioTerminate();
    return EXIT_FAILURE;
}

