#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0b11000000000  /* CPHA=1, CPOL=1, 16-bit words, aux off */

#define REG_X_GYRO  0x04
#define REG_Y_GYRO  0x06
#define REG_Z_GYRO  0x08
#define REG_X_ACCEL 0x0A
#define REG_Y_ACCEL 0x0C
#define REG_Z_ACCEL 0x0E

#define GYRO_SENSITIVITY 0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g/LSB */

#define SAMPLE_PERIOD_US 100000   /* 100 ms */
#define REQ_STALL_US     40       /* >30 us per ADIS16488A timing */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_csv_file   = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_csv_file) {
        fflush(g_csv_file);
        fclose(g_csv_file);
        g_csv_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2], rx[2];
    int  rc;

    tx[0] = (char)(0x80 | (reg & 0x7F)); /* MSB=1 = read */
    tx[1] = 0x00;

    rc = spiXfer(g_spi_handle, tx, rx, 2);
    if (rc != 2) {
        fprintf(stderr, "SPI read request for reg 0x%02X failed (rc=%d)\n", reg, rc);
        return -1;
    }

    gpioDelay(REQ_STALL_US);

    tx[0] = 0x00;
    tx[1] = 0x00;

    rc = spiXfer(g_spi_handle, tx, rx, 2);
    if (rc != 2) {
        fprintf(stderr, "SPI data read for reg 0x%02X failed (rc=%d)\n", reg, rc);
        return -1;
    }

    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int read_gyro(int16_t *gx, int16_t *gy, int16_t *gz)
{
    if (read_register(REG_X_GYRO, gx) < 0) return -1;
    if (read_register(REG_Y_GYRO, gy) < 0) return -1;
    if (read_register(REG_Z_GYRO, gz) < 0) return -1;
    return 0;
}

static int read_accel(int16_t *ax, int16_t *ay, int16_t *az)
{
    if (read_register(REG_X_ACCEL, ax) < 0) return -1;
    if (read_register(REG_Y_ACCEL, ay) < 0) return -1;
    if (read_register(REG_Z_ACCEL, az) < 0) return -1;
    return 0;
}

static void log_sample(float gx, float gy, float gz,
                        float ax, float ay, float az)
{
    struct timespec ts;
    struct tm tm_info;
    char tbuf[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_csv_file, "%s.%03ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            tbuf, ts.tv_nsec / 1000000L, gx, gy, gz, ax, ay, az);
    fflush(g_csv_file);
}

int main(void)
{
    int16_t gx_raw, gy_raw, gz_raw, ax_raw, ay_raw, az_raw;
    float   gx, gy, gz, ax, ay, az;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_csv_file = fopen("imu_data.csv", "a");
    if (!g_csv_file) {
        fprintf(stderr, "Failed to open imu_data.csv\n");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(g_csv_file, 0, SEEK_END);
    if (ftell(g_csv_file) == 0)
        fprintf(g_csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    atexit(cleanup);

    while (g_running) {
        if (read_gyro(&gx_raw, &gy_raw, &gz_raw) < 0) {
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        if (read_accel(&ax_raw, &ay_raw, &az_raw) < 0) {
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        gx = (float)gx_raw * GYRO_SENSITIVITY;
        gy = (float)gy_raw * GYRO_SENSITIVITY;
        gz = (float)gz_raw * GYRO_SENSITIVITY;
        ax = (float)ax_raw * ACCEL_SENSITIVITY;
        ay = (float)ay_raw * ACCEL_SENSITIVITY;
        az = (float)az_raw * ACCEL_SENSITIVITY;

        log_sample(gx, gy, gz, ax, ay, az);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    return EXIT_SUCCESS;
}

