#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "gpiochip0"
#define CS_GPIO_LINE    8
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define SAMPLE_PERIOD_MS 100

#define REG_XGYRO_OUT  0x04
#define REG_YGYRO_OUT  0x06
#define REG_ZGYRO_OUT  0x08
#define REG_XACCL_OUT  0x0A
#define REG_YACCL_OUT  0x0C
#define REG_ZACCL_OUT  0x0E

#define GYRO_SCALE 0.02f
#define ACCL_SCALE 0.00025f

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_register(int fd, struct gpiod_line *cs, uint8_t reg, int16_t *out) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    if (gpiod_line_set_value(cs, 0) < 0) {
        fprintf(stderr, "CS low failed: %s\n", strerror(errno));
        return -1;
    }

    if (spi_transfer(fd, tx, rx, 2) < 0) {
        gpiod_line_set_value(cs, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs, 1) < 0) {
        fprintf(stderr, "CS high failed: %s\n", strerror(errno));
        return -1;
    }

    *out = (int16_t)((rx[1] << 8) | rx[0]);
    return 0;
}

static int read_gyro(int fd, struct gpiod_line *cs, float *x, float *y, float *z) {
    int16_t rx, ry, rz;
    if (read_register(fd, cs, REG_XGYRO_OUT, &rx) < 0) return -1;
    if (read_register(fd, cs, REG_YGYRO_OUT, &ry) < 0) return -1;
    if (read_register(fd, cs, REG_ZGYRO_OUT, &rz) < 0) return -1;
    *x = rx * GYRO_SCALE;
    *y = ry * GYRO_SCALE;
    *z = rz * GYRO_SCALE;
    return 0;
}

static int read_accel(int fd, struct gpiod_line *cs, float *x, float *y, float *z) {
    int16_t rx, ry, rz;
    if (read_register(fd, cs, REG_XACCL_OUT, &rx) < 0) return -1;
    if (read_register(fd, cs, REG_YACCL_OUT, &ry) < 0) return -1;
    if (read_register(fd, cs, REG_ZACCL_OUT, &rz) < 0) return -1;
    *x = rx * ACCL_SCALE;
    *y = ry * ACCL_SCALE;
    *z = rz * ACCL_SCALE;
    return 0;
}

int main(void) {
    int fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs = NULL;
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        return 1;
    }

    cs = gpiod_chip_get_line(chip, CS_GPIO_LINE);
    if (!cs) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", CS_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(cs, "adis16448-cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SPI_DEVICE, strerror(errno));
        gpiod_line_release(cs);
        gpiod_chip_close(chip);
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("ADIS16448 IMU Reader (spidev + libgpiod CS)\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        float gx, gy, gz, ax, ay, az;
        int ok = 1;

        if (read_gyro(fd, cs, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Gyro read error\n");
            ok = 0;
        }
        if (read_accel(fd, cs, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Accel read error\n");
            ok = 0;
        }

        if (ok) {
            printf("Gyro: X=%.2f Y=%.2f Z=%.2f dps  |  Accel: X=%.4f Y=%.4f Z=%.4f g\n",
                   gx, gy, gz, ax, ay, az);
        }

        struct timespec ts = { 0, SAMPLE_PERIOD_MS * 1000000L };
        nanosleep(&ts, NULL);
    }

cleanup:
    if (fd >= 0) close(fd);
    if (cs) gpiod_line_release(cs);
    if (chip) gpiod_chip_close(chip);
    return 0;
}

