#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16448 Register Addresses */
#define X_GYRO_OUT  0x04
#define Y_GYRO_OUT  0x06
#define Z_GYRO_OUT  0x08
#define X_ACCL_OUT  0x0A
#define Y_ACCL_OUT  0x0C
#define Z_ACCL_OUT  0x0E

/* Scaling factors (from ADIS16448 datasheet) */
#define GYRO_SCALE  0.05f   /* deg/sec/LSB */
#define ACCL_SCALE  0.00025f /* g/LSB */

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 /* 1 MHz */
#define SPI_MODE    0
#define SAMPLE_US   100000  /* 100 ms */

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * ADIS16448 SPI read requires two 16-bit transfers:
 *   1. Send (reg_addr | 0x8000) to select the register.
 *   2. Stall >= 40 us, then send 0x0000 to clock out the data.
 * Returns 0 on success, -1 on error.
 */
static int adis_read_reg16(int handle, uint8_t reg, int16_t *out) {
    char tx[4] = {0};
    char rx[4] = {0};

    /* First transfer: send read command */
    tx[0] = (reg | 0x80) << 6; /* bit 15 set for read */
    tx[1] = 0;
    tx[2] = 0;
    tx[3] = 0;

    if (spiXfer(handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI read command transfer failed for reg 0x%02X\n", reg);
        return -1;
    }

    /* Stall >= 40 us (ADIS16448 datasheet) */
    gpioDelay(40);

    /* Second transfer: dummy 0x0000 to clock out data */
    tx[0] = 0x00;
    tx[1] = 0x00;
    tx[2] = 0x00;
    tx[3] = 0x00;

    if (spiXfer(handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI data transfer failed for reg 0x%02X\n", reg);
        return -1;
    }

    *out = (int16_t)(((uint16_t)(uint8_t)rx[2] << 8) | (uint8_t)rx[3]);
    return 0;
}

static int read_gyro(int16_t *gx, int16_t *gy, int16_t *gz) {
    if (adis_read_reg16(spi_handle, X_GYRO_OUT, gx) != 0) return -1;
    if (adis_read_reg16(spi_handle, Y_GYRO_OUT, gy) != 0) return -1;
    if (adis_read_reg16(spi_handle, Z_GYRO_OUT, gz) != 0) return -1;
    return 0;
}

static int read_accl(int16_t *ax, int16_t *ay, int16_t *az) {
    if (adis_read_reg16(spi_handle, X_ACCL_OUT, ax) != 0) return -1;
    if (adis_read_reg16(spi_handle, Y_ACCL_OUT, ay) != 0) return -1;
    if (adis_read_reg16(spi_handle, Z_ACCL_OUT, az) != 0) return -1;
    return 0;
}

static void print_data(float gx, float gy, float gz, float ax, float ay, float az) {
    printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s\n", gx, gy, gz);
    printf("Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n", ax, ay, az);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 0) | (1 << 1));
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return 1;
    }

    printf("ADIS16448 IMU reader started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t gx_raw, gy_raw, gz_raw, ax_raw, ay_raw, az_raw;

        if (read_gyro(&gx_raw, &gy_raw, &gz_raw) != 0) {
            fprintf(stderr, "Gyro read error\n");
        } else if (read_accl(&ax_raw, &ay_raw, &az_raw) != 0) {
            fprintf(stderr, "Accel read error\n");
        } else {
            float gx = (float)gx_raw * GYRO_SCALE;
            float gy = (float)gy_raw * GYRO_SCALE;
            float gz = (float)gz_raw * GYRO_SCALE;
            float ax = (float)ax_raw * ACCL_SCALE;
            float ay = (float)ay_raw * ACCL_SCALE;
            float az = (float)az_raw * ACCL_SCALE;
            print_data(gx, gy, gz, ax, ay, az);
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return 0;
}

