#define MPU6886_GYRO_CONFIG  0x1B
#define MPU6886_ACCEL_XOUT_H 0x3B
#define MPU6886_GYRO_XOUT_H  0x43

#define WHO_AM_I_EXPECTED 0x86
#define I2C_BUS "/dev/i2c-1"
#define SAMPLE_DELAY_US 50000
#define MAX_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        return -1;
    }
    return 0;
}

static int mpu6886_init(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, MPU6886_WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). Sensor not present?\n",
                who_am_i, WHO_AM_I_EXPECTED);
        return -1;
    }

    /* Wake up the MPU-6886 (clear SLEEP bit) */
    if (i2c_write_reg8(fd, MPU6886_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000); /* Allow time for oscillator to stabilize */

    /* Set accelerometer range to +/- 2g (AFS_SEL = 0) */
    if (i2c_write_reg8(fd, MPU6886_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write ACCEL_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    /* Set gyroscope range to +/- 250 dps (FS_SEL = 0) */
    if (i2c_write_reg8(fd, MPU6886_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_sensor_data(int fd, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[14];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read_burst(fd, MPU6886_ACCEL_XOUT_H, buf, sizeof(buf)) == 0) {
            *ax = (int16_t)((buf[0] << 8) | buf[1]);
            *ay = (int16_t)((buf[2] << 8) | buf[3]);
            *az = (int16_t)((buf[4] << 8) | buf[5]);
            *gx = (int16_t)((buf[8] << 8) | buf[9]);
            *gy = (int16_t)((buf[10] << 8) | buf[11]);
            *gz = (int16_t)((buf[12] << 8) | buf[13]);
            return 0;
        }
        retries++;
        usleep(1000);
    }

    fprintf(stderr, "Error: Failed to read sensor data after %d retries: %s\n",
            MAX_RETRIES, strerror(errno));
    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Error: Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to acquire I2C bus access: %s\n", strerror(errno));
        close(g_fd);
        return 1;
    }

    if (mpu6886_init(g_fd) < 0) {
        fprintf(stderr, "Error: MPU-6886 initialization failed.\n");
        close(g_fd);
        return 1;
    }

    printf("MPU-6886 initialized successfully. Reading data every 50 ms...\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (read_sensor_data(g_fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d, Y=%6d, Z=%6d  |  Gyro: X=%6d, Y=%6d, Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, continuing...\n");
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    if (g_fd >= 0) {
        close(g_fd);
    }
    return 0;
}

