#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXL345 I2C address (ALT ADDRESS pin tied to GND) */
#define ADXL345_ADDRESS 0x53

/* ADXL345 register addresses */
#define ADXL345_DEVID       0x00
#define ADXL345_BW_RATE     0x2C
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATAX0      0x32
#define ADXL345_DATAY0      0x34
#define ADXL345_DATAZ0      0x36

/* Expected device ID */
#define ADXL345_DEVID_VALUE 0xE5

/* Full-resolution mode, +/- 2g range (scale factor = 256 LSB/g) */
#define ADXL345_RANGE_2G    0x00
#define ADXL345_BW_100HZ    0x0A

/* Impact threshold in g */
#define IMPACT_THRESHOLD_G  2.5f

/* LED GPIO pin */
#define LED_GPIO            17

/* Polling interval in microseconds */
#define POLL_INTERVAL_US    10000

/* LED on duration in microseconds */
#define LED_ON_DURATION_US  500000

/* Log file path */
#define LOG_FILE_PATH       "impact_log.txt"

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADXL345 register                              */
/* ------------------------------------------------------------------ */
static int adxl345_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ADXL345 register                              */
/* ------------------------------------------------------------------ */
static int adxl345_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ADXL345: verify device ID, set range, set data rate  */
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    /* Verify device identity */
    if (adxl345_read_reg(handle, ADXL345_DEVID, &devid) != 0) {
        fprintf(stderr, "Cannot read DEVID — sensor absent or bus error.\n");
        return -1;
    }
    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "Unexpected DEVID: 0x%02X (expected 0x%02X).\n",
                devid, ADXL345_DEVID_VALUE);
        return -1;
    }

    /* Standby mode before configuring */
    if (adxl345_write_reg(handle, ADXL345_POWER_CTL, 0x00) != 0)
        return -1;

    /* Full-resolution, +/- 2g range */
    if (adxl345_write_reg(handle, 0x28, ADXL345_RANGE_2G) != 0)
        return -1;

    /* Data rate = 100 Hz */
    if (adxl345_write_reg(handle, ADXL345_BW_RATE, ADXL345_BW_100HZ) != 0)
        return -1;

    /* Measurement mode */
    if (adxl345_write_reg(handle, ADXL345_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (X, Y, Z)                         */
/* ------------------------------------------------------------------ */
static int adxl345_read_accel(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];

    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, buf, 6) != 6) {
        fprintf(stderr, "I2C block read failed: %s\n", pigpio_error(0));
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    *y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    *z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute magnitude in g (full-resolution, +/- 2g → 256 LSB/g)       */
/* ------------------------------------------------------------------ */
static float accel_magnitude_g(int16_t x, int16_t y, int16_t z)
{
    float fx = (float)x / 256.0f;
    float fy = (float)y / 256.0f;
    float fz = (float)z / 256.0f;
    return sqrtf(fx * fx + fy * fy + fz * fz);
}

/* ------------------------------------------------------------------ */
/* Log an impact event to file and turn on the LED                     */
/* ------------------------------------------------------------------ */
static void log_impact(float mag, int16_t x, int16_t y, int16_t z)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    fprintf(g_log_file, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f g\n",
            ts, x, y, z, mag);
    fflush(g_log_file);

    gpioWrite(LED_GPIO, 1);
    gpioDelay(LED_ON_DURATION_US);
    gpioWrite(LED_GPIO, 0);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — release all resources                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t x, y, z;
    float mag;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADXL345 address */
    g_i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (adxl345_init(g_i2c_handle) != 0) {
        fprintf(stderr, "ADXL345 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE_PATH, "a");
    if (g_log_file == NULL) {
        perror("fopen log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL345 impact detector running. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        if (adxl345_read_accel(g_i2c_handle, &x, &y, &z) == 0) {
            mag = accel_magnitude_g(x, y, z);
            if (mag > IMPACT_THRESHOLD_G) {
                printf("Impact detected! Magnitude: %.2f g\n", mag);
                log_impact(mag, x, y, z);
            }
        } else {
            fprintf(stderr, "Read error — continuing.\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

