#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ICM-20602 I2C address (AD0 tied to GND) */
#define ICM20602_ADDR 0x68

/* ICM-20602 register addresses */
#define REG_WHO_AM_I      0x75
#define REG_PWR_MGMT_1    0x6B
#define REG_ACCEL_CONFIG  0x1C
#define REG_GYRO_CONFIG   0x1B
#define REG_ACCEL_XOUT_H  0x3B
#define REG_GYRO_XOUT_H   0x43

/* Expected WHO_AM_I value for ICM-20602 */
#define ICM20602_WHO_AM_I 0x12

/* Scaling factors for default ranges (+/-2g, +/-250 dps) */
#define ACCEL_SCALE 16384.0f
#define GYRO_SCALE  131.0f

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an I2C register; returns 0 on success, -1 on error */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "Error: I2C write failed (reg=0x%02X, val=0x%02X)\n", reg, value);
        return -1;
    }
    return 0;
}

/* Read a block of bytes from an I2C register; returns 0 on success, -1 on error */
