#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I 0x0D
#define WHO_AM_I_VAL 0x1A
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define LED_GPIO_LINE 17
#define ACCEL_THRESHOLD 2.0f
#define G_PER_COUNT 0.0009765625f
#define POLL_DELAY_MS 100
#define LED_ON_MS 500

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MMA8451Q_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(i2c_fd, WHO_AM_I, &who_am_i) < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (i2c_write_reg8(i2c_fd, CTRL_REG1, 0x01) < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(led_line, "mma8451q-impact", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        led_line = NULL;
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static void log_impact(float x, float y, float z) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open impact_log.txt: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, X: %.2f g, Y: %.2f g, Z: %.2f g\n", ts, x, y, z);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }
    if (init_i2c() < 0) {
        return 1;
    }
    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }
    printf("MMA8451Q impact detection started. Press Ctrl+C to exit.\n");
    while (running) {
        int16_t raw_x, raw_y, raw_z;
        if (i2c_read_reg16(i2c_fd, OUT_X_MSB, &raw_x) < 0 ||
            i2c_read_reg16(i2c_fd, OUT_Y_MSB, &raw_y) < 0 ||
            i2c_read_reg16(i2c_fd, OUT_Z_MSB, &raw_z) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }
        float x = (float)raw_x * G_PER_COUNT;
        float y = (float)raw_y * G_PER_COUNT;
        float z = (float)raw_z * G_PER_COUNT;
        float mag = sqrtf(x * x + y * y + z * z);
        if (mag > ACCEL_THRESHOLD) {
            printf("Impact detected! Magnitude: %.2f g\n", mag);
            log_impact(x, y, z);
            gpiod_line_set_value(led_line, 1);
            usleep(LED_ON_MS * 1000);
            gpiod_line_set_value(led_line, 0);
        }
        usleep(POLL_DELAY_MS * 1000);
    }
    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

