    uint8_t who_am_i = 0;
    if (i2c_read_reg8(i2c_fd, WHO_AM_I, &who_am_i) < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (i2c_write_reg8(i2c_fd, CTRL_REG1, 0x01) < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(led_line, "mma8451q-impact", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        led_line = NULL;
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static void log_impact(float x, float y, float z) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open impact_log.txt: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, X: %.2f g, Y: %.2f g, Z: %.2f g\n", ts, x, y, z);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }
    if (init_i2c() < 0) {
        return 1;
    }
    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }
    printf("MMA8451Q impact detection started. Press Ctrl+C to exit.\n");
    while (running) {
        int16_t raw_x, raw_y, raw_z;
        if (i2c_read_reg16(i2c_fd, OUT_X_MSB, &raw_x) < 0 ||
            i2c_read_reg16(i2c_fd, OUT_Y_MSB, &raw_y) < 0 ||
            i2c_read_reg16(i2c_fd, OUT_Z_MSB, &raw_z) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }
        float x = (float)raw_x * G_PER_COUNT;
        float y = (float)raw_y * G_PER_COUNT;
        float z = (float)raw_z * G_PER_COUNT;
        float mag = sqrtf(x * x + y * y + z * z);
        if (mag > ACCEL_THRESHOLD) {
            printf("Impact detected! Magnitude: %.2f g\n", mag);
            log_impact(x, y, z);
            gpiod_line_set_value(led_line, 1);
            usleep(LED_ON_MS * 1000);
            gpiod_line_set_value(led_line, 0);
        }
        usleep(POLL_DELAY_MS * 1000);
    }
    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

