#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TMAG5273_ADDR 0x35
#define I2C_BUS "/dev/i2c-1"
#define CSV_FILE "magnetic_field_log.csv"

#define REG_X_RESULT 0x10
#define REG_Y_RESULT 0x11
#define REG_Z_RESULT 0x12

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *csv_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg, int16_t *out) {
    if (i2c_write_reg8(fd, reg) < 0) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d,%d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush CSV failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", TMAG5273_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    csv_fp = fopen(CSV_FILE, "a");
    if (!csv_fp) {
        fprintf(stderr, "fopen %s failed: %s\n", CSV_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    fseek(csv_fp, 0, SEEK_END);
    long file_size = ftell(csv_fp);
    if (file_size == 0) {
        if (fprintf(csv_fp, "Timestamp,X,Y,Z\n") < 0) {
            fprintf(stderr, "CSV header write failed: %s\n", strerror(errno));
            fclose(csv_fp);
            close(i2c_fd);
            return 1;
        }
        fflush(csv_fp);
    }

    printf("TMAG5273 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t x, y, z;
        if (i2c_read_reg16_le(i2c_fd, REG_X_RESULT, &x) < 0 ||
            i2c_read_reg16_le(i2c_fd, REG_Y_RESULT, &y) < 0 ||
            i2c_read_reg16_le(i2c_fd, REG_Z_RESULT, &z) < 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
        } else {
            if (log_data(csv_fp, x, y, z) < 0) {
                fprintf(stderr, "CSV log error, continuing...\n");
            }
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    if (csv_fp) fclose(csv_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

