#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <poll.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADXL345_ADDR   0x53
#define ADXL345_DEVID  0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_INT_ENABLE 0x2E
#define ADXL345_INT_MAP    0x2F
#define ADXL345_INT_SOURCE 0x30
#define ADXL345_DATAX0     0x32
#define ADXL345_THRESH_FF  0x0A
#define ADXL345_TIME_FF    0x20

#define GPIO_CHIP       "gpiochip0"
#define GPIO_LINE       17
#define LOG_FILE        "freefall_log.csv"

#define DEVID_EXPECTED  0xE5
#define FREEFALL_BIT    0x04
#define POLL_TIMEOUT_MS 100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int adxl345_init(int fd) {
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, ADXL345_DEVID, &devid) < 0) return -1;
    if (devid != DEVID_EXPECTED) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n", devid, DEVID_EXPECTED);
        return -1;
    }

    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x00) < 0) return -1; /* standby */
    usleep(10000);

    if (i2c_write_reg8(fd, ADXL345_THRESH_FF, 0x14) < 0) return -1; /* ~300 mg */
    if (i2c_write_reg8(fd, ADXL345_TIME_FF, 0x0A) < 0) return -1;  /* ~100 ms */
    if (i2c_write_reg8(fd, ADXL345_INT_MAP, 0x00) < 0) return -1;  /* INT1 */
    if (i2c_write_reg8(fd, ADXL345_INT_ENABLE, 0x04) < 0) return -1; /* enable freefall */
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x08) < 0) return -1; /* measurement */

    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, ADXL345_DATAX0, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld,%d,%d,%d\n", tbuf, ts.tv_nsec / 1000000, x, y, z);
    fflush(fp);
}

static void cleanup(void) {
    if (g_i2c_fd >= 0) {
        i2c_write_reg8(g_i2c_fd, ADXL345_POWER_CTL, 0x00);
        i2c_write_reg8(g_i2c_fd, ADXL345_INT_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", ADXL345_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (adxl345_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(g_i2c_fd);
        return 1;
    }
    if (gpiod_line_request_falling_edge_events(line, "adxl345_ff") < 0) {
        fprintf(stderr, "Cannot request falling-edge events on GPIO%d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(g_i2c_fd);
        return 1;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(g_i2c_fd);
        return 1;
    }
    fprintf(g_log, "Timestamp,X,Y,Z\n");
    fflush(g_log);

    printf("Freefall detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        struct pollfd pfd = { .fd = gpiod_line_event_get_fd(line), .events = POLLIN };
        int pr = poll(&pfd, 1, POLL_TIMEOUT_MS);
        if (pr < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "poll error: %s\n", strerror(errno));
            break;
        }
        if (pr == 0) continue;

        struct gpiod_line_event ev;
        if (gpiod_line_event_read(line, &ev) < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "gpiod_line_event_read error: %s\n", strerror(errno));
            break;
        }

        uint8_t intsrc = 0;
        if (i2c_read_reg8(g_i2c_fd, ADXL345_INT_SOURCE, &intsrc) < 0) {
            fprintf(stderr, "Failed to read INT_SOURCE\n");
            continue;
        }
        if (!(intsrc & FREEFALL_BIT)) continue;

        int16_t x, y, z;
        if (read_accel(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue;
        }
        log_data(g_log, x, y, z);
    }

    cleanup();
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    printf("Exiting.\n");
    return 0;
}

