#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6A
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0x6A
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

#define ACCEL_SCALE 0.000061f
#define GYRO_SCALE 0.00875f
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define FREEFALL_DURATION 1.0f
#define SAMPLE_RATE 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE)

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} imu_data_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(uint8_t reg, uint8_t val) {
    char buf[2] = {(char)reg, (char)val};
    return i2cWriteDevice(i2c_handle, buf, 2);
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) return -1;
    return i2cReadDevice(i2c_handle, (char *)buf, len);
}

static int init_lsm6dsr(void) {
    uint8_t who_am_i = 0;
    if (i2c_read_block(WHO_AM_I, &who_am_i, 1) != 1) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (0x%02X, expected 0x%02X). Sensor absent?\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_byte(CTRL1_XL, 0x80) != 0) return -1;
    if (i2c_write_byte(CTRL2_G, 0x80) != 0) return -1;
    return 0;
}

static int read_imu_data(imu_data_t *data) {
    uint8_t buf[6];
    if (i2c_read_block(OUTX_L_G, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read gyroscope data.\n");
        return -1;
    }
    int16_t gyro_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t gyro_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t gyro_z = (int16_t)((buf[5] << 8) | buf[4]);

    if (i2c_read_block(OUTX_L_XL, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data.\n");
        return -1;
    }
    int16_t accel_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t accel_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t accel_z = (int16_t)((buf[5] << 8) | buf[4]);

    data->gyro_x = gyro_x * GYRO_SCALE;
    data->gyro_y = gyro_y * GYRO_SCALE;
    data->gyro_z = gyro_z * GYRO_SCALE;
    data->accel_x = accel_x * ACCEL_SCALE;
    data->accel_y = accel_y * ACCEL_SCALE;
    data->accel_z = accel_z * ACCEL_SCALE;
    return 0;
}

static void log_data(const imu_data_t *data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s.%03ld,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            timestamp, ts.tv_nsec / 1000000,
            data->accel_x, data->accel_y, data->accel_z,
            data->gyro_x, data->gyro_y, data->gyro_z);
    fflush(log_file);
}

static void detect_fall(const imu_data_t *data) {
    static int in_freefall = 0;
    static double freefall_start_time = 0.0;
    static double impact_time = 0.0;

    float magnitude = sqrtf(data->accel_x * data->accel_x +
                            data->accel_y * data->accel_y +
                            data->accel_z * data->accel_z);

    if (magnitude < FREEFALL_THRESHOLD) {
        if (!in_freefall) {
            in_freefall = 1;
            freefall_start_time = time_time();
        }
    } else {
        if (in_freefall) {
            in_freefall = 0;
            impact_time = 0.0;
        }
    }

    if (in_freefall) {
        double elapsed = time_time() - freefall_start_time;
        if (elapsed >= FREEFALL_DURATION) {
            printf("Potential fall detected!\n");
            impact_time = time_time();
        }
    }

    if (magnitude > IMPACT_THRESHOLD && impact_time > 0.0) {
        double elapsed = time_time() - impact_time;
        if (elapsed < 0.5) {
            printf("Impact detected!\n");
        }
        impact_time = 0.0;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lsm6dsr() != 0) {
        fprintf(stderr, "Error: LSM6DSR initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LSM6DSR fall detection started. Press Ctrl+C to exit.\n");

    while (running) {
        imu_data_t data;
        if (read_imu_data(&data) == 0) {
            log_data(&data);
            detect_fall(&data);
        } else {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

