#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16266 Register Map */
#define ADIS16266_REG_X_GYRO_OUT 0x14
#define ADIS16266_REG_WHO_AM_I   0x00

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    3        /* CPOL=1, CPHA=1 */
#define SPI_BITS    8

/* Scaling factor: 0.0305 deg/sec/LSB (from datasheet) */
#define GYRO_SCALE 0.0305f

/* Expected WHO_AM_I value (from ADIS16266 datasheet) */
#define ADIS16266_WHO_AM_I_VAL 0x3F5A

/* Global variables for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Function to read a 16-bit register from the ADIS16266 */
static int read_register(uint8_t reg, int16_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    /* Send read command: register address with bit 7 set */
    tx_buf[0] = (char)(reg | 0x80);
    tx_buf[1] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
