#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* L3G4200D I2C address (SA0 tied high on GY-50) */
#define L3G4200D_ADDR 0x69

/* L3G4200D register addresses */
#define WHO_AM_I     0x0F
#define CTRL_REG1    0x20
#define CTRL_REG4    0x23
#define OUT_X_L      0x28

/* Expected device ID */
#define WHO_AM_I_VAL 0xD3

/* Sensitivity scale factor for +/-250 dps: 8.75 mdps/LSB */
#define GYRO_SENSITIVITY 8.75f

/* Global state for signal handler */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a byte to a register with retry */
static int write_reg_retry(int handle, uint8_t reg, uint8_t value, int retries) {
    for (int i = 0; i < retries; i++) {
        if (i2cWriteByteData(handle, reg, value) == 0) {
            return 0;
        }
        gpioDelay(1000); /* 1 ms backoff */
    }
    return -1;
}

/* Read a byte from a register with retry */
static int read_reg_retry(int handle, uint8_t reg, uint8_t *value, int retries) {
    for (int i = 0; i < retries; i++) {
        int result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0;
        }
        gpioDelay(1000);
    }
    return -1;
}

/* Initialize the L3G4200D gyroscope */
static int init_gyroscope(int handle) {
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (read_reg_retry(handle, WHO_AM_I, &who_am_i, 3) != 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register after retries.\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). Sensor not present?\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: 0x0F = normal mode, all axes enabled, 100 Hz ODR */
    if (write_reg_retry(handle, CTRL_REG1, 0x0F, 3) != 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1 after retries.\n");
        return -1;
    }

    /* CTRL_REG4: 0x00 = +/-250 dps full-scale range */
    if (write_reg_retry(handle, CTRL_REG4, 0x00, 3) != 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG4 after retries.\n");
        return -1;
    }

    return 0;
}

/* Read raw gyroscope data (6 bytes starting at OUT_X_L) */
static int read_gyro_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(handle, OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error: Failed to read 6 bytes of gyro data.\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

    return 0;
}

/* Convert raw data to degrees per second */
static void convert_to_dps(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                           float *x, float *y, float *z) {
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;
}

/* Log data to CSV file with nanosecond timestamp */
static void log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%09ld,%.3f,%.3f,%.3f\n", timestamp, ts.tv_nsec, x, y, z);
    fflush(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at L3G4200D address */
    i2c_handle = i2cOpen(1, L3G4200D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X.\n", L3G4200D_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize gyroscope */
    if (init_gyroscope(i2c_handle) != 0) {
        fprintf(stderr, "Error: Gyroscope initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open gyro_log.csv: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gyroscope data logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (running) {
        int16_t raw_x, raw_y, raw_z;
        float x_dps, y_dps, z_dps;

        if (read_gyro_data(i2c_handle, &raw_x, &raw_y, &raw_z) == 0) {
            convert_to_dps(raw_x, raw_y, raw_z, &x_dps, &y_dps, &z_dps);
            log_data(log_file, x_dps, y_dps, z_dps);
        } else {
            fprintf(stderr, "Warning: Failed to read gyro data, skipping sample.\n");
        }

        gpioDelay(10000); /* 10 ms delay (100 Hz sampling) */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

