    while (program_running) {
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);

        if (sensor_value == PI_BAD_GPIO) {
            log_event("ERROR: gpioRead returned PI_BAD_GPIO");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* KY-026 DO is active-LOW: 0 = flame detected, 1 = no flame */
        const char *flame_status = (sensor_value == 0) ? "YES" : "NO";
        char log_message[128];
        snprintf(log_message, sizeof(log_message),
                 "Flame detected: %s", flame_status);

