#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x53
#define REG_X_LSB      0x28
#define REG_X_MSB      0x29
#define REG_Y_LSB      0x2A
#define REG_Y_MSB      0x2B
#define REG_Z_LSB      0x2C
#define REG_Z_MSB      0x2D
#define LOG_FILE       "vibration_log.csv"
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_axis(int fd, uint8_t lsb_reg, uint8_t msb_reg, int16_t *out)
{
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, lsb_reg, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, msb_reg, &msb) < 0) return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int read_sensor(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    if (read_axis(fd, REG_X_LSB, REG_X_MSB, x) < 0) return -1;
    if (read_axis(fd, REG_Y_LSB, REG_Y_MSB, y) < 0) return -1;
    if (read_axis(fd, REG_Z_LSB, REG_Z_MSB, z) < 0) return -1;
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm_utc;
    gmtime_r(&t, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

static void log_data(FILE *fp, const char *ts, int16_t x, int16_t y, int16_t z)
{
    fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", D7S_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    fseek(g_log, 0, SEEK_END);
    if (ftell(g_log) == 0) {
        fprintf(g_log, "Timestamp,X,Y,Z\n");
        fflush(g_log);
    }

    printf("Monitoring D7S-0001 at 0x%02X on %s. Press Ctrl+C to stop.\n", D7S_ADDR, I2C_BUS);

    while (g_running) {
        int16_t x, y, z;
        char ts[32];

        if (read_sensor(g_i2c_fd, &x, &y, &z) == 0) {
            get_timestamp(ts, sizeof(ts));
            log_data(g_log, ts, x, y, z);
            printf("%s  X=%d  Y=%d  Z=%d\n", ts, x, y, z);
        } else {
            fprintf(stderr, "Sensor read failed; skipping sample.\n");
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_log)  fclose(g_log);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return EXIT_SUCCESS;
}

