    line1 = gpiod_chip_get_line(chip, SENSOR_1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line (sensor 1)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, SENSOR_2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line (sensor 2)");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line1, "conveyor_sensor1",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        perror("gpiod_line_request_input_flags (sensor 1)");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(line2, "conveyor_sensor2",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        perror("gpiod_line_request_input_flags (sensor 2)");
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log file");
        goto cleanup;
    }

    printf("Conveyor belt safety system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0 || val2 < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        log_event(log_file, val1, val2);

        if (val1 == 1 && val2 == 1) {
            printf("Conveyor belt halted!\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_file) fclose(log_file);
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

