#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8452Q_ADDR  0x1D
#define WHO_AM_I_REG   0x0D
#define WHO_AM_I_VAL   0x2A
#define CTRL_REG1      0x2A
#define OUT_X_MSB      0x01
#define OUT_X_LSB      0x02
#define OUT_Y_MSB      0x03
#define OUT_Y_LSB      0x04
#define OUT_Z_MSB      0x05
#define OUT_Z_LSB      0x06
#define TILT_THRESHOLD 45.0
#define LOG_FILE       "fall_log.txt"
#define POLL_DELAY_MS  10

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C block write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read (reg 0x%02X, len %zu) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mma8452q(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, WHO_AM_I_REG, &who_am_i) != 0)
        return -1;
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    uint8_t ctrl = 0;
    if (i2c_read_reg8(fd, CTRL_REG1, &ctrl) != 0)
        return -1;

    /* Clear ACTIVE bit (bit 0) to enter standby mode */
    ctrl &= ~0x01;
    if (i2c_write_reg8(fd, CTRL_REG1, ctrl) != 0)
        return -1;

    /* Set data rate to 100 Hz (bits 3-5 = 0b010) */
    ctrl &= ~0x70;
    ctrl |= 0x20;
    if (i2c_write_reg8(fd, CTRL_REG1, ctrl) != 0)
        return -1;

    /* Set ACTIVE bit (bit 0) to enter active mode */
    ctrl |= 0x01;
    if (i2c_write_reg8(fd, CTRL_REG1, ctrl) != 0)
        return -1;

    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_MSB, buf, sizeof(buf)) != 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]) >> 4;
    *y = (int16_t)((buf[2] << 8) | buf[3]) >> 4;
    *z = (int16_t)((buf[4] << 8) | buf[5]) >> 4;
    return 0;
}

static double calculate_tilt(int16_t x, int16_t y, int16_t z)
{
    double yz = sqrt((double)y * y + (double)z * z);
    return atan2((double)x, yz) * 180.0 / M_PI;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %d, Y: %d, Z: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        fclose(g_log_fp);
        g_log_fp = NULL;
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MMA8452Q_ADDR, strerror(errno));
        goto cleanup;
    }

    if (init_mma8452q(g_i2c_fd) != 0) {
        fprintf(stderr, "MMA8452Q initialization failed\n");
        goto cleanup;
    }

    printf("MMA8452Q initialized. Monitoring tilt (threshold %.0f degrees)...\n",
           TILT_THRESHOLD);

    while (g_running) {
        int16_t x, y, z;
        if (read_accel(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error, skipping iteration\n");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        double tilt = calculate_tilt(x, y, z);
        if (fabs(tilt) > TILT_THRESHOLD) {
            log_data(g_log_fp, x, y, z);
        }

        usleep(POLL_DELAY_MS * 1000);
    }

cleanup:
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    printf("\nExiting cleanly.\n");
    return 0;
}

