code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LIS3MDL_ADDR   0x1E
#define WHO_AM_I_REG   0x0F
#define WHO_AM_I_VAL   0x3D
#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define CTRL_REG3      0x22
#define OUT_X_L        0x28
#define MAG_X_OFFSET   0.0f
#define MAG_Y_OFFSET   0.0f
#define MAG_Z_OFFSET   0.0f
#define MAG_X_SCALE    1.0f
#define MAG_Y_SCALE    1.0f
#define MAG_Z_SCALE    1.0f
#define METAL_THRESHOLD 800.0f
#define SAMPLE_PERIOD_US 100000
#define MAX_INIT_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int lis3mdl_init(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg(fd, WHO_AM_I_REG, &who_am_i) < 0) return -1;
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg(fd, CTRL_REG1, 0x70) < 0) return -1;
    if (i2c_write_reg(fd, CTRL_REG4, 0x0C) < 0) return -1;
    if (i2c_write_reg(fd, CTRL_REG3, 0x00) < 0) return -1;
    return 0;
}

static int read_magnetometer(int fd, float *x, float *y, float *z) {
    uint8_t raw[6];
    if (i2c_read_burst(fd, OUT_X_L, raw, 6) < 0) return -1;
    int16_t rx = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t ry = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t rz = (int16_t)((raw[5] << 8) | raw[4]);
    *x = ((float)rx - MAG_X_OFFSET) * MAG_X_SCALE;
    *y = ((float)ry - MAG_Y_OFFSET) * MAG_Y_SCALE;
    *z = ((float)rz - MAG_Z_OFFSET) * MAG_Z_SCALE;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    fprintf(fp, "%.2f,%.2f,%.2f\n", x, y, z);
    fflush(fp);
}

static void check_metal(float x, float y, float z) {
    float mag = sqrtf(x * x + y * y + z * z);
    if (mag > METAL_THRESHOLD) {
        fprintf(stderr, "Metal detected! Total field magnitude: %.2f mG\n", mag);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_log_fp = fopen("magnetic_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    for (int attempt = 0; attempt < MAX_INIT_RETRIES; attempt++) {
        g_i2c_fd = open(I2C_BUS, O_RDWR);
        if (g_i2c_fd < 0) {
            fprintf(stderr, "Failed to open %s (attempt %d/%d): %s\n", I2C_BUS, attempt + 1, MAX_INIT_RETRIES, strerror(errno));
            usleep(100000);
            continue;
        }
        if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
            fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LIS3MDL_ADDR, strerror(errno));
            close(g_i2c_fd);
            g_i2c_fd = -1;
            usleep(100000);
            continue;
        }
        if (lis3mdl_init(g_i2c_fd) == 0) {
            printf("LIS3MDL initialized successfully.\n");
            break;
        }
        close(g_i2c_fd);
        g_i2c_fd = -1;
        usleep(100000);
    }
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize LIS3MDL after %d attempts.\n", MAX_INIT_RETRIES);
        fclose(g_log_fp);
        return 1;
    }

    while (g_running) {
        float x, y, z;
        if (read_magnetometer(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_log_fp, x, y, z);
            check_metal(x, y, z);
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    if (g_i2c_fd >= 0) close(g_i2c_fd);
    if (g_log_fp) fclose(g_log_fp);
    printf("\nExiting cleanly.\n");
    return 0;
}

