#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* ADXL354B Register Addresses */
#define ADXL354B_REG_STATUS      0x04
#define ADXL354B_REG_PARTID      0x01
#define ADXL354B_REG_RESET       0x1F
#define ADXL354B_REG_XDATA       0x08
#define ADXL354B_REG_YDATA       0x0B
#define ADXL354B_REG_ZDATA       0x0E
#define ADXL354B_REG_POWER_CTL   0x2D

/* POWER_CTL bits */
#define ADXL354B_POWER_CTL_STANDBY 0x00
#define ADXL354B_POWER_CTL_MEASURE 0x01
#define ADXL354B_POWER_CTL_STABLE  0x02

/* Expected PARTID for ADXL354B */
#define ADXL354B_PARTID_EXPECTED  0x1D

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0

/* Sensitivity for +/-2g range: 3.9 microg/LSB */
#define ADXL354B_SENSITIVITY 0.0000039f

/* Global variables for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int adxl354b_read_register(int handle, uint8_t reg, uint8_t *value);
static int adxl354b_write_register(int handle, uint8_t reg, uint8_t value);
static int adxl354b_reset(int handle);
static int adxl354b_init(int handle);
static int adxl354b_read_axis(int handle, uint8_t reg, float *acceleration);
static int log_data(FILE *fp, float x, float y, float z);
static void signal_handler(int signal);
static void cleanup(void);

/* Read a single register from the ADXL354B */
static int adxl354b_read_register(int handle, uint8_t reg, uint8_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F;  /* Bit 7 = 0 for read */
    tx_buf[1] = 0x00;        /* Dummy byte for clocking data out */

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI read error on register 0x%02X\n", reg);
        return -1;
    }

    *value = (uint8_t)rx_buf[1];
    return 0;
}

/* Write a single register to the ADXL354B */
static int adxl354b_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg | 0x80;  /* Bit 7 = 1 for write */
    tx_buf[1] = value;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI write error on register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* Reset the ADXL354B */
static int adxl354b_reset(int handle) {
    if (adxl354b_write_register(handle, ADXL354B_REG_RESET, 0x52) != 0) {
        fprintf(stderr, "Failed to write RESET register\n");
        return -1;
    }
    gpioDelay(1000);  /* 1 ms delay for reset to take effect */
    return 0;
}

/* Initialize the ADXL354B */
static int adxl354b_init(int handle) {
    uint8_t partid = 0;

    /* Check device presence */
    if (adxl354b_read_register(handle, ADXL354B_REG_PARTID, &partid) != 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }

    if (partid != ADXL354B_PARTID_EXPECTED) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x%02X)\n",
                partid, ADXL354B_PARTID_EXPECTED);
        return -1;
    }

    /* Reset the device */
    if (adxl354b_reset(handle) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        return -1;
    }

    /* Set standby mode to configure */
    if (adxl354b_write_register(handle, ADXL354B_REG_POWER_CTL,
                                ADXL354B_POWER_CTL_STANDBY) != 0) {
        fprintf(stderr, "Failed to set standby mode\n");
        return -1;
    }

    /* Wait for STABLE bit to clear (device ready) */
    uint8_t status = 0;
    int timeout = 100;
    do {
        if (adxl354b_read_register(handle, ADXL354B_REG_STATUS, &status) != 0) {
            fprintf(stderr, "Failed to read STATUS register\n");
            return -1;
        }
        gpioDelay(1000);  /* 1 ms */
        timeout--;
    } while ((status & ADXL354B_POWER_CTL_STABLE) && timeout > 0);

    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for ADXL354B to stabilize\n");
        return -1;
    }

    /* Set measurement mode */
    if (adxl354b_write_register(handle, ADXL354B_REG_POWER_CTL,
                                ADXL354B_POWER_CTL_MEASURE) != 0) {
        fprintf(stderr, "Failed to set measurement mode\n");
        return -1;
    }

    return 0;
}

/* Read acceleration data from a specific axis */
static int adxl354b_read_axis(int handle, uint8_t reg, float *acceleration) {
    char tx_buf[4];
    char rx_buf[4];

    /* Read 3 bytes: bit 7 = 1 (read), bit 6 = 1 (multi-byte) */
    tx_buf[0] = reg | 0xC0;
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;
    tx_buf[3] = 0x00;

    if (spiXfer(handle, tx_buf, rx_buf, 4) != 4) {
        fprintf(stderr, "SPI read error on axis 0x%02X\n", reg);
        return -1;
    }

    /* Combine 3 bytes into 24-bit signed value */
    int32_t raw = ((int32_t)(rx_buf[1] & 0xFF) << 16) |
                  ((int32_t)(rx_buf[2] & 0xFF) << 8) |
                  ((int32_t)(rx_buf[3] & 0xFF));

    /* Sign-extend from 24-bit to 32-bit */
    if (raw & 0x00800000) {
        raw |= 0xFF000000;
    }

    *acceleration = (float)raw * ADXL354B_SENSITIVITY;
    return 0;
}

/* Log data to a file */
static int log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    /* Initialize ADXL354B */
    if (adxl354b_init(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B initialisation failed\n");
        cleanup();
        return 1;
    }

    /* Open log file */
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Main loop */
    while (!terminate) {
        float x, y, z;

        if (adxl354b_read_axis(spi_handle, ADXL354B_REG_XDATA, &x) != 0 ||
            adxl354b_read_axis(spi_handle, ADXL354B_REG_YDATA, &y) != 0 ||
            adxl354b_read_axis(spi_handle, ADXL354B_REG_ZDATA, &z) != 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
        } else {
            if (log_data(log_file, x, y, z) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        gpioDelay(100000);  /* 100 ms */
    }

    /* Cleanup */
    cleanup();
    return 0;
}

