/* ADIS16362 Register Addresses */
#define REG_X_GYRO  0x04
#define REG_Y_GYRO  0x06
#define REG_Z_GYRO  0x08
#define REG_X_ACCL  0x0A
#define REG_Y_ACCL  0x0C
#define REG_Z_ACCL  0x0E

/* Scaling factors (from ADIS16362 datasheet) */
#define GYRO_SCALE  0.05f   /* deg/sec/LSB */
#define ACCL_SCALE  0.0025f /* g/LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000 /* 1 MHz */
#define SPI_FLAGS   0x03    /* Mode 3: CPOL=1, CPHA=1 */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x, y, z;
} imu_data_t;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a 16-bit register from ADIS16362.
 * ADIS16362 read protocol: send address with MSB set, then dummy byte;
 * the requested data is returned on the next 16-bit transfer.
 * Returns 0 on success, -1 on SPI error. */
static int read_register(uint8_t reg, int16_t *out) {
    char tx[2], rx[2];
    int ret;

    /* Phase 1: send read address */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;
    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read address phase failed for reg 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }

    /* Small delay to allow conversion (ADIS16362 is fast, but we wait) */
    gpioDelay(1000); /* 1 ms */

    /* Phase 2: send dummy to get data */
    tx[0] = 0x00;
    tx[1] = 0x00;
    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI data phase failed for reg 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }

    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* Read all 6 IMU axes and scale */
static int read_imu_data(imu_data_t *data) {
    int16_t raw;

    if (read_register(REG_X_GYRO, &raw) != 0) return -1;
    data->x = (float)raw * GYRO_SCALE;

    if (read_register(REG_Y_GYRO, &raw) != 0) return -1;
    data->y = (float)raw * GYRO_SCALE;

    if (read_register(REG_Z_GYRO, &raw) != 0) return -1;
    data->z = (float)raw * GYRO_SCALE;

    if (read_register(REG_X_ACCL, &raw) != 0) return -1;
    data->x += (float)raw * ACCL_SCALE;

    if (read_register(REG_Y_ACCL, &raw) != 0) return -1;
    data->y += (float)raw * ACCL_SCALE;

    if (read_register(REG_Z_ACCL, &raw) != 0) return -1;
    data->z += (float)raw * ACCL_SCALE;

    return 0;
}

/* Log one data row with high-precision timestamp */
static void log_data(const imu_data_t *data) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    fprintf(log_file, "%ld.%09ld,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            (long)ts.tv_sec, ts.tv_nsec,
            data->x, data->y, data->z,
            data->x, data->y, data->z);
    fflush(log_file);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0, 1 MHz, Mode 3 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("imu_log.csv", "w");
    if (!log_file) {
        perror("fopen imu_log.csv");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    fflush(log_file);

    /* Install signal handler */
    signal(SIGINT, signal_handler);

    printf("ADIS16362 IMU logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        imu_data_t data;
        if (read_imu_data(&data) == 0) {
            log_data(&data);
        } else {
            fprintf(stderr, "IMU read error, skipping log entry\n");
        }
        gpioDelay(10000); /* 10 ms -> ~100 Hz */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

