/*
 * KY-032 IR Obstacle Avoidance Sensor Reader (libgpiod v2)
 * Board:  Raspberry Pi 3 Model B+
 * Sensors: 2 x Keyes KY-032 on GPIO17 and GPIO27 (BCM)
 *   KY-032 output is active-low: 0 = obstacle detected, 1 = clear
 *
 * Build:  gcc -O2 -Wall -Wextra -o ky032_avoid ky032_avoid.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO17  17
#define GPIO27  27
#define POLL_MS 100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    char ts[32];

    if (localtime_r(&now, &tm_buf) != NULL &&
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_buf) > 0) {
        printf("[%s] ", ts);
    } else {
        printf("[unknown] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_values *vals = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 3 B+). */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    /* Configure both lines as inputs. */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        perror("gpiod_line_settings_new");
        goto cleanup;
    }
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        perror("gpiod_line_config_new");
        goto cleanup;
    }

    unsigned int offsets[2] = { GPIO17, GPIO27 };
    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 2, settings) < 0) {
        perror("gpiod_line_config_add_line_settings");
        goto cleanup;
    }

    /* Request the two lines together. */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        perror("gpiod_request_config_new");
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ky032-avoid");

    struct gpiod_line_request *req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (req == NULL) {
        perror("gpiod_chip_request_lines");
        goto cleanup;
    }

    printf("KY-032 obstacle avoidance system started.\n");
    printf("  GPIO17 (BCM) - sensor 1\n");
    printf("  GPIO27 (BCM) - sensor 2\n");
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        vals = gpiod_line_request_get_values(req);
        if (vals == NULL) {
            perror("gpiod_line_request_get_values");
            break;
        }

        int v1 = gpiod_line_value_get(vals, GPIO17);
        int v2 = gpiod_line_value_get(vals, GPIO27);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "Error reading sensor values: %s\n", strerror(errno));
            break;
        }

        print_timestamp();
        if (v1 == 0) {
            printf("Obstacle detected by sensor 1 (GPIO17)\n");
        } else {
            printf("Sensor 1 (GPIO17): clear\n");
        }
        if (v2 == 0) {
            printf("Obstacle detected by sensor 2 (GPIO27)\n");
        } else {
            printf("Sensor 2 (GPIO27): clear\n");
        }
        fflush(stdout);

        struct timespec ts = { 0, POLL_MS * 1000000L };
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (vals != NULL) {
        gpiod_line_values_free(vals);
    }
    if (req != NULL) {
        gpiod_line_request_release(req);
    }
    if (req_cfg != NULL) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

