        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ky032-avoid");

    struct gpiod_line_request *req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (req == NULL) {
        perror("gpiod_chip_request_lines");
        goto cleanup;
    }

    printf("KY-032 obstacle avoidance system started.\n");
    printf("  GPIO17 (BCM) - sensor 1\n");
    printf("  GPIO27 (BCM) - sensor 2\n");
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        vals = gpiod_line_request_get_values(req);
        if (vals == NULL) {
            perror("gpiod_line_request_get_values");
            break;
        }

        int v1 = gpiod_line_value_get(vals, GPIO17);
        int v2 = gpiod_line_value_get(vals, GPIO27);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "Error reading sensor values: %s\n", strerror(errno));
            break;
        }

        print_timestamp();
        if (v1 == 0) {
            printf("Obstacle detected by sensor 1 (GPIO17)\n");
        } else {
            printf("Sensor 1 (GPIO17): clear\n");
        }
        if (v2 == 0) {
            printf("Obstacle detected by sensor 2 (GPIO27)\n");
        } else {
            printf("Sensor 2 (GPIO27): clear\n");
        }
        fflush(stdout);

        struct timespec ts = { 0, POLL_MS * 1000000L };
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (vals != NULL) {
        gpiod_line_values_free(vals);
    }
    if (req != NULL) {
        gpiod_line_request_release(req);
    }
    if (req_cfg != NULL) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

