#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

/* ADIS16266 Register Addresses */
#define ADIS16266_REG_XGYRO_OUT  0x04
#define ADIS16266_REG_YGYRO_OUT  0x06
#define ADIS16266_REG_ZGYRO_OUT  0x08
#define ADIS16266_REG_MSC_CTRL   0x24

/* SPI Configuration */
#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8

/* GPIO Configuration (libgpiod) */
#define GPIO_CHIP       "gpiochip4"
#define CS_LINE_OFFSET  8  /* GPIO8 = SPI0 CE0 */

/* Scaling factor for ADIS16266 (degrees/second per LSB) */
#define SCALE_FACTOR    0.02f

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a single register on the ADIS16266 */
static int adis_write_reg(int spi_fd, struct gpiod_line *cs_line, uint8_t reg, uint16_t value) {
    uint8_t tx[3] = { (uint8_t)(reg & 0x7F), (uint8_t)(value >> 8), (uint8_t)(value & 0xFF) };
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = 0,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error: Failed to assert CS line: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI write failed for reg 0x%02X: %s\n", reg, strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error: Failed to deassert CS line: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* Read a 16-bit register from the ADIS16266 using the two-transfer read protocol */
static int adis_read_reg(int spi_fd, struct gpiod_line *cs_line, uint8_t reg, uint16_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error: Failed to assert CS line: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI read phase 1 failed for reg 0x%02X: %s\n", reg, strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error: Failed to deassert CS line: %s\n", strerror(errno));
        return -1;
    }

    /* Small delay between transfers to meet ADIS16266 timing */
    usleep(10);

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error: Failed to assert CS line: %s\n", strerror(errno));
        return -1;
    }

    tx[0] = 0x00;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI read phase 2 failed for reg 0x%02X: %s\n", reg, strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error: Failed to deassert CS line: %s\n", strerror(errno));
        return -1;
    }

    *value = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

int main(void) {
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = EXIT_FAILURE;

    /* Set up signal handler for clean exit */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure SPI mode */
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure SPI bits per word */
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure SPI max speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: Failed to set SPI speed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open GPIO chip and get CS line */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request CS line as output, initially high (inactive) */
    if (gpiod_line_request_output(cs_line, "adis16266-cs", 1) < 0) {
        fprintf(stderr, "Error: Failed to request CS line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Initialize ADIS16266: enable data ready mode via MSC_CTRL */
    if (adis_write_reg(spi_fd, cs_line, ADIS16266_REG_MSC_CTRL, 0x0001) < 0) {
        fprintf(stderr, "Error: Failed to initialize ADIS16266 (sensor may be absent or bus error)\n");
        goto cleanup;
    }

    printf("ADIS16266 initialized. Reading gyroscope data every 100 ms...\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        uint16_t raw_x, raw_y, raw_z;
        float gyro_x, gyro_y, gyro_z;

        if (adis_read_reg(spi_fd, cs_line, ADIS16266_REG_XGYRO_OUT, &raw_x) < 0 ||
            adis_read_reg(spi_fd, cs_line, ADIS16266_REG_YGYRO_OUT, &raw_y) < 0 ||
            adis_read_reg(spi_fd, cs_line, ADIS16266_REG_ZGYRO_OUT, &raw_z) < 0) {
            fprintf(stderr, "Error: Failed to read gyroscope data. Retrying...\n");
            usleep(100000);
            continue;
        }

        /* Convert raw 16-bit signed values to angular rates */
        gyro_x = (float)((int16_t)raw_x) * SCALE_FACTOR;
        gyro_y = (float)((int16_t)raw_y) * SCALE_FACTOR;
        gyro_z = (float)((int16_t)raw_z) * SCALE_FACTOR;

        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", gyro_x, gyro_y, gyro_z);
        fflush(stdout);

        usleep(100000); /* 100 ms */
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret;
}

