#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C 7-bit address (SA0 tied to GND) */
#define LSM6DSR_ADDR 0x6B

/* WHO_AM_I register and expected value */
#define WHO_AM_I_REG   0x0F
#define WHO_AM_I_VAL   0x6B

/* CTRL1_XL: accel ODR 104 Hz, FS +-2g, BW filter 400 Hz */
#define CTRL1_XL       0x10
#define CTRL1_XL_VAL   0x42

/* CTRL2_G: gyro ODR 104 Hz, FS +-250 dps, BW filter 400 Hz */
#define CTRL2_G        0x11
#define CTRL2_G_VAL    0x42

/* Gyro and accel data registers (burst read 12 bytes) */
#define OUTX_L_G       0x22
#define GYRO_SENS      8.75f   /* dps/LSB at +-250 dps */
#define ACCEL_SENS     0.061f  /* g/LSB at +-2g */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0)
        fprintf(stderr, "i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, val, rc);
    return rc;
}

static int i2c_read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: got %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(int handle)
{
    int who = i2cReadByteData(handle, WHO_AM_I_REG);
    if (who < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I: %d\n", who);
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg(handle, CTRL1_XL, CTRL1_XL_VAL) < 0)
        return -1;
    if (i2c_write_reg(handle, CTRL2_G, CTRL2_G_VAL) < 0)
        return -1;

    return 0;
}

static int read_sensor_data(int handle, float *gyro_x, float *gyro_y,
                            float *gyro_z, float *accel_x, float *accel_y,
                            float *accel_z)
{
    uint8_t buf[12];
    if (i2c_read_burst(handle, OUTX_L_G, buf, sizeof(buf)) < 0)
        return -1;

    int16_t raw_gx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_gy = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_gz = (int16_t)((buf[5] << 8) | buf[4]);
    int16_t raw_ax = (int16_t)((buf[7] << 8) | buf[6]);
    int16_t raw_ay = (int16_t)((buf[9] << 8) | buf[8]);
    int16_t raw_az = (int16_t)((buf[11] << 8) | buf[10]);

    *gyro_x = (float)raw_gx / GYRO_SENS;
    *gyro_y = (float)raw_gy / GYRO_SENS;
    *gyro_z = (float)raw_gz / GYRO_SENS;
    *accel_x = (float)raw_ax / ACCEL_SENS;
    *accel_y = (float)raw_ay / ACCEL_SENS;
    *accel_z = (float)raw_az / ACCEL_SENS;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                LSM6DSR_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(g_i2c_handle) < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("LSM6DSR initialised. Reading data every 100 ms (Ctrl+C to stop).\n");

    while (g_running) {
        float gx, gy, gz, ax, ay, az;

        if (read_sensor_data(g_i2c_handle, &gx, &gy, &gz, &ax, &ay, &az) == 0) {
            printf("Gyro: X=%.3f dps, Y=%.3f dps, Z=%.3f dps | "
                   "Accel: X=%.3f g, Y=%.3f g, Z=%.3f g\n",
                   gx, gy, gz, ax, ay, az);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

