/* FXOS8700 register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_WHO_AM_I_VAL 0xC7
#define FXOS8700_CTRL_REG1  0x2A
#define FXOS8700_CTRL_REG2  0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB  0x01

/* I2C bus on Raspberry Pi 4 (GPIO2 = SDA, GPIO3 = SCL) */
#define I2C_BUS 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an 8-bit register; returns 0 on success, -1 on error. */
static int reg_write(int handle, uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* Read a single byte from an 8-bit register; returns 0 on success, -1 on error. */
static int reg_read(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadByteData(reg=0x%02X) failed\n", reg);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Initialize the FXOS8700 into hybrid accelerometer + magnetometer mode. */
static int fxos8700_init(int handle)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (reg_read(handle, FXOS8700_WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Error: cannot read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode so configuration changes take effect */
    if (reg_write(handle, FXOS8700_CTRL_REG1, 0x00) < 0) return -1;

    /* Hybrid mode: 14-bit accel, 12-bit mag, active */
    if (reg_write(handle, FXOS8700_CTRL_REG1, 0x0D) < 0) return -1;

    /* Enable magnetometer */
    if (reg_write(handle, FXOS8700_M_CTRL_REG1, 0x1F) < 0) return -1;

    /* Set magnetometer ODR to 80 Hz (ODR = 0x0F) */
    if (reg_write(handle, FXOS8700_M_CTRL_REG2, 0x0F) < 0) return -1;

    /* Active mode */
    if (reg_write(handle, FXOS8700_CTRL_REG1, 0x0D) < 0) return -1;

    return 0;
}

/* Read 12 bytes of combined data (accel 6 bytes + mag 6 bytes). */
static int fxos8700_read_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                              int16_t *mx, int16_t *my, int16_t *mz)
{
    char buffer[12];
    int rc = i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, buffer, 12);
    if (rc != 12) {
        fprintf(stderr, "Error: i2cReadI2CBlockData returned %d (expected 12)\n", rc);
        return -1;
    }

    /* Accelerometer: 14-bit left-aligned, shift right 2 to get 12-bit value */
    *ax = (int16_t)(((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1]) >> 2;
    *ay = (int16_t)(((uint16_t)buffer[2] << 8) | (uint8_t)buffer[3]) >> 2;
    *az = (int16_t)(((uint16_t)buffer[4] << 8) | (uint8_t)buffer[5]) >> 2;

    /* Magnetometer: 16-bit big-endian */
    *mx = (int16_t)(((uint16_t)buffer[6] << 8) | (uint8_t)buffer[7]);
    *my = (int16_t)(((uint16_t)buffer[8] << 8) | (uint8_t)buffer[9]);
    *mz = (int16_t)(((uint16_t)buffer[10] << 8) | (uint8_t)buffer[11]);

    return 0;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the FXOS8700 address */
    g_i2c_handle = i2cOpen(I2C_BUS, FXOS8700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, FXOS8700_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (fxos8700_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: FXOS8700 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialized. Reading data every 100 ms (Ctrl+C to stop)...\n");

    /* Main loop: read and log data every 100 ms */
    while (g_running) {
        int16_t ax, ay, az, mx, my, mz;

        if (fxos8700_read_data(g_i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Mag: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Warning: read failed, retrying next cycle\n");
        }

        gpioDelay(100000); /* 100 ms in microseconds */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

