    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s: Tilt angle: %.2f degrees\n", timestamp, angle);
    fclose(fp);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Error: Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (init_adxl345(i2c_fd) < 0) {
        fprintf(stderr, "Error: ADXL345 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    float x, y, z, tilt_angle;

    while (running) {
        if (read_acceleration(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error: Failed to read acceleration data.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        tilt_angle = calculate_tilt_angle(x, y, z);

        if (fabs(tilt_angle) > TILT_THRESHOLD) {
