#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define WINDOW_SECONDS 5
#define SAMPLE_INTERVAL_US 1000
#define PAUSE_SECONDS 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor(void) {
    return gpioRead(SENSOR_PIN);
}

static void print_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] ", buffer);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        fprintf(stderr, "  threshold: minimum high-readings per %d-second window to trigger alert\n", WINDOW_SECONDS);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long threshold = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        fprintf(stderr, "Error: invalid threshold '%s'. Must be a positive integer.\n", argv[1]);
        return EXIT_FAILURE;
    }
    if (threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    if (setup_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-038 sound sensor on GPIO%d. Threshold=%ld high-readings/%d s. Press Ctrl+C to exit.\n",
           SENSOR_PIN, threshold, WINDOW_SECONDS);
    fflush(stdout);

    while (running) {
        int high_count = 0;
        int elapsed_us = 0;

        for (int i = 0; i < WINDOW_SECONDS * 1000 && running; i++) {
            int level = read_sensor();
            if (level < 0) {
                fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n", SENSOR_PIN);
            } else if (level == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
            elapsed_us += SAMPLE_INTERVAL_US;
        }

        if (!running) {
            break;
        }

        print_timestamp();
        if (high_count > (int)threshold) {
            printf("ALERT: %d high readings in %d s (threshold %ld exceeded)\n",
                   high_count, WINDOW_SECONDS, threshold);
        } else {
            printf("Noise level: %d high readings in %d s\n",
                   high_count, WINDOW_SECONDS);
        }
        fflush(stdout);

        for (int i = 0; i < PAUSE_SECONDS * 1000 && running; i++) {
            gpioDelay(1000);
        }
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

