/*
 * door_access.c — Raspberry Pi 4 Model B
 * libgpiod-based door access control using TIP120 relays on GPIO17 and GPIO27.
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 * Run:    ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip4"   /* BCM GPIO bank on Pi 4 */
#define DOOR_A_PIN       17
#define DOOR_B_PIN       27
#define CODE_LENGTH      6
#define UNLOCK_DURATION  5            /* seconds */
#define LOG_FILE         "access_log.txt"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Returns a 6-digit code (100000..999999) or -1 on error.             */
static int generate_code(void)
{
    return (rand() % 900000) + 100000;
}

/* ------------------------------------------------------------------ */
/* Logs a successful entry as "YYYY-MM-DD HH:MM:SS,NNNNNN"             */
static void log_access(int code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, code);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Drive a single GPIO line HIGH (unlock) or LOW (lock).              */
static int set_door(struct gpiod_line *line, int unlock)
{
    int ret = gpiod_line_set_value(line, unlock ? 1 : 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_set_value failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *door_a = NULL;
    struct gpiod_line *door_b = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Seed PRNG ------------------------------------------------- */
    srand((unsigned int)time(NULL));

    /* ---- Open GPIO chip -------------------------------------------- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Get lines ------------------------------------------------- */
    door_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }
    door_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- Request lines as outputs, default LOW (locked) ------------ */
    if (gpiod_line_request_output(door_a, "door_access", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(door_a) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(door_b, "door_access", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(door_b) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- Generate initial code ------------------------------------ */
    int code = generate_code();
    printf("Generated security code: %d\n", code);

    /* ---- Main loop ------------------------------------------------- */
    while (g_running) {
        char input[CODE_LENGTH + 1];
        printf("Enter the security code (%d-digit): ", CODE_LENGTH);
        fflush(stdout);

        if (fgets(input, sizeof(input), stdin) == NULL) {
            if (feof(stdin)) {
                fprintf(stderr, "EOF on stdin, exiting.\n");
                break;
            }
            fprintf(stderr, "fgets failed: %s\n", strerror(errno));
            break;
        }

        /* Strip trailing newline */
        input[strcspn(input, "\n")] = '\0';

        /* Validate: exactly CODE_LENGTH digits */
        if (strlen(input) != CODE_LENGTH) {
            fprintf(stderr, "Invalid input: must be exactly %d digits.\n",
                    CODE_LENGTH);
            continue;
        }
        for (int i = 0; i < CODE_LENGTH; i++) {
            if (!isdigit((unsigned char)input[i])) {
                fprintf(stderr, "Invalid input: only digits allowed.\n");
                goto re_prompt;
            }
        }

        if (strcmp(input, "exit") == 0) {
            printf("Exiting.\n");
            break;
        }

        if (strcmp(input, "quit") == 0) {
            printf("Exiting.\n");
            break;
        }

        if (strcmp(input, "help") == 0) {
            printf("Commands: exit, quit, help\n");
            continue;
        }

        if (strcmp(input, "unlock") == 0) {
            printf("Unlocking Door A for %d seconds...\n", UNLOCK_DURATION);
            if (set_door(door_a, 1) < 0) goto cleanup;
            sleep(UNLOCK_DURATION);
            if (set_door(door_a, 0) < 0) goto cleanup;
            printf("Door A locked.\n");
            continue;
        }

        if (strcmp(input, "lock") == 0) {
            printf("Locking Door A...\n");
            if (set_door(door_a, 0) < 0) goto cleanup;
            printf("Door A locked.\n");
            continue;
        }

        if (strcmp(input, "status") == 0) {
            int va = gpiod_line_get_value(door_a);
            int vb = gpiod_line_get_value(door_b);
            if (va < 0 || vb < 0) {
                fprintf(stderr, "gpiod_line_get_value failed: %s\n",
                        strerror(errno));
                continue;
            }
            printf("Door A: %s (GPIO%d)\n", va ? "UNLOCKED" : "LOCKED", DOOR_A_PIN);
            printf("Door B: %s (GPIO%d)\n", vb ? "UNLOCKED" : "LOCKED", DOOR_B_PIN);
            continue;
        }

        if (strcmp(input, "code") == 0) {
            code = generate_code();
            printf("New security code: %d\n", code);
            continue;
        }

        if (strcmp(input, "log") == 0) {
            log_access(code);
            printf("Access logged.\n");
            continue;
        }

        if (strcmp(input, "doors") == 0) {
            printf("Doors: A=%s, B=%s\n",
                   gpiod_line_get_value(door_a) ? "UNLOCKED" : "LOCKED",
                   gpiod_line_get_value(door_b) ? "UNLOCKED" : "LOCKED");
            continue;
        }

        if (strcmp(input, "help") == 0) {
            printf("Commands: exit, quit, help, unlock, lock, status, code, log, doors\n");
            continue;
        }

        if (strcmp(input, "clear") == 0) {
            printf("Clearing input buffer.\n");
            continue;
