static int mpr121_read_touch(int handle, int *touch) {
    char buf[24];
    if (i2cReadI2CBlockData(handle, 0x00, buf, 24) != 24) return -1;
    for (int i = 0; i < MAX_ELECTRODE; i++) touch[i] = (buf[i * 2] & 0x01) ? 1 : 0;
    return 0;
}

static int mpr121_read_filtered(int handle, int *filtered) {
    char buf[24];
    if (i2cReadI2CBlockData(handle, 0x41, buf, 24) != 24) return -1;
    for (int i = 0; i < MAX_ELECTRODE; i++) filtered[i] = (buf[i * 2] & 0xFF);
    return 0;
}

static double map_log(int val, int max_val, double min_freq, double max_freq) {
    if (max_val <= 0) return min_freq;
    double norm = (double)val / (double)max_val;
    if (norm <= 0.0) return min_freq;
    return min_freq * pow(2.0, (log2(max_freq / min_freq) * norm));
}

static void play_tone(double freq) {
    if (freq < MIN_FREQ) freq = MIN_FREQ;
    if (freq > MAX_FREQ) freq = MAX_FREQ;
    gpioSetPWMfrequency(PWM_GPIO, (int)freq);
    gpioPWM(PWM_GPIO, PWM_DUTY);
}

static void log_frequency(double freq) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f\n", ts, freq);
    fclose(fp);
}

