#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define LSM303_ADDRESS 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define LED_GPIO 17
#define PWM_PERIOD_NS 10000000  // 10 ms period for 100 Hz PWM
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LSM303_ADDRESS, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

int init_magnetometer(void) {
    uint8_t buf[2] = {CTRL_REG1_M, 0x18};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to write CTRL_REG1_M: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);  // Wait for sensor to stabilize
    return 0;
}

int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t reg = OUT_X_L_M;
    uint8_t data[6];
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data ioctl_data;

    msgs[0].addr = LSM303_ADDRESS;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &reg;

    msgs[1].addr = LSM303_ADDRESS;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = 6;
    msgs[1].buf = data;

    ioctl_data.msgs = msgs;
    ioctl_data.nmsgs = 2;

    if (ioctl(i2c_fd, I2C_RDWR, &ioctl_data) < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);
    return 0;
}

int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(led_line, "lsm303_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_GPIO, strerror(errno));
        gpiod_line_release(led_line);
        led_line = NULL;
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    return 0;
}

void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    int duty_ns = (PWM_PERIOD_NS * brightness) / PWM_RANGE;
    // Simple software PWM: toggle at 100 Hz with variable duty cycle
    // For production, use hardware PWM via sysfs or pwm-2.0 API
    // Here we use a simple busy-wait for demonstration; in real use replace with proper PWM
    int on_time = duty_ns / 10000;  // 10 us resolution
    int off_time = (PWM_PERIOD_NS / 10000 - on_time) / 10000;
    gpiod_line_set_value(led_line, 1);
    usleep(on_time);
    gpiod_line_set_value(led_line, 0);
    usleep(off_time);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen("magnetometer_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    if (init_i2c() < 0) {
        fprintf(log_file, "I2C init failed\n");
        cleanup();
        return 1;
    }
    if (init_magnetometer() < 0) {
        fprintf(log_file, "Magnetometer init failed\n");
        cleanup();
        return 1;
    }
    if (init_gpio() < 0) {
        fprintf(log_file, "GPIO init failed\n");
        cleanup();
        return 1;
    }

    fprintf(log_file, "Program started\n");
    fflush(log_file);

    while (running) {
        int16_t x, y, z;
        if (read_magnetometer(&x, &y, &z) == 0) {
            double magnitude = sqrt((double)(x * x + y * y + z * z));
            int brightness = (int)(magnitude / 100.0);
            if (brightness < 0) brightness = 0;
            if (brightness > PWM_RANGE) brightness = PWM_RANGE;
            set_led_brightness(brightness);
            fprintf(log_file, "X: %d, Y: %d, Z: %d, Magnitude: %.2f, Brightness: %d\n", x, y, z, magnitude, brightness);
            fflush(log_file);
        } else {
            fprintf(log_file, "Read error, skipping sample\n");
            fflush(log_file);
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fprintf(log_file, "Program exiting\n");
    cleanup();
    return 0;
}

