#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define REG_CONFIG_A 0x00
#define REG_CONFIG_B 0x01
#define REG_MODE     0x02
#define REG_DATA_X_MSB 0x03
#define REG_DATA_Z_MSB 0x05
#define REG_DATA_Y_MSB 0x07

#define SAMPLE_WINDOW 100
#define SAMPLE_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, val, rc);
    }
    return rc;
}

static int read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed: reg=0x%02X, expected=%u, got=%d\n", reg, len, rc);
        return -1;
    }
    return 0;
}

static int init_hmc5883l(void) {
    if (write_reg(REG_CONFIG_A, 0x70) < 0) return -1;
    if (write_reg(REG_CONFIG_B, 0x20) < 0) return -1;
    if (write_reg(REG_MODE, 0x00) < 0) return -1;
    return 0;
}

static void update_offsets(int16_t x, int16_t y, int16_t z,
                           int32_t *off_x, int32_t *off_y, int32_t *off_z,
                           int *count) {
    *off_x += x;
    *off_y += y;
    *off_z += z;
    (*count)++;
    if (*count >= SAMPLE_WINDOW) {
        *off_x /= SAMPLE_WINDOW;
        *off_y /= SAMPLE_WINDOW;
        *off_z /= SAMPLE_WINDOW;
    }
}

static void apply_offsets(int16_t x, int16_t y, int16_t z,
                          int32_t off_x, int32_t off_y, int32_t off_z,
                          int32_t *out_x, int32_t *out_y, int32_t *out_z) {
    *out_x = (int32_t)x - off_x;
    *out_y = (int32_t)y - off_y;
    *out_z = (int32_t)z - off_z;
}

int main(void) {
    int32_t off_x = 0, off_y = 0, off_z = 0;
    int count = 0;
    int32_t out_x, out_y, out_z;
    uint8_t data[6];

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: rc=%d\n", HMC5883L_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HMC5883L initialized. Collecting hard-iron offsets...\n");

    while (running) {
        if (read_block(REG_DATA_X_MSB, data, 6) == 0) {
            int16_t x = (int16_t)((data[0] << 8) | data[1]);
            int16_t z = (int16_t)((data[2] << 8) | data[3]);
            int16_t y = (int16_t)((data[4] << 8) | data[5]);

            update_offsets(x, y, z, &off_x, &off_y, &off_z, &count);

            if (count >= SAMPLE_WINDOW) {
                apply_offsets(x, y, z, off_x, off_y, off_z, &out_x, &out_y, &out_z);
                printf("X: %d, Y: %d, Z: %d\n", out_x, out_y, out_z);
            }
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

