/*
 * LSM303D accelerometer monitor with GPIO interrupt-driven event logging.
 *
 * Board:  Raspberry Pi Zero W
 * Bus:    /dev/i2c-1 (I2C address 0x1D, SA0 tied high)
 * INT1:   GPIO23 (BCM 23, physical pin 16) via libgpiod
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define LSM303D_ADDR   0x1D

#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0x49

#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define INT1_CFG       0x30
#define INT1_THS       0x31
#define INT1_DURATION  0x32
#define OUT_X_L_A      0x28

#define GPIO_CHIP      "gpiochip0"
#define INT1_LINE      23

#define BUFFER_SIZE    64
#define EVENT_SAMPLES  10
#define POLL_MS        10

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers using linux/i2c-dev kernel interface ---- */

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val)
{
    if (i2c_smbus_read_byte_data(fd, reg) < 0) {
        fprintf(stderr, "I2C read 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)i2c_smbus_read_byte_data(fd, reg);
    return 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0) {
        fprintf(stderr, "I2C write 0x%02X <- 0x%02X failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (i2c_smbus_read_i2c_block_data(fd, reg, len, buf) < 0) {
        fprintf(stderr, "I2C block read 0x%02X (%zu bytes) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- LSM303D configuration ---- */

static int lsm303d_init(int fd)
{
    uint8_t who;
    if (i2c_read_byte(fd, WHO_AM_I, &who) < 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* 50 Hz ODR, all axes enabled, normal mode */
    if (i2c_write_byte(fd, CTRL_REG1, 0x57) < 0)
        return -1;

    /* Full-scale +-2g (sensitivity 0.061 mg/LSB) */
    if (i2c_write_byte(fd, CTRL_REG4, 0x00) < 0)
        return -1;

    /* INT1: any-axis high event */
    if (i2c_write_byte(fd, INT1_CFG, 0x2A) < 0)
        return -1;

    /* Threshold: 2000 mg / 16 = 125 */
    if (i2c_write_byte(fd, INT1_THS, 0x7D) < 0)
        return -1;

    /* Duration: 0 (immediate) */
    if (i2c_write_byte(fd, INT1_DURATION, 0x00) < 0)
        return -1;

    return 0;
}

/* ---- Accelerometer data ---- */

typedef struct {
    int16_t x, y, z;
} accel_t;

static int read_accel(int fd, accel_t *out)
{
    uint8_t raw[6];
    if (i2c_read_block(fd, OUT_X_L_A | 0x80, raw, sizeof(raw)) < 0)
        return -1;

    out->x = (int16_t)((raw[1] << 8) | raw[0]);
    out->y = (int16_t)((raw[3] << 8) | raw[2]);
    out->z = (int16_t)((raw[5] << 8) | raw[4]);
    return 0;
}

/* ---- Circular buffer ---- */

static accel_t  g_buf[BUFFER_SIZE];
static int      g_head = 0;
static int      g_count = 0;

static void buf_push(const accel_t *a)
{
    g_buf[g_head] = *a;
    g_head = (g_head + 1) % BUFFER_SIZE;
    if (g_count < BUFFER_SIZE)
        g_count++;
}

static void buf_dump_latest(int n)
{
    if (n > g_count)
        n = g_count;
    int start = (g_head - n + BUFFER_SIZE) % BUFFER_SIZE;
    printf("--- Last %d acceleration samples ---\n", n);
    for (int i = 0; i < n; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        printf("[%ld.%09ld] X=%6d  Y=%6d  Z=%6d  mg\n",
               (long)ts.tv_sec, ts.tv_nsec,
               g_buf[idx].x, g_buf[idx].y, g_buf[idx].z);
    }
    printf("-------------------------------------\n");
}

/* ---- Main ---- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (lsm303d_init(i2c_fd) < 0) {
        fprintf(stderr, "LSM303D initialization failed.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, INT1_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(line, "lsm303d_mon") < 0) {
        perror("gpiod_line_request_rising_edge_events");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("LSM303D monitoring started. INT1 on GPIO23. Ctrl-C to exit.\n");

    while (g_running) {
        struct timespec ts = {0, POLL_MS * 1000000L};
        int ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) {
            if (errno == EINTR)
                continue;
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0)
            continue; /* timeout, loop and re-check g_running */

        struct gpiod_line_event ev;
        if (gpiod_line_event_read(line, &ev) < 0) {
            if (errno == EINTR)
                continue;
            perror("gpiod_line_event_read");
            continue;
        }

        if (ev.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            accel_t a;
            if (read_accel(i2c_fd, &a) < 0) {
                fprintf(stderr, "Warning: accel read failed, skipping event.\n");
            } else {
                buf_push(&a);
                buf_dump_latest(EVENT_SAMPLES);
            }
        }
    }

    /* Graceful shutdown */
    if (i2c_write_byte(i2c_fd, CTRL_REG1, 0x00) < 0)
        fprintf(stderr, "Warning: failed to disable accelerometer.\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

