#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <termios.h>
#include <fcntl.h>
#include <pigpio.h>

#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define SERIAL_PORT1 "/dev/serial0"
#define SERIAL_PORT2 "/dev/serial1"
#define BAUD_RATE B9600
#define CODE_LENGTH 6
#define EXPECTED_CODE "123456"
#define READ_TIMEOUT_SEC 5
#define UNLOCK_DURATION_SEC 2
#define POLL_DELAY_US 100000

static volatile sig_atomic_t program_running = 1;
static int serial_handle1 = -1;
static int serial_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LOCK1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LOCK2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LOCK2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LOCK1_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW.\n", LOCK1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW.\n", LOCK2_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_serial(const char *port, speed_t baud) {
    int handle = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (handle < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", port, strerror(errno));
        return -1;
    }
    if (fcntl(handle, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error: fcntl F_SETFL failed on %s: %s\n", port, strerror(errno));
        close(handle);
        return -1;
    }
    struct termios tty;
    if (tcgetattr(handle, &tty) != 0) {
        fprintf(stderr, "Error: tcgetattr failed on %s: %s\n", port, strerror(errno));
        close(handle);
        return -1;
    }
    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);
    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 50; /* 5 seconds */
    if (tcsetattr(handle, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error: tcsetattr failed on %s: %s\n", port, strerror(errno));
        close(handle);
        return -1;
    }
    return handle;
}

static int read_code(int handle, char *code, int max_len) {
    int idx = 0;
    time_t start = time(NULL);
    while (program_running && (time(NULL) - start) < READ_TIMEOUT_SEC) {
        char ch;
        ssize_t n = read(handle, &ch, 1);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                usleep(POLL_DELAY_US);
                continue;
            }
            fprintf(stderr, "Error: read from serial failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            usleep(POLL_DELAY_US);
            continue;
        }
        if (ch >= '0' && ch <= '9') {
            code[idx++] = ch;
            if (idx == CODE_LENGTH) {
                code[idx] = '\0';
                return 0;
            }
        } else {
            /* Non-digit: flush the port */
            char discard;
            while (read(handle, &discard, 1) > 0) {
                /* discard */
            }
            start = time(NULL);
        }
    }
    return 1; /* timeout */
}

static int codes_match(const char *a, const char *b) {
    for (int i = 0; i < CODE_LENGTH; i++) {
        if (a[i] != b[i]) return 0;
    }
    return 1;
}

static int unlock_doors(void) {
    if (gpioWrite(LOCK1_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d HIGH.\n", LOCK1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d HIGH.\n", LOCK2_GPIO);
        gpioWrite(LOCK1_GPIO, 0);
        return -1;
    }
    printf("Doors unlocked for %d seconds.\n", UNLOCK_DURATION_SEC);
    sleep(UNLOCK_DURATION_SEC);
    if (gpioWrite(LOCK1_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d LOW.\n", LOCK1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d LOW.\n", LOCK2_GPIO);
        return -1;
    }
    printf("Doors locked.\n");
    return 0;
}

static void cleanup(void) {
    if (serial_handle1 >= 0) {
        close(serial_handle1);
        serial_handle1 = -1;
    }
    if (serial_handle2 >= 0) {
        close(serial_handle2);
        serial_handle2 = -1;
    }
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    serial_handle1 = init_serial(SERIAL_PORT1, BAUD_RATE);
    if (serial_handle1 < 0) {
        gpioTerminate();
        return 1;
    }
    serial_handle2 = init_serial(SERIAL_PORT2, BAUD_RATE);
    if (serial_handle2 < 0) {
        close(serial_handle1);
        gpioTerminate();
        return 1;
    }

    printf("Dual-factor authentication system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        char code1[CODE_LENGTH + 1];
        char code2[CODE_LENGTH + 1];
        int rc1 = read_code(serial_handle1, code1, CODE_LENGTH + 1);
        int rc2 = read_code(serial_handle2, code2, CODE_LENGTH + 1);

        if (rc1 == 0 && rc2 == 0) {
            if (codes_match(code1, code2) && codes_match(code1, EXPECTED_CODE)) {
                printf("Authentication successful. Code: %s\n", code1);
                if (unlock_doors() != 0) {
                    fprintf(stderr, "Error during unlock sequence.\n");
                }
            } else {
                fprintf(stderr, "Authentication failed. Received: %s (port1), %s (port2)\n", code1, code2);
            }
        } else if (rc1 != 0) {
            fprintf(stderr, "Timeout on port1 after %d seconds.\n", READ_TIMEOUT_SEC);
        } else if (rc2 != 0) {
            fprintf(stderr, "Timeout on port2 after %d seconds.\n", READ_TIMEOUT_SEC);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

