#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN      4
#define RELAY_PIN    17
#define CHIP_NAME    "gpiochip0"
#define STRIKE_MS    1000
#define POLL_MS      50
#define FAILSAFE_MS  10000

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_msg(int priority, const char *msg)
{
    syslog(priority, "%s", msg);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open %s: %s", CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get relay line %d: %s", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(pir_line, "door_strike_pir") < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "door_strike_relay", 0) < 0) {
        syslog(LOG_ERR, "Failed to request relay line as output: %s", strerror(errno));
        goto cleanup;
    }

    log_msg(LOG_INFO, "Door strike system started.");

    while (running) {
        int pir_val = gpiod_line_get_value(pir_line);
        if (pir_val < 0) {
            syslog(LOG_ERR, "Failed to read PIR line: %s", strerror(errno));
            usleep(POLL_MS * 1000);
            continue;
        }

        if (pir_val == 1) {
            log_msg(LOG_INFO, "Motion detected on PIR pin.");
            if (gpiod_line_set_value(relay_line, 1) < 0) {
                syslog(LOG_ERR, "Failed to energize relay: %s", strerror(errno));
            } else {
                log_msg(LOG_INFO, "Relay energized for strike.");
            }

            struct timespec strike_start;
            clock_gettime(CLOCK_MONOTONIC, &strike_start);
            while (running) {
                struct timespec now;
                clock_gettime(CLOCK_MONOTONIC, &now);
                long elapsed_ms = (now.tv_sec - strike_start.tv_sec) * 1000L +
                                  (now.tv_nsec - strike_start.tv_nsec) / 1000000L;
                if (elapsed_ms >= STRIKE_MS) {
                    break;
                }
                usleep(10000);
            }

            if (gpiod_line_set_value(relay_line, 0) < 0) {
                syslog(LOG_ERR, "Failed to de-energize relay: %s", strerror(errno));
            } else {
                log_msg(LOG_INFO, "Relay de-energized.");
            }

            struct timespec failsafe_start;
            clock_gettime(CLOCK_MONOTONIC, &failsafe_start);
            while (running) {
                int pir_val2 = gpiod_line_get_value(pir_line);
                if (pir_val2 < 0) {
                    syslog(LOG_ERR, "Failed to read PIR line during failsafe: %s", strerror(errno));
                    break;
                }
                if (pir_val2 == 0) {
                    break;
                }
                struct timespec now;
                clock_gettime(CLOCK_MONOTONIC, &now);
                long elapsed_ms2 = (now.tv_sec - failsafe_start.tv_sec) * 1000L +
                                   (now.tv_nsec - failsafe_start.tv_nsec) / 1000000L;
                if (elapsed_ms2 >= FAILSAFE_MS) {
                    if (gpiod_line_set_value(relay_line, 0) < 0) {
                        syslog(LOG_ERR, "Failed to de-energize relay during failsafe: %s", strerror(errno));
                    } else {
                        log_msg(LOG_WARNING, "Potential malfunction: PIR HIGH for >10s. De-energizing relay.");
                    }
                    break;
                }
                usleep(POLL_MS * 1000);
            }
        }
        usleep(POLL_MS * 1000);
    }

    log_msg(LOG_INFO, "Shutting down.");
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    return EXIT_SUCCESS;

cleanup:
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret;
}

