#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <stdbool.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define RELAY_ON 0
#define RELAY_OFF 1

#define ACTIVATION_DURATION 300
#define PAUSE_DURATION 60
#define TIMER_INTERVAL 60

static const int relay_pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
static const int num_relays = 4;

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    for (int i = 0; i < num_relays; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            syslog(LOG_ERR, "Failed to set GPIO %d as output", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_pins[i], RELAY_OFF) != 0) {
            syslog(LOG_ERR, "Failed to initialize GPIO %d to OFF", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void activate_relay(int pin) {
    if (gpioWrite(pin, RELAY_ON) != 0) {
        syslog(LOG_ERR, "Failed to activate relay on GPIO %d", pin);
    } else {
        char message[128];
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        snprintf(message, sizeof(message), "Relay on GPIO %d activated", pin);
        log_message(message);
    }
}

static void deactivate_relay(int pin) {
    if (gpioWrite(pin, RELAY_OFF) != 0) {
        syslog(LOG_ERR, "Failed to deactivate relay on GPIO %d", pin);
    } else {
        char message[128];
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        snprintf(message, sizeof(message), "Relay on GPIO %d deactivated", pin);
        log_message(message);
    }
}

static void timer_callback(void *user_data) {
    (void)user_data;
    static int current_relay_index = 0;
    static bool is_activating = false;
    static int remaining_time = 0;

    if (!is_activating) {
        activate_relay(relay_pins[current_relay_index]);
        is_activating = true;
        remaining_time = ACTIVATION_DURATION;
    } else {
        remaining_time--;
        if (remaining_time <= 0) {
            deactivate_relay(relay_pins[current_relay_index]);
            is_activating = false;
            remaining_time = PAUSE_DURATION;
            current_relay_index = (current_relay_index + 1) % num_relays;
        }
    }
}

static void cleanup(void) {
    for (int i = 0; i < num_relays; i++) {
        gpioWrite(relay_pins[i], RELAY_OFF);
    }
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set timer function");
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("Irrigation system started");

    while (program_running) {
        sleep(1);
    }

    log_message("Shutting down irrigation system");
    cleanup();
    return EXIT_SUCCESS;
}

