        remaining_time = ACTIVATION_DURATION;
    } else {
        remaining_time--;
        if (remaining_time <= 0) {
            deactivate_relay(relay_pins[current_relay_index]);
            is_activating = false;
            remaining_time = PAUSE_DURATION;
            current_relay_index = (current_relay_index + 1) % num_relays;
