    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set timer function");
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("Irrigation system started");

    while (program_running) {
        sleep(1);
    }

    log_message("Shutting down irrigation system");
    cleanup();
    return EXIT_SUCCESS;
}

