#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_RATE_HZ)

typedef struct {
    float x, y, z;
} AccelData;

typedef struct {
    AccelData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static CircularBuffer buffer;
static int sysfs_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, ACCEL_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_accel(int fd, AccelData *out) {
    uint8_t raw[6];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, raw, 6) < 0) return -1;
    int16_t x = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t y = (int16_t)((raw[2] << 8) | raw[3]);
    int16_t z = (int16_t)((raw[4] << 8) | raw[5]);
    out->x = (float)x / 16384.0f;
    out->y = (float)y / 16384.0f;
    out->z = (float)z / 16384.0f;
    return 0;
}

static void buffer_add(CircularBuffer *b, AccelData d) {
    b->data[b->head] = d;
    b->head = (b->head + 1) % BUFFER_SIZE;
    if (b->count < BUFFER_SIZE) b->count++;
}

static void buffer_read_latest(CircularBuffer *b, AccelData *out) {
    if (b->count == 0) {
        memset(out, 0, sizeof(*out));
        return;
    }
    int idx = (b->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    *out = b->data[idx];
}

static void timer_handler(union sigval sv) {
    (void)sv;
    AccelData d;
    if (read_accel(i2c_fd, &d) == 0) {
        buffer_add(&buffer, d);
    }
}

static int create_sysfs_file(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to create sysfs file %s: %s\n", path, strerror(errno));
        return -1;
    }
    close(fd);
    return 0;
}

static int write_sysfs_file(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open sysfs file %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, value, strlen(value)) < 0) {
        fprintf(stderr, "Failed to write sysfs file %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    buffer.head = 0;
    buffer.count = 0;

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    timer_t timer_id;
    if (timer_create(CLOCK_MONOTONIC, &sev, &timer_id) < 0) {
        fprintf(stderr, "Failed to create timer: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    struct itimerspec its;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = SAMPLE_PERIOD_NS;
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = SAMPLE_PERIOD_NS;
    if (timer_settime(timer_id, 0, &its, NULL) < 0) {
        fprintf(stderr, "Failed to set timer: %s\n", strerror(errno));
        timer_delete(timer_id);
        close(i2c_fd);
        return 1;
    }

    if (create_sysfs_file("/sys/kernel/mpu6050_accel/latest") < 0) {
        close(i2c_fd);
        return 1;
    }

    printf("MPU6050 data logging started. Press Ctrl+C to exit.\n");

    while (running) {
        pause();
    }

    printf("\nShutting down...\n");
    timer_delete(timer_id);
    close(i2c_fd);
    close(sysfs_fd);
    return 0;
}

