#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define GPIO_CHIP "/dev/gpiochip0"

static const unsigned int relay_pins[NUM_RELAYS] = {18, 23, 24, 25};
static const int prime_intervals[NUM_RELAYS] = {2, 3, 5, 7};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static long long monotonic_ms(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return -1;
    }
    return (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "smart-lighting", 0) != 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    long long last_toggle[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++) {
        last_toggle[i] = monotonic_ms();
        if (last_toggle[i] < 0) {
            fprintf(stderr, "Failed to initialize monotonic time: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    while (program_running) {
        long long current_ms = monotonic_ms();
        if (current_ms < 0) {
            fprintf(stderr, "Failed to get monotonic time: %s\n", strerror(errno));
            break;
        }

        for (int i = 0; i < NUM_RELAYS; i++) {
            long long elapsed = current_ms - last_toggle[i];
            if (elapsed >= (long long)prime_intervals[i] * 1000LL) {
                int current_state = gpiod_line_get_value(lines[i]);
                if (current_state < 0) {
                    fprintf(stderr, "Failed to read GPIO line %u: %s\n", relay_pins[i], strerror(errno));
                    goto cleanup;
                }

                if (gpiod_line_set_value(lines[i], current_state == 0 ? 1 : 0) != 0) {
                    fprintf(stderr, "Failed to write GPIO line %u: %s\n", relay_pins[i], strerror(errno));
                    goto cleanup;
                }

                last_toggle[i] = current_ms;
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("Smart Lighting System stopped.\n");
    return ret;
}

