#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 Registers
#define MPU6050_ADDR 0x68
#define WHO_AM_I 0x75
#define WHO_AM_I_VAL 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Gyroscope sensitivity for +/- 250 degrees/sec range
#define GYRO_SENSITIVITY 131.0f

// Circular buffer size
#define BUFFER_SIZE 100

// Threshold for angular velocity
#define THRESHOLD 50.0f

// Global variables
static int i2c_fd = -1;
static volatile sig_atomic_t running = 1;

// Circular buffer structure
typedef struct {
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer gyro_buffer;

// Function prototypes
int init_i2c();
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(CircularBuffer *buffer, float x, float y, float z);
void check_threshold(float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup function to release I2C resources
void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus /dev/i2c-1: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to acquire I2C bus access or talk to slave 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize MPU-6050 sensor
int init_mpu6050() {
    uint8_t buf[2];

    // Verify device identity
    buf[0] = WHO_AM_I;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Error: Failed to write WHO_AM_I register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I value: %s\n", strerror(errno));
        return -1;
    }
    if (buf[0] != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch. Expected 0x%02X, got 0x%02X\n", WHO_AM_I_VAL, buf[0]);
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep bit in PWR_MGMT_1)
    buf[0] = PWR_MGMT_1;
    buf[1] = 0x00;
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to write PWR_MGMT_1 register: %s\n", strerror(errno));
        return -1;
    }

    usleep(100000); // Wait 100ms for sensor to stabilize
    return 0;
}

// Read gyroscope data from MPU-6050
int read_gyro_data(float *x, float *y, float *z) {
    uint8_t buf[6];
    int16_t raw_x, raw_y, raw_z;

    // Read 6 bytes starting from GYRO_XOUT_H
    buf[0] = GYRO_XOUT_H;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Error: Failed to write GYRO_XOUT_H register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read gyroscope data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes (big-endian)
    raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert to degrees/second
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(CircularBuffer *buffer, float x, float y, float z) {
    buffer->x[buffer->head] = x;
    buffer->y[buffer->head] = y;
    buffer->z[buffer->head] = z;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Check if angular velocity exceeds threshold
void check_threshold(float x, float y, float z) {
    float magnitude = sqrtf(x * x + y * y + z * z);
    if (magnitude > THRESHOLD) {
        printf("Threshold exceeded! Magnitude: %.2f deg/s\n", magnitude);
    }
}

int main() {
    float x, y, z;

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("MPU-6050 gyroscope data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Add data to buffer
            add_to_buffer(&gyro_buffer, x, y, z);

            // Check threshold
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
        }

        usleep(10000); // 10ms delay
    }

    // Cleanup
    cleanup();
    printf("\nExiting gracefully.\n");

    return 0;
}

