/*
 * MH-Z19B CO2 monitor for Raspberry Pi 3 Model B+
 * Uses pigpio UART (serOpen/serWrite/serRead) on /dev/serial0 @ 9600 8N1.
 * Logs JSON to co2_log.json every 5 s; logs errors to co2_error.log.
 * Compile: gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lpigpio -lrt
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE    "/dev/serial0"
#define BAUD_RATE      9600
#define LOG_FILE       "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define READ_INTERVAL  5          /* seconds between readings */
#define READ_TIMEOUT   1000000    /* 1 s timeout for read completion */
#define READ_DELAY     100000     /* 100 ms command delay */
#define MAX_RETRIES    10         /* retries for partial read */
#define RESP_LEN       9

static volatile sig_atomic_t g_running = 1;
static int  g_uart = -1;
static FILE *g_log  = NULL;
static FILE *g_err  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
    size_t pos = strlen(buf);
    if (pos + 8 < len)
        snprintf(buf + pos, len - pos, ".%06ldZ", ts.tv_nsec / 1000);
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof ts);
    if (g_err) {
        fprintf(g_err, "%s: %s\n", ts, msg);
        fflush(g_err);
    }
    fprintf(stderr, "%s: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Open log files                                                      */
/* ------------------------------------------------------------------ */
static int open_files(void)
{
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    g_err = fopen(ERROR_LOG_FILE, "a");
    if (!g_err) {
        perror("fopen(" ERROR_LOG_FILE ")");
        fclose(g_log);
        g_log = NULL;
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Open UART                                                           */
/* ------------------------------------------------------------------ */
static int open_uart(void)
{
    g_uart = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (g_uart < 0) {
        log_error("serOpen failed");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read exactly n bytes from UART with timeout                         */
/* ------------------------------------------------------------------ */
static int read_exact(uint8_t *buf, int n)
{
    int total = 0;
    int waited = 0;
    while (total < n && waited < READ_TIMEOUT) {
        int avail = serDataAvailable(g_uart);
        if (avail < 0) {
            log_error("serDataAvailable failed");
            return -1;
        }
        if (avail > 0) {
            int to_read = (avail < (n - total)) ? avail : (n - total);
            int r = serRead(g_uart, (char *)(buf + total), to_read);
            if (r < 0) {
                log_error("serRead failed");
                return -1;
            }
            total += r;
            waited = 0;
        } else {
            gpioDelay(1000);          /* 1 ms */
            waited += 1000;
        }
    }
    if (total < n) {
        log_error("UART read timeout: partial data");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read CO2 from MH-Z19B                                               */
/* ------------------------------------------------------------------ */
static int read_co2(uint16_t *co2)
{
    uint8_t cmd[9] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    uint8_t resp[RESP_LEN];

    if (serWrite(g_uart, (char *)cmd, sizeof cmd) != (int)sizeof cmd) {
        log_error("serWrite (command) failed");
        return -1;
    }
    gpioDelay(READ_DELAY);

    if (read_exact(resp, RESP_LEN) != 0)
        return -1;

    /* Checksum: sum bytes 1..7, invert, increment by 1 */
    uint8_t calc = 0;
    for (int i = 1; i < 8; i++)
        calc += resp[i];
    calc = (uint8_t)(0xFF - calc + 1);
    if (calc != resp[8]) {
        log_error("Checksum mismatch");
        return -1;
    }

    *co2 = (uint16_t)((resp[2] << 8) | resp[3]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one JSON line to log file                                    */
/* ------------------------------------------------------------------ */
static void log_data(uint16_t co2, int error)
{
    char ts[32];
    get_timestamp(ts, sizeof ts);

    if (g_log) {
        fprintf(g_log,
            "{\"timestamp\":\"%s\",\"co2_ppm\":%u,\"error\":%d}\n",
            ts, co2, error);
        fflush(g_log);
    }
    printf("{\"timestamp\":\"%s\",\"co2_ppm\":%u,\"error\":%d}\n",
           ts, co2, error);
}

