/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart >= 0) {
        serClose(g_uart);
        g_uart = -1;
    }
    if (g_log) { fclose(g_log); g_log = NULL; }
    if (g_err) { fclose(g_err); g_err = NULL; }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
