    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        log_error("gpioInitialise failed");
        return EXIT_FAILURE;
    }

    if (open_files() != 0)
        return EXIT_FAILURE;

    if (open_uart() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    uint16_t co2;
    while (g_running) {
        int err = read_co2(&co2);
        log_data(err ? 0 : co2, err);
        sleep(READ_INTERVAL);
    }

    cleanup();
