#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA 0x03

#define GPIO_PIN 17
#define TARGET_HEADING 90.0
#define HEADING_THRESHOLD 10.0
#define SAMPLE_INTERVAL_US 100000
#define CIRCULAR_BUFFER_SIZE 100

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    float buffer[CIRCULAR_BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cb_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % CIRCULAR_BUFFER_SIZE;
    if (cb->count < CIRCULAR_BUFFER_SIZE) cb->count++;
}

static int hmc5883l_init(int handle) {
    if (i2cWriteByteData(handle, HMC5883L_CONFIG_A, 0x70) < 0) return -1;
    if (i2cWriteByteData(handle, HMC5883L_CONFIG_B, 0x20) < 0) return -1;
    if (i2cWriteByteData(handle, HMC5883L_MODE, 0x00) < 0) return -1;
    return 0;
}

static int hmc5883l_read(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    if (i2cReadI2CBlockData(handle, HMC5883L_DATA, data, 6) != 6) return -1;
    *x = (int16_t)((data[0] << 8) | (data[1] & 0xFF));
    *z = (int16_t)((data[2] << 8) | (data[3] & 0xFF));
    *y = (int16_t)((data[4] << 8) | (data[5] & 0xFF));
    return 0;
}

static float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2f((float)y, (float)x) * 180.0 / M_PI;
    if (heading < 0) heading += 360.0;
    return heading;
}

static float compensate_heading(int16_t x, int16_t y, float x_offset, float y_offset) {
    return calculate_heading(x - x_offset, y - y_offset);
}

static void control_gpio(int state) {
    gpioWrite(GPIO_PIN, state);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (hmc5883l_init(i2c_handle) < 0) {
        fprintf(stderr, "Error initializing HMC5883L\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    CircularBuffer heading_buffer;
    cb_init(&heading_buffer);

    int16_t x, y, z;
    float compensated_heading;
    float x_offset = 100.0;
    float y_offset = -50.0;

    while (running) {
        if (hmc5883l_read(i2c_handle, &x, &y, &z) == 0) {
            compensated_heading = compensate_heading(x, y, x_offset, y_offset);
            cb_add(&heading_buffer, compensated_heading);

            if (fabsf(compensated_heading - TARGET_HEADING) > HEADING_THRESHOLD) {
                control_gpio(1);
            } else {
                control_gpio(0);
            }

            printf("Heading: %.2f, Target: %.2f, Threshold: %.2f\n",
                   compensated_heading, TARGET_HEADING, HEADING_THRESHOLD);
        } else {
            fprintf(stderr, "Error reading HMC5883L data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(GPIO_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

