#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define RED_RELAY_PIN   17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN  22
#define BH1750_ADDR     0x23
#define I2C_BUS         "/dev/i2c-1"
#define LOG_FILE        "lighting_log.txt"
#define LUX_THRESHOLD_LOW   50.0f
#define LUX_THRESHOLD_MEDIUM 150.0f
#define LUX_THRESHOLD_HIGH  300.0f
#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_CONV_TIME_MS 120

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void cleanup(void) {
    if (red_line) { gpiod_line_release(red_line); red_line = NULL; }
    if (green_line) { gpiod_line_release(green_line); green_line = NULL; }
    if (blue_line) { gpiod_line_release(blue_line); blue_line = NULL; }
    if (chip) { gpiod_chip_close(chip); chip = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
    if (log_fp) { fclose(log_fp); log_fp = NULL; }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    red_line = gpiod_chip_get_line(chip, RED_RELAY_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_RELAY_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_RELAY_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(red_line, "smart_lighting", 0) < 0 ||
        gpiod_line_request_output(green_line, "smart_lighting", 0) < 0 ||
        gpiod_line_request_output(blue_line, "smart_lighting", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_bh1750(float *lux) {
    unsigned char cmd = BH1750_CONT_HIGH_RES;
    if (write(i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 write command failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_TIME_MS * 1000);

    unsigned char buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "BH1750 read failed: %s\n", strerror(errno));
        return -1;
    }
    unsigned int raw = (buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void set_relay_states(int red, int green, int blue) {
    gpiod_line_set_value(red_line, red);
    gpiod_line_set_value(green_line, green);
    gpiod_line_set_value(blue_line, blue);
}

static void log_data(float lux, int red, int green, int blue) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_fp, "%s, Lux: %.2f, Red: %d, Green: %d, Blue: %d\n", ts, lux, red, green, blue);
    fflush(log_fp);
}

static void control_lights(float lux) {
    int red, green, blue;
    if (lux < LUX_THRESHOLD_LOW) {
