        red = 1; green = 0; blue = 0;
    } else if (lux < LUX_THRESHOLD_MEDIUM) {
        red = 0; green = 1; blue = 0;
    } else if (lux < LUX_THRESHOLD_HIGH) {
        red = 0; green = 0; blue = 1;
    } else {
        red = 1; green = 1; blue = 1;
    }
    set_relay_states(red, green, blue);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (init_i2c() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        float lux;
        if (read_bh1750(&lux) < 0) {
            fprintf(stderr, "Sensor read error, retrying in 1s...\n");
            sleep(1);
            continue;
        }
        control_lights(lux);
        log_data(lux, gpiod_line_get_value(red_line), gpiod_line_get_value(green_line), gpiod_line_get_value(blue_line));
        sleep(1);
    }

    set_relay_states(0, 0, 0);
    cleanup();
    return EXIT_SUCCESS;
}

