static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_gpio_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_gpio_pwm_start(unsigned gpio, unsigned duty) {
    if (gpioPWM(gpio, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %u) failed\n", gpio, duty);
        return -1;
    }
    return 0;
}

static int safe_gpio_pwm_stop(unsigned gpio) {
    if (gpioPWM(gpio, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM(%u, 0) failed\n", gpio);
        return -1;
    }
    return 0;
}

static int safe_gpio_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_gpio_set_pull(unsigned gpio, unsigned pud) {
    if (gpioSetPullUpDown(gpio, pud) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%u, %u) failed\n", gpio, pud);
        return -1;
    }
    return 0;
}

static int safe_gpio_set_freq_range(unsigned freq, unsigned range) {
    if (gpioSetPWMfrequency(MOTOR_A_IN2, freq) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%u) failed\n", freq);
        return -1;
    }
    if (gpioSetPWMrange(MOTOR_A_IN2, range) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%u) failed\n", range);
        return -1;
    }
    return 0;
}

static int map_distance_to_duty(float distance) {
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;
    float duty = 255.0f - ((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * 255.0f;
    return (int)duty;
}

static int control_motor(unsigned in1, unsigned in2, unsigned in3, unsigned in4, float distance) {
    int duty = map_distance_to_duty(distance);
    if (safe_gpio_write(in1, 1) < 0) return -1;
    if (safe_gpio_write(in2, 0) < 0) return -1;
    if (safe_gpio_write(in3, 1) < 0) return -1;
    if (safe_gpio_write(in4, 0) < 0) return -1;
    if (safe_gpio_pwm_start(in2, duty) < 0) return -1;
    if (safe_gpio_pwm_start(in4, duty) < 0) return -1;
