        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (safe_gpio_set_mode(MOTOR_A_IN1, PI_OUTPUT) < 0 ||
