        gpioTerminate();
        return 1;
    }

    float distance_a = 60.0f;
    float distance_b = 70.0f;

    while (running) {
        if (distance_a < DISTANCE_THRESHOLD) {
            if (control_motor(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, distance_a) < 0) {
                break;
            }
        } else {
            if (stop_motor(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4) < 0) {
                break;
            }
        }

        if (distance_b < DISTANCE_THRESHOLD) {
            if (control_motor(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, distance_b) < 0) {
