#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define IN1 17
#define IN2 18
#define IN3 27
#define IN4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

#define STEPS_PER_REV 2048
#define STEP_DELAY_US 2000
#define LOCK_STEPS (STEPS_PER_REV / 4)

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void deenergize(void) {
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
}

static int setup_gpio(void) {
    if (gpioSetMode(IN1, PI_OUTPUT) != 0) return -1;
    if (gpioSetMode(IN2, PI_OUTPUT) != 0) return -1;
    if (gpioSetMode(IN3, PI_OUTPUT) != 0) return -1;
    if (gpioSetMode(IN4, PI_OUTPUT) != 0) return -1;
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) return -1;
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) return -1;
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0) return -1;
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) return -1;
    deenergize();
    return 0;
}

static void step_clockwise(void) {
    gpioWrite(IN1, 1);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 1);
    gpioDelay(STEP_DELAY_US);
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 1);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY_US);
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 1);
    gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY_US);
    gpioWrite(IN1, 1);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY_US);
}

static void step_counter_clockwise(void) {
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 1);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY_US);
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 1);
    gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY_US);
    gpioWrite(IN1, 1);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY_US);
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 1);
    gpioDelay(STEP_DELAY_US);
}

static void lock_door(void) {
    printf("Locking door...\n");
    for (int i = 0; i < LOCK_STEPS && running; i++) {
        step_clockwise();
    }
    if (running) printf("Door locked.\n");
}

static void unlock_door(void) {
    printf("Unlocking door...\n");
    for (int i = 0; i < LOCK_STEPS && running; i++) {
        step_counter_clockwise();
    }
    if (running) printf("Door unlocked.\n");
}

