#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <sys/stat.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 20000000
#define PWM_DUTY_MAX 18000000
#define PWM_DUTY_MIN 2000000
#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define SAMPLE_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int pwm_exported = 0;
static int pwm_enabled = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int init_i2c(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int init_mpu6050(int fd) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
            fprintf(stderr, "Failed to wake MPU-6050 (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        usleep(100000);
        uint8_t whoami = 0;
        if (i2c_read_reg8(fd, 0x75, &whoami) < 0) {
            fprintf(stderr, "Failed to read WHO_AM_I (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (whoami != 0x68) {
            fprintf(stderr, "WHO_AM_I mismatch: 0x%02X (expected 0x68, attempt %d)\n", whoami, retries + 1);
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (i2c_write_reg8(fd, ACCEL_CONFIG, 0x00) < 0) {
            fprintf(stderr, "Failed to set ACCEL_CONFIG (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (i2c_write_reg8(fd, GYRO_CONFIG, 0x00) < 0) {
            fprintf(stderr, "Failed to set GYRO_CONFIG (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        return 0;
    }
    fprintf(stderr, "MPU-6050 initialization failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

static int init_pwm(void) {
    char path[256];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        if (errno != EBUSY) {
            fprintf(stderr, "Failed to open PWM export: %s\n", strerror(errno));
            return -1;
        }
    } else {
        if (write(fd, "0", 1) < 0) {
            fprintf(stderr, "Failed to export PWM channel: %s\n", strerror(errno));
            close(fd);
            return -1;
        }
        close(fd);
        pwm_exported = 1;
    }
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm0/period", PWM_CHIP);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM period: %s\n", strerror(errno));
        return -1;
    }
    char buf[32];
    snprintf(buf, sizeof(buf), "%d", PWM_PERIOD_NS);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Failed to set PWM period: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm0/duty_cycle", PWM_CHIP);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM duty_cycle: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, "0", 1) < 0) {
        fprintf(stderr, "Failed to set initial duty cycle: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm0/enable", PWM_CHIP);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM enable: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, "1", 1) < 0) {
        fprintf(stderr, "Failed to enable PWM: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    pwm_enabled = 1;
    return 0;
}

static int set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int duty = PWM_DUTY_MIN + (int)(((float)angle / 180.0f) * (PWM_DUTY_MAX - PWM_DUTY_MIN));
    char path[256];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm0/duty_cycle", PWM_CHIP);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM duty_cycle: %s\n", strerror(errno));
        return -1;
    }
    char buf[32];
    snprintf(buf, sizeof(buf), "%d", duty);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int read_mpu6050(int fd, float *pitch, float *roll) {
    uint8_t buf[14];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 14) < 0) {
        fprintf(stderr, "Failed to read MPU-6050 data: %s\n", strerror(errno));
        return -1;
    }
    int16_t ax = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t ay = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t az = (int16_t)((buf[4] << 8) | buf[5]);
    int16_t gx = (int16_t)((buf[8] << 8) | buf[9]);
    int16_t gy = (int16_t)((buf[10] << 8) | buf[11]);
    int16_t gz = (int16_t)((buf[12] << 8) | buf[13]);
    float ax_f = (float)ax / 16384.0f;
    float ay_f = (float)ay / 16384.0f;
    float az_f = (float)az / 16384.0f;
    float gx_f = (float)gx / 131.0f;
    float gy_f = (float)gy / 131.0f;
    float gz_f = (float)gz / 131.0f;
    *pitch = atan2f(ay_f, az_f) * 180.0f / M_PI;
    *roll = atan2f(-ax_f, az_f) * 180.0f / M_PI;
    return 0;
}

static int log_data(float pitch, float roll, int angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, pitch, roll, angle);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (pwm_enabled) {
        char path[256];
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm0/duty_cycle", PWM_CHIP);
        int fd = open(path, O_WRONLY);
        if (fd >= 0) {
            write(fd, "0", 1);
            close(fd);
        }
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm0/enable", PWM_CHIP);
        fd = open(path, O_WRONLY);
        if (fd >= 0) {
            write(fd, "0", 1);
            close(fd);
        }
    }
    if (pwm_exported) {
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/unexport", PWM_CHIP);
        int fd = open(path, O_WRONLY);
        if (fd >= 0) {
            write(fd, "0", 1);
            close(fd);
        }
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        return 1;
    }
    if (init_mpu6050(i2c_fd) < 0) {
        cleanup();
        return 1;
    }
    if (init_pwm() < 0) {
        cleanup();
        return 1;
    }

    float pitch = 0.0f, roll = 0.0f;
    int angle = 90;
    int last_angle = angle;
    float pitch_offset = 0.0f;
    float roll_offset = 0.0f;
    float pitch_gain = 0.1f;
    float roll_gain = 0.1f;
    float angle_rate = 1.0f;

    while (running) {
        if (read_mpu6050(i2c_fd, &pitch, &roll) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }
        pitch -= pitch_offset;
        roll -= roll_offset;
        angle += (int)(pitch_gain * pitch + roll_gain * roll) * angle_rate;
        if (angle < 0) angle = 0;
        if (angle > 180) angle = 180;
        if (angle != last_angle) {
            if (set_servo_angle(angle) == 0) {
                last_angle = angle;
            }
        }
        if (log_data(pitch, roll, angle) < 0) {
            fprintf(stderr, "Logging failed.\n");
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

