#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define FADE_DURATION 1800
#define SCHEDULE_FILE "lighting_schedule.txt"

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};

typedef struct {
    int hour;
    int minute;
    int second;
    int relay;
    int state;
} schedule_entry_t;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int parse_schedule(const char *filename, schedule_entry_t *schedule, int max_entries) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }

    int count = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) && count < max_entries) {
        char *token = strtok(line, ",");
        if (!token) continue;
        int hour = atoi(token);

        token = strtok(NULL, ",");
        if (!token) continue;
        int minute = atoi(token);

        token = strtok(NULL, ",");
        if (!token) continue;
        int second = atoi(token);

        token = strtok(NULL, ",");
        if (!token) continue;
        int relay = atoi(token);

        token = strtok(NULL, ",");
        if (!token) continue;
        int state = atoi(token);

        if (hour < 0 || hour > 23 || minute < 0 || minute > 59 || second < 0 || second > 59 ||
            relay < 0 || relay >= NUM_RELAYS || state != 0 && state != 1) {
            fprintf(stderr, "Invalid schedule entry: %s", line);
            continue;
        }

        schedule[count].hour = hour;
        schedule[count].minute = minute;
        schedule[count].second = second;
        schedule[count].relay = relay;
        schedule[count].state = state;
        count++;
    }

    fclose(fp);
    return count;
}

static int set_relay(int pin, int state) {
    if (gpioPWM(pin, state ? PWM_RANGE : 0) != 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static void fade_relay(int pin, int target_state, int duration) {
    int current_state = gpioGetPWMdutycycle(pin);
    if (current_state < 0) {
        fprintf(stderr, "Error reading PWM duty cycle on GPIO %d\n", pin);
        return;
    }

    int steps = duration;
    int step_delay = 1000000 / steps;

    for (int i = 0; i <= steps && running; i++) {
        int new_state = current_state + (target_state - current_state) * i / steps;
        if (new_state < 0) new_state = 0;
        if (new_state > PWM_RANGE) new_state = PWM_RANGE;

        if (gpioPWM(pin, new_state) != 0) {
            fprintf(stderr, "Error setting PWM on GPIO %d\n", pin);
            return;
        }
        gpioDelay(step_delay);
    }

    if (set_relay(pin, target_state) != 0) {
        fprintf(stderr, "Error finalizing relay state on GPIO %d\n", pin);
    }
}

static void apply_schedule(const schedule_entry_t *schedule, int num_entries) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    if (!tm_info) {
        perror("localtime failed");
        return;
    }

    for (int i = 0; i < num_entries; i++) {
        if (tm_info->tm_hour == schedule[i].hour &&
            tm_info->tm_min == schedule[i].minute &&
            tm_info->tm_sec == schedule[i].second) {
            int pin = relay_pins[schedule[i].relay];
            fade_relay(pin, schedule[i].state, FADE_DURATION);
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY) != 0) {
            fprintf(stderr, "Error setting PWM frequency on GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(relay_pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error setting PWM range on GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (set_relay(relay_pins[i], 0) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    schedule_entry_t schedule[100];
    int num_entries = parse_schedule(SCHEDULE_FILE, schedule, sizeof(schedule) / sizeof(schedule[0]));
    if (num_entries < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart home lighting system started. Press Ctrl+C to exit.\n");

    while (running) {
        apply_schedule(schedule, num_entries);
        sleep(1);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay(relay_pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

