        return -1.0f;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout (sensor absent?)\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout (stuck high?)\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    /* speed of sound ~343 m/s => 1 cm = 100 us round trip */
    float distance = (float)pulse_us / 100.0f / 2.0f;
    return distance;
}

static int map_distance_to_frequency(float distance)
{
    if (distance < 0.0f) return -1;
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    float freq = MIN_FREQUENCY_HZ +
                 (distance - MIN_DISTANCE_CM) *
                 (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM);

    if (freq < MIN_FREQUENCY_HZ) freq = MIN_FREQUENCY_HZ;
    if (freq > MAX_FREQUENCY_HZ) freq = MAX_FREQUENCY_HZ;
    return (int)freq;
}

static void set_buzzer_frequency(int frequency)
{
    if (frequency < 0) {
        gpioPWM(BUZZER_PIN, 0);
        return;
    }
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", frequency);
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) {
        fprintf(stderr, "Error: gpioPWM write failed\n");
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioPWM(BUZZER_PIN, 0);

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("Theremin running. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = read_distance();

        if (distance < 0.0f) {
            /* Sensor error: silence buzzer and wait */
            gpioPWM(BUZZER_PIN, 0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int frequency = map_distance_to_frequency(distance);
        if (frequency < 0) {
            gpioPWM(BUZZER_PIN, 0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        set_buzzer_frequency(frequency);

        /* Enforce minimum 60 ms gap between measurements */
        gpioDelay(MEASURE_GAP_US);
    }

    /* Graceful shutdown */
    gpioPWM(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

