#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_FREQ  1000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_pwm_start(unsigned pin, unsigned duty) {
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %u) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

static void safe_pwm_stop(unsigned pin) {
    gpioPWM(pin, 0);
}

static void cleanup(void) {
    safe_pwm_stop(RED_PIN);
    safe_pwm_stop(GREEN_PIN);
    safe_pwm_stop(BLUE_PIN);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(RED_PIN, PI_OUTPUT) < 0 ||
        safe_set_mode(GREEN_PIN, PI_OUTPUT) < 0 ||
        safe_set_mode(BLUE_PIN, PI_OUTPUT) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        double t = time(NULL) * 0.1;
        double proximity = 0.5 * (1.0 + sin(t));

        int red   = (int)(proximity * 255.0);
        int green = (int)((1.0 - proximity) * 255.0);
        int blue  = 0;

        if (safe_pwm_start(RED_PIN, red) < 0 ||
            safe_pwm_start(GREEN_PIN, green) < 0 ||
            safe_pwm_start(BLUE_PIN, blue) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        printf("Proximity: %.2f, R: %d, G: %d, B: %d\n", proximity, red, green, blue);
        fflush(stdout);

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

