#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <stdint.h>
#include <stdbool.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_US 50000  /* 50 ms */
#define PWM_DUTY_50PCT 128  /* 0-255 range */

/* Flash-stored melody: {frequency Hz, duration ms} */
static const int melody[][2] = {
    {262, 250}, {294, 250}, {330, 250}, {349, 250},
    {392, 250}, {440, 250}, {494, 250}, {523, 250}
};
static const int melody_len = sizeof(melody) / sizeof(melody[0]);

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t button_pressed = 0;
static volatile uint32_t last_press_tick = 0;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 0)  /* only act on falling edge (active-low) */
        return;

    uint32_t elapsed = tick - last_press_tick;
    if (elapsed < DEBOUNCE_US)
        return;
    last_press_tick = tick;

    button_pressed = 1;
}

static void play_tone(int freq, int duration_ms)
{
    if (freq <= 0) {
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
        gpioDelay(duration_ms * 1000);
        return;
    }

    if (gpioHardwarePWM(BUZZER_PIN, freq, PWM_DUTY_50PCT) < 0) {
        fprintf(stderr, "Warning: gpioHardwarePWM failed for freq %d\n", freq);
        return;
    }

    gpioDelay(duration_ms * 1000);

    if (gpioHardwarePWM(BUZZER_PIN, 0, 0) < 0)
        fprintf(stderr, "Warning: gpioHardwarePWM stop failed\n");
}

static void play_melody(void)
{
    for (int i = 0; i < melody_len; i++) {
        if (!running)
            break;
        play_tone(melody[i][0], melody[i][1]);
    }
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUTTON_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(BUTTON_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioHardwarePWM(BUZZER_PIN, 0, 0) < 0) {
        fprintf(stderr, "Error: initial gpioHardwarePWM off failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
