#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5
#define ALERT_THRESHOLD 3
#define DEFAULT_POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", timeinfo);
}

static void log_event(int value) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (log_file) {
        if (fprintf(log_file, "%s,%d\n", ts, value) < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        } else {
            if (fflush(log_file) != 0) {
                fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
            }
        }
    }
}

static void check_alert(const int events[], int size) {
    int high_count = 0;
    for (int i = 0; i < size; i++) {
        if (events[i] == 1) high_count++;
    }
    if (high_count >= ALERT_THRESHOLD) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        printf("EARTHQUAKE ALERT: %s - %d HIGH events in window\n", ts, high_count);
        fflush(stdout);
    }
}

int main(int argc, char *argv[]) {
    int poll_timeout_ms = DEFAULT_POLL_TIMEOUT_MS;
    if (argc > 1) {
        poll_timeout_ms = atoi(argv[1]);
        if (poll_timeout_ms <= 0) {
            fprintf(stderr, "Invalid poll timeout. Using default: %d ms\n", DEFAULT_POLL_TIMEOUT_MS);
            poll_timeout_ms = DEFAULT_POLL_TIMEOUT_MS;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        fclose(log_file);
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    struct gpiod_line_request_config config = {
        .consumer = "vibration_monitor",
        .request_type = GPIOD_LINE_REQUEST_EVENT_BOTH_EDGES,
        .flags = 0
    };

    if (gpiod_line_request(line, &config, 0) != 0) {
        fprintf(stderr, "Failed to request GPIO line %d for event monitoring: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    int events[WINDOW_SIZE];
    int event_index = 0;
    int event_count = 0;

    printf("Monitoring SW-420 vibration sensor on GPIO%d (poll timeout: %d ms). Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET, poll_timeout_ms);

    while (program_running) {
        struct timespec ts = { .tv_sec = poll_timeout_ms / 1000, .tv_nsec = (poll_timeout_ms % 1000) * 1000000L };
        int ret = gpiod_line_event_wait(line, &ts);

        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            break;
        }

        if (ret == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) != 0) {
            fprintf(stderr, "Error reading GPIO event: %s\n", strerror(errno));
            continue;
        }

        int value = (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) ? 1 : 0;
        log_event(value);

        events[event_index] = value;
        event_index = (event_index + 1) % WINDOW_SIZE;
        if (event_count < WINDOW_SIZE) {
            event_count++;
        }

        check_alert(events, event_count);
    }

    printf("\nExiting gracefully...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    if (log_file) {
        fclose(log_file);
    }
    return 0;
}

