#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* LSM303DLHC magnetometer I2C 7-bit address */
#define LSM303_MAG_ADDR 0x1E

/* LSM303DLHC magnetometer register addresses */
#define CRA_REG_M   0x00
#define MR_REG_M    0x02
#define OUT_X_H_M   0x03
#define OUT_X_L_M   0x04
#define OUT_Z_H_M   0x05
#define OUT_Z_L_M   0x06
#define OUT_Y_H_M   0x07
#define OUT_Y_L_M   0x08

/* Hard-iron calibration offsets (raw counts) */
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

/* Compass directions */
static const char *compass_directions[] = {
    "N", "NE", "E", "SE", "S", "SW", "W", "NW"
};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an LSM303DLHC register                            */
/* ------------------------------------------------------------------ */
static int lsm303_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an LSM303DLHC register                           */
/* ------------------------------------------------------------------ */
static int lsm303_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, value, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the six magnetometer data registers (X, Z, Y)                 */
/* ------------------------------------------------------------------ */
static int lsm303_read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t x_h, x_l, z_h, z_l, y_h, y_l;

    if (lsm303_read_reg(fd, OUT_X_H_M, &x_h) < 0) return -1;
    if (lsm303_read_reg(fd, OUT_X_L_M, &x_l) < 0) return -1;
    if (lsm303_read_reg(fd, OUT_Z_H_M, &z_h) < 0) return -1;
    if (lsm303_read_reg(fd, OUT_Z_L_M, &z_l) < 0) return -1;
    if (lsm303_read_reg(fd, OUT_Y_H_M, &y_h) < 0) return -1;
    if (lsm303_read_reg(fd, OUT_Y_L_M, &y_l) < 0) return -1;

    *x = (int16_t)((x_h << 8) | x_l);
    *z = (int16_t)((z_h << 8) | z_l);
    *y = (int16_t)((y_h << 8) | y_l);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Calibrate raw magnetometer data                                    */
/* ------------------------------------------------------------------ */
static void calibrate_magnetometer(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                                   float *cal_x, float *cal_y, float *cal_z)
{
    *cal_x = (float)raw_x - X_OFFSET;
    *cal_y = (float)raw_y - Y_OFFSET;
    *cal_z = (float)raw_z - Z_OFFSET;
}

/* ------------------------------------------------------------------ */
/* Compute compass heading in degrees (0-360)                         */
/* ------------------------------------------------------------------ */
static float calculate_heading(float cal_x, float cal_y)
{
    float heading = atan2f(cal_y, cal_x) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

/* ------------------------------------------------------------------ */
/* Map heading to one of eight compass directions                     */
/* ------------------------------------------------------------------ */
static const char *determine_compass_direction(float heading)
{
    int index = (int)(heading / 45.0f);
    if (index < 0) index = 0;
    if (index > 7) index = 7;
    return compass_directions[index];
}

/* ------------------------------------------------------------------ */
/* Append a CSV row                                                   */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float cal_x, float cal_y, float cal_z,
                    float heading)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f\n",
                timestamp, cal_x, cal_y, cal_z, heading) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush on log file failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t raw_x, raw_y, raw_z;
    float cal_x, cal_y, cal_z, heading;
    const char *log_filename = "mag_log.csv";

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(/dev/i2c-1) failed: %s\n", strerror(errno));
        return 1;
    }

    /* ---- Set slave address ---- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    /* ---- Configure LSM303DLHC: continuous-conversion mode ---- */
    if (lsm303_write_reg(g_i2c_fd, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to set continuous-conversion mode.\n");
        cleanup();
        return 1;
    }

    /* ---- Optional: set output data rate to 15 Hz ---- */
    if (lsm303_write_reg(g_i2c_fd, CRA_REG_M, 0x14) < 0) {
