#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_PIN      17
#define TOUCH_PIN      4
#define DEBOUNCE_MS    200
#define LOG_FILE       "relay_log.json"

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_last_tick = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_relay_state(int state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00");

    fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n",
            ts, state ? "ON" : "OFF");
    fclose(fp);
}

static void relay_toggle(void)
{
    int cur = gpioRead(RELAY_PIN);
    if (cur < 0) {
        fprintf(stderr, "gpioRead failed on pin %d\n", RELAY_PIN);
        return;
    }
    if (gpioWrite(RELAY_PIN, cur ? 0 : 1) < 0)
        fprintf(stderr, "gpioWrite failed on pin %d\n", RELAY_PIN);
    log_relay_state(cur ? 0 : 1);
}

static void touch_isr(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    if (level != 1)            /* only rising edge */
        return;

    uint32_t elapsed = tick - g_last_tick;   /* pigpio ticks are uint32; wraps handled by subtraction */
    if (elapsed < DEBOUNCE_MS * 1000)
        return;

    g_last_tick = tick;
    relay_toggle();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for relay pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for touch pin %d\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for touch pin %d\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite failed to initialise relay pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFunc(TOUCH_PIN, RISING_EDGE, 0, touch_isr) < 0) {
        fprintf(stderr, "gpioSetISRFunc failed for touch pin %d\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioSetISRFunc(TOUCH_PIN, RISING_EDGE, 0, NULL);
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Relay control started. Touch GPIO4 to toggle relay on GPIO17.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running)
        gpioDelay(100000);   /* 100 ms */

    /* Clean shutdown */
    gpioWrite(RELAY_PIN, 0);
    log_relay_state(0);
    gpioSetISRFunc(TOUCH_PIN, RISING_EDGE, 0, NULL);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

