#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define MOISTURE_THRESHOLD 30
#define RELAY_ON_TIME_SEC 5
#define POLL_INTERVAL_SEC 10
#define LOG_FILE "irrigation_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 23, 24, 25};
static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS] = {NULL};

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Error: Failed to get GPIO line %u: %s\n",
                    relay_pins[i], strerror(errno));
            return -1;
        }

        if (gpiod_line_request_output(relay_lines[i], "irrigation", 1) < 0) {
            fprintf(stderr, "Error: Failed to request GPIO %u as output: %s\n",
                    relay_pins[i], strerror(errno));
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 1);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int activate_relay(int relay_num, int duration_sec) {
    if (relay_num < 0 || relay_num >= NUM_RELAYS) {
        fprintf(stderr, "Error: Invalid relay number %d\n", relay_num);
        return -1;
    }

    if (gpiod_line_set_value(relay_lines[relay_num], 0) < 0) {
        fprintf(stderr, "Error: Failed to activate relay %d: %s\n",
                relay_num, strerror(errno));
        return -1;
    }

    sleep(duration_sec);

    if (gpiod_line_set_value(relay_lines[relay_num], 1) < 0) {
        fprintf(stderr, "Error: Failed to deactivate relay %d: %s\n",
                relay_num, strerror(errno));
        return -1;
    }
    return 0;
}

static int log_event(int relay_num, int moisture_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (!localtime_r(&rawtime, &timeinfo)) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Relay %d - Moisture: %d%%\n",
                timestamp, relay_num, moisture_level) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
