/*
 * Automated Plant Watering System (Raspberry Pi Zero W)
 * Library: pigpio
 *
 * Hardware:
 *   - SG90 servo 1 (water valve)  -> GPIO17 (physical pin 11)
 *   - SG90 servo 2 (nozzle)       -> GPIO18 (physical pin 12)
 *
 * SG90 servo pulse-width range: 500-2500 us
 *   500 us  -> ~0 degrees
 *   1500 us -> ~90 degrees
 *   2500 us -> ~180 degrees
 *
 * Valve: closed at 0 degrees, open at 90 degrees.
 * Nozzle: sweeps 0, 45, 90, 135, 180 degrees during watering.
 *
 * Moisture readings (simulated) cycle: 20, 40, 60, 80, 100 every second.
 * Watering threshold: 50.
 *
 * Build: gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_SERVO_PIN      17
#define NOZZLE_SERVO_PIN     18

#define VALVE_OPEN_ANGLE     90
#define VALVE_CLOSED_ANGLE   0
#define NOZZLE_STEPS         5
#define NOZZLE_STEP_DELAY_US 2000000  /* 2 s per step */
#define CYCLE_HOLD_DELAY_US  5000000  /* 5 s hold after watering */
#define CYCLE_WAIT_DELAY_US  5000000  /* 5 s between moisture readings */
#define SERVO_RETRY_COUNT    3
#define SERVO_RETRY_DELAY_US 100000   /* 100 ms backoff */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Set a servo angle with retry; returns 0 on success, -1 on failure. */
static int set_servo_angle(int pin, int angle)
{
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: angle %d out of range (0-180)\n", angle);
        return -1;
    }

    int pulse_width = 500 + (angle * 2000) / 180;  /* 500-2500 us */

    for (int attempt = 0; attempt < SERVO_RETRY_COUNT; attempt++) {
        int rc = gpioServo(pin, pulse_width);
        if (rc == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: gpioServo(pin=%d, pw=%d) failed (rc=%d), attempt %d/%d\n",
                pin, pulse_width, rc, attempt + 1, SERVO_RETRY_COUNT);
        if (attempt < SERVO_RETRY_COUNT - 1) {
            gpioDelay(SERVO_RETRY_DELAY_US);
        }
    }
    fprintf(stderr, "Error: gpioServo(pin=%d, pw=%d) failed after %d attempts\n",
            pin, pulse_width, SERVO_RETRY_COUNT);
    return -1;
}

/* Stop a servo (pulse width 0). */
static void stop_servo(int pin)
{
    gpioServo(pin, 0);
}

/* Stop both servos and terminate pigpio. */
static void cleanup(void)
{
    stop_servo(VALVE_SERVO_PIN);
    stop_servo(NOZZLE_SERVO_PIN);
    gpioTerminate();
}

int main(void)
{
    /* Install signal handlers for clean shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Ensure servos start in a safe (closed) state. */
    if (set_servo_angle(VALVE_SERVO_PIN, VALVE_CLOSED_ANGLE) != 0) {
        fprintf(stderr, "Error: failed to initialise valve servo to closed position\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (set_servo_angle(NOZZLE_SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise nozzle servo to 0 degrees\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Simulated moisture readings (percent). */
    const int moisture_readings[] = {20, 40, 60, 80, 100};
    const int num_readings =
        (int)(sizeof(moisture_readings) / sizeof(moisture_readings[0]));

    int nozzle_angles[NOZZLE_STEPS] = {0, 45, 90, 135, 180};

    while (g_running) {
        /* Read next moisture value. */
        int moisture = moisture_readings[(int)(time(NULL) % num_readings)];

        printf("Moisture reading: %d%%\n", moisture);

        if (moisture < 50) {
            printf("Moisture below threshold. Starting watering cycle.\n");

            /* Open valve. */
            if (set_servo_angle(VALVE_SERVO_PIN, VALVE_OPEN_ANGLE) != 0) {
                fprintf(stderr, "Error: failed to open valve. Aborting watering cycle.\n");
                break;
            }
            printf("Valve opened.\n");

            /* Sweep nozzle through all five angles. */
            for (int i = 0; i < NOZZLE_STEPS && g_running; i++) {
                if (set_servo_angle(NOZZLE_SERVO_PIN, nozzle_angles[i]) != 0) {
                    fprintf(stderr, "Warning: failed to set nozzle to %d degrees, skipping step %d\n",
                            nozzle_angles[i], i + 1);
                    continue;
                }
                printf("Nozzle at %d degrees\n", nozzle_angles[i]);
                gpioDelay(NOZZLE_STEP_DELAY_US);
            }

            /* Hold for 5 seconds. */
            if (g_running) {
                printf("Holding for 5 seconds...\n");
                gpioDelay(CYCLE_HOLD_DELAY_US);
            }

            /* Close valve. */
            if (set_servo_angle(VALVE_SERVO_PIN, VALVE_CLOSED_ANGLE) != 0) {
                fprintf(stderr, "Warning: failed to close valve. Continuing to next cycle.\n");
            }
            printf("Valve closed.\n");
        } else {
            printf("Moisture sufficient. Skipping watering cycle.\n");
        }

        /* Wait 5 seconds before next reading. */
        if (g_running) {
            printf("Waiting 5 seconds before next reading...\n");
            gpioDelay(CYCLE_WAIT_DELAY_US);
        }
    }

    /* Clean shutdown. */
    cleanup();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

