#define MOTOR_PIN_2 17
#define MOTOR_PIN_3 27
#define MOTOR_PIN_4 22

#define STEPS_PER_ROTATION 512
#define STEP_DELAY_US 3000
#define DEBOUNCE_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_pull_up(unsigned gpio, unsigned pud) {
    if (gpioSetPullUpDown(gpio, pud) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%u, %u) failed\n", gpio, pud);
        return -1;
    }
    return 0;
}

static void deenergize(void) {
    safe_write(MOTOR_PIN_1, 0);
    safe_write(MOTOR_PIN_2, 0);
    safe_write(MOTOR_PIN_3, 0);
    safe_write(MOTOR_PIN_4, 0);
}

static void rotate_clockwise(int steps) {
    printf("Locking door...\n");
    for (int i = 0; i < steps && running; i++) {
        if (safe_write(MOTOR_PIN_1, 1) < 0) break;
        if (safe_write(MOTOR_PIN_2, 0) < 0) break;
        if (safe_write(MOTOR_PIN_3, 0) < 0) break;
        if (safe_write(MOTOR_PIN_4, 1) < 0) break;
        gpioDelay(STEP_DELAY_US);
        if (safe_write(MOTOR_PIN_1, 0) < 0) break;
        if (safe_write(MOTOR_PIN_2, 1) < 0) break;
        if (safe_write(MOTOR_PIN_3, 0) < 0) break;
        if (safe_write(MOTOR_PIN_4, 0) < 0) break;
        gpioDelay(STEP_DELAY_US);
    }
    deenergize();
    printf("Door locked.\n");
}

static void rotate_counter_clockwise(int steps) {
    printf("Unlocking door...\n");
    for (int i = 0; i < steps && running; i++) {
        if (safe_write(MOTOR_PIN_1, 0) < 0) break;
        if (safe_write(MOTOR_PIN_2, 1) < 0) break;
        if (safe_write(MOTOR_PIN_3, 0) < 0) break;
        if (safe_write(MOTOR_PIN_4, 1) < 0) break;
        gpioDelay(STEP_DELAY_US);
        if (safe_write(MOTOR_PIN_1, 1) < 0) break;
        if (safe_write(MOTOR_PIN_2, 0) < 0) break;
        if (safe_write(MOTOR_PIN_3, 0) < 0) break;
        if (safe_write(MOTOR_PIN_4, 0) < 0) break;
        gpioDelay(STEP_DELAY_US);
    }
    deenergize();
    printf("Door unlocked.\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(MOTOR_PIN_1, PI_OUTPUT) < 0 ||
        safe_set_mode(MOTOR_PIN_2, PI_OUTPUT) < 0 ||
        safe_set_mode(MOTOR_PIN_3, PI_OUTPUT) < 0 ||
        safe_set_mode(MOTOR_PIN_4, PI_OUTPUT) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_pull_up(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        safe_pull_up(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

