        return EXIT_FAILURE;
    }

    printf("Automatic Door Lock System started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            if (gpioRead(LOCK_BUTTON) == 0) {
                rotate_clockwise(STEPS_PER_ROTATION);
                while (gpioRead(LOCK_BUTTON) == 0 && running) {
                    gpioDelay(100000);
                }
            }
        }
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
