                rotate_counter_clockwise(STEPS_PER_ROTATION);
                while (gpioRead(UNLOCK_BUTTON) == 0 && running) {
                    gpioDelay(100000);
                }
            }
        }
        gpioDelay(10000);
    }

    deenergize();
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

