		if (clock_gettime(CLOCK_MONOTONIC, &t0) != 0)
			return -2;
	} while (gpiod_line_get_value(echo) == 1);

	/* Wait for echo falling edge (timeout) */
	do {
		if (gpiod_line_get_value(echo) == 0)
			break;
		sleep_us(1);
	} while (clock_gettime(CLOCK_MONOTONIC, &t1) == 0 &&
		 (t1.tv_sec - t0.tv_sec) * 1000000L +
		 (t1.tv_nsec - t0.tv_nsec) / 1000L < ECHO_TIMEOUT_US);

	if (gpiod_line_get_value(echo) != 0)
		return -1;

	/* Measure falling-edge end */
	do {
		if (clock_gettime(CLOCK_MONOTONIC, &t1) != 0)
			return -2;
	} while (gpiod_line_get_value(echo) == 0);

	elapsed_us = (long)(t1.tv_sec - t0.tv_sec) * 1000000L +
		     (t1.tv_nsec - t0.tv_nsec) / 1000L;
	return elapsed_us;
}

static void log_distance(FILE *fp, long duration_us, float distance_cm)
{
	if (fp) {
		fprintf(fp, "%ld,%.2f\n", duration_us, distance_cm);
		fflush(fp);
	}
}

int main(void)
{
	struct gpiod_chip *chip = NULL;
	struct gpiod_line *trigger = NULL;
	struct gpiod_line *echo = NULL;
	int ret = EXIT_FAILURE;

	struct sigaction sa;
	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = sig_handler;
	sigemptyset(&sa.sa_mask);
	sa.sa_flags = 0;
	if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
		fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
		return EXIT_FAILURE;
	}

	g_log = fopen(LOG_FILE, "a");
	if (!g_log) {
		fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
		return EXIT_FAILURE;
	}

	chip = gpiod_chip_open_by_name("gpiochip4");
	if (!chip) {
		fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
		goto cleanup;
	}

	trigger = gpiod_chip_get_line(chip, TRIGGER_LINE);
	echo = gpiod_chip_get_line(chip, ECHO_LINE);
	if (!trigger || !echo) {
		fprintf(stderr, "gpiod_chip_get_line failed: %s\n", strerror(errno));
		goto cleanup;
	}

	if (gpiod_line_request_output(trigger, "hcsr04-trigger", 0) < 0) {
		fprintf(stderr, "request_output(trigger) failed: %s\n", strerror(errno));
		goto cleanup;
	}

	if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
		fprintf(stderr, "request_input(echo) failed: %s\n", strerror(errno));
		goto cleanup;
	}

	printf("HC-SR04 distance logger started. Press Ctrl+C to exit.\n");

	while (g_running) {
		/* Generate 10 us trigger pulse */
		if (gpiod_line_set_value(trigger, 1) < 0) {
			fprintf(stderr, "set trigger high failed: %s\n", strerror(errno));
			goto cleanup;
		}
		sleep_us(TRIGGER_PULSE_US);
		if (gpiod_line_set_value(trigger, 0) < 0) {
			fprintf(stderr, "set trigger low failed: %s\n", strerror(errno));
			goto cleanup;
		}

		long duration = measure_echo(echo);

		if (duration < 0) {
			fprintf(stderr, "Echo measurement failed (code %ld)\n", duration);
			log_distance(g_log, duration, -1.0f);
		} else {
			float distance = duration * SPEED_OF_SOUND_CM_PER_US;
			log_distance(g_log, duration, distance);
			printf("Distance: %.2f cm\n", distance);
		}

		/* 60 ms guard between measurements */
		sleep_us(MEASURE_INTERVAL_US);
	}

	ret = EXIT_SUCCESS;

cleanup:
	if (trigger)
		gpiod_line_release(trigger);
	if (echo)
		gpiod_line_release(echo);
	if (chip)
		gpiod_chip_close(chip);
	if (g_log) {
		fclose(g_log);
		g_log = NULL;
	}
	return ret;
}

