#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define RELAY_GPIO     18
#define DISTANCE_THRESHOLD_CM 50
#define POLL_DELAY_US  100000  /* 100 ms */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET              0x0000
#define REG_SYSTEM_MODE_START       0x0080
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define REG_RESULT_INTERRUPT_STATUS 0x0044
#define REG_RESULT_DISTANCE_HI      0x0096
#define REG_RESULT_DISTANCE_LO      0x0097

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address, then a single byte value. */
static int vl53l1x_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "I2C write failed for reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

/* Read a 16-bit register address, then one byte. */
static int vl53l1x_read_reg8(int handle, uint16_t reg, uint8_t *value)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) != 0) {
        fprintf(stderr, "I2C write (addr) failed for reg 0x%04X\n", reg);
        return -1;
    }
    char data;
    if (i2cReadDevice(handle, &data, 1) != 1) {
        fprintf(stderr, "I2C read failed for reg 0x%04X\n", reg);
        return -1;
    }
    *value = (uint8_t)data;
    return 0;
}

/* Read a 16-bit big-endian register pair. */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) != 0) {
        fprintf(stderr, "I2C write (addr) failed for reg 0x%04X\n", reg);
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "I2C read failed for reg 0x%04X\n", reg);
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(int handle)
{
    /* Software reset: write 0x00 to register 0x0000. */
    if (vl53l1x_write_reg8(handle, REG_SOFT_RESET, 0x00) != 0)
        return -1;
    gpioDelay(1000);  /* 1 ms settle after reset */

    /* Start continuous ranging: write 0x01 to register 0x0080. */
    if (vl53l1x_write_reg8(handle, REG_SYSTEM_MODE_START, 0x01) != 0)
        return -1;

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status;
    if (vl53l1x_read_reg8(handle, REG_RESULT_INTERRUPT_STATUS, &status) != 0)
        return -1;

    if ((status & 0x01) == 0)
        return 1;  /* no new data yet */

    /* Clear the interrupt so the next measurement can signal again. */
    if (vl53l1x_write_reg8(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    uint16_t dist;
    if (vl53l1x_read_reg16(handle, REG_RESULT_DISTANCE_HI, &dist) != 0)
        return -1;

    *distance_mm = dist;
    return 0;
}

static void control_relay(int gpio_pin, int state)
{
    if (gpioWrite(gpio_pin, state) != 0)
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", gpio_pin, state);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_relay(RELAY_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("Proximity-based automated door system running. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance_mm;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance_mm);

        if (rc == 0) {
            uint16_t distance_cm = distance_mm / 10;
            printf("Distance: %u cm\n", distance_cm);
            if (distance_cm <= DISTANCE_THRESHOLD_CM) {
                control_relay(RELAY_GPIO, 1);
            } else {
                control_relay(RELAY_GPIO, 0);
            }
        } else if (rc < 0) {
            fprintf(stderr, "Error reading distance from VL53L1X\n");
        }
        /* rc == 1: no new data yet, just wait */

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    control_relay(RELAY_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

