    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (init_mpu6050(fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed (sensor absent or bus error)\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized. Reading gyroscope data (Ctrl+C to exit)...\n");

    while (running) {
        float x, y, z;
        if (read_gyro(fd, &x, &y, &z) == 0) {
            printf("X: %.2f dps, Y: %.2f dps, Z: %.2f dps\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }
        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return EXIT_SUCCESS;
}

