/*
 * Automated Plant Watering System using libgpiod v1 API
 * Board:  Raspberry Pi 4 Model B
 * Relays: 4x 5V relay modules on BCM GPIO17, GPIO18, GPIO27, GPIO22
 * API:    libgpiod v1 (modern kernel GPIO character-device interface)
 *
 * Build:  gcc -o watering watering.c -lgpiod
 * Run:    sudo ./watering   (root needed for /dev/gpiochip0 access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define WATERING_DURATION_SEC 5
#define CYCLE_INTERVAL_SEC 86400   /* 24 hours */
#define POLL_INTERVAL_SEC 60       /* seconds between cycle checks */

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped entry to the watering log file.               */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int log_watering_event(void)
{
    FILE *fp = fopen("watering_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening watering_log.txt: %s\n",
                strerror(errno));
        return -1;
    }

    time_t rawtime = time(NULL);
    if (rawtime == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm timeinfo;
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() on log failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Activate all four relays for WATERING_DURATION_SEC.                */
/* ------------------------------------------------------------------ */
static void water_plants(struct gpiod_line_bulk *lines)
{
    printf("Watering plants for %d seconds...\n", WATERING_DURATION_SEC);

    if (gpiod_line_set_value_bulk(lines, 0) < 0) {
        fprintf(stderr, "Failed to activate relays: %s\n", strerror(errno));
        return;
    }

    for (int i = 0; i < WATERING_DURATION_SEC && program_running; i++)
        sleep(1);

    if (gpiod_line_set_value_bulk(lines, 1) < 0) {
        fprintf(stderr, "Failed to deactivate relays: %s\n", strerror(errno));
    } else {
        printf("Watering complete.\n");
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    int ret = EXIT_FAILURE;

    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open the GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Collect the relay lines into a bulk ---- */
    gpiod_line_bulk_init(&lines);
    for (int i = 0; i < NUM_RELAYS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!line) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
        gpiod_line_bulk_add(&lines, line);
    }

    /* ---- Request all lines as outputs, initially HIGH (inactive) ---- */
    if (gpiod_line_request_bulk_output(&lines, "plant-watering",
                                       1) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as outputs: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    /* ---- Main watering cycle loop ---- */
    while (program_running) {
        water_plants(&lines);

        if (!program_running)
            break;

        if (log_watering_event() < 0) {
            fprintf(stderr, "Warning: failed to log watering event.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < CYCLE_INTERVAL_SEC && program_running; i++)
            sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Release lines and close chip ---- */
    if (gpiod_line_bulk_num_lines(&lines) > 0) {
        gpiod_line_release_bulk(&lines);
    }
    if (chip)
        gpiod_chip_close(chip);

    printf("Plant watering system stopped.\n");
    return ret;
}

