#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define NUM_RELAYS 4
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SUNRISE_DURATION 1800
#define STEP_DELAY_US 1000000

static const int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};
static volatile sig_atomic_t running = 1;

static void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(relay_pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioPWM(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Failed to initialise PWM on GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioPWM(relay_pins[i], 0);
    }
    gpioTerminate();
}

static void sunrise_simulation(void) {
    int current_duty = 0;
    int step = (PWM_RANGE * SUNRISE_DURATION) / STEP_DELAY_US;

    log_event("Sunrise simulation started");

    while (running && current_duty <= PWM_RANGE) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (gpioPWM(relay_pins[i], current_duty) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", relay_pins[i]);
                running = 0;
                break;
            }
        }
        current_duty += step;
        if (current_duty > PWM_RANGE) current_duty = PWM_RANGE;

        if (running) {
            gpioDelay(STEP_DELAY_US);
        }
    }

    if (running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpioPWM(relay_pins[i], PWM_RANGE);
        }
        log_event("Sunrise simulation completed");
    } else {
        log_event("Sunrise simulation interrupted");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set up signal handlers");
        return 1;
    }

    if (setup_gpio() != 0) {
        return 1;
    }

    sunrise_simulation();

    cleanup_gpio();
    return 0;
}

