#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 register addresses */
#define MPU6050_WHO_AM_I   0x75
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_GYRO_XOUT_H 0x43

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I_VAL 0x68

/* Full-scale range: ±250 deg/s => 131 LSB/deg/s */
#define GYRO_SCALE 131.0f

/* LED GPIO pin */
#define LED_PIN 17

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Sampling period in microseconds (20 Hz) */
#define SAMPLE_PERIOD_US 50000

/* Oversampling limit for re-initialisation */
#define MAX_REINIT_ATTEMPTS 3

/* Threshold for angular velocity (deg/s) */
#define THRESHOLD 250.0f

/* Structure to hold gyroscope data and timestamp */
typedef struct {
    float x, y, z;
    struct timespec timestamp;
} gyro_data_t;

/* Circular buffer */
static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* Function prototypes */
static int init_i2c(void);
static int init_mpu6050(void);
static int read_gyro_data(float *x, float *y, float *z);
static void add_to_buffer(float x, float y, float z);
static void check_threshold(float x, float y, float z);
static void cleanup(void);
static void signal_handler(int sig);

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* Initialise I2C bus 1 with the MPU-6050 */
static int init_i2c(void) {
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n",
                MPU6050_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/* Initialise MPU-6050: wake, set sample rate, configure gyro range */
static int init_mpu6050(void) {
    int status;

    /* Wake up the MPU-6050 (clear sleep bit) */
    status = i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x00);
    if (status < 0) {
