#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_LINE_OFFSET  8          /* GPIO8 = CE0 on RPi 4 */
#define GYRO_REG_START  0x43       /* GYRO_XOUT_H */
#define GYRO_REG_COUNT  6          /* 3 axes * 2 bytes */
#define GYRO_SCALE      131.0f     /* ±250 dps range */
#define SAMPLE_PERIOD_US 10000     /* 10 ms */
#define MAX_RETRIES     3

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd   = -1;
static struct gpiod_line *g_cs_line = NULL;
static FILE    *g_log_fp   = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gyro_data(int fd, struct gpiod_line *cs, int32_t *x, int32_t *y, int32_t *z)
{
    uint8_t tx[GYRO_REG_COUNT + 1];
    uint8_t rx[GYRO_REG_COUNT + 1];
    int32_t raw_x, raw_y, raw_z;
    int retries = 0;

    tx[0] = GYRO_REG_START | 0x80;  /* read, auto-increment */

    while (retries < MAX_RETRIES) {
        if (gpiod_line_set_value(cs, 0) < 0) {
            fprintf(stderr, "CS low failed: %s\n", strerror(errno));
            retries++;
            usleep(1000);
            continue;
        }

        if (spi_transfer(fd, tx, rx, sizeof(tx)) < 0) {
            gpiod_line_set_value(cs, 1);
            retries++;
            usleep(1000);
            continue;
        }

        gpiod_line_set_value(cs, 1);

        raw_x = (int32_t)(((uint32_t)rx[1] << 8) | rx[2]);
        raw_y = (int32_t)(((uint32_t)rx[3] << 8) | rx[4]);
        raw_z = (int32_t)(((uint32_t)rx[5] << 8) | rx[6]);

        /* Sign-extend 16-bit two's complement to 32-bit */
        if (raw_x & 0x8000) raw_x |= 0xFFFF0000;
        if (raw_y & 0x8000) raw_y |= 0xFFFF0000;
        if (raw_z & 0x8000) raw_z |= 0xFFFF0000;

        *x = raw_x;
        *y = raw_y;
        *z = raw_z;
        return 0;
    }

    fprintf(stderr, "Gyroscope read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static void log_data(FILE *fp, int32_t x, int32_t y, int32_t z)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[40];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp),
             ".%09ld", ts.tv_nsec);

    float x_rate = (float)x / GYRO_SCALE;
    float y_rate = (float)y / GYRO_SCALE;
    float z_rate = (float)z / GYRO_SCALE;

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x_rate, y_rate, z_rate) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    } else {
        fflush(fp);
    }
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_cs_line) {
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void)
{
    int32_t x, y, z;
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI config failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_cs_line = gpiod_line_get(GPIO_CHIP, CS_LINE_OFFSET);
    if (!g_cs_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_cs_line, "mpu9250-cs", 1) < 0) {
        fprintf(stderr, "Cannot request CS line as output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("gyro_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open gyro_log.txt: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU-9250 gyroscope logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        if (read_gyro_data(g_spi_fd, g_cs_line, &x, &y, &z) == 0) {
            log_data(g_log_fp, x, y, z);
        } else {
            fprintf(stderr, "Skipping sample due to read error\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

