#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 3900000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8

#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_YOUT_H 0x45
#define MPU6050_GYRO_ZOUT_H 0x47
#define MPU6050_PWR_MGMT_1 0x6B

#define LED_GPIO_LINE 17
#define CS_GPIO_LINE 8
#define GPIO_CHIP_NAME "gpiochip0"

#define BUFFER_SIZE 64
#define DEG_PER_SEC_THRESHOLD 200.0f
#define GYRO_SCALE 131.0f

typedef struct {
    struct timespec timestamp;
    float x, y, z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_GPIO_LINE);
    if (!cs_line) {
        fprintf(stderr, "Error getting CS GPIO line %d: %s\n", CS_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Error getting LED GPIO line %d: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "mpu6050_cs", 1) < 0) {
        fprintf(stderr, "Error requesting CS line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(led_line, "mpu6050_led", 0) < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error asserting CS: %s\n", strerror(errno));
        return -1;
    }

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error deasserting CS: %s\n", strerror(errno));
        return -1;
    }

    if (ret < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_gyro_axis(uint8_t reg, float *out) {
    uint8_t tx[2] = { reg & 0x7F, 0x00 };
    uint8_t rx[2] = { 0 };

    if (spi_transfer(tx, rx, 2) < 0) {
        return -1;
    }

    int16_t raw = (int16_t)((rx[0] << 8) | rx[1]);
    *out = (float)raw / GYRO_SCALE;
    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    if (read_gyro_axis(MPU6050_GYRO_XOUT_H, x) < 0) return -1;
    if (read_gyro_axis(MPU6050_GYRO_YOUT_H, y) < 0) return -1;
    if (read_gyro_axis(MPU6050_GYRO_ZOUT_H, z) < 0) return -1;
    return 0;
}

static void add_to_buffer(float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    gyro_buffer[buffer_index].timestamp = ts;
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("%ld.%09ld,%.2f,%.2f,%.2f\n",
               (long)gyro_buffer[idx].timestamp.tv_sec,
               gyro_buffer[idx].timestamp.tv_nsec,
               gyro_buffer[idx].x,
               gyro_buffer[idx].y,
               gyro_buffer[idx].z);
    }
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (cs_line) {
        gpiod_line_set_value(cs_line, 1);
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_set_value(led_line, 0) < 0) {
        fprintf(stderr, "Error initializing LED: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("MPU-6050 Gyroscope SPI Monitor (libgpiod + spidev)\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (read_gyro_data(&x, &y, &z) < 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
            break;
        }

        add_to_buffer(x, y, z);

        if (x > DEG_PER_SEC_THRESHOLD || x < -DEG_PER_SEC_THRESHOLD ||
            y > DEG_PER_SEC_THRESHOLD || y < -DEG_PER_SEC_THRESHOLD ||
            z > DEG_PER_SEC_THRESHOLD || z < -DEG_PER_SEC_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
            usleep(500000);
            gpiod_line_set_value(led_line, 0);
            usleep(500000);
        }

        usleep(10000);
    }

    printf("\nExiting...\n");
    print_buffer();
    cleanup();
    return 0;
}

