#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define LED_PIN      21
#define TILT_THRESHOLD 45.0
#define I2C_BUS      1

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_mpu6050(void) {
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to wake MPU-6050 (PWR_MGMT_1)\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle */

    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set accelerometer range\n");
        return -1;
    }
    return 0;
}

static int read_accel_data(int16_t *ax, int16_t *ay, int16_t *az) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read accelerometer data\n");
        return -1;
    }
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void calculate_tilt(int16_t ax, int16_t ay, int16_t az, float *roll, float *pitch) {
    *roll  = atan2f((float)ay, (float)az) * 180.0f / M_PI;
    *pitch = atan2f(-(float)ax, sqrtf((float)ay * ay + (float)az * az)) * 180.0f / M_PI;
}

static void control_led(float roll, float pitch) {
    int on = (fabsf(roll) > TILT_THRESHOLD || fabsf(pitch) > TILT_THRESHOLD) ? 1 : 0;
    gpioWrite(LED_PIN, on);
}

static void log_data(float roll, float pitch) {
    FILE *fp = fopen("tilt_log.txt", "a");
    if (!fp) {
