#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define REG_ALS_DATA0 0x20
#define REG_PS1_DATA0 0x22
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define PROXIMITY_THRESHOLD 100
#define LOG_FILE "biometric_log.txt"
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_MS 10
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_chip *chip = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t reg_buf = reg;
    if (write(fd, &reg_buf, 1) != 1) return -1;
    uint8_t data[2];
    if (read(fd, data, 2) != 2) return -1;
    *out = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    return 0;
}

static int init_i2c(void) {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return -1;
    }
    return fd;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(led_line, "si1145_led", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        chip = NULL;
        led_line = NULL;
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

static int read_sensor_data(uint16_t *ambient_light, uint16_t *proximity) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (i2c_read_reg16(i2c_fd, REG_ALS_DATA0, ambient_light) == 0 &&
            i2c_read_reg16(i2c_fd, REG_PS1_DATA0, proximity) == 0) {
            return 0;
        }
        fprintf(stderr, "I2C read error (attempt %d/%d)\n", attempt + 1, I2C_RETRIES);
        if (attempt < I2C_RETRIES - 1) usleep(I2C_RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static void log_data(uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient_light, proximity);
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = init_i2c();
    if (i2c_fd < 0) return 1;

    if (init_gpio() < 0) {
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        cleanup();
        return 1;
    }

    printf("Starting Si1145 biometric monitoring...\n");

    while (running) {
        uint16_t ambient_light = 0, proximity = 0;
        if (read_sensor_data(&ambient_light, &proximity) == 0) {
            log_data(ambient_light, proximity);
            if (proximity > PROXIMITY_THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after retries.\n");
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

