#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXRS290 register addresses */
#define ADXRS290_X_RATE_REG  0x02
#define ADXRS290_Y_RATE_REG  0x04

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0        /* CPOL=0, CPHA=0 */

/* Sensitivity: 200 LSB per deg/s */
#define SENSITIVITY 200.0f

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 10000

/* Maximum SPI reinitialisations on failure */
#define MAX_SPI_REINIT 3

static int spi_handle = -1;
static FILE *data_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/*
 * Read a 16-bit two's-complement register from the ADXRS290.
 * The ADXRS290 returns the MSB of the requested register in the
 * first byte of the transfer, then the LSB in the second byte.
 * To read register addr, send (addr | 0x80) followed by a dummy byte.
 * The response is the second byte of the 2-byte transfer.
 */
static int read_gyro_register(uint8_t addr, int16_t *value)
{
    char tx[2];
    char rx[2];

    tx[0] = (char)(addr | 0x80);  /* set read bit */
    tx[1] = 0x00;                 /* dummy byte */

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", addr);
        return -1;
    }

    /* rx[0] is the MSB of the previous register; rx[1] is the LSB of this one */
    *value = (int16_t)(((uint16_t)(uint8_t)rx[1] << 8) | (uint8_t)rx[0]);
    return 0;
}

static int init_spi(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

static int log_data(int16_t x_rate, int16_t y_rate)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1.0e9;

    if (fprintf(data_file, "%.9f,%d,%d\n", timestamp, x_rate, y_rate) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(data_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (data_file != NULL) {
        fflush(data_file);
        fclose(data_file);
        data_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    data_file = fopen("gyro_data.csv", "w");
    if (data_file == NULL) {
        perror("fopen");
        cleanup();
        return 1;
    }

    if (fprintf(data_file, "timestamp,X_rate,Y_rate\n") < 0) {
        perror("fprintf header");
        cleanup();
        return 1;
    }
    fflush(data_file);

    int consecutive_errors = 0;

    while (!terminate) {
        int16_t x_rate = 0, y_rate = 0;

        if (read_gyro_register(ADXRS290_X_RATE_REG, &x_rate) != 0) {
            consecutive_errors++;
            if (consecutive_errors > MAX_SPI_REINIT) {
                fprintf(stderr, "Max SPI reinitialisations reached. Exiting.\n");
                break;
            }
            if (init_spi() != 0) {
                fprintf(stderr, "SPI reinitialisation failed. Exiting.\n");
                break;
            }
            continue;
        }
        consecutive_errors = 0;

        if (read_gyro_register(ADXRS290_Y_RATE_REG, &y_rate) != 0) {
            consecutive_errors++;
            if (consecutive_errors > MAX_SPI_REINIT) {
                fprintf(stderr, "Max SPI reinitialisations reached. Exiting.\n");
                break;
            }
            if (init_spi() != 0) {
                fprintf(stderr, "SPI reinitialisation failed. Exiting.\n");
                break;
            }
            continue;
        }
        consecutive_errors = 0;

        if (log_data(x_rate, y_rate) != 0) {
            fprintf(stderr, "Logging failed. Exiting.\n");
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

