#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN    17
#define ALERT_DURATION_MS 2000
#define SEISMIC_THRESHOLD_MS 500
#define LOG_FILE "seismic_events.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

static void alert_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    static uint32_t start_tick = 0;
    static int s1_tilted = 0, s2_tilted = 0;

    if (gpio == SENSOR_1_PIN) {
        s1_tilted = (level == 1);
    } else if (gpio == SENSOR_2_PIN) {
        s2_tilted = (level == 1);
    }

    if (s1_tilted && s2_tilted) {
        if (start_tick == 0) {
            start_tick = tick;
        } else if ((tick - start_tick) >= SEISMIC_THRESHOLD_MS * 1000) {
            gpioWrite(ALERT_PIN, 1);
            log_event("Seismic event detected!");
            gpioDelay(ALERT_DURATION_MS * 1000);
            gpioWrite(ALERT_PIN, 0);
            start_tick = 0;
        }
    } else {
        start_tick = 0;
    }
}

