#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <pthread.h>

/* ADXRS290 register addresses (lower byte; read bit set in MSB) */
#define ADXRS290_REG_RATE_XL 0x02
#define ADXRS290_REG_RATE_XH 0x03

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CS handled by pigpio */

/* GPIO pins */
#define LED_PIN 17

/* Gyroscope sensitivity: 200 LSB per deg/s */
#define GYRO_SENSITIVITY 200.0f

/* Angular velocity threshold (deg/s) */
#define ANGULAR_VELOCITY_THRESHOLD 20.0f

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Data structure for a single reading */
typedef struct {
    struct timespec timestamp;
    float angular_velocity;
} GyroData;

/* Circular buffer */
typedef struct {
    GyroData data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

/* Global state */
static int spi_handle = -1;
static CircularBuffer gyro_buffer;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int  init_spi(void);
static int  read_gyro_data(float *angular_velocity);
static void add_to_buffer(CircularBuffer *buffer, float angular_velocity);
static void check_threshold(float angular_velocity);
static void cleanup(void);
static void signal_handler(int signal);

/* ------------------------------------------------------------------ */
/* Circular buffer implementation                                      */
/* ------------------------------------------------------------------ */
static void circular_buffer_init(CircularBuffer *buffer) {
    buffer->head  = 0;
    buffer->tail  = 0;
    buffer->count = 0;
    if (pthread_mutex_init(&buffer->mutex, NULL) != 0) {
        perror("Failed to initialize circular buffer mutex");
        exit(EXIT_FAILURE);
    }
}

static void circular_buffer_add(CircularBuffer *buffer, float angular_velocity) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime failed");
        return;
    }

    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head].timestamp = ts;
    buffer->data[buffer->head].angular_velocity = angular_velocity;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

/* ------------------------------------------------------------------ */
/* Gyroscope read                                                     */
/* ------------------------------------------------------------------ */
/*
 * ADXRS290 SPI read sequence (3 bytes):
 *   Byte 0: register address | 0x80 (MSB = 1 -> read)
 *   Byte 1: dummy (clocks out LSB of register address)
 *   Byte 2: dummy (clocks out data byte 0)
 * Result: data = byte[2] << 8 | byte[1]
 */
static int read_gyro_data(float *angular_velocity) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = (char)(ADXRS290_REG_RATE_XL | 0x80);  /* read, lower byte */
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int16_t raw_data = (int16_t)(((uint16_t)(uint8_t)rx_buf[2] << 8) |
                                 (uint16_t)(uint8_t)rx_buf[1]);

    *angular_velocity = (float)raw_data / GYRO_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Threshold check and LED control                                     */
/* ------------------------------------------------------------------ */
static void check_threshold(float angular_velocity) {
    static bool threshold_exceeded = false;

    if (fabsf(angular_velocity) > ANGULAR_VELOCITY_THRESHOLD) {
        if (!threshold_exceeded) {
            gpioWrite(LED_PIN, 1);
            threshold_exceeded = true;
            printf("Threshold exceeded! Angular velocity: %.2f deg/s\n",
                   angular_velocity);
        }
    } else {
        if (threshold_exceeded) {
            gpioWrite(LED_PIN, 0);
            threshold_exceeded = false;
            printf("Threshold cleared. Angular velocity: %.2f deg/s\n",
                   angular_velocity);
        }
    }
}

/* ------------------------------------------------------------------ */
/* Initialization                                                      */
/* ------------------------------------------------------------------ */
static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    circular_buffer_init(&gyro_buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXRS290 gyroscope reader started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float angular_velocity;
        if (read_gyro_data(&angular_velocity) == 0) {
            add_to_buffer(&gyro_buffer, angular_velocity);
            check_threshold(angular_velocity);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }
        gpioDelay(10000);  /* 10 ms */
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

