#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE 0x21
#define CHARGE_TIME 0x0D
#define RUN_MODE 0x0D
#define STOP_MODE 0x00
#define RESET_CMD 0x63
#define ELE0_ENABLE 0x01
#define TOUCH_STATUS_L 0x00
#define TOUCH_STATUS_H 0x01

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write failed: reg=0x%02X, val=0x%02X, errno=%d", reg, value, errno);
        log_message(msg);
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (mpr121_write_reg(0x80, RESET_CMD) != 0) return -1;
    gpioDelay(10000);
    if (mpr121_write_reg(0x5E, STOP_MODE) != 0) return -1;
    if (mpr121_write_reg(0x5D, ELE0_ENABLE) != 0) return -1;
    if (mpr121_write_reg(0x41, TOUCH_THRESHOLD) != 0) return -1;
    if (mpr121_write_reg(0x42, RELEASE_THRESHOLD) != 0) return -1;
    if (mpr121_write_reg(0x5B, DEBOUNCE) != 0) return -1;
    if (mpr121_write_reg(0x5C, CHARGE_TIME) != 0) return -1;
    if (mpr121_write_reg(0x5E, RUN_MODE) != 0) return -1;
    return 0;
}

static int read_touch_status(uint16_t *status) {
    char reg = TOUCH_STATUS_L;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write for touch status failed, errno=%d", errno);
        log_message(msg);
        return -1;
    }
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C read for touch status failed, errno=%d", errno);
        log_message(msg);
        return -1;
    }
    *status = ((uint16_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    log_message("Program started");

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        log_message("Failed to set GPIO17 as output");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to open I2C device at 0x%02X on bus %d, errno=%d", MPR121_ADDR, I2C_BUS, errno);
        log_message(msg);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() != 0) {
        log_message("MPR121 initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;
    uint16_t touch_status = 0;
    uint32_t last_touch_tick = 0;

    while (running) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status & 0x01) {
                uint32_t now = gpioTick();
                if (now - last_touch_tick > 100000) {
                    relay_state = !relay_state;
                    gpioWrite(RELAY_GPIO, relay_state);
                    char msg[128];
                    snprintf(msg, sizeof(msg), "Relay toggled to %d", relay_state);
                    log_message(msg);
                    last_touch_tick = now;
                }
            }
        }
        gpioDelay(10000);
    }

    log_message("Shutting down");
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
