#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23
#define LOG_FILE "flame_log.txt"
#define DEBOUNCE_READINGS 3
#define DEBOUNCE_DELAY_MS 50
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(FILE *log_file, const char *message) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }
    struct tm *tstruct = localtime(&now);
    if (tstruct == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        return -1;
    }
    char buf[80];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct) == 0) {
        fprintf(stderr, "Error formatting time\n");
        return -1;
    }
    if (fprintf(log_file, "%s: %s\n", buf, message) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_flame_sensor(struct gpiod_line *line) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading flame sensor: %s\n", strerror(errno));
            return -1;
        }
        if (val == 0) {
            low_count++;
        }
        if (i < DEBOUNCE_READINGS - 1) {
            usleep(DEBOUNCE_DELAY_MS * 1000);
        }
    }
    return (low_count == DEBOUNCE_READINGS) ? 1 : 0;
}

static int set_output(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting output to %d: %s\n", value, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    struct gpiod_line *led_line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (flame_line == NULL || buzzer_line == NULL || led_line == NULL) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "Error requesting flame sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int flame_detected = read_flame_sensor(flame_line);
        if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting.\n");
            break;
        }

        if (flame_detected) {
            if (set_output(buzzer_line, 1) < 0 || set_output(led_line, 1) < 0) {
                fprintf(stderr, "Error activating buzzer/LED, exiting.\n");
                break;
            }
            if (log_event(log_file, "Flame Detected") < 0) {
                fprintf(stderr, "Error logging event, exiting.\n");
                break;
            }
        } else {
            if (set_output(buzzer_line, 0) < 0 || set_output(led_line, 0) < 0) {
                fprintf(stderr, "Error deactivating buzzer/LED, exiting.\n");
                break;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (buzzer_line != NULL) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (led_line != NULL) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (flame_line != NULL) {
        gpiod_line_release(flame_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    return ret;
}

