#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define TOTAL_DISPENSE_DURATION_MS 1000
#define DISPENSE_INTERVAL_MS 5000
#define LOG_FILE "dispense_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(SOLENOID_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d low\n", SOLENOID_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(SOLENOID_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d low\n", SOLENOID_2_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int activate_solenoid(int pin, int duration_ms) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: failed to activate solenoid on GPIO%d\n", pin);
        return -1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate solenoid on GPIO%d\n", pin);
        return -1;
    }
    return 0;
}

static int log_dispense_event(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s - Solenoid 1 (GPIO%d): %d ms, Solenoid 2 (GPIO%d): %d ms\n",
                timestamp, solenoid1_pin, duration_ms, solenoid2_pin, duration_ms) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: failed to close log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    while (running) {
        int duration1 = TOTAL_DISPENSE_DURATION_MS / 2;
        int duration2 = TOTAL_DISPENSE_DURATION_MS / 2;

        if (activate_solenoid(SOLENOID_1_PIN, duration1) != 0) {
            gpioTerminate();
            return 1;
        }
        if (!running) break;

        if (activate_solenoid(SOLENOID_2_PIN, duration2) != 0) {
            gpioTerminate();
            return 1;
        }

        if (log_dispense_event(SOLENOID_1_PIN, SOLENOID_2_PIN, TOTAL_DISPENSE_DURATION_MS) != 0) {
            gpioTerminate();
            return 1;
        }

        for (int i = 0; i < DISPENSE_INTERVAL_MS / 100 && running; i++) {
            gpioDelay(100000);
        }
    }

    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();
    return 0;
}

