#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* Motor A pins */
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_A_ENABLE 24

/* Motor B pins */
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_B_ENABLE 25

/* PID gains */
#define KP 1.0
#define KI 0.01
#define KD 0.1

/* Obstacle avoidance threshold (cm) */
#define OBSTACLE_THRESHOLD 20.0

/* Log file path */
#define LOG_FILE "balance_log.txt"

/* Global flag for graceful shutdown */
volatile sig_atomic_t program_running = 1;

/* Global log file pointer */
FILE *log_file = NULL;

/* Function prototypes */
int initialize_gpio(void);
void set_motor_speed(int motor, int speed);
void stop_motors(void);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);
float pid_control(float error, float *integral, float *previous_error);
float simulate_sensor(float error);
void cleanup(void);

int main(void) {
    float tilt_error, distance, motor_a_speed, motor_b_speed;
    float integral = 0.0, previous_error = 0.0;
    int motor;

    /* Seed the random number generator */
    srand(time(NULL));

    /* Initialize pigpio */
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    /* Open the log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    /* Register signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);

    /* Main control loop */
    while (program_running) {
        /* Simulate sensor data */
        tilt_error = simulate_sensor(0.0);
        distance = simulate_sensor(tilt_error);

        /* Check for obstacle */
        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed = -50;
            motor_b_speed = -50;
        } else {
            /* PID control */
            motor_a_speed = pid_control(tilt_error, &integral, &previous_error);
            motor_b_speed = pid_control(tilt_error, &integral, &previous_error);
        }

        /* Clamp motor speeds to [-255, 255] */
        if (motor_a_speed > 255) motor_a_speed = 255;
        if (motor_a_speed < -255) motor_a_speed = -255;
        if (motor_b_speed > 255) motor_b_speed = 255;
        if (motor_b_speed < -255) motor_b_speed = -255;

        /* Set motor speeds */
        set_motor_speed(1, motor_a_speed);
        set_motor_speed(2, motor_b_speed);

        /* Log data */
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        /* Delay 50 ms */
        gpioDelay(50000);
    }

    /* Cleanup */
    cleanup();
    return 0;
}

/* Initialize pigpio and set GPIO modes */
int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set motor control pins as outputs */
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    /* Enable PWM on enable pins (50% duty cycle) */
    gpioPWM(MOTOR_A_ENABLE, 128);
    gpioPWM(MOTOR_B_ENABLE, 128);

    return 0;
}

/* Set motor speed (1 = Motor A, 2 = Motor B) */
void set_motor_speed(int motor, int speed) {
    if (motor == 1) {
        if (speed > 0) {
            gpioWrite(MOTOR_A_FORWARD, 1);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(MOTOR_A_ENABLE, abs(speed));
        } else if (speed < 0) {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 1);
            gpioPWM(MOTOR_A_ENABLE, abs(speed));
        } else {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(MOTOR_A_ENABLE, 0);
        }
    } else if (motor == 2) {
        if (speed > 0) {
            gpioWrite(MOTOR_B_FORWARD, 1);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(MOTOR_B_ENABLE, abs(speed));
        } else if (speed < 0) {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 1);
            gpioPWM(MOTOR_B_ENABLE, abs(speed));
        } else {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(MOTOR_B_ENABLE, 0);
        }
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
    }
}

/* Stop both motors */
void stop_motors(void) {
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
}

/* Log data to file */
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

/* Signal handler for graceful shutdown */
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* PID control */
float pid_control(float error, float *integral, float *previous_error) {
    float output;

    *integral += error;
    output = KP * error + KI * (*integral) + KD * (error - *previous_error);
    *previous_error = error;

    return output;
}

/* Simulate sensor data */
float simulate_sensor(float error) {
    return 10.0 + error + (rand() % 1000) / 100.0;
}

/* Cleanup resources */
void cleanup(void) {
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

