/*
 * mood_light.c — Raspberry Pi 3 Model B+
 *
 * Drives a common-cathode RGB LED (GPIO17=red, GPIO18=green, GPIO27=blue)
 * using pigpio software PWM, with color determined by ambient noise
 * captured via ALSA (if available) or a simulated sine wave.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lpigpio -lm
 *   (link with -lpigpio and -lm; pigpio must be compiled with ALSA support)
 *
 * Run:
 *   ./mood_light [sensitivity]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define DEFAULT_SENSITIVITY 1.0
#define SAMPLE_RATE        8000
#define PERIOD_SIZE        1024
#define UPDATE_DELAY_US    10000   /* 10 ms */
#define MAX_AUDIO_VALUE    32767.0

/* ------------------------------------------------------------------ */
/* ALSA helpers (compile-time guard)                                  */
/* ------------------------------------------------------------------ */

#if defined(__linux__) && defined(SND_PCM)
#define ALSA_AVAILABLE 1
#include <alsa/asoundlib.h>
#else
#define ALSA_AVAILABLE 0
#endif

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int g_alsa_handle = -1;
static int g_alsa_started = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio helpers                                                     */
/* ------------------------------------------------------------------ */

static int set_led_color(int red, int green, int blue)
{
    if (gpioPWM(RED_PIN,   red)   < 0) return -1;
    if (gpioPWM(GREEN_PIN, green) < 0) return -1;
    if (gpioPWM(BLUE_PIN,  blue)  < 0) return -1;
    return 0;
}

static void all_off(void)
{
    gpioPWM(RED_PIN,   0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN,  0);
}

/* ------------------------------------------------------------------ */
/* ALSA capture                                                       */
/* ------------------------------------------------------------------ */

static int initialize_alsa(void)
{
    g_alsa_handle = snd_pcm_open(NULL, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (g_alsa_handle < 0) {
        fprintf(stderr, "ALSA open failed: %s\n", snd_strerror(g_alsa_handle));
        return -1;
    }

    snd_pcm_hw_params_t *hw_params;
    snd_pcm_hw_params_alloca(&hw_params);

    if (snd_pcm_hw_params_any(g_alsa_handle, hw_params) < 0) {
        fprintf(stderr, "ALSA hw_params_any failed\n");
        goto fail;
    }
    if (snd_pcm_hw_params_set_access(g_alsa_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED) < 0) {
        fprintf(stderr, "ALSA set_access failed\n");
        goto fail;
    }
    if (snd_pcm_hw_params_set_format(g_alsa_handle, hw_params, SND_PCM_FORMAT_S16_LE) < 0) {
        fprintf(stderr, "ALSA set_format failed\n");
        goto fail;
    }
    if (snd_pcm_hw_params_set_channels(g_alsa_handle, hw_params, 1) < 0) {
        fprintf(stderr, "ALSA set_channels failed\n");
        goto fail;
    }
    if (snd_pcm_hw_params_set_rate_near(g_alsa_handle, hw_params, &SAMPLE_RATE, NULL) < 0) {
        fprintf(stderr, "ALSA set_rate failed\n");
        goto fail;
    }
    if (snd_pcm_hw_params_set_period_size_near(g_alsa_handle, hw_params, &PERIOD_SIZE, NULL) < 0) {
        fprintf(stderr, "ALSA set_period_size failed\n");
        goto fail;
    }

    if (snd_pcm_hw_params(g_alsa_handle, hw_params) < 0) {
        fprintf(stderr, "ALSA hw_params failed\n");
        goto fail;
    }

    if (snd_pcm_prepare(g_alsa_handle) < 0) {
        fprintf(stderr, "ALSA prepare failed\n");
        goto fail;
    }
    g_alsa_started = 1;
    return 0;

fail:
    snd_pcm_close(g_alsa_handle);
    g_alsa_handle = -1;
    return -1;
}

static int read_audio_sample(short *sample)
{
    snd_pcm_sframes_t frames = snd_pcm_readi(g_alsa_handle, sample, 1);
    if (frames < 0) {
        frames = snd_pcm_recover(g_alsa_handle, frames, 1);
        if (frames < 0) {
            fprintf(stderr, "ALSA recover failed: %s\n", snd_strerror(frames));
            snd_pcm_prepare(g_alsa_handle);
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Simulated audio (when ALSA unavailable)                            */
/* ------------------------------------------------------------------ */

static double generate_sine_wave(double phase)
{
    return 0.5 + 0.5 * sin(phase);
}

static int read_simulated_sample(double *sample)
{
    static double phase = 0.0;
    phase += 0.01;
    if (phase > 2.0 * M_PI) phase = 0.0;
    *sample = generate_sine_wave(phase);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Color mapping — non-linear transition                              */
/* ------------------------------------------------------------------ */

static void map_amplitude_to_color(double amplitude, double sensitivity,
                                   int *red, int *green, int *blue)
{
    double norm = amplitude / MAX_AUDIO_VALUE;
    if (norm < 0.0) norm = 0.0;
    if (norm > 1.0) norm = 1.0;

    /* Cool colors for low amplitude, warm for high */
    double cool = 1.0 - norm;
    double warm = norm;

    *red   = (int)(cool * 255.0);
    *green = (int)(warm * 255.0);
    *blue  = (int)(cool * 255.0);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    all_off();
    if (g_alsa_started) {
        snd_pcm_drain(g_alsa_handle);
        snd_pcm_close(g_alsa_handle);
        g_alsa_started = 0;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    double sensitivity = DEFAULT_SENSITIVITY;

    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0.0) {
            fprintf(stderr, "Sensitivity must be positive.\n");
            return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_alsa() < 0) {
        fprintf(stderr, "ALSA unavailable; using simulated sine-wave input.\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    short audio_sample;
    double amplitude;
    int red, green, blue;

    while (g_running) {
        if (ALSA_AVAILABLE) {
            if (read_audio_sample(&audio_sample) < 0) {
                gpioDelay(UPDATE_DELAY_US);
                continue;
            }
            amplitude = (double)audio_sample;
        } else {
            if (read_simulated_sample(&amplitude) < 0) {
                gpioDelay(UPDATE_DELAY_US);
                continue;
            }
            amplitude *= MAX_AUDIO_VALUE;
        }

        map_amplitude_to_color(amplitude, sensitivity, &red, &green, &blue);

        if (set_led_color(red, green, blue) < 0) {
            fprintf(stderr, "Failed to set LED color\n");
            break;
        }

        gpioDelay(UPDATE_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

