#define TCS34725_RDATAH  0x17
#define TCS34725_GDATAL  0x18
#define TCS34725_GDATAH  0x19
#define TCS34725_BDATAL  0x1A
#define TCS34725_BDATAH  0x1B

#define ENABLE_PON       0x01
#define ENABLE_AEN       0x02

static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0)
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, expected %u, got %d)\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

static int init_sensor(int handle)
{
    if (i2c_write_byte(handle, TCS34725_ENABLE, ENABLE_PON) < 0)
        return -1;
    gpioDelay(3000);  /* power-on wait */

    if (i2c_write_byte(handle, TCS34725_ATIME, 0xD5) < 0)
        return -1;  /* 154 ms integration time */

    if (i2c_write_byte(handle, TCS34725_ENABLE, ENABLE_PON | ENABLE_AEN) < 0)
        return -1;

    return 0;
}

static int read_sensor(int handle, uint16_t *clear, uint16_t *red,
                       uint16_t *green, uint16_t *blue)
{
    uint8_t buf[8];

    if (i2c_read_block(handle, TCS34725_CDATAL, buf, sizeof(buf)) < 0)
        return -1;

    *clear = (uint16_t)((buf[1] << 8) | buf[0]);
    *red   = (uint16_t)((buf[3] << 8) | buf[2]);
    *green = (uint16_t)((buf[5] << 8) | buf[4]);
    *blue  = (uint16_t)((buf[7] << 8) | buf[6]);

    return 0;
}

static int log_data(FILE *f, uint16_t c, uint16_t r, uint16_t g, uint16_t b)
{
    time_t now = time(NULL);
    if (fprintf(f, "%ld,%u,%u,%u,%u\n", (long)now, c, r, g, b) < 0)
        return -1;
    fflush(f);
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen(CSV_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s\n", CSV_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fprintf(fp, "timestamp,clear,red,green,blue\n") < 0) {
        fprintf(stderr, "Failed to write CSV header\n");
        fclose(fp);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Color sensor logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t c, r, g, b;

        if (read_sensor(i2c_handle, &c, &r, &g, &b) == 0) {
            if (log_data(fp, c, r, g, b) < 0)
                fprintf(stderr, "Failed to log data\n");
        } else {
            fprintf(stderr, "Sensor read failed; setting values to 0\n");
            c = r = g = b = 0;
            if (log_data(fp, c, r, g, b) < 0)
                fprintf(stderr, "Failed to log data (error state)\n");
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");

    if (fp) {
        fclose(fp);
        fp = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

