#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_LAMPS 4
#define SUNRISE_DURATION 3600
#define SUNSET_DURATION 3600
#define DAYTIME_DURATION 21600
#define NIGHTTIME_DURATION 51840

static const unsigned int lamp_pins[NUM_LAMPS] = {17, 27, 22, 23};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_LAMPS];
static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_LAMPS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);  // relays active-low: 1 = off
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }
    for (int i = 0; i < NUM_LAMPS; i++) {
        lines[i] = gpiod_chip_get_line(chip, lamp_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", lamp_pins[i]);
            cleanup();
            return -1;
        }
        if (gpiod_line_request_output(lines[i], "sunlight-sim", 1) < 0) {
            fprintf(stderr, "Failed to request output on GPIO %u\n", lamp_pins[i]);
            cleanup();
            return -1;
        }
    }
    return 0;
}

static void set_lamp(int lamp, int state) {
    if (lamp < 0 || lamp >= NUM_LAMPS) return;
    gpiod_line_set_value(lines[lamp], state ? 0 : 1);
}

static void all_lamps_off(void) {
    for (int i = 0; i < NUM_LAMPS; i++) {
        set_lamp(i, 0);
    }
}

static void sleep_seconds(unsigned int seconds) {
    while (seconds > 0 && keep_running) {
        unsigned int chunk = (seconds > 1) ? 1 : seconds;
        sleep(chunk);
        seconds -= chunk;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    while (keep_running) {
        printf("Sunrise\n");
        for (int duty = 0; duty <= 100 && keep_running; duty++) {
            for (int i = 0; i < NUM_LAMPS; i++) {
                set_lamp(i, (duty > 0) ? 1 : 0);
            }
            sleep_seconds(SUNRISE_DURATION / 100);
        }
        if (!keep_running) break;

        printf("Daytime\n");
        sleep_seconds(DAYTIME_DURATION);

        if (!keep_running) break;

        printf("Sunset\n");
        for (int duty = 100; duty >= 0 && keep_running; duty--) {
            for (int i = 0; i < NUM_LAMPS; i++) {
                set_lamp(i, (duty > 0) ? 1 : 0);
            }
            sleep_seconds(SUNSET_DURATION / 100);
        }
        if (!keep_running) break;

        printf("Nighttime\n");
        all_lamps_off();
        sleep_seconds(NIGHTTIME_DURATION);
    }

    cleanup();
    return EXIT_SUCCESS;
}

