#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>

#define MOTION_SENSOR_GPIO 17
#define VIDEO_DURATION 5
#define DEBOUNCE_DELAY_US 200000
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: %s exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        perror("mkdir");
        return -1;
    }
    return 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) return -1;
    if (strftime(buf, len, "%Y%m%d_%H%M%S", timeinfo) == 0) return -1;
    return 0;
}

static int log_motion(const char *timestamp) {
    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            perror("fopen log");
            return -1;
        }
    }
    if (fprintf(log_fp, "%s Motion detected\n", timestamp) < 0) {
        perror("fprintf log");
        return -1;
    }
    fflush(log_fp);
    return 0;
}

static int record_video(const char *timestamp) {
    char filepath[256];
    char command[512];
    snprintf(filepath, sizeof(filepath), "%s%s.%d.h264", VIDEO_DIR, timestamp, VIDEO_DURATION);
    snprintf(command, sizeof(command), "raspivid -o %s -t %d -w 640 -h 480 -fps 15 -g 10 -q 10 -n", filepath, VIDEO_DURATION * 1000);
    int status = system(command);
    if (status == -1) {
        perror("system");
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    if (WIFSIGNALED(status)) {
        fprintf(stderr, "raspivid killed by signal %d\n", WTERMSIG(status));
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(MOTION_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(MOTION_SENSOR_GPIO, PI_PUD_UP);

    if (ensure_directory(VIDEO_DIR) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", MOTION_SENSOR_GPIO);

    uint32_t last_trigger_tick = 0;

    while (running) {
        int motion = gpioRead(MOTION_SENSOR_GPIO);
        if (motion < 0) {
            fprintf(stderr, "gpioRead failed\n");
            break;
        }

        if (motion == 0) {
            uint32_t now = gpioTick();
            uint32_t elapsed = now - last_trigger_tick;
            if (last_trigger_tick == 0 || elapsed >= DEBOUNCE_DELAY_US) {
                char timestamp[32];
                if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                    printf("Motion detected at %s\n", timestamp);
                    if (log_motion(timestamp) != 0) {
                        fprintf(stderr, "Failed to log motion event\n");
                    }
                    if (record_video(timestamp) != 0) {
                        fprintf(stderr, "Failed to record video\n");
                    }
                    last_trigger_tick = now;
                } else {
                    fprintf(stderr, "Failed to generate timestamp\n");
                }
            }
        }
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

