#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* MPU-6050 I2C address (AD0 low) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_REG_PWR_MGMT_1   0x6B
#define MPU6050_REG_SMPLRT_DIV   0x19
#define MPU6050_REG_GYRO_CONFIG   0x1B
#define MPU6050_REG_GYRO_XOUT_H   0x43
#define MPU6050_REG_GYRO_XOUT_L   0x44
#define MPU6050_REG_GYRO_YOUT_H   0x45
#define MPU6050_REG_GYRO_YOUT_L   0x46
#define MPU6050_REG_GYRO_ZOUT_H   0x47
#define MPU6050_REG_GYRO_ZOUT_L   0x48

/* Sensitivity scale factor for ±250°/s range: 131 LSB per °/s */
#define GYRO_SCALE 131.0f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Sampling interval in microseconds (100 Hz) */
#define SAMPLE_INTERVAL_US 10000

/* Maximum re-initialization attempts on read failure */
#define MAX_REINIT_ATTEMPTS 3

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an MPU-6050 register; returns 0 on success, -1    */
/* on failure.                                                         */
/* ------------------------------------------------------------------ */
static int mpu_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the MPU-6050: wake, set sample rate, set gyro range.     */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int mpu_init(int handle)
{
    /* Wake up the device (clear SLEEP bit) */
