#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define NUM_ZONES 4
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define POLL_INTERVAL_SEC 5

static const int relay_pins[NUM_ZONES] = {4, 17, 27, 22};
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_ZONES; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {  /* HIGH = relay OFF (active-low) */
            fprintf(stderr, "Error: failed to initialize GPIO %d HIGH.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(int zone) {
    return rand() % 101;
}

static int control_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d to %d.\n", pin, state);
        return -1;
    }
    return 0;
}

static int log_data(int zone, int moisture, int relay_state) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed.\n");
        return -1;
    }

    struct tm *tstruct = localtime(&now);
    if (tstruct == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return -1;
    }

    char buf[80];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct) == 0) {
        fprintf(stderr, "Error: strftime() failed.\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Zone %d: Moisture = %d, Relay = %s\n",
                buf, zone, moisture, relay_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error: fprintf to log failed.\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }
    return 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_ZONES; i++) {
        gpioWrite(relay_pins[i], 1);  /* HIGH = OFF */
    }
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    srand((unsigned int)time(NULL));

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_ZONES; i++) {
            int moisture = read_moisture_sensor(i + 1);
            int relay_state = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;  /* 0 = ON, 1 = OFF */

            if (control_relay(relay_pins[i], relay_state) != 0) {
                fprintf(stderr, "Error: failed to control relay on GPIO %d.\n", relay_pins[i]);
            }

            if (log_data(i + 1, moisture, relay_state) != 0) {
                fprintf(stderr, "Error: failed to log data for zone %d.\n", i + 1);
            }
        }

        for (int s = 0; s < POLL_INTERVAL_SEC && running; s++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

