#include <pthread.h>
#include <errno.h>

#define TRIG_PIN 4
#define ECHO_PIN 18
#define TRIG_PULSE_US 10
#define ECHO_TIMEOUT_US 100000
#define MAX_PULSE_US 23200
#define LOOP_DELAY_US 200000
#define LOG_FILE "distance_log.txt"

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int echo_timeout = 0;
static FILE *log_file = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t running = 1;

static void trigger_pulse(void) {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIG_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    pthread_mutex_lock(&mutex);
    if (level == 1) {
        start_tick = tick;
        echo_received = 0;
        echo_timeout = 0;
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 1;
    }
    pthread_mutex_unlock(&mutex);
}

static double calculate_distance_cm(uint32_t start, uint32_t end) {
    uint32_t diff = end - start;
    if (diff > 0x80000000U) {
        diff = 0;
    }
    return (double)diff / 58.0;
}

static void log_distance(double distance) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long long ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
    if (fprintf(log_file, "%lld,%.2f\n", ns, distance) < 0) {
        perror("fprintf");
    }
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIG_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN pull-down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_received = 0;
        echo_timeout = 0;
        trigger_pulse();

        uint32_t wait_start = gpioTick();
        while (!echo_received && !echo_timeout && running) {
            if (gpioTick() - wait_start > ECHO_TIMEOUT_US) {
                echo_timeout = 1;
                break;
            }
            gpioDelay(100);
        }

        pthread_mutex_lock(&mutex);
        if (echo_timeout) {
            pthread_mutex_unlock(&mutex);
            continue;
        }
        if (!echo_received) {
            pthread_mutex_unlock(&mutex);
            continue;
        }
        uint32_t pulse_us = end_tick - start_tick;
        if (pulse_us > MAX_PULSE_US) {
            pthread_mutex_unlock(&mutex);
            continue;
        }
        double distance = calculate_distance_cm(start_tick, end_tick);
        pthread_mutex_unlock(&mutex);

        log_distance(distance);
    }

    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&mutex);
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

