#define NUM_RETRIES 3
#define RETRY_DELAY_US 10000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    for (int attempt = 0; attempt < NUM_RETRIES; attempt++) {
        int result = i2cWriteByteData(i2c_handle, reg, value);
        if (result == 0) return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %d\n", reg, attempt + 1, NUM_RETRIES, result);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    for (int attempt = 0; attempt < NUM_RETRIES; attempt++) {
        int result = i2cReadByteData(i2c_handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0;
        }
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d): %d\n", reg, attempt + 1, NUM_RETRIES, result);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    for (int attempt = 0; attempt < NUM_RETRIES; attempt++) {
        int result = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
        if (result == (int)len) return 0;
        fprintf(stderr, "I2C block read from reg 0x%02X failed (attempt %d/%d): %d\n", reg, attempt + 1, NUM_RETRIES, result);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int init_lis3dh(void) {
    if (i2c_write_reg(CTRL_REG1, 0x77) != 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1\n");
        return -1;
    }
    if (i2c_write_reg(CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Failed to configure CTRL_REG4\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(OUT_X_L, buf, 6) != 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x / ACCEL_SENSITIVITY;
    *y = (float)raw_y / ACCEL_SENSITIVITY;
    *z = (float)raw_z / ACCEL_SENSITIVITY;
    return 0;
}

static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void activate_buzzer(int duration_ms) {
    gpioWrite(BUZZER_GPIO, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(BUZZER_GPIO, 0);
}

int main(int argc, char *argv[]) {
    float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    if (argc > 1) freefall_threshold = atof(argv[1]);
    if (argc > 2) impact_threshold = atof(argv[2]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n", I2C_BUS, LIS3DH_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lis3dh() != 0) {
        fprintf(stderr, "LIS3DH initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Fall detection started. Freefall threshold: %.2f g, Impact threshold: %.2f g\n", freefall_threshold, impact_threshold);

    bool in_freefall = false;

    while (!terminate) {
        float x, y, z;
        if (read_acceleration(&x, &y, &z) != 0) {
            fprintf(stderr, "Read error, continuing...\n");
            gpioDelay(100000);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude < freefall_threshold && !in_freefall) {
            in_freefall = true;
            printf("Freefall detected! Magnitude: %.2f g\n", magnitude);
        }

        if (in_freefall && magnitude > impact_threshold) {
            printf("Impact detected! Magnitude: %.2f g\n", magnitude);
            activate_buzzer(1000);
            in_freefall = false;
        }

        gpioDelay(10000);
    }

    printf("\nCleaning up...\n");
    gpioWrite(BUZZER_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

