#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define LOG_FILE "/var/log/high_acceleration.log"
#define DEFAULT_THRESHOLD 2.0f
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(int addr) {
    i2c_handle = i2cOpen(I2C_BUS, addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", addr, i2c_handle);
        return -1;
    }
    return 0;
}

static int configure_sensor(int addr) {
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1 at 0x%02X\n", addr);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x88) < 0) {
        fprintf(stderr, "Error writing CTRL_REG4 at 0x%02X\n", addr);
        return -1;
    }
    return 0;
}

static int read_acceleration(int addr, float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buf, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data from 0x%02X\n", addr);
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;
    return 0;
}

static void log_event(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - High acceleration detected: X=%.3f g, Y=%.3f g, Z=%.3f g\n", ts, x, y, z);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int addr = LIS3DH_ADDR;
    float threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                addr = (int)strtol(optarg, NULL, 16);
                if (addr < 0x08 || addr > 0x77) {
                    fprintf(stderr, "Invalid I2C address 0x%02X (must be 0x08-0x77)\n", addr);
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Threshold must be greater than 0\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold_g]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (running in non-hardware environment?)\n");
        return 0;
    }

    signal(SIGINT, signal_handler);

    if (init_i2c(addr) != 0) {
        gpioTerminate();
        return 1;
    }

    if (configure_sensor(addr) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("LIS3DH accelerometer monitoring started at 0x%02X (threshold %.2f g)\n", addr, threshold);

    while (running) {
        float x, y, z;
        if (read_acceleration(addr, &x, &y, &z) == 0) {
            if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
                log_event(x, y, z);
                printf("High acceleration detected! Logging and shutting down...\n");
                system("sudo shutdown -h now");
                break;
            }
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

