#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN  4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_PIN        22

#define BUFFER_SIZE 5
#define ALERT_THRESHOLD 5
#define ALERT_DURATION_MS 2000
#define POLL_INTERVAL_US 10000

#define MOTOR_FORWARD 1
#define MOTOR_LEFT    2
#define MOTOR_RIGHT   3
#define MOTOR_STOP    0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    int left;
    int center;
    int right;
} sensor_data_t;

static sensor_data_t sensor_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int center_no_line_count = 0;

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *left_line = NULL;
static struct gpiod_line *center_line = NULL;
static struct gpiod_line *right_line = NULL;
static struct gpiod_line *alert_line = NULL;

static void cleanup(void) {
    if (alert_line) {
        gpiod_line_set_value(alert_line, 0);
        gpiod_line_release(alert_line);
        alert_line = NULL;
    }
    if (left_line) { gpiod_line_release(left_line); left_line = NULL; }
    if (center_line) { gpiod_line_release(center_line); center_line = NULL; }
    if (right_line) { gpiod_line_release(right_line); right_line = NULL; }
    if (chip) { gpiod_chip_close(chip); chip = NULL; }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return -1;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);
    if (!left_line || !center_line || !right_line || !alert_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(left_line, "line_follower") < 0 ||
        gpiod_line_request_input(center_line, "line_follower") < 0 ||
        gpiod_line_request_input(right_line, "line_follower") < 0) {
        fprintf(stderr, "Failed to request sensor lines as input: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(alert_line, "line_follower", 0) < 0) {
        fprintf(stderr, "Failed to request alert line as output: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_sensor(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Failed to read sensor: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

static void log_sensor_data(int left, int center, int right) {
    sensor_buffer[buffer_index].left = left;
    sensor_buffer[buffer_index].center = center;
    sensor_buffer[buffer_index].right = right;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void check_alert(void) {
    if (center_no_line_count >= ALERT_THRESHOLD) {
        printf("Alert triggered! Center sensor has no line for %d consecutive readings.\n", ALERT_THRESHOLD);
        if (gpiod_line_set_value(alert_line, 1) < 0) {
            fprintf(stderr, "Failed to set alert HIGH: %s\n", strerror(errno));
            return;
        }
        usleep(ALERT_DURATION_MS * 1000);
        if (gpiod_line_set_value(alert_line, 0) < 0) {
            fprintf(stderr, "Failed to set alert LOW: %s\n", strerror(errno));
        }
        center_no_line_count = 0;
    }
}

static void control_motors(int direction) {
    switch (direction) {
        case MOTOR_FORWARD: printf("Moving forward\n"); break;
        case MOTOR_LEFT:    printf("Turning left\n"); break;
        case MOTOR_RIGHT:   printf("Turning right\n"); break;
        case MOTOR_STOP:    printf("Stopping\n"); break;
        default:            printf("Invalid motor direction\n"); break;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line follower started. Press Ctrl+C to exit.\n");

    while (running) {
        int left = read_sensor(left_line);
        int center = read_sensor(center_line);
        int right = read_sensor(right_line);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        log_sensor_data(left, center, right);

        if (center == 1) {
            center_no_line_count++;
        } else {
            center_no_line_count = 0;
        }

        check_alert();

        if (center == 0) {
            control_motors(MOTOR_FORWARD);
        } else if (left == 0) {
            control_motors(MOTOR_LEFT);
        } else if (right == 0) {
            control_motors(MOTOR_RIGHT);
        } else {
            control_motors(MOTOR_STOP);
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

