#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS        1
#define SI7210_ADDR    0x30
#define RELAY_GPIO     17
#define THRESHOLD_MT   5.0f
#define SAMPLE_US      100000
#define POLL_US        1000
#define POLL_MAX       50
#define LOG_FILE       "magnetic_events.txt"

#define SI7210_REG_FIELD_MSB  0xC0
#define SI7210_REG_FIELD_LSB  0xC1
#define SI7210_REG_MEAS_START 0xC1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "<unknown time> %s\n", msg);
    }
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    return 0;
}

static int init_i2c(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n",
                SI7210_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_register(uint8_t reg, uint8_t *val) {
    int r = i2cReadByteData(g_i2c_handle, reg);
    if (r < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, r);
        return -1;
    }
    *val = (uint8_t)r;
    return 0;
}

static int write_register(uint8_t reg, uint8_t val) {
    int r = i2cWriteByteData(g_i2c_handle, reg, val);
    if (r < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, r);
        return -1;
    }
    return 0;
}

static int read_field_raw(int16_t *field_raw) {
    uint8_t msb, lsb;

    if (write_register(SI7210_REG_MEAS_START, 0x01) != 0)
        return -1;

    for (int i = 0; i < POLL_MAX; i++) {
        if (read_register(SI7210_REG_FIELD_LSB, &lsb) != 0)
            return -1;
        if (lsb == 0x00)
            break;
        gpioDelay(POLL_US);
    }

    if (read_register(SI7210_REG_FIELD_MSB, &msb) != 0)
        return -1;

    *field_raw = (int16_t)((msb << 8) | lsb);
    return 0;
}

static float convert_to_mT(int16_t raw) {
    return (float)raw * 25.0f / 1000.0f;
}

static void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_pigpio() != 0) {
        log_event("pigpio initialization failed");
        return 1;
    }

    if (init_i2c() != 0) {
        log_event("I2C initialization failed");
        gpioTerminate();
        return 1;
    }

    log_event("System initialized");

    int relay_state = 0;
    int error_count = 0;

    while (g_running) {
        int16_t raw;
        if (read_field_raw(&raw) != 0) {
            error_count++;
            if (error_count > 10) {
                log_event("Too many consecutive I2C errors, aborting");
                break;
            }
            control_relay(0);
            gpioDelay(SAMPLE_US);
            continue;
        }
        error_count = 0;

        float field_mT = convert_to_mT(raw);
        float threshold_mT = THRESHOLD_MT;

        if (field_mT > threshold_mT) {
            if (relay_state == 0) {
                control_relay(1);
                relay_state = 1;
                log_event("Relay activated");
            }
        } else {
            if (relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                log_event("Relay deactivated");
            }
        }

        char msg[128];
        snprintf(msg, sizeof(msg), "Field: %.2f mT, Threshold: %.2f mT, Relay: %d",
                 field_mT, threshold_mT, relay_state);
        log_event(msg);

        gpioDelay(SAMPLE_US);
    }

    log_event("Shutting down");
    cleanup();
    return 0;
}

