                break;
            }
            control_relay(0);
            gpioDelay(SAMPLE_US);
            continue;
        }
        error_count = 0;

        float field_mT = convert_to_mT(raw);
        float threshold_mT = THRESHOLD_MT;

        if (field_mT > threshold_mT) {
            if (relay_state == 0) {
                control_relay(1);
                relay_state = 1;
                log_event("Relay activated");
            }
        } else {
            if (relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                log_event("Relay deactivated");
            }
        }

        char msg[128];
        snprintf(msg, sizeof(msg), "Field: %.2f mT, Threshold: %.2f mT, Relay: %d",
                 field_mT, threshold_mT, relay_state);
        log_event(msg);

        gpioDelay(SAMPLE_US);
    }

    log_event("Shutting down");
    cleanup();
    return 0;
}

