/*
 * Raspberry Pi Zero W – dual Sensirion SLF3S-1300F liquid flow monitor
 * Library : pigpio (I2C + GPIO)
 * Sensors : 2 × SLF3S-1300F on I2C bus 1
 *   Sensor 1 → 0x08   Sensor 2 → 0x09
 * Relay   : active-high on GPIO 18 (BCM)
 * Logic   : energize relay when either sensor < 5.0 ml/min
 *           de-energize when both ≥ 5.0 ml/min
 * Build   : gcc -Wall -Wextra -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run     : sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define SENSOR1_ADDR       0x08
#define SENSOR2_ADDR       0x09
#define RELAY_GPIO         18          /* BCM pin, active-high relay */
#define FLOW_THRESHOLD     5.0f        /* ml/min */
#define SCALE_FACTOR       (1.0f / 1500.0f)  /* SLF3S-1300F: 40 ml/min → 1/1500 */
#define POLL_DELAY_US      100000      /* 100 ms */
#define LOG_FILE           "flow_log.txt"

/* SLF3S start-measurement command (big-endian on the wire) */
static const uint8_t START_MEAS_CMD[2] = { 0x36, 0x08 };

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c1 = -1;
static int  g_i2c2 = -1;
static int  g_pigpio_ready = 0;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- CRC-8 (Sensirion) --------------------------- */
/* Polynomial 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* --------------------------- I2C helpers --------------------------------- */
static int i2c_open(int bus, int addr)
{
    int h = i2cOpen(bus, addr, 0);
    if (h < 0)
        fprintf(stderr, "[WARN] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                bus, addr, h);
    return h;
}

static int i2c_write_cmd(int handle, const uint8_t *cmd, size_t len)
{
    int rc = i2cWriteDevice(handle, (char *)cmd, len);
    if (rc < 0)
        fprintf(stderr, "[WARN] i2cWriteDevice(handle=%d) failed: %d\n", handle, rc);
    return rc;
}

static int i2c_read_bytes(int handle, uint8_t *buf, size_t len)
{
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc < 0)
        fprintf(stderr, "[WARN] i2cReadDevice(handle=%d) failed: %d\n", handle, rc);
    return rc;
}

/* --------------------------- Sensor read --------------------------------- */
/*
 * Returns 0 on success (flow_out set), -1 on I/O error, -2 on CRC mismatch.
 */
static int read_flow_rate(int handle, float *flow_out)
{
    uint8_t buf[3];

    if (i2c_read_bytes(handle, buf, sizeof(buf)) < 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[WARN] CRC mismatch on handle %d (calc=0x%02X recv=0x%02X)\n",
                handle, crc8(buf, 2), buf[2]);
        return -2;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw * SCALE_FACTOR;
    return 0;
}

/* --------------------------- Relay control ------------------------------- */
static int relay_set(int state)
{
    int rc = gpioWrite(RELAY_GPIO, state);
    if (rc < 0)
        fprintf(stderr, "[WARN] gpioWrite(RELAY=%d, %d) failed: %d\n",
                RELAY_GPIO, state, rc);
    return rc;
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_pigpio_ready) {
        relay_set(0);          /* de-energize relay */
        gpioTerminate();
        g_pigpio_ready = 0;
    }
    if (g_i2c1 >= 0) {
        i2cClose(g_i2c1);
        g_i2c1 = -1;
    }
    if (g_i2c2 >= 0) {
        i2cClose(g_i2c2);
        g_i2c2 = -1;
    }
}

/* --------------------------- Main ---------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_ready = 1;

    /* --- I2C open --- */
    g_i2c1 = i2c_open(I2C_BUS, SENSOR1_ADDR);
    g_i2c2 = i2c_open(I2C_BUS, SENSOR2_ADDR);
    if (g_i2c1 < 0 || g_i2c2 < 0) {
        fprintf(stderr, "[FATAL] One or more I2C sensors unavailable; aborting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Start measurement on both sensors --- */
    if (i2c_write_cmd(g_i2c1, START_MEAS_CMD, sizeof(START_MEAS_CMD)) < 0) {
        fprintf(stderr, "[FATAL] Failed to start sensor 1; aborting.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2c_write_cmd(g_i2c2, START_MEAS_CMD, sizeof(START_MEAS_CMD)) < 0) {
        fprintf(stderr, "[FATAL] Failed to start sensor 2; aborting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Relay GPIO setup --- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(RELAY=%d) failed\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (relay_set(0) < 0) {
        fprintf(stderr, "[FATAL] Initial relay de-energize failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("[FATAL] sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Main loop --- */
    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int  r1 = read_flow_rate(g_i2c1, &f1);
        int  r2 = read_flow_rate(g_i2c2, &f2);

        if (r1 == 0 && r2 == 0) {
            bool below = (f1 < FLOW_THRESHOLD) || (f2 < FLOW_THRESHOLD);
            if (below) {
                if (relay_set(1) == 0)
                    printf("[INFO] Energizing relay – f1=%.2f ml/min, f2=%.2f ml/min\n",
                           f1, f2);
            } else {
                if (relay_set(0) == 0)
                    printf("[INFO] De-energizing relay – f1=%.2f ml/min, f2=%.2f ml/min\n",
                           f1, f2);
            }

            /* Timestamped log entry */
            FILE *fp = fopen(LOG_FILE, "a");
            if (fp) {
                struct timespec ts;
                if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                    struct tm tmv;
                    localtime_r(&ts.tv_sec, &tmv);
                    char tbuf[32];
                    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tmv);
                    fprintf(fp, "%s.%03ld,%.2f,%.2f\n",
                            tbuf, ts.tv_nsec / 1000000, f1, f2);
                }
                fclose(fp);
            } else {
                perror("[WARN] fopen(" LOG_FILE ")");
            }
        } else {
            /* On read/CRC error, ensure relay is safe and skip this cycle */
            if (r1 != 0 || r2 != 0)
                fprintf(stderr, "[WARN] Sensor read error (s1=%d, s2=%d); skipping cycle.\n",
                        r1, r2);
        }

        gpioDelay(POLL_DELAY_US);   /* 100 ms */
    }

    /* --- Graceful shutdown --- */
    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

