#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24

#define POLL_INTERVAL_US  200000   /* 200 ms */
#define MOTOR_RUN_US      5000000  /* 5 s   */
#define DRY_THRESHOLD     3        /* 3 dry polls = ~600 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_write(unsigned pin, unsigned level, const char *label)
{
    if (gpioWrite(pin, level) < 0) {
        syslog(LOG_ERR, "gpioWrite(%u, %u) failed for %s", pin, level, label);
        return -1;
    }
    return 0;
}

static int motor_stop(void)
{
    int rc = 0;
    rc |= safe_write(MOTOR_ENA_PIN, 0, "MOTOR_ENA");
    rc |= safe_write(MOTOR_IN1_PIN, 0, "MOTOR_IN1");
    rc |= safe_write(MOTOR_IN2_PIN, 0, "MOTOR_IN2");
    return rc;
}

static int motor_close(void)
{
    int rc = 0;
    rc |= safe_write(MOTOR_ENA_PIN, 1, "MOTOR_ENA");
    rc |= safe_write(MOTOR_IN1_PIN, 1, "MOTOR_IN1");
    rc |= safe_write(MOTOR_IN2_PIN, 0, "MOTOR_IN2");
    if (rc == 0)
        syslog(LOG_INFO, "Motor started: ENA=1 IN1=1 IN2=0 (closing window)");
    return rc;
}

static int motor_run(void)
{
    int rc = 0;
    for (int i = 0; i < 50 && g_running; i++) {
        rc |= safe_write(MOTOR_ENA_PIN, 1, "MOTOR_ENA");
        rc |= safe_write(MOTOR_IN1_PIN, 1, "MOTOR_IN1");
        rc |= safe_write(MOTOR_IN2_PIN, 0, "MOTOR_IN2");
        if (rc != 0)
            return -1;
        gpioDelay(100000); /* 100 ms */
    }
    return rc;
}

static int motor_stop_and_release(void)
{
    int rc = 0;
    rc |= safe_write(MOTOR_ENA_PIN, 0, "MOTOR_ENA");
    rc |= safe_write(MOTOR_IN1_PIN, 0, "MOTOR_IN1");
    rc |= safe_write(MOTOR_IN2_PIN, 0, "MOTOR_IN2");
    if (rc == 0)
        syslog(LOG_INFO, "Motor stopped and released");
    return rc;
}

static int read_rain_sensor(void)
{
    int v = gpioRead(RAIN_SENSOR_PIN);
    if (v < 0)
        syslog(LOG_ERR, "gpioRead(%d) failed", RAIN_SENSOR_PIN);
    return v;
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Rain-actuated window controller starting");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "pigpio initialised");

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, INPUT) failed", RAIN_SENSOR_PIN);
        goto fail;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(%d, UP) failed", RAIN_SENSOR_PIN);
        goto fail;
    }

    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed for motor pins");
        goto fail;
    }

    if (motor_stop() != 0)
        goto fail;

    int dry_count = 0;
    int last_rain = 0;

    while (g_running) {
        int rain = read_rain_sensor();
        if (rain < 0) {
            syslog(LOG_ERR, "Rain sensor read error; retrying");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (rain == 0) {
            dry_count++;
            if (dry_count >= DRY_THRESHOLD) {
                dry_count = 0;
                syslog(LOG_INFO, "Dry for %d polls; window closed", DRY_THRESHOLD);
            }
        } else {
            dry_count = 0;
            if (last_rain == 0) {
                syslog(LOG_INFO, "Rain detected (DO=0) - closing window");
                if (motor_run() == 0) {
                    if (motor_stop_and_release() != 0)
                        syslog(LOG_ERR, "Motor stop failed after run");
                } else {
                    syslog(LOG_ERR, "Motor run failed");
                }
            }
            last_rain = 1;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    motor_stop();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;

fail:
    motor_stop();
    gpioTerminate();
    closelog();
    return EXIT_FAILURE;
}

