#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define SERVO_LOCK_US  2000   /* 2 ms pulse -> locked */
#define SERVO_UNLOCK_US 1000  /* 1 ms pulse -> unlocked */
#define DEBOUNCE_US    200000 /* 200 ms debounce */
#define POLL_US        10000  /* 10 ms poll interval */
#define SHUTDOWN_US    0      /* 0 pulse = servo off */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse(int pulse_us)
{
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo(%d) failed\n", pulse_us);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop servo pulses and release pigpio resources */
    gpioServo(SERVO_PIN, SHUTDOWN_US);
    gpioTerminate();
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure servo pin as output */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SERVO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with internal pull-ups */
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(LOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(UNLOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(LOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(UNLOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");
    printf("  GPIO %d (BCM): lock button (to GND)\n", LOCK_BUTTON);
    printf("  GPIO %d (BCM): unlock button (to GND)\n", UNLOCK_BUTTON);
    printf("  GPIO %d (BCM): servo signal\n", SERVO_PIN);
    printf("  Press lock button -> servo locked (2000 us)\n");
    printf("  Press unlock button -> servo unlocked (1000 us)\n");
    fflush(stdout);

    int last_lock_state = 1;   /* assume released (pull-up high) */
    int last_unlock_state = 1; /* assume released (pull-up high) */

    while (g_running) {
        int lock_state = gpioRead(LOCK_BUTTON);
        int unlock_state = gpioRead(UNLOCK_BUTTON);

        /* Detect falling edge on lock button (pressed -> low) */
        if (lock_state == 0 && last_lock_state == 1) {
            if (set_servo_pulse(SERVO_LOCK_US) == 0) {
                printf("Locking door...\n");
                fflush(stdout);
            }
            /* Debounce: wait for release and debounce delay */
            while (g_running && gpioRead(LOCK_BUTTON) == 0) {
                gpioDelay(POLL_US);
            }
            gpioDelay(DEBOUNCE_US);
            last_lock_state = 0;
        } else if (lock_state == 1 && last_lock_state == 0) {
            last_lock_state = 1;
        }

        /* Detect falling edge on unlock button (pressed -> low) */
        if (unlock_state == 0 && last_unlock_state == 1) {
            if (set_servo_pulse(SERVO_UNLOCK_US) == 0) {
                printf("Unlocking door...\n");
                fflush(stdout);
            }
            /* Debounce: wait for release and debounce delay */
            while (g_running && gpioRead(UNLOCK_BUTTON) == 0) {
                gpioDelay(POLL_US);
            }
            gpioDelay(DEBOUNCE_US);
            last_unlock_state = 0;
        } else if (unlock_state == 1 && last_unlock_state == 0) {
            last_unlock_state = 1;
        }

        gpioDelay(POLL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

