    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(UNLOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");
    printf("  GPIO %d (BCM): lock button (to GND)\n", LOCK_BUTTON);
    printf("  GPIO %d (BCM): unlock button (to GND)\n", UNLOCK_BUTTON);
    printf("  GPIO %d (BCM): servo signal\n", SERVO_PIN);
    printf("  Press lock button -> servo locked (2000 us)\n");
    printf("  Press unlock button -> servo unlocked (1000 us)\n");
    fflush(stdout);

    int last_lock_state = 1;   /* assume released (pull-up high) */
    int last_unlock_state = 1; /* assume released (pull-up high) */

    while (g_running) {
        int lock_state = gpioRead(LOCK_BUTTON);
        int unlock_state = gpioRead(UNLOCK_BUTTON);

        /* Detect falling edge on lock button (pressed -> low) */
        if (lock_state == 0 && last_lock_state == 1) {
            if (set_servo_pulse(SERVO_LOCK_US) == 0) {
                printf("Locking door...\n");
                fflush(stdout);
            }
            /* Debounce: wait for release and debounce delay */
            while (g_running && gpioRead(LOCK_BUTTON) == 0) {
                gpioDelay(POLL_US);
            }
            gpioDelay(DEBOUNCE_US);
            last_lock_state = 0;
        } else if (lock_state == 1 && last_lock_state == 0) {
            last_lock_state = 1;
        }

        /* Detect falling edge on unlock button (pressed -> low) */
        if (unlock_state == 0 && last_unlock_state == 1) {
            if (set_servo_pulse(SERVO_UNLOCK_US) == 0) {
                printf("Unlocking door...\n");
                fflush(stdout);
            }
            /* Debounce: wait for release and debounce delay */
            while (g_running && gpioRead(UNLOCK_BUTTON) == 0) {
                gpioDelay(POLL_US);
            }
            gpioDelay(DEBOUNCE_US);
            last_unlock_state = 0;
        } else if (unlock_state == 1 && last_unlock_state == 0) {
            last_unlock_state = 1;
        }

        gpioDelay(POLL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

