#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_GPIO        4
#define FLOODLIGHT_GPIO 17
#define LOG_FILE        "security_log.txt"
#define POLL_DELAY_US   100000   /* 100 ms */
#define FLOODLIGHT_ON_S 60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_event(const char *event, int duration)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (duration >= 0) {
        fprintf(fp, "%s - %s (Duration: %d seconds)\n", ts, event, duration);
    } else {
        fprintf(fp, "%s - %s\n", ts, event);
    }

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

static int set_floodlight(int state)
{
    if (gpioWrite(FLOODLIGHT_GPIO, state) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", FLOODLIGHT_GPIO, state);
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(PIR_GPIO, PI_INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOODLIGHT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(FLOODLIGHT_GPIO, PI_OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_floodlight(0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        set_floodlight(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        set_floodlight(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Security Light started. PIR=GPIO%d, Floodlight=GPIO%d, Log=%s\n",
           PIR_GPIO, FLOODLIGHT_GPIO, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    int last_pir = gpioRead(PIR_GPIO);
    if (last_pir < 0) {
        fprintf(stderr, "gpioRead(PIR_GPIO) initial failed\n");
        set_floodlight(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int pir = gpioRead(PIR_GPIO);
        if (pir < 0) {
            fprintf(stderr, "gpioRead(PIR_GPIO) failed\n");
            break;
        }

        if (pir == 1 && last_pir == 0) {
            printf("Motion detected! Activating floodlight for %d seconds.\n", FLOODLIGHT_ON_S);
            if (set_floodlight(1) < 0) {
                break;
            }
            if (log_event("Motion Detected", -1) < 0) {
                set_floodlight(0);
                gpioTerminate();
                return EXIT_FAILURE;
            }

            time_t start = time(NULL);
            if (start == (time_t)-1) {
                perror("time()");
                break;
            }

            while (g_running) {
                if (time(NULL) - start >= FLOODLIGHT_ON_S) {
                    break;
                }
                gpioDelay(POLL_DELAY_US);
            }

            if (set_floodlight(0) < 0) {
                break;
            }
            time_t end = time(NULL);
            if (end == (time_t)-1) {
                perror("time()");
                break;
            }
            int duration = (int)(end - start);
            if (log_event("Floodlight Deactivated", duration) < 0) {
                break;
            }
            printf("Floodlight deactivated. Duration: %d seconds.\n", duration);
        }

        last_pir = pir;
        gpioDelay(POLL_DELAY_US);
    }

    set_floodlight(0);
    gpioTerminate();
    printf("Smart Security Light stopped.\n");
    return EXIT_SUCCESS;
}

