#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MPR121_ADDR    0x5A
#define RELAY_GPIO     17
#define DEBOUNCE_MS    200
#define POLL_MS        10

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET      0x80
#define MPR121_MHD_F         0x2B
#define MPR121_NHD_F         0x2C
#define MPR121_NCL_F         0x2D
#define MPR121_FDL_F         0x2E
#define MPR121_MHD_R         0x2F
#define MPR121_NHD_R         0x30
#define MPR121_NCL_R         0x31
#define MPR121_FDL_R         0x32
#define MPR121_NHD_PROX      0x33
#define MPR121_NCL_PROX      0x34
#define MPR121_FDL_PROX      0x35
#define MPR121_NHD_T         0x36
#define MPR121_NCL_T         0x37
#define MPR121_FDL_T         0x38
#define MPR121_NHD_E         0x39
#define MPR121_NCL_E         0x3A
#define MPR121_FDL_E         0x3B
#define MPR121_E0TTH         0x41
#define MPR121_E0RTH         0x42
#define MPR121_DEBOUNCE      0x5B
#define MPR121_CONFIG1       0x5C
#define MPR121_CONFIG2       0x5D
#define MPR121_AUTO_CONFIG0  0x7B
#define MPR121_AUTO_CONFIG1  0x7C
#define MPR121_AUTO_CONFIG2  0x7D
#define MPR121_USL           0x7E
#define MPR121_LSL           0x7F
#define MPR121_TL            0x80
#define MPR121_CL            0x81
#define MPR121_E0FH          0x0C
#define MPR121_E0FL          0x0D

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int mpr121_write(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X val=0x%02X rc=%d\n", reg, value, rc);
    }
    return rc;
}

static int mpr121_read_word(int handle, uint8_t reg) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X rc=%d\n", reg, rc);
    }
    return rc;
}

static int mpr121_init(int handle) {
    /* Soft reset */
    if (mpr121_write(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000); /* 10 ms */

    /* Baseline filtering (F) */
    if (mpr121_write(handle, MPR121_MHD_F, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHD_F, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCL_F, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDL_F, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_MHD_R, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHD_R, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCL_R, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDL_R, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHD_PROX, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCL_PROX, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDL_PROX, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHD_T, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCL_T, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDL_T, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHD_E, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCL_E, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDL_E, 0x00) < 0) return -1;

    /* Touch / release thresholds for electrode 0 */
    if (mpr121_write(handle, MPR121_E0TTH, 0x0F) < 0) return -1;
    if (mpr121_write(handle, MPR121_E0RTH, 0x0A) < 0) return -1;

    /* Debounce: 3 samples for both touch and release */
    if (mpr121_write(handle, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=6 samples, SFI=4 samples, CDT=0.5 us */
    if (mpr121_write(handle, MPR121_CONFIG1, 0x10) < 0) return -1;

    /* Auto-config: enable, 12 electrodes, 1 us charge time */
    if (mpr121_write(handle, MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Auto-config registers */
    if (mpr121_write(handle, MPR121_AUTO_CONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write(handle, MPR121_AUTO_CONFIG1, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_AUTO_CONFIG2, 0x00) < 0) return -1;

    /* Touch / release upper / lower limits */
    if (mpr121_write(handle, MPR121_USL, 0xC8) < 0) return -1;
    if (mpr121_write(handle, MPR121_LSL, 0x82) < 0) return -1;
    if (mpr121_write(handle, MPR121_TL, 0xFF) < 0) return -1;
    if (mpr121_write(handle, MPR121_CL, 0x00) < 0) return -1;

    /* Filter configuration for electrode 0 */
    if (mpr121_write(handle, MPR121_E0FH, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_E0FL, 0x01) < 0) return -1;

    /* Enable 12 electrodes */
    if (mpr121_write(handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;

    return 0;
}

static int read_touch_status(int handle, uint16_t *status) {
    int rc = mpr121_read_word(handle, MPR121_TOUCHSTATUS_L);
    if (rc < 0) return -1;
    *status = (uint16_t)(rc & 0x0FFF);
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: rc=%d\n",
                I2C_BUS, MPR121_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(g_i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    printf("MPR121 initialized. Monitoring electrode 0 for touch (Ctrl+C to exit)...\n");

    bool relay_state = false;
    bool last_touched = false;

    while (g_running) {
        uint16_t touch_status = 0;
        if (read_touch_status(g_i2c_handle, &touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(POLL_MS * 1000);
            continue;
        }

        bool electrode0_touched = (touch_status & 0x0001) != 0;

        if (electrode0_touched && !last_touched) {
            relay_state = !relay_state;
            gpioWrite(RELAY_GPIO, relay_state ? 1 : 0);
            printf("Relay %s\n", relay_state ? "ON" : "OFF");
        }

        last_touched = electrode0_touched;
        gpioDelay(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

