#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <pthread.h>
#include <gpiod.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"
#define MAX_BUFFER 1024
#define SERVO_MIN_PULSE 1000
#define SERVO_MAX_PULSE 2000
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define PWM_PERIOD_NS 20000000
#define PWM_STEP_NS 100000

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static pthread_t pwm_thread;
static int pwm_pulse_width = SERVO_MIN_PULSE;

static void log_message(const char *level, const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    syslog(level, "%s: %s", ts, fmt);
    if (log_file) {
        fprintf(log_file, "%s: %s", ts, fmt);
        vfprintf(log_file, fmt, args);
        fprintf(log_file, "\n");
        fflush(log_file);
    }
    va_end(args);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void *pwm_thread_func(void *arg) {
    (void)arg;
    while (running) {
        int val = gpiod_line_set_value(servo_line, 1);
        if (val < 0) {
            log_message(LOG_ERR, "PWM: failed to set line high: %s", strerror(errno));
            break;
        }
        struct timespec ts = {0, pwm_pulse_width};
        nanosleep(&ts, NULL);
        val = gpiod_line_set_value(servo_line, 0);
        if (val < 0) {
            log_message(LOG_ERR, "PWM: failed to set line low: %s", strerror(errno));
            break;
        }
        ts.tv_sec = 0;
        ts.tv_nsec = PWM_PERIOD_NS - pwm_pulse_width;
        nanosleep(&ts, NULL);
    }
    return NULL;
}

static int set_servo_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        log_message(LOG_ERR, "Invalid servo angle: %d (must be 0-180)", angle);
        return -1;
    }
    int pulse = SERVO_MIN_PULSE + (angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) / SERVO_MAX_ANGLE);
    pwm_pulse_width = pulse;
    log_message(LOG_INFO, "Servo angle set to %d (pulse %d us)", angle, pulse);
    return 0;
}

static int read_pir_sensor(void) {
    int val = gpiod_line_get_value(pir_line);
    if (val < 0) {
        log_message(LOG_ERR, "Failed to read PIR sensor: %s", strerror(errno));
        return -1;
    }
    return val;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open gpiochip4: %s", strerror(errno));
        return -1;
    }
    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_message(LOG_ERR, "Failed to get servo line %d: %s", SERVO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        servo_line = NULL;
        return -1;
    }
    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        log_message(LOG_ERR, "Failed to request servo line as output: %s", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        servo_line = NULL;
        pir_line = NULL;
        return -1;
    }
    if (gpiod_line_request_input(pir_line, "pir") < 0) {
        log_message(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        gpiod_line_release(servo_line);
        gpiod_chip_close(chip);
        chip = NULL;
        servo_line = NULL;
        pir_line = NULL;
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    if (servo_line) {
        gpiod_line_set_value(servo_line, 0);
        gpiod_line_release(servo_line);
        servo_line = NULL;
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_socket(void) {
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message(LOG_ERR, "setsockopt failed: %s", strerror(errno));
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s", strerror(errno));
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s", strerror(errno));
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    log_message(LOG_INFO, "Listening on port %d", PORT);
    return 0;
}

static void handle_client(int client_fd) {
    char buffer[MAX_BUFFER];
    ssize_t n = recv(client_fd, buffer, MAX_BUFFER - 1, 0);
    if (n < 0) {
        log_message(LOG_ERR, "recv failed: %s", strerror(errno));
        close(client_fd);
        return;
    }
    if (n == 0) {
        log_message(LOG_INFO, "Client disconnected");
        close(client_fd);
        return;
    }
    buffer[n] = '\0';
    char *newline = strpbrk(buffer, "\r\n");
    if (newline) *newline = '\0';
    char *cmd = strtok(buffer, " \r\n");
    if (!cmd) {
        log_message(LOG_INFO, "Empty command received");
        send(client_fd, "OK\n", 3, 0);
        close(client_fd);
        return;
    }
    if (strcmp(cmd, "SERVO") == 0) {
        char *arg = strtok(NULL, " \r\n");
        if (!arg) {
            log_message(LOG_INFO, "SERVO command missing argument");
            send(client_fd, "ERROR: missing argument\n", 20, 0);
            close(client_fd);
            return;
        }
        int angle = atoi(arg);
        if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
            log_message(LOG_INFO, "Invalid angle %d", angle);
            send(client_fd, "ERROR: angle out of range\n", 22, 0);
            close(client_fd);
            return;
        }
        if (set_servo_angle(angle) == 0) {
            char resp[64];
            snprintf(resp, sizeof(resp), "OK: angle %d\n", angle);
            send(client_fd, resp, strlen(resp), 0);
        } else {
            send(client_fd, "ERROR: servo set failed\n", 23, 0);
        }
    } else if (strcmp(cmd, "PIR") == 0) {
        int val = read_pir_sensor();
        if (val < 0) {
            send(client_fd, "ERROR: PIR read failed\n", 23, 0);
        } else {
            char resp[16];
            snprintf(resp, sizeof(resp), "PIR:%d\n", val);
            send(client_fd, resp, strlen(resp), 0);
        }
    } else {
        log_message(LOG_INFO, "Unknown command: %s", cmd);
        send(client_fd, "ERROR: unknown command\n", 22, 0);
    }
    close(client_fd);
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_message(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        closelog();
        return 1;
    }
    log_message(LOG_INFO, "Starting security system");

    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting");
        fclose(log_file);
        closelog();
        return 1;
    }
    if (init_socket() != 0) {
        log_message(LOG_ERR, "Socket initialization failed, exiting");
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    if (pthread_create(&pwm_thread, NULL, pwm_thread_func, NULL) != 0) {
        log_message(LOG_ERR, "Failed to create PWM thread: %s", strerror(errno));
        close(server_fd);
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Security system started");

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            log_message(LOG_ERR, "Accept failed: %s", strerror(errno));
            continue;
        }
        handle_client(client_fd);
    }

    log_message(LOG_INFO, "Shutting down");
    running = 0;
    pthread_join(pwm_thread, NULL);
    if (server_fd >= 0) close(server_fd);
    cleanup_gpio();
    if (log_file) fclose(log_file);
    closelog();
    return 0;
}

