#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BH1750_ADDR 0x23
#define BH1750_ONE_TIME_HIGH_RES 0x20
#define GROW_LIGHT_GPIO 23
#define LUX_THRESHOLD 150.0
#define I2C_BUS 1
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL_US 2000000
#define CONVERSION_DELAY_US 120000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux) {
    char cmd = BH1750_ONE_TIME_HIGH_RES;
    char buf[2];
    int rc;

    rc = i2cWriteDevice(handle, &cmd, 1);
    if (rc < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", rc);
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    rc = i2cReadDevice(handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "Unexpected byte count from I2C device: %d\n", rc);
        return -1;
    }

    unsigned int raw = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void control_grow_light(int gpio, float lux) {
    if (lux < LUX_THRESHOLD) {
        gpioWrite(gpio, 1);
        printf("Grow light ON (lux: %.2f)\n", lux);
    } else {
        gpioWrite(gpio, 0);
        printf("Grow light OFF (lux: %.2f)\n", lux);
    }
}

static void log_data(FILE *fp, float lux) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    }
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GROW_LIGHT_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GROW_LIGHT_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GROW_LIGHT_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, BH1750_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Grow light controller started. Logging to %s\n", LOG_FILE);

    while (running) {
        float lux = 0.0f;

        if (read_bh1750(i2c_handle, &lux) == 0) {
            control_grow_light(GROW_LIGHT_GPIO, lux);
            log_data(log_file, lux);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

