    }

    dout_line = gpiod_chip_get_line(chip, HX711_DOUT);
    if (!dout_line) {
        syslog(LOG_ERR, "Failed to get DOUT line (GPIO%d): %s", HX711_DOUT, strerror(errno));
        return -1;
    }

    sck_line = gpiod_chip_get_line(chip, HX711_SCK);
    if (!sck_line) {
        syslog(LOG_ERR, "Failed to get SCK line (GPIO%d): %s", HX711_SCK, strerror(errno));
        return -1;
    }

    solenoid_line = gpiod_chip_get_line(chip, SOLENOID);
    if (!solenoid_line) {
        syslog(LOG_ERR, "Failed to get solenoid line (GPIO%d): %s", SOLENOID, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(dout_line, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input: %s", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(sck_line, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output: %s", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(solenoid_line, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid as output: %s", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_hx711_raw(int32_t *out) {
    int val;
    int32_t data = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        val = gpiod_line_get_value(dout_line);
        if (val < 0) {
            syslog(LOG_ERR, "DOUT read failed: %s", strerror(errno));
            retries++;
            usleep(10000);
            continue;
        }

        if (val == 0) break;

        retries++;
        usleep(1000);
    }

    if (retries >= MAX_RETRIES) {
        syslog(LOG_ERR, "HX711 DOUT timeout after %d retries", MAX_RETRIES);
        return -1;
    }

    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck_line, 1) < 0) {
            syslog(LOG_ERR, "SCK high failed: %s", strerror(errno));
            return -1;
        }
        usleep(1);

        data <<= 1;
        val = gpiod_line_get_value(dout_line);
        if (val < 0) {
            syslog(LOG_ERR, "DOUT read during clock failed: %s", strerror(errno));
            return -1;
        }
        if (val) data |= 1;

        if (gpiod_line_set_value(sck_line, 0) < 0) {
            syslog(LOG_ERR, "SCK low failed: %s", strerror(errno));
            return -1;
        }
        usleep(1);
    }

    if (gpiod_line_set_value(sck_line, 1) < 0) {
        syslog(LOG_ERR, "Final SCK high failed: %s", strerror(errno));
        return -1;
    }
    usleep(1);
    if (gpiod_line_set_value(sck_line, 0) < 0) {
        syslog(LOG_ERR, "Final SCK low failed: %s", strerror(errno));
        return -1;
    }
    usleep(1);

    if (data & 0x800000) data |= 0xFF000000;

    *out = data;
    return 0;
}

static double read_hx711_weight(void) {
    double sum = 0.0;
    int32_t raw;
    int ok = 0;

    for (int i = 0; i < readings_per_cycle; i++) {
        if (read_hx711_raw(&raw) == 0) {
            sum += (double)raw;
            ok++;
        } else {
            syslog(LOG_ERR, "HX711 read failed in cycle iteration %d", i);
        }
        usleep(1000);
    }

    if (ok == 0) return 0.0;
    return (sum / ok) / scale;
}

static double tare_hx711(void) {
    double sum = 0.0;
    int32_t raw;
    int ok = 0;

    syslog(LOG_INFO, "Taring HX711...");
    for (int i = 0; i < tare_readings; i++) {
        if (read_hx711_raw(&raw) == 0) {
            sum += (double)raw;
            ok++;
        } else {
            syslog(LOG_ERR, "Tare read failed at iteration %d", i);
        }
        usleep(1000);
    }

    if (ok == 0) {
        syslog(LOG_ERR, "Tare failed: no valid readings");
        return 0.0;
    }
    return sum / ok;
}

static void activate_solenoid(void) {
    if (gpiod_line_set_value(solenoid_line, 1) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid HIGH: %s", strerror(errno));
        return;
    }
    syslog(LOG_INFO, "Solenoid activated for %d ms", solenoid_duration_ms);
    usleep(solenoid_duration_ms * 1000);
    if (gpiod_line_set_value(solenoid_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid LOW: %s", strerror(errno));
    }
    syslog(LOG_INFO, "Solenoid deactivated");
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "t:s:d:p:r:a:")) != -1) {
        switch (opt) {
            case 't': threshold = atof(optarg); break;
            case 's': scale = atof(optarg); break;
            case 'd': solenoid_duration_ms = atoi(optarg); break;
            case 'p': poll_interval_ms = atoi(optarg); break;
            case 'r': readings_per_cycle = atoi(optarg); break;
            case 'a': tare_readings = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration] [-p poll_ms] [-r readings] [-a tare_readings]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("hx711_solenoid", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting HX711 solenoid control. Threshold=%.1f g, Scale=%.1f, Duration=%d ms, Poll=%d ms, Readings=%d, Tare=%d",
           threshold, scale, solenoid_duration_ms, poll_interval_ms, readings_per_cycle, tare_readings);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    double tare_offset = tare_hx711();
    syslog(LOG_INFO, "Tare offset: %.2f", tare_offset);

    while (running) {
        double weight = read_hx711_weight();
        syslog(LOG_INFO, "Weight: %.2f g", weight);

        if (weight > threshold) {
            syslog(LOG_INFO, "Threshold exceeded. Activating solenoid.");
            activate_solenoid();
        }

        usleep(poll_interval_ms * 1000);
    }

    syslog(LOG_INFO, "Shutting down gracefully.");
    cleanup();
    return EXIT_SUCCESS;
}

