/*
 * relay_controller.c
 *
 * Raspberry Pi 4 Model B — MQTT relay controller
 *   - libmosquitto MQTT client (localhost:1883)
 *   - pigpio GPIO17 (BCM 17, physical pin 11) relay control
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c \
 *       -lmosquitto -lpigpio -lrt
 *
 * Run:
 *   sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST      "localhost"
#define MQTT_PORT      1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC     "home/lights/control"
#define GPIO_PIN       17
#define RECONNECT_DELAY 5
#define MAX_PAYLOAD    256

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_setup(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_OUTPUT) failed", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Relay OFF at startup (LOW) */
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        syslog(LOG_ERR, "gpioWrite(%d, 0) failed", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    syslog(LOG_INFO, "GPIO%d configured as output, relay OFF (LOW)");
    return 0;
}

static void gpio_set_relay(int state)
{
    if (gpioWrite(GPIO_PIN, state) != 0) {
        syslog(LOG_ERR, "gpioWrite(%d, %d) failed", GPIO_PIN, state);
    } else {
        syslog(LOG_INFO, "GPIO%d set to %d (relay %s)",
               GPIO_PIN, state, state ? "ON" : "OFF");
    }
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *m, void *ud, int rc)
{
    (void)ud;

    if (rc == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d (client %s)",
               MQTT_HOST, MQTT_PORT, MQTT_CLIENT_ID);
        if (mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to %s", MQTT_TOPIC);
        } else {
            syslog(LOG_INFO, "Subscribed to %s (QoS 0)", MQTT_TOPIC);
        }
    } else {
        syslog(LOG_ERR, "MQTT connect error: %s", mosquitto_connack_string(rc));
    }
}

static void on_disconnect(struct mosquitto *m, void *ud, int rc)
{
    (void)m;
    (void)ud;

    if (rc == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT disconnected cleanly");
    } else {
        syslog(LOG_ERR, "MQTT unexpected disconnect: %s", mosquitto_strerror(rc));
    }
}

static void on_message(struct mosquitto *m, void *ud,
                        const struct mosquitto_message *msg)
{
    (void)m;
    (void)ud;

    if (msg->payloadlen <= 0) {
        syslog(LOG_ERR, "Received empty message on %s", msg->topic);
        return;
    }

    char payload[MAX_PAYLOAD];
    int n = msg->payloadlen < (int)sizeof(payload) - 1
            ? msg->payloadlen
            : (int)sizeof(payload) - 1;

    memcpy(payload, msg->payload, n);
    payload[n] = '\0';

    /* Treat payload as a NUL-terminated string */
    if (strcmp(payload, "ON") == 0) {
        gpio_set_relay(1);
    } else if (strcmp(payload, "OFF") == 0) {
        gpio_set_relay(0);
    } else {
        syslog(LOG_ERR, "Invalid payload '%s' on %s", payload, msg->topic);
    }
}

/* ------------------------------------------------------------------ */
/* MQTT helpers                                                        */
/* ------------------------------------------------------------------ */
static int mqtt_connect(void)
{
    int rc = mosquitto_connect(g_mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect: %s", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

static int mqtt_reconnect(void)
{
    syslog(LOG_INFO, "Attempting MQTT reconnection in %d seconds...", RECONNECT_DELAY);
    sleep(RECONNECT_DELAY);

    if (mosquitto_reconnect(g_mosq) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_reconnect failed");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_setup() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed (out of memory)");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    if (mqtt_connect() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int rc = mosquitto_loop(g_mosq, 100, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop error: %s", mosquitto_strerror(rc));
            if (g_mosq) {
                mosquitto_destroy(g_mosq);
                g_mosq = NULL;
            }
            mosquitto_lib_cleanup();
            gpioTerminate();
            sleep(RECONNECT_DELAY);

            if (!g_running) {
                break;
            }

            if (mosquitto_lib_init() != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "mosquitto_lib_init failed");
                break;
            }
            g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
            if (!g_mosq) {
                syslog(LOG_ERR, "mosquitto_new failed (out of memory)");
                break;
            }
            if (mqtt_connect() != 0) {
                break;
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

