int main(void)
{
    int i;
    int rc;

    /* Initialize pigpio library */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", rc);
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range for each servo pin */
    for (i = 0; i < NUM_SERVOS; i++) {
        gpioSetMode(servo_pins[i], PI_OUTPUT);
        gpioSetPWMfrequency(servo_pins[i], PWM_FREQ);
        gpioSetPWMrange(servo_pins[i], PWM_RANGE);
    }

    /* Apply pulse widths to each servo */
    for (i = 0; i < NUM_SERVOS; i++) {
        gpioPWM(servo_pins[i], pulse_widths[i]);
    }

    /* Hold signals for 3 seconds so servos can reach positions */
    gpioDelay(HOLD_MS * 1000);

    /* Cleanly stop PWM on all pins */
    for (i = 0; i < NUM_SERVOS; i++) {
        gpioPWM(servo_pins[i], 0);
    }

