#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdatomic.h>
#include <stdbool.h>

/* Motor A */
#define MOTOR_A_PWM_PIN 17
#define MOTOR_A_DIR_PIN 18

/* Motor B */
#define MOTOR_B_PWM_PIN 22
#define MOTOR_B_DIR_PIN 23

/* Encoder A (quadrature) */
#define ENCODER_A_PIN_A 4
#define ENCODER_A_PIN_B 5

/* Encoder B (quadrature) */
#define ENCODER_B_PIN_A 6
#define ENCODER_B_PIN_B 12

#define TARGET_SPEED_RPM 50.0
#define KP 0.5
#define KI 0.05
#define PWM_FREQUENCY 10000
#define PWM_RANGE 255
#define CONTROL_PERIOD_US 100000
#define STALL_TIMEOUT_US 2000000

static volatile sig_atomic_t running = 1;
static atomic_int encoder_a_count = 0;
static atomic_int encoder_b_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    atomic_fetch_add(&encoder_a_count, 1);
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    atomic_fetch_add(&encoder_b_count, 1);
}

static int set_motor_direction(int dir_pin, int direction) {
    if (gpioWrite(dir_pin, direction) < 0) {
        fprintf(stderr, "Error: gpioWrite failed on direction pin %d\n", dir_pin);
        return -1;
    }
    return 0;
}

static int set_motor_pwm(int pwm_pin, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (gpioPWM(pwm_pin, duty_cycle) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pwm_pin);
        return -1;
    }
    return 0;
}

static double calculate_rpm(int ticks, double dt_sec) {
    if (dt_sec <= 0.0) return 0.0;
    return (double)ticks / (60.0 * dt_sec);
}

static int control_motor(int pwm_pin, int dir_pin, double target_rpm,
                         double *integral, double *prev_error, double dt_sec) {
    int ticks_a = atomic_load(&encoder_a_count);
    int ticks_b = atomic_load(&encoder_b_count);
    double rpm_a = calculate_rpm(ticks_a, dt_sec);
    double rpm_b = calculate_rpm(ticks_b, dt_sec);

    double error = target_rpm - rpm_a;
    *integral += error * dt_sec;
    if (*integral > 100.0) *integral = 100.0;
    if (*integral < -100.0) *integral = -100.0;

    double output = KP * error + KI * (*integral);
    int duty_cycle = (int)output;
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    if (set_motor_pwm(pwm_pin, duty_cycle) < 0) return -1;
    if (set_motor_direction(dir_pin, duty_cycle > 0 ? 1 : 0) < 0) return -1;

    printf("Motor A: RPM = %.2f, PWM = %d\n", rpm_a, duty_cycle);
    printf("Motor B: RPM = %.2f, PWM = %d\n", rpm_b, duty_cycle);

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_A_PWM_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ENCODER_A_PIN_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_A_PIN_B, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_PIN_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_PIN_B, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for encoder pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(ENCODER_A_PIN_A, RISING_EDGE, 0, encoder_a_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_A_PIN_B, RISING_EDGE, 0, encoder_a_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_B_PIN_A, RISING_EDGE, 0, encoder_b_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_B_PIN_B, RISING_EDGE, 0, encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double integral_a = 0.0, prev_error_a = 0.0;
    double integral_b = 0.0, prev_error_b = 0.0;
    uint32_t last_tick = gpioTick();
    bool stalled = false;

    while (running) {
        uint32_t now = gpioTick();
        double dt = (double)(now - last_tick) / 1000000.0;
        last_tick = now;

        int ticks_a = atomic_load(&encoder_a_count);
        int ticks_b = atomic_load(&encoder_b_count);

        if (dt > 0.0) {
            if (ticks_a == 0 && ticks_b == 0 && dt > STALL_TIMEOUT_US / 1000000.0) {
                if (!stalled) {
                    fprintf(stderr, "Warning: Encoder stall detected (0 ticks for %.2f s)\n", dt);
                    stalled = true;
                }
            } else {
                stalled = false;
            }
        }

        if (control_motor(MOTOR_A_PWM_PIN, MOTOR_A_DIR_PIN, TARGET_SPEED_RPM,
                          &integral_a, &prev_error_a, dt) < 0) {
            break;
        }
        if (control_motor(MOTOR_B_PWM_PIN, MOTOR_B_DIR_PIN, TARGET_SPEED_RPM,
                          &integral_b, &prev_error_b, dt) < 0) {
            break;
        }
    }

    set_motor_pwm(MOTOR_A_PWM_PIN, 0);
    set_motor_pwm(MOTOR_B_PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

