#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 17
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define POLL_INTERVAL_SEC 5
#define BH1750_MEASUREMENT_DELAY_MS 180
#define LOG_FILE "chicken_coop_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, int *lux_out) {
    char cmd = 0x21; /* One-Time High-Resolution Mode 2 */
    char buf[2];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        return -1;
    }
    gpioDelay(BH1750_MEASUREMENT_DELAY_MS * 1000);

    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }

    unsigned int raw = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (int)(raw / 1.2f);
    return 0;
}

static void log_event(int lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (log_file) {
        fprintf(log_file, "%s: Lux = %d, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
        fflush(log_file);
    }
    printf("%s: Lux = %d, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, BH1750_ADDR);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    int relay_state = 0;
    int consecutive_errors = 0;

    while (running) {
        int lux = 0;
        if (read_bh1750(i2c_handle, &lux) != 0) {
            consecutive_errors++;
            fprintf(stderr, "Warning: Failed to read BH1750 (attempt %d).\n", consecutive_errors);
            log_event(-1, relay_state);
            if (consecutive_errors >= 3) {
                fprintf(stderr, "Error: Sensor unresponsive after 3 failures. Turning off relay for safety.\n");
                gpioWrite(RELAY_GPIO, 0);
                relay_state = 0;
                log_event(-1, relay_state);
                consecutive_errors = 0;
            }
        } else {
            consecutive_errors = 0;
            if (lux < LUX_THRESHOLD_DUSK && !relay_state) {
                gpioWrite(RELAY_GPIO, 1);
                relay_state = 1;
                log_event(lux, relay_state);
            } else if (lux > LUX_THRESHOLD_DAWN && relay_state) {
                gpioWrite(RELAY_GPIO, 0);
                relay_state = 0;
                log_event(lux, relay_state);
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

