#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000   /* 50 ms in microseconds */
#define LOOP_DELAY_US 10000       /* 10 ms main-loop sleep */
#define POLL_INTERVAL_US 1000     /* 1 ms poll interval */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_relay_state(int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("[%s] Relay %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void)
{
    int relay_state = 0;
    int last_stable_touch = 0;
    int first_read = 1;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pin as input */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output and ensure it starts OFF */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO %d to LOW\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch-controlled relay started. Touch GPIO %d to toggle relay on GPIO %d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        int touch = gpioRead(TOUCH_SENSOR_PIN);

        if (touch < 0) {
            fprintf(stderr, "Warning: gpioRead failed on pin %d\n", TOUCH_SENSOR_PIN);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        /* Edge detection: rising edge (touch) triggers a toggle */
        if (touch == 1 && last_stable_touch == 0) {
            /* Debounce: wait and re-read to confirm */
            gpioDelay(DEBOUNCE_DELAY_US);
            int confirm = gpioRead(TOUCH_SENSOR_PIN);
            if (confirm == 1) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Error: gpioWrite failed on pin %d\n", RELAY_PIN);
                } else {
                    log_relay_state(relay_state);
                }
                /* Wait for touch release before allowing next toggle */
                while (running) {
                    int release = gpioRead(TOUCH_SENSOR_PIN);
                    if (release < 0) {
                        fprintf(stderr, "Warning: gpioRead failed on pin %d\n", TOUCH_SENSOR_PIN);
                        gpioDelay(LOOP_DELAY_US);
                        continue;
                    }
                    if (release == 0) {
                        break;
                    }
                    gpioDelay(LOOP_DELAY_US);
                }
            }
        }

        last_stable_touch = touch;
        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful shutdown: turn relay OFF and release pigpio */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off relay during shutdown\n");
    }
    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

