#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define FLOW_RATE_THRESHOLD 5.0
#define FLOW_RATE_HYSTERESIS 0.5
#define PULSES_PER_LITER 450.0
#define LOG_FILE "water_flow.log"
#define SAMPLE_INTERVAL_US 1000000
#define DEBOUNCE_US 1000000

static volatile int pulse_count = 0;
static volatile int solenoid_state = 1; /* 1 = open, 0 = closed */
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t running = 1;

static void log_message(const char *message) {
    if (log_file == NULL) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static double calculate_flow_rate(int pulses) {
    return ((double)pulses / PULSES_PER_LITER) * 60.0;
}

static void control_solenoid(double flow_rate) {
    if (flow_rate > FLOW_RATE_THRESHOLD && solenoid_state == 1) {
        if (gpioWrite(SOLENOID_GPIO, 0) != 0) {
            log_message("ERROR: Failed to close solenoid");
        } else {
            solenoid_state = 0;
            log_message("Solenoid closed (flow rate exceeded threshold)");
        }
    } else if (flow_rate < (FLOW_RATE_THRESHOLD - FLOW_RATE_HYSTERESIS) && solenoid_state == 0) {
        if (gpioWrite(SOLENOID_GPIO, 1) != 0) {
            log_message("ERROR: Failed to open solenoid");
        } else {
            solenoid_state = 1;
            log_message("Solenoid opened (flow rate below threshold)");
        }
    }
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void cleanup(void) {
    if (solenoid_state == 0) {
        gpioWrite(SOLENOID_GPIO, 1);
        solenoid_state = 1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to initialize solenoid state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_US, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function for flow sensor\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Water flow monitoring started");

    while (running) {
        int pulses;
        pthread_mutex_lock(&pulse_mutex);
        pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double flow_rate = calculate_flow_rate(pulses);
        char log_buf[128];
        snprintf(log_buf, sizeof(log_buf), "Flow rate: %.2f L/min", flow_rate);
        log_message(log_buf);

        control_solenoid(flow_rate);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    log_message("Water flow monitoring stopped");
    cleanup();
    return EXIT_SUCCESS;
}

