#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18

#define DEFAULT_CALIBRATION_FACTOR 1000.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_LOG_FILE "dispensing_log.json"

#define HX711_TIMEOUT 1000
#define HX711_SETTLE_TIME_US 1000000
#define SERVO_SETTLE_TIME_US 1000000
#define SERVO_PULSE_MIN 1000
#define SERVO_PULSE_MAX 2000

#define MAX_WEIGHT_GRAMS 1000.0
#define MIN_WEIGHT_GRAMS 0.0

typedef struct {
    double calibration_factor;
    char server_ip[64];
    int server_port;
    char log_file[64];
} Config;

static volatile sig_atomic_t running = 1;
static int server_socket = -1;
static int hx711_ready = 0;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static char server_ip[64] = DEFAULT_SERVER_IP;
static int server_port = DEFAULT_SERVER_PORT;
static char log_file[64] = DEFAULT_LOG_FILE;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s', using defaults.\n", filename);
        return 0;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=\n");
        char *value = strtok(NULL, "=\n");
        if (!key || !value) continue;
        if (strcmp(key, "calibration_factor") == 0) {
            calibration_factor = atof(value);
        } else if (strcmp(key, "server_ip") == 0) {
            strncpy(server_ip, value, sizeof(server_ip) - 1);
            server_ip[sizeof(server_ip) - 1] = '\0';
        } else if (strcmp(key, "server_port") == 0) {
            server_port = atoi(value);
        } else if (strcmp(key, "log_file") == 0) {
            strncpy(log_file, value, sizeof(log_file) - 1);
            log_file[sizeof(log_file) - 1] = '\0';
        }
    }
    fclose(fp);
    return 0;
}

static int init_hx711(void) {
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1000);
    return 0;
}

static long read_hx711(void) {
    if (!hx711_ready) {
        fprintf(stderr, "Error: HX711 not ready.\n");
        return -1;
    }
    int timeout = HX711_TIMEOUT;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1);
        if (--timeout <= 0) {
            fprintf(stderr, "Error: HX711 timeout waiting for data.\n");
            return -1;
        }
    }
    long value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        value = (value << 1) | (gpioRead(HX711_DATA_PIN) & 1);
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);
    if (value & 0x80000) {
        value |= 0xFF000000;
    }
    return value;
}

static double get_weight_grams(void) {
    long raw = read_hx711();
    if (raw == -1) return -1.0;
    return (double)raw / calibration_factor;
}

static int set_servo_pulse(int pulse_width) {
    if (pulse_width < SERVO_PULSE_MIN) pulse_width = SERVO_PULSE_MIN;
    if (pulse_width > SERVO_PULSE_MAX) pulse_width = SERVO_PULSE_MAX;
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width.\n");
        return -1;
    }
    return 0;
}

static int map_weight_to_pulse(double weight) {
    if (weight < MIN_WEIGHT_GRAMS) weight = MIN_WEIGHT_GRAMS;
    if (weight > MAX_WEIGHT_GRAMS) weight = MAX_WEIGHT_GRAMS;
    return (int)((weight / MAX_WEIGHT_GRAMS) * (SERVO_PULSE_MAX - SERVO_PULSE_MIN) + SERVO_PULSE_MIN);
}

static int log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    FILE *fp = fopen(log_file, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", log_file, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "{\"timestamp\":\"%s\",\"target_weight\":%.2f,\"actual_weight\":%.2f,\"error_message\":\"%s\"}\n",
            timestamp, target_weight, actual_weight, error_message ? error_message : "");
    fclose(fp);
    return 0;
}

static int handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        fprintf(stderr, "Error: recv failed: %s\n", strerror(errno));
        close(client_socket);
        return -1;
    }
    if (bytes_received == 0) {
        fprintf(stderr, "Error: Client disconnected.\n");
        close(client_socket);
        return -1;
    }
    buffer[bytes_received] = '\0';
    double target_weight = atof(buffer);
    if (target_weight < 0.0 || target_weight > MAX_WEIGHT_GRAMS) {
        fprintf(stderr, "Error: Invalid target weight: %.2f\n", target_weight);
        const char *err = "Invalid target weight";
        send(client_socket, err, strlen(err), 0);
        close(client_socket);
        return -1;
    }
    int pulse_width = map_weight_to_pulse(target_weight);
    if (set_servo_pulse(pulse_width) != 0) {
        const char *err = "Failed to set servo pulse";
        send(client_socket, err, strlen(err), 0);
        close(client_socket);
        return -1;
    }
    gpioDelay(SERVO_SETTLE_TIME_US);
    double actual_weight = get_weight_grams();
    if (actual_weight < 0.0) {
        fprintf(stderr, "Error: Failed to read weight from HX711.\n");
        const char *err = "Failed to read weight from HX711";
        send(client_socket, err, strlen(err), 0);
        set_servo_pulse(SERVO_PULSE_MIN);
        close(client_socket);
        return -1;
    }
    char response[128];
    snprintf(response, sizeof(response), "%.2f", actual_weight);
    send(client_socket, response, strlen(response), 0);
    log_dispensing_event(target_weight, actual_weight, NULL);
    set_servo_pulse(SERVO_PULSE_MIN);
    close(client_socket);
    return 0;
}

static int start_tcp_server(void) {
    struct sockaddr_in server_addr;
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        fprintf(stderr, "Error: Could not create socket: %s\n", strerror(errno));
        return -1;
    }
    int opt = 1;
    if (setsockopt(server_socket, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "Error: setsockopt failed: %s\n", strerror(errno));
        close(server_socket);
        return -1;
    }
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(server_ip);
    server_addr.sin_port = htons(server_port);
    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error: Could not bind socket: %s\n", strerror(errno));
        close(server_socket);
        return -1;
    }
    if (listen(server_socket, 3) < 0) {
        fprintf(stderr, "Error: Could not listen on socket: %s\n", strerror(errno));
        close(server_socket);
        return -1;
    }
    printf("Listening on %s:%d\n", server_ip, server_port);
    return 0;
}

int main(void) {
