}

static int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s', using defaults.\n", filename);
        return 0;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=\n");
        char *value = strtok(NULL, "=\n");
        if (!key || !value) continue;
        if (strcmp(key, "calibration_factor") == 0) {
            calibration_factor = atof(value);
        } else if (strcmp(key, "server_ip") == 0) {
            strncpy(server_ip, value, sizeof(server_ip) - 1);
            server_ip[sizeof(server_ip) - 1] = '\0';
        } else if (strcmp(key, "server_port") == 0) {
            server_port = atoi(value);
        } else if (strcmp(key, "log_file") == 0) {
            strncpy(log_file, value, sizeof(log_file) - 1);
            log_file[sizeof(log_file) - 1] = '\0';
        }
    }
    fclose(fp);
    return 0;
}

static int init_hx711(void) {
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1000);
    return 0;
}

static long read_hx711(void) {
    if (!hx711_ready) {
        fprintf(stderr, "Error: HX711 not ready.\n");
        return -1;
    }
    int timeout = HX711_TIMEOUT;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1);
        if (--timeout <= 0) {
            fprintf(stderr, "Error: HX711 timeout waiting for data.\n");
            return -1;
        }
    }
    long value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        value = (value << 1) | (gpioRead(HX711_DATA_PIN) & 1);
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);
