#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define LOG_FILE "motor_rpm.log"
#define SAMPLE_INTERVAL_SEC 5
#define DEBOUNCE_NS 2000000L  /* 2 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    if (install_signal_handlers() == -1)
        return EXIT_FAILURE;

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request line as input with internal pull-up (A3144 open-collector). */
    if (gpiod_line_request_input_flags(line, "hall-sensor",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    unsigned long pulse_count = 0;
    struct timespec last_event;
    if (clock_gettime(CLOCK_MONOTONIC, &last_event) == -1) {
        perror("clock_gettime");
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring motor RPM on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (program_running) {
        struct timespec now;
        if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
            perror("clock_gettime");
            break;
        }

        struct timespec deadline;
        deadline.tv_sec = now.tv_sec + SAMPLE_INTERVAL_SEC;
        deadline.tv_nsec = now.tv_nsec;

        /* Block up to SAMPLE_INTERVAL_SEC for a rising-edge event. */
        int ret = gpiod_line_event_wait(line, &deadline);
        if (ret < 0) {
            if (errno == EINTR)
                continue;
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) {
            /* Timeout: end of sampling window. */
            double rpm = (double)pulse_count / (double)SAMPLE_INTERVAL_SEC * 60.0;
            char ts[32];
            if (get_timestamp(ts, sizeof(ts)) == -1) {
                fprintf(stderr, "Failed to get timestamp; skipping log entry.\n");
            } else {
                fprintf(log_file, "%s,%.2f\n", ts, rpm);
                fflush(log_file);
            }
            printf("RPM: %.2f\n", rpm);
            pulse_count = 0;
            last_event = now;
            continue;
        }

        /* Event detected: read it to confirm it is a rising edge. */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("gpiod_line_event_read");
            continue;
        }
        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE)
            continue;

        /* Debounce: ignore events within DEBOUNCE_NS of the last accepted one. */
        long delta_ns = (now.tv_sec - last_event.tv_sec) * 1000000000L
                      + (now.tv_nsec - last_event.tv_nsec);
        if (delta_ns < DEBOUNCE_NS)
            continue;
        last_event = now;

        pulse_count++;
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

