#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define POLL_DELAY_US    50000   /* 50 ms */
#define FAILSAFE_TIMEOUT 10      /* seconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v == PI_BAD_GPIO) {
        fprintf(stderr, "Error: gpioRead(%u) returned PI_BAD_GPIO\n", pin);
        return -1;
    }
    return v;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(TOUCH_SENSOR_PIN, PI_INPUT) != 0 ||
        safe_set_mode(RELAY_PIN, PI_OUTPUT)        != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_write(RELAY_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install signal handlers\n");
    }

    int relay_state = 0;
    int last_touch  = 0;
    int failsafe_armed = 1;
    int failsafe_start = 0;

    while (g_running) {
        int touch = safe_read(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (touch == 1 && last_touch == 0) {
            /* Rising edge: toggle relay */
            relay_state = !relay_state;
            if (safe_write(RELAY_PIN, relay_state) != 0) {
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            fflush(stdout);
            failsafe_armed = 1;
            failsafe_start = 0;
        }

        if (touch == 1) {
            if (failsafe_armed) {
                failsafe_start = (failsafe_start == 0) ? 0 : failsafe_start + 1;
                if (failsafe_start >= FAILSAFE_TIMEOUT) {
                    printf("Failsafe: touch held > %d s, forcing relay OFF\n", FAILSAFE_TIMEOUT);
                    fflush(stdout);
                    if (safe_write(RELAY_PIN, 0) != 0) {
                        gpioTerminate();
                        return EXIT_FAILURE;
                    }
                    relay_state = 0;
                    failsafe_armed = 0;
                }
            }
        } else {
            failsafe_armed = 1;
            failsafe_start = 0;
        }

        last_touch = touch;
        usleep(POLL_DELAY_US);
    }

    /* Clean shutdown */
    if (safe_write(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off relay during shutdown\n");
    }
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

