#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_1_GPIO 17
#define LOCK_2_GPIO 27
#define BUTTON_GPIO 22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define DEBOUNCE_US 50000
#define LOCK_HOLD_US 5000000
#define POLL_DELAY_US 100000

static const unsigned char VALID_TAG[10] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", ts, event);
    fflush(log_file);
}

static int read_rfid_tag(unsigned char *tag_data, size_t len) {
    unsigned char tx[10] = {0x00};
    unsigned char rx[10] = {0x00};
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 10);
    if (ret != 10) {
        log_event("SPI read failed");
        return -1;
    }
    if (memcmp(rx, VALID_TAG, 10) == 0) {
        memcpy(tag_data, rx, len);
        return 0;
    }
    return 1;
}

static int authenticate_rfid(unsigned char *tag_data) {
    if (read_rfid_tag(tag_data, 10) != 0) return -1;
    return memcmp(tag_data, VALID_TAG, 10) == 0 ? 0 : 1;
}

static int button_pressed(void) {
    if (gpioRead(BUTTON_GPIO) == 0) {
        gpioDelay(DEBOUNCE_US);
        return gpioRead(BUTTON_GPIO) == 0;
    }
    return 0;
}

static void control_locks(int unlock) {
    if (unlock) {
        gpioWrite(LOCK_1_GPIO, 0);
        gpioWrite(LOCK_2_GPIO, 0);
        log_event("Locks disengaged");
    } else {
        gpioWrite(LOCK_1_GPIO, 1);
        gpioWrite(LOCK_2_GPIO, 1);
        log_event("Locks re-engaged");
    }
}

static void cleanup(void) {
    control_locks(0);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen("/var/log/door_access.log", "a");
    if (!log_file) {
        perror("fopen log");
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        log_event("SPI open failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LOCK_1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK_2_GPIO, PI_OUTPUT);
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);
    control_locks(1);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    unsigned char tag_data[10];
    int button_state = 1;

    while (!terminate) {
        int ret = authenticate_rfid(tag_data);
        if (ret == 0) {
            log_event("RFID authentication successful");
            if (button_pressed()) {
                log_event("Button pressed");
                control_locks(1);
                gpioDelay(LOCK_HOLD_US);
                control_locks(0);
                gpioDelay(LOCK_HOLD_US);
                control_locks(1);
            } else {
                log_event("Button not pressed after RFID");
            }
        } else if (ret == -1) {
            log_event("RFID read failure");
        } else {
            log_event("Invalid RFID tag");
        }

        if (button_pressed() && button_state) {
            log_event("Button press without valid tag");
        }
        button_state = button_pressed();

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

