#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define KP 1.0
#define KI 0.1
#define KD 0.01
#define SAMPLE_TIME_MS 100
#define PWM_FREQ_HZ 100
#define PWM_PERIOD_US (1000000 / PWM_FREQ_HZ)
#define ENCODER_PPR 600
#define LOG_FILE "motor_log.csv"

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_lines[6] = {NULL};
static struct gpiod_line *encoder_a_lines[2] = {NULL};
static struct gpiod_line *encoder_b_lines[2] = {NULL};

static pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;
static int encoder_counts[2] = {0, 0};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    for (int i = 0; i < 6; i++) {
        if (motor_lines[i]) {
            gpiod_line_set_value(motor_lines[i], 0);
            gpiod_line_release(motor_lines[i]);
            motor_lines[i] = NULL;
        }
    }
    for (int i = 0; i < 2; i++) {
        if (encoder_a_lines[i]) {
            gpiod_line_release(encoder_a_lines[i]);
            encoder_a_lines[i] = NULL;
        }
        if (encoder_b_lines[i]) {
            gpiod_line_release(encoder_b_lines[i]);
            encoder_b_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    const unsigned int motor_pins[6] = {MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2, MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4};
    const unsigned int encoder_a_pins[2] = {ENCODER1_A, ENCODER2_A};
    const unsigned int encoder_b_pins[2] = {ENCODER1_B, ENCODER2_B};

    for (int i = 0; i < 6; i++) {
        motor_lines[i] = gpiod_chip_get_line(chip, motor_pins[i]);
        if (!motor_lines[i]) {
            fprintf(stderr, "Failed to get motor line %d: %s\n", motor_pins[i], strerror(errno));
            return -1;
        }
        if (gpiod_line_request_output(motor_lines[i], "motor-pid", 0) < 0) {
            fprintf(stderr, "Failed to request motor line %d as output: %s\n", motor_pins[i], strerror(errno));
            return -1;
        }
    }

    for (int i = 0; i < 2; i++) {
        encoder_a_lines[i] = gpiod_chip_get_line(chip, encoder_a_pins[i]);
        if (!encoder_a_lines[i]) {
            fprintf(stderr, "Failed to get encoder A line %d: %s\n", encoder_a_pins[i], strerror(errno));
            return -1;
        }
        encoder_b_lines[i] = gpiod_chip_get_line(chip, encoder_b_pins[i]);
        if (!encoder_b_lines[i]) {
            fprintf(stderr, "Failed to get encoder B line %d: %s\n", encoder_b_pins[i], strerror(errno));
            return -1;
        }
        if (gpiod_line_request_both_edges_events(encoder_a_lines[i], "encoder") < 0) {
            fprintf(stderr, "Failed to request edge events on encoder A line %d: %s\n", encoder_a_pins[i], strerror(errno));
            return -1;
        }
    }
    return 0;
}

static void *encoder_thread(void *arg) {
    int motor_id = *(int *)arg;
    struct gpiod_line *a_line = encoder_a_lines[motor_id];
    struct gpiod_line *b_line = encoder_b_lines[motor_id];

    while (running) {
        struct timespec ts = {0, 100000000}; // 100 ms timeout
        int ret = gpiod_line_event_wait(a_line, &ts);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error waiting for encoder event: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) continue;

        struct gpiod_line_event event;
        if (gpiod_line_event_read(a_line, &event) < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error reading encoder event: %s\n", strerror(errno));
            break;
        }

        int b_val = gpiod_line_get_value(b_line);
        if (b_val < 0) {
            fprintf(stderr, "Error reading encoder B value: %s\n", strerror(errno));
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            if (b_val == 1) {
                pthread_mutex_lock(&encoder_mutex);
                encoder_counts[motor_id]++;
                pthread_mutex_unlock(&encoder_mutex);
            } else {
                pthread_mutex_lock(&encoder_mutex);
                encoder_counts[motor_id]--;
                pthread_mutex_unlock(&encoder_mutex);
            }
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            if (b_val == 0) {
                pthread_mutex_lock(&encoder_mutex);
                encoder_counts[motor_id]++;
                pthread_mutex_unlock(&encoder_mutex);
            } else {
                pthread_mutex_lock(&encoder_mutex);
                encoder_counts[motor_id]--;
                pthread_mutex_unlock(&encoder_mutex);
            }
        }
    }
    return NULL;
}

static double calculate_rpm(int *counts, int motor_id) {
    static double prev_counts[2] = {0.0, 0.0};
    static struct timespec prev_time[2] = {{0, 0}, {0, 0}};

    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    double dt = (now.tv_sec - prev_time[motor_id].tv_sec) +
                (now.tv_nsec - prev_time[motor_id].tv_nsec) / 1e9;
    if (dt <= 0.0) dt = 0.001;

    double delta_counts = (double)*counts - prev_counts[motor_id];
    double rpm = (delta_counts / (double)ENCODER_PPR) / dt * 60.0;

    prev_counts[motor_id] = (double)*counts;
    prev_time[motor_id] = now;

    return rpm;
}

static double pid_control(double target_rpm, double current_rpm, double *integral, double *prev_error) {
    double error = target_rpm - current_rpm;
    *integral += error * SAMPLE_TIME_MS / 1000.0;
    double derivative = (error - *prev_error) / (SAMPLE_TIME_MS / 1000.0);
    double output = KP * error + KI * (*integral) + KD * derivative;
    *prev_error = error;
    return output;
}

static void set_motor_speed(int motor_id, double speed) {
    if (speed < -100.0) speed = -100.0;
    if (speed > 100.0) speed = 100.0;

    struct gpiod_line *ena = motor_id == 0 ? motor_lines[0] : motor_lines[3];
    struct gpiod_line *in1 = motor_id == 0 ? motor_lines[1] : motor_lines[4];
    struct gpiod_line *in2 = motor_id == 0 ? motor_lines[2] : motor_lines[5];

    int direction = (speed > 0) ? 1 : 0;
    int magnitude = (speed > 0) ? (int)fabs(speed) : 0;

    if (gpiod_line_set_value(ena, 1) < 0) {
        fprintf(stderr, "Failed to set ENA/ENB: %s\n", strerror(errno));
        return;
    }

    if (gpiod_line_set_value(in1, direction) < 0) {
        fprintf(stderr, "Failed to set IN1/IN3: %s\n", strerror(errno));
        return;
    }
    if (gpiod_line_set_value(in2, !direction) < 0) {
        fprintf(stderr, "Failed to set IN2/IN4: %s\n", strerror(errno));
        return;
    }

    int on_time_us = (int)((magnitude / 100.0) * PWM_PERIOD_US);
    int off_time_us = PWM_PERIOD_US - on_time_us;

    if (on_time_us > 0) {
        if (gpiod_line_set_value(ena, 1) < 0) return;
        if (gpiod_line_set_value(in1, direction) < 0) return;
        if (gpiod_line_set_value(in2, !direction) < 0) return;
        usleep(on_time_us);
    }
    if (off_time_us > 0) {
        if (gpiod_line_set_value(ena, 0) < 0) return;
        usleep(off_time_us);
    }
}

static void log_data(double rpm1, double rpm2, double p1, double i1, double d1, double p2, double i2, double d2, double out1, double out2) {
    if (!log_file) return;
    fprintf(log_file, "%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            rpm1, rpm2, p1, i1, d1, p2, i2, d2, out1, out2);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    fprintf(log_file, "Motor1_RPM,Motor2_RPM,P1,I1,D1,P2,I2,D2,Output1,Output2\n");
    fflush(log_file);

    pthread_t encoder_threads[2];
    int motor_ids[2] = {0, 1};

    for (int i = 0; i < 2; i++) {
        if (pthread_create(&encoder_threads[i], NULL, encoder_thread, &motor_ids[i]) != 0) {
            fprintf(stderr, "Failed to create encoder thread %d: %s\n", i, strerror(errno));
            cleanup();
            return 1;
        }
    }

    double integral1 = 0.0, prev_error1 = 0.0;
    double integral2 = 0.0, prev_error2 = 0.0;
    double target_rpm = 60.0;

    while (running) {
        int counts[2];
        pthread_mutex_lock(&encoder_mutex);
        counts[0] = encoder_counts[0];
        counts[1] = encoder_counts[1];
        pthread_mutex_unlock(&encoder_mutex);

        double rpm1 = calculate_rpm(&counts[0], 0);
        double rpm2 = calculate_rpm(&counts[1], 1);

        double out1 = pid_control(target_rpm, rpm1, &integral1, &prev_error1);
        double out2 = pid_control(target_rpm, rpm2, &integral2, &prev_error2);

        set_motor_speed(0, out1);
        set_motor_speed(1, out2);

        log_data(rpm1, rpm2, KP * (target_rpm - rpm1), integral1, KD * (target_rpm - rpm1 - prev_error1), KP * (target_rpm - rpm2), integral2, KD * (target_rpm - rpm2 - prev_error2), out1, out2);

        usleep(SAMPLE_TIME_MS * 1000);
    }

    for (int i = 0; i < 2; i++) {
        pthread_join(encoder_threads[i], NULL);
    }
    cleanup();
    return 0;
}

