    int rc = i2cReadWordData(handle, MPR121_TOUCHSTATUS_L);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", MPR121_TOUCHSTATUS_L, strerror(errno));
        return -1;
    }
    *status = (uint16_t)rc;
    return 0;
}

