    FILE *fp = fopen("relay_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Relay %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            state ? "ACTIVATED" : "DEACTIVATED");
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n", I2C_BUS, MPR121_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor may be absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    int relay_state = 0;
    uint16_t touch_status = 0;

    while (running) {
        if (read_touch_status(i2c_handle, &touch_status) == 0) {
            if (touch_status != 0) {
                if (relay_state == 0) {
                    gpioWrite(RELAY_GPIO, 1);
                    relay_state = 1;
                    log_relay_state(1);
                }
            } else {
                if (relay_state == 1) {
                    gpioWrite(RELAY_GPIO, 0);
                    relay_state = 0;
                    log_relay_state(0);
                }
            }
        } else {
            fprintf(stderr, "Error reading touch status, retrying...\n");
        }
        gpioDelay(50000);
    }

    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

