#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define VALVE1_DURATION_MS 500
#define VALVE2_DURATION_MS 1000
#define PAUSE_BETWEEN_VALVES_MS 5000
#define PAUSE_BETWEEN_CYCLES_MS 10000
#define LOG_FILE "valve_log.txt"
#define GPIO_CHIP_NAME "gpiochip4"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", tstruct);
    fprintf(log_file, "%s: %s\n", buf, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (valve1_line) {
        gpiod_line_set_value(valve1_line, 0);
        gpiod_line_release(valve1_line);
        valve1_line = NULL;
    }
    if (valve2_line) {
        gpiod_line_set_value(valve2_line, 0);
        gpiod_line_release(valve2_line);
        valve2_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!valve1_line) {
        perror("Failed to get GPIO line for Valve 1");
        return -1;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!valve2_line) {
        perror("Failed to get GPIO line for Valve 2");
        return -1;
    }

    if (gpiod_line_request_output(valve1_line, "valve1", 0) < 0) {
        perror("Failed to request Valve 1 line as output");
        return -1;
    }

    if (gpiod_line_request_output(valve2_line, "valve2", 0) < 0) {
        perror("Failed to request Valve 2 line as output");
        return -1;
    }

    return 0;
}

static void activate_valve(struct gpiod_line *line, int duration_ms, const char *valve_name) {
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to set valve GPIO HIGH");
        return;
    }
    log_event(valve_name);
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to set valve GPIO LOW");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    if (init_gpio() < 0) {
        log_event("GPIO initialization failed");
        cleanup();
        return 1;
    }

    log_event("Program started");

    while (program_running) {
        activate_valve(valve1_line, VALVE1_DURATION_MS, "Valve 1 activated");
        if (!program_running) break;
        usleep(PAUSE_BETWEEN_VALVES_MS * 1000);
        if (!program_running) break;
        activate_valve(valve2_line, VALVE2_DURATION_MS, "Valve 2 activated");
        if (!program_running) break;
        usleep(PAUSE_BETWEEN_CYCLES_MS * 1000);
    }

    log_event("Program stopped");
    cleanup();
    return 0;
}

