#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x20
#define MPR121_TOUCHTH_0 0x10
#define MPR121_RELEASETH_0 0x11
#define MPR121_FILTER_CONFIG 0x20
#define MPR121_ELECTRODE_CURRENT 0x01

static int i2c_handle = -1;
static volatile int keep_running = 1;

void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int mpr121_init(int handle) {
    // Stop mode
    if (i2cWriteByteData(handle, MPR121_ELECTRODE_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to stop mode\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    // Set touch and release thresholds for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(handle, MPR121_TOUCHTH_0 + 2 * i, 0x10) < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(handle, MPR121_RELEASETH_0 + 2 * i, 0x0A) < 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Set filter/charge time (0x20 = 0b00100000)
    if (i2cWriteByteData(handle, MPR121_FILTER_CONFIG, 0x20) < 0) {
