#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_GPIO 17
#define RELAY_GPIO 18
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_US 50000
#define LOG_FILE "door_events.log"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event_type, int gpio_pin) {
    if (!log_file) return;
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char time_buf[32];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000;
    fprintf(log_file, "%s.%03ld: %s - GPIO %d\n", time_buf, ms, event_type, gpio_pin);
    fflush(log_file);
}

static void unlock_door(void) {
    if (gpioWrite(RELAY_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to set relay GPIO %d high\n", RELAY_GPIO);
        return;
    }
    gpioDelay(UNLOCK_DURATION_MS * 1000);
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to set relay GPIO %d low\n", RELAY_GPIO);
    }
    log_event("Door Unlocked", RELAY_GPIO);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set PIR GPIO %d as input\n", PIR_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on PIR GPIO %d\n", PIR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize relay GPIO %d low\n", RELAY_GPIO);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }

    printf("Door unlock system started. PIR=GPIO%d, Relay=GPIO%d. Press Ctrl+C to exit.\n", PIR_GPIO, RELAY_GPIO);

    uint32_t last_motion_tick = 0;
    int last_pir_state = 0;

    while (running) {
        int pir_state = gpioRead(PIR_GPIO);
        if (pir_state < 0) {
            fprintf(stderr, "Error: failed to read PIR GPIO %d\n", PIR_GPIO);
            break;
        }

        if (pir_state == 1 && last_pir_state == 0) {
            uint32_t now_tick = gpioTick();
            if (now_tick - last_motion_tick > RATE_LIMIT_MS * 1000) {
                log_event("Motion Detected", PIR_GPIO);
                unlock_door();
                last_motion_tick = now_tick;
            } else {
                log_event("Rate Limited", PIR_GPIO);
            }
        }
        last_pir_state = pir_state;

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

