#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define NUM_STEPS 5
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200
#define PWM_RANGE 255

volatile sig_atomic_t shutdown_flag = 0;

void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

typedef struct {
    int motor1_duty;
    int motor2_duty;
    int duration_ms;
} Step;

Step *generate_pattern(int num_steps) {
    Step *pattern = (Step *)malloc(num_steps * sizeof(Step));
    if (pattern == NULL) {
        fprintf(stderr, "Error: Memory allocation failed for pattern.\n");
        return NULL;
    }

    for (int i = 0; i < num_steps; i++) {
        pattern[i].motor1_duty = rand() % (PWM_RANGE + 1);
        pattern[i].motor2_duty = rand() % (PWM_RANGE + 1);
        pattern[i].duration_ms = MIN_DURATION_MS + (rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1));
    }
    return pattern;
}

void play_pattern(Step *pattern, int num_steps) {
    for (int i = 0; i < num_steps && !shutdown_flag; i++) {
        if (gpioPWM(MOTOR1_PIN, pattern[i].motor1_duty) < 0) {
            fprintf(stderr, "Error: Failed to set PWM on GPIO %d.\n", MOTOR1_PIN);
            return;
        }
        if (gpioPWM(MOTOR2_PIN, pattern[i].motor2_duty) < 0) {
            fprintf(stderr, "Error: Failed to set PWM on GPIO %d.\n", MOTOR2_PIN);
            return;
        }
        gpioDelay(pattern[i].duration_ms * 1000);
    }
}

void stop_motors(void) {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", MOTOR1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", MOTOR2_PIN);
        gpioTerminate();
        return 1;
    }

    srand(time(NULL));
    signal(SIGINT, signal_handler);

    while (!shutdown_flag) {
        int num_steps = NUM_STEPS + (rand() % 6);
        Step *pattern = generate_pattern(num_steps);
        if (pattern != NULL) {
            play_pattern(pattern, num_steps);
            free(pattern);
        }
    }

    stop_motors();
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return 0;
}

