#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define WEIGHT_THRESHOLD 10.0
#define NUM_CALIBRATION_READINGS 100
#define HX711_TIMEOUT_US 500000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin) {
    int count = 0;
    int timeout = 0;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);
    gpioWrite(clock_pin, 0);

    while (gpioRead(data_pin) == 1) {
        gpioDelay(1);
        if (++timeout > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout on data pin %d\n", data_pin);
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        count = count << 1;
        if (gpioRead(data_pin) == 1) {
            count++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);

    if (count & 0x800000) {
        count |= 0xFF000000;
    }

    return count;
}

static double calculate_weight(int raw_value, double scale_factor, double offset) {
    return ((double)raw_value - offset) / scale_factor;
}

static int log_weight(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fclose(fp);
    return 0;
}

static int load_calibration(double *scale_factor, double *offset) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Calibration file not found, using defaults\n");
        *scale_factor = 1.0;
        *offset = 0.0;
        return -1;
    }
    if (fscanf(fp, "%lf %lf", scale_factor, offset) != 2) {
        fprintf(stderr, "Invalid calibration file, using defaults\n");
        *scale_factor = 1.0;
        *offset = 0.0;
        fclose(fp);
        return -1;
    }
    fclose(fp);
    printf("Calibration loaded: scale=%.2f, offset=%.2f\n", *scale_factor, *offset);
    return 0;
}

static int save_calibration(double scale_factor, double offset) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) {
        perror("fopen calibration");
        return -1;
    }
    fprintf(fp, "%.2f %.2f\n", scale_factor, offset);
    fclose(fp);
    return 0;
}

static int calibrate_hx711(int data_pin, int clock_pin, double *offset) {
    long sum = 0;
    int valid = 0;
    printf("Calibrating HX711 (place known weight on sensor)\n");
    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        int raw = read_hx711(data_pin, clock_pin);
        if (raw < 0) {
            fprintf(stderr, "Calibration read failed at iteration %d\n", i);
            continue;
        }
        sum += raw;
        valid++;
        gpioDelay(10000);
    }
    if (valid == 0) {
        fprintf(stderr, "Calibration failed: no valid readings\n");
        return -1;
    }
    *offset = (double)sum / valid;
    printf("Calibration offset: %.2f\n", *offset);
    return 0;
}

int main(void) {
    double scale_factor = 1.0;
    double offset = 0.0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (load_calibration(&scale_factor, &offset) != 0) {
        if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &offset) != 0) {
            fprintf(stderr, "Calibration failed, using defaults\n");
        } else {
            if (save_calibration(scale_factor, offset) != 0) {
                fprintf(stderr, "Warning: could not save calibration\n");
            }
        }
    }

    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0);

    printf("Starting weight monitoring loop (Ctrl+C to exit)\n");

    while (running) {
        int raw = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw < 0) {
            fprintf(stderr, "HX711 read error, skipping iteration\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double weight = calculate_weight(raw, scale_factor, offset);

        if (weight > WEIGHT_THRESHOLD) {
            gpioWrite(SOLENOID_PIN, 1);
            printf("Weight %.2f kg exceeds threshold %.2f kg, lock engaged\n", weight, WEIGHT_THRESHOLD);
        } else {
            gpioWrite(SOLENOID_PIN, 0);
