#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

#define DEBOUNCE_READINGS 5
#define DEBOUNCE_INTERVAL_MS 50
#define MOTOR_RUN_TIME_SEC 5
#define CHECK_INTERVAL_SEC 60
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define PWM_DUTY 150

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int v = gpioRead(RAIN_SENSOR_PIN);
        if (v == 0) low_count++;
        gpioDelay(DEBOUNCE_INTERVAL_MS * 1000);
    }
    return (low_count >= 3) ? 1 : 0;
}

static void close_window(void) {
    syslog(LOG_INFO, "Closing window...");
    gpioWrite(MOTOR_IN1_PIN, 1);
    gpioWrite(MOTOR_IN2_PIN, 0);
    if (gpioPWM(MOTOR_PWM_PIN, PWM_DUTY) < 0) {
        syslog(LOG_ERR, "Failed to start PWM on GPIO%d", MOTOR_PWM_PIN);
    }
    gpioDelay(MOTOR_RUN_TIME_SEC * 1000000);
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    if (gpioPWM(MOTOR_PWM_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to stop PWM on GPIO%d", MOTOR_PWM_PIN);
    }
    syslog(LOG_INFO, "Window closed.");
}

static void log_event(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "[%s] %s", ts, msg);
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMrange(MOTOR_PWM_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to configure PWM on GPIO%d", MOTOR_PWM_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    log_event("Window control service started.");

    while (running) {
        int rain = read_rain_sensor();
        if (rain) {
            log_event("Rain detected!");
            close_window();
        } else {
            log_event("No rain detected.");
        }

        for (int i = 0; i < CHECK_INTERVAL_SEC && running; i++) {
            gpioDelay(1000000);
        }
    }

    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
    log_event("Window control service stopped.");
    closelog();
    return EXIT_SUCCESS;
}

