#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define HX711_DT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100.0
#define SOLENOID_DURATION_MS 5000
#define HX711_TIMEOUT_US 1000000
#define HX711_SETTLE_US 1000
#define SAMPLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711_raw(int dt_pin, int sck_pin) {
    int count = 0;
    int i;

    if (gpioSetMode(dt_pin, PI_INPUT) < 0) return -1;
    if (gpioSetMode(sck_pin, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(sck_pin, 0) < 0) return -1;

    for (i = 0; i < 24; i++) {
        if (gpioWrite(sck_pin, 1) < 0) return -1;
        gpioDelay(1);
        if (gpioWrite(sck_pin, 0) < 0) return -1;
        gpioDelay(1);

        int bit = gpioRead(dt_pin);
        if (bit < 0) return -1;
        count = (count << 1) | bit;
    }

    if (gpioWrite(sck_pin, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(sck_pin, 0) < 0) return -1;
    gpioDelay(1);

    if (count & 0x800000) {
        count = count | 0xFF000000;
    }

    return count;
}

static double read_hx711_weight(int dt_pin, int sck_pin) {
    int raw;
    int timeout = 0;

    while ((raw = read_hx711_raw(dt_pin, sck_pin)) == 0) {
        gpioDelay(1000);
        timeout++;
        if (timeout > HX711_TIMEOUT_US / 1000) {
            fprintf(stderr, "Error: HX711 data line stuck low or timeout.\n");
            return -1.0;
        }
    }

    if (raw < 0) {
        fprintf(stderr, "Error: HX711 read failed.\n");
        return -1.0;
    }

    return (double)raw / 1000.0;
}

static int control_solenoid(int pin, int duration_ms) {
    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set solenoid pin mode.\n");
        return -1;
    }
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Error: Failed to activate solenoid.\n");
        return -1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Error: Failed to deactivate solenoid.\n");
        return -1;
    }
    return 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen("stock_events.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open stock_events.txt: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set solenoid pin mode.\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(SOLENOID_PIN, 0);

    printf("Ingredient stock monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        double weight = read_hx711_weight(HX711_DT_PIN, HX711_SCK_PIN);

        if (weight < 0) {
            fprintf(stderr, "Error: Failed to read weight.\n");
        } else {
            printf("Weight: %.2f g\n", weight);

            if (weight < WEIGHT_THRESHOLD) {
                printf("Weight below threshold! Activating solenoid lock.\n");
                if (control_solenoid(SOLENOID_PIN, SOLENOID_DURATION_MS) == 0) {
                    log_event("Solenoid lock activated");
                } else {
                    fprintf(stderr, "Error: Failed to control solenoid.\n");
                }
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Ingredient stock monitoring stopped.\n");
    return 0;
}

