#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define WEIGHT_THRESHOLD 5.0
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define HX711_TIMEOUT_US 100000
#define CLOCK_HALF_PERIOD_US 1

static volatile sig_atomic_t running = 1;
static double calibration_factor = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin) {
    int count = 0;
    int timeout = 0;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);
    gpioWrite(clock_pin, 0);

    while (gpioRead(data_pin) == 1) {
        gpioDelay(CLOCK_HALF_PERIOD_US);
        if (++timeout > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout: data line stuck high\n");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(CLOCK_HALF_PERIOD_US);
        count = count << 1;
        if (gpioRead(data_pin) == 1) {
            count++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(CLOCK_HALF_PERIOD_US);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(CLOCK_HALF_PERIOD_US);
    gpioWrite(clock_pin, 0);
    gpioDelay(CLOCK_HALF_PERIOD_US);

    if (count & 0x800000) {
        count |= 0xFF000000;
    }

    return count;
}

static double read_weight(int data_pin, int clock_pin) {
    int raw = read_hx711(data_pin, clock_pin);
    if (raw < 0) {
        return -1.0;
    }
    return (double)raw / calibration_factor;
}

static void calibrate_hx711(int data_pin, int clock_pin) {
    double known_weight;
    int raw_value;

    printf("Place a known weight on the load cell and press Enter.\n");
    while (getchar() != '\n') {
        /* drain */
    }

    printf("Enter the known weight in kilograms: ");
    if (scanf("%lf", &known_weight) != 1 || known_weight <= 0.0) {
        fprintf(stderr, "Invalid weight input. Calibration aborted.\n");
        return;
    }

    raw_value = read_hx711(data_pin, clock_pin);
    if (raw_value < 0) {
        fprintf(stderr, "HX711 read failed during calibration.\n");
        return;
    }

    calibration_factor = (double)raw_value / known_weight;
    printf("Calibration factor: %.6f\n", calibration_factor);

    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        perror("Error opening calibration file");
        return;
    }
    fprintf(fp, "%.6f\n", calibration_factor);
    fclose(fp);
}

static void log_security_event(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fclose(fp);
}

static void control_solenoid(int pin, int duration_seconds) {
    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 1);
    gpioDelay(duration_seconds * 1000000);
    gpioWrite(pin, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp != NULL) {
        if (fscanf(fp, "%lf", &calibration_factor) != 1) {
            fprintf(stderr, "Error reading calibration file. Using default factor.\n");
            calibration_factor = 1.0;
        }
        fclose(fp);
    } else {
        printf("No calibration file found. Starting calibration.\n");
        calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        fp = fopen(CALIBRATION_FILE, "r");
        if (fp == NULL) {
            perror("Error opening calibration file after calibration");
            gpioTerminate();
            return 1;
        }
        if (fscanf(fp, "%lf", &calibration_factor) != 1) {
            fprintf(stderr, "Error reading calibration file. Using default factor.\n");
            calibration_factor = 1.0;
        }
        fclose(fp);
    }

    printf("Weight-based security system started. Press Ctrl+C to exit.\n");

    while (running) {
        double weight = read_weight(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (weight < 0) {
            fprintf(stderr, "Error reading weight. Retrying...\n");
            gpioDelay(1000000);
            continue;
        }

        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded! Logging event...\n");
            log_security_event(weight);
            control_solenoid(SOLENOID_PIN, 5);
        }

        gpioDelay(100000);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Exiting gracefully.\n");
    return 0;
}

