#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define PIR_PIN 17
#define BUZZER_PIN 18
#define BUZZER_DURATION_MS 2000
#define LOG_FILE "motion_log.txt"
#define CHIP_NAME "gpiochip4"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_line *buzzer_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int log_motion(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Error: localtime failed\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    int ret;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        perror("gpiod_chip_get_line (PIR)");
        cleanup();
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line (buzzer)");
        cleanup();
