#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define CONFIG_FILE "watering.conf"
#define GPIO_CHIP_NAME "gpiochip0"
#define VALVE_GPIO_LINE 18
#define MAX_DURATION 3600
#define MIN_DURATION 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_duration(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        if (feof(fp)) {
            fprintf(stderr, "Error: config file '%s' is empty.\n", filename);
        } else {
            fprintf(stderr, "Error reading config file '%s': %s\n", filename, strerror(errno));
        }
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *start = line;
    while (*start == ' ' || *start == '\t') start++;
    if (*start == '\0') {
        fprintf(stderr, "Error: config file '%s' has no valid key.\n", filename);
        return -1;
    }

    if (strncmp(start, "duration=", 9) != 0) {
        fprintf(stderr, "Error: config file '%s' must start with 'duration='. Got: '%s'\n", filename, start);
        return -1;
    }

    char *endptr = NULL;
    errno = 0;
    long val = strtol(start + 9, &endptr, 10);
    if (errno != 0 || endptr == start + 9 || *endptr != '\0') {
        fprintf(stderr, "Error: invalid duration value in config file '%s'.\n", filename);
        return -1;
    }

    if (val < MIN_DURATION || val > MAX_DURATION) {
        fprintf(stderr, "Error: duration must be between %d and %d seconds. Got: %ld\n",
                MIN_DURATION, MAX_DURATION, val);
        return -1;
    }

    *duration = (int)val;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int duration = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (read_duration(CONFIG_FILE, &duration) != 0) {
        return EXIT_FAILURE;
    }

    printf("Configured watering duration: %d seconds\n", duration);

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, VALVE_GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", VALVE_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "valve-control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", VALVE_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    printf("Valve OFF (initial state)\n");

    if (!program_running) {
        goto cleanup;
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error activating valve: %s\n", strerror(errno));
        goto cleanup;
    }
    printf("Valve ON\n");

    if (!program_running) {
        goto cleanup;
    }

    for (int i = 0; i < duration && program_running; i++) {
        sleep(1);
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error deactivating valve: %s\n", strerror(errno));
        goto cleanup;
    }
    printf("Valve OFF\n");

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

