#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* GPIO pin assignments */
#define LEFT_SENSOR_PIN  4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

#define MOTOR1_PIN 22
#define MOTOR2_PIN 23
#define MOTOR3_PIN 24
#define MOTOR4_PIN 25

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define BASE_SPEED    150
#define LOOP_DELAY_US 10000  /* 10 ms */

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one of the three IR sensors (active-low: 0 = line detected)    */
/* Returns 0 or 1 on success, -1 on error.                             */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n",
                pin, pigpio_error(v));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Drive a motor forward, backward, or stop.                           */
/* ------------------------------------------------------------------ */
static void drive_motor(int pin, int direction, int speed)
{
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;

    switch (direction) {
    case 0:  /* stop */
        gpioPWM(pin, 0);
        break;
    case 1:  /* forward */
        gpioPWM(pin, speed);
        break;
    case -1: /* backward */
        gpioPWM(pin, speed);
        break;
    default:
        fprintf(stderr, "Invalid motor direction %d\n", direction);
        break;
    }
}

/* ------------------------------------------------------------------ */
/* Stop both motors                                                     */
/* ------------------------------------------------------------------ */
static void stop_motors(void)
{
    drive_motor(MOTOR1_PIN,  0, 0);
    drive_motor(MOTOR2_PIN,  0, 0);
    drive_motor(MOTOR3_PIN,  0, 0);
    drive_motor(MOTOR4_PIN,  0, 0);
}

/* ------------------------------------------------------------------ */
/* Log one control cycle to the trace file                              */
/* ------------------------------------------------------------------ */
static void log_cycle(int l, int m, int r, int left_speed, int right_speed)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (fprintf(g_log_file, "%s,%d,%d,%d,%d,%d\n",
                ts, l, m, r, left_speed, right_speed) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup — stop motors, close log, terminate pigpio                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    stop_motors();

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode LEFT_SENSOR_PIN failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode MIDDLE_SENSOR_PIN failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode RIGHT_SENSOR_PIN failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR3_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR4_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode motor pins failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* PWM setup on the two PWM-capable pins */
    if (gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR1_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR2_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("trace_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Cannot open trace_log.txt: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Main control loop ---- */
    while (g_running) {
        int l = read_sensor(LEFT_SENSOR_PIN);
        int m = read_sensor(MIDDLE_SENSOR_PIN);
        int r = read_sensor(RIGHT_SENSOR_PIN);

        if (l < 0 || m < 0 || r < 0) {
            /* Sensor read error — stop and wait */
            stop_motors();
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int left_speed  = 0;
        int right_speed = 0;

        if (m == 0) {
            /* Line under middle — drive straight */
            left_speed  = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (l == 0) {
            /* Line under left — turn right */
            left_speed  = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (r == 0) {
            /* Line under right — turn left */
            left_speed  = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else {
            /* No line detected — stop */
            left_speed  = 0;
            right_speed = 0;
        }

        drive_motor(MOTOR1_PIN,  1, left_speed);
        drive_motor(MOTOR2_PIN,  1, right_speed);
        drive_motor(MOTOR3_PIN, -1, left_speed);
        drive_motor(MOTOR4_PIN, -1, right_speed);

        log_cycle(l, m, r, left_speed, right_speed);

        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    cleanup();
    return EXIT_SUCCESS;
}

