#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0f
#define MEASUREMENT_DELAY_US 180000
#define LOG_FILE "grow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char time_buf[64];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", time_buf, ts.tv_nsec / 1000000, message);
    fclose(fp);
}

static int read_bh1750(int handle, float *lux_out) {
    uint8_t cmd = 0x10; /* Continuous high-resolution mode */
    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        log_event("I2C write error: failed to send measurement command");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_US);
    uint8_t buf[2];
    if (i2cReadDevice(handle, (char *)buf, 2) != 2) {
        log_event("I2C read error: failed to read 2 bytes from BH1750");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        log_event("gpioWrite error: failed to set relay GPIO");
        return;
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "Relay GPIO %d set to %s", gpio, state ? "ON" : "OFF");
    log_event(msg);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X\n", I2C_BUS, BH1750_ADDR);
        log_event("I2C open error: sensor not detected");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        log_event("gpioSetMode error: failed to configure relay GPIO");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    int relay_state = 0;
    log_event("Grow light controller started");

    while (running) {
        float lux;
        if (read_bh1750(i2c_handle, &lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux: %.2f", lux);
            log_event(msg);
            if (lux < LUX_THRESHOLD) {
                if (relay_state == 0) {
                    control_relay(RELAY_GPIO, 1);
                    relay_state = 1;
                }
            } else {
                if (relay_state == 1) {
                    control_relay(RELAY_GPIO, 0);
                    relay_state = 0;
                }
            }
        } else {
            log_event("Sensor read failed; skipping cycle");
        }
        gpioDelay(5000000);
    }

    log_event("Shutting down");
    control_relay(RELAY_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

