#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

#define SERVO_LOCK_PULSE 1000
#define SERVO_UNLOCK_PULSE 2000
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500

#define DEBOUNCE_DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse(int pin, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE) {
        fprintf(stderr, "Error: pulse width %d too low (min %d)\n", pulse_width, SERVO_MIN_PULSE);
        return -1;
    }
    if (pulse_width > SERVO_MAX_PULSE) {
        fprintf(stderr, "Error: pulse width %d too high (max %d)\n", pulse_width, SERVO_MAX_PULSE);
        return -1;
    }
    if (gpioServo(pin, pulse_width) != 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static void lock_door(void) {
    printf("Locking door...\n");
    fflush(stdout);
    if (set_servo_pulse(SERVO_PIN, SERVO_LOCK_PULSE) != 0) {
        fprintf(stderr, "Failed to lock door\n");
    }
}

static void unlock_door(void) {
    printf("Unlocking door...\n");
    fflush(stdout);
    if (set_servo_pulse(SERVO_PIN, SERVO_UNLOCK_PULSE) != 0) {
        fprintf(stderr, "Failed to unlock door\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set servo pin %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set lock button pin %d as input\n", LOCK_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set unlock button pin %d as input\n", UNLOCK_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on lock button pin %d\n", LOCK_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on unlock button pin %d\n", UNLOCK_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        if (!running) break;

        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            lock_door();
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            while (gpioRead(LOCK_BUTTON_PIN) == 0 && running) {
                gpioDelay(10000);
            }
        }

        if (!running) break;

        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            unlock_door();
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            while (gpioRead(UNLOCK_BUTTON_PIN) == 0 && running) {
                gpioDelay(10000);
            }
        }

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    fflush(stdout);

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

