#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define POLL_INTERVAL_MS 10
#define ALARM_DURATION_MS 1000
#define ZMQ_PORT 5555
#define ZMQ_TOPIC "SOUND_ALERTS"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = {
        .tv_sec = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  mode: sound_sensor | alarm_node\n");
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_line = NULL;
    struct gpiod_line *alarm_line = NULL;
    void *zmq_ctx = NULL;
    void *zmq_sock = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (strcmp(mode, "sound_sensor") == 0) {
        chip = gpiod_chip_open_by_name("gpiochip4");
        if (!chip) {
            perror("gpiod_chip_open_by_name(\"gpiochip4\")");
            return EXIT_FAILURE;
        }

        sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
        if (!sound_line) {
            perror("gpiod_chip_get_line(SOUND_SENSOR_PIN)");
            goto cleanup;
        }

        if (gpiod_line_request_input(sound_line, "sound_sensor") < 0) {
            perror("gpiod_line_request_input(SOUND_SENSOR_PIN)");
            goto cleanup;
        }

        zmq_ctx = zmq_ctx_new();
        if (!zmq_ctx) {
            perror("zmq_ctx_new");
            goto cleanup;
        }

        zmq_sock = zmq_socket(zmq_ctx, ZMQ_PUB);
        if (!zmq_sock) {
            perror("zmq_socket(PUB)");
            goto cleanup;
        }

        char addr[32];
        snprintf(addr, sizeof(addr), "tcp://*:%d", ZMQ_PORT);
        if (zmq_bind(zmq_sock, addr, 0) != 0) {
            perror("zmq_bind");
            goto cleanup;
        }

        printf("Sound sensor mode started. Listening on tcp://*:%d\n", ZMQ_PORT);
        printf("Press Ctrl+C to exit.\n");

        while (running) {
            int val = gpiod_line_get_value(sound_line);
            if (val < 0) {
                perror("gpiod_line_get_value(SOUND_SENSOR_PIN)");
                break;
            }

            if (val == 0) {
                time_t now = time(NULL);
                char msg[64];
                strftime(msg, sizeof(msg), "%Y-%m-%d %H:%M:%S", localtime(&now));
                strcat(msg, " Sound detected!");

                char topic[64];
                snprintf(topic, sizeof(topic), "%s", ZMQ_TOPIC);

                if (zmq_send(zmq_sock, msg, strlen(msg), 0) < 0) {
                    perror("zmq_send");
                    break;
                }
                if (zmq_send(zmq_sock, topic, strlen(topic), 0) < 0) {
                    perror("zmq_send(topic)");
                    break;
                }
                printf("Alert sent: %s\n", msg);
            }

            sleep_ms(POLL_INTERVAL_MS);
        }

        ret = EXIT_SUCCESS;

    } else if (strcmp(mode, "alarm_node") == 0) {
        chip = gpiod_chip_open_by_name("gpiochip4");
        if (!chip) {
            perror("gpiod_chip_open_by_name(\"gpiochip4\")");
            return EXIT_FAILURE;
        }

        alarm_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
        if (!alarm_line) {
            perror("gpiod_chip_get_line(ALARM_LED_PIN)");
            goto cleanup;
        }

        if (gpiod_line_request_output(alarm_line, "alarm_node", 0) < 0) {
            perror("gpiod_line_request_output(ALARM_LED_PIN)");
            goto cleanup;
        }

        zmq_ctx = zmq_ctx_new();
        if (!zmq_ctx) {
            perror("zmq_ctx_new");
            goto cleanup;
        }

        zmq_sock = zmq_socket(zmq_ctx, ZMQ_SUB);
        if (!zmq_sock) {
            perror("zmq_socket(SUB)");
            goto cleanup;
        }

        if (zmq_setsockopt(zmq_sock, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC)) != 0) {
            perror("zmq_setsockopt(ZMQ_SUBSCRIBE)");
            goto cleanup;
        }

        char addr[32];
        snprintf(addr, sizeof(addr), "tcp://localhost:%d", ZMQ_PORT);
        if (zmq_connect(zmq_sock, addr) != 0) {
            perror("zmq_connect");
            goto cleanup;
        }

        printf("Alarm node mode started. Listening on tcp://localhost:%d\n", ZMQ_PORT);
        printf("Press Ctrl+C to exit.\n");

        while (running) {
            zmq_msg_t msg;
            if (zmq_msg_init(&msg) != 0) {
                perror("zmq_msg_init");
                break;
            }

            int rc = zmq_msg_recv(&msg, zmq_sock, 0);
            if (rc < 0) {
                if (errno == EINTR) {
                    continue;
                }
                perror("zmq_msg_recv");
                break;
            }

            if (rc > 0) {
                char *data = (char *)zmq_msg_data(&msg);
                if (data && data[0] == 'S' && data[1] == 'o' && data[2] == 'u' &&
                    data[3] == 'n' && data[4] == 'd' && data[5] == ' ') {
                    printf("Sound detected! Activating alarm.\n");
                    if (gpiod_line_set_value(alarm_line, 1) < 0) {
                        perror("gpiod_line_set_value(ALARM_LED_PIN, 1)");
                    }
                    sleep_ms(ALARM_DURATION_MS);
                    if (gpiod_line_set_value(alarm_line, 0) < 0) {
                        perror("gpiod_line_set_value(ALARM_LED_PIN, 0)");
                    }
                }
                zmq_msg_close(&msg);
            }
        }

        ret = EXIT_SUCCESS;

    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return EXIT_FAILURE;
    }

cleanup:
    if (alarm_line) {
        gpiod_line_set_value(alarm_line, 0);
        gpiod_line_release(alarm_line);
    }
    if (sound_line) {
        gpiod_line_release(sound_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (zmq_sock) {
        zmq_close(zmq_sock);
    }
    if (zmq_ctx) {
        zmq_ctx_destroy(zmq_ctx);
    }

    return ret;
}

