#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define IR_GPIO 17
#define PULSE_BUFFER_SIZE 100
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MQTT_CLIENT_ID "ir_decoder"
#define MQTT_KEEPALIVE 60

#define NEC_HDR_MARK  9000
#define NEC_HDR_SPACE 4500
#define NEC_BIT_MARK  560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_RPT_SPACE 2250

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_buffer[PULSE_BUFFER_SIZE];
static volatile int pulse_index = 0;
static MQTTClient mqtt_client;
static MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void ir_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 0) {
        if (pulse_index < PULSE_BUFFER_SIZE) {
            pulse_buffer[pulse_index++] = tick;
        } else {
            syslog(LOG_WARNING, "Pulse buffer overflow, resetting");
            pulse_index = 0;
        }
    }
}

static int decode_nec(uint32_t *pulses, int count, uint32_t *address, uint32_t *command) {
    if (count < 34) {
        syslog(LOG_WARNING, "NEC frame too short: %d pulses", count);
        return -1;
    }
    if (pulses[0] < NEC_HDR_MARK * 0.8 || pulses[0] > NEC_HDR_MARK * 1.2) {
        syslog(LOG_WARNING, "Invalid NEC header mark: %u us", pulses[0]);
        return -1;
    }
    if (pulses[1] < NEC_HDR_SPACE * 0.8 || pulses[1] > NEC_HDR_SPACE * 1.2) {
        syslog(LOG_WARNING, "Invalid NEC header space: %u us", pulses[1]);
        return -1;
    }
    uint32_t addr = 0, cmd = 0;
    for (int i = 0; i < 32; i++) {
        int idx = 2 + i * 2;
        if (idx + 1 >= count) {
            syslog(LOG_WARNING, "NEC bit %d out of bounds", i);
            return -1;
        }
        if (pulses[idx] < NEC_BIT_MARK * 0.8 || pulses[idx] > NEC_BIT_MARK * 1.2) {
            syslog(LOG_WARNING, "Invalid NEC bit mark at %d: %u us", i, pulses[idx]);
            return -1;
        }
        if (pulses[idx + 1] > NEC_ONE_SPACE * 1.2) {
            addr |= (1UL << i);
        }
    }
    if (pulses[64] < NEC_RPT_SPACE * 0.8 || pulses[64] > NEC_RPT_SPACE * 1.2) {
        syslog(LOG_WARNING, "Invalid NEC repeat space: %u us", pulses[64]);
        return -1;
    }
    *address = addr;
    *command = cmd;
    return 0;
}

static void log_nec(uint32_t address, uint32_t command) {
    syslog(LOG_INFO, "NEC: Address=0x%08X, Command=0x%08X", address, command);
}

static void publish_mqtt(uint32_t address, uint32_t command) {
    char payload[256];
    snprintf(payload, sizeof(payload),
             "{\"address\": \"%08X\", \"command\": \"%08X\"}",
             address, command);
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;
    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", MQTTClient_strerror(rc));
    }
}

static int init_mqtt(void) {
    MQTTClient_create(&mqtt_client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = MQTT_KEEPALIVE;
    conn_opts.cleansession = 1;
