#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <math.h>

#define NUM_SENSORS 4
#define I2C_BUS "/dev/i2c-1"
#define BH1750_CMD_OT_HIGH_RES 0x20
#define BH1750_CONV_TIME_MS 180
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SAMPLE_INTERVAL_MS 1000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_open(int addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bh1750_read(int fd, float *lux_out) {
    unsigned char cmd = BH1750_CMD_OT_HIGH_RES;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "write(cmd 0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_TIME_MS * 1000);
    unsigned char buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "read failed: expected 2 bytes, got %zd (%s)\n", n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(int sockfd, const float lux[NUM_SENSORS]) {
    char buf[256];
    int len = snprintf(buf, sizeof(buf), "1,%.1f;2,%.1f;3,%.1f;4,%.1f\n",
                       lux[0], lux[1], lux[2], lux[3]);
    if (len < 0 || (size_t)len >= sizeof(buf)) {
        fprintf(stderr, "snprintf failed\n");
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);
    if (sendto(sockfd, buf, (size_t)len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "socket failed: %s\n", strerror(errno));
        return 1;
    }
    int ttl = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "setsockopt(IP_MULTICAST_TTL) failed: %s\n", strerror(errno));
        close(sockfd);
        return 1;
    }

    int sensor_addrs[NUM_SENSORS] = {0x23, 0x24, 0x25, 0x26};
    int fds[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        fds[i] = -1;
    }

    while (g_running) {
        float lux[NUM_SENSORS];
        int ok = 1;
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (fds[i] >= 0) close(fds[i]);
            fds[i] = -1;
            int fd = i2c_open(sensor_addrs[i]);
            if (fd < 0) {
                lux[i] = NAN;
                ok = 0;
                continue;
            }
            fds[i] = fd;
            if (bh1750_read(fd, &lux[i]) < 0) {
                lux[i] = NAN;
                ok = 0;
            }
            close(fd);
        }

        if (ok) {
            if (send_multicast(sockfd, lux) < 0) {
                fprintf(stderr, "send_multicast failed\n");
            }
        }

        for (int ms = 0; ms < SAMPLE_INTERVAL_MS && g_running; ms += 100) {
            usleep(100 * 1000);
        }
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (fds[i] >= 0) close(fds[i]);
    }
    close(sockfd);
    return 0;
}

