/*
 * Raspberry Pi Zero W - Honeywell AWM7300V Mass Airflow Sensor Logger
 *
 * Wiring:
 *   AWM7300V SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   AWM7300V SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   AWM7300V VDD  -> 3.3 V
 *   AWM7300V GND  -> GND
 *
 * I2C address: 0x28
 *   The AWM7300V returns a 14-bit flow value in the first two bytes of a
 *   zero-length write + 2-byte read.  Flow (SLPM) = (raw - 3277) * 0.1
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow_logger airflow_logger.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x28
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100

/* AWM7300V 14-bit flow resolution: 0.1 SLPM per LSB */
#define FLOW_OFFSET    3277
#define FLOW_SCALE     0.1f

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 2 bytes from the AWM7300V.  Returns 0 on success, -1 on error.  */
/* raw_out receives the 14-bit value (bits 15..2 of the two bytes).    */
static int read_flow_raw(uint16_t *raw_out)
{
    uint8_t buf[2];
    ssize_t n;

    /* Zero-length write: start a read transaction. */
    if (write(g_i2c_fd, buf, 0) < 0) {
        return -1;
    }

    /* Read 2 bytes of flow data. */
    n = read(g_i2c_fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        return -1;
    }

    /* AWM7300V: 14-bit value in the first two bytes, left-justified. */
    *raw_out = ((uint16_t)buf[0] << 8) | buf[1];
    *raw_out &= 0x3FFF;          /* keep only the 14 valid bits */
    return 0;
}

/* ------------------------------------------------------------------ */
static float convert_to_slpm(uint16_t raw)
{
    return ((float)raw - (float)FLOW_OFFSET) * FLOW_SCALE;
}

/* ------------------------------------------------------------------ */
static void log_data(float flow_rate)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(g_log, "%s, %.2f SLPM\n", ts, flow_rate) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log) {
        fflush(g_log);
        fclose(g_log);
        g_log = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    uint16_t raw;
    int rc;

    /* ---- Signal handling ------------------------------------------ */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus --------------------------------------------- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

