#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define AS7341_ADDR 0x39
#define AS7341_ID_REG 0x24
#define AS7341_ID_VAL 0x19
#define AS7341_ENABLE 0x80
#define AS7341_PON 0x01
#define AS7341_SP_EN 0x02
#define AS7341_CFG6 0xAF
#define AS7341_SMUX 0x00
#define AS7341_F1 0x60
#define AS7341_F2 0x61
#define AS7341_F3 0x62
#define AS7341_F4 0x63
#define AS7341_F5 0x64
#define AS7341_F6 0x65
#define AS7341_F7 0x66
#define AS7341_F8 0x67
#define AS7341_CLEAR 0x68
#define AS7341_NIR 0x69
#define LOG_FILE "spectral_log.csv"
#define I2C_DEV "/dev/i2c-1"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int as7341_init(int fd) {
    uint8_t id = 0;
    if (i2c_read_reg8(fd, AS7341_ID_REG, &id) < 0) return -1;
    if (id != AS7341_ID_VAL) {
        fprintf(stderr, "AS7341 ID mismatch: got 0x%02X, expected 0x%02X\n", id, AS7341_ID_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, AS7341_ENABLE, AS7341_PON) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, AS7341_CFG6, AS7341_SMUX) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_ENABLE, AS7341_PON | AS7341_SP_EN) < 0) return -1;
    usleep(10000);
    return 0;
}

static int read_channel(int fd, uint8_t reg, uint16_t *val) {
    uint8_t lo = 0, hi = 0;
    if (i2c_read_reg8(fd, reg, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, reg + 1, &hi) < 0) return -1;
    *val = (uint16_t)((hi << 8) | lo);
    return 0;
}

static float calculate_lux(uint16_t f1, uint16_t f2, uint16_t f3, uint16_t f4,
                           uint16_t f5, uint16_t f6, uint16_t f7, uint16_t f8,
                           uint16_t clear, uint16_t nir) {
    float lux = 0.0f;
    lux += (float)f1 * 0.1f;
    lux += (float)f2 * 0.2f;
    lux += (float)f3 * 0.3f;
    lux += (float)f4 * 0.4f;
    lux += (float)f5 * 0.5f;
    lux += (float)f6 * 0.6f;
    lux += (float)f7 * 0.7f;
    lux += (float)f8 * 0.8f;
    lux += (float)clear * 0.9f;
    lux += (float)nir * 1.0f;
    return lux;
}

static int log_data(FILE *fp, uint16_t f1, uint16_t f2, uint16_t f3, uint16_t f4,
                    uint16_t f5, uint16_t f6, uint16_t f7, uint16_t f8,
                    uint16_t clear, uint16_t nir, float lux) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
                ts, f1, f2, f3, f4, f5, f6, f7, f8, clear, nir, lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", AS7341_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (as7341_init(i2c_fd) < 0) {
        fprintf(stderr, "AS7341 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "fopen %s failed: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }

    while (running) {
        uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;
        int err = 0;

        if (read_channel(i2c_fd, AS7341_F1, &f1) < 0) err = 1;
        if (read_channel(i2c_fd, AS7341_F2, &f2) < 0) err = 1;
        if (read_channel(i2c_fd, AS7341_F3, &f3) < 0) err = 1;
        if (read_channel(i2c_fd, AS7341_F4, &f4) < 0) err = 1;
        if (read_channel(i2c_fd, AS7341_F5, &f5) < 0) err = 1;
        if (read_channel(i2c_fd, AS7341_F6, &f6) < 0) err = 1;
        if (read_channel(i2c_fd, AS7341_F7, &f7) < 0) err = 1;
        if (read_channel(i2c_fd, AS7341_F8, &f8) < 0) err = 1;
        if (read_channel(i2c_fd, AS7341_CLEAR, &clear) < 0) err = 1;
        if (read_channel(i2c_fd, AS7341_NIR, &nir) < 0) err = 1;

        if (err) {
            fprintf(stderr, "Sensor read error; skipping cycle\n");
            sleep(5);
            continue;
        }

        float lux = calculate_lux(f1, f2, f3, f4, f5, f6, f7, f8, clear, nir);

        if (log_data(log_fp, f1, f2, f3, f4, f5, f6, f7, f8, clear, nir, lux) < 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        sleep(5);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

