#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_OUTPUT_FILE "seismic_data.csv"
#define ERROR_LOG_FILE "seismic_error.log"
#define I2C_BUS "/dev/i2c-1"
#define REG_ACCEL_X_L 0x28
#define ACCEL_SCALE 0.000244f
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static int i2c_fd = -1;
static FILE *data_file = NULL;
static FILE *error_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (error_file) {
        fprintf(error_file, "%s: %s (errno=%d: %s)\n", ts, msg, errno, strerror(errno));
        fflush(error_file);
    }
    fprintf(stderr, "%s: %s (errno=%d: %s)\n", ts, msg, errno, strerror(errno));
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_write_byte(fd, REG_ACCEL_X_L) < 0) {
            log_error("I2C write (register select) failed");
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (i2c_read_bytes(fd, buf, 6) < 0) {
            log_error("I2C read (acceleration data) failed");
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
        int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
        int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
        *x = (float)raw_x * ACCEL_SCALE;
        *y = (float)raw_y * ACCEL_SCALE;
        *z = (float)raw_z * ACCEL_SCALE;
        return 0;
    }
    log_error("Failed to read acceleration after retries");
    return -1;
}

static int log_data(FILE *fp, float x, float y, float z) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z) < 0) {
        log_error("Failed to write data to CSV");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (data_file) { fclose(data_file); data_file = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
    if (error_file) { fclose(error_file); error_file = NULL; }
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int interval = DEFAULT_INTERVAL;
    char *output_file = DEFAULT_OUTPUT_FILE;

    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:h")) != -1) {
        switch (opt) {
            case 'a': i2c_address = (int)strtol(optarg, NULL, 0); break;
            case 'i': interval = (int)strtol(optarg, NULL, 0); break;
            case 'f': output_file = optarg; break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval_sec] [-f output_file]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    error_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_file) {
        fprintf(stderr, "Failed to open error log: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        log_error("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    data_file = fopen(output_file, "a");
    if (!data_file) {
        log_error("Failed to open data file");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(data_file, 0, SEEK_END);
    if (ftell(data_file) == 0) {
        fprintf(data_file, "timestamp,x_g,y_g,z_g\n");
        fflush(data_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic data logging started. I2C addr=0x%02X, interval=%ds, output=%s\n",
           i2c_address, interval, output_file);

    while (!terminate) {
        float x, y, z;
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            if (log_data(data_file, x, y, z) != 0) {
                log_error("Data logging failed");
            }
        }
        sleep(interval);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

