#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_POWER_ON 0x01
#define BH1750_CONT_HIGH_RES 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define MULTICAST_TTL 1
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sock_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t *out) {
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed: expected 2 bytes, got %zd (%s)\n", n, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int init_bh1750(int fd) {
    if (i2c_write_cmd(fd, BH1750_POWER_ON) < 0) return -1;
    usleep(10000);
    if (i2c_write_cmd(fd, BH1750_CONT_HIGH_RES) < 0) return -1;
    usleep(180000);
    return 0;
}

static int read_bh1750(int fd, float *lux_out) {
    uint16_t raw;
    if (i2c_read16(fd, &raw) < 0) return -1;
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(float lux) {
    char buffer[64];
    int len = snprintf(buffer, sizeof(buffer), "%.2f", lux);
    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "snprintf failed\n");
        return -1;
    }
    if (sendto(sock_fd, buffer, (size_t)len, 0,
               (struct sockaddr *)&(struct sockaddr_in){0},
               sizeof(struct sockaddr_in)) < 0) {
        fprintf(stderr, "sendto failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_bh1750(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed (sensor absent or bus error)\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    sock_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock_fd < 0) {
        fprintf(stderr, "socket creation failed: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    unsigned char ttl = MULTICAST_TTL;
    if (setsockopt(sock_fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "setsockopt(IP_MULTICAST_TTL) failed: %s\n", strerror(errno));
        close(sock_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float lux;
        if (read_bh1750(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Read failed, retrying in %d s...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }
        if (send_multicast(lux) < 0) {
            fprintf(stderr, "Multicast send failed, retrying in %d s...\n", SAMPLE_INTERVAL_SEC);
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (sock_fd >= 0) close(sock_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    return EXIT_SUCCESS;
}

