/* TLV types */
#define TLV_TYPE_DETECTED_OBJECTS 1

/* Frame header (little-endian) */
typedef struct {
    uint32_t magic_word[2];
    uint32_t version;
    uint32_t total_packet_len;
    uint32_t platform;
    uint32_t frame_number;
    uint32_t time_subframe;
    uint32_t num_detected_obj;
    uint32_t num_tlvs;
    uint32_t subframe_number;
} __attribute__((packed)) frame_header_t;

/* TLV header (little-endian) */
typedef struct {
    uint32_t type;
    uint32_t length;
} __attribute__((packed)) tlv_header_t;

/* Detected object (little-endian) */
typedef struct {
    uint16_t range_idx;
    uint16_t doppler_idx;
    uint16_t peak_val;
    uint16_t x;
    uint16_t y;
    uint16_t z;
} __attribute__((packed)) detected_obj_t;

static volatile sig_atomic_t running = 1;
static int uart_handle = -1;
static FILE *csv_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioTerminate();
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", UART_DEVICE, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_csv(void) {
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Error opening CSV file %s: %s\n", CSV_FILE, strerror(errno));
        return -1;
    }
    /* Write header if file is empty */
    fseek(csv_file, 0, SEEK_END);
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
        fflush(csv_file);
    }
    return 0;
}

/*
 * Synchronize on the 8-byte magic word.
 * Returns 0 on success, -1 on timeout, -2 on buffer overflow.
 */
static int sync_magic(uint8_t *buf, int *buf_len) {
    int i, j;
    for (i = 0; i < BUFFER_SIZE && running; i++) {
        int n = serRead(uart_handle, buf + *buf_len, BUFFER_SIZE - *buf_len);
        if (n < 0) {
            fprintf(stderr, "UART read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            gpioDelay(1000); /* 1 ms */
            continue;
        }
        *buf_len += n;

        /* Search for magic word */
        for (j = 0; j <= *buf_len - 8; j++) {
            if (memcmp(buf + j, MAGIC_WORD, 8) == 0) {
