                memmove(buf, buf + j, *buf_len - j);
                *buf_len -= j;
                return 0;
            }
        }
        /* Discard all but last 7 bytes in case of partial match */
        if (*buf_len > 7) {
            memmove(buf, buf + *buf_len - 7, 7);
            *buf_len = 7;
        }
    }
    return -1; /* timeout */
}

static int read_frame(uint8_t *buf, int *buf_len) {
    frame_header_t hdr;
    int total_len = 0;

    /* Read header (40 bytes) */
    int hdr_bytes = (int)sizeof(hdr);
    while (total_len < hdr_bytes && running) {
        int n = serRead(uart_handle, buf + total_len, hdr_bytes - total_len);
        if (n < 0) {
            fprintf(stderr, "UART read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            gpioDelay(1000);
            continue;
        }
        total_len += n;
    }
    if (total_len < hdr_bytes) {
        fprintf(stderr, "Incomplete frame header\n");
        return -1;
    }
    memcpy(&hdr, buf, sizeof(hdr));

    /* Validate total packet length */
    uint32_t total_packet_len = hdr.total_packet_len;
    if (total_packet_len < sizeof(hdr) || total_packet_len > BUFFER_SIZE) {
        fprintf(stderr, "Invalid total packet length: %u\n", total_packet_len);
        return -1;
    }

    /* Read TLV data */
    int tlv_bytes = (int)(total_packet_len - sizeof(hdr));
    int tlv_read = 0;
    while (tlv_read < tlv_bytes && running) {
        int n = serRead(uart_handle, buf + total_len, tlv_bytes - tlv_read);
        if (n < 0) {
            fprintf(stderr, "UART read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            gpioDelay(1000);
            continue;
        }
        tlv_read += n;
    }
    if (tlv_read < tlv_bytes) {
        fprintf(stderr, "Incomplete TLV data\n");
        return -1;
    }

    /* Process TLVs */
    int offset = 0;
    for (uint32_t i = 0; i < hdr.num_tlvs && offset + (int)sizeof(tlv_header_t) <= tlv_bytes; i++) {
        tlv_header_t tlv_hdr;
