                float range_m = obj[j].range_idx * 0.01f;
                float velocity_mps = obj[j].doppler_idx * 0.01f;
                time_t now = time(NULL);
                fprintf(csv_file, "%ld,%u,%.2f,%.2f\n", (long)now, j, range_m, velocity_mps);
            }
