        cleanup();
        return 1;
    }
    int buf_len = 0;

    while (running) {
        int rc = sync_magic(buf, &buf_len);
        if (rc == -1) {
            /* Timeout: discard buffer and retry */
            buf_len = 0;
            continue;
        }
        if (rc == -2) {
            /* Overflow: discard all but last 7 bytes */
            buf_len = 7;
            continue;
        }

        if (buf_len < (int)sizeof(frame_header_t)) {
            continue;
        }

        frame_header_t hdr;
        memcpy(&hdr, buf, sizeof(hdr));
        if (hdr.total_packet_len < sizeof(hdr) || hdr.total_packet_len > BUFFER_SIZE) {
            fprintf(stderr, "Invalid frame length: %u\n", hdr.total_packet_len);
            buf_len = 0;
            continue;
        }

        if (read_frame(buf, &buf_len) != 0) {
            buf_len = 0;
        }
    }

    free(buf);
    cleanup();
    return 0;
}

