#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define LINE_BUF_SIZE 256
#define READ_TIMEOUT_SEC 2
#define POLL_INTERVAL_SEC 0.5

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag |= CLOCAL | CREAD;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5; /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int parse_line(const char *line, char *timestamp_str, char *range_str) {
    char *saveptr = NULL;
    char *ts_ptr = strtok_r((char *)line, ",", &saveptr);
    if (!ts_ptr) return -1;

    char *range_ptr = strtok_r(NULL, "\n", &saveptr);
    if (!range_ptr) return -1;

    strncpy(timestamp_str, ts_ptr, 20);
    timestamp_str[20] = '\0';
    strncpy(range_str, range_ptr, 10);
    range_str[10] = '\0';
    return 0;
}

static void log_detection(const char *timestamp, const char *range) {
    printf("Timestamp: %s, Range: %s meters\n", timestamp, range);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_uart_fd = init_uart(UART_DEVICE);
    if (g_uart_fd < 0) {
        return 1;
    }

    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    char *timestamp_str = malloc(21);
    char *range_str = malloc(11);
    if (!timestamp_str || !range_str) {
        fprintf(stderr, "malloc failed: %s\n", strerror(errno));
        free(timestamp_str);
        free(range_str);
        close(g_uart_fd);
        return 1;
    }

    while (g_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(g_uart_fd, &readfds);

        struct timeval tv;
        tv.tv_sec = READ_TIMEOUT_SEC;
        tv.tv_usec = 0;

        int sel = select(g_uart_fd + 1, &readfds, NULL, NULL, &tv);
        if (sel < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "select error: %s\n", strerror(errno));
            break;
        }
        if (sel == 0) {
            /* Timeout — no data available this cycle */
            continue;
        }

        char chunk[256];
        ssize_t n = read(g_uart_fd, chunk, sizeof(chunk) - 1);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) continue;
            fprintf(stderr, "read error: %s\n", strerror(errno));
            break;
        }
        if (n == 0) {
            /* Sensor disconnected or no data */
            fprintf(stderr, "UART read returned 0 — sensor absent or bus error\n");
            break;
        }

        chunk[n] = '\0';

        for (ssize_t i = 0; i < n; i++) {
            char c = chunk[i];
            if (c == '\n') {
                line_buf[line_len] = '\0';
                if (line_len > 0) {
                    if (parse_line(line_buf, timestamp_str, range_str) == 0) {
                        log_detection(timestamp_str, range_str);
                    } else {
                        fprintf(stderr, "Invalid line format: %s\n", line_buf);
                    }
                }
                line_len = 0;
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SIZE - 1) {
                    line_buf[line_len++] = c;
                } else {
                    fprintf(stderr, "Line buffer overflow, discarding\n");
                    line_len = 0;
                }
            }
        }
    }

    free(timestamp_str);
    free(range_str);
    if (g_uart_fd >= 0) {
        close(g_uart_fd);
    }
    return 0;
}

