#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN  4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define SERIAL_PORT      "/dev/ttyAMA0"
#define BAUD_RATE        115200
#define SAMPLE_PERIOD_US 100000  /* 100 ms = 10 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_serial_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %d\n", pin, v);
    }
    return v;
}

static void log_sensor_data(int left, int middle, int right)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Left: %d, Middle: %d, Right: %d\n",
           timestamp, left, middle, right);
    fflush(stdout);
}

static int send_emergency_stop(void)
{
    const char *msg = "EMERGENCY STOP!\n";
    size_t len = strlen(msg);

    if (g_serial_fd < 0) {
        fprintf(stderr, "Serial port not open; cannot send emergency stop\n");
        return -1;
    }

    ssize_t written = write(g_serial_fd, msg, len);
    if (written < 0) {
        perror("write (emergency stop)");
        return -1;
    }
    if ((size_t)written != len) {
        fprintf(stderr, "Partial write: %zd of %zu bytes\n", written, len);
        return -1;
    }
    return 0;
}

int main(void)
{
    int left, middle, right;
    int rc = EXIT_SUCCESS;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", LEFT_SENSOR_PIN);
        rc = EXIT_FAILURE;
        goto cleanup_gpio;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", MIDDLE_SENSOR_PIN);
        rc = EXIT_FAILURE;
        goto cleanup_gpio;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", RIGHT_SENSOR_PIN);
        rc = EXIT_FAILURE;
        goto cleanup_gpio;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", LEFT_SENSOR_PIN);
        rc = EXIT_FAILURE;
        goto cleanup_gpio;
    }
    if (gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", MIDDLE_SENSOR_PIN);
        rc = EXIT_FAILURE;
        goto cleanup_gpio;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", RIGHT_SENSOR_PIN);
        rc = EXIT_FAILURE;
        goto cleanup_gpio;
    }

    g_serial_fd = serOpen(SERIAL_PORT, BAUD_RATE, 0);
    if (g_serial_fd < 0) {
        fprintf(stderr, "Failed to open serial port %s: %d\n",
                SERIAL_PORT, g_serial_fd);
        rc = EXIT_FAILURE;
        goto cleanup_gpio;
    }

    printf("KY-033 obstacle detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        left   = read_sensor(LEFT_SENSOR_PIN);
        middle = read_sensor(MIDDLE_SENSOR_PIN);
        right  = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Sensor read error; skipping cycle\n");
        } else {
            log_sensor_data(left, middle, right);

            if (left == 0 && middle == 0 && right == 0) {
                if (send_emergency_stop() != 0) {
                    fprintf(stderr, "Failed to send emergency stop\n");
                }
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");

    if (g_serial_fd >= 0) {
        serClose(g_serial_fd);
        g_serial_fd = -1;
    }

cleanup_gpio:
    gpioTerminate();
    return rc;
}

